// Codex tests cover attempt client cleanup plugin behavior.
import { describe, expect, it, vi } from "vitest";
import {
  closeCodexStartupClientBestEffort,
  interruptCodexTurnAndWaitBestEffort,
  retireUnsafeCodexTurnClientBestEffort,
  retireCodexAppServerClientAfterTimedOutTurn,
  unsubscribeCodexThreadBestEffort,
  terminateCodexBackgroundTerminals,
} from "./attempt-client-cleanup.js";
import { createClientHarness } from "./test-support.js";

describe("Codex app-server attempt client cleanup", () => {
  it.each([true, false])(
    "drains the full terminal inventory and accepts a concurrent exit (%s)",
    async (terminated) => {
      const request = vi
        .fn()
        .mockResolvedValueOnce({
          data: [{ processId: "10" }, { processId: "20" }],
          nextCursor: null,
        })
        .mockResolvedValueOnce({ terminated })
        .mockResolvedValueOnce({ terminated: true })
        .mockResolvedValueOnce({ data: [], nextCursor: null });
      await expect(
        terminateCodexBackgroundTerminals({ request } as never, "thread-1"),
      ).resolves.toBeUndefined();
      expect(request.mock.calls.map(([method, params]) => [method, params])).toEqual([
        ["thread/backgroundTerminals/list", { threadId: "thread-1" }],
        ["thread/backgroundTerminals/terminate", { threadId: "thread-1", processId: "10" }],
        ["thread/backgroundTerminals/terminate", { threadId: "thread-1", processId: "20" }],
        ["thread/backgroundTerminals/list", { threadId: "thread-1", limit: 1 }],
      ]);
    },
  );

  it("reports a terminal that remains running after termination", async () => {
    const request = vi
      .fn()
      .mockResolvedValueOnce({ data: [{ processId: "10" }], nextCursor: null })
      .mockResolvedValueOnce({ terminated: false })
      .mockResolvedValueOnce({ data: [{ processId: "10" }], nextCursor: null });
    await expect(
      terminateCodexBackgroundTerminals({ request } as never, "thread-1"),
    ).rejects.toThrow("Codex background-terminal cleanup failed");
  });

  it("bounds the entire terminal inventory request without closing the shared client", async () => {
    vi.useFakeTimers();
    const harness = createClientHarness();
    const close = vi.spyOn(harness.client, "close");
    try {
      const cleanup = terminateCodexBackgroundTerminals(harness.client, "thread-1");
      const rejected = expect(cleanup).rejects.toThrow("Codex background-terminal cleanup failed");
      await vi.advanceTimersByTimeAsync(5_000);
      await rejected;
      expect(close).not.toHaveBeenCalled();
    } finally {
      harness.client.close();
      vi.useRealTimers();
    }
  });

  it("keeps strict startup retirement failures visible to lifecycle owners", async () => {
    const closeAndWait = vi.fn(async () => {
      throw new Error("strict client retirement failed");
    });

    await expect(closeCodexStartupClientBestEffort({ closeAndWait } as never)).rejects.toThrow(
      "strict client retirement failed",
    );
  });

  it("preserves the primary failure when unsafe turn retirement rejects", async () => {
    const close = vi.fn();
    const closeAndWait = vi.fn(async () => {
      throw new Error("unsafe client retirement failed");
    });

    await expect(
      retireUnsafeCodexTurnClientBestEffort({ close, closeAndWait } as never, "startup interrupt"),
    ).resolves.toBeUndefined();
    expect(close).toHaveBeenCalledOnce();
  });

  it("waits for the matching terminal after an interrupt is acknowledged", async () => {
    const harness = createClientHarness();
    const completion = interruptCodexTurnAndWaitBestEffort(harness.client, {
      threadId: "thread-1",
      turnId: "turn-1",
      timeoutMs: 1_000,
    });
    const settled = vi.fn();
    void completion.then(settled);
    const request = JSON.parse(harness.writes.at(-1) ?? "{}") as {
      id: number;
      method: string;
      params: Record<string, unknown>;
    };

    expect(request).toMatchObject({
      method: "turn/interrupt",
      params: { threadId: "thread-1", turnId: "turn-1" },
    });
    harness.send({ id: request.id, result: {} });
    await Promise.resolve();
    expect(settled).not.toHaveBeenCalled();

    harness.send({
      method: "turn/completed",
      params: {
        threadId: "thread-1",
        turn: { id: "turn-other", status: "interrupted" },
      },
    });
    await Promise.resolve();
    expect(settled).not.toHaveBeenCalled();

    harness.send({
      method: "turn/completed",
      params: {
        threadId: "thread-1",
        turn: { id: "turn-1", status: "interrupted" },
      },
    });

    await expect(completion).resolves.toBe(true);
    harness.client.close();
  });

  it("retains the startup interrupt acknowledgement contract", async () => {
    const request = vi.fn(async () => ({}));

    await expect(
      interruptCodexTurnAndWaitBestEffort({ request } as never, {
        threadId: "thread-1",
        turnId: "",
        timeoutMs: 123,
      }),
    ).resolves.toBe(true);

    expect(request).toHaveBeenCalledWith(
      "turn/interrupt",
      { threadId: "thread-1", turnId: "" },
      { timeoutMs: 123 },
    );
  });

  it("fails closed when acknowledged interruption never reaches its terminal", async () => {
    const harness = createClientHarness();
    const completion = interruptCodexTurnAndWaitBestEffort(harness.client, {
      threadId: "thread-1",
      turnId: "turn-1",
      timeoutMs: 10,
    });
    const request = JSON.parse(harness.writes.at(-1) ?? "{}") as { id: number };
    harness.send({ id: request.id, result: {} });

    await expect(completion).resolves.toBe(false);
    harness.client.close();
  });

  it.each([
    {
      name: "the exact already-terminal error",
      error: { code: -32_600, message: "no active turn to interrupt" },
      completed: true,
    },
    {
      name: "another invalid-request error",
      error: { code: -32_600, message: "expected another active turn" },
      completed: false,
    },
    {
      name: "the terminal message with another error code",
      error: { code: -32_000, message: "no active turn to interrupt" },
      completed: false,
    },
  ])("classifies $name without waiting for a dropped terminal", async ({ error, completed }) => {
    const harness = createClientHarness();
    const completion = interruptCodexTurnAndWaitBestEffort(harness.client, {
      threadId: "thread-1",
      turnId: "turn-1",
      timeoutMs: 1_000,
    });
    const request = JSON.parse(harness.writes.at(-1) ?? "{}") as { id: number };
    harness.send({ id: request.id, error });

    await expect(completion).resolves.toBe(completed);
    harness.client.close();
  });

  it("swallows unsubscribe cleanup failures", async () => {
    const request = vi.fn(async () => {
      throw new Error("already gone");
    });

    await expect(
      unsubscribeCodexThreadBestEffort({ request } as never, {
        threadId: "thread-1",
        timeoutMs: 123,
      }),
    ).resolves.toBe(false);

    expect(request).toHaveBeenCalledWith(
      "thread/unsubscribe",
      { threadId: "thread-1" },
      { timeoutMs: 123 },
    );
  });

  it("closes only the isolated client after timed-out turn cleanup", async () => {
    const notificationHandlers = new Set<(notification: unknown) => void>();
    const request = vi.fn(async (method: string) => {
      if (method === "turn/interrupt") {
        queueMicrotask(() => {
          for (const handler of notificationHandlers) {
            handler({
              method: "turn/completed",
              params: {
                threadId: "thread-1",
                turn: { id: "turn-1", status: "interrupted" },
              },
            });
          }
        });
      }
      return {};
    });
    const close = vi.fn();

    await retireCodexAppServerClientAfterTimedOutTurn(
      {
        request,
        close,
        addNotificationHandler: (handler: (notification: unknown) => void) => {
          notificationHandlers.add(handler);
          return () => notificationHandlers.delete(handler);
        },
        addRequestHandler: () => () => undefined,
        addCloseHandler: () => () => undefined,
      } as never,
      {
        threadId: "thread-1",
        turnId: "turn-1",
        reason: "turn_terminal_idle_timeout",
        suspectPhysicalClient: true,
      },
    );

    expect(request).toHaveBeenCalledWith(
      "turn/interrupt",
      { threadId: "thread-1", turnId: "turn-1" },
      { timeoutMs: 5_000 },
    );
    expect(request).toHaveBeenCalledWith(
      "thread/unsubscribe",
      { threadId: "thread-1" },
      { timeoutMs: 5_000 },
    );
    expect(close).toHaveBeenCalledTimes(1);
  });
});

/**
 * Best-effort cleanup helpers for Codex app-server startup attempts and turns.
 */
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import { unsubscribeCodexAppServerLiveThread } from "./client-runtime.js";
import { CodexAppServerRpcError, type CodexAppServerClient } from "./client.js";
import { retireSharedCodexAppServerClientIfCurrent } from "./shared-client.js";
import { getCodexAppServerTurnRouter } from "./turn-router.js";

/** Timeout for best-effort app-server turn interruption during cleanup. */
export const CODEX_APP_SERVER_INTERRUPT_TIMEOUT_MS = 5_000;
/** Timeout for best-effort thread unsubscribe during cleanup. */
export const CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS = 5_000;
const CODEX_NO_ACTIVE_TURN_ERROR_CODE = -32_600;
const CODEX_NO_ACTIVE_TURN_ERROR_MESSAGE = "no active turn to interrupt";

/** Identifies Codex's exact proof that an interrupt target already finished. */
export function isCodexAlreadyTerminalInterruptError(
  error: unknown,
): error is CodexAppServerRpcError {
  return (
    error instanceof CodexAppServerRpcError &&
    error.code === CODEX_NO_ACTIVE_TURN_ERROR_CODE &&
    error.message === CODEX_NO_ACTIVE_TURN_ERROR_MESSAGE
  );
}

/** Raised when a thread subscription may be live on a client OpenClaw no longer controls. */
export class CodexAppServerUnsafeSubscriptionError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "CodexAppServerUnsafeSubscriptionError";
  }
}

export function isCodexAppServerUnsafeSubscriptionError(
  error: unknown,
): error is CodexAppServerUnsafeSubscriptionError {
  return error instanceof CodexAppServerUnsafeSubscriptionError;
}

/** Asserts Codex resumed the exact thread this attempt subscribed to. */
export function assertCodexThreadResumeSubscription(
  requestedThreadId: string,
  returnedThreadId: string,
): void {
  if (returnedThreadId !== requestedThreadId) {
    throw new CodexAppServerUnsafeSubscriptionError(
      `Codex thread/resume returned ${returnedThreadId} for ${requestedThreadId}`,
    );
  }
}

async function closeClientAndWaitIfAvailable(client: CodexAppServerClient): Promise<void> {
  const closeable = client as {
    close?: CodexAppServerClient["close"];
    closeAndWait?: CodexAppServerClient["closeAndWait"];
  };
  if (typeof closeable.closeAndWait === "function") {
    await closeable.closeAndWait();
    return;
  }
  closeable.close?.();
}

export async function closeCodexStartupClientBestEffort(
  client: CodexAppServerClient | undefined,
): Promise<void> {
  if (!client) {
    return;
  }
  const retiredSharedClient = retireSharedCodexAppServerClientIfCurrent(client);
  // Detached entries retain every ordinary and native lease; only isolated or
  // already-closed shared clients may be joined without aborting sibling turns.
  if (!retiredSharedClient || retiredSharedClient.closed) {
    await closeClientAndWaitIfAvailable(client);
  }
}

/** Retires an unsafe turn client without replacing an already-authoritative failure. */
export async function retireUnsafeCodexTurnClientBestEffort(
  client: CodexAppServerClient,
  operation: string,
): Promise<void> {
  try {
    await closeCodexStartupClientBestEffort(client);
  } catch (error) {
    embeddedAgentLog.debug("codex app-server unsafe turn client retirement failed", {
      operation,
      error,
    });
    try {
      client.close();
    } catch (closeError) {
      embeddedAgentLog.debug("codex app-server unsafe turn client close failed", {
        operation,
        error: closeError,
      });
    }
  }
}

/** Sends a bounded turn interrupt and waits for Codex to confirm terminal abort handling. */
export async function interruptCodexTurnAndWaitBestEffort(
  client: CodexAppServerClient,
  params: {
    threadId: string;
    turnId: string;
    timeoutMs?: number;
  },
): Promise<boolean> {
  const timeoutMs =
    params.timeoutMs && Number.isFinite(params.timeoutMs) && params.timeoutMs > 0
      ? params.timeoutMs
      : CODEX_APP_SERVER_INTERRUPT_TIMEOUT_MS;
  const requestParams = { threadId: params.threadId, turnId: params.turnId };
  let completion: { completion: Promise<boolean>; cancel: () => void } | undefined;
  try {
    // Codex acknowledges interruption before publishing turn/completed. Register
    // first so an immediate exact-turn terminal cannot race past its owner.
    completion = params.turnId
      ? getCodexAppServerTurnRouter(client).watchNativeTurnCompletion({
          threadId: params.threadId,
          turnId: params.turnId,
          timeoutMs,
        })
      : undefined;
    await client.request("turn/interrupt", requestParams, { timeoutMs });
    return completion ? await completion.completion : true;
  } catch (error) {
    if (isCodexAlreadyTerminalInterruptError(error)) {
      return true;
    }
    embeddedAgentLog.debug("codex app-server turn interrupt failed during abort", { error });
    return false;
  } finally {
    completion?.cancel();
  }
}

/** Stops native terminals on the cancelled thread without retiring peer threads. */
export async function terminateCodexBackgroundTerminals(
  client: CodexAppServerClient,
  threadId: string,
): Promise<void> {
  const options = {
    timeoutMs: CODEX_APP_SERVER_INTERRUPT_TIMEOUT_MS,
    signal: AbortSignal.timeout(CODEX_APP_SERVER_INTERRUPT_TIMEOUT_MS),
  };
  try {
    // Codex returns the complete inventory when limit is omitted. Its process
    // IDs are thread-owned handles, not host PIDs or process-group authority.
    const { data } = await client.request("thread/backgroundTerminals/list", { threadId }, options);
    for (const { processId } of data) {
      // False also means it exited between listing and termination. The final
      // inventory distinguishes that benign race from a failed termination.
      await client.request(
        "thread/backgroundTerminals/terminate",
        { threadId, processId },
        options,
      );
    }
    if (data.length > 0) {
      const remaining = await client.request(
        "thread/backgroundTerminals/list",
        { threadId, limit: 1 },
        options,
      );
      if (remaining.data.length > 0) {
        throw new Error("native background terminals remain running");
      }
    }
  } catch (cause) {
    throw new Error(
      "Codex background-terminal cleanup failed; inspect the thread's running terminals before starting more work.",
      { cause },
    );
  }
}

/** Unsubscribes from a thread while swallowing cleanup-only failures. */
export async function unsubscribeCodexThreadBestEffort(
  client: CodexAppServerClient,
  params: {
    threadId: string;
    timeoutMs: number;
    assertCurrent?: () => void;
  },
): Promise<boolean> {
  try {
    await unsubscribeCodexAppServerLiveThread(
      client,
      params.threadId,
      params.timeoutMs,
      params.assertCurrent,
    );
    return true;
  } catch (error) {
    params.assertCurrent?.();
    embeddedAgentLog.debug("codex app-server thread unsubscribe cleanup failed", {
      threadId: params.threadId,
      error,
    });
    return false;
  }
}

/**
 * Retires the shared client after a timed-out turn so later runs do not reuse a
 * potentially wedged app-server connection.
 */
export async function retireCodexAppServerClientAfterTimedOutTurn(
  client: CodexAppServerClient,
  params: {
    threadId: string;
    turnId: string;
    reason: string;
    /**
     * Only the terminal-idle watch proves the physical client is dead (zero
     * notifications for the whole window). Completion/assistant/budget
     * timeouts are per-turn conditions on a possibly healthy shared process —
     * failing co-leases for those would abort innocent sibling turns.
     */
    suspectPhysicalClient: boolean;
  },
): Promise<void> {
  const retiredSharedClient = retireSharedCodexAppServerClientIfCurrent(client, {
    failActiveLeases: params.suspectPhysicalClient,
  });
  const detachedSharedClient = Boolean(retiredSharedClient);
  const clientAlreadyClosed =
    params.suspectPhysicalClient && (retiredSharedClient?.closed ?? false);
  // Best-effort interrupt/unsubscribe only make sense while the transport is
  // still open; a suspect client was just closed (child gets SIGKILLed).
  if (!clientAlreadyClosed) {
    await interruptCodexTurnAndWaitBestEffort(client, {
      threadId: params.threadId,
      turnId: params.turnId,
      timeoutMs: CODEX_APP_SERVER_INTERRUPT_TIMEOUT_MS,
    });
    await unsubscribeCodexThreadBestEffort(client, {
      threadId: params.threadId,
      timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
    });
  }
  let closedClient = retiredSharedClient?.closed ?? false;
  if (!detachedSharedClient) {
    const close = (client as { close?: () => void }).close;
    if (typeof close === "function") {
      try {
        close.call(client);
        closedClient = true;
      } catch (error) {
        embeddedAgentLog.debug("codex app-server client close failed during timeout cleanup", {
          threadId: params.threadId,
          turnId: params.turnId,
          error,
        });
      }
    }
  }
  embeddedAgentLog.warn("codex app-server client retired after timed-out turn", {
    threadId: params.threadId,
    turnId: params.turnId,
    reason: params.reason,
    detachedSharedClient,
    closedClient,
    activeSharedClientLeases: retiredSharedClient?.activeLeases ?? 0,
  });
}

