  "CODEX_APP_SERVER_CONTEXT_RESTART_SELECTION_CHANGED";

/** True when a pre-write context restart must replay on the newly selected owner. */
export function isCodexContextRestartSelectionChangedError(
  error: unknown,
): error is Error & { code: typeof CODEX_APP_SERVER_CONTEXT_RESTART_SELECTION_CHANGED } {
  return (
    error instanceof Error &&
    "code" in error &&
    error.code === CODEX_APP_SERVER_CONTEXT_RESTART_SELECTION_CHANGED
  );
}

type CodexSandboxContext = Awaited<ReturnType<typeof resolveSandboxContext>>;

/** Resources and bindings returned after a Codex attempt thread starts. */
type StartCodexAttemptThreadResult = {
  client: CodexAppServerClient;
  turnRouter: CodexAppServerTurnRouter;
  turnRoute: CodexThreadRouteReservation;
  thread: CodexAppServerThreadLifecycleBinding;
  pluginAppServer: CodexAppServerRuntimeOptions;
  sandboxEnvironment: CodexSandboxExecEnvironment | undefined;
  environmentSelection: CodexTurnEnvironmentParams[] | undefined;
  executionCwd: string;
  sandboxPolicy: CodexSandboxPolicy | undefined;
  runtimeArtifact?: AgentHarnessRuntimeArtifactBinding;
  releaseSharedClientLease: () => void;
  restartContextEngineCodexThread: () => Promise<CodexAppServerThreadLifecycleBinding>;
};

/**
 * Starts or resumes the Codex app-server thread and returns the resources the
 * run loop must later release.
 */
export async function startCodexAttemptThread(params: {
  attemptClientFactory: CodexAppServerClientFactory;
  bindingStore: CodexAppServerBindingStore;
  runtime?: PluginRuntime;
  appServer: CodexAppServerRuntimeOptions;
  pluginConfig: CodexPluginConfig;
  computerUseConfig: ResolvedCodexComputerUseConfig;
  startupAuthProfileId: string | null | undefined;
  startupAuthRequirement?: CodexAppServerClientOptions["authRequirement"];
  startupAuthBindingFingerprint: string | undefined;
  runtimeArtifactRequest?: Readonly<{
    expected?: AgentHarnessRuntimeArtifactBinding;
  }>;
  startupPreparedAuth?: CodexAppServerClientOptions["preparedAuth"];
  startupAuthAccountCacheKey: string | undefined;
  startupEnvApiKeyCacheKey: string | undefined;
  agentDir: string;
  config: EmbeddedRunAttemptParams["config"] | undefined;
  shellEnvironment?: Readonly<Record<string, string>>;
  disableLoginShell?: boolean;
  buildAttemptParams: () => EmbeddedRunAttemptParams;
  runtimeModelId?: string;
  sessionAgentId: string;
  effectiveWorkspace: string;
  effectiveCwd: string;
  dynamicTools: CodexDynamicToolSpec[];
  persistentWebSearchAllowed?: boolean;
  webSearchAllowed: boolean;
  developerInstructions: string | undefined;
  agentWorkspaceDeveloperInstructions?: string;
  finalConfigPatch?: Parameters<typeof startOrResumeThread>[0]["finalConfigPatch"];
  buildFinalConfigPatch?: Parameters<typeof startOrResumeThread>[0]["buildFinalConfigPatch"];
  nativeHookRelayGeneration?: string;
  nativeHookRelayRequired?: boolean;
  bundleMcpThreadConfig: CodexBundleMcpThreadConfig;
  /** OpenClaw owns configured MCP dynamically for this scheduled turn. */
  configuredMcpOwnershipVersion?: 1;
  nativeToolSurfaceEnabled: boolean;
  nativeProviderWebSearchSupport: CodexNativeWebSearchSupport;
  sandboxExecServerEnabled: boolean;
  sandbox: CodexSandboxContext;
  contextEngineProjection: CodexContextEngineThreadBootstrapProjection | undefined;
  startupTimeoutMs: number;
  signal: AbortSignal;
  onStartupTimeout: () => void | Promise<void>;
  onExecutionDisconnect?: (error: Error) => void;
  spawnedBy: EmbeddedRunAttemptParams["spawnedBy"];
}): Promise<StartCodexAttemptThreadResult> {
  let pluginAppServer = params.appServer;
  const startupRuntimeAuthProfileId =
    params.startupPreparedAuth?.kind === "profile"
      ? params.startupPreparedAuth.profileId
      : (params.startupAuthProfileId ?? undefined);
  const startupRuntimeAuthProfileStore =
    params.startupPreparedAuth?.kind === "profile" ? params.startupPreparedAuth.store : undefined;
  let releaseSharedClientLease: (() => void) | undefined;
  let startupClientForAbandonedRequestCleanup: CodexAppServerClient | undefined;
  let releaseStartupResourcesOnTimeout: (() => Promise<void>) | undefined;
  let startupAbandoned = false;
  const startupAbandonController = new AbortController();
  const abandonStartupAcquire = () => startupAbandonController.abort();
  params.signal.addEventListener("abort", abandonStartupAcquire, { once: true });
  try {
    const startupResult = await withCodexStartupTimeout({
      timeoutMs: params.startupTimeoutMs,
      signal: params.signal,
      onTimeout: async () => {
        startupAbandoned = true;
        startupAbandonController.abort();
        await params.onStartupTimeout();
        await releaseStartupResourcesOnTimeout?.();
        releaseSharedClientLease?.();
        releaseSharedClientLease = undefined;
        await closeCodexStartupClientBestEffort(startupClientForAbandonedRequestCleanup);
        startupClientForAbandonedRequestCleanup = undefined;
      },
      operation: async () => {
        const threadConfig = mergeCodexThreadConfigs(
          params.configuredMcpOwnershipVersion === 1
            ? undefined
            : (params.bundleMcpThreadConfig?.configPatch as JsonObject | undefined),
        );
        const pluginStartupPolicy = resolveCodexPluginThreadConfigStartupPolicy({
          pluginConfig: params.pluginConfig,
          nativeToolSurfaceEnabled: params.nativeToolSurfaceEnabled,
          scheduledRuntimeAuthority: params.buildAttemptParams().scheduledRuntimeAuthority,
        });
        const {
          pluginThreadConfigRequired,
          pluginThreadConfigPluginConfig,
          resolvedPluginPolicy,
          enabledPluginConfigKeys,
        } = pluginStartupPolicy;
        const computerUseMcpElicitationDelegationRequired = params.computerUseConfig.enabled;
        const mcpElicitationDelegationRequired =
          resolvedPluginPolicy?.enabled === true || computerUseMcpElicitationDelegationRequired;
        pluginAppServer = mcpElicitationDelegationRequired
          ? {
              ...params.appServer,
              approvalPolicy: withMcpElicitationsApprovalPolicy(params.appServer.approvalPolicy),
            }
          : params.appServer;

        let attemptedClient: CodexAppServerClient | undefined;
        const startupAttempt = async () => {
          let startupClientLease: (() => void) | undefined;
          let startupClient: CodexAppServerClient | undefined;
          let startupAttemptError: unknown;
          let startupAttemptSucceeded = false;
          try {
            const attemptParams = params.buildAttemptParams();
            startupClient = await params.attemptClientFactory({
              startOptions: params.appServer.start,
              pluginConfig: params.pluginConfig,
              ...(params.startupPreparedAuth
                ? { preparedAuth: params.startupPreparedAuth }
                : { authProfileId: params.startupAuthProfileId }),
              authRequirement: params.startupAuthRequirement,
              authProfileStore: attemptParams.authProfileStore,
              authBindingFingerprint: params.startupAuthBindingFingerprint,
              ...(params.runtimeArtifactRequest
                ? {
                    runtimeArtifactMode: "capture" as const,
                    ...(params.runtimeArtifactRequest.expected
                      ? { expectedRuntimeArtifact: params.runtimeArtifactRequest.expected }
                      : {}),
                  }
                : {}),
              agentId: params.sessionAgentId,
              agentDir: params.agentDir,
              config: params.config,
              onStartedClient: (client) => {
                // Timeout cleanup may fire before the client factory resolves;
                // close any late-arriving client instead of leaking a lease.
                startupClientForAbandonedRequestCleanup = client;
                if (startupAbandoned || startupAbandonController.signal.aborted) {
                  void closeCodexStartupClientBestEffort(client);
                }
              },
              abandonSignal: startupAbandonController.signal,
              timeoutMs: params.appServer.requestTimeoutMs,
            });
            const activeStartupClient = startupClient;
            let startupClientLeaseReleased = false;
            startupClientLease = () => {
              if (startupClientLeaseReleased) {
                return;
              }
              startupClientLeaseReleased = true;
              if (params.attemptClientFactory === createIsolatedCodexAppServerClient) {
                activeStartupClient.close();
              } else {
                releaseLeasedSharedCodexAppServerClient(activeStartupClient);
              }
            };
            releaseSharedClientLease = startupClientLease;
            attemptedClient = activeStartupClient;
            startupClientForAbandonedRequestCleanup = activeStartupClient;
            if (startupAbandoned) {
              throw new CodexAppServerStartupError("timed_out");
            }
            if (startupAbandonController.signal.aborted) {
              throw new CodexAppServerStartupError("aborted");
            }
            const runtimeArtifact = await verifyStartupArtifact({
              client: activeStartupClient,
              request: params.runtimeArtifactRequest,
              signal: startupAbandonController.signal,
            });
            ensureCodexAppServerClientRuntime(activeStartupClient, {
              agentDir: params.agentDir,
              authProfileId: startupRuntimeAuthProfileId,
              authMode:
                params.startupPreparedAuth?.kind === "api-key" ? "prepared-api-key" : "profile",
              authProfileStore: startupRuntimeAuthProfileStore ?? attemptParams.authProfileStore,
              config: params.config,
            });
            const turnRouter = getCodexAppServerTurnRouter(activeStartupClient);
            try {
              await ensureCodexComputerUse({
                client: activeStartupClient,
                pluginConfig: params.pluginConfig,
                config: params.config,
                agentDir: params.agentDir,
                timeoutMs: params.appServer.requestTimeoutMs,
                signal: startupAbandonController.signal,
              });
            } catch (error) {
              if (
                startupAbandonController.signal.aborted ||
                isCodexAppServerStartSelectionChangedError(error)
              ) {
                throw error;
              }
              throw new AgentHarnessPreflightError(
                `Codex Computer Use readiness failed: ${formatErrorMessage(error)}`,
                { cause: error, scope: "harness" },
              );
            }
            const startupRuntimeIdentity = activeStartupClient.getRuntimeIdentity();
            const pluginAppCacheKey = buildCodexPluginAppCacheKey({
              appServer: params.appServer,
              agentDir: params.agentDir,
              authProfileId: startupRuntimeAuthProfileId,
              accountId: params.startupAuthAccountCacheKey,
              envApiKeyFingerprint: params.startupEnvApiKeyCacheKey,
              appServerVersion: activeStartupClient.getServerVersion(),
              runtimeIdentity: startupRuntimeIdentity,
              desktopGenerationFingerprint:
                readCodexAppServerClientDesktopGenerationFingerprint(activeStartupClient),
            });
            const appServerRuntimeFingerprint = buildCodexAppServerRuntimeFingerprint({
              appServer: params.appServer,
              appServerVersion: activeStartupClient.getServerVersion(),
              runtimeIdentity: startupRuntimeIdentity,
            });
            const basePluginThreadConfigInputFingerprint = pluginThreadConfigRequired
              ? buildCodexPluginThreadConfigInputFingerprint({
                  pluginConfig: pluginThreadConfigPluginConfig,
                  appCacheKey: pluginAppCacheKey,
                })
              : undefined;
            const pluginThreadConfigInputFingerprint = basePluginThreadConfigInputFingerprint
              ? buildScheduledCodexAppAuthorityInputFingerprint(
                  basePluginThreadConfigInputFingerprint,
                  attemptParams.scheduledRuntimeAuthority,
                )
              : undefined;
            embeddedAgentLog.debug(
              "codex plugin thread config eligibility",
              buildCodexPluginThreadConfigEligibilityLogData({
                sessionId: attemptParams.sessionId,
                sessionKey: attemptParams.sessionKey ?? "",
                pluginThreadConfigRequired,
                resolvedPluginPolicy,
                enabledPluginConfigKeys,
                pluginAppCacheKey,
                startupAuthProfileId: startupRuntimeAuthProfileId,
                appServer: params.appServer,
              }),
            );
            let startupSandboxEnvironment: CodexSandboxExecEnvironment | undefined;
            let startupSandboxEnvironmentAcquired = false;
            const releaseStartupSandboxEnvironment = async () => {
              if (startupSandboxEnvironmentAcquired) {
                startupSandboxEnvironmentAcquired = false;
                await releaseCodexSandboxExecServerEnvironment(
                  params.sandbox,
                  startupSandboxEnvironment,
                );
              }
            };
            releaseStartupResourcesOnTimeout = releaseStartupSandboxEnvironment;
            try {
              const sandboxEnvironmentRequired = shouldRequireCodexSandboxExecServerEnvironment({
                sandbox: params.sandbox,
                nativeToolSurfaceEnabled: params.nativeToolSurfaceEnabled,
                sandboxExecServerEnabled: params.sandboxExecServerEnabled,
              });
              startupSandboxEnvironment = sandboxEnvironmentRequired
                ? await ensureCodexSandboxExecServerEnvironment({
                    client: activeStartupClient,
                    sandbox: params.sandbox ?? null,
                    runtime: params.runtime,
                    appServerStartOptions: params.appServer.start,
                    timeoutMs: params.appServer.requestTimeoutMs,
                    signal: AbortSignal.any([params.signal, startupAbandonController.signal]),
                    onExecutionDisconnect: params.onExecutionDisconnect,
                  })
                : undefined;
              startupSandboxEnvironmentAcquired = Boolean(startupSandboxEnvironment);
              if (startupAbandonController.signal.aborted) {
                await releaseStartupSandboxEnvironment();
                throw new CodexAppServerStartupError("aborted");
              }
              if (sandboxEnvironmentRequired && !startupSandboxEnvironment) {
                throw new Error(
                  "Codex app-server did not register an OpenClaw sandbox exec-server environment.",
                );
              }
            } catch (error) {
              await releaseStartupSandboxEnvironment();
              throw error;
            }
            const startupEnvironmentSelection = resolveCodexSandboxEnvironmentSelection(
              startupSandboxEnvironment,
              params.nativeToolSurfaceEnabled,
            );
            const startupExecutionCwd = resolveCodexAppServerExecutionCwd({
              effectiveCwd: params.effectiveCwd,
              localWorkspaceRoot: params.effectiveWorkspace,
              environment: startupSandboxEnvironment,
              nativeToolSurfaceEnabled: params.nativeToolSurfaceEnabled,
              remoteWorkspaceRoot: params.appServer.remoteWorkspaceRoot,
            });
            const startupSandboxPolicy = startupSandboxEnvironment
              ? resolveCodexExternalSandboxPolicyForOpenClawSandbox(params.sandbox)
              : undefined;
            let startupReservation: CodexThreadRouteReservation | undefined;
            const releaseStartupReservation = () => {
              startupReservation?.release();
              startupReservation = undefined;
            };
            const reserveStartupThread = (threadId: string) => {
              if (startupReservation) {
                if (startupReservation.threadId !== threadId) {
                  throw new Error(
                    `codex app-server reserved ${startupReservation.threadId} but started ${threadId}`,
                  );
                }
                return { release: releaseStartupReservation };
              }
              startupReservation = turnRouter.reserveThread({
                threadId,
              });
              return { release: releaseStartupReservation };
            };
            const releaseStartupResources = async () => {
              releaseStartupReservation();
              await releaseStartupSandboxEnvironment();
            };
            releaseStartupResourcesOnTimeout = releaseStartupResources;
            const buildThreadLifecycleParams = (
              signal: AbortSignal,
              reserveResumeThread?: typeof reserveStartupThread,
            ) =>
              ({
                client: activeStartupClient,
                reserveResumeThread,
                bindingStore: params.bindingStore,
                params: params.buildAttemptParams(),
                runtimeModelId: params.runtimeModelId,
                agentId: params.sessionAgentId,
                agentDir: params.agentDir,
                cwd: startupExecutionCwd,
                dynamicTools: params.dynamicTools,
                persistentWebSearchAllowed: params.persistentWebSearchAllowed,
                webSearchAllowed: params.webSearchAllowed,
                appServer: pluginAppServer,
                developerInstructions: params.developerInstructions,
                agentWorkspaceDeveloperInstructions: params.agentWorkspaceDeveloperInstructions,
                config: threadConfig,
                shellEnvironment: params.shellEnvironment,
                disableLoginShell: params.disableLoginShell,
                finalConfigPatch: params.finalConfigPatch,
                buildFinalConfigPatch: params.buildFinalConfigPatch,
                nativeHookRelayGeneration: params.nativeHookRelayGeneration,
                nativeHookRelayRequired: params.nativeHookRelayRequired,
                nativeCodeModeEnabled: params.nativeToolSurfaceEnabled,
                nativeProviderWebSearchSupport: params.nativeProviderWebSearchSupport,
                nativeCodeModeOnlyEnabled: params.appServer.codeModeOnly,
                userMcpServersEnabled:
                  params.configuredMcpOwnershipVersion === 1
                    ? false
                    : params.nativeToolSurfaceEnabled,
                mcpServersFingerprint:
                  params.configuredMcpOwnershipVersion === 1
                    ? undefined
                    : params.bundleMcpThreadConfig.fingerprint,
                mcpServersFingerprintEvaluated:
                  params.configuredMcpOwnershipVersion === 1 ||
                  params.bundleMcpThreadConfig.evaluated,
                configuredMcpOwnershipVersion: params.configuredMcpOwnershipVersion,
                environmentSelection: startupEnvironmentSelection,
                appServerRuntimeFingerprint,
                contextEngineProjection: params.contextEngineProjection,
                signal,
                pluginThreadConfig: pluginThreadConfigRequired
                  ? createCodexPluginThreadConfigStartupProvider({
                      inputFingerprint: pluginThreadConfigInputFingerprint,
                      enabledPluginConfigKeys,
                      policy: resolvedPluginPolicy,
                      requestTimeoutMs: params.appServer.requestTimeoutMs,
                      signal,
                      pluginConfig: pluginThreadConfigPluginConfig,
                      client: activeStartupClient,
                      configCwd: startupExecutionCwd,
                      appCacheKey: pluginAppCacheKey,
                      scheduledRuntimeAuthority: attemptParams.scheduledRuntimeAuthority,
                    })
                  : undefined,
              }) satisfies Parameters<typeof startOrResumeThread>[0];
            try {
              const startupThread = await startOrResumeThread(
                buildThreadLifecycleParams(startupAbandonController.signal, reserveStartupThread),
              );
              try {
                // Fresh starts reach here unreserved; resumes reserved before
                // thread/resume so their early notifications are already buffered.
                reserveStartupThread(startupThread.threadId);
              } catch (error) {
                const unsubscribed = await unsubscribeCodexThreadBestEffort(activeStartupClient, {
                  threadId: startupThread.threadId,
                  timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
                });
                if (!unsubscribed) {
                  throw new CodexAppServerUnsafeSubscriptionError(
                    "Codex startup subscription cleanup failed",
                    { cause: error },
                  );
                }
                throw error;
              }
              if (startupAbandonController.signal.aborted) {
                throw new CodexAppServerStartupError("aborted");
              }
              const startupRoute = startupReservation;
              if (!startupRoute) {
                throw new Error("codex app-server startup did not reserve its thread route");
              }
              startupSandboxEnvironmentAcquired = false;
              startCodexComputerUseHealthMonitor({
                client: activeStartupClient,
                config: params.computerUseConfig,
              });
              startupAttemptSucceeded = true;
              return {
                client: activeStartupClient,
                turnRouter,
                turnRoute: startupRoute,
                thread: startupThread,
                sandboxEnvironment: startupSandboxEnvironment,
                environmentSelection: startupEnvironmentSelection,
                executionCwd: startupExecutionCwd,
                sandboxPolicy: startupSandboxPolicy,
                ...(runtimeArtifact ? { runtimeArtifact } : {}),
                restartContextEngineCodexThread: async () => {
                  try {
                    return await startOrResumeThread(buildThreadLifecycleParams(params.signal));
                  } catch (error) {
                    if (!isCodexAppServerStartSelectionChangedError(error)) {
                      throw error;
                    }
                    // The run loop cannot safely swap the physical client, router,
                    // and lease halfway through an overflow retry. Retire this
                    // generation so the next bounded attempt acquires the owner
                    // selected by the now-current native config.
                    retireSharedCodexAppServerClientIfCurrent(activeStartupClient);
                    throw Object.assign(
                      new Error("codex app-server client is closed", { cause: error }),
                      { code: CODEX_APP_SERVER_CONTEXT_RESTART_SELECTION_CHANGED },
                    );
                  }
                },
              };
            } catch (error) {
              await releaseStartupResources();
              throw error;
            } finally {
              if (releaseStartupResourcesOnTimeout === releaseStartupResources) {
                releaseStartupResourcesOnTimeout = undefined;
              }
            }
          } catch (error) {
            startupAttemptError = error;
            if (!startupAbandoned && !params.signal.aborted && !startupClient) {
              const sharedClient = clearSharedCodexAppServerClientIfCurrentAndUnclaimed(
                startupClientForAbandonedRequestCleanup,
              );
              if (sharedClient.found && !sharedClient.closed) {
                // Shared acquisition already released this caller. A peer still
                // owns the client, so outer cleanup must not retire it.
                startupClientForAbandonedRequestCleanup = undefined;
              }
            }
            throw error;
          } finally {
            if (!startupAttemptSucceeded) {
              if (releaseSharedClientLease === startupClientLease) {
                releaseSharedClientLease = undefined;
              }
              startupClientLease?.();
              if (startupAbandoned || params.signal.aborted) {
                if (startupClientForAbandonedRequestCleanup === startupClient) {
                  startupClientForAbandonedRequestCleanup = undefined;
                }
                await closeCodexStartupClientBestEffort(startupClient);
              } else if (
                !isCodexAppServerStartSelectionChangedError(startupAttemptError) &&
                (shouldClearSharedClientAfterStartupRace(startupAttemptError) ||
                  shouldClearSharedClientAfterStartupFailure({
                    error: startupAttemptError,
                    spawnedBy: params.spawnedBy,
                  }))
              ) {
                if (startupClientForAbandonedRequestCleanup === startupClient) {
                  startupClientForAbandonedRequestCleanup = undefined;
                }
                await closeCodexStartupClientBestEffort(startupClient);
              }
            }
          }
        };

        for (let attempt = 1; attempt <= CODEX_APP_SERVER_STARTUP_MAX_ATTEMPTS; attempt += 1) {
          try {
            return await startupAttempt();
          } catch (error) {
            const selectionChanged = isCodexAppServerStartSelectionChangedError(error);
            if (
              startupAbandoned ||
              params.signal.aborted ||
              (!selectionChanged && !isCodexAppServerConnectionClosedError(error))
            ) {
              throw error;
            }
            const refreshedSharedClient = selectionChanged
              ? retireSharedCodexAppServerClientIfCurrent(attemptedClient)
              : clearSharedCodexAppServerClientIfCurrent(attemptedClient);
            if (startupClientForAbandonedRequestCleanup === attemptedClient) {
              startupClientForAbandonedRequestCleanup = undefined;
            }
            if (attempt >= CODEX_APP_SERVER_STARTUP_MAX_ATTEMPTS) {
              embeddedAgentLog.warn(
                selectionChanged
                  ? "codex app-server executable selection kept changing during startup; retries exhausted"
                  : "codex app-server connection closed during startup; retries exhausted",
                {
                  attempt,
                  maxAttempts: CODEX_APP_SERVER_STARTUP_MAX_ATTEMPTS,
                  refreshedSharedClient,
                  error: formatErrorMessage(error),
                },
              );
              throw error;
            }
            const retryDelayMs = selectionChanged ? 0 : 1_000 * 2 ** (attempt - 1);
            embeddedAgentLog.warn(
              selectionChanged
                ? "codex app-server executable selection changed during startup; restarting app-server and retrying"
                : "codex app-server connection closed during startup; restarting app-server and retrying",
              {
                attempt,
                nextAttempt: attempt + 1,
                maxAttempts: CODEX_APP_SERVER_STARTUP_MAX_ATTEMPTS,
                refreshedSharedClient,
                error: formatErrorMessage(error),
              },
            );
            // Codex exits after its five-second SQLite busy timeout; a bounded,
            // abortable backoff avoids immediately racing the same transient lock.
            await sleepWithAbort(retryDelayMs, startupAbandonController.signal);
          }
        }
        throw new Error("codex app-server startup retry loop exited unexpectedly");
      },
    });
    startupClientForAbandonedRequestCleanup = undefined;
    if (!releaseSharedClientLease) {
      throw new Error("codex app-server startup succeeded without a shared client lease");
    }
    return {
      ...startupResult,
      pluginAppServer,
      releaseSharedClientLease,
    };
  } catch (error) {
    if (params.signal.aborted || isCodexAppServerStartupError(error)) {
      releaseSharedClientLease?.();
      releaseSharedClientLease = undefined;
      await closeCodexStartupClientBestEffort(startupClientForAbandonedRequestCleanup);
      startupClientForAbandonedRequestCleanup = undefined;
    } else if (
      !isCodexAppServerStartSelectionChangedError(error) &&
      (shouldClearSharedClientAfterStartupRace(error) ||
        shouldClearSharedClientAfterStartupFailure({
          error,
          spawnedBy: params.spawnedBy,
        }))
    ) {
      releaseSharedClientLease?.();
      releaseSharedClientLease = undefined;
      await closeCodexStartupClientBestEffort(startupClientForAbandonedRequestCleanup);
      startupClientForAbandonedRequestCleanup = undefined;
    }
    throw error;
  } finally {
    params.signal.removeEventListener("abort", abandonStartupAcquire);
  }
}

function shouldClearSharedClientAfterStartupRace(error: unknown): boolean {
  return isCodexAppServerStartupError(error) || isCodexAppServerRequestTimeoutError(error);
}

function shouldClearSharedClientAfterStartupFailure(params: {
  error: unknown;
  spawnedBy: EmbeddedRunAttemptParams["spawnedBy"];
}): boolean {
  if (isCodexAppServerOverloadError(params.error)) {
    return false;
  }
  return isCodexAppServerBrokenPipeError(params.error) || !params.spawnedBy;
}

// Codex tests cover attempt steering plugin behavior.
import { createDeferred } from "openclaw/plugin-sdk/extension-shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  CodexSteeringAcceptedUnconfirmedError,
  createCodexSteeringQueue,
} from "./attempt-steering.js";
import { createClientHarness } from "./test-support.js";
import { buildCodexUserInput } from "./user-input.js";

type QueueParams = Parameters<typeof createCodexSteeringQueue>[0];

const prepareMessage: QueueParams["prepareMessage"] = async (text, options) =>
  buildCodexUserInput(text, options.images);

const PNG_1X1 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9Z0V8AAAAASUVORK5CYII=";

describe("Codex app-server steering queue", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  function createQueue(
    client: QueueParams["client"] | { request: ReturnType<typeof vi.fn> },
    options: Partial<Pick<QueueParams, "signal" | "requestTimeoutMs" | "prepareMessage">> = {},
  ) {
    return createCodexSteeringQueue({
      client: client as QueueParams["client"],
      threadId: "thread-1",
      turnId: "turn-1",
      requestTimeoutMs: 60_000,
      signal: new AbortController().signal,
      assertActive: () => {},
      prepareMessage,
      ...options,
    });
  }

  const steerRequestOptions = { timeoutMs: 60_000, signal: expect.any(AbortSignal) };

  it("resolves only after the matching Codex user message completes", async () => {
    const request = vi.fn(async (_method: string, _params: unknown) => ({ turnId: "turn-1" }));
    const queue = createQueue({ request });
    const onQueueAccepted = vi.fn();

    const queued = queue.queue("accepted", { debounceMs: 0, onQueueAccepted });
    let settled = false;
    void queued.finally(() => {
      settled = true;
    });
    await vi.advanceTimersByTimeAsync(0);

    const requestParams = request.mock.calls[0]?.[1] as { clientUserMessageId?: string };
    expect(requestParams.clientUserMessageId).toBe("openclaw:turn-1:steer:1");
    expect(onQueueAccepted).toHaveBeenCalledWith(true);
    expect(settled).toBe(false);
    expect(queue.confirmConsumed("unrelated-user-message")).toBe(false);
    expect(queue.confirmConsumed(requestParams.clientUserMessageId ?? "")).toBe(true);
    await queued;
    expect(request).toHaveBeenCalledWith(
      "turn/steer",
      {
        threadId: "thread-1",
        expectedTurnId: "turn-1",
        input: [{ type: "text", text: "accepted", text_elements: [] }],
        clientUserMessageId: "openclaw:turn-1:steer:1",
      },
      steerRequestOptions,
    );
  });

  it("fails the steer when the app-server never answers turn/steer", async () => {
    // Real client over an in-memory transport: only the app-server process is faked,
    // so this exercises the production request deadline rather than a stub.
    const harness = createClientHarness();
    const queue = createQueue(harness.client, { requestTimeoutMs: 1_000 });

    const outcomes: unknown[] = [];
    void queue.queue("steer me", { debounceMs: 0 }).then(
      () => outcomes.push("resolved"),
      (error: unknown) => outcomes.push(error),
    );
    await vi.advanceTimersByTimeAsync(0);
    expect((JSON.parse(harness.writes[0] ?? "{}") as { method?: string }).method).toBe(
      "turn/steer",
    );

    // Codex accepted the frame but never responds: the caller must not wait forever.
    await vi.advanceTimersByTimeAsync(5_000);

    expect(outcomes[0]).toBeInstanceOf(CodexSteeringAcceptedUnconfirmedError);
    expect((outcomes[0] as Error & { cause?: unknown }).cause).toMatchObject({
      message: "turn/steer timed out",
    });
    harness.client.close();
  });

  it("aborts the in-flight steer request and removes its client pending entry", async () => {
    const harness = createClientHarness();
    const controller = new AbortController();
    const queue = createQueue(harness.client, { signal: controller.signal });
    const pendingRequests = (
      harness.client as unknown as { pending: Map<number | string, unknown> }
    ).pending;

    const queued = queue.queue("steer me", { debounceMs: 0 });
    const rejected = expect(queued).rejects.toBeInstanceOf(CodexSteeringAcceptedUnconfirmedError);
    await vi.advanceTimersByTimeAsync(0);
    expect(pendingRequests.size).toBe(1);

    controller.abort();

    await rejected;
    expect(pendingRequests.size).toBe(0);
    harness.client.close();
  });

  it("handles user-message completion before the steer response", async () => {
    let acceptSteer: (() => void) | undefined;
    const steerAccepted = new Promise<void>((resolve) => {
      acceptSteer = resolve;
    });
    const request = vi.fn(async () => {
      await steerAccepted;
      return { turnId: "turn-1" };
    });
    const queue = createQueue({ request });
    const onQueueAccepted = vi.fn();

    const queued = queue.queue("consumed first", { debounceMs: 0, onQueueAccepted });
    await vi.advanceTimersByTimeAsync(0);
    expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(true);
    expect(onQueueAccepted).toHaveBeenCalledWith(true);
    await queued;

    acceptSteer?.();
    await vi.advanceTimersByTimeAsync(0);
  });

  it("batches ordered text and images under one correlated user-message id", async () => {
    const request = vi.fn(async () => ({ turnId: "turn-1" }));
    const queue = createQueue({ request });

    const first = queue.queue("first", {
      debounceMs: 5,
      images: [{ type: "image", data: PNG_1X1, mimeType: "image/png" }],
    });
    const second = queue.queue("second", {
      debounceMs: 5,
      images: [{ type: "image", data: PNG_1X1, mimeType: "image/png" }],
    });
    await vi.advanceTimersByTimeAsync(5);

    expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(true);
    await Promise.all([first, second]);
    expect(request).toHaveBeenCalledWith(
      "turn/steer",
      {
        threadId: "thread-1",
        expectedTurnId: "turn-1",
        input: [
          { type: "text", text: "first", text_elements: [] },
          { type: "image", url: `data:image/png;base64,${PNG_1X1}` },
          { type: "text", text: "second", text_elements: [] },
          { type: "image", url: `data:image/png;base64,${PNG_1X1}` },
        ],
        clientUserMessageId: "openclaw:turn-1:steer:1",
      },
      steerRequestOptions,
    );
  });

  it("rejects the batch when Codex rejects turn/steer", async () => {
    const request = vi.fn(async () => {
      throw new Error("cannot steer this turn");
    });
    const queue = createQueue({ request });
    const onQueueAccepted = vi.fn();

    const queued = queue.queue("rejected", { debounceMs: 0, onQueueAccepted });
    const rejected = expect(queued).rejects.toThrow("cannot steer this turn");
    await vi.advanceTimersByTimeAsync(0);
    await rejected;
    expect(onQueueAccepted).toHaveBeenCalledWith(false);
  });

  it("rejects later steering behind a failed batch", async () => {
    let rejectFirstSteer: ((error: Error) => void) | undefined;
    const request = vi.fn(
      () =>
        new Promise<{ turnId: string }>((_resolve, reject) => {
          rejectFirstSteer = reject;
        }),
    );
    const queue = createQueue({ request });

    const settled: string[] = [];
    const first = queue.queue("first", { debounceMs: 0 }).catch(() => {
      settled.push("first");
    });
    await vi.advanceTimersByTimeAsync(0);
    const second = queue.queue("second", { debounceMs: 0 }).catch(() => {
      settled.push("second");
    });
    await vi.advanceTimersByTimeAsync(0);

    expect(request).toHaveBeenCalledOnce();
    rejectFirstSteer?.(new Error("cannot steer this turn"));
    await vi.advanceTimersByTimeAsync(0);
    await Promise.all([first, second]);

    expect(request).toHaveBeenCalledOnce();
    expect(settled).toEqual(["first", "second"]);
  });

  it("rejects accepted but unconsumed steering when cancelled", async () => {
    const request = vi.fn(async () => ({ turnId: "turn-1" }));
    const queue = createQueue({ request });

    const queued = queue.queue("completion wake", { debounceMs: 0 });
    const rejected = expect(queued).rejects.toBeInstanceOf(CodexSteeringAcceptedUnconfirmedError);
    await vi.advanceTimersByTimeAsync(0);
    expect(request).toHaveBeenCalledTimes(1);

    queue.cancel();
    await rejected;
    expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(false);
    await expect(queue.queue("too late", { debounceMs: 0 })).rejects.toThrow(
      "steering queue cancelled",
    );
  });

  it("rejects accepted but unconsumed steering when the run aborts", async () => {
    const controller = new AbortController();
    const request = vi.fn(async () => ({ turnId: "turn-1" }));
    const queue = createQueue({ request }, { signal: controller.signal });

    const queued = queue.queue("completion wake", { debounceMs: 0 });
    const rejected = expect(queued).rejects.toBeInstanceOf(CodexSteeringAcceptedUnconfirmedError);
    await vi.advanceTimersByTimeAsync(0);
    expect(request).toHaveBeenCalledTimes(1);

    controller.abort();
    await rejected;
    expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(false);
    await expect(queue.queue("too late", { debounceMs: 0 })).rejects.toThrow(
      "steering queue aborted",
    );
  });

  it.each([
    { closure: "terminal", reason: "steering queue admission sealed" },
    { closure: "abort", reason: "steering queue aborted" },
  ] as const)("fences preparation that finishes after $closure", async ({ closure, reason }) => {
    const started = createDeferred<void>();
    const finished = createDeferred<Awaited<ReturnType<QueueParams["prepareMessage"]>>>();
    const request = vi.fn(async () => ({ turnId: "turn-1" }));
    const controller = new AbortController();
    const queue = createQueue(
      { request },
      {
        signal: controller.signal,
        prepareMessage: () => {
          started.resolve();
          return finished.promise;
        },
      },
    );
    const images = [{ type: "image" as const, data: PNG_1X1, mimeType: "image/png" }];
    const prepared = await prepareMessage("delayed image", { images });
    const onQueueAccepted = vi.fn();
    const queued = queue.queue("delayed image", { images, debounceMs: 0, onQueueAccepted });
    const rejected = expect(queued).rejects.toThrow(reason);

    try {
      await started.promise;
      expect(onQueueAccepted).not.toHaveBeenCalled();
      if (closure === "terminal") {
        queue.sealAdmission();
      } else {
        controller.abort();
      }
      await rejected;
      expect(onQueueAccepted).toHaveBeenCalledExactlyOnceWith(false);

      finished.resolve(prepared);
      // The queue subscribed before this await, so its resumed dispatch path
      // runs before the assertion. Early cancellation alone is not this proof.
      await finished.promise;
      expect(request).not.toHaveBeenCalled();
      expect(onQueueAccepted).toHaveBeenCalledExactlyOnceWith(false);
      expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(false);
    } finally {
      queue.cancel();
      finished.resolve(prepared);
      await Promise.allSettled([queued, rejected, finished.promise]);
    }
  });

  it("does not dispatch a chained batch after cancellation", async () => {
    let acceptFirstSteer: (() => void) | undefined;
    const firstSteerAccepted = new Promise<void>((resolve) => {
      acceptFirstSteer = resolve;
    });
    const request = vi
      .fn()
      .mockImplementationOnce(async () => {
        await firstSteerAccepted;
        return { turnId: "turn-1" };
      })
      .mockResolvedValue({ turnId: "turn-1" });
    const queue = createQueue({ request });
    const onFirstAccepted = vi.fn();
    const onSecondAccepted = vi.fn();

    const first = queue.queue("on the wire", {
      debounceMs: 0,
      onQueueAccepted: onFirstAccepted,
    });
    const firstRejected = expect(first).rejects.toBeInstanceOf(
      CodexSteeringAcceptedUnconfirmedError,
    );
    await vi.advanceTimersByTimeAsync(0);
    const second = queue.queue("waiting", {
      debounceMs: 0,
      onQueueAccepted: onSecondAccepted,
    });
    const secondRejected = expect(second).rejects.toThrow("steering queue cancelled");
    await vi.advanceTimersByTimeAsync(0);

    queue.cancel();
    acceptFirstSteer?.();
    await vi.advanceTimersByTimeAsync(0);
    await Promise.all([firstRejected, secondRejected]);
    expect(request).toHaveBeenCalledTimes(1);
    expect(onFirstAccepted).toHaveBeenCalledWith(true);
    expect(onSecondAccepted).toHaveBeenCalledWith(false);
  });

  it("seals unsent admission while preserving a dispatched consumption confirmation", async () => {
    let acceptFirstSteer: (() => void) | undefined;
    const firstSteerAccepted = new Promise<void>((resolve) => {
      acceptFirstSteer = resolve;
    });
    const request = vi.fn(async () => {
      await firstSteerAccepted;
      return { turnId: "turn-1" };
    });
    const queue = createQueue({ request });
    const onDispatchedAccepted = vi.fn();
    const onChainedAccepted = vi.fn();
    const onDebouncedAccepted = vi.fn();
    const onLateAccepted = vi.fn();

    const dispatched = queue.queue("on the wire", {
      debounceMs: 0,
      onQueueAccepted: onDispatchedAccepted,
    });
    await vi.advanceTimersByTimeAsync(0);
    const chained = queue.queue("waiting on send chain", {
      debounceMs: 0,
      onQueueAccepted: onChainedAccepted,
    });
    const chainedRejected = expect(chained).rejects.toThrow("queue admission sealed");
    const debounced = queue.queue("still debounced", {
      debounceMs: 30_000,
      onQueueAccepted: onDebouncedAccepted,
    });
    const debouncedRejected = expect(debounced).rejects.toThrow("queue admission sealed");
    await vi.advanceTimersByTimeAsync(0);

    queue.sealAdmission();

    await Promise.all([chainedRejected, debouncedRejected]);
    await expect(
      queue.queue("too late", { debounceMs: 0, onQueueAccepted: onLateAccepted }),
    ).rejects.toThrow("queue admission sealed");
    expect(request).toHaveBeenCalledOnce();
    expect(onChainedAccepted).toHaveBeenCalledWith(false);
    expect(onDebouncedAccepted).toHaveBeenCalledWith(false);
    expect(onLateAccepted).toHaveBeenCalledWith(false);
    expect(onDispatchedAccepted).not.toHaveBeenCalled();

    expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(true);
    await dispatched;
    expect(onDispatchedAccepted).toHaveBeenCalledWith(true);

    queue.cancel();
    acceptFirstSteer?.();
    await vi.advanceTimersByTimeAsync(0);
    expect(request).toHaveBeenCalledOnce();
  });

  it("fully cancels a dispatched batch after admission was sealed", async () => {
    let acceptSteer: (() => void) | undefined;
    const steerAccepted = new Promise<void>((resolve) => {
      acceptSteer = resolve;
    });
    const request = vi.fn(async () => {
      await steerAccepted;
      return { turnId: "turn-1" };
    });
    const queue = createQueue({ request });
    const onQueueAccepted = vi.fn();

    const dispatched = queue.queue("on the wire", { debounceMs: 0, onQueueAccepted });
    const rejected = expect(dispatched).rejects.toBeInstanceOf(
      CodexSteeringAcceptedUnconfirmedError,
    );
    await vi.advanceTimersByTimeAsync(0);

    queue.sealAdmission();
    expect(onQueueAccepted).not.toHaveBeenCalled();
    queue.cancel();
    queue.cancel();

    await rejected;
    expect(onQueueAccepted).toHaveBeenCalledWith(true);
    expect(queue.confirmConsumed("openclaw:turn-1:steer:1")).toBe(false);
    acceptSteer?.();
    await vi.advanceTimersByTimeAsync(0);
  });

  it("rejects before dispatch when the run is already aborted", async () => {
    const controller = new AbortController();
    controller.abort();
    const request = vi.fn(async () => ({ turnId: "turn-1" }));
    const queue = createQueue({ request }, { signal: controller.signal });
    const onQueueAccepted = vi.fn();

    await expect(queue.queue("aborted", { debounceMs: 0, onQueueAccepted })).rejects.toThrow(
      "steering queue aborted",
    );
    expect(onQueueAccepted).toHaveBeenCalledWith(false);
    expect(request).not.toHaveBeenCalled();
  });

  it("rejects a debounced batch when the run aborts before dispatch", async () => {
    const controller = new AbortController();
    const request = vi.fn(async () => ({ turnId: "turn-1" }));
    const queue = createQueue({ request }, { signal: controller.signal });
    const onQueueAccepted = vi.fn();

    const queued = queue.queue("aborted", { debounceMs: 5, onQueueAccepted });
    const rejected = expect(queued).rejects.toThrow("steering queue aborted");
    controller.abort();
    await vi.advanceTimersByTimeAsync(5);

    await rejected;
    expect(request).not.toHaveBeenCalled();
    expect(onQueueAccepted).toHaveBeenCalledWith(false);
  });
});

/**
 * Debounced steering queue for forwarding user messages to an active Codex
 * app-server turn.
 */
import {
  embeddedAgentLog,
  type queueAgentHarnessMessage,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import {
  isCodexAppServerIndeterminateRequestCancellationError,
  isCodexAppServerIndeterminateTransportError,
  type CodexAppServerClient,
} from "./client.js";
import type { CodexUserInput } from "./protocol.js";

const CODEX_STEER_ALL_DEBOUNCE_MS = 500;
type AgentHarnessQueueMessageOptions = NonNullable<Parameters<typeof queueAgentHarnessMessage>[2]>;

export class CodexSteeringAcceptedUnconfirmedError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "CodexSteeringAcceptedUnconfirmedError";
  }
}

/** Per-message options for Codex steering queue behavior. */
export type CodexSteeringQueueOptions = Pick<
  AgentHarnessQueueMessageOptions,
  | "debounceMs"
  | "images"
  | "imageOrder"
  | "media"
  | "isInboundUserMessage"
  | "onQueueAccepted"
  | "userTurnTranscriptRecorder"
>;

type CodexSteeringCommitItem = Pick<
  CodexSteeringQueueOptions,
  "isInboundUserMessage" | "userTurnTranscriptRecorder"
>;

/**
 * Creates a queue that batches steer messages while still serializing
 * app-server `turn/steer` requests.
 */
export function createCodexSteeringQueue(params: {
  client: CodexAppServerClient;
  threadId: string;
  turnId: string;
  requestTimeoutMs: number;
  signal: AbortSignal;
  assertActive: () => void;
  prepareMessage: (text: string, options: CodexSteeringQueueOptions) => Promise<CodexUserInput[]>;
  beforeConfirmConsumed?: (items: readonly CodexSteeringCommitItem[]) => Promise<void>;
}) {
  type PendingSteerMessage = CodexSteeringQueueOptions & {
    acceptance: "open" | "accepted" | "rejected";
    text: string;
    resolve: () => void;
    reject: (error: unknown) => void;
    settled: boolean;
  };
  type PendingSteerBatch = {
    items: PendingSteerMessage[];
  };
  let batchedMessages: PendingSteerMessage[] = [];
  const dispatchedBatches = new Map<string, PendingSteerBatch>();
  const pendingMessages = new Set<PendingSteerMessage>();
  let batchTimer: NodeJS.Timeout | undefined;
  let batchSequence = 0;
  let sendChain: Promise<void> = Promise.resolve();
  let sealedError: Error | undefined;
  let closedError: Error | undefined;

  const assertActive = () => {
    const unavailableError = closedError ?? sealedError;
    if (unavailableError) {
      throw unavailableError;
    }
    params.signal.throwIfAborted();
    params.assertActive();
  };

  const clearBatchTimer = () => {
    if (batchTimer) {
      clearTimeout(batchTimer);
      batchTimer = undefined;
    }
  };

  const reportItemAcceptance = (item: PendingSteerMessage, accepted: boolean) => {
    if (item.acceptance !== "open") {
      return;
    }
    item.acceptance = accepted ? "accepted" : "rejected";
    item.onQueueAccepted?.(accepted);
  };

  const resolveItem = (item: PendingSteerMessage) => {
    if (item.settled) {
      return;
    }
    reportItemAcceptance(item, true);
    item.settled = true;
    pendingMessages.delete(item);
    item.resolve();
  };

  const rejectItem = (item: PendingSteerMessage, error: unknown) => {
    if (item.settled) {
      return;
    }
    item.settled = true;
    pendingMessages.delete(item);
    reportItemAcceptance(item, false);
    item.reject(
      item.acceptance === "accepted"
        ? new CodexSteeringAcceptedUnconfirmedError(
            "Codex accepted steering but did not confirm transcript consumption",
            { cause: error },
          )
        : error,
    );
  };

  const closeQueue = (error: Error) => {
    if (closedError) {
      return;
    }
    closedError = error;
    params.signal.removeEventListener("abort", abortQueue);
    clearBatchTimer();
    batchedMessages = [];
    // An issued RPC may have reached Codex before its response. Fence wire-dispatched
    // batches as accepted-unconfirmed so terminal cancellation cannot replay them.
    for (const batch of dispatchedBatches.values()) {
      for (const item of batch.items) {
        reportItemAcceptance(item, true);
      }
    }
    dispatchedBatches.clear();
    for (const item of pendingMessages) {
      rejectItem(item, error);
    }
  };
  const sealQueueAdmission = () => {
    if (sealedError || closedError) {
      return;
    }
    sealedError = new Error("codex app-server steering queue admission sealed");
    clearBatchTimer();
    batchedMessages = [];
    const dispatchedItems = new Set(
      [...dispatchedBatches.values()].flatMap((batch) => batch.items),
    );
    // Terminal receipt closes admission immediately, but a user-message
    // completion already ahead of it on the wire still owns its dispatched batch.
    for (const item of pendingMessages) {
      if (!dispatchedItems.has(item)) {
        rejectItem(item, sealedError);
      }
    }
  };
  const abortQueue = () => {
    closeQueue(new Error("codex app-server steering queue aborted"));
  };
  const cancelQueue = () => {
    closeQueue(new Error("codex app-server steering queue cancelled"));
  };

  const sendBatch = async (items: PendingSteerMessage[]) => {
    const liveItems = items.filter((item) => !item.settled);
    if (liveItems.length === 0) {
      return;
    }
    let clientUserMessageId: string | undefined;
    try {
      assertActive();
      const input: CodexUserInput[] = [];
      // Reserve sendChain ownership before any preparation so later text cannot
      // overtake an image read. Preparing input has not crossed the wire boundary.
      for (const item of liveItems) {
        input.push(...(await params.prepareMessage(item.text, item)));
        assertActive();
      }
      // No await between final owner validation and RPC dispatch. Only these
      // batches become accepted-unconfirmed if cancellation races the response.
      clientUserMessageId = `openclaw:${params.turnId}:steer:${++batchSequence}`;
      dispatchedBatches.set(clientUserMessageId, { items: liveItems });
      // turn/steer is an ack, but nothing guarantees the app-server answers it.
      // Without a deadline and the run signal the caller only unblocks when the
      // app-server client closes, which strands whichever channel handler is
      // awaiting delivery and wedges every later steer behind sendChain.
      await params.client.request(
        "turn/steer",
        {
          threadId: params.threadId,
          expectedTurnId: params.turnId,
          input,
          clientUserMessageId,
        },
        { timeoutMs: params.requestTimeoutMs, signal: params.signal },
      );
      for (const item of liveItems) {
        reportItemAcceptance(item, true);
      }
    } catch (error) {
      if (clientUserMessageId) {
        dispatchedBatches.delete(clientUserMessageId);
      }
      const acceptedUnconfirmed =
        clientUserMessageId !== undefined &&
        (isCodexAppServerIndeterminateRequestCancellationError(error) ||
          isCodexAppServerIndeterminateTransportError(error));
      for (const item of liveItems) {
        if (acceptedUnconfirmed) {
          reportItemAcceptance(item, true);
        }
        rejectItem(item, error);
      }
      throw error;
    }
  };

  const enqueueSend = (items: PendingSteerMessage[]) => {
    const send = sendChain.then(() => sendBatch(items));
    // Preserve submission order after rejection: later messages must fall back
    // instead of overtaking the failed message with another turn/steer request.
    sendChain = send;
    void send.catch((error: unknown) => {
      for (const item of items) {
        rejectItem(item, error);
      }
      embeddedAgentLog.debug("codex app-server queued steer failed", { error });
    });
    return send;
  };

  const flushBatch = (): Promise<void> => {
    clearBatchTimer();
    const items = batchedMessages;
    batchedMessages = [];
    if (items.length === 0) {
      return sendChain;
    }
    const send = enqueueSend(items);
    void send.catch(() => undefined);
    return send;
  };

  const createPendingMessage = (
    text: string,
    options?: CodexSteeringQueueOptions,
  ): { item: PendingSteerMessage; delivery: Promise<void> } => {
    let resolveDelivery!: () => void;
    let rejectDelivery!: (error: unknown) => void;
    const delivery = new Promise<void>((resolve, reject) => {
      resolveDelivery = resolve;
      rejectDelivery = reject;
    });
    const item = {
      ...options,
      acceptance: "open" as const,
      text,
      resolve: resolveDelivery,
      reject: rejectDelivery,
      settled: false,
    };
    pendingMessages.add(item);
    return { item, delivery };
  };

  params.signal.addEventListener("abort", abortQueue, { once: true });
  if (params.signal.aborted) {
    abortQueue();
  }

  return {
    async queue(text: string, options?: CodexSteeringQueueOptions) {
      try {
        assertActive();
      } catch (error) {
        options?.onQueueAccepted?.(false);
        throw error;
      }
      const { item, delivery } = createPendingMessage(text, options);
      batchedMessages.push(item);
      clearBatchTimer();
      const debounceMs = normalizeCodexSteerDebounceMs(options?.debounceMs);
      if (debounceMs === 0) {
        void flushBatch();
      } else {
        batchTimer = setTimeout(() => {
          batchTimer = undefined;
          void flushBatch();
        }, debounceMs);
      }
      return await delivery;
    },
    confirmConsumed(clientUserMessageId: string) {
      const batch = dispatchedBatches.get(clientUserMessageId);
      if (!batch) {
        return false;
      }
      dispatchedBatches.delete(clientUserMessageId);
      for (const item of batch.items) {
        reportItemAcceptance(item, true);
      }
      const resolveBatch = () => {
        for (const item of batch.items) {
          resolveItem(item);
        }
        return true;
      };
      const rejectBatch = (error: unknown) => {
        for (const item of batch.items) {
          rejectItem(item, error);
        }
        return true;
      };
      if (!params.beforeConfirmConsumed) {
        return resolveBatch();
      }
      try {
        return params.beforeConfirmConsumed(batch.items).then(resolveBatch, rejectBatch);
      } catch (error) {
        return rejectBatch(error);
      }
    },
    sealAdmission: sealQueueAdmission,
    cancel: cancelQueue,
  };
}

/** Normalizes steer debounce milliseconds, preserving explicit zero. */
function normalizeCodexSteerDebounceMs(value: number | undefined): number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0
    ? Math.floor(value)
    : CODEX_STEER_ALL_DEBOUNCE_MS;
}

import { attemptTerminal, type EmbeddedRunAttemptResult } from "./attempt-terminal.js";

export const readAttemptTerminal = (result: EmbeddedRunAttemptResult) =>
  attemptTerminal.project(result.terminal);

import {
  agentHarnessAttemptTerminal,
  type AgentHarnessAttemptResult,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import type { TranscriptEntryAnchor } from "openclaw/plugin-sdk/session-transcript-runtime";

export type EmbeddedRunAttemptResult = Extract<AgentHarnessAttemptResult, { terminal: unknown }> & {
  /** Host-private terminal identity returned to the harness selection boundary. */
  contextEngineTerminalAnchor?: TranscriptEntryAnchor;
};
export type AttemptFailureSource = Extract<
  EmbeddedRunAttemptResult["terminal"],
  { kind: "failed" }
>["source"];
export const attemptTerminal = agentHarnessAttemptTerminal;

// Codex tests cover attempt timeouts plugin behavior.
import { MAX_TIMER_TIMEOUT_MS } from "openclaw/plugin-sdk/number-runtime";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  isCodexAppServerStartupError,
  resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs,
  resolveCodexGatewayTimeoutWithGraceMs,
  resolveCodexStartupTimeoutMs,
  resolveCodexTurnAssistantCompletionIdleTimeoutMs,
  resolveCodexTurnCompletionIdleTimeoutMs,
  resolveCodexTurnTerminalIdleTimeoutMs,
  withCodexStartupTimeout,
} from "./attempt-timeouts.js";

const CODEX_APP_SERVER_STARTUP_TIMEOUT_FLOOR_MS = 100;
const CODEX_TURN_COMPLETION_IDLE_TIMEOUT_MS = 60_000;
const CODEX_TURN_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS = 10_000;
const CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS = 5 * 60_000;
const CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS = 30 * 60_000;

describe("Codex app-server attempt timeouts", () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it("resolves startup timeout with a configurable floor", () => {
    expect(resolveCodexStartupTimeoutMs({ timeoutMs: 5 })).toBe(
      CODEX_APP_SERVER_STARTUP_TIMEOUT_FLOOR_MS,
    );
    expect(resolveCodexStartupTimeoutMs({ timeoutMs: 500 })).toBe(500);
    expect(resolveCodexStartupTimeoutMs({ timeoutMs: 5, timeoutFloorMs: 250 })).toBe(250);
    expect(resolveCodexStartupTimeoutMs({ timeoutMs: Number.NaN })).toBe(
      CODEX_APP_SERVER_STARTUP_TIMEOUT_FLOOR_MS,
    );
    expect(resolveCodexStartupTimeoutMs({ timeoutMs: 500, timeoutFloorMs: Number.NaN })).toBe(500);
    expect(resolveCodexStartupTimeoutMs({ timeoutMs: Number.MAX_SAFE_INTEGER })).toBe(
      MAX_TIMER_TIMEOUT_MS,
    );
    expect(
      resolveCodexStartupTimeoutMs({
        timeoutMs: Number.MAX_SAFE_INTEGER,
        timeoutFloorMs: Number.MAX_SAFE_INTEGER,
      }),
    ).toBe(MAX_TIMER_TIMEOUT_MS);
    expect(
      resolveCodexStartupTimeoutMs({
        timeoutMs: Number.NaN,
        timeoutFloorMs: Number.NaN,
      }),
    ).toBe(CODEX_APP_SERVER_STARTUP_TIMEOUT_FLOOR_MS);
  });

  it("normalizes turn idle timeout overrides", () => {
    expect(CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS).toBe(5 * 60_000);
    expect(CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS).toBeGreaterThan(
      CODEX_TURN_COMPLETION_IDLE_TIMEOUT_MS,
    );

    expect(resolveCodexTurnCompletionIdleTimeoutMs(undefined)).toBe(
      CODEX_TURN_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnCompletionIdleTimeoutMs(Number.POSITIVE_INFINITY)).toBe(
      CODEX_TURN_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnCompletionIdleTimeoutMs(2.9)).toBe(2);
    expect(resolveCodexTurnCompletionIdleTimeoutMs(0)).toBe(1);
    expect(resolveCodexTurnCompletionIdleTimeoutMs(Number.MAX_SAFE_INTEGER)).toBe(
      MAX_TIMER_TIMEOUT_MS,
    );

    expect(resolveCodexTurnAssistantCompletionIdleTimeoutMs(undefined)).toBe(
      CODEX_TURN_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnAssistantCompletionIdleTimeoutMs(Number.NaN)).toBe(
      CODEX_TURN_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnAssistantCompletionIdleTimeoutMs(9.8)).toBe(9);
    expect(resolveCodexTurnAssistantCompletionIdleTimeoutMs(-10)).toBe(1);

    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(undefined, 123)).toBe(
      CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(Number.NaN, 123)).toBe(
      CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(undefined, 120_000)).toBe(
      CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(undefined, 6 * 60_000)).toBe(
      6 * 60_000,
    );
    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(undefined, Number.NaN)).toBe(
      CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(7.9, 123)).toBe(7);
    expect(resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(0, 123)).toBe(1);
    expect(
      resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(
        Number.MAX_SAFE_INTEGER,
        Number.MAX_SAFE_INTEGER,
      ),
    ).toBe(MAX_TIMER_TIMEOUT_MS);

    expect(resolveCodexTurnTerminalIdleTimeoutMs(undefined)).toBe(
      CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnTerminalIdleTimeoutMs(Number.NEGATIVE_INFINITY)).toBe(
      CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnTerminalIdleTimeoutMs(3.7)).toBe(3);
    expect(resolveCodexTurnTerminalIdleTimeoutMs(-1)).toBe(1);
    expect(resolveCodexTurnTerminalIdleTimeoutMs(Number.MAX_SAFE_INTEGER)).toBe(
      MAX_TIMER_TIMEOUT_MS,
    );
  });

  it("derives the terminal idle timeout from the effective run budget", () => {
    const overFloor = CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS + 15 * 60_000;
    // A run budget above the 30-minute floor extends the watchdog (the #85242 fix).
    expect(resolveCodexTurnTerminalIdleTimeoutMs(undefined, overFloor)).toBe(overFloor);
    // A run budget below the floor keeps the 30-minute floor (protection never shortened).
    expect(resolveCodexTurnTerminalIdleTimeoutMs(undefined, 10 * 60_000)).toBe(
      CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS,
    );
    // A non-finite budget falls back to the 30-minute default.
    expect(resolveCodexTurnTerminalIdleTimeoutMs(undefined, Number.POSITIVE_INFINITY)).toBe(
      CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS,
    );
    expect(resolveCodexTurnTerminalIdleTimeoutMs(undefined, Number.MAX_SAFE_INTEGER)).toBe(
      MAX_TIMER_TIMEOUT_MS,
    );
    // An explicit override still wins even when a run budget is present.
    expect(resolveCodexTurnTerminalIdleTimeoutMs(5 * 60_000, overFloor)).toBe(5 * 60_000);
  });

  it("caps gateway timeout grace", () => {
    expect(resolveCodexGatewayTimeoutWithGraceMs(120_000)).toBe(130_000);
    expect(resolveCodexGatewayTimeoutWithGraceMs(120_000, 500)).toBe(120_500);
    expect(resolveCodexGatewayTimeoutWithGraceMs(Number.MAX_SAFE_INTEGER)).toBe(
      MAX_TIMER_TIMEOUT_MS,
    );
    expect(resolveCodexGatewayTimeoutWithGraceMs(MAX_TIMER_TIMEOUT_MS - 100, 500)).toBe(
      MAX_TIMER_TIMEOUT_MS,
    );
  });

  it("returns the startup operation result before timeout", async () => {
    await expect(
      withCodexStartupTimeout({
        timeoutMs: 1_000,
        signal: new AbortController().signal,
        operation: async () => "ready",
      }),
    ).resolves.toBe("ready");
  });

  it("waits for startup timeout cleanup before rejecting", async () => {
    vi.useFakeTimers();
    const events: string[] = [];
    const run = withCodexStartupTimeout({
      timeoutMs: 10,
      signal: new AbortController().signal,
      onTimeout: async () => {
        events.push("cleanup-start");
        await new Promise<void>((resolve) => {
          setTimeout(() => {
            events.push("cleanup-done");
            resolve();
          }, 5);
        });
      },
      operation: async () => new Promise<never>(() => {}),
    });
    const errorResult = run.catch((error: unknown) => error);

    await vi.advanceTimersByTimeAsync(10);
    expect(events).toEqual(["cleanup-start"]);
    await vi.advanceTimersByTimeAsync(5);
    const error = await errorResult;
    expect(isCodexAppServerStartupError(error, "timed_out")).toBe(true);
    expect((error as Error).message).toBe("codex app-server startup timed out");
    expect(events).toEqual(["cleanup-start", "cleanup-done"]);
  });

  it("rejects startup timeout when aborted before completion", async () => {
    vi.useFakeTimers();
    const controller = new AbortController();
    const run = withCodexStartupTimeout({
      timeoutMs: 1_000,
      signal: controller.signal,
      operation: async () => new Promise<never>(() => {}),
    });
    const errorResult = run.catch((error: unknown) => error);

    controller.abort();

    const error = await errorResult;
    expect(isCodexAppServerStartupError(error, "aborted")).toBe(true);
    expect((error as Error).message).toBe("codex app-server startup aborted");
  });
});

/**
 * Timeout defaults and normalizers for Codex app-server startup and turn
 * liveness watches.
 */
import { addTimerTimeoutGraceMs, resolveTimerTimeoutMs } from "openclaw/plugin-sdk/number-runtime";

/** Minimum startup timeout accepted by the Codex app-server harness. */
const CODEX_APP_SERVER_STARTUP_TIMEOUT_FLOOR_MS = 100;
/** Default idle timeout while waiting for app-server turn completion. */
const CODEX_TURN_COMPLETION_IDLE_TIMEOUT_MS = 60_000;
/** Short guard after apparent assistant completion. */
const CODEX_TURN_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS = 10_000;
// Native Codex can spend a long quiet window synthesizing after tool results,
// raw assistant/reasoning completions, or reasoning progress. Forwarded deltas
// count as activity, but older native paths may not surface them, so keep this
// terminal guard conservative.
const CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS = 5 * 60_000;
/** Guard after reasoning/commentary progress when no tool handoff occurred. */
export const CODEX_POST_REASONING_REPLY_IDLE_TIMEOUT_MS = 5 * 60_000;
/** Long terminal idle watch for app-server turns that never send completion. */
const CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS = 30 * 60_000;
// Terminal receipt must still reach settlement; force a bounded abort if the
// handler tail stalls, or the session can remain active forever.
export const TURN_TERMINAL_SETTLEMENT_IDLE_TIMEOUT_MS = 2 * 60_000;
// Aborted/timed-out completions still join queued projection work; this grace
// bounds a blocked handler tail so finalization cannot hang forever.
export const TURN_FINALIZE_DRAIN_ABORT_GRACE_MS = 5_000;

type CodexAppServerStartupErrorReason = "aborted" | "timed_out";

export class CodexAppServerStartupError extends Error {
  readonly code = "CODEX_APP_SERVER_STARTUP_CANCELLED";

  constructor(
    readonly reason: CodexAppServerStartupErrorReason,
    message = reason === "timed_out"
      ? "codex app-server startup timed out"
      : "codex app-server startup aborted",
  ) {
    super(message);
    this.name = "CodexAppServerStartupError";
  }
}

export function isCodexAppServerStartupError(
  error: unknown,
  reason?: CodexAppServerStartupErrorReason,
): error is CodexAppServerStartupError {
  return (
    error instanceof Error &&
    "code" in error &&
    error.code === "CODEX_APP_SERVER_STARTUP_CANCELLED" &&
    "reason" in error &&
    (error.reason === "aborted" || error.reason === "timed_out") &&
    (reason === undefined || error.reason === reason)
  );
}

function resolvePositiveIntegerTimeoutMs(value: number | undefined, fallbackMs: number): number {
  const fallback = resolveTimerTimeoutMs(fallbackMs, 1);
  return resolveTimerTimeoutMs(value, fallback);
}

/** Runs startup work with abort and timeout handling plus optional cleanup. */
export async function withCodexStartupTimeout<T>(params: {
  timeoutMs: number;
  signal: AbortSignal;
  onTimeout?: () => void | Promise<void>;
  operation: () => Promise<T>;
}): Promise<T> {
  if (params.signal.aborted) {
    throw new CodexAppServerStartupError("aborted");
  }
  let timeout: NodeJS.Timeout | undefined;
  let abortCleanup: (() => void) | undefined;
  let timeoutError: Error | undefined;
  let timeoutCleanup: Promise<void> | undefined;
  try {
    return await Promise.race([
      params.operation(),
      new Promise<never>((_, reject) => {
        const rejectOnce = (error: Error) => {
          if (timeout) {
            clearTimeout(timeout);
            timeout = undefined;
          }
          reject(error);
        };
        timeout = setTimeout(() => {
          timeoutError = new CodexAppServerStartupError("timed_out");
          timeoutCleanup = Promise.resolve(params.onTimeout?.()).then(
            () => undefined,
            () => undefined,
          );
          void timeoutCleanup.finally(() => {
            rejectOnce(timeoutError!);
          });
        }, params.timeoutMs);
        const abortListener = () => rejectOnce(new CodexAppServerStartupError("aborted"));
        params.signal.addEventListener("abort", abortListener, { once: true });
        abortCleanup = () => params.signal.removeEventListener("abort", abortListener);
      }),
    ]);
  } catch (error) {
    if (timeoutError) {
      await timeoutCleanup;
      throw timeoutError;
    }
    throw error;
  } finally {
    if (timeout) {
      clearTimeout(timeout);
    }
    abortCleanup?.();
  }
}

/** Resolves startup timeout while honoring the configured floor. */
export function resolveCodexStartupTimeoutMs(params: {
  timeoutMs: number;
  timeoutFloorMs?: number;
}): number {
  const timeoutFloorMs = resolvePositiveIntegerTimeoutMs(
    params.timeoutFloorMs,
    CODEX_APP_SERVER_STARTUP_TIMEOUT_FLOOR_MS,
  );
  const timeoutMs = resolvePositiveIntegerTimeoutMs(params.timeoutMs, timeoutFloorMs);
  return Math.max(timeoutFloorMs, timeoutMs);
}

/** Resolves the completion-idle timeout for an active turn. */
export function resolveCodexTurnCompletionIdleTimeoutMs(value: number | undefined): number {
  return resolvePositiveIntegerTimeoutMs(value, CODEX_TURN_COMPLETION_IDLE_TIMEOUT_MS);
}

/** Resolves the short assistant-completion release timeout. */
export function resolveCodexTurnAssistantCompletionIdleTimeoutMs(
  value: number | undefined,
): number {
  return resolvePositiveIntegerTimeoutMs(value, CODEX_TURN_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS);
}

/** Resolves the conservative post-tool raw assistant guard timeout. */
export function resolveCodexPostToolRawAssistantCompletionIdleTimeoutMs(
  value: number | undefined,
  fallbackMs: number,
): number {
  const defaultMs = Math.max(
    resolvePositiveIntegerTimeoutMs(undefined, fallbackMs),
    CODEX_POST_TOOL_RAW_ASSISTANT_COMPLETION_IDLE_TIMEOUT_MS,
  );
  return resolvePositiveIntegerTimeoutMs(value, defaultMs);
}

/** Resolves the long terminal turn idle timeout. */
export function resolveCodexTurnTerminalIdleTimeoutMs(
  value: number | undefined,
  runTimeoutOverrideMs?: number,
): number {
  // The terminal watchdog is wrapper-owned; Codex turn options do not carry a
  // timeout budget. Follow explicit per-run intent without replacing the floor
  // with the implicit 48-hour agent default.
  const explicitRunBudgetMs = resolvePositiveIntegerTimeoutMs(
    runTimeoutOverrideMs,
    CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS,
  );
  const defaultMs = Math.max(CODEX_TURN_TERMINAL_IDLE_TIMEOUT_MS, explicitRunBudgetMs);
  return resolvePositiveIntegerTimeoutMs(value, defaultMs);
}

/** Adds gateway grace time to a caller timeout without overflowing invalid values. */
export function resolveCodexGatewayTimeoutWithGraceMs(timeoutMs: number, graceMs = 10_000): number {
  const timeout = resolvePositiveIntegerTimeoutMs(timeoutMs, 1);
  const grace = resolveTimerTimeoutMs(graceMs, 0, 0);
  return addTimerTimeoutGraceMs(timeout, grace) ?? timeout;
}

// Codex tests cover attempt turn watches plugin behavior.
import { MAX_TIMER_TIMEOUT_MS } from "openclaw/plugin-sdk/number-runtime";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { updateActiveCompletionBlockerItemIds } from "./attempt-notifications.js";
import { createCodexAttemptTurnWatchController } from "./attempt-turn-watches.js";

describe("Codex app-server attempt turn watches", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(0);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.clearAllTimers();
    vi.useRealTimers();
  });

  function createController(
    overrides: Partial<Parameters<typeof createCodexAttemptTurnWatchController>[0]> = {},
  ) {
    const abortController = new AbortController();
    let completed = false;
    let terminalQueued = false;
    let activeRequests = 0;
    let activeRequestsWithoutTimeout = 0;
    let activeItems = 0;
    let activeCompletionBlockers = 0;
    let activeFinalizationHooks = 0;
    let canReleaseAssistantCompletionIdle = true;
    const interrupts: Array<Record<string, unknown>> = [];
    const timeouts: Array<Record<string, unknown>> = [];
    const events: Array<{ name: string; fields: Record<string, unknown> }> = [];
    const progress: string[] = [];
    const diagnostics: string[] = [];
    const controller = createCodexAttemptTurnWatchController({
      threadId: "thread-1",
      signal: abortController.signal,
      getTurnId: () => "turn-1",
      isCompleted: () => completed,
      isTerminalTurnNotificationQueued: () => terminalQueued,
      getActiveAppServerTurnRequests: () => activeRequests,
      getActiveAppServerTurnRequestsWithoutTimeout: () => activeRequestsWithoutTimeout,
      getActiveTurnItemCount: () => activeItems,
      getActiveCompletionBlockerItemCount: () => activeCompletionBlockers,
      getActiveFinalizationHookCount: () => activeFinalizationHooks,
      canReleaseAssistantCompletionIdle: () => canReleaseAssistantCompletionIdle,
      turnCompletionIdleTimeoutMs: 10,
      turnAssistantCompletionIdleTimeoutMs: 10,
      turnAttemptIdleTimeoutMs: 10,
      turnTerminalIdleTimeoutMs: 10,
      interruptTimeoutMs: 5,
      onInterruptTurn: async (input) => {
        interrupts.push(input);
        return true;
      },
      onTimeout: (timeout) => timeouts.push(timeout),
      onAbort: (reason) => abortController.abort(reason),
      onCompleted: () => {
        completed = true;
      },
      onRecordEvent: (name, fields) => events.push({ name, fields }),
      onAttemptProgress: (reason) => progress.push(reason),
      onProgressDiagnostic: (reason) => diagnostics.push(reason),
      ...overrides,
    });
    return {
      controller,
      abortController,
      get completed() {
        return completed;
      },
      set terminalQueued(value: boolean) {
        terminalQueued = value;
      },
      set activeRequests(value: number) {
        activeRequests = value;
      },
      set activeRequestsWithoutTimeout(value: number) {
        activeRequestsWithoutTimeout = value;
      },
      set activeItems(value: number) {
        activeItems = value;
      },
      set activeCompletionBlockers(value: number) {
        activeCompletionBlockers = value;
      },
      set activeFinalizationHooks(value: number) {
        activeFinalizationHooks = value;
      },
      set canReleaseAssistantCompletionIdle(value: boolean) {
        canReleaseAssistantCompletionIdle = value;
      },
      interrupts,
      timeouts,
      events,
      progress,
      diagnostics,
    };
  }

  it("fires completion idle timeout when an armed turn goes quiet", () => {
    const harness = createController();

    harness.controller.touchActivity("turn:start", { arm: true });
    vi.advanceTimersByTime(10);

    expect(harness.timeouts).toMatchObject([
      {
        kind: "completion",
        idleMs: 10,
        timeoutMs: 10,
        lastActivityReason: "turn:start",
        details: {
          activeAppServerTurnRequests: 0,
          activeTurnItemCount: 0,
          terminalTurnNotificationQueued: false,
          completionIdleWatchArmed: true,
          assistantCompletionIdleWatchArmed: false,
          terminalIdleWatchArmed: false,
        },
      },
    ]);
    expect(harness.abortController.signal.reason).toBe("turn_completion_idle_timeout");
  });

  it("prefers completion idle timeout when completion and progress watches are due together", () => {
    const harness = createController();

    harness.controller.armAttemptIdleWatch();
    harness.controller.touchActivity("request:item/tool/call:response", {
      arm: true,
      attemptProgress: true,
      attemptTimeoutMs: 10,
    });
    vi.advanceTimersByTime(10);

    expect(harness.timeouts).toMatchObject([
      {
        kind: "completion",
        idleMs: 10,
        timeoutMs: 10,
        lastActivityReason: "request:item/tool/call:response",
      },
    ]);
    expect(harness.abortController.signal.reason).toBe("turn_completion_idle_timeout");
  });

  it("clamps oversized completion idle timeouts before scheduling", () => {
