/** Shared Computer Use plugin cache reconciliation for isolated Codex homes. */
import fs from "node:fs/promises";
import path from "node:path";
import {
  assertDirectoryIdentityStable,
  directoryIdentityIsStable,
  prepareOwnedServiceParent,
} from "./computer-use-service-path.js";
import type { ResolvedCodexComputerUseConfig } from "./config.js";
import {
  resolveFirstExistingMacOSDesktopCodexBundledMarketplacePath,
  resolveMacOSDesktopCodexBundledMarketplaceCandidates,
} from "./desktop-app-paths.js";

type CodexComputerUsePluginCacheRepairResult =
  | {
      status: "disabled" | "explicit_marketplace" | "independent" | "source_missing" | "shared";
      changed: boolean;
      message: string;
      cachePath?: string;
      targetPath?: string;
      version?: string;
      removedStaleVersions: string[];
      warnings: string[];
    }
  | {
      status: "failed";
      changed: false;
      message: string;
      removedStaleVersions: string[];
      warnings: string[];
    };

const DEFAULT_CODEX_COMPUTER_USE_BUNDLED_MARKETPLACE_PATH =
  resolveMacOSDesktopCodexBundledMarketplaceCandidates("darwin")[0] ?? "";

const DEFAULT_BUNDLED_MARKETPLACE_NAME = "openai-bundled";
export async function ensureCodexComputerUseSharedPluginCache(params: {
  codexHome: string;
  config: ResolvedCodexComputerUseConfig;
  bundledMarketplacePath?: string;
  bundledMarketplacePathCandidates?: readonly string[];
  ownershipRoot?: string;
  assertCurrent?: () => void;
  forceRefresh?: boolean;
}): Promise<CodexComputerUsePluginCacheRepairResult> {
  if (!params.config.enabled) {
    return skippedCacheResult(
      "disabled",
      "Computer Use cache sharing skipped because it is disabled.",
    );
  }
  if (params.config.pluginCacheMode === "independent") {
    return skippedCacheResult(
      "independent",
      "Computer Use cache sharing skipped because pluginCacheMode is independent.",
    );
  }
  if (params.config.marketplaceName || params.config.marketplacePath) {
    return skippedCacheResult(
      "explicit_marketplace",
      "Computer Use cache sharing skipped because an explicit marketplace is configured.",
    );
  }

  const bundledMarketplacePath = resolveComputerUseBundledMarketplacePath(params);
  const sourcePluginRoot = path.join(bundledMarketplacePath, "plugins", params.config.pluginName);
  const version = await readBundledPluginVersion(sourcePluginRoot);
  if (!version) {
    return skippedCacheResult(
      "source_missing",
      `Computer Use bundled plugin source was not found at ${sourcePluginRoot}.`,
    );
  }

  const marketplaceName = params.config.marketplaceName ?? DEFAULT_BUNDLED_MARKETPLACE_NAME;
  const cacheRoot = path.join(
    params.codexHome,
    "plugins",
    "cache",
    marketplaceName,
    params.config.pluginName,
  );
  const cachePath = path.join(cacheRoot, version);
  const changed = await ensureRealDirectoryCopy(cachePath, sourcePluginRoot, version, {
    codexHome: params.codexHome,
    ownershipRoot: params.ownershipRoot,
    assertCurrent: params.assertCurrent,
    forceRefresh: params.forceRefresh,
  });
  return {
    status: "shared",
    changed,
    cachePath,
    targetPath: sourcePluginRoot,
    version,
    removedStaleVersions: [],
    warnings: [],
    message: `Computer Use plugin cache ${cachePath} contains bundled plugin ${sourcePluginRoot}.`,
  };
}

function resolveComputerUseBundledMarketplacePath(params: {
  bundledMarketplacePath?: string;
  bundledMarketplacePathCandidates?: readonly string[];
}): string {
  return (
    params.bundledMarketplacePath ??
    resolveFirstExistingMacOSDesktopCodexBundledMarketplacePath({
      candidates: params.bundledMarketplacePathCandidates,
    }) ??
    params.bundledMarketplacePathCandidates?.[0] ??
    DEFAULT_CODEX_COMPUTER_USE_BUNDLED_MARKETPLACE_PATH
  );
}

async function readBundledPluginVersion(sourcePluginRoot: string): Promise<string | undefined> {
  const pluginJsonPath = path.join(sourcePluginRoot, ".codex-plugin", "plugin.json");
  let raw: string;
  try {
    raw = await fs.readFile(pluginJsonPath, "utf8");
  } catch {
    return undefined;
  }
  try {
    const parsed = JSON.parse(raw) as { version?: unknown };
    return typeof parsed.version === "string" && parsed.version.trim()
      ? parsed.version.trim()
      : undefined;
  } catch {
    return undefined;
  }
}

async function ensureRealDirectoryCopy(
  cachePath: string,
  sourcePluginRoot: string,
  version: string,
  boundary: {
    codexHome: string;
    ownershipRoot?: string;
    assertCurrent?: () => void;
    forceRefresh?: boolean;
  },
): Promise<boolean> {
  const cacheRoot = path.dirname(cachePath);
  const ownedParent = boundary.ownershipRoot
    ? await prepareOwnedServiceParent({
        ownershipRoot: boundary.ownershipRoot,
        codexHome: boundary.codexHome,
        targetParent: cacheRoot,
      })
    : undefined;
  if (!ownedParent) {
    await fs.mkdir(cacheRoot, { recursive: true });
  }
  const physicalCachePath = ownedParent
    ? path.join(ownedParent.realPath, path.basename(cachePath))
    : cachePath;
  const stat = await fs.lstat(physicalCachePath).catch(() => undefined);
  if (stat?.isDirectory() && !stat.isSymbolicLink()) {
    const cachedVersion = await readBundledPluginVersion(physicalCachePath);
    if (cachedVersion === version && !boundary.forceRefresh) {
      return false;
    }
  }
  const cacheName = path.basename(cachePath);
  const physicalCacheRoot = path.dirname(physicalCachePath);
  const stagingRoot = await fs.mkdtemp(path.join(physicalCacheRoot, `.${cacheName}.staging-`));
  const stagedPath = path.join(stagingRoot, cacheName);
  const backupPath = path.join(
    physicalCacheRoot,
    `.${cacheName}.backup-${process.pid}-${Date.now()}`,
  );
  let backupCreated = false;
  try {
    await fs.cp(sourcePluginRoot, stagedPath, { recursive: true });
    if (ownedParent) {
      await assertDirectoryIdentityStable(ownedParent, "Computer Use plugin cache parent");
    }
    if (stat) {
      boundary.assertCurrent?.();
      await fs.rename(physicalCachePath, backupPath);
      backupCreated = true;
    }
    try {
      if (ownedParent) {
        await assertDirectoryIdentityStable(ownedParent, "Computer Use plugin cache parent");
      }
      boundary.assertCurrent?.();
      await fs.rename(stagedPath, physicalCachePath);
    } catch (error) {
      if (backupCreated) {
        try {
          if (ownedParent) {
            await assertDirectoryIdentityStable(ownedParent, "Computer Use plugin cache parent");
          }
          await fs.rename(backupPath, physicalCachePath);
          backupCreated = false;
        } catch (restoreError) {
          throw new Error(
            `Failed to install Computer Use cache ${cachePath} and restore its prior copy: ${String(error)}`,
            { cause: restoreError },
          );
        }
      }
      throw error;
    }
    if (backupCreated) {
      if (ownedParent) {
        await assertDirectoryIdentityStable(ownedParent, "Computer Use plugin cache parent");
      }
      await fs.rm(backupPath, { recursive: true, force: true });
    }
    return true;
  } finally {
    if (!ownedParent || (await directoryIdentityIsStable(ownedParent))) {
      await fs.rm(stagingRoot, { recursive: true, force: true });
    }
  }
}

function skippedCacheResult(
  status: "disabled" | "explicit_marketplace" | "independent" | "source_missing",
  message: string,
): CodexComputerUsePluginCacheRepairResult {
  return {
    status,
    changed: false,
    message,
    removedStaleVersions: [],
    warnings: status === "source_missing" ? [message] : [],
  };
}

// Codex tests cover periodic Computer Use health monitoring.
import { afterEach, describe, expect, it, vi } from "vitest";
import type { CodexAppServerClient } from "./client.js";
import { startCodexComputerUseHealthMonitor } from "./computer-use-health.js";
import type { ResolvedCodexComputerUseConfig } from "./config.js";

describe("Codex Computer Use periodic health", () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it("runs the live list_apps probe on the configured cadence and clears on client close", async () => {
    vi.useFakeTimers();
    const client = createClient();

    const result = startCodexComputerUseHealthMonitor({
      client: client.client,
      config: computerUseConfig({ healthCheckEnabled: true, healthCheckIntervalMinutes: 30 }),
    });

    expect(result).toEqual({ started: true, intervalMs: 30 * 60_000 });
    expect(client.request).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(30 * 60_000);

    expect(client.request).toHaveBeenCalledWith(
      "thread/start",
      {
        input: [],
        developerInstructions: "OpenClaw Computer Use readiness probe",
        ephemeral: true,
      },
      { timeoutMs: 60_000 },
    );
    expect(client.request).toHaveBeenCalledWith(
      "mcpServer/tool/call",
      {
        threadId: "health-probe-thread-1",
        server: "computer-use",
        tool: "list_apps",
        arguments: {},
      },
      { timeoutMs: 60_000 },
    );

    client.close();
    await vi.advanceTimersByTimeAsync(30 * 60_000);
    expect(
      client.request.mock.calls.filter(([method]) => method === "mcpServer/tool/call"),
    ).toHaveLength(1);
  });

  it("reloads the owner-managed MCP runtime and retries once after a failed probe", async () => {
    vi.useFakeTimers();
    const client = createClient({ liveTestFailures: 1 });

    startCodexComputerUseHealthMonitor({
      client: client.client,
      config: computerUseConfig({
        autoRepair: true,
        healthCheckEnabled: true,
        healthCheckIntervalMinutes: 30,
      }),
    });

    await vi.advanceTimersByTimeAsync(30 * 60_000);

    expect(
      client.request.mock.calls.filter(([method]) => method === "mcpServer/tool/call"),
    ).toHaveLength(2);
    expect(client.request).toHaveBeenCalledWith("config/mcpServer/reload", undefined, {
      timeoutMs: 60_000,
    });
  });

  it("stops an existing monitor when health checks are disabled", async () => {
    vi.useFakeTimers();
    const client = createClient();

    startCodexComputerUseHealthMonitor({
      client: client.client,
      config: computerUseConfig({ healthCheckEnabled: true, healthCheckIntervalMinutes: 30 }),
    });
    expect(
      startCodexComputerUseHealthMonitor({
        client: client.client,
        config: computerUseConfig({ healthCheckEnabled: false }),
      }),
    ).toEqual({ started: false, reason: "health_disabled" });

    await vi.advanceTimersByTimeAsync(30 * 60_000);
    expect(client.request).not.toHaveBeenCalled();
  });

  it("stops an existing monitor when Computer Use is disabled", async () => {
    vi.useFakeTimers();
    const client = createClient();

    startCodexComputerUseHealthMonitor({
      client: client.client,
      config: computerUseConfig({ healthCheckEnabled: true, healthCheckIntervalMinutes: 30 }),
    });
    expect(
      startCodexComputerUseHealthMonitor({
        client: client.client,
        config: computerUseConfig({ enabled: false, healthCheckEnabled: true }),
      }),
    ).toEqual({ started: false, reason: "disabled" });

    await vi.advanceTimersByTimeAsync(30 * 60_000);
    expect(client.request).not.toHaveBeenCalled();
  });

  it("replaces a same-interval monitor when probe configuration changes", async () => {
    vi.useFakeTimers();
    const client = createClient();

    startCodexComputerUseHealthMonitor({
      client: client.client,
      config: computerUseConfig({ healthCheckEnabled: true, healthCheckIntervalMinutes: 30 }),
    });
    expect(
      startCodexComputerUseHealthMonitor({
        client: client.client,
        config: computerUseConfig({
          healthCheckEnabled: true,
          healthCheckIntervalMinutes: 30,
          mcpServerName: "replacement-computer-use",
          toolCallTimeoutMs: 45_000,
        }),
      }),
    ).toEqual({ started: true, intervalMs: 30 * 60_000 });

    await vi.advanceTimersByTimeAsync(30 * 60_000);
    expect(client.request).toHaveBeenCalledWith(
      "mcpServer/tool/call",
      {
        threadId: "health-probe-thread-1",
        server: "replacement-computer-use",
        tool: "list_apps",
        arguments: {},
      },
      { timeoutMs: 45_000 },
    );
    expect(
      client.request.mock.calls.filter(([method]) => method === "mcpServer/tool/call"),
    ).toHaveLength(1);
  });

  it("does not start when Computer Use is disabled", () => {
    const client = createClient();

    expect(
      startCodexComputerUseHealthMonitor({
        client: client.client,
        config: computerUseConfig({ enabled: false }),
      }),
    ).toEqual({ started: false, reason: "disabled" });
    expect(client.addCloseHandler).not.toHaveBeenCalled();
  });

  it("does not start periodic health checks unless explicitly enabled", () => {
    const client = createClient();

    expect(
      startCodexComputerUseHealthMonitor({
        client: client.client,
        config: computerUseConfig(),
      }),
    ).toEqual({ started: false, reason: "health_disabled" });
    expect(client.addCloseHandler).not.toHaveBeenCalled();
  });
});

function createClient(options: { liveTestFailures?: number } = {}) {
  const closeHandlers = new Set<(client: CodexAppServerClient) => void>();
  let threadStarts = 0;
  let liveTestFailures = options.liveTestFailures ?? 0;
  const request = vi.fn(async (method: string, params?: unknown) => {
    if (method === "thread/start") {
      threadStarts += 1;
      return {
        thread: { id: `health-probe-thread-${threadStarts}` },
        model: "gpt-5.1",
        modelProvider: "openai",
      };
    }
    if (method === "mcpServer/tool/call") {
      if (liveTestFailures > 0) {
        liveTestFailures -= 1;
        throw new Error("hung");
      }
      return { content: [{ type: "text", text: "[]" }] };
    }
    if (method === "config/mcpServer/reload") {
      return undefined;
    }
    if (method === "thread/unsubscribe" || method === "thread/archive") {
      expect(params).toEqual({ threadId: `health-probe-thread-${threadStarts}` });
      return undefined;
    }
    throw new Error(`unexpected request ${method}`);
  });
  const addCloseHandler = vi.fn((handler: (client: CodexAppServerClient) => void) => {
    closeHandlers.add(handler);
    return () => closeHandlers.delete(handler);
  });
  const client = {
    request,
    addCloseHandler,
  } as unknown as CodexAppServerClient;
  return {
    client,
    request,
    addCloseHandler,
    close: () => {
      for (const handler of closeHandlers) {
        handler(client);
      }
    },
  };
}

function computerUseConfig(
  overrides: Partial<ResolvedCodexComputerUseConfig> = {},
): ResolvedCodexComputerUseConfig {
  return {
    enabled: true,
    autoInstall: true,
    marketplaceDiscoveryTimeoutMs: 60_000,
    liveTestTimeoutMs: 60_000,
    toolCallTimeoutMs: 60_000,
    healthCheckEnabled: false,
    healthCheckIntervalMinutes: 60,
    pluginCacheMode: "shared",
    strictReadiness: false,
    autoRepair: false,
    pluginName: "computer-use",
    mcpServerName: "computer-use",
    ...overrides,
  };
}

// Codex plugin module implements periodic Computer Use health probes.
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { CodexAppServerClient } from "./client.js";
import { runCodexComputerUseLiveTest } from "./computer-use.js";
import type { ResolvedCodexComputerUseConfig } from "./config.js";

type ComputerUseHealthMonitor = {
  fingerprint: string;
  intervalMs: number;
  timer: ReturnType<typeof setInterval>;
  disposeCloseHandler: () => void;
  running: boolean;
};

type ComputerUseHealthMonitorState = {
  monitors: WeakMap<CodexAppServerClient, ComputerUseHealthMonitor>;
};

const COMPUTER_USE_HEALTH_MONITOR_STATE = Symbol.for("openclaw.codexComputerUseHealthMonitorState");

function getComputerUseHealthMonitorState(): ComputerUseHealthMonitorState {
  const globalState = globalThis as typeof globalThis & {
    [COMPUTER_USE_HEALTH_MONITOR_STATE]?: ComputerUseHealthMonitorState;
  };
  globalState[COMPUTER_USE_HEALTH_MONITOR_STATE] ??= {
    monitors: new WeakMap(),
  };
  return globalState[COMPUTER_USE_HEALTH_MONITOR_STATE];
}

export function startCodexComputerUseHealthMonitor(params: {
  client: CodexAppServerClient;
  config: ResolvedCodexComputerUseConfig;
}): { started: boolean; intervalMs?: number; reason?: string } {
  const state = getComputerUseHealthMonitorState();
  const existing = state.monitors.get(params.client);
  if (!params.config.enabled || !params.config.healthCheckEnabled) {
    if (existing) {
      clearComputerUseHealthMonitor(params.client, existing);
    }
    return {
      started: false,
      reason: params.config.enabled ? "health_disabled" : "disabled",
    };
  }
  const fingerprint = buildComputerUseHealthMonitorFingerprint(params.config);
  const intervalMs = params.config.healthCheckIntervalMinutes * 60_000;
  if (existing?.fingerprint === fingerprint) {
    return { started: false, intervalMs, reason: "already_started" };
  }
  if (existing) {
    clearComputerUseHealthMonitor(params.client, existing);
  }
  const monitor: ComputerUseHealthMonitor = {
    fingerprint,
    intervalMs,
    timer: setInterval(() => {
      void runCodexComputerUseHealthProbe(params.client, params.config, monitor);
    }, intervalMs),
    disposeCloseHandler: () => undefined,
    running: false,
  };
  monitor.timer.unref?.();
  monitor.disposeCloseHandler = params.client.addCloseHandler((client) => {
    const active = state.monitors.get(client);
    if (active) {
      clearComputerUseHealthMonitor(client, active);
    }
  });
  state.monitors.set(params.client, monitor);
  return { started: true, intervalMs };
}

function buildComputerUseHealthMonitorFingerprint(config: ResolvedCodexComputerUseConfig): string {
  return JSON.stringify({
    autoRepair: config.autoRepair,
    healthCheckIntervalMinutes: config.healthCheckIntervalMinutes,
    liveTestTimeoutMs: config.liveTestTimeoutMs,
    mcpServerName: config.mcpServerName,
    toolCallTimeoutMs: config.toolCallTimeoutMs,
  });
}

async function runCodexComputerUseHealthProbe(
  client: CodexAppServerClient,
  config: ResolvedCodexComputerUseConfig,
  monitor: ComputerUseHealthMonitor,
): Promise<void> {
  if (monitor.running) {
    return;
  }
  monitor.running = true;
  try {
    const { liveTest, repair } = await runCodexComputerUseLiveTest({
      config,
      request: async <T>(
        method: string,
        requestParams?: unknown,
        requestOptions?: { timeoutMs?: number },
      ) =>
        await client.request<T>(method, requestParams, {
          timeoutMs: requestOptions?.timeoutMs ?? config.liveTestTimeoutMs,
        }),
    });
    if (!liveTest.ok) {
      embeddedAgentLog.warn("codex computer-use periodic health failed", {
        mcpServerName: config.mcpServerName,
        attempts: liveTest.attempts,
        timeoutMs: liveTest.timeoutMs,
        error: liveTest.error,
        repair,
      });
      return;
    }
    if (repair?.attempted && repair.warnings.length === 0) {
      embeddedAgentLog.info("codex computer-use periodic health reloaded MCP servers", {
        mcpServerName: config.mcpServerName,
      });
    }
  } catch (error) {
    embeddedAgentLog.warn("codex computer-use periodic health probe crashed", {
      mcpServerName: config.mcpServerName,
      error: error instanceof Error ? error.message : String(error),
    });
  } finally {
    monitor.running = false;
  }
}

function clearComputerUseHealthMonitor(
  client: CodexAppServerClient,
  monitor: ComputerUseHealthMonitor,
): void {
  clearInterval(monitor.timer);
  monitor.disposeCloseHandler();
  getComputerUseHealthMonitorState().monitors.delete(client);
}

import fs from "node:fs/promises";
import path from "node:path";
import { createDeferred } from "openclaw/plugin-sdk/extension-shared";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  ensureCodexManagedBundledMarketplace,
  resolveCodexManagedBundledMarketplacePath,
} from "./computer-use-marketplace.js";
import type { MacOSDesktopCodexAppPathCandidate } from "./desktop-app-paths.js";
import { useAutoCleanupTempDirTracker } from "./test-support.js";

describe("managed Codex bundled marketplace", () => {
  const tempDirs = useAutoCleanupTempDirTracker(afterEach);

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("publishes a real reserved root with links to the selected desktop marketplace", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-");
    const candidate = await writeCandidate(root);
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");

    const result = await ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      appServerCommand: candidate.appServerCommandPath,
      candidates: [candidate],
    });

    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    expect(result).toBe(target);
    expect((await fs.lstat(target)).isDirectory()).toBe(true);
    expect(await fs.realpath(target)).toBe(target);
    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(candidate.bundledMarketplacePath, "plugins"),
    );
    await expect(
      ensureCodexManagedBundledMarketplace({
        codexHome,
        ownershipRoot: agentDir,
        candidates: [candidate],
      }),
    ).resolves.toBe(target);
  });

  it("coalesces concurrent publication without leaving swap debris", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-concurrent-");
    const candidate = await writeCandidate(root);
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");

    const results = await Promise.all(
      Array.from({ length: 3 }, () =>
        ensureCodexManagedBundledMarketplace({
          codexHome,
          ownershipRoot: agentDir,
          candidates: [candidate],
        }),
      ),
    );

    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    expect(results).toEqual([target, target, target]);
    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(candidate.bundledMarketplacePath, "plugins"),
    );
    expect(
      (await fs.readdir(path.dirname(target))).filter((entry) =>
        entry.startsWith(".openai-bundled"),
      ),
    ).toEqual([]);
  });

  it("converges a concurrent replacement to the newly selected desktop source", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-transition-");
    const firstCandidate = await writeCandidate(path.join(root, "first"));
    const secondCandidate = await writeCandidate(path.join(root, "second"));
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");
    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    const firstPublishStarted = createDeferred<void>();
    const releaseFirstPublish = createDeferred<void>();
    const rename = fs.rename.bind(fs);
    let heldFirstPublish = false;
    vi.spyOn(fs, "rename").mockImplementation(async (source, destination) => {
      if (!heldFirstPublish && destination === target) {
        heldFirstPublish = true;
        firstPublishStarted.resolve();
        await releaseFirstPublish.promise;
      }
      return await rename(source, destination);
    });

    const first = ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      appServerCommand: firstCandidate.appServerCommandPath,
      candidates: [firstCandidate],
      ownershipCandidates: [firstCandidate, secondCandidate],
    });
    await firstPublishStarted.promise;
    const second = ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      appServerCommand: secondCandidate.appServerCommandPath,
      candidates: [secondCandidate],
      ownershipCandidates: [firstCandidate, secondCandidate],
    });
    releaseFirstPublish.resolve();

    await expect(Promise.all([first, second])).resolves.toEqual([target, target]);
    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(secondCandidate.bundledMarketplacePath, "plugins"),
    );
    expect(
      (await fs.readdir(path.dirname(target))).filter((entry) =>
        entry.startsWith(".openai-bundled"),
      ),
    ).toEqual([]);
  });

  it("does not let a matching fast path outrun a conflicting publication", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-conflict-");
    const firstCandidate = await writeCandidate(path.join(root, "first"));
    const secondCandidate = await writeCandidate(path.join(root, "second"));
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");
    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    const ownershipCandidates = [firstCandidate, secondCandidate];
    await ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      candidates: [secondCandidate],
      ownershipCandidates,
    });

    const firstStagingStarted = createDeferred<void>();
    const releaseFirstStaging = createDeferred<void>();
    const createStagingDir = fs.mkdtemp.bind(fs);
    vi.spyOn(fs, "mkdtemp").mockImplementationOnce(async (prefix, options) => {
      firstStagingStarted.resolve();
      await releaseFirstStaging.promise;
      return await createStagingDir(prefix, options);
    });
    const first = ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      candidates: [firstCandidate],
      ownershipCandidates,
    });
    await firstStagingStarted.promise;
    const lstat = fs.lstat.bind(fs);
    let firstReleased = false;
    let targetChecksBeforeRelease = 0;
    vi.spyOn(fs, "lstat").mockImplementation(async (filePath, options) => {
      if (path.resolve(String(filePath)) === target && !firstReleased) {
        targetChecksBeforeRelease += 1;
        if (targetChecksBeforeRelease > 1) {
          throw new Error("conflicting wrapper fast path ran before active publication settled");
        }
        setImmediate(() => {
          firstReleased = true;
          releaseFirstStaging.resolve();
        });
      }
      return await lstat(filePath, options);
    });
    const second = ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      candidates: [secondCandidate],
      ownershipCandidates,
    });
    const results = await Promise.allSettled([first, second]);

    expect(targetChecksBeforeRelease).toBe(1);
    expect(results).toEqual([
      { status: "fulfilled", value: target },
      { status: "fulfilled", value: target },
    ]);
    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(secondCandidate.bundledMarketplacePath, "plugins"),
    );
  });

  it("replaces a prior owned wrapper when desktop app selection changes", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-owner-transition-");
    const firstCandidate = await writeCandidate(path.join(root, "first"));
    const secondCandidate = await writeCandidate(path.join(root, "second"));
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");
    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    const ownershipCandidates = [firstCandidate, secondCandidate];

    await ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      appServerCommand: firstCandidate.appServerCommandPath,
      candidates: [firstCandidate],
      ownershipCandidates,
    });
    await ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      appServerCommand: secondCandidate.appServerCommandPath,
      candidates: [secondCandidate],
      ownershipCandidates,
    });

    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(secondCandidate.bundledMarketplacePath, "plugins"),
    );
  });

  it("leaves the prior wrapper intact when its generation becomes stale before publication", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-stale-");
    const firstCandidate = await writeCandidate(path.join(root, "first"));
    const secondCandidate = await writeCandidate(path.join(root, "second"));
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");
    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    const ownershipCandidates = [firstCandidate, secondCandidate];
    await ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      candidates: [firstCandidate],
      ownershipCandidates,
    });

    let currentnessChecks = 0;
    await expect(
      ensureCodexManagedBundledMarketplace({
        codexHome,
        ownershipRoot: agentDir,
        candidates: [secondCandidate],
        ownershipCandidates,
        assertCurrent: () => {
          currentnessChecks += 1;
          if (currentnessChecks === 2) {
            throw new Error("desktop generation is stale");
          }
        },
      }),
    ).rejects.toThrow("desktop generation is stale");
    expect(currentnessChecks).toBe(2);

    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(firstCandidate.bundledMarketplacePath, "plugins"),
    );
    expect(
      (await fs.readdir(path.dirname(target))).filter((entry) =>
        entry.startsWith(".openai-bundled"),
      ),
    ).toEqual([]);
  });

  it("does not replace an unowned directory at the reserved managed path", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-unowned-");
    const candidate = await writeCandidate(root);
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");
    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    await fs.mkdir(target, { recursive: true });
    await fs.writeFile(path.join(target, "sentinel"), "operator-owned");

    await expect(
      ensureCodexManagedBundledMarketplace({
        codexHome,
        ownershipRoot: agentDir,
        candidates: [candidate],
      }),
    ).rejects.toThrow("unowned bundled marketplace");
    await expect(fs.readFile(path.join(target, "sentinel"), "utf8")).resolves.toBe(
      "operator-owned",
    );
  });

  it("restores the prior managed wrapper when publication fails after backup", async () => {
    const root = tempDirs.make("openclaw-codex-marketplace-rollback-");
    const firstCandidate = await writeCandidate(path.join(root, "first"));
    const secondCandidate = await writeCandidate(path.join(root, "second"));
    const agentDir = path.join(root, "agent");
    const codexHome = path.join(agentDir, "codex-home");
    const target = resolveCodexManagedBundledMarketplacePath(codexHome);
    await ensureCodexManagedBundledMarketplace({
      codexHome,
      ownershipRoot: agentDir,
      appServerCommand: firstCandidate.appServerCommandPath,
      candidates: [firstCandidate, secondCandidate],
    });
    const rename = fs.rename.bind(fs);
    let renameCount = 0;
    vi.spyOn(fs, "rename").mockImplementation(async (source, destination) => {
      renameCount += 1;
      if (renameCount === 2) {
        throw new Error("injected publish failure");
      }
      return await rename(source, destination);
    });

    await expect(
      ensureCodexManagedBundledMarketplace({
        codexHome,
        ownershipRoot: agentDir,
        appServerCommand: secondCandidate.appServerCommandPath,
        candidates: [firstCandidate, secondCandidate],
      }),
    ).rejects.toThrow("injected publish failure");

    expect(await fs.readlink(path.join(target, "plugins"))).toBe(
      path.join(firstCandidate.bundledMarketplacePath, "plugins"),
    );
    expect(
      (await fs.readdir(path.dirname(target))).filter((entry) =>
        entry.startsWith(".openai-bundled"),
      ),
    ).toEqual([]);
  });

  it.runIf(process.platform !== "win32")(
    "rejects a symlinked isolated home without touching its external target",
    async () => {
      const root = tempDirs.make("openclaw-codex-marketplace-home-link-");
      const candidate = await writeCandidate(root);
      const agentDir = path.join(root, "agent");
      const external = path.join(root, "external");
      const codexHome = path.join(agentDir, "codex-home");
      await fs.mkdir(agentDir, { recursive: true });
      await fs.mkdir(external, { recursive: true });
      await fs.writeFile(path.join(external, "sentinel"), "outside");
      await fs.symlink(external, codexHome, "dir");

      await expect(
        ensureCodexManagedBundledMarketplace({
          codexHome,
          ownershipRoot: agentDir,
          candidates: [candidate],
        }),
      ).rejects.toThrow(/symlink|symbolic link|real directories/u);
      await expect(fs.readFile(path.join(external, "sentinel"), "utf8")).resolves.toBe("outside");
      await expect(fs.access(path.join(external, ".tmp"))).rejects.toThrow();
    },
  );

  it.runIf(process.platform !== "win32")(
    "does not publish through a marketplace parent rebound during the staged swap",
    async () => {
      const root = tempDirs.make("openclaw-codex-marketplace-rebind-");
      const candidate = await writeCandidate(root);
      const agentDir = path.join(root, "agent");
      const codexHome = path.join(agentDir, "codex-home");
      const target = resolveCodexManagedBundledMarketplacePath(codexHome);
      const parent = path.dirname(target);
      const movedParent = `${parent}.moved`;
      const external = path.join(root, "external");
      await fs.mkdir(external, { recursive: true });
      await fs.writeFile(path.join(external, "sentinel"), "outside");
      const rename = fs.rename.bind(fs);
      vi.spyOn(fs, "rename").mockImplementationOnce(async (source, destination) => {
        await rename(parent, movedParent);
        await fs.symlink(external, parent, "dir");
        return await rename(source, destination);
      });

      await expect(
        ensureCodexManagedBundledMarketplace({
          codexHome,
          ownershipRoot: agentDir,
          candidates: [candidate],
        }),
      ).rejects.toThrow();
      await expect(fs.readFile(path.join(external, "sentinel"), "utf8")).resolves.toBe("outside");
      await expect(fs.access(path.join(external, "openai-bundled"))).rejects.toThrow();
    },
  );
});

async function writeCandidate(root: string): Promise<MacOSDesktopCodexAppPathCandidate> {
  const appBundlePath = path.join(root, "ChatGPT.app");
  const bundledMarketplacePath = path.join(appBundlePath, "openai-bundled");
  await fs.mkdir(path.join(bundledMarketplacePath, ".agents", "plugins"), { recursive: true });
  await fs.mkdir(path.join(bundledMarketplacePath, "plugins", "computer-use", ".codex-plugin"), {
    recursive: true,
  });
  await fs.writeFile(
    path.join(bundledMarketplacePath, ".agents", "plugins", "marketplace.json"),
    JSON.stringify({ name: "openai-bundled", plugins: [{ name: "computer-use" }] }),
  );
  await fs.writeFile(
    path.join(bundledMarketplacePath, "plugins", "computer-use", ".codex-plugin", "plugin.json"),
    JSON.stringify({ name: "computer-use", version: "1.0.0" }),
  );
  return {
    appName: "ChatGPT.app",
    appBundlePath,
    appServerCommandPath: path.join(appBundlePath, "codex"),
    bundledMarketplacePath,
    computerUseServiceAppPaths: [],
  };
}

/** Managed local wrapper for Codex's reserved bundled marketplace. */
import fs from "node:fs/promises";
import path from "node:path";
import { isRecord } from "openclaw/plugin-sdk/string-coerce-runtime";
import {
  assertDirectoryIdentityStable,
  assertNotSymlink,
  directoryIdentityIsStable,
  prepareOwnedServiceParent,
} from "./computer-use-service-path.js";
import {
  resolveMacOSDesktopCodexAppPathCandidates,
  type MacOSDesktopCodexAppPathCandidate,
} from "./desktop-app-paths.js";

const MARKETPLACE_NAME = "openai-bundled";
const activeInstalls = new Map<
  string,
  { sourcePath: string; promise: Promise<string | undefined> }
>();

export function resolveCodexManagedBundledMarketplacePath(codexHome: string): string {
  return path.join(codexHome, ".tmp", "bundled-marketplaces", MARKETPLACE_NAME);
}

export async function ensureCodexManagedBundledMarketplace(params: {
  codexHome: string;
  ownershipRoot: string;
  appServerCommand?: string;
  candidates?: readonly MacOSDesktopCodexAppPathCandidate[];
  ownershipCandidates?: readonly MacOSDesktopCodexAppPathCandidate[];
  assertCurrent?: () => void;
}): Promise<string | undefined> {
  const candidates = params.candidates ?? resolveMacOSDesktopCodexAppPathCandidates();
  const source = await resolveCodexManagedBundledMarketplaceSource({ ...params, candidates });
  if (!source) {
    return undefined;
  }
  const parentPath = path.dirname(resolveCodexManagedBundledMarketplacePath(params.codexHome));
  const targetPath = path.join(parentPath, MARKETPLACE_NAME);
  const parent = await prepareOwnedServiceParent({
    ownershipRoot: params.ownershipRoot,
    codexHome: params.codexHome,
    targetParent: parentPath,
  });
  const physicalTargetPath = path.join(parent.realPath, MARKETPLACE_NAME);
  await assertNotSymlink(physicalTargetPath, "managed bundled marketplace");
  const active = activeInstalls.get(physicalTargetPath);
  if (active) {
    if (active.sourcePath === source.bundledMarketplacePath) {
      return await active.promise;
    }
    await active.promise.catch(() => undefined);
    return await ensureCodexManagedBundledMarketplace(params);
  }
  const install = reconcileManagedWrapper({
    parent,
    physicalTargetPath,
    targetPath,
    source,
    ownershipCandidates: params.ownershipCandidates ?? candidates,
    assertCurrent: params.assertCurrent,
  });
  const activeEntry = { sourcePath: source.bundledMarketplacePath, promise: install };
  activeInstalls.set(physicalTargetPath, activeEntry);
  const clearActive = () => {
    if (activeInstalls.get(physicalTargetPath) === activeEntry) {
      activeInstalls.delete(physicalTargetPath);
    }
  };
  void install.then(clearActive, clearActive);
  return await install;
}

async function reconcileManagedWrapper(
  params: Parameters<typeof publishManagedWrapper>[0],
): Promise<string> {
  if (await wrapperMatches(params.physicalTargetPath, params.source.bundledMarketplacePath)) {
    return params.targetPath;
  }
  return await publishManagedWrapper(params);
}

async function publishManagedWrapper(params: {
  parent: Awaited<ReturnType<typeof prepareOwnedServiceParent>>;
  physicalTargetPath: string;
  targetPath: string;
  source: MacOSDesktopCodexAppPathCandidate;
  ownershipCandidates: readonly MacOSDesktopCodexAppPathCandidate[];
  assertCurrent?: () => void;
}): Promise<string> {
  const { parent, physicalTargetPath, targetPath, source, ownershipCandidates, assertCurrent } =
    params;

  const stagingPath = await fs.mkdtemp(path.join(parent.realPath, `.${MARKETPLACE_NAME}.staging-`));
  const backupPath = path.join(
    parent.realPath,
    `.${MARKETPLACE_NAME}.backup-${process.pid}-${Date.now()}`,
  );
  let backupCreated = false;
  try {
    const manifestParent = path.join(stagingPath, ".agents", "plugins");
    await fs.mkdir(manifestParent, { recursive: true, mode: 0o700 });
    await Promise.all([
      fs.symlink(
        path.join(source.bundledMarketplacePath, ".agents", "plugins", "marketplace.json"),
        path.join(manifestParent, "marketplace.json"),
      ),
      fs.symlink(
        path.join(source.bundledMarketplacePath, "plugins"),
        path.join(stagingPath, "plugins"),
      ),
    ]);
    await assertDirectoryIdentityStable(parent, "managed bundled marketplace parent");
    const existing = await fs.lstat(physicalTargetPath).catch((error: unknown) => {
      if (hasNodeErrorCode(error, "ENOENT")) {
        return undefined;
      }
      throw error;
    });
    if (existing && !existing.isDirectory()) {
      throw new Error(`Managed bundled marketplace must be a real directory: ${targetPath}`);
    }
    if (existing && !(await wrapperMatchesAnySource(physicalTargetPath, ownershipCandidates))) {
      throw new Error(
        `Refusing to replace an unowned bundled marketplace directory: ${targetPath}`,
      );
    }
    if (existing) {
      assertCurrent?.();
      await fs.rename(physicalTargetPath, backupPath);
      backupCreated = true;
      await assertDirectoryIdentityStable(parent, "managed bundled marketplace parent");
    }
    assertCurrent?.();
    await fs.rename(stagingPath, physicalTargetPath);
    await assertDirectoryIdentityStable(parent, "managed bundled marketplace parent");
    if (backupCreated) {
      await fs.rm(backupPath, { recursive: true });
      backupCreated = false;
    }
    return targetPath;
  } catch (error) {
    if (backupCreated) {
      try {
        await assertDirectoryIdentityStable(parent, "managed bundled marketplace parent");
        const replacement = await fs.lstat(physicalTargetPath).catch(() => undefined);
        if (replacement) {
          if (!(await wrapperMatches(physicalTargetPath, source.bundledMarketplacePath))) {
            throw new Error("managed bundled marketplace replacement is no longer owned", {
              cause: error,
            });
          }
          await fs.rm(physicalTargetPath, { recursive: true });
        }
        await fs.rename(backupPath, physicalTargetPath);
        backupCreated = false;
      } catch (restoreError) {
        throw new Error(
          `Failed to restore the prior managed bundled marketplace: ${String(error)}`,
          {
            cause: restoreError,
          },
        );
      }
    }
    throw error;
  } finally {
    if (await directoryIdentityIsStable(parent)) {
      await fs.rm(stagingPath, { recursive: true, force: true });
    }
  }
}

export async function resolveCodexManagedBundledMarketplaceSource(params: {
  appServerCommand?: string;
  candidates?: readonly MacOSDesktopCodexAppPathCandidate[];
}): Promise<MacOSDesktopCodexAppPathCandidate | undefined> {
  const candidates = params.candidates ?? resolveMacOSDesktopCodexAppPathCandidates();
  const command = params.appServerCommand && path.resolve(params.appServerCommand);
  const ordered = command
    ? candidates.filter((candidate) => path.resolve(candidate.appServerCommandPath) === command)
    : candidates;
  for (const candidate of ordered) {
    if (await isExpectedMarketplace(candidate.bundledMarketplacePath)) {
      return candidate;
    }
  }
  return undefined;
}

async function isExpectedMarketplace(root: string): Promise<boolean> {
  try {
    const manifest: unknown = JSON.parse(
      await fs.readFile(path.join(root, ".agents", "plugins", "marketplace.json"), "utf8"),
    );
    await fs.access(path.join(root, "plugins", "computer-use", ".codex-plugin", "plugin.json"));
    return (
      isRecord(manifest) &&
      manifest.name === MARKETPLACE_NAME &&
      Array.isArray(manifest.plugins) &&
      manifest.plugins.some((plugin) => isRecord(plugin) && plugin.name === "computer-use")
    );
  } catch {
    return false;
  }
}

async function wrapperMatches(targetPath: string, sourcePath: string): Promise<boolean> {
  try {
    const target = await fs.lstat(targetPath);
    if (!target.isDirectory() || target.isSymbolicLink()) {
      return false;
    }
    const [manifest, plugins] = await Promise.all([
      fs.readlink(path.join(targetPath, ".agents", "plugins", "marketplace.json")),
      fs.readlink(path.join(targetPath, "plugins")),
    ]);
    return (
      manifest === path.join(sourcePath, ".agents", "plugins", "marketplace.json") &&
      plugins === path.join(sourcePath, "plugins")
    );
  } catch {
    return false;
  }
}

async function wrapperMatchesAnySource(
  targetPath: string,
  candidates: readonly MacOSDesktopCodexAppPathCandidate[],
): Promise<boolean> {
  for (const candidate of candidates) {
    if (await wrapperMatches(targetPath, candidate.bundledMarketplacePath)) {
      return true;
    }
  }
  return false;
}

function hasNodeErrorCode(error: unknown, code: string): error is NodeJS.ErrnoException {
  return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

/** Filesystem ownership guards for isolated Computer Use service provisioning. */
import fs from "node:fs/promises";
import path from "node:path";
import { assertNoSymlinkParents } from "openclaw/plugin-sdk/security-runtime";

type OwnedServiceParent = {
  logicalPath: string;
  realPath: string;
  dev: number;
  ino: number;
};

export async function assertOwnedServicePath(params: {
  ownershipRoot: string;
  codexHome: string;
  targetParent: string;
  targetPath: string;
}): Promise<void> {
  await assertOwnedCodexHomePath({
    ownershipRoot: params.ownershipRoot,
    codexHome: params.codexHome,
    allowMissing: true,
  });
  assertPathAtOrInside(params.ownershipRoot, params.targetParent, "Computer Use service parent");
  await assertNoSymlinkParents({
    rootDir: params.ownershipRoot,
    targetPath: params.targetParent,
    allowMissing: true,
    requireDirectories: true,
    messagePrefix: "Computer Use service path",
  });
  await assertNotSymlink(params.targetPath, "Computer Use service target");
}

export async function ensureOwnedCodexHome(
  codexHomeInput: string,
  ownershipRootInput = path.dirname(path.resolve(codexHomeInput)),
): Promise<void> {
  const codexHome = path.resolve(codexHomeInput);
  const ownershipRoot = path.resolve(ownershipRootInput);
  await fs.mkdir(ownershipRoot, { recursive: true, mode: 0o700 });
  await assertOwnedCodexHomePath({ ownershipRoot, codexHome, allowMissing: true });
  await ensureRealDirectoryTree(ownershipRoot, codexHome, "isolated Codex home");
  await assertOwnedCodexHomePath({ ownershipRoot, codexHome, allowMissing: false });
}

export async function prepareOwnedServiceParent(params: {
  ownershipRoot: string;
  codexHome: string;
  targetParent: string;
}): Promise<OwnedServiceParent> {
  await ensureOwnedCodexHome(params.codexHome, params.ownershipRoot);
  await ensureRealDirectoryTree(
    params.ownershipRoot,
    params.targetParent,
    "Computer Use service parent",
  );
  await assertNoSymlinkParents({
    rootDir: params.ownershipRoot,
    targetPath: params.targetParent,
    allowMissing: false,
    requireDirectories: true,
    messagePrefix: "Computer Use service path",
  });
  const [rootIdentity, parentIdentity] = await Promise.all([
    readRealDirectoryIdentity(params.ownershipRoot, "Computer Use ownership root"),
    readRealDirectoryIdentity(params.targetParent, "Computer Use service parent"),
  ]);
  assertPathAtOrInside(
    rootIdentity.realPath,
    parentIdentity.realPath,
    "canonical Computer Use service parent",
  );
  return parentIdentity;
}

async function assertOwnedCodexHomePath(params: {
  ownershipRoot: string;
  codexHome: string;
  allowMissing: boolean;
}): Promise<void> {
  await readRealDirectoryIdentity(params.ownershipRoot, "Computer Use ownership root");
  assertPathAtOrInside(params.ownershipRoot, params.codexHome, "isolated Codex home");
  await assertNoSymlinkParents({
    rootDir: params.ownershipRoot,
    targetPath: params.codexHome,
    allowMissing: params.allowMissing,
    requireDirectories: true,
    messagePrefix: "Computer Use service path",
  });
}

export async function readRealDirectoryIdentity(
  directoryPath: string,
  label: string,
): Promise<OwnedServiceParent> {
  const logicalPath = path.resolve(directoryPath);
  const before = await fs.lstat(logicalPath);
  if (before.isSymbolicLink() || !before.isDirectory()) {
    throw new Error(`${label} must be a real directory: ${logicalPath}`);
  }
  const realPath = await fs.realpath(logicalPath);
  const [after, resolved] = await Promise.all([fs.lstat(logicalPath), fs.lstat(realPath)]);
  if (
    after.isSymbolicLink() ||
    !after.isDirectory() ||
    !resolved.isDirectory() ||
    before.dev !== after.dev ||
    before.ino !== after.ino ||
    after.dev !== resolved.dev ||
    after.ino !== resolved.ino
  ) {
    throw new Error(`${label} changed while its ownership boundary was being established.`);
  }
  return { logicalPath, realPath, dev: after.dev, ino: after.ino };
}

export async function assertOwnedServiceParentStable(parent: OwnedServiceParent): Promise<void> {
  await assertDirectoryIdentityStable(parent, "Computer Use service parent");
}

export async function assertDirectoryIdentityStable(
  expected: OwnedServiceParent,
  label: string,
): Promise<void> {
  if (!(await directoryIdentityIsStable(expected))) {
    throw new Error(`${label} changed during refresh; refusing to mutate the replacement path.`);
  }
}

export async function ownedServiceParentIsStable(parent: OwnedServiceParent): Promise<boolean> {
  return await directoryIdentityIsStable(parent);
}

export async function directoryIdentityIsStable(expected: OwnedServiceParent): Promise<boolean> {
  try {
    const current = await fs.lstat(expected.logicalPath);
    if (
      current.isSymbolicLink() ||
      !current.isDirectory() ||
      current.dev !== expected.dev ||
      current.ino !== expected.ino
    ) {
      return false;
    }
    return (await fs.realpath(expected.logicalPath)) === expected.realPath;
  } catch {
    return false;
  }
}

export async function assertNotSymlink(filePath: string, label: string): Promise<void> {
  try {
    if ((await fs.lstat(filePath)).isSymbolicLink()) {
      throw new Error(`${label} must not be a symbolic link: ${filePath}`);
    }
  } catch (error) {
    if (hasNodeErrorCode(error, "ENOENT")) {
      return;
    }
    throw error;
  }
}

async function ensureRealDirectoryTree(
  ownershipRoot: string,
  directoryPath: string,
  label: string,
): Promise<void> {
  const root = path.resolve(ownershipRoot);
  const target = path.resolve(directoryPath);
  assertPathAtOrInside(root, target, label);
  const relative = path.relative(root, target);
  let current = root;
  for (const segment of relative.split(path.sep).filter(Boolean)) {
    current = path.join(current, segment);
    const existing = await fs.lstat(current).catch((error: unknown) => {
      if (hasNodeErrorCode(error, "ENOENT")) {
        return undefined;
      }
      throw error;
    });
    if (!existing) {
      try {
        await fs.mkdir(current, { mode: 0o700 });
      } catch (error) {
        if (!hasNodeErrorCode(error, "EEXIST")) {
          throw error;
        }
      }
      const created = await fs.lstat(current);
      if (created.isSymbolicLink() || !created.isDirectory()) {
        throw new Error(`${label} changed while its directory tree was being created: ${current}`);
      }
    } else if (existing.isSymbolicLink() || !existing.isDirectory()) {
      throw new Error(`${label} must traverse real directories: ${current}`);
    }
  }
  await assertNoSymlinkParents({
    rootDir: root,
    targetPath: target,
    allowMissing: false,
    requireDirectories: true,
    messagePrefix: "Computer Use service path",
  });
  await readRealDirectoryIdentity(target, label);
}

function assertPathAtOrInside(rootPath: string, candidatePath: string, label: string): void {
  const relative = path.relative(path.resolve(rootPath), path.resolve(candidatePath));
  if (relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
    throw new Error(`${label} must remain inside ${path.resolve(rootPath)}.`);
  }
}

function hasNodeErrorCode(error: unknown, code: string): error is NodeJS.ErrnoException {
  return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

