import {
  embeddedAgentLog,
  formatErrorMessage,
  type EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import {
  appendSessionTranscriptMessageByIdentity,
  publishSessionTranscriptUpdateByIdentity,
} from "openclaw/plugin-sdk/session-transcript-runtime";

const CONTEXT_COMPACTION_CUSTOM_TYPE = "openclaw.context-compaction";

export async function persistCodexContextCompactionActivity(params: {
  sessionTarget?: EmbeddedRunAttemptParams["sessionTarget"];
  config?: EmbeddedRunAttemptParams["config"];
  cwd?: string;
  runId?: string;
  threadId: string;
  turnId: string;
  itemId: string;
  timestamp: number;
}): Promise<void> {
  const target = params.sessionTarget;
  if (!target?.sessionId || !target.sessionKey || !target.storePath) {
    return;
  }
  const activityId = `codex-context-compaction:${params.threadId}:${params.turnId}:${params.itemId}`;
  const message = {
    role: "custom" as const,
    customType: CONTEXT_COMPACTION_CUSTOM_TYPE,
    content: "Context compacted",
    display: true,
    excludeFromContext: true,
    details: {
      kind: "context_compaction",
      backend: "codex-app-server",
      threadId: params.threadId,
      turnId: params.turnId,
      itemId: params.itemId,
      ...(params.runId ? { runId: params.runId } : {}),
    },
    ...(params.runId ? { __openclaw: { runId: params.runId } } : {}),
    timestamp: params.timestamp,
    idempotencyKey: activityId,
  };
  try {
    const appended = await appendSessionTranscriptMessageByIdentity({
      agentId: target.agentId,
      sessionId: target.sessionId,
      sessionKey: target.sessionKey,
      storePath: target.storePath,
      config: params.config,
      cwd: params.cwd,
      eventId: activityId,
      message,
    });
    if (!appended?.appended) {
      return;
    }
    await publishSessionTranscriptUpdateByIdentity({
      agentId: target.agentId,
      sessionId: target.sessionId,
      sessionKey: target.sessionKey,
      storePath: target.storePath,
      update: {
        message: appended.message,
        messageId: appended.messageId,
        ...(params.runId ? { runId: params.runId } : {}),
      },
    });
  } catch (error) {
    embeddedAgentLog.warn("failed to persist codex context compaction activity", {
      error: formatErrorMessage(error),
      itemId: params.itemId,
    });
  }
}

// Codex tests cover context engine projection plugin behavior.
import { buildSessionContext, type AgentMessage } from "openclaw/plugin-sdk/agent-core";
import { describe, expect, it } from "vitest";
import {
  buildCodexContinuityCalibration,
  fitCodexProjectedContextForTurnStart,
  projectContextEngineAssemblyForCodex,
