type CodexDynamicToolHookContext = NonNullable<
  Parameters<typeof wrapToolWithBeforeToolCallHook>[1]
> & {
  remoteWorkspaceRoot?: string;
  remoteWorkspaceRequestTimeoutMs?: number;
  currentChannelProvider?: string;
