type AgentEvent = Parameters<NonNullable<EmbeddedRunAttemptParams["onAgentEvent"]>>[0];

/** Downstream event consumers must never corrupt the canonical Codex turn projection. */
export function emitCodexAgentEvent(params: EmbeddedRunAttemptParams, event: AgentEvent): void {
  try {
    emitGlobalAgentEvent({
      runId: params.runId,
      stream: event.stream,
      data: event.data,
      ...(params.sessionKey ? { sessionKey: params.sessionKey } : {}),
    });
  } catch (error) {
    embeddedAgentLog.debug("codex app-server global agent event emit failed", { error });
  }
  try {
    const maybePromise = params.onAgentEvent?.(event);
    void Promise.resolve(maybePromise).catch((error: unknown) => {
      embeddedAgentLog.debug("codex app-server agent event handler rejected", { error });
    });
  } catch (error) {
    embeddedAgentLog.debug("codex app-server agent event handler threw", { error });
  }
}

type NormalizedToolItemProjection = {
  name: string;
  status: ReturnType<typeof itemStatus>;
  args: Record<string, unknown> | undefined;
  meta: string | undefined;
  event: AgentEvent | undefined;
};

function guardianActionCommand(action: JsonObject | undefined): string | undefined {
  if (!action) {
    return undefined;
  }
  const directLabel =
    readString(action, "command") ??
    readString(action, "target") ??
    readString(action, "toolTitle") ??
    readString(action, "reason");
  if (directLabel) {
    return directLabel;
  }
  const server = readString(action, "connectorName") ?? readString(action, "server");
  const tool = readString(action, "toolName");
  if (server && tool) {
    return `${server}/${tool}`;
  }
  const argv = Array.isArray(action.argv)
    ? action.argv.filter((value): value is string => typeof value === "string")
    : [];
  return argv.length > 0 ? argv.join(" ") : readString(action, "program");
}

function normalizeApprovalReviewStatus(status: string | undefined): string | undefined {
  return status === "inProgress" ? "in_progress" : status === "timedOut" ? "timed_out" : status;
}

const GUARDIAN_TIMEOUT_WARNING =
  "Automatic approval review timed out while evaluating the requested approval.";

// These routine Codex diagnostics lack structured codes. Match complete templates so only
// host-managed notices stay log-only and other actionable warnings still reach chat.
const LOG_ONLY_CODEX_WARNING_PATTERNS = [
  /^Configured service tier `[^`\r\n]+` is not advertised as supported for model `[^`\r\n]+` and will be omitted from requests\.$/,
  /^Code Mode is enabled in configuration, but model `[^`\r\n]+` does not advertise Code Mode support\. This may degrade model performance\. Disable `features\.code_mode` and `features\.code_mode_only`, or select a model whose metadata enables Code Mode\.$/,
];

export function projectNormalizedToolItem(params: {
  phase: "start" | "result";
  item: CodexThreadItem | undefined;
  detailMode?: ToolProgressDetailMode;
}): NormalizedToolItemProjection | undefined {
  const { item } = params;
  if (!item || !shouldSynthesizeToolProgressForItem(item)) {
    return undefined;
  }
  const name = itemName(item);
  if (!name) {
    return undefined;
  }
  const status = params.phase === "result" ? itemStatus(item) : "running";
  const args = itemToolArgs(item);
  const commandBearing = isCommandBearingToolItem(item, args);
  const meta = itemMeta(item, params.detailMode);
  const event = shouldEmitTranscriptToolProgress(name, args)
    ? {
        stream: "tool",
        data: {
          phase: params.phase,
          name,
          itemId: item.id,
          toolCallId: item.id,
          ...(meta ? { meta } : {}),
          ...(commandBearing ? { commandBearing: true as const } : {}),
          ...(params.phase === "start" && args ? { args } : {}),
          ...(params.phase === "result"
            ? {
                status,
                isError: isNonSuccessItemStatus(status),
                ...itemToolResult(item),
              }
            : {}),
        },
      }
    : undefined;
  return { name, status, args, meta, event };
}

export class CodexEventProjection {
  private reviewCount = 0;
  private pendingGuardianWarning: string | undefined;
  private activeGuardianReview:
    | {
        reviewId?: string;
        targetItemId?: string | null;
        command?: string;
        threadId: string;
        turnId: string;
      }
    | undefined;

  constructor(
    private readonly threadId: string,
    private readonly turnId: string,
    private readonly emitAgentEvent: (event: AgentEvent) => void,
    private readonly toolProgress: CodexToolProgressProjection,
    private readonly toolTranscript: CodexToolTranscriptProjection,
    private readonly onNativeToolResultRecorded?: () => void | Promise<void>,
  ) {}

  get guardianReviewCount(): number {
    return this.reviewCount;
  }

  emitCompactionEnd(itemId: string, completed: boolean): void {
    this.emitAgentEvent({
      stream: "compaction",
      data: {
        phase: "end",
        backend: "codex-app-server",
        completed,
        threadId: this.threadId,
        turnId: this.turnId,
        itemId,
      },
    });
  }

  handleGuardianReview(method: string, params: JsonObject): void {
    this.reviewCount += 1;
    const review = isJsonObject(params.review) ? params.review : undefined;
    const action = isJsonObject(params.action) ? params.action : undefined;
    const reviewId = readString(params, "reviewId");
    const targetItemId = readNullableString(params, "targetItemId");
    const command = guardianActionCommand(action);
    const reviewStatus = review ? readString(review, "status") : undefined;
    const status = normalizeApprovalReviewStatus(reviewStatus);
    const riskLevel = review ? readString(review, "riskLevel") : undefined;
    const userAuthorization = review ? readString(review, "userAuthorization") : undefined;
    const rationale = review ? readNullableString(review, "rationale") : undefined;
    // Codex emits the routine warning immediately before its structured terminal fact.
    // Exact byte equality consumes only that duplicate; every other warning is flushed.
    const expectedWarning =
      status === "timed_out"
        ? GUARDIAN_TIMEOUT_WARNING
        : rationale &&
            riskLevel &&
            userAuthorization &&
            (status === "approved" || status === "denied")
          ? `Automatic approval review ${status} (risk: ${riskLevel}, authorization: ${userAuthorization}): ${rationale}`
          : undefined;
    const warningMatchesReview =
      Boolean(targetItemId) && Boolean(reviewId) && this.pendingGuardianWarning === expectedWarning;
    if (warningMatchesReview) {
      this.pendingGuardianWarning = undefined;
    } else {
      this.flushPendingGuardianWarning();
    }
    const threadId = readString(params, "threadId") ?? this.threadId;
    const turnId = readString(params, "turnId") ?? this.turnId;
    if (method.endsWith("/started")) {
      this.activeGuardianReview = { reviewId, targetItemId, command, threadId, turnId };
    }
    this.emitAgentEvent({
      stream: "codex_app_server.guardian",
      data: {
        method,
        phase: method.endsWith("/started") ? "started" : "completed",
        threadId,
        turnId,
        reviewId,
        targetItemId,
        decisionSource: readString(params, "decisionSource"),
        status: reviewStatus,
        riskLevel,
        userAuthorization,
        rationale,
        actionType: action ? readString(action, "type") : undefined,
        command,
      },
    });
    if (reviewId && targetItemId && status) {
      const approvalReview: JsonObject = {
        id: reviewId,
        label: "Guardian",
        status,
        ...(riskLevel ? { riskLevel } : {}),
        ...(userAuthorization ? { userAuthorization } : {}),
        ...(rationale ? { rationale } : {}),
      };
      const approvalReviewOutcome = this.toolTranscript.recordToolApprovalReview(
        targetItemId,
        reviewId,
        status,
        approvalReview,
      );
      this.emitAgentEvent({
        stream: "tool",
        data: {
          phase: "review",
          toolCallId: targetItemId,
          hideFromChannelProgress: true,
          approvalReviewOutcome,
          review: approvalReview,
        },
      });
    }
    if (method.endsWith("/completed") && this.activeGuardianReview?.reviewId === reviewId) {
      this.activeGuardianReview = undefined;
    }
  }

  handleGuardianWarning(params: JsonObject): void {
    this.flushPendingGuardianWarning();
    const message = readString(params, "message");
    if (message) {
      this.pendingGuardianWarning = message;
      return;
    }
    this.emitAgentEvent({
      stream: "codex_app_server.guardian",
      data: { phase: "warning", message },
    });
  }

  handleWarning(params: JsonObject): void {
    const summary = readString(params, "summary") ?? readString(params, "message");
    const details = readString(params, "details");
    const message = [summary, details].filter(Boolean).join("\n");
    if (LOG_ONLY_CODEX_WARNING_PATTERNS.some((pattern) => pattern.test(message))) {
      embeddedAgentLog.warn(message);
    } else if (message) {
      this.emitAgentEvent({ stream: "notice", data: { phase: "warning", message } });
    }
  }

  handleModelRerouted(params: JsonObject): void {
    const fromModel = readString(params, "fromModel");
    const toModel = readString(params, "toModel");
    const reason = readString(params, "reason");
    if (fromModel && toModel && fromModel !== toModel) {
      this.emitAgentEvent({
        stream: "fallback",
        data: { fromModel, toModel, ...(reason ? { reason } : {}) },
      });
    }
  }

  flushPendingGuardianWarning(): void {
    const pending = this.pendingGuardianWarning;
    if (!pending) {
      return;
    }
    this.pendingGuardianWarning = undefined;
    this.emitAgentEvent({
      stream: "codex_app_server.guardian",
      data: { phase: "warning", message: pending },
    });
  }

  handleStrictReviewRequired(params: JsonObject): void {
    this.emitAgentEvent({
      stream: "codex_app_server.guardian",
      data: {
        method: "autoApprovalReview/strictReviewRequired",
        phase: "strict_review_required",
        threadId:
          readString(params, "threadId") ?? this.activeGuardianReview?.threadId ?? this.threadId,
        turnId: readString(params, "turnId") ?? this.activeGuardianReview?.turnId ?? this.turnId,
        reviewId: this.activeGuardianReview?.reviewId,
        targetItemId: this.activeGuardianReview?.targetItemId,
        command: this.activeGuardianReview?.command,
        startedAtMs: asFiniteNumber(params.startedAtMs),
      },
    });
  }

  handleHook(method: string, params: JsonObject): void {
    const run = isJsonObject(params.run) ? params.run : undefined;
    if (!run) {
      return;
    }
    const durationMs = asFiniteNumber(run.durationMs);
    const entries = readHookOutputEntries(run.entries);
    const hookTurnId = readNullableString(params, "turnId");
    this.emitAgentEvent({
      stream: "codex_app_server.hook",
      data: {
        phase: method === "hook/started" ? "started" : "completed",
        threadId: this.threadId,
        turnId: hookTurnId === undefined ? this.turnId : hookTurnId,
        hookRunId: readString(run, "id"),
        eventName: readString(run, "eventName"),
        handlerType: readString(run, "handlerType"),
        executionMode: readString(run, "executionMode"),
        scope: readString(run, "scope"),
        source: readString(run, "source"),
        sourcePath: readString(run, "sourcePath"),
        status: readString(run, "status"),
        statusMessage: readNullableString(run, "statusMessage"),
        ...(durationMs !== undefined ? { durationMs } : {}),
        ...(entries.length > 0 ? { entries } : {}),
      },
    });
  }

  emitStandardItemEvent(params: {
    phase: "start" | "end";
    item: CodexThreadItem | undefined;
  }): void {
    const { item } = params;
    if (!item) {
      return;
    }
    const kind = itemKind(item);
    if (!kind) {
      return;
    }
    const name = itemName(item);
    const args = itemToolArgs(item);
    const commandBearing = isCommandBearingToolItem(item, args);
    const meta = itemMeta(item, this.toolProgress.toolProgressDetailMode());
    const suppressChannelProgress = shouldSuppressChannelProgressForItem(item);
    this.emitAgentEvent({
      stream: "item",
      data: {
        itemId: item.id,
        phase: params.phase,
        kind,
        title: itemTitle(item),
        status: params.phase === "start" ? "running" : itemStatus(item),
        ...(name ? { name } : {}),
        ...(meta ? { meta } : {}),
        ...(commandBearing ? { commandBearing: true } : {}),
        ...(suppressChannelProgress ? { suppressChannelProgress: true } : {}),
      },
    });
  }

  async emitNormalizedToolItemEvent(params: {
    phase: "start" | "result";
    item: CodexThreadItem | undefined;
  }): Promise<void> {
    const projection = projectNormalizedToolItem({
      ...params,
      detailMode: this.toolProgress.toolProgressDetailMode(),
    });
    if (!projection || !params.item) {
      return;
    }
    const { item } = params;
    const { name, status, args, meta, event } = projection;
    const approvalReviewOutcome =
      params.phase === "result"
        ? this.toolTranscript.finalizeToolApprovalReviews(item.id)
        : undefined;
    if (event && approvalReviewOutcome) {
      event.data.approvalReviewOutcome = approvalReviewOutcome;
    }
    this.toolTranscript.recordTrajectoryEvent({ phase: params.phase, item, name, args, status });
    if (params.phase === "result") {
      this.toolProgress.recordNativeToolError({ item, name, meta, status });
    }
    if (!event) {
      if (params.phase === "result") {
        this.toolTranscript.emitAfterToolCallObservation(item);
        await this.onNativeToolResultRecorded?.();
      }
      return;
    }
    this.emitAgentEvent(event);
    if (params.phase === "result") {
      this.toolTranscript.emitAfterToolCallObservation(item);
      await this.onNativeToolResultRecorded?.();
    }
  }
}

import { readItemString } from "./event-projector-values.js";
import type { CodexThreadItem } from "./protocol.js";

export type CodexNativeToolAuditStatus = ReturnType<typeof itemStatus> | "cancelled" | "unknown";
export type CodexNativeToolUnfinishedStatus = Extract<
  CodexNativeToolAuditStatus,
  "failed" | "unknown"
>;

export function itemKind(
  item: CodexThreadItem,
): "tool" | "command" | "patch" | "search" | "analysis" | undefined {
  switch (item.type) {
    case "dynamicToolCall":
    case "mcpToolCall":
      return "tool";
    case "commandExecution":
      return "command";
    case "fileChange":
      return "patch";
    case "webSearch":
      return "search";
    case "reasoning":
    case "contextCompaction":
      return "analysis";
    default:
      return undefined;
  }
}

export function itemTitle(item: CodexThreadItem): string {
  switch (item.type) {
    case "commandExecution":
      return "Command";
    case "fileChange":
      return "File change";
    case "mcpToolCall":
      return "MCP tool";
    case "dynamicToolCall":
      return "Tool";
    case "webSearch":
      return "Web search";
    case "contextCompaction":
      return "Context compaction";
    case "reasoning":
      return "Reasoning";
    default:
      return item.type;
  }
}

export function itemStatus(item: CodexThreadItem): "completed" | "failed" | "running" | "blocked" {
  const status = readItemString(item, "status");
  if (status === "failed" || status === "error") {
    return "failed";
  }
  if (status === "declined") {
    return "blocked";
  }
  if (status === "inProgress" || status === "in_progress" || status === "running") {
    return "running";
  }
  return "completed";
}

export function unknownItemStatus(item: CodexThreadItem): string | undefined {
  const status = readItemString(item, "status");
  switch (status) {
    case undefined:
    case "completed":
    case "failed":
    case "error":
    case "declined":
    case "inProgress":
    case "in_progress":
    case "running":
      return undefined;
    default:
      return status;
  }
}

export function auditNativeToolTerminalStatus(item: CodexThreadItem): CodexNativeToolAuditStatus {
  if (item.type === "imageView" || item.type === "sleep") {
    return "completed";
  }
  const status = readItemString(item, "status");
  if (status === "completed") {
    return "completed";
  }
  if (status === "failed" || status === "error") {
    return "failed";
  }
  if (status === "declined") {
    return "blocked";
  }
  // A completed notification with a missing, active, or new status does not
  // prove success. Preserve that ambiguity at the durable audit boundary.
  return "unknown";
}

export function auditNativeToolUnfinishedStatus(
  item: CodexThreadItem,
): CodexNativeToolUnfinishedStatus {
  // Search and image generation publish explicit terminal states. An enclosing
  // run outcome cannot substitute when that dependency-owned state is absent.
  return item.type === "webSearch" || item.type === "imageGeneration" ? "unknown" : "failed";
}

export function isNonSuccessItemStatus(status: ReturnType<typeof itemStatus>): boolean {
  return status === "failed" || status === "blocked";
}

export function itemName(item: CodexThreadItem): string | undefined {
  if (item.type === "dynamicToolCall" && typeof item.tool === "string") {
    return item.tool;
  }
  if (item.type === "mcpToolCall" && typeof item.tool === "string") {
    const server = typeof item.server === "string" ? item.server : undefined;
    return server ? `${server}.${item.tool}` : item.tool;
  }
  if (item.type === "commandExecution") {
    return "bash";
  }
  if (item.type === "fileChange") {
    return "apply_patch";
  }
  if (item.type === "webSearch") {
    return "web_search";
  }
  return undefined;
}

export function auditNativeToolName(item: CodexThreadItem): string | undefined {
  if (item.type === "dynamicToolCall") {
    return undefined;
  }
  const progressName = itemName(item);
  if (progressName) {
    return progressName;
  }
  if (item.type === "collabAgentToolCall") {
    return typeof item.tool === "string" && item.tool.trim()
      ? `collab.${item.tool.trim()}`
      : "collab_agent";
  }
  if (item.type === "imageGeneration") {
    return "image_generation";
  }
  if (item.type === "imageView") {
    return "image_view";
  }
  if (item.type === "sleep") {
    return "sleep";
  }
  return undefined;
}

export function isSideEffectingNativeToolItem(item: CodexThreadItem): boolean {
  return (
    itemStatus(item) !== "blocked" &&
    (isMutatingNativeToolItem(item) || item.type === "mcpToolCall")
  );
}

export function shouldSynthesizeToolProgressForItem(item: CodexThreadItem): boolean {
  switch (item.type) {
    case "commandExecution":
    case "fileChange":
    case "webSearch":
    case "mcpToolCall":
      return true;
    default:
      return false;
  }
}

export function shouldRecordNativeToolTranscript(item: CodexThreadItem): boolean {
  return shouldSynthesizeToolProgressForItem(item);
}

export function isMutatingNativeToolItem(item: CodexThreadItem): boolean {
  if (item.type === "commandExecution") {
    // Codex commandActions describe presentation, not safety. Upstream may
    // classify mutating commands as read/search, so native commands fail closed.
    return true;
  }
  return (
    item.type === "fileChange" ||
    item.type === "collabAgentToolCall" ||
    item.type === "imageGeneration"
  );
}

export function shouldClearTerminalPresentationForNativeItem(item: CodexThreadItem): boolean {
  switch (item.type) {
    case "collabAgentToolCall":
    case "commandExecution":
    case "fileChange":
    case "imageGeneration":
    case "imageView":
    case "mcpToolCall":
    case "webSearch":
      return true;
    default:
      return false;
  }
}

import {
  embeddedAgentLog,
  type EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { generatedImageAssetFromBase64 } from "openclaw/plugin-sdk/image-generation";
import { resolveGeneratedMediaMaxBytes } from "openclaw/plugin-sdk/media-generation-runtime";
import { saveMediaBuffer } from "openclaw/plugin-sdk/media-store";
import { readStringField as readString } from "openclaw/plugin-sdk/string-coerce-runtime";
import { readItemString } from "./event-projector-values.js";
import type { CodexThreadItem, JsonObject } from "./protocol.js";
import type { CodexRemoteWorkspaceFileReader } from "./remote-workspace-media.js";

const GENERATED_IMAGE_MEDIA_SUBDIR = "tool-image-generation";

export class CodexGeneratedMediaProjection {
  private readonly itemIds = new Set<string>();
  private readonly urlsByItemId = new Map<string, string>();
  private readonly gatewayMaterializedItemIds = new Set<string>();
  private readonly pendingMaterializationsByItemId = new Map<string, Promise<void>>();

  constructor(
    private readonly config: EmbeddedRunAttemptParams["config"],
    private readonly remote?: {
      remoteWorkspaceRoot?: string;
      readFile?: CodexRemoteWorkspaceFileReader;
      requestTimeoutMs?: number;
      signal?: AbortSignal;
    },
  ) {}

  hasGeneratedMedia(): boolean {
    return this.itemIds.size > 0;
  }

  async recordNative(item: CodexThreadItem | undefined): Promise<void> {
    if (item?.type !== "imageGeneration") {
      return;
    }
    // Image generation is already a billable side effect even if its remote
    // artifact cannot be transferred into this gateway's media store.
    this.itemIds.add(item.id);
    const result = readItemString(item, "result");
    if (result) {
      await this.recordImage({
        itemId: item.id,
        result,
        revisedPrompt: readItemString(item, "revisedPrompt"),
        source: "native",
      });
      return;
    }
    const savedPath = readItemString(item, "savedPath")?.trim();
    if (savedPath) {
      if (this.remote?.remoteWorkspaceRoot) {
        if (!this.remote.readFile) {
          embeddedAgentLog.warn("codex remote image has no app-server file transfer", {
            itemId: item.id,
          });
          return;
        }
        try {
          const response = await this.remote.readFile({
            path: savedPath,
            maxBytes: resolveGeneratedMediaMaxBytes(this.config, "image"),
            signal: this.remote.signal,
            timeoutMs: this.remote.requestTimeoutMs,
          });
          if (!response || typeof response.dataBase64 !== "string" || !response.dataBase64) {
            embeddedAgentLog.warn("codex remote image file returned no inline bytes", {
              itemId: item.id,
            });
            return;
          }
          await this.recordImage({
            itemId: item.id,
            result: response.dataBase64,
            revisedPrompt: readItemString(item, "revisedPrompt"),
            source: "native",
          });
        } catch (error) {
          embeddedAgentLog.warn("codex app-server remote image file read failed", {
            itemId: item.id,
            error,
          });
        }
        return;
      }
      this.recordUrl({ itemId: item.id, mediaUrl: savedPath });
    }
  }

  async recordRaw(item: JsonObject): Promise<void> {
    if (readString(item, "type") !== "image_generation_call") {
      return;
    }
    const result = readString(item, "result");
    if (!result) {
      return;
    }
    const itemId = readString(item, "id") ?? `raw-image-${this.itemIds.size}`;
    await this.recordImage({
      itemId,
      result,
      revisedPrompt: readString(item, "revised_prompt") ?? readString(item, "revisedPrompt"),
      source: "raw",
    });
  }

  private async recordImage(params: {
    itemId: string;
    result: string;
    revisedPrompt?: string;
    source: "native" | "raw";
  }): Promise<void> {
    this.itemIds.add(params.itemId);
    if (this.gatewayMaterializedItemIds.has(params.itemId)) {
      return;
    }
    let pending = this.pendingMaterializationsByItemId.get(params.itemId);
    while (pending) {
      await pending;
      if (this.gatewayMaterializedItemIds.has(params.itemId)) {
        return;
      }
      // A malformed, oversized, or failed sibling event must not suppress a
      // valid completion carrying the same Codex image item.
      pending = this.pendingMaterializationsByItemId.get(params.itemId);
    }

    const materialization = this.materializeImage(params);
    this.pendingMaterializationsByItemId.set(params.itemId, materialization);
    try {
      await materialization;
    } finally {
      if (this.pendingMaterializationsByItemId.get(params.itemId) === materialization) {
        this.pendingMaterializationsByItemId.delete(params.itemId);
      }
    }
  }

  private async materializeImage(params: {
    itemId: string;
    result: string;
    revisedPrompt?: string;
    source: "native" | "raw";
  }): Promise<void> {
    const maxBytes = resolveGeneratedMediaMaxBytes(this.config, "image");
    const estimatedDecodedBytes = estimateBase64DecodedBytes(params.result);
    if (estimatedDecodedBytes !== undefined && estimatedDecodedBytes > maxBytes) {
      embeddedAgentLog.warn(
        `codex app-server ${params.source} image generation result exceeds media limit`,
        {
          itemId: params.itemId,
          estimatedDecodedBytes,
          maxBytes,
        },
      );
      return;
    }
    const asset = generatedImageAssetFromBase64({
      base64: params.result,
      index: this.itemIds.size,
      revisedPrompt: params.revisedPrompt,
      fileNamePrefix: "codex-image-generation",
      sniffMimeType: true,
    });
    if (!asset) {
      return;
    }
    try {
      const saved = await saveMediaBuffer(
        asset.buffer,
        asset.mimeType,
        GENERATED_IMAGE_MEDIA_SUBDIR,
        maxBytes,
        asset.fileName,
      );
      this.gatewayMaterializedItemIds.add(params.itemId);
      this.recordUrl({
        itemId: params.itemId,
        mediaUrl: saved.path,
        // Both Codex event shapes can carry a DevBox-local savedPath; channel
        // delivery must always use the copy materialized on this gateway.
        replaceExisting: true,
      });
    } catch (error) {
      embeddedAgentLog.warn(
        `codex app-server ${params.source} image generation result save failed`,
        {
          itemId: params.itemId,
          error,
        },
      );
    }
  }

  buildToolMediaUrls(params: {
    toolMediaUrls?: string[];
    messagingToolSentMediaUrls?: string[];
  }): string[] | undefined {
    const mediaUrls = new Set(params.toolMediaUrls?.map((url) => url.trim()).filter(Boolean) ?? []);
    if ((params.messagingToolSentMediaUrls?.length ?? 0) === 0) {
      for (const mediaUrl of this.urlsByItemId.values()) {
        mediaUrls.add(mediaUrl);
      }
    }
    return mediaUrls.size > 0 ? [...mediaUrls] : params.toolMediaUrls;
  }

  buildHostOwnedMediaUrls(params: { messagingToolSentMediaUrls?: string[] }): string[] | undefined {
    if ((params.messagingToolSentMediaUrls?.length ?? 0) > 0) {
      return undefined;
    }
    const mediaUrls = [...this.urlsByItemId.values()];
    return mediaUrls.length > 0 ? mediaUrls : undefined;
  }

  private recordUrl(params: { itemId: string; mediaUrl: string; replaceExisting?: boolean }): void {
    if (this.urlsByItemId.has(params.itemId) && params.replaceExisting !== true) {
      this.itemIds.add(params.itemId);
      return;
    }
    this.urlsByItemId.set(params.itemId, params.mediaUrl);
    this.itemIds.add(params.itemId);
  }
}

function estimateBase64DecodedBytes(base64: string): number | undefined {
  let nonWhitespaceLength = 0;
  let previousCode = -1;
  let lastCode = -1;
  for (let i = 0; i < base64.length; i += 1) {
    const code = base64.charCodeAt(i);
    if (isBase64WhitespaceCode(code)) {
      continue;
    }
    nonWhitespaceLength += 1;
    previousCode = lastCode;
    lastCode = code;
  }
  if (nonWhitespaceLength === 0) {
    return undefined;
  }
  const equalsCode = "=".charCodeAt(0);
  const padding = lastCode === equalsCode ? (previousCode === equalsCode ? 2 : 1) : 0;
  return Math.max(0, Math.floor((nonWhitespaceLength * 3) / 4) - padding);
}

function isBase64WhitespaceCode(code: number): boolean {
  return code === 0x20 || code === 0x09 || code === 0x0a || code === 0x0d;
}

import type {
  BeforeToolCallFailureDisposition,
  EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { emitTrustedDiagnosticEvent } from "openclaw/plugin-sdk/diagnostic-runtime";
import { asDateTimestampMs } from "openclaw/plugin-sdk/number-runtime";
import { readStringField as readString } from "openclaw/plugin-sdk/string-coerce-runtime";
import { resolveCodexToolAbortTerminalReason } from "./dynamic-tool-execution.js";
import {
  auditNativeToolName,
  auditNativeToolTerminalStatus,
  auditNativeToolUnfinishedStatus,
  itemStatus,
  type CodexNativeToolAuditStatus,
  type CodexNativeToolUnfinishedStatus,
} from "./event-projector-items.js";
import { readItem } from "./event-projector-values.js";
import {
  emitCodexNativePreToolUseFailureDiagnostic,
  type CodexNativePreToolUseFailure,
} from "./native-hook-relay.js";
import { isCodexNotificationForTurn } from "./notification-correlation.js";
import { readCodexTurn } from "./protocol-validators.js";
import {
  isJsonObject,
  type CodexServerNotification,
  type CodexThreadItem,
  type JsonObject,
} from "./protocol.js";

type CodexNativeToolLifecycleContext = Pick<
  EmbeddedRunAttemptParams,
  "agentId" | "runId" | "sessionId" | "sessionKey"
>;

type CodexNativeToolLifecycleProjectorOptions = {
  runAbortSignal?: AbortSignal;
};

type CodexNativePreToolUseFailureRecord = {
  failure: CodexNativePreToolUseFailure;
  terminalReason: CodexNativePreToolUseFailure["disposition"];
};

/** Projects metadata-only lifecycle diagnostics for native tool items. */
export class CodexNativeToolLifecycleProjector {
  private readonly startedAtByItem = new Map<string, number>();
  private readonly activeItems = new Map<
    string,
    { toolName: string; unfinishedStatus: CodexNativeToolUnfinishedStatus }
  >();
  private readonly webSearchCompletionByItem = new Map<
    string,
    { runWasAborted: boolean; sourceTimestampMs?: number }
  >();
  private readonly completedItemIds = new Set<string>();
  private readonly approvalFailureDispositionByItem = new Map<
    string,
    Exclude<BeforeToolCallFailureDisposition, "blocked">
  >();
  private readonly preToolUseFailureByItem = new Map<string, CodexNativePreToolUseFailureRecord>();
  private finalized = false;

  constructor(
    private readonly context: CodexNativeToolLifecycleContext,
    private readonly threadId: string,
    private readonly turnId: string,
    private readonly options: CodexNativeToolLifecycleProjectorOptions = {},
  ) {}

  handleNotification(notification: CodexServerNotification): void {
    const params = isJsonObject(notification.params) ? notification.params : undefined;
    if (!params || !isCodexNotificationForTurn(params, this.threadId, this.turnId)) {
      return;
    }
    if (notification.method === "turn/completed") {
      const turn = readCodexTurn(params.turn);
      if (!turn || turn.id !== this.turnId) {
        return;
      }
      for (const item of turn.items ?? []) {
        this.recordSnapshotItem(item);
      }
      return;
    }
    if (notification.method === "rawResponseItem/completed") {
      const item = isJsonObject(params.item) ? params.item : undefined;
      if (item) {
        this.recordRawWebSearchResult(item);
      }
      return;
    }
    if (notification.method !== "item/started" && notification.method !== "item/completed") {
      return;
    }
    const item = readItem(params.item);
    if (!item) {
      return;
    }
    this.recordItem({
      phase: notification.method === "item/started" ? "start" : "result",
      item,
      sourceTimestampMs: asDateTimestampMs(
        notification.method === "item/started" ? params.startedAtMs : params.completedAtMs,
      ),
    });
  }

  recordItem(params: {
    phase: "start" | "result";
    item: CodexThreadItem;
    sourceTimestampMs?: number;
  }): void {
    const toolName = auditNativeToolName(params.item);
    if (!toolName || this.completedItemIds.has(params.item.id)) {
      return;
    }
    if (params.phase === "start") {
      this.recordStarted(
        params.item.id,
        toolName,
        auditNativeToolUnfinishedStatus(params.item),
        params.sourceTimestampMs,
      );
      return;
    }
    if (params.item.type === "webSearch") {
      // Warm resumes retain raw-event delivery, while cold resumes expose no
      // capability bit. Wait through the drain; finalization closes misses unknown.
      this.webSearchCompletionByItem.set(params.item.id, {
        runWasAborted: this.options.runAbortSignal?.aborted === true,
        sourceTimestampMs: params.sourceTimestampMs,
      });
      return;
    }

    const itemDurationMs =
      typeof params.item.durationMs === "number" ? params.item.durationMs : undefined;
    this.recordTerminal(params.item.id, toolName, auditNativeToolTerminalStatus(params.item), {
      itemDurationMs,
      sourceTimestampMs: params.sourceTimestampMs,
    });
  }

  recordApprovalFailureDisposition(
    toolCallId: string,
    disposition: Exclude<BeforeToolCallFailureDisposition, "blocked">,
  ): void {
    if (!this.completedItemIds.has(toolCallId)) {
      this.approvalFailureDispositionByItem.set(toolCallId, disposition);
    }
  }

  recordPreToolUseFailure(
    failure: CodexNativePreToolUseFailure,
    runWasAborted = this.options.runAbortSignal?.aborted === true,
  ): void {
    if (this.completedItemIds.has(failure.toolCallId)) {
      return;
    }
    const record: CodexNativePreToolUseFailureRecord = {
      failure,
      terminalReason:
        runWasAborted && this.options.runAbortSignal
          ? resolveCodexToolAbortTerminalReason(this.options.runAbortSignal)
          : failure.disposition,
    };
    if (this.finalized) {
      // Relay subprocesses can settle after result construction. Emit the
      // item-less fallback here because no later notification drain remains.
      this.completedItemIds.add(failure.toolCallId);
      this.emitPreToolUseFailure(record, failure.toolName, failure.durationMs);
      return;
    }
    this.preToolUseFailureByItem.set(failure.toolCallId, record);
  }

  private recordRawWebSearchResult(item: JsonObject): void {
    if (readString(item, "type") !== "web_search_call") {
      return;
    }
    const toolCallId = readString(item, "id");
    if (!toolCallId || this.completedItemIds.has(toolCallId)) {
      return;
    }
    const toolName = "web_search";
    this.recordStarted(toolCallId, toolName, "unknown");
    const rawStatus = readString(item, "status");
    if (rawStatus === "in_progress" || rawStatus === "running") {
      return;
    }
    const status: CodexNativeToolAuditStatus =
      rawStatus === "completed"
        ? "completed"
        : rawStatus === "cancelled"
          ? "cancelled"
          : rawStatus === "failed" || rawStatus === "error" || rawStatus === "incomplete"
            ? "failed"
            : "unknown";
    this.recordTerminal(toolCallId, toolName, status, {
      sourceTimestampMs: this.webSearchCompletionByItem.get(toolCallId)?.sourceTimestampMs,
    });
  }

  private recordTerminal(
    toolCallId: string,
    toolName: string,
    status: CodexNativeToolAuditStatus,
    options: {
      itemDurationMs?: number;
      sourceTimestampMs?: number;
      runWasAborted?: boolean;
    } = {},
  ): void {
    const runWasAborted = options.runWasAborted ?? this.options.runAbortSignal?.aborted === true;
    const preToolUseFailure = this.preToolUseFailureByItem.get(toolCallId);
    this.preToolUseFailureByItem.delete(toolCallId);
    const approvalFailureDisposition = this.approvalFailureDispositionByItem.get(toolCallId);
    this.approvalFailureDispositionByItem.delete(toolCallId);
    this.completedItemIds.add(toolCallId);
    this.activeItems.delete(toolCallId);
    this.webSearchCompletionByItem.delete(toolCallId);
    const startedAt = this.startedAtByItem.get(toolCallId);
    this.startedAtByItem.delete(toolCallId);
    const endedAt = options.sourceTimestampMs ?? Date.now();
    const durationMs =
      options.itemDurationMs ?? (startedAt === undefined ? 0 : Math.max(0, endedAt - startedAt));
    if (preToolUseFailure) {
      this.emitPreToolUseFailure(
        preToolUseFailure,
        toolName,
        durationMs,
        options.sourceTimestampMs,
      );
      return;
    }
    const terminalEvent = approvalFailureDisposition
      ? {
          type: "tool.execution.error" as const,
          durationMs,
          errorCategory: "codex_native_tool_approval",
          terminalReason: approvalFailureDisposition,
        }
      : status === "blocked"
        ? {
            type: "tool.execution.blocked" as const,
            reason: "codex_native_tool_blocked",
            deniedReason: "codex_native_tool_blocked",
          }
        : status === "failed" || status === "cancelled" || status === "unknown"
          ? {
              type: "tool.execution.error" as const,
              durationMs,
              errorCategory:
                status === "unknown"
                  ? "codex_native_tool_outcome_unknown"
                  : status === "cancelled"
                    ? "aborted"
                    : "codex_native_tool_error",
              ...(status === "unknown" ? { errorCode: "tool_outcome_unknown" } : {}),
              terminalReason:
                // An enclosing abort explains unfinished work, but cannot classify
                // a native terminal whose status is absent or unrecognized.
                status === "unknown"
                  ? ("failed" as const)
                  : runWasAborted && this.options.runAbortSignal
                    ? resolveCodexToolAbortTerminalReason(this.options.runAbortSignal)
                    : status === "cancelled"
                      ? ("cancelled" as const)
                      : ("failed" as const),
            }
          : {
              type: "tool.execution.completed" as const,
              durationMs,
            };
    emitTrustedDiagnosticEvent({
      ...this.buildBase(toolCallId, toolName),
      ...terminalEvent,
      ...(options.sourceTimestampMs !== undefined
        ? { sourceTimestampMs: options.sourceTimestampMs }
        : {}),
    });
  }

  finalizeActive(runWasAborted = this.options.runAbortSignal?.aborted === true): void {
    this.finalized = true;
    for (const [toolCallId, { toolName, unfinishedStatus }] of this.activeItems) {
      const webSearchCompletion = this.webSearchCompletionByItem.get(toolCallId);
      const itemRunWasAborted = webSearchCompletion
        ? webSearchCompletion.runWasAborted
        : runWasAborted;
      this.recordTerminal(toolCallId, toolName, unfinishedStatus, {
        runWasAborted: itemRunWasAborted,
        sourceTimestampMs: webSearchCompletion?.sourceTimestampMs,
      });
    }
    for (const [toolCallId, record] of this.preToolUseFailureByItem) {
      if (!this.completedItemIds.has(toolCallId)) {
        this.recordTerminal(toolCallId, record.failure.toolName, "failed", {
          itemDurationMs: record.failure.durationMs,
        });
      }
    }
    this.activeItems.clear();
    this.webSearchCompletionByItem.clear();
    this.approvalFailureDispositionByItem.clear();
    this.preToolUseFailureByItem.clear();
  }

  private emitPreToolUseFailure(
    record: CodexNativePreToolUseFailureRecord,
    toolName: string,
    durationMs: number,
    sourceTimestampMs?: number,
  ): void {
    emitCodexNativePreToolUseFailureDiagnostic({
      agentId: this.context.agentId,
      sessionId: this.context.sessionId,
      sessionKey: this.context.sessionKey,
      runId: this.context.runId,
      failure: { ...record.failure, toolName, durationMs },
      terminalReason: record.terminalReason,
      sourceTimestampMs,
    });
  }

  private recordSnapshotItem(item: CodexThreadItem): void {
    if (
      !auditNativeToolName(item) ||
      this.completedItemIds.has(item.id) ||
      itemStatus(item) === "running"
    ) {
      return;
    }
    const toolName = auditNativeToolName(item);
    if (!toolName) {
      return;
    }
    this.recordStarted(item.id, toolName, auditNativeToolUnfinishedStatus(item));
    this.recordItem({ phase: "result", item });
  }

  private recordStarted(
    toolCallId: string,
    toolName: string,
    unfinishedStatus: CodexNativeToolUnfinishedStatus,
    sourceTimestampMs?: number,
  ): void {
    if (this.activeItems.has(toolCallId)) {
      return;
    }
    this.startedAtByItem.set(toolCallId, sourceTimestampMs ?? Date.now());
    this.activeItems.set(toolCallId, { toolName, unfinishedStatus });
    emitTrustedDiagnosticEvent({
      type: "tool.execution.started",
      ...this.buildBase(toolCallId, toolName),
      ...(sourceTimestampMs !== undefined ? { sourceTimestampMs } : {}),
    });
  }

  private buildBase(toolCallId: string, toolName: string) {
    return {
      agentId: this.context.agentId,
      runId: this.context.runId,
      sessionId: this.context.sessionId,
      sessionKey: this.context.sessionKey,
      toolName,
      toolCallId,
    };
  }
}

import type { AgentPlanStep } from "openclaw/plugin-sdk/channel-outbound";
import type { AssistantMessage } from "openclaw/plugin-sdk/llm";
import type { CodexThreadItem, JsonValue } from "./protocol.js";
import type { CodexRemoteWorkspaceFileReader } from "./remote-workspace-media.js";
import type { CodexTrajectoryRecorder } from "./trajectory.js";

export type CodexAsyncDeliverySettlement = "settled" | "retry";

export type CodexAppServerEventProjectorOptions = {
  initialContextTokens?: number;
  nativePostToolUseRelayEnabled?: boolean;
  asyncUserMessageAllowed?: boolean;
  onAsyncDelivery?: (delivery: {
    itemId: string;
    message: AssistantMessage;
    text: string;
  }) => CodexAsyncDeliverySettlement | Promise<CodexAsyncDeliverySettlement>;
  onNativeToolResultRecorded?: () => void | Promise<void>;
  onNativePlanUpdate?: (update: {
    markdown?: string;
    steps: AgentPlanStep[];
  }) => void | Promise<void>;
  prepareNativeMcpAppResultDetails?: (item: CodexThreadItem) => Promise<unknown>;
  readRecentRateLimits?: () => JsonValue | undefined;
  runAbortSignal?: AbortSignal;
  remoteWorkspaceRoot?: string;
  readRemoteWorkspaceFile?: CodexRemoteWorkspaceFileReader;
  remoteWorkspaceRequestTimeoutMs?: number;
  trajectoryRecorder?: CodexTrajectoryRecorder | null;
  onContextCompacted?: () => void | Promise<void>;
  resolveDynamicToolResultContentSource?: (toolName: string) => "network" | undefined;
  upstreamUserText?: string;
};

import type { EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { AgentPlanStep, AgentPlanStepStatus } from "openclaw/plugin-sdk/channel-outbound";
import { readStringField as readString } from "openclaw/plugin-sdk/string-coerce-runtime";
import {
  readNonNegativeInteger,
  readNullableString,
  splitPlanText,
} from "./event-projector-values.js";
import type { CodexThreadItem, JsonObject } from "./protocol.js";

type ReasoningDeltaMethod = "item/reasoning/summaryTextDelta" | "item/reasoning/textDelta";

type ReasoningTextGroup = {
  itemId: string;
  method: ReasoningDeltaMethod;
  index: number;
  text: string;
};

type AgentEvent = Parameters<NonNullable<EmbeddedRunAttemptParams["onAgentEvent"]>>[0];
type PlanUpdateSource = "codex-app-server" | "openclaw";
type NativePlanUpdate = { markdown?: string; steps: AgentPlanStep[] };

export class CodexReasoningProjection {
  private readonly reasoningTextByGroup = new Map<string, ReasoningTextGroup>();
  private readonly reasoningItemOrder = new Map<string, number>();
  private readonly planTextByItem = new Map<string, string>();
  private turnPlanText: string | undefined;
  private reasoningStarted = false;
  private reasoningEnded = false;

  constructor(
    private readonly params: EmbeddedRunAttemptParams,
    private readonly emitAgentEvent: (event: AgentEvent) => void,
    private readonly onNativePlanUpdate?: (update: NativePlanUpdate) => void | Promise<void>,
  ) {}

  async handleReasoningDelta(method: ReasoningDeltaMethod, params: JsonObject): Promise<void> {
    const itemId = readString(params, "itemId") ?? "reasoning";
    const delta = readString(params, "delta") ?? "";
    if (!delta) {
      return;
    }
    this.reasoningStarted = true;
    if (!this.reasoningItemOrder.has(itemId)) {
      this.reasoningItemOrder.set(itemId, this.reasoningItemOrder.size);
    }
    // Codex indexes reasoning sections independently within an item.
    const groupIndex =
      method === "item/reasoning/textDelta"
        ? (readNonNegativeInteger(params, "contentIndex") ?? 0)
        : (readNonNegativeInteger(params, "summaryIndex") ?? 0);
    const groupKey = `${method}\0${itemId}\0${groupIndex}`;
    const current = this.reasoningTextByGroup.get(groupKey);
    this.reasoningTextByGroup.set(groupKey, {
      itemId,
      method,
      index: groupIndex,
      text: `${current?.text ?? ""}${delta}`,
    });
    await this.params.onReasoningStream?.({
      text: this.reasoningText(),
      isReasoningSnapshot: true,
    });
  }

  handlePlanDelta(params: JsonObject): void {
    const itemId = readString(params, "itemId") ?? "plan";
    const delta = readString(params, "delta") ?? "";
    if (!delta) {
      return;
    }
    const text = `${this.planTextByItem.get(itemId) ?? ""}${delta}`;
    this.planTextByItem.set(itemId, text);
    this.emitPlanUpdate({
      explanation: undefined,
      steps: splitPlanText(text).map((step) => ({ step, status: "pending" })),
    });
  }

  async handleTurnPlanUpdated(
    params: JsonObject,
    source: PlanUpdateSource = "codex-app-server",
  ): Promise<void> {
    const explanation = readNullableString(params, "explanation");
    const plan = Array.isArray(params.plan)
      ? params.plan.flatMap((entry) => {
          if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
            return [];
          }
          const record = entry as JsonObject;
          const step = readString(record, "step");
          if (!step) {
            return [];
          }
          return [{ step, status: normalizePlanStepStatus(readString(record, "status")) }];
        })
      : undefined;
    const planText = [
      explanation,
      ...(plan ?? []).map(({ step, status }) => `- [${status}] ${step}`),
    ]
      .filter((part): part is string => Boolean(part))
      .join("\n");
    if (planText) {
      // Structured turn updates are the canonical latest plan for terminal classification.
      this.turnPlanText = planText;
    }
    if (source === "codex-app-server" && plan) {
      await this.onNativePlanUpdate?.({
        ...(typeof explanation === "string" ? { markdown: explanation } : {}),
        steps: plan,
      });
    }
    this.emitPlanUpdate(
      {
        explanation,
        steps: plan,
      },
      source,
    );
  }

  recordItem(item: CodexThreadItem | undefined): void {
    if (item?.type === "plan" && typeof item.text === "string" && item.text) {
      this.planTextByItem.set(item.id, item.text);
      this.emitPlanUpdate({
        explanation: undefined,
        steps: splitPlanText(item.text).map((step) => ({ step, status: "pending" })),
      });
    }
  }

  async maybeEndReasoning(): Promise<void> {
    if (!this.reasoningStarted || this.reasoningEnded) {
      return;
    }
    this.reasoningEnded = true;
    await this.params.onReasoningEnd?.();
  }

  reasoningText(): string {
    return collectReasoningTextValues(this.reasoningTextByGroup, this.reasoningItemOrder).join(
      "\n\n",
    );
  }

  planText(): string {
    return (
      this.turnPlanText ??
      [...this.planTextByItem.values()].filter((text) => text.trim().length > 0).join("\n\n")
    );
  }

  private emitPlanUpdate(
    params: { explanation?: string | null; steps?: AgentPlanStep[] },
    source: PlanUpdateSource = "codex-app-server",
  ): void {
    if (!params.explanation && params.steps === undefined) {
      return;
    }
    this.emitAgentEvent({
      stream: "plan",
      data: {
        phase: "update",
        title: "Plan updated",
        source,
        ...(params.explanation ? { explanation: params.explanation } : {}),
        ...(params.steps ? { steps: params.steps } : {}),
      },
    });
  }
}

function normalizePlanStepStatus(status: string | undefined): AgentPlanStepStatus {
  if (status === "inProgress" || status === "in_progress") {
    return "in_progress";
  }
  return status === "completed" ? "completed" : "pending";
}

function collectReasoningTextValues(
  groups: Map<string, ReasoningTextGroup>,
  itemOrder: Map<string, number>,
): string[] {
  return [...groups.values()]
    .toSorted((left, right) => {
      const itemDelta =
        (itemOrder.get(left.itemId) ?? Number.MAX_SAFE_INTEGER) -
        (itemOrder.get(right.itemId) ?? Number.MAX_SAFE_INTEGER);
      if (itemDelta !== 0) {
        return itemDelta;
      }
      const methodDelta = reasoningMethodOrder(left.method) - reasoningMethodOrder(right.method);
      return methodDelta !== 0 ? methodDelta : left.index - right.index;
    })
    .map((group) => group.text)
    .filter((text) => text.trim().length > 0);
}

function reasoningMethodOrder(method: ReasoningDeltaMethod): number {
  return method === "item/reasoning/summaryTextDelta" ? 0 : 1;
}

