import { expectDefined } from "@openclaw/normalization-core";
import { upsertSessionEntry } from "openclaw/plugin-sdk/session-store-runtime";
import { readSessionTranscriptEvents } from "openclaw/plugin-sdk/session-transcript-runtime";
import { describe, expect, it, vi } from "vitest";
import {
  buildEmptyToolTelemetry,
  createParams,
  createProjector,
  forCurrentTurn,
  registerCodexEventProjectorTestLifecycle,
  TURN_ID,
  turnCompleted,
} from "./event-projector.test-harness.js";
import { codexTranscriptMirrorRuntime } from "./transcript-mirror.js";

registerCodexEventProjectorTestLifecycle();

describe("CodexAppServerEventProjector async delivery", () => {
  it.each([
    { name: "disabled tools", disableTools: true },
    { name: "an empty tool allowlist", toolsAllow: [] },
    { name: "the ring-zero system tool", toolsAllow: ["openclaw"] },
    { name: "an allowlist without message delivery", toolsAllow: ["read"] },
  ])("does not expose native async messages through $name", async (restriction) => {
    const params = await createParams();
    const onAsyncDelivery = vi.fn().mockResolvedValue("settled");
    const projector = await createProjector({ ...params, ...restriction }, { onAsyncDelivery });

    await projector.handleNotification(
      forCurrentTurn("item/completed", {
        item: {
          type: "agentMessage",
          id: "unauthorized-async-update",
          phase: "final_answer",
          delivery: "async",
          text: "This restricted update must not reach a user.",
        },
      }),
    );
    await projector.handleNotification(
      turnCompleted([
        {
          type: "agentMessage",
          id: "authorized-final",
          phase: "final_answer",
          text: "Ordinary final reply.",
        },
      ]),
    );

    expect(onAsyncDelivery).not.toHaveBeenCalled();
    expect(
      JSON.stringify(projector.buildResult(buildEmptyToolTelemetry()).messagesSnapshot),
    ).not.toContain("restricted update");
  });

  it("persists async delivery once without selecting it as the final answer", async () => {
    const onAgentEvent = vi.fn();
    const onBlockReply = vi.fn();
    const params = await createParams();
    const sessionId = expectDefined(params.sessionId, "Codex async delivery test session");
    const storePath = `${params.workspaceDir}/openclaw-agent.sqlite`;
    params.sessionKey = "agent:main:session-1";
    const sessionTarget = {
      agentId: "main",
      sessionId,
      sessionKey: params.sessionKey,
      storePath,
    };
    params.sessionTarget = sessionTarget;
    await upsertSessionEntry({
      agentId: "main",
      sessionKey: params.sessionKey,
      storePath,
      entry: {
        sessionFile: params.sessionFile,
        sessionId,
        updatedAt: Date.now(),
      },
    });
    const projector = await createProjector(
      {
        ...params,
        onAgentEvent,
        onBlockReply,
      },
      {
        onAsyncDelivery: async (delivery) => {
          return await codexTranscriptMirrorRuntime.deliverAsyncMessageBestEffort({
            params: { ...params, onAgentEvent, onBlockReply },
            cwd: params.workspaceDir,
            threadId: "thread-1",
            turnId: TURN_ID,
            ...delivery,
          });
        },
      },
    );

    await projector.handleNotification(
      forCurrentTurn("item/completed", {
        item: {
          type: "agentMessage",
          id: "terminal-answer",
          phase: "final_answer",
          text: "Finished.",
        },
      }),
    );
    const asyncCompletion = forCurrentTurn("item/completed", {
      item: {
        type: "agentMessage",
        id: "async-update",
        phase: "final_answer",
        delivery: "async",
        text: "Background agent update.",
      },
    });
    await projector.handleNotification(asyncCompletion);
    expect(onBlockReply).toHaveBeenCalledOnce();
    expect(onBlockReply).toHaveBeenCalledWith(
      { text: "Background agent update." },
      {
        deliveryIntentId: `block-reply:v1:codex-app-server:thread-1:${TURN_ID}:async-update`,
      },
    );
    await projector.handleNotification(asyncCompletion);
    expect(onBlockReply).toHaveBeenCalledOnce();
    await projector.handleNotification(
      turnCompleted([
        {
          type: "agentMessage",
          id: "async-update",
          phase: "final_answer",
          delivery: "async",
          text: "Background agent update.",
        },
        {
          type: "agentMessage",
          id: "terminal-answer",
          phase: "final_answer",
          text: "Finished.",
        },
      ]),
    );
    expect(onBlockReply).toHaveBeenCalledOnce();

    const result = projector.buildResult(buildEmptyToolTelemetry());
    expect(result.assistantTexts).toEqual(["Finished."]);
    expect(result.currentAttemptAssistant?.content).toEqual([{ type: "text", text: "Finished." }]);
    const asyncMessages = result.messagesSnapshot.filter(
      (message) =>
        (message as { openclawAsyncDelivery?: { itemId?: unknown } }).openclawAsyncDelivery
          ?.itemId === "async-update",
    );
    expect(asyncMessages).toHaveLength(1);
    expect(asyncMessages[0]).toMatchObject({
      role: "assistant",
      content: [{ type: "text", text: "Background agent update." }],
      openclawAsyncDelivery: { itemId: "async-update" },
      __openclaw: { mirrorIdentity: `${TURN_ID}:async:async-update` },
    });
    const transcriptMessages = (await readSessionTranscriptEvents(sessionTarget))
      .map((event) => (event as { message?: unknown }).message)
      .filter((message): message is Record<string, unknown> => Boolean(message));
    expect(
      transcriptMessages.filter(
        (message) =>
          (message.openclawAsyncDelivery as { itemId?: unknown } | undefined)?.itemId ===
          "async-update",
      ),
    ).toHaveLength(1);
    expect(
      onAgentEvent.mock.calls
        .map((call) => call[0])
        .filter(
          (event) =>
            event.stream === "item" &&
            event.data.itemId === "async-update" &&
            event.data.kind === "answer_candidate",
        ),
    ).toEqual([]);
  });

  it("settles sessionless async delivery once across completion and terminal replay", async () => {
    const params = await createParams();
    const onBlockReply = vi.fn();
    const projector = await createProjector(
      { ...params, onBlockReply },
      {
        onAsyncDelivery: (delivery) =>
          codexTranscriptMirrorRuntime.deliverAsyncMessageBestEffort({
            params: { ...params, onBlockReply },
            cwd: params.workspaceDir,
            threadId: "thread-1",
            turnId: TURN_ID,
            ...delivery,
          }),
      },
    );
    const asyncItem = {
      type: "agentMessage" as const,
      id: "async-sessionless",
      phase: "final_answer",
      delivery: "async" as const,
      text: "Sessionless background update.",
    };
    const completion = forCurrentTurn("item/completed", { item: asyncItem });

    await projector.handleNotification(completion);
    await projector.handleNotification(completion);
    await projector.handleNotification(
      turnCompleted([
        asyncItem,
        {
          type: "agentMessage",
          id: "terminal-sessionless",
          phase: "final_answer",
          text: "Sessionless final.",
        },
      ]),
    );

    expect(onBlockReply).toHaveBeenCalledOnce();
    expect(onBlockReply).toHaveBeenCalledWith(
      { text: "Sessionless background update." },
      {
        deliveryIntentId: `block-reply:v1:codex-app-server:thread-1:${TURN_ID}:async-sessionless`,
      },
    );
    expect(projector.buildResult(buildEmptyToolTelemetry()).assistantTexts).toEqual([
      "Sessionless final.",
    ]);
  });

  it("retries unsettled sessionless async delivery when the real terminal summary contains only the final answer", async () => {
    const params = await createParams();
    const onBlockReply = vi
      .fn()
      .mockRejectedValueOnce(new Error("channel unavailable"))
      .mockResolvedValue(undefined);
    const projector = await createProjector(
      { ...params, onBlockReply },
      {
        onAsyncDelivery: (delivery) =>
          codexTranscriptMirrorRuntime.deliverAsyncMessageBestEffort({
            params: { ...params, onBlockReply },
            cwd: params.workspaceDir,
            threadId: "thread-1",
            turnId: TURN_ID,
            ...delivery,
          }),
      },
    );
    const asyncItem = {
      type: "agentMessage" as const,
      id: "async-retry",
      phase: "final_answer",
      delivery: "async" as const,
      text: "Retry this background update.",
    };
    const completed = turnCompleted([
      {
        type: "agentMessage",
        id: "terminal-retry",
        phase: "final_answer",
        text: "Retry final.",
      },
    ]);

    await projector.handleNotification(forCurrentTurn("item/completed", { item: asyncItem }));
    await projector.handleNotification(completed);
    await projector.handleNotification(completed);

    expect(onBlockReply).toHaveBeenCalledTimes(2);
    expect(onBlockReply.mock.calls[1]).toEqual(onBlockReply.mock.calls[0]);
    expect(onBlockReply).toHaveBeenCalledWith(
      { text: "Retry this background update." },
      {
        deliveryIntentId: `block-reply:v1:codex-app-server:thread-1:${TURN_ID}:async-retry`,
      },
    );
    expect(projector.buildResult(buildEmptyToolTelemetry()).assistantTexts).toEqual([
      "Retry final.",
    ]);
  });

  it("retains async delivery across reconstructed turn snapshots", async () => {
    const completed = turnCompleted([
      {
        type: "agentMessage",
        id: "async-reconnect",
        phase: "final_answer",
        delivery: "async",
        text: "Delivered while the client was reconnecting.",
      },
      {
        type: "agentMessage",
        id: "terminal-reconnect",
        phase: "final_answer",
        text: "Reconnect complete.",
      },
    ]);

    for (let attempt = 0; attempt < 2; attempt += 1) {
      const onAsyncDelivery = vi.fn().mockResolvedValue("settled");
      const projector = await createProjector(undefined, { onAsyncDelivery });
      await projector.handleNotification(completed);
      expect(onAsyncDelivery).toHaveBeenCalledOnce();
      expect(onAsyncDelivery).toHaveBeenCalledWith(
        expect.objectContaining({
          itemId: "async-reconnect",
          text: "Delivered while the client was reconnecting.",
        }),
      );
      const result = projector.buildResult(buildEmptyToolTelemetry());

      expect(result.assistantTexts).toEqual(["Reconnect complete."]);
      expect(
        result.messagesSnapshot.filter(
          (message) =>
            (message as { openclawAsyncDelivery?: { itemId?: unknown } }).openclawAsyncDelivery
              ?.itemId === "async-reconnect",
        ),
      ).toMatchObject([
        {
          role: "assistant",
          content: [{ type: "text", text: "Delivered while the client was reconnecting." }],
          __openclaw: { mirrorIdentity: `${TURN_ID}:async:async-reconnect` },
        },
      ]);
    }
  });
});

import {
  describe,
  registerCodexEventProjectorTestLifecycle,
  expect,
  it,
  vi,
  TURN_ID,
  createParams,
  createProjector,
  buildEmptyToolTelemetry,
  requireRecord,
  requireArray,
  mockCallArg,
  findAgentEvent,
  forCurrentTurn,
  turnCompleted,
} from "./event-projector.test-harness.js";

registerCodexEventProjectorTestLifecycle();

describe("CodexAppServerEventProjector command output projection", () => {
  it("uses streamed command output when final command snapshots omit aggregated output", async () => {
    const onAgentEvent = vi.fn();
    const trajectoryRecorder = {
      filePath: "trajectory.jsonl",
      recordEvent: vi.fn(),
      flush: vi.fn(async () => undefined),
    };
    const projector = await createProjector(
      {
        ...(await createParams()),
        onAgentEvent,
      },
      {
        trajectoryRecorder,
      },
    );

    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-1",
        delta: "status passed\n",
      }),
    );
    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-1",
        delta: "json /tmp/scenario.json\n",
      }),
    );
    await projector.handleNotification(
      turnCompleted([
        {
          type: "commandExecution",
          id: "cmd-1",
          command: "python scripts/run_demo_scenario.py",
          cwd: "/workspace",
          processId: null,
          source: "agent",
          status: "completed",
          commandActions: [],
          aggregatedOutput: null,
          exitCode: 0,
          durationMs: 42,
        },
      ]),
    );

    const result = projector.buildResult(buildEmptyToolTelemetry());
    const toolResultMessage = requireRecord(result.messagesSnapshot[2], "tool result message");
    const toolResultContent = requireArray(toolResultMessage.content, "tool result content");
    const toolResultContentItem = requireRecord(toolResultContent[0], "tool result content item");
    expect(toolResultContentItem.content).toBe("status passed\njson /tmp/scenario.json");
    expect(trajectoryRecorder.recordEvent).toHaveBeenCalledWith(
      "tool.result",
      expect.objectContaining({
        itemId: "cmd-1",
        output: "status passed\njson /tmp/scenario.json",
      }),
    );
    const toolResult = findAgentEvent(onAgentEvent, {
      stream: "tool",
      phase: "result",
      itemId: "cmd-1",
      name: "bash",
    }).data;
    expect(toolResult.result).toEqual({ status: "completed", exitCode: 0, durationMs: 42 });
  });

  it("keeps final command output UTF-16 safe at the transcript limit", async () => {
    const projector = await createProjector();
    // Position the surrogate pair so it straddles the transcript cap: the
    // truncation boundary must drop the whole emoji, never split it in half.
    const prefix = "a".repeat(9_886);
    const aggregatedOutput = `${prefix}😀${"a".repeat(400)}`;

    await projector.handleNotification(
      turnCompleted([
        {
          type: "commandExecution",
          id: "cmd-utf16-final",
          command: "printf output",
          cwd: "/workspace",
          processId: null,
          source: "agent",
          status: "completed",
          commandActions: [],
          aggregatedOutput,
          exitCode: 0,
          durationMs: 42,
        },
      ]),
    );

    const result = projector.buildResult(buildEmptyToolTelemetry());
    const message = requireRecord(result.messagesSnapshot[2], "tool result message");
    const content = requireArray(message.content, "tool result content");
    const item = requireRecord(content[0], "tool result content item");
    expect(item.content).toBe(
      `${prefix}\n...(OpenClaw truncated Codex native tool output: original 10288 chars, showing 10000; rerun with narrower args.)`,
    );
    // A split surrogate would leave a lone code unit behind.
    expect(item.content).not.toMatch(/[\uD800-\uDFFF]/);
  });

  it("keeps streamed command output UTF-16 safe at the transcript limit", async () => {
    const projector = await createProjector();
    // The surrogate pair straddles the transcript cap in the first delta so the
    // bounded prefix must drop the whole emoji rather than split it.
    const prefix = "a".repeat(9_886);

    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-utf16-streamed",
        delta: `${prefix}😀${"a".repeat(400)}`,
      }),
    );
    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-utf16-streamed",
        delta: "must not resurrect a split surrogate",
      }),
    );
    await projector.handleNotification(
      turnCompleted([
        {
          type: "commandExecution",
          id: "cmd-utf16-streamed",
          command: "printf output",
          cwd: "/workspace",
          processId: null,
          source: "agent",
          status: "completed",
          commandActions: [],
          aggregatedOutput: null,
          exitCode: 0,
          durationMs: 42,
        },
      ]),
    );

    const result = projector.buildResult(buildEmptyToolTelemetry());
    const message = requireRecord(result.messagesSnapshot[2], "tool result message");
    const content = requireArray(message.content, "tool result content");
    const item = requireRecord(content[0], "tool result content item");
    // A split surrogate would leave a lone code unit behind; the streamed output
    // must stay well-formed while still carrying the truncation notice.
    expect(item.content).not.toMatch(/[\uD800-\uDFFF]/);
    expect(item.content).toContain("OpenClaw truncated Codex native tool output");
    expect(item.content).toContain("showing 10000");
  });

  it.each([
    { prefixLength: 7_999, delta: "😀tail", expectedChunk: "" },
    { prefixLength: 7_998, delta: "x😀tail", expectedChunk: "x\n" },
  ])(
    "keeps streamed progress UTF-16 safe with $prefixLength chars already emitted",
    async ({ prefixLength, delta, expectedChunk }) => {
      const onToolResult = vi.fn();
      const projector = await createProjector({
        ...(await createParams()),
        verboseLevel: "full",
        onToolResult,
      });

      await projector.handleNotification(
        forCurrentTurn("item/commandExecution/outputDelta", {
          itemId: "cmd-progress-utf16",
          delta: "a".repeat(prefixLength),
        }),
      );
      onToolResult.mockClear();
      await projector.handleNotification(
        forCurrentTurn("item/commandExecution/outputDelta", {
          itemId: "cmd-progress-utf16",
          delta,
        }),
      );

      expect(onToolResult).toHaveBeenCalledTimes(1);
      expect(onToolResult).toHaveBeenCalledWith({
        text: `🛠️ Bash\n\`\`\`txt\n${expectedChunk}...(truncated)...\n\`\`\``,
      });
      const text = (mockCallArg(onToolResult, 0, 0, "onToolResult") as { text?: string }).text;
      expect(text).not.toMatch(
        /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/u,
      );
    },
  );

  it("freezes streamed raw prefix after UTF-16-safe truncation so full-output echoes stay suppressed", async () => {
    const projector = await createProjector();
    // First over-cap delta ends mid-surrogate: truncateUtf16Safe backs up and
    // leaves spare capacity under the notice budget. Later deltas must not fill it.
    const prefix = "a".repeat(9_886);
    const firstDelta = `${prefix}😀${"a".repeat(400)}`;
    const moreDeltas = ["more-after-cap-1", "more-after-cap-2", "tail-chunk"];
    const fullOutput = `${firstDelta}${moreDeltas.join("")}`;

    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-freeze-prefix",
        delta: firstDelta,
      }),
    );
    for (const delta of moreDeltas) {
      await projector.handleNotification(
        forCurrentTurn("item/commandExecution/outputDelta", {
          itemId: "cmd-freeze-prefix",
          delta,
        }),
      );
    }

    const echoState = (
      projector as unknown as {
        toolProgressProjection: {
          echoesByItem: Map<string, { streamedRawSignature?: { length: number; prefix: string } }>;
        };
      }
    ).toolProgressProjection.echoesByItem;
    const state = echoState.get("cmd-freeze-prefix");
    expect(state?.streamedRawSignature).toBeDefined();
    expect(fullOutput.startsWith(state!.streamedRawSignature!.prefix)).toBe(true);
    expect(state!.streamedRawSignature!.length).toBe(fullOutput.length);

    await projector.handleNotification(
      forCurrentTurn("rawResponseItem/completed", {
        item: {
          type: "message",
          id: "raw-freeze-full-output",
          role: "assistant",
          content: [{ type: "output_text", text: fullOutput }],
        },
      }),
    );
    await projector.handleNotification(
      turnCompleted([
        {
          type: "commandExecution",
          id: "cmd-freeze-prefix",
          command: "printf output",
          cwd: "/workspace",
          processId: null,
          source: "agent",
          status: "completed",
          commandActions: [],
          aggregatedOutput: null,
          exitCode: 0,
          durationMs: 42,
        },
      ]),
    );

    const result = projector.buildResult(buildEmptyToolTelemetry());
    expect(result.assistantTexts).toEqual([]);
    expect(result.lastAssistant).toBeUndefined();
    expect(result.currentAttemptAssistant).toBeUndefined();
  });

  it("keeps streaming after output text includes the truncation notice prefix", async () => {
    const trajectoryRecorder = {
      filePath: "trajectory.jsonl",
      recordEvent: vi.fn(),
      flush: vi.fn(async () => undefined),
    };
    const projector = await createProjector(await createParams(), {
      trajectoryRecorder,
    });
    const userOutputWithNotice =
      "...(OpenClaw truncated Codex native tool output is a literal line from the process)\n";

    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-notice-prefix",
        delta: userOutputWithNotice,
      }),
    );
    await projector.handleNotification(
      forCurrentTurn("item/commandExecution/outputDelta", {
        itemId: "cmd-notice-prefix",
        delta: "second line must survive\n",
      }),
    );
    await projector.handleNotification(
      turnCompleted([
        {
          type: "commandExecution",
          id: "cmd-notice-prefix",
          command: "python scripts/run_demo_scenario.py",
          cwd: "/workspace",
          processId: null,
          source: "agent",
          status: "completed",
          commandActions: [],
          aggregatedOutput: null,
          exitCode: 0,
          durationMs: 42,
        },
      ]),
    );

    const result = projector.buildResult(buildEmptyToolTelemetry());
    const toolResultMessage = requireRecord(result.messagesSnapshot[2], "tool result message");
    const toolResultContent = requireArray(toolResultMessage.content, "tool result content");
    const toolResultContentItem = requireRecord(toolResultContent[0], "tool result content item");
    expect(toolResultContentItem.content).toBe(`${userOutputWithNotice}second line must survive`);
    expect(trajectoryRecorder.recordEvent).toHaveBeenCalledWith(
      "tool.result",
      expect.objectContaining({
        itemId: "cmd-notice-prefix",
        output: `${userOutputWithNotice}second line must survive`,
      }),
    );
  });

  it("does not parse user output as a prior truncation notice when streaming crosses the cap", async () => {
    const trajectoryRecorder = {
      filePath: "trajectory.jsonl",
      recordEvent: vi.fn(),
      flush: vi.fn(async () => undefined),
    };
    const projector = await createProjector(await createParams(), {
      trajectoryRecorder,
    });
    const userOutputWithNotice =
