      terminalType: "completed",
      contentItems: [{ type: "inputText", text: "ok" }],
    });

    expect(projector.buildResult(buildEmptyToolTelemetry()).lastToolError).toBeUndefined();
  });

  it.each([
    {
      command: "/bin/zsh -lc 'rg -n TODO src'",
