import type { AgentHarnessV2 } from "openclaw/plugin-sdk/agent-harness-runtime";
import { resolveCodexAppServerPreparedAuthHandoff } from "./auth-bridge.js";
import { runBoundedCodexAppServerTurn, type CodexBoundedTurnOptions } from "./bounded-turn.js";
import { readCodexPluginConfig, resolveCodexAppServerHomeScope } from "./config.js";
import { createAttributedCodexAssistantMessage } from "./event-projector-assistant-message.js";
import { isJsonObject, type CodexThreadItem } from "./protocol.js";

const ISOLATED_PASSIVE_ITEM_TYPES = new Set(["agentMessage", "reasoning"]);

type CodexIsolatedCompletionParams = Parameters<
  NonNullable<AgentHarnessV2["runIsolatedCompletionV2"]>
>[0];
type AgentHarnessIsolatedCompletionResult = Awaited<
  ReturnType<NonNullable<AgentHarnessV2["runIsolatedCompletionV2"]>>
>;

function assertIsolatedCompletionItems(items: CodexThreadItem[], prompt: string): void {
  let promptEchoSeen = false;
  for (const item of items) {
    if (ISOLATED_PASSIVE_ITEM_TYPES.has(item.type)) {
      continue;
    }
    if (item.type === "userMessage" && !promptEchoSeen) {
      const content = Array.isArray(item.content) ? item.content : [];
      const input = content[0];
      if (
        content.length === 1 &&
        isJsonObject(input) &&
        input.type === "text" &&
        input.text === prompt
      ) {
        promptEchoSeen = true;
        continue;
      }
    }
    throw new Error(`Codex isolated completion returned unexpected native item: ${item.type}`);
  }
}

/** Runs prompt-only Codex inference on an ephemeral, ring-zero native thread. */
export async function runCodexIsolatedCompletion(
  params: CodexIsolatedCompletionParams,
  options: CodexBoundedTurnOptions,
): Promise<AgentHarnessIsolatedCompletionResult> {
  const authorization = params.authorization;
  if (authorization.owner !== "harness") {
    throw new Error("Codex native isolated completion requires harness-owned authorization.");
  }
  const pluginConfig = readCodexPluginConfig(options.pluginConfig);
  const authRequirement = authorization.plan.modelRoute?.authRequirement;
  const authHandoff = await resolveCodexAppServerPreparedAuthHandoff({
    authRequirement,
    authProfileId: authorization.plan.forwardedAuthProfileId,
    authProfileStore: authorization.authProfileStore,
    agentDir: params.agentDir,
    homeScope: resolveCodexAppServerHomeScope({ appServer: pluginConfig.appServer }),
    config: params.config,
    subscriptionProfileRequiredError:
      "Prepared Codex subscription route requires a scoped native OAuth or token profile.",
    subscriptionProfileUnusableError: `Prepared Codex auth profile "${authorization.plan.forwardedAuthProfileId}" is unusable.`,
  });
  const authSelection = authHandoff.preparedAuth
    ? { preparedAuth: authHandoff.preparedAuth }
    : { profile: authHandoff.authProfileId };
  const result = await runBoundedCodexAppServerTurn({
    config: params.config,
    model: {
      mode: "required",
      id: params.modelId,
    },
    ...authSelection,
    authRequirement,
    timeoutMs: params.timeoutMs,
    signal: params.abortSignal,
    agentDir: params.agentDir,
    authProfileStore: authorization.authProfileStore,
    options,
    taskLabel: "isolated completion",
    developerInstructions: params.systemPrompt,
    input: [{ type: "text", text: params.prompt, text_elements: [] }],
    requiredModalities: ["text"],
    isolation: "configured-transport",
    requireNoExternalCapabilities: true,
  });
  assertIsolatedCompletionItems(result.items, params.prompt);
  return {
    assistant: createAttributedCodexAssistantMessage(
      {
        api: "openai-chatgpt-responses",
        provider: params.provider,
        modelId: result.model,
      },
      result.text,
      { tokenUsage: result.usage, aborted: false, promptError: null },
    ),
  };
}

// Single-value root/app-server options from the pinned Codex CLI, shared_options,
// tui/cli, transport/auth, and code_mode_host. Values are never subcommands.
const CODEX_VALUE_OPTIONS = new Set([
  "-m",
  "--model",
  "--local-provider",
  "-p",
  "--profile",
  "-s",
  "--sandbox",
  "-a",
  "--ask-for-approval",
  "-C",
  "--cd",
  "--add-dir",
  "--remote",
  "--remote-auth-token-env",
  "-c",
  "--config",
  "--enable",
  "--disable",
  "--listen",
  "--code-mode-host",
  "--ws-auth",
  "--ws-token-file",
  "--ws-token-sha256",
  "--ws-shared-secret-file",
  "--ws-issuer",
  "--ws-audience",
  "--ws-max-clock-skew-seconds",
]);

type CodexArg = { index: number; end: number; name: string; value?: string };

/** One tokenization owner for launch, turn policy, reviewer trust, and private turns. */
function readCodexArgs(args: readonly string[]): CodexArg[] {
  const tokens: CodexArg[] = [];
  let nativeSubcommand = false;
  let end = 0;
  for (const [index, arg] of args.entries()) {
    if (index < end) {
      continue;
    }
    end = index + 1;
    const attached = /^(--[^=]+)=([\s\S]*)$/u.exec(arg) ?? /^(-[cmpisaC])=?([\s\S]+)$/u.exec(arg);
    const name = attached?.[1] ?? arg;
    let value = attached?.[2];
    if (name === "-i" || name === "--image") {
      // Native image arguments consume multiple paths, even one named app-server.
      while (args[end]?.startsWith("-") === false) {
        end += 1;
      }
    } else if (!attached && CODEX_VALUE_OPTIONS.has(name)) {
      value = args[end];
      if (value !== undefined) {
        end += 1;
      }
    }
    tokens.push({ index, end, name, value });
    if (name === "app-server") {
      nativeSubcommand = true;
    }
    // A prefix -- may belong to a shell wrapper. After app-server it is native.
    if (name === "--" && nativeSubcommand) {
      break;
    }
  }
  return tokens;
}

export function readCodexAppServerConfigOptions(args: readonly string[]) {
  return readCodexArgs(args).filter(
    ({ name }) => name === "-c" || name === "--config" || name === "-p" || name === "--profile",
  );
}

/** Keeps Codex overrides in one CLI scope without rewriting raw TOML or wrapper prefixes. */
export function normalizeCodexAppServerArgs(
  rawArgs: string[],
  enforcedOverride?: string,
): string[] {
  const tokens = readCodexArgs(rawArgs);
  const subcommandIndex = tokens.findLast(({ name }) => name === "app-server")?.index ?? -1;
  const prefix = subcommandIndex < 0 ? [...rawArgs] : rawArgs.slice(0, subcommandIndex);
  const suffix: string[] = [];
  if (subcommandIndex >= 0) {
    // clap replaces root global Append values when a suffix config flag exists.
    // Move only native suffix overrides, retaining their original order and bytes.
    for (const token of tokens) {
      if (token.index <= subcommandIndex) {
        continue;
      }
      if (token.name === "--") {
        suffix.push(...rawArgs.slice(token.index));
        break;
      }
      const target = token.name === "-c" || token.name === "--config" ? prefix : suffix;
      target.push(...rawArgs.slice(token.index, token.end));
    }
  }
  if (enforcedOverride && !(prefix.at(-2) === "-c" && prefix.at(-1) === enforcedOverride)) {
    prefix.push("-c", enforcedOverride);
  }
  const normalized = subcommandIndex < 0 ? prefix : [...prefix, "app-server", ...suffix];
  return normalized.length === rawArgs.length &&
    normalized.every((arg, index) => arg === rawArgs[index])
    ? rawArgs
    : normalized;
}

/**
 * Resolves the provider/api attribution used when a local Codex runtime is
 * backed by OpenAI auth but should still report Codex Responses semantics.
 */
import type { AgentHarnessAttemptParamsV2 } from "openclaw/plugin-sdk/agent-harness-runtime";
import { normalizeLowercaseStringOrEmpty as normalizeRuntimeId } from "openclaw/plugin-sdk/string-coerce-runtime";

export type CodexLocalRuntimeAttributionParams = Pick<
  AgentHarnessAttemptParamsV2,
  "model" | "provider" | "runtimePlan"
>;

const OPENAI_PROVIDER_ID = "openai";
const OPENAI_RESPONSES_API = "openai-responses";
const OPENAI_CODEX_RESPONSES_API = "openai-chatgpt-responses";

/** Provider identity that downstream telemetry should attribute to the local Codex turn. */
type CodexLocalRuntimeAttribution = {
  provider: string;
  api?: string;
};

/** Maps local Codex runtime plans onto the provider/api pair exposed to event projection. */
export function resolveCodexLocalRuntimeAttribution(
  params: CodexLocalRuntimeAttributionParams,
): CodexLocalRuntimeAttribution {
  const authProfileProvider = normalizeRuntimeId(
    params.runtimePlan?.auth?.authProfileProviderForAuth,
  );
  if (
    normalizeRuntimeId(params.runtimePlan?.observability.harnessId) === "codex" &&
    authProfileProvider !== OPENAI_PROVIDER_ID &&
    normalizeRuntimeId(params.model.provider) === OPENAI_PROVIDER_ID &&
    normalizeRuntimeId(params.model.api) === OPENAI_RESPONSES_API
  ) {
    return {
      provider: OPENAI_PROVIDER_ID,
      api: OPENAI_CODEX_RESPONSES_API,
    };
  }

  return {
    provider: params.provider,
    api: params.model.api,
  };
}

