/** Records the process-stable plugin root prepared by OpenClaw's plugin loader. */
export function setManagedCodexPluginRoot(pluginRoot: string | undefined): void {
  registeredCodexPluginRoot = pluginRoot;
}

/** Rewrites managed stdio start options to point at an executable Codex binary path. */
export async function resolveManagedCodexAppServerStartOptions(
  startOptions: CodexAppServerStartOptions,
  options: ResolveManagedCodexAppServerOptions = {},
): Promise<CodexAppServerStartOptions> {
  if (startOptions.transport !== "stdio" || startOptions.commandSource !== "managed") {
    return startOptions;
  }

  const platform = options.platform ?? process.platform;
  const candidateCommandPaths = resolveManagedCodexAppServerCommandCandidates(
    options.pluginRoot ?? registeredCodexPluginRoot ?? CODEX_PLUGIN_ROOT,
    platform,
    startOptions.managedCommandOrder ?? "package-first",
  );
  const pathExists = options.pathExists ?? commandPathExists;
  const commandPaths = await findManagedCodexAppServerCommandPaths({
    candidateCommandPaths,
    pathExists,
    platform,
  });
  const commandPath = expectDefined(commandPaths[0], "resolved managed Codex command path");
  const managedFallbackCommandPaths = commandPaths.slice(1);

  return {
    ...startOptions,
    command: commandPath,
    commandSource: "resolved-managed",
    ...(managedFallbackCommandPaths.length > 0 ? { managedFallbackCommandPaths } : {}),
  };
}

/** Resolves the native artifact behind a successful managed launcher selection. */
export function resolveManagedCodexNativeCommand(
  command: string,
  options: ResolveManagedCodexNativeCommandOptions = {},
): string | undefined {
  const platform = options.platform ?? process.platform;
  if (isManagedCodexDesktopCommand(command, platform)) {
    return command;
  }
  const target = resolveCodexNativeTarget(platform, options.arch ?? process.arch);
  if (!target) {
    return undefined;
  }
  const packageRoot = resolveManagedCodexPackageRootForCommand(command, platform);
  if (!packageRoot) {
    return undefined;
  }
  const resolvePackageJson = options.resolvePackageJson ?? resolvePackageJsonFromRoot;
  const pathExists = options.pathExists ?? existsSync;
  for (const packageName of [target.packageName, MANAGED_CODEX_APP_SERVER_PACKAGE]) {
    const packageJsonPath = resolvePackageJson(packageName, packageRoot);
    if (!packageJsonPath) {
      continue;
    }
    const candidate = path.join(
      path.dirname(packageJsonPath),
      "vendor",
      target.triple,
      "bin",
      platform === "win32" ? "codex.exe" : "codex",
    );
    if (pathExists(candidate)) {
      return candidate;
    }
  }
  return undefined;
}

/** Returns whether a command is one of the standard macOS desktop app executables. */
export function isManagedCodexDesktopCommand(
  command: string,
  platform: NodeJS.Platform = process.platform,
): boolean {
  return (
    platform === "darwin" &&
    resolveMacOSDesktopCodexAppServerCommandCandidates(platform).some(
      (candidate) => candidate === command,
    )
  );
}

function resolveManagedCodexPackageRootForCommand(
  command: string,
  platform: NodeJS.Platform,
): string | undefined {
  const pathApi = pathForPlatform(platform);
  const commandPaths = [command];
  try {
    commandPaths.unshift(realpathSync(command));
  } catch {
    // Lexical .bin shims still identify their adjacent package root.
  }
  for (const commandPath of commandPaths) {
    let current = pathApi.dirname(commandPath);
    while (true) {
      if (
        pathApi.basename(current) === "codex" &&
        pathApi.basename(pathApi.dirname(current)) === "@openai"
      ) {
        return current;
      }
      if (pathApi.basename(current) === ".bin") {
        return pathApi.join(pathApi.dirname(current), "@openai", "codex");
      }
      const parent = pathApi.dirname(current);
      if (parent === current) {
        break;
      }
      current = parent;
    }
  }
  return undefined;
}

function resolveCodexNativeTarget(
  platform: NodeJS.Platform,
  arch: NodeJS.Architecture,
): { packageName: string; triple: string } | undefined {
  // Mirrors @openai/codex's launcher mapping; this resolves identity only and
  // leaves process environment/launch behavior with the upstream entrypoint.
  if ((platform === "linux" || platform === "android") && arch === "x64") {
    return { packageName: "@openai/codex-linux-x64", triple: "x86_64-unknown-linux-musl" };
  }
  if ((platform === "linux" || platform === "android") && arch === "arm64") {
    return { packageName: "@openai/codex-linux-arm64", triple: "aarch64-unknown-linux-musl" };
  }
  if (platform === "darwin" && arch === "x64") {
    return { packageName: "@openai/codex-darwin-x64", triple: "x86_64-apple-darwin" };
  }
  if (platform === "darwin" && arch === "arm64") {
    return { packageName: "@openai/codex-darwin-arm64", triple: "aarch64-apple-darwin" };
  }
  if (platform === "win32" && arch === "x64") {
    return { packageName: "@openai/codex-win32-x64", triple: "x86_64-pc-windows-msvc" };
  }
  if (platform === "win32" && arch === "arm64") {
    return { packageName: "@openai/codex-win32-arm64", triple: "aarch64-pc-windows-msvc" };
  }
  return undefined;
}

function resolvePackageJsonFromRoot(packageName: string, root: string): string | undefined {
  try {
    return createRequire(path.join(root, "package.json")).resolve(`${packageName}/package.json`);
  } catch {
    return undefined;
  }
}

function resolveManagedCodexAppServerCommandCandidates(
  pluginRoot: string,
  platform: NodeJS.Platform,
  managedCommandOrder: CodexManagedCommandOrder,
): string[] {
  const pathApi = pathForPlatform(platform);
  const commandName = platform === "win32" ? "codex.cmd" : "codex";
  const roots = resolveManagedCodexAppServerCandidateRoots(pluginRoot, platform);
  const packageCommandPaths = [
    ...roots.map((root) => pathApi.join(root, "node_modules", ".bin", commandName)),
    ...resolveManagedCodexPackageBinCandidates(roots, platform),
  ];
  const desktopCommandPaths = resolveDesktopCodexAppServerCommandCandidates(platform);
  // Ordinary turns must honor the pinned package version. Computer Use opts
  // into the desktop app owner because its macOS TCC permissions live there.
  const orderedCommandPaths =
    managedCommandOrder === "desktop-first"
      ? [...desktopCommandPaths, ...packageCommandPaths]
      : [...packageCommandPaths, ...desktopCommandPaths];
  return [...new Set(orderedCommandPaths)];
}

function resolveDesktopCodexAppServerCommandCandidates(platform: NodeJS.Platform): string[] {
  return resolveMacOSDesktopCodexAppServerCommandCandidates(platform);
}

function resolveDefaultCodexPluginRoot(moduleDir: string): string {
  const moduleBaseName = path.basename(moduleDir);
  if (moduleBaseName === "dist" || moduleBaseName === "dist-runtime") {
    return path.dirname(moduleDir);
  }
  return path.resolve(moduleDir, "..", "..");
}

function resolveManagedCodexAppServerCandidateRoots(
  pluginRoot: string,
  platform: NodeJS.Platform,
): string[] {
  const pathApi = pathForPlatform(platform);
  const directRoots = [
    pluginRoot,
    pathApi.dirname(pluginRoot),
    pathApi.dirname(pathApi.dirname(pluginRoot)),
    isDistExtensionRoot(pluginRoot, platform)
      ? pathApi.dirname(pathApi.dirname(pathApi.dirname(pluginRoot)))
      : null,
  ].filter((root): root is string => Boolean(root));
  return [
    ...new Set([...directRoots, ...resolveNearestNodeModulesProjectRoots(directRoots, platform)]),
  ];
}

function resolveNearestNodeModulesProjectRoots(
  roots: readonly string[],
  platform: NodeJS.Platform,
): string[] {
  const pathApi = pathForPlatform(platform);
  const projectRoots: string[] = [];
  for (const root of roots) {
    let current = pathApi.resolve(root);
    while (true) {
      if (pathApi.basename(current) === "node_modules") {
        projectRoots.push(pathApi.dirname(current));
        break;
      }
      const parent = pathApi.dirname(current);
      if (parent === current) {
        break;
      }
      current = parent;
    }
  }
  return projectRoots;
}

function resolveManagedCodexPackageBinCandidates(
  roots: readonly string[],
  platform: NodeJS.Platform,
): string[] {
  if (platform === "win32") {
    return [];
  }

  const candidates: string[] = [];
  for (const root of roots) {
    const candidate = resolveManagedCodexPackageBinCandidate(root);
    if (candidate) {
      candidates.push(candidate);
    }
  }
  return candidates;
}

function resolveManagedCodexPackageBinCandidate(root: string): string | null {
  try {
    const requireFromRoot = createRequire(path.join(root, "package.json"));
    const packageJsonPath = requireFromRoot.resolve(
      `${MANAGED_CODEX_APP_SERVER_PACKAGE}/package.json`,
    );
    const packageRoot = path.dirname(packageJsonPath);
    const packageJson = JSON.parse(readFileSync(packageJsonPath, "utf8")) as {
      bin?: unknown;
    };
    const packageBin =
      packageJson.bin && typeof packageJson.bin === "object"
        ? (packageJson.bin as Record<string, unknown>)
        : undefined;
    const binPath =
      typeof packageJson.bin === "string"
        ? packageJson.bin
        : typeof packageBin?.codex === "string"
          ? packageBin.codex
          : null;
    return binPath ? path.resolve(packageRoot, binPath) : null;
  } catch {
    return null;
  }
}

function isDistExtensionRoot(pluginRoot: string, platform: NodeJS.Platform): boolean {
  const pathApi = pathForPlatform(platform);
  const extensionsDir = pathApi.dirname(pluginRoot);
  const distDir = pathApi.dirname(extensionsDir);
  return (
    pathApi.basename(extensionsDir) === "extensions" &&
    (pathApi.basename(distDir) === "dist" || pathApi.basename(distDir) === "dist-runtime")
  );
}

function pathForPlatform(platform: NodeJS.Platform): typeof path {
  return platform === "win32" ? path.win32 : path.posix;
}

async function findManagedCodexAppServerCommandPaths(params: {
  candidateCommandPaths: readonly string[];
  pathExists: (filePath: string, platform: NodeJS.Platform) => Promise<boolean>;
  platform: NodeJS.Platform;
}): Promise<string[]> {
  const commandPaths: string[] = [];
  for (const commandPath of params.candidateCommandPaths) {
    if (await params.pathExists(commandPath, params.platform)) {
      commandPaths.push(commandPath);
    }
  }
  if (commandPaths.length > 0) {
    return commandPaths;
  }

  throw new Error(
    [
      `Managed Codex app-server binary was not found for ${MANAGED_CODEX_APP_SERVER_PACKAGE}.`,
      "Reinstall or update OpenClaw, or run pnpm install in a source checkout.",
      "Set plugins.entries.codex.config.appServer.command or OPENCLAW_CODEX_APP_SERVER_BIN to use a custom Codex binary.",
    ].join(" "),
  );
}

async function commandPathExists(filePath: string, platform: NodeJS.Platform): Promise<boolean> {
  try {
    await access(filePath, platform === "win32" ? fsConstants.F_OK : fsConstants.X_OK);
    return true;
  } catch {
    return false;
  }
}

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import type { PluginStateSyncKeyedStore } from "openclaw/plugin-sdk/plugin-state-runtime";
import { describe, expect, it } from "vitest";
import { codexCatalogHomeId } from "../session-catalog-home-id.js";
import {
  createCodexManagedThreadStore,
  type StoredCodexManagedThread,
} from "./managed-thread-store.js";

function createStateStore() {
  const values = new Map<string, StoredCodexManagedThread>();
  const state: Pick<
    PluginStateSyncKeyedStore<StoredCodexManagedThread>,
    "entries" | "lookup" | "registerIfAbsent"
  > = {
    registerIfAbsent(key, value) {
      if (values.has(key)) {
        return false;
      }
      values.set(key, value);
      return true;
    },
    lookup: (key) => values.get(key),
    entries: () => [...values].map(([key, value]) => ({ key, value, createdAt: 0 })),
  };
  return { state, values };
}

describe("Codex managed thread store", () => {
  it("records one durable ownership row per home and thread", async () => {
    const { state, values } = createStateStore();
    const store = createCodexManagedThreadStore(state);
    const sourceHomeId = codexCatalogHomeId("/tmp/codex-home");

    await store.mark({ sourceHomeId, threadId: "thread-1", rolloutPath: "/rollout.jsonl" });
    await store.mark({ sourceHomeId, threadId: "thread-1", rolloutPath: "/new-path.jsonl" });

    await expect(store.has(sourceHomeId, "thread-1")).resolves.toBe(true);
    await expect(store.has("other-home", "thread-1")).resolves.toBe(false);
    await expect(store.has(sourceHomeId, "missing-thread")).resolves.toBe(false);
    expect(values.size).toBe(1);
    expect([...values.values()][0]).toMatchObject({
      kind: "managed-thread",
      sourceHomeId,
      threadId: "thread-1",
      rolloutPath: "/rollout.jsonl",
    });
    await expect(store.snapshot()).resolves.toEqual(
      new Map([[sourceHomeId, new Set(["thread-1"])]]),
    );
  });

  it("ignores malformed rows when building a snapshot", async () => {
    const { state, values } = createStateStore();
    values.set("malformed", {
      version: 1,
      kind: "managed-thread",
    } as unknown as StoredCodexManagedThread);

    await expect(createCodexManagedThreadStore(state).snapshot()).resolves.toEqual(new Map());
  });

  it("uses the same source identity for a symlinked configured home", async () => {
    const root = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), "codex-home-id-")));
    try {
      const home = path.join(root, "home");
      const alias = path.join(root, "alias");
      await fs.mkdir(home);
      await fs.symlink(home, alias, process.platform === "win32" ? "junction" : "dir");

      expect(codexCatalogHomeId(alias)).toBe(codexCatalogHomeId(home));
    } finally {
      await fs.rm(root, { recursive: true, force: true });
    }
  });
});

import { createHash } from "node:crypto";
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { PluginStateSyncKeyedStore } from "openclaw/plugin-sdk/plugin-state-runtime";
import { z } from "zod";

export const CODEX_MANAGED_THREAD_NAMESPACE = "app-server-managed-threads";
export const CODEX_MANAGED_THREAD_MAX_ENTRIES = 20_000;

const managedThreadSchema = z.object({
  version: z.literal(1),
  kind: z.literal("managed-thread"),
  sourceHomeId: z.string().min(1),
  threadId: z.string().min(1),
  rolloutPath: z.string().min(1).optional(),
});

export type StoredCodexManagedThread = z.infer<typeof managedThreadSchema>;

export type CodexManagedThreadStore = {
  has(sourceHomeId: string, threadId: string): Promise<boolean>;
  mark(params: { sourceHomeId: string; threadId: string; rolloutPath?: string }): Promise<boolean>;
  snapshot(): Promise<ReadonlyMap<string, ReadonlySet<string>>>;
};

export async function markStartedCodexManagedThread(
  store: CodexManagedThreadStore | undefined,
  params: { sourceHomeId: string; rolloutPath?: string; threadId: string },
): Promise<void> {
  if (!store) {
    return;
  }
  try {
    await store.mark({
      sourceHomeId: params.sourceHomeId,
      threadId: params.threadId,
      ...(params.rolloutPath ? { rolloutPath: params.rolloutPath } : {}),
    });
  } catch (error) {
    // Keep this boundary fail-open even for a custom or legacy store implementation.
    // A catalog duplicate is less harmful than rejecting an otherwise valid new session.
    embeddedAgentLog.warn("failed to record Codex managed thread ownership", { error });
  }
}

function managedThreadStoreKey(sourceHomeId: string, threadId: string): string {
  return `sha256:${createHash("sha256")
    .update("openclaw:codex-managed-thread:v1\0")
    .update(sourceHomeId)
    .update("\0")
    .update(threadId)
    .digest("hex")}`;
}

/** Durable ownership index for Codex threads created by OpenClaw. */
export function createCodexManagedThreadStore(
  state: Pick<
    PluginStateSyncKeyedStore<StoredCodexManagedThread>,
    "entries" | "lookup" | "registerIfAbsent"
  >,
): CodexManagedThreadStore {
  return {
    async has(sourceHomeId, threadId) {
      const parsed = managedThreadSchema.safeParse(
        state.lookup(managedThreadStoreKey(sourceHomeId, threadId)),
      );
      return (
        parsed.success &&
        parsed.data.sourceHomeId === sourceHomeId &&
        parsed.data.threadId === threadId
      );
    },
    async mark(params) {
      try {
        const value = managedThreadSchema.parse({
          version: 1,
          kind: "managed-thread",
          sourceHomeId: params.sourceHomeId.trim(),
          threadId: params.threadId.trim(),
          ...(params.rolloutPath?.trim() ? { rolloutPath: params.rolloutPath.trim() } : {}),
        });
        state.registerIfAbsent(managedThreadStoreKey(value.sourceHomeId, value.threadId), value);
        return true;
      } catch (error) {
        // Catalog ownership is advisory bookkeeping. Losing an old catalog exclusion is safer
        // than aborting a real Codex session start when plugin state is full or unavailable.
        embeddedAgentLog.warn("failed to record Codex managed thread ownership", { error });
        return false;
      }
    },
    async snapshot() {
      const byHome = new Map<string, Set<string>>();
      for (const entry of state.entries()) {
        const parsed = managedThreadSchema.safeParse(entry.value);
        if (!parsed.success) {
          continue;
        }
        const ids = byHome.get(parsed.data.sourceHomeId) ?? new Set<string>();
        ids.add(parsed.data.threadId);
        byHome.set(parsed.data.sourceHomeId, ids);
      }
      return byHome;
    },
  };
}

import {
  asOptionalRecord,
  normalizeOptionalString,
} from "openclaw/plugin-sdk/string-coerce-runtime";

/** Hosted app ownership is authoritative only on metadata supplied by Codex. */
export function readCodexMcpToolConnectorId(tool: unknown): string | undefined {
  const metadata = asOptionalRecord(asOptionalRecord(tool)?.["_meta"]);
  return (
    normalizeOptionalString(metadata?.connector_id) ??
    normalizeOptionalString(metadata?.connectorId)
  );
}

/** Preserve MCP App visibility so model-only tools cannot become widget authority. */
export function readCodexMcpToolUiVisibility(tool: unknown): Array<"app" | "model"> | undefined {
  const metadata = asOptionalRecord(asOptionalRecord(tool)?.["_meta"]);
  const visibility = asOptionalRecord(metadata?.ui)?.visibility;
  if (!Array.isArray(visibility)) {
    return undefined;
  }
  return [
    ...new Set(
      visibility.filter((value): value is "app" | "model" => value === "app" || value === "model"),
    ),
  ].toSorted();
}

import { createDeferred } from "openclaw/plugin-sdk/extension-shared";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { createCodexAppServerModelCatalog } from "./model-catalog.js";
import { listAllCodexAppServerModels } from "./models.js";
import { withCodexAppServerJsonClient } from "./request.js";

vi.mock("./models.js", () => ({
  listAllCodexAppServerModels: vi.fn(),
}));

const rpc = vi.hoisted(() => ({ request: vi.fn(), epoch: 0, client: {} }));
vi.mock("./request.js", () => ({
  withCodexAppServerJsonClient: vi.fn(
    (_options: unknown, run: (request: unknown, client: unknown) => unknown) =>
      run(rpc.request, rpc.client),
  ),
}));
vi.mock("./shared-client.js", () => ({
  captureSharedCodexAppServerCatalogLifetime: () => {
    const epoch = rpc.epoch;
    return () => rpc.epoch === epoch;
  },
}));
let owner: ReturnType<typeof createCodexAppServerModelCatalog>;
const loadCodexAppServerModelCatalog = (...args: Parameters<typeof owner.load>) =>
  owner.load(...args);
const read = (overrides = {}) =>
  owner.read(
    { ...catalogParams, provider: "openai", modelId: "synthetic-opaque", ...overrides },
    undefined,
  );
const listModelsMock = vi.mocked(listAllCodexAppServerModels);

const catalogParams = {
  config: {},
  agentId: "main",
  agentDir: "/tmp/main-agent",
  workspaceDir: "/tmp/workspace",
};

describe("Codex app-server model catalog", () => {
  beforeEach(() => {
    listModelsMock.mockReset();
    vi.mocked(withCodexAppServerJsonClient).mockClear();
    rpc.epoch += 1;
    rpc.request
      .mockReset()
      .mockResolvedValue({ account: { type: "apiKey" }, requiresOpenaiAuth: true });
    owner = createCodexAppServerModelCatalog("codex");
  });

  it("keeps native picker models independent of a host transport", async () => {
    listModelsMock.mockResolvedValue({
      models: [
        {
          id: "gpt-5.6-sol",
          model: "codex-execution-model",
          displayName: "GPT-5.6 Sol",
          inputModalities: ["text", "image", "unknown"],
          supportedReasoningEfforts: ["low", "medium", "high", "xhigh", "max", "ultra"],
        },
        {
          id: "gpt-5.6-luna",
          model: "gpt-5.6-luna",
          displayName: "GPT-5.6 Luna",
          inputModalities: ["text"],
          supportedReasoningEfforts: [],
        },
      ],
    });
    const catalog = await loadCodexAppServerModelCatalog(catalogParams, undefined);
    expect(catalog).toEqual([
      {
        provider: "openai",
        nativeRuntime: "codex",
        id: "gpt-5.6-sol",
        name: "GPT-5.6 Sol",
        providerOrder: 0,
        reasoning: true,
        input: ["text", "image"],
        params: { codexAppServerRuntimeModel: "codex-execution-model" },
        compat: {
          supportsReasoningEffort: true,
          supportedReasoningEfforts: ["low", "medium", "high", "xhigh", "max", "ultra"],
        },
      },
      {
        provider: "openai",
        nativeRuntime: "codex",
        id: "gpt-5.6-luna",
        name: "GPT-5.6 Luna",
        providerOrder: 1,
        reasoning: false,
        input: ["text"],
        compat: {
          supportsReasoningEffort: false,
          supportedReasoningEfforts: [],
        },
      },
    ]);
    expect(listModelsMock).toHaveBeenCalledExactlyOnceWith({ request: rpc.request, limit: 100 });
  });

  it("returns no rows without a live call when discovery is disabled", async () => {
    expect(
      await loadCodexAppServerModelCatalog(catalogParams, { discovery: { enabled: false } }),
    ).toEqual([]);
    expect(listModelsMock).not.toHaveBeenCalled();
  });

  it("bounds the live call with the configured discovery timeout", async () => {
    listModelsMock.mockResolvedValue({ models: [] });
    await loadCodexAppServerModelCatalog(catalogParams, { discovery: { timeoutMs: 750 } });
    expect(withCodexAppServerJsonClient).toHaveBeenCalledExactlyOnceWith(
      expect.objectContaining({ timeoutMs: 750 }),
      expect.any(Function),
    );
  });
  it.each([
    { account: { type: "apiKey" }, mode: "apiKey" },
    {
      account: { type: "chatgpt", email: "synthetic@example.test", planType: "plus" },
      mode: "chatgpt",
    },
    { account: null, mode: undefined },
  ])("preserves account mode $mode without importing credentials", async ({ account, mode }) => {
    listModelsMock.mockResolvedValue({
      models: [
        {
          id: "synthetic-opaque",
          model: "synthetic-opaque",
          inputModalities: ["text"],
          supportedReasoningEfforts: [],
        },
      ],
    });
    rpc.request.mockResolvedValue({ account, requiresOpenaiAuth: true });
    await owner.load(catalogParams, undefined);
    expect(read()).toEqual(mode ? { accountType: mode } : undefined);
    expect(read({ agentId: "another" })).toBeUndefined();
    expect(read({ agentDir: "/tmp/another-agent" })).toBeUndefined();
    expect(read({ workspaceDir: "/tmp/another-workspace" })).toBeUndefined();
    expect(read({ config: { ...catalogParams.config } })).toBeUndefined();
    expect(read({ modelId: "unlisted" })).toBeUndefined();
    expect(read({ provider: "another" })).toBeUndefined();
    expect(
      owner.read({ ...catalogParams, provider: "openai", modelId: "synthetic-opaque" }, {}),
    ).toBeUndefined();
    rpc.epoch += 1;
    expect(read()).toBeUndefined();
  });

  it("revokes prior readiness on failed or disabled refresh", async () => {
    listModelsMock.mockResolvedValue({
      models: [
        {
          id: "synthetic-opaque",
          model: "synthetic-opaque",
          inputModalities: ["text"],
          supportedReasoningEfforts: [],
        },
      ],
    });
    await owner.load(catalogParams, undefined);
    expect(read()).toEqual({ accountType: "apiKey" });
    rpc.request.mockRejectedValueOnce(new Error("synthetic account failure"));
    await expect(owner.load(catalogParams, undefined)).rejects.toThrow("synthetic account failure");
    expect(read()).toBeUndefined();
    await owner.load(catalogParams, undefined);
    await owner.load(catalogParams, { discovery: { enabled: false } });
    expect(read()).toBeUndefined();
  });

  it("cannot publish superseded or disposed asynchronous observations", async () => {
    listModelsMock.mockResolvedValue({
      models: [
        {
          id: "synthetic-opaque",
          model: "synthetic-opaque",
          inputModalities: ["text"],
          supportedReasoningEfforts: [],
        },
      ],
    });
    const pending = createDeferred<unknown>();
    rpc.request.mockReturnValueOnce(pending.promise);
    const older = owner.load(catalogParams, undefined);
    await vi.waitFor(() => expect(rpc.request).toHaveBeenCalledOnce());
    expect(read()).toBeUndefined();
    await owner.load(catalogParams, undefined);
    pending.resolve({ account: { type: "chatgpt" }, requiresOpenaiAuth: true });
    expect(await older).toEqual([]);
    expect(read()).toEqual({ accountType: "apiKey" });
    const disposed = createDeferred<unknown>();
    rpc.request.mockReturnValueOnce(disposed.promise);
    const late = owner.load(catalogParams, undefined);
    await vi.waitFor(() => expect(rpc.request).toHaveBeenCalledTimes(3));
    owner.dispose();
    disposed.resolve({ account: { type: "apiKey" }, requiresOpenaiAuth: true });
    expect(await late).toEqual([]);
    expect(read()).toBeUndefined();
  });
});

import type { AgentHarnessModelCatalogParams } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { ModelCatalogEntry } from "openclaw/plugin-sdk/agent-runtime";
import { readCodexPluginConfig } from "./config-parsing.js";
import { resolveCodexAppServerRuntimeOptions } from "./config-runtime.js";
import { buildCodexRuntimeModelParams } from "./model-runtime.js";
import { listAllCodexAppServerModels, type CodexAppServerModel } from "./models.js";
import { isJsonObject, type CodexGetAccountResponse } from "./protocol.js";
import { withCodexAppServerJsonClient } from "./request.js";
import { captureSharedCodexAppServerCatalogLifetime } from "./shared-client.js";

// Manifest contract (openclaw.plugin.json discovery.timeoutMs default): live model
// discovery is bounded tightly so a wedged app-server degrades to the static catalog.
const DEFAULT_MODEL_DISCOVERY_TIMEOUT_MS = 2500;
type ModelInputType = NonNullable<ModelCatalogEntry["input"]>[number];
const INPUT_TYPES: ReadonlySet<string> = new Set(["text", "image", "audio", "video", "document"]);

function isModelInputType(value: string): value is ModelInputType {
  return INPUT_TYPES.has(value);
}

function codexAppServerModelsToCatalogEntries(
  models: readonly CodexAppServerModel[],
  runtime: string,
): ModelCatalogEntry[] {
  return models.map((model, providerOrder) => {
    const input = model.inputModalities.filter(isModelInputType);
    const runtimeParams = buildCodexRuntimeModelParams(model.id, model.model);
    return {
      provider: "openai",
      id: model.id,
      name: model.displayName ?? model.id,
      providerOrder,
      nativeRuntime: runtime,
      reasoning: model.supportedReasoningEfforts.length > 0,
      ...(input.length > 0 ? { input } : {}),
      ...(runtimeParams ? { params: runtimeParams } : {}),
      compat: {
        supportsReasoningEffort: model.supportedReasoningEfforts.length > 0,
        supportedReasoningEfforts: model.supportedReasoningEfforts,
      },
    };
  });
}

/** One harness registration owns its observations; none travel with worker snapshots. */
export function createCodexAppServerModelCatalog(runtime: string) {
  type Observation = {
    pluginConfig: unknown;
    models?: ReadonlySet<string>;
    accountType?: "apiKey" | "chatgpt";
    isCurrent?: () => boolean;
  };
  const scopes = new WeakMap<AgentHarnessModelCatalogParams["config"], Map<string, Observation>>();
  const scopeKey = (params: AgentHarnessModelCatalogParams) =>
    JSON.stringify([params.agentId, params.agentDir, params.workspaceDir]);
  let disposed = false;
  return {
    dispose() {
      disposed = true;
    },
    read(
      params: AgentHarnessModelCatalogParams & { provider: string; modelId: string },
      pluginConfig: unknown,
    ) {
      const observation = scopes.get(params.config)?.get(scopeKey(params));
      return !disposed &&
        params.provider === "openai" &&
        observation !== undefined &&
        observation.pluginConfig === pluginConfig &&
        observation.models?.has(params.modelId) &&
        observation.accountType &&
        observation.isCurrent?.()
        ? { accountType: observation.accountType }
        : undefined;
    },
    async load(
      params: AgentHarnessModelCatalogParams,
      pluginConfig: unknown,
    ): Promise<ModelCatalogEntry[]> {
      if (disposed) {
        return [];
      }
      let observations = scopes.get(params.config);
      if (!observations) {
        observations = new Map();
        scopes.set(params.config, observations);
      }
      const key = scopeKey(params);
      const observation: Observation = { pluginConfig };
      // Revoke before any await, including failed/disabled refreshes and superseded reads.
      observations.set(key, observation);
      const discovery = readCodexPluginConfig(pluginConfig).discovery;
      if (discovery?.enabled === false) {
        return [];
      }
      const { start } = resolveCodexAppServerRuntimeOptions({ pluginConfig });
      const timeoutMs = discovery?.timeoutMs ?? DEFAULT_MODEL_DISCOVERY_TIMEOUT_MS;
      const result = await withCodexAppServerJsonClient(
        { startOptions: start, config: params.config, agentDir: params.agentDir, timeoutMs },
        async (request, client) => {
          const isCurrent = captureSharedCodexAppServerCatalogLifetime(client);
          const listed = await listAllCodexAppServerModels({ request, limit: 100 });
          const account = await request<CodexGetAccountResponse>({
            method: "account/read",
            requestParams: { refreshToken: false },
          });
          const observedType = isJsonObject(account.account) ? account.account.type : undefined;
          const accountType =
            account.requiresOpenaiAuth === true
              ? observedType === "apiKey" || observedType === "chatgpt"
                ? observedType
                : undefined
              : undefined;
          return { models: listed.models, isCurrent, accountType } as const;
        },
      );
      // Publish only after the bounded operation settles; a late timed-out callback cannot publish.
      if (disposed || observations.get(key) !== observation || !result.isCurrent()) {
        return [];
      }
      observation.models = new Set(result.models.map((model) => model.id));
      observation.accountType = result.accountType;
      observation.isCurrent = result.isCurrent;
      return codexAppServerModelsToCatalogEntries(result.models, runtime);
    },
  };
}

import { normalizeOptionalString } from "openclaw/plugin-sdk/string-coerce-runtime";

const CODEX_APP_SERVER_RUNTIME_MODEL_PARAM = "codexAppServerRuntimeModel";

type CodexRuntimeModel = {
  id: string;
  params?: Record<string, unknown>;
};

export function buildCodexRuntimeModelParams(catalogId: string, runtimeModelId: string) {
  return catalogId === runtimeModelId
    ? undefined
    : { [CODEX_APP_SERVER_RUNTIME_MODEL_PARAM]: runtimeModelId };
}

export function readCodexRuntimeModelId(
  model: CodexRuntimeModel | undefined,
  fallbackId: string,
): string {
  return (
    normalizeOptionalString(model?.params?.[CODEX_APP_SERVER_RUNTIME_MODEL_PARAM]) ??
    model?.id ??
    fallbackId
  );
}

