            ],
          };
        }
        throw new Error(`unexpected request: ${method}`);
      });
      const prepare = createCodexNativeMcpAppResultDetailsPreparer({
        client: { request, getInstanceId: () => "client-1" } as unknown as CodexAppServerClient,
        threadId: "thread-1",
        attempt: createAttempt(),
      });

      await expect(
        prepare?.({
