/**
 * Mirrors Codex native subagent lifecycle and completion into OpenClaw task
 * runtime records, with app-server history as the recovery source.
 */
import {
  embeddedAgentLog,
  emitAgentEvent,
  formatErrorMessage,
} from "openclaw/plugin-sdk/agent-harness-runtime";
