    async ({ action, replaySafe }) => {
      const toolResult: AgentToolResult<unknown> = {
        content: [{ type: "text", text: "cron complete" }],
        details: { ok: true },
      };
      const bridge = createCodexDynamicToolBridge({
        tools: [
          {
            name: "cron",
            description: "Cron",
            parameters: {
              type: "object",
              properties: { action: { type: "string" } },
              required: ["action"],
              additionalProperties: false,
            },
            execute: vi.fn(async () => toolResult),
          } as never,
        ],
        signal: new AbortController().signal,
      });
      const projector = await createProjector();
      const call = {
        threadId: THREAD_ID,
        turnId: TURN_ID,
        callId: `call-cron-${action}`,
        namespace: null,
        tool: "cron",
        arguments: { action },
      };
      projector.recordDynamicToolCall(call);
      const response = await bridge.handleToolCall(call);
      projector.recordDynamicToolResult({
        callId: call.callId,
        tool: call.tool,
        success: response.success,
        terminalType: response.diagnosticTerminalType,
        sideEffectEvidence: response.sideEffectEvidence === true,
        contentItems: response.contentItems,
      });
      await projector.handleNotification(
        forCurrentTurn("turn/completed", {
          turn: { id: TURN_ID, status: "completed", items: [] },
        }),
      );

      const result = projector.buildResult(bridge.telemetry);

      expect(result.replayMetadata).toEqual({
        hadPotentialSideEffects: !replaySafe,
        replaySafe,
      });
      expect(classifyProjectedAttemptResult(result) !== null).toBe(replaySafe);
    },
  );
});

import { Buffer } from "node:buffer";
import type { EmbeddedRunAttemptParams } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { AgentPlanStep } from "openclaw/plugin-sdk/channel-outbound";
import { truncateUtf8Prefix } from "openclaw/plugin-sdk/text-utility-runtime";
import { stripInvisibleUnicode } from "openclaw/plugin-sdk/web-content-extractor";
import type { CodexAppServerClient } from "./client.js";
import { isJsonObject } from "./protocol.js";

type AgentEvent = Parameters<NonNullable<EmbeddedRunAttemptParams["onAgentEvent"]>>[0];
type StoredPlan = { markdown?: string; steps: AgentPlanStep[] };

const RESTORED_PLAN_PREAMBLE =
  "OpenClaw restored the session progress card after context compaction. " +
  "This is application state, not a new user request. Continue the current task and call " +
  "progress_card whenever the status meaningfully changes.";
const PROGRESS_CARD_MAX_STEPS = 50;
const PROGRESS_CARD_MAX_STEP_UTF8_BYTES = 512;
const PROGRESS_CARD_MAX_UTF8_BYTES = 8 * 1024;
const RESTORED_PLAN_MAX_MARKDOWN_BYTES = 2 * 1024;
const RESTORED_PLAN_MAX_PAYLOAD_BYTES = 32 * 1024;
const RESTORED_PLAN_TRUNCATION_SUFFIX = "…";

export function canonicalizeNativeProgressCardInput(input: StoredPlan): {
  markdown?: string;
  plan: AgentPlanStep[];
} {
  const markdown =
    input.markdown === undefined
      ? undefined
      : truncateUtf8(stripInvisibleUnicode(input.markdown), PROGRESS_CARD_MAX_UTF8_BYTES);
  const plan: AgentPlanStep[] = [];
  let hasInProgressStep = false;
  for (const step of input.steps.slice(0, PROGRESS_CARD_MAX_STEPS)) {
    const text = truncateUtf8(stripInvisibleUnicode(step.step), PROGRESS_CARD_MAX_STEP_UTF8_BYTES);
    if (!text.trim()) {
      continue;
    }
    let status = step.status;
    if (status === "in_progress") {
      if (hasInProgressStep) {
        status = "pending";
      } else {
        hasInProgressStep = true;
      }
    }
    plan.push({ step: text, status });
  }
  return {
    ...(markdown !== undefined ? { markdown } : {}),
    plan,
  };
}

/** Retains the latest projected plan so Codex compaction cannot discard it. */
export class CodexCompactionPlanState {
  private latestPlan: StoredPlan | undefined;

  record(event: AgentEvent): void {
    if (event.stream !== "plan") {
      return;
    }
    const plan = readBoundedPlan(event.data.explanation, event.data.steps);
    this.latestPlan = plan;
  }

  /** Retains markdown that migration-only plan events intentionally omit. */
  recordProgressCardInput(value: unknown): void {
    if (!isJsonObject(value)) {
      return;
    }
    this.latestPlan = readBoundedPlan(value.markdown, value.plan);
  }

  async restore(params: {
    client: CodexAppServerClient;
    threadId: string;
    timeoutMs: number;
    signal?: AbortSignal;
  }): Promise<void> {
    if (!this.latestPlan) {
      return;
    }
    await params.client.request(
      "thread/inject_items",
      {
        threadId: params.threadId,
        items: [
          {
            type: "message",
            role: "user",
            content: [
              {
                type: "input_text",
                text: `${RESTORED_PLAN_PREAMBLE}\n${serializePlan(this.latestPlan)}`,
              },
            ],
          },
        ],
      },
      { timeoutMs: params.timeoutMs, signal: params.signal },
    );
  }
}

function readBoundedPlan(markdownValue: unknown, stepsValue: unknown): StoredPlan | undefined {
  const canonical = canonicalizeNativeProgressCardInput({
    ...(typeof markdownValue === "string" ? { markdown: markdownValue } : {}),
    steps: readPlanSteps(stepsValue),
  });
  const markdown =
    canonical.markdown === undefined
      ? undefined
      : truncateUtf8(canonical.markdown, RESTORED_PLAN_MAX_MARKDOWN_BYTES);
  const steps: AgentPlanStep[] = [];
  for (const step of canonical.plan) {
    const candidate = {
      ...(markdown?.trim() ? { markdown } : {}),
      steps: [...steps, step],
    };
    if (Buffer.byteLength(serializePlan(candidate), "utf8") > RESTORED_PLAN_MAX_PAYLOAD_BYTES) {
      break;
    }
    steps.push(step);
  }
  return markdown?.trim() || steps.length > 0
    ? { ...(markdown?.trim() ? { markdown } : {}), steps }
    : undefined;
}

function serializePlan(plan: StoredPlan): string {
  return JSON.stringify({ markdown: plan.markdown, plan: plan.steps });
}

function truncateUtf8(value: string, maxBytes: number): string {
  if (Buffer.byteLength(value, "utf8") <= maxBytes) {
    return value;
  }
  const suffixBytes = Buffer.byteLength(RESTORED_PLAN_TRUNCATION_SUFFIX, "utf8");
  return `${truncateUtf8Prefix(value, maxBytes - suffixBytes)}${RESTORED_PLAN_TRUNCATION_SUFFIX}`;
}

function readPlanSteps(value: unknown): AgentPlanStep[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.flatMap((entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      return [];
    }
    const { step, status } = entry as { step?: unknown; status?: unknown };
    if (typeof step !== "string" || !isPlanStatus(status)) {
      return [];
    }
    return [{ step, status }];
  });
}

function isPlanStatus(value: unknown): value is AgentPlanStep["status"] {
  return value === "pending" || value === "in_progress" || value === "completed";
}

// Codex tests cover plugin activation plugin behavior.
import { describe, expect, it, vi } from "vitest";
import { CodexAppInventoryCache } from "./app-inventory-cache.js";
import { CodexAppServerRpcError } from "./client.js";
import {
  CODEX_PLUGINS_MARKETPLACE_NAME,
  CODEX_PLUGINS_WORKSPACE_MARKETPLACE_NAME,
  type ResolvedCodexPluginPolicy,
} from "./config.js";
import { ensureCodexPluginActivation } from "./plugin-activation.js";
import { CodexPluginMetadataCache } from "./plugin-metadata-cache.js";
import type { v2 } from "./protocol.js";

describe("Codex plugin activation", () => {
  function expectActivationResult(
    result: Awaited<ReturnType<typeof ensureCodexPluginActivation>>,
    expected: { ok: boolean; reason: string; installAttempted: boolean },
  ) {
    expect(result.ok).toBe(expected.ok);
    expect(result.reason).toBe(expected.reason);
    expect(result.installAttempted).toBe(expected.installAttempted);
  }

  function expectBooleanParam(params: unknown, key: string, expected: boolean) {
    expect((params as Record<string, unknown> | undefined)?.[key]).toBe(expected);
  }

  it("skips plugin/install when the migrated plugin is already active", async () => {
    const calls: string[] = [];
    const result = await ensureCodexPluginActivation({
      identity: identity("google-calendar"),
      request: async (method) => {
        calls.push(method);
        if (method === "plugin/list") {
          return pluginList([pluginSummary("google-calendar", { installed: true, enabled: true })]);
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expectActivationResult(result, {
      ok: true,
      reason: "already_active",
      installAttempted: false,
    });
    expect(calls).toEqual(["plugin/list"]);
  });

  it("can reinstall an already active plugin when migration explicitly applies it", async () => {
    const calls: string[] = [];
    const result = await ensureCodexPluginActivation({
      identity: identity("google-calendar"),
      installEvenIfActive: true,
      request: async (method, params) => {
        calls.push(method);
        if (method === "plugin/list") {
          return pluginList([pluginSummary("google-calendar", { installed: true, enabled: true })]);
        }
        if (method === "plugin/install") {
          expect(params).toEqual({
            marketplacePath: "/marketplaces/openai-curated",
            pluginName: "google-calendar",
          });
          return { authPolicy: "ON_USE", appsNeedingAuth: [] } satisfies v2.PluginInstallResponse;
        }
        if (method === "skills/list") {
          return { data: [] } satisfies v2.SkillsListResponse;
        }
        if (method === "hooks/list") {
          return { data: [] } satisfies v2.HooksListResponse;
        }
        if (method === "config/mcpServer/reload") {
          return {};
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expectActivationResult(result, {
      ok: true,
      reason: "already_active",
      installAttempted: true,
    });
    expect(calls).toEqual([
      "plugin/list",
      "plugin/install",
      "plugin/list",
      "skills/list",
      "hooks/list",
      "config/mcpServer/reload",
    ]);
  });

  it("installs a migration-authorized local curated plugin and refreshes runtime state", async () => {
    const calls: Array<{ method: string; params: unknown }> = [];
    const appCache = new CodexAppInventoryCache();
    const metadataCache = new CodexPluginMetadataCache();
    let pluginListCalls = 0;
    const result = await ensureCodexPluginActivation({
      identity: identity("google-calendar"),
      appCache,
      appCacheKey: "runtime",
      metadataCache,
      request: async (method, params) => {
        calls.push({ method, params });
        if (method === "plugin/list") {
          pluginListCalls += 1;
          expect(params).toEqual(pluginListCalls === 1 ? {} : { forceRefetch: true });
          return pluginList([
            pluginSummary("google-calendar", {
              installed: pluginListCalls > 1,
              enabled: pluginListCalls > 1,
            }),
          ]);
        }
        if (method === "plugin/install") {
          expect(params).toEqual({
            marketplacePath: "/marketplaces/openai-curated",
            pluginName: "google-calendar",
          });
          return { authPolicy: "ON_USE", appsNeedingAuth: [] } satisfies v2.PluginInstallResponse;
        }
        if (method === "skills/list") {
          expectBooleanParam(params, "forceReload", true);
          return { data: [] } satisfies v2.SkillsListResponse;
        }
        if (method === "hooks/list") {
          return { data: [] } satisfies v2.HooksListResponse;
        }
        if (method === "config/mcpServer/reload") {
          return {};
        }
        if (method === "app/installed") {
          expectBooleanParam(params, "forceRefresh", true);
          return { apps: [] } satisfies v2.AppsInstalledResponse;
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expectActivationResult(result, {
      ok: true,
      reason: "installed",
      installAttempted: true,
    });
    expect(calls.map((call) => call.method)).toEqual([
      "plugin/list",
      "plugin/install",
      "plugin/list",
      "skills/list",
      "hooks/list",
      "config/mcpServer/reload",
      "app/installed",
    ]);
    expect(pluginListCalls).toBe(2);
    expect(
      metadataCache.read("runtime", "curated-global")?.response.marketplaces[0]?.plugins[0],
    ).toMatchObject({ installed: true, enabled: true });
    expect(appCache.getRevision()).toBeGreaterThan(0);
