/**
 * Builds stable Codex plugin/app inventory cache keys from app-server startup,
 * auth, account, and version inputs without storing secret material.
 */
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { OPENCLAW_VERSION } from "openclaw/plugin-sdk/agent-harness-runtime";
import { readPluginPackageVersion } from "openclaw/plugin-sdk/extension-shared";
import {
  buildCodexAppInventoryCacheKey,
  type CodexAppInventoryCacheKeyInput,
} from "./app-inventory-cache.js";
import {
  resolveCodexAppServerHomeDir,
  resolveCodexAppServerLocalHomeDir,
} from "./auth-start-options.js";
import type { CodexAppServerRuntimeIdentity } from "./client.js";
import {
  resolveCodexAppServerUserHomeDir,
  type CodexAppServerRuntimeOptions,
  type CodexAppServerStartOptions,
} from "./config.js";

const require = createRequire(import.meta.url);
const CODEX_PLUGIN_VERSION = readPluginPackageVersion({ require });

type CodexCatalogConnectionHome = {
  agentDir: string;
  fingerprint: string;
  codexHome: string;
};

let catalogConnectionHomes = new Map<string, string>();

function catalogConnectionHomeKey(fingerprint: string, agentDir?: string): string {
  return `${agentDir ?? ""}\0${fingerprint}`;
}

/** Replaces the lifecycle-owned catalog connection snapshot used by supervised bindings. */
export function replaceCodexCatalogConnectionHomes(homes: CodexCatalogConnectionHome[]): void {
  catalogConnectionHomes = new Map(
    homes.map((home) => [
      catalogConnectionHomeKey(home.fingerprint, home.agentDir),
      home.codexHome,
    ]),
  );
}

/** Inputs that identify the Codex app inventory cache scope for one runtime. */
type CodexPluginAppCacheKeyParams = Omit<
  CodexAppInventoryCacheKeyInput,
  "codexHome" | "endpoint"
> & {
  appServer: Pick<CodexAppServerRuntimeOptions, "start">;
  agentDir?: string;
  runtimeIdentity?: CodexAppServerRuntimeIdentity;
  desktopGenerationFingerprint?: string;
};

/** Builds the full app inventory cache key for Codex plugin/app discovery. */
export function buildCodexPluginAppCacheKey(params: CodexPluginAppCacheKeyParams): string {
  return buildCodexAppInventoryCacheKey(
    {
      codexHome:
        params.runtimeIdentity?.codexHome ??
        resolveCodexPluginAppCacheCodexHome(params.appServer, params.agentDir),
      endpoint: resolveCodexPluginAppCacheEndpoint(params.appServer),
      authProfileId: params.authProfileId,
      accountId: params.accountId,
      envApiKeyFingerprint: params.envApiKeyFingerprint,
      appServerVersion: params.appServerVersion ?? params.runtimeIdentity?.serverVersion,
      runtimeIdentity: params.desktopGenerationFingerprint
        ? {
            ...params.runtimeIdentity,
            desktopGeneration: params.desktopGenerationFingerprint,
          }
        : params.runtimeIdentity,
    },
    OPENCLAW_VERSION,
    CODEX_PLUGIN_VERSION,
  );
}

/** Builds a durable thread-binding fingerprint for one initialized app-server runtime. */
export function buildCodexAppServerRuntimeFingerprint(params: {
  appServer: Pick<
    CodexAppServerRuntimeOptions,
    "start" | "connectionClass" | "remoteWorkspaceRoot"
  >;
  appServerVersion?: string;
  runtimeIdentity?: CodexAppServerRuntimeIdentity;
}): string {
  return JSON.stringify({
    endpoint: resolveCodexPluginAppCacheEndpoint(params.appServer),
    connectionClass: params.appServer.connectionClass,
    remoteWorkspaceRoot: params.appServer.remoteWorkspaceRoot ?? null,
    appServerVersion: params.appServerVersion ?? params.runtimeIdentity?.serverVersion ?? null,
    runtimeIdentity: params.runtimeIdentity ?? null,
  });
}

/** Fingerprints the configured connection that owns a supervised source thread. */
export function buildCodexAppServerConnectionFingerprint(
  appServer: Pick<
    CodexAppServerRuntimeOptions,
    "start" | "connectionClass" | "remoteWorkspaceRoot"
  >,
  agentDir?: string,
): string {
  return JSON.stringify({
    endpoint: resolveCodexPluginAppCacheEndpoint(appServer),
    connectionClass: appServer.connectionClass,
    remoteWorkspaceRoot: appServer.remoteWorkspaceRoot ?? null,
    homeScope: appServer.start.homeScope ?? null,
    codexHome: resolveCodexAppServerConnectionHome(appServer.start, agentDir),
    cwd: appServer.start.cwd ?? null,
  });
}

/** Looks up a snapshotted catalog store without repeating filesystem discovery on a run. */
export function resolveCodexCatalogConnectionHome(
  fingerprint: string,
  agentDir?: string,
): string | undefined {
  return catalogConnectionHomes.get(catalogConnectionHomeKey(fingerprint, agentDir));
}

function resolveCodexAppServerConnectionHome(
  start: CodexAppServerStartOptions,
  agentDir?: string,
): string | null {
  const configured = start.env?.CODEX_HOME?.trim();
  if (configured) {
    return configured;
  }
  if (start.transport === "unix" && (!start.url || start.url === "unix://")) {
    return resolveCodexAppServerUserHomeDir(start.env ?? process.env);
  }
  if (start.transport !== "stdio") {
    return null;
  }
  if (start.homeScope === "user") {
    return resolveCodexAppServerUserHomeDir(process.env);
  }
  return agentDir ? resolveCodexAppServerLocalHomeDir(start, agentDir) : null;
}

/** Serializes app-server endpoint identity, including credential fingerprints. */
function resolveCodexPluginAppCacheEndpoint(
  appServer: Pick<CodexAppServerRuntimeOptions, "start">,
): string {
  return JSON.stringify({
    transport: appServer.start.transport,
    command: appServer.start.command,
    args: appServer.start.args,
    url: appServer.start.url ?? null,
    credentialFingerprint: fingerprintCodexPluginAppCacheCredentials(appServer.start),
  });
}

/** Resolves the CODEX_HOME value that scopes local app-server inventory. */
function resolveCodexPluginAppCacheCodexHome(
  appServer: Pick<CodexAppServerRuntimeOptions, "start">,
  agentDir?: string,
): string | undefined {
  const configuredCodexHome = appServer.start.env?.CODEX_HOME?.trim();
  if (configuredCodexHome) {
    return configuredCodexHome;
  }
  return appServer.start.transport === "stdio" && agentDir
    ? resolveCodexAppServerHomeDir(agentDir)
    : undefined;
}

function fingerprintCodexPluginAppCacheCredentials(
  startOptions: CodexAppServerStartOptions,
): string | null {
  const authToken = startOptions.authToken ?? "";
  const headers = Object.entries(startOptions.headers)
    .map(([key, value]) => [key.toLowerCase(), value] as const)
    .toSorted(([left], [right]) => left.localeCompare(right));
  if (!authToken && headers.length === 0) {
    return null;
  }
  const hash = createHash("sha256");
  hash.update("openclaw:codex:plugin-app-cache-credentials:v1");
  hash.update("\0");
  hash.update(authToken);
  for (const [key, value] of headers) {
    hash.update("\0");
    hash.update(key);
    hash.update("\0");
    hash.update(value);
  }
  return `sha256:${hash.digest("hex")}`;
}

/**
 * Routes Codex app-server plugin approval prompts through OpenClaw's gateway
 * approval tool and maps gateway decisions back to Codex outcomes.
 */
import type { EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams } from "openclaw/plugin-sdk/agent-harness-runtime";
import { isApprovalNotFoundError, toErrorObject } from "openclaw/plugin-sdk/error-runtime";
import { truncateUtf16Safe } from "openclaw/plugin-sdk/text-utility-runtime";
import { resolveCodexGatewayTimeoutWithGraceMs } from "./attempt-timeouts.js";

type AgentHarnessHostCapabilities = EmbeddedRunAttemptParams["hostCapabilities"];

const DEFAULT_CODEX_APPROVAL_TIMEOUT_MS = 120_000;
const MAX_PLUGIN_APPROVAL_TITLE_LENGTH = 80;
const MAX_PLUGIN_APPROVAL_DESCRIPTION_LENGTH = 256;
const ANSI_OSC_SEQUENCE_RE = new RegExp(
  String.raw`(?:\u001b]|\u009d)[^\u001b\u009c\u0007]*(?:\u0007|\u001b\\|\u009c)`,
  "g",
);
const ANSI_CONTROL_SEQUENCE_RE = new RegExp(
  String.raw`(?:\u001b\[[0-?]*[ -/]*[@-~]|\u009b[0-?]*[ -/]*[@-~]|\u001b[@-Z\\-_])`,
  "g",
);
const CONTROL_CHARACTER_RE = new RegExp(String.raw`[\u0000-\u001f\u007f-\u009f]+`, "g");
const INVISIBLE_FORMATTING_CONTROL_RE = new RegExp(
  String.raw`[\u00ad\u034f\u061c\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff\ufe00-\ufe0f\u{e0100}-\u{e01ef}]`,
  "gu",
);
const DANGLING_TERMINAL_SEQUENCE_SUFFIX_RE = new RegExp(
  String.raw`(?:\u001b\][^\u001b\u009c\u0007]*|\u009d[^\u001b\u009c\u0007]*|\u001b\[[0-?]*[ -/]*|\u009b[0-?]*[ -/]*|\u001b)$`,
);

export type ExecApprovalDecision = "allow-once" | "allow-always" | "deny";

export type CodexApprovalKind = "command" | "file-change" | "permissions" | "other";
const CODEX_APPROVAL_TIMEOUT_SUBJECTS: Record<CodexApprovalKind, string> = {
  command: "Command approval",
  "file-change": "File change approval",
  permissions: "Permission approval",
  other: "Approval",
};

export function codexApprovalTimeoutText(kind: CodexApprovalKind): string {
  return `${CODEX_APPROVAL_TIMEOUT_SUBJECTS[kind]} timed out before an operator responded.`;
}

/** Normalized Codex app-server approval outcome after a gateway decision. */
export type AppServerApprovalOutcome =
  | "approved-once"
  | "approved-session"
  | "denied"
  | "unavailable"
  | "cancelled";

type ApprovalRequestResult = {
  id?: string;
  decision?: ExecApprovalDecision | null;
};

/** Starts a two-phase plugin approval request through the OpenClaw gateway. */
export async function requestPluginApproval(params: {
  hostCapabilities: AgentHarnessHostCapabilities;
  signal?: AbortSignal;
  title: string;
  description: string;
  severity: "info" | "warning";
  toolName: string;
  toolCallId?: string;
  allowedDecisions?: ExecApprovalDecision[];
}): Promise<ApprovalRequestResult | undefined> {
  const timeoutMs = DEFAULT_CODEX_APPROVAL_TIMEOUT_MS;
  return params.hostCapabilities.requestApproval({
    signal: params.signal,
    title: truncateCodexApprovalDisplayText(params.title, MAX_PLUGIN_APPROVAL_TITLE_LENGTH),
    description: truncateCodexApprovalDisplayText(
      params.description,
      MAX_PLUGIN_APPROVAL_DESCRIPTION_LENGTH,
    ),
    severity: params.severity,
    toolName: params.toolName,
    toolCallId: params.toolCallId,
    timeoutMs,
    transportTimeoutMs: resolveCodexGatewayTimeoutWithGraceMs(timeoutMs),
    ...(params.allowedDecisions ? { allowedDecisions: params.allowedDecisions } : {}),
  }) as Promise<ApprovalRequestResult | undefined>;
}

/** Detects the gateway's explicit null-decision marker for unavailable approvals. */
export function approvalRequestExplicitlyUnavailable(result: unknown): boolean {
  if (result === null || result === undefined || typeof result !== "object") {
    return false;
  }
  let descriptor: PropertyDescriptor | undefined;
  try {
    descriptor = Object.getOwnPropertyDescriptor(result, "decision");
  } catch {
    return false;
  }
  return descriptor !== undefined && "value" in descriptor && descriptor.value === null;
}

/** Waits for the gateway's final approval decision, respecting turn aborts. */
export async function waitForPluginApprovalDecision(params: {
  hostCapabilities: AgentHarnessHostCapabilities;
  approvalId: string;
  signal?: AbortSignal;
}): ReturnType<AgentHarnessHostCapabilities["waitForApproval"]> {
  const timeoutMs = DEFAULT_CODEX_APPROVAL_TIMEOUT_MS;
  const waitPromise = params.hostCapabilities
    .waitForApproval({
      approvalId: params.approvalId,
      timeoutMs,
      transportTimeoutMs: resolveCodexGatewayTimeoutWithGraceMs(timeoutMs),
      signal: params.signal,
    })
    .catch((error: unknown) => {
      if (isApprovalNotFoundError(error)) {
        return undefined;
      }
      throw error;
    });
  if (!params.signal) {
    return await waitPromise;
  }
  let onAbort: (() => void) | undefined;
  const abortPromise = new Promise<never>((_, reject) => {
    if (params.signal!.aborted) {
      reject(toErrorObject(params.signal!.reason, "Non-Error rejection"));
      return;
    }
    onAbort = () => reject(toErrorObject(params.signal!.reason, "Non-Error rejection"));
    params.signal!.addEventListener("abort", onAbort, { once: true });
  });
  try {
    return await Promise.race([waitPromise, abortPromise]);
  } finally {
    if (onAbort) {
      params.signal.removeEventListener("abort", onAbort);
    }
  }
}

/** Converts a gateway exec approval decision into the app-server approval outcome enum. */
export function mapExecDecisionToOutcome(
  decision: ExecApprovalDecision | null | undefined,
): AppServerApprovalOutcome {
  switch (decision) {
    case "allow-once":
      return "approved-once";
    case "allow-always":
      return "approved-session";
    case "deny":
      return "denied";
    default:
      return "unavailable";
  }
}

export function truncateCodexApprovalDisplayText(value: string, maxLength: number): string {
  return value.length <= maxLength ? value : `${truncateUtf16Safe(value, maxLength - 3)}...`;
}

export function stripDanglingCodexApprovalTerminalSequence(value: string): string {
  return value.replace(DANGLING_TERMINAL_SEQUENCE_SUFFIX_RE, "");
}

export function sanitizeCodexApprovalVisibleText(
  value: string,
  options: { stripDanglingTerminalSequence?: boolean } = {},
): string {
  const terminalSafe = value
    .replace(ANSI_OSC_SEQUENCE_RE, "")
    .replace(ANSI_CONTROL_SEQUENCE_RE, "");
  const visible = options.stripDanglingTerminalSequence
    ? stripDanglingCodexApprovalTerminalSequence(terminalSafe)
    : terminalSafe;
  return visible
    .replace(INVISIBLE_FORMATTING_CONTROL_RE, " ")
    .replace(CONTROL_CHARACTER_RE, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// Codex tests cover marketplace-qualified plugin inventory behavior.
import { describe, expect, it } from "vitest";
import { CodexAppInventoryCache } from "./app-inventory-cache.js";
import { codexAppInventoryResponse } from "./app-inventory.test-helpers.js";
import { readCodexPluginInventory } from "./plugin-inventory.js";
import {
  appInfo,
  appSummary,
  pluginDetail,
  pluginInstalled,
  pluginList,
  pluginSummary,
} from "./plugin-inventory.test-helpers.js";
import { CodexPluginMetadataCache } from "./plugin-metadata-cache.js";
import type { v2 } from "./protocol.js";

describe("Codex marketplace-qualified plugin inventory", () => {
  it("resolves an owner-installed repository plugin from its exact marketplace", async () => {
    const appCache = new CodexAppInventoryCache();
    await appCache.refreshNow({
      key: "runtime",
      nowMs: 0,
      request: async (method, params) =>
        codexAppInventoryResponse(method, [appInfo("github-app", true)], params),
    });
    const calls: Array<{ method: string; params: unknown }> = [];

    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "security-review@company-tools": {
              marketplaceName: "company-tools",
              pluginName: "security-review",
            },
          },
        },
      },
      appCache,
      appCacheKey: "runtime",
      configCwd: "/repo/company",
      nowMs: 1,
      request: async (method, params) => {
        calls.push({ method, params });
        if (method === "plugin/installed") {
          return pluginInstalled(
            [
              pluginSummary("security-review@company-tools", {
                name: "security-review",
                installed: true,
                enabled: true,
              }),
            ],
            { name: "company-tools", path: "/repo/company/.agents/plugins/marketplace.json" },
          );
        }
        if (method === "plugin/read") {
          return pluginDetail("security-review", [appSummary("github-app")], {
            marketplaceName: "company-tools",
            marketplacePath: "/repo/company/.agents/plugins/marketplace.json",
          });
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(calls).toEqual([
      { method: "plugin/installed", params: { cwds: ["/repo/company"] } },
      {
        method: "plugin/read",
        params: {
          marketplacePath: "/repo/company/.agents/plugins/marketplace.json",
          pluginName: "security-review",
        },
      },
    ]);
    expect(inventory.records[0]).toMatchObject({
      policy: { marketplaceName: "company-tools", pluginName: "security-review" },
      activationRequired: false,
      ownedAppIds: ["github-app"],
    });
  });

  it("never admits the same plugin name from a different marketplace", async () => {
    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "audit@trusted-company": {
              marketplaceName: "trusted-company",
              pluginName: "audit",
            },
          },
        },
      },
      configCwd: "/repo/company",
      readPluginDetails: false,
      request: async (method, params) => {
        expect(params).toEqual({ cwds: ["/repo/company"] });
        if (method === "plugin/installed" || method === "plugin/list") {
          const marketplace = {
            name: "untrusted-company",
            path: "/repo/untrusted/.agents/plugins/marketplace.json",
            interface: null,
            plugins: [pluginSummary("audit", { installed: true, enabled: true })],
          };
          return method === "plugin/installed"
            ? { marketplaces: [marketplace], marketplaceLoadErrors: [] }
            : { marketplaces: [marketplace], marketplaceLoadErrors: [], featuredPluginIds: [] };
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(inventory.records).toEqual([]);
    expect(inventory.diagnostics).toEqual([
      expect.objectContaining({ code: "marketplace_missing" }),
    ]);
  });

  it("selects the authorized marketplace when two catalogs contain the same plugin name", async () => {
    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "audit@trusted-company": {
              marketplaceName: "trusted-company",
              pluginName: "audit",
            },
          },
        },
      },
      request: async (method, params) => {
        if (method === "plugin/installed") {
          return {
            marketplaces: [
              {
                name: "untrusted-company",
                path: "/untrusted/marketplace.json",
                interface: null,
                plugins: [pluginSummary("audit", { installed: true, enabled: true })],
              },
              {
                name: "trusted-company",
                path: "/trusted/marketplace.json",
                interface: null,
                plugins: [pluginSummary("audit", { installed: true, enabled: true })],
              },
            ],
            marketplaceLoadErrors: [],
          } satisfies v2.PluginInstalledResponse;
        }
        if (method === "plugin/read") {
          expect(params).toEqual({
            marketplacePath: "/trusted/marketplace.json",
            pluginName: "audit",
          });
          return pluginDetail("audit", [], {
            marketplaceName: "trusted-company",
            marketplacePath: "/trusted/marketplace.json",
          });
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(inventory.records).toHaveLength(1);
    expect(inventory.records[0]?.policy.marketplaceName).toBe("trusted-company");
  });

  it("discovers an uninstalled repository plugin with its current conversation cwd", async () => {
    const calls: Array<{ method: string; params: unknown }> = [];
    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "security-review@company-tools": {
              marketplaceName: "company-tools",
              pluginName: "security-review",
            },
          },
        },
      },
      configCwd: "/repo/company",
      readPluginDetails: false,
      request: async (method, params) => {
        calls.push({ method, params });
        if (method === "plugin/installed") {
          return {
            marketplaces: [],
            marketplaceLoadErrors: [],
          } satisfies v2.PluginInstalledResponse;
        }
        if (method === "plugin/list") {
          return pluginList(
            [pluginSummary("security-review", { installed: false, enabled: false })],
            {
              name: "company-tools",
              path: "/repo/company/.agents/plugins/marketplace.json",
            },
          );
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(calls).toEqual([
      { method: "plugin/installed", params: { cwds: ["/repo/company"] } },
      { method: "plugin/list", params: { cwds: ["/repo/company"] } },
    ]);
    expect(inventory.records[0]).toMatchObject({
      policy: { marketplaceName: "company-tools" },
      activationRequired: true,
    });
  });

  it("uses the opaque remote id for installed shared-marketplace plugins", async () => {
    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "audit@workspace-shared-with-me": {
              marketplaceName: "workspace-shared-with-me",
              pluginName: "audit@workspace-shared-with-me",
            },
          },
        },
      },
      request: async (method, params) => {
        if (method === "plugin/installed") {
          return pluginInstalled(
            [
              pluginSummary("audit@workspace-shared-with-me", {
                name: "audit",
                remotePluginId: "plugin_shared_audit_opaque",
                installed: true,
                enabled: true,
              }),
            ],
            { name: "workspace-shared-with-me", path: null },
          );
        }
        if (method === "plugin/read") {
          expect(params).toEqual({
            remoteMarketplaceName: "workspace-shared-with-me",
            pluginName: "plugin_shared_audit_opaque",
          });
          return pluginDetail("audit", [], {
            marketplaceName: "workspace-shared-with-me",
            marketplacePath: null,
          });
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(inventory.records[0]?.summary.remotePluginId).toBe("plugin_shared_audit_opaque");
    expect(inventory.diagnostics).toEqual([]);
  });

  it("does not reuse a partial repository catalog when resolving the curated marketplace", async () => {
    const metadataCache = new CodexPluginMetadataCache();
    let catalogCalls = 0;
    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "a-security": {
              marketplaceName: "company-tools",
              pluginName: "security-review",
            },
            "z-calendar": {
              marketplaceName: "openai-curated",
              pluginName: "calendar",
            },
          },
        },
      },
      appCacheKey: "runtime",
      configCwd: "/repo/company",
      metadataCache,
      readPluginDetails: false,
      request: async (method) => {
        if (method === "plugin/installed") {
          return { marketplaces: [], marketplaceLoadErrors: [] };
        }
        if (method === "plugin/list") {
          catalogCalls += 1;
          return catalogCalls === 1
            ? pluginList([pluginSummary("security-review")], {
                name: "company-tools",
                path: "/repo/company/.agents/plugins/marketplace.json",
              })
            : pluginList([pluginSummary("calendar")], {
                name: "openai-curated",
                path: "/managed/openai-curated/marketplace.json",
              });
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(catalogCalls).toBe(2);
    expect(inventory.records.map((record) => record.policy.configKey)).toEqual([
      "a-security",
      "z-calendar",
    ]);
    expect(inventory.diagnostics).toEqual([]);
  });

  it("never exposes plugins disabled by an administrator", async () => {
    const calls: string[] = [];
    const inventory = await readCodexPluginInventory({
      pluginConfig: {
        codexPlugins: {
          enabled: true,
          plugins: {
            "audit@enterprise": {
              marketplaceName: "enterprise",
              pluginName: "audit",
            },
          },
        },
      },
      request: async (method, params) => {
        calls.push(method);
        if (method === "plugin/installed") {
          return pluginInstalled(
            [
              pluginSummary("audit", {
                installed: true,
                enabled: true,
                availability: "DISABLED_BY_ADMIN",
              }),
            ],
            { name: "enterprise", path: "/enterprise/marketplace.json" },
          );
        }
        if (method === "plugin/read") {
          expect(params).toEqual({
            marketplacePath: "/enterprise/marketplace.json",
            pluginName: "audit",
          });
          return pluginDetail("audit", [appSummary("admin-denied-app")], {
            marketplaceName: "enterprise",
            marketplacePath: "/enterprise/marketplace.json",
          });
        }
        throw new Error(`unexpected request ${method}`);
      },
    });

    expect(calls).toEqual(["plugin/installed", "plugin/read"]);
    expect(inventory.records[0]).toMatchObject({
      activationRequired: true,
      ownedAppIds: ["admin-denied-app"],
    });
    expect(inventory.diagnostics).toEqual([expect.objectContaining({ code: "plugin_disabled" })]);
  });
});

import { CODEX_PLUGINS_MARKETPLACE_NAME } from "./config.js";
import type { v2 } from "./protocol.js";

export function asPluginInstalled(listed: v2.PluginListResponse): v2.PluginInstalledResponse {
  const { featuredPluginIds: _featuredPluginIds, ...installed } = listed;
  return installed;
}

export function pluginInstalled(
  plugins: v2.PluginSummary[],
  marketplace: { name?: string; path?: string | null } = {},
): v2.PluginInstalledResponse {
  return asPluginInstalled(pluginList(plugins, marketplace));
}

export function pluginList(
  plugins: v2.PluginSummary[],
  marketplace: { name?: string; path?: string | null } = {},
): v2.PluginListResponse {
  return {
    marketplaces: [
      {
        name: marketplace.name ?? CODEX_PLUGINS_MARKETPLACE_NAME,
        path: marketplace.path === undefined ? "/marketplaces/openai-curated" : marketplace.path,
        interface: null,
        plugins,
      },
    ],
    marketplaceLoadErrors: [],
    featuredPluginIds: [],
  };
}

export function pluginSummary(
  id: string,
  overrides: Partial<v2.PluginSummary> = {},
): v2.PluginSummary {
  return {
    id,
    name: id,
    source: { type: "remote" },
    installed: false,
    enabled: false,
    installPolicy: "AVAILABLE",
    authPolicy: "ON_USE",
    availability: "AVAILABLE",
    interface: null,
    ...overrides,
  };
}

export function pluginDetail(
  pluginName: string,
  apps: v2.AppSummary[],
  marketplace: { marketplaceName?: string; marketplacePath?: string | null } = {},
): v2.PluginReadResponse {
  return {
    plugin: {
      marketplaceName: marketplace.marketplaceName ?? CODEX_PLUGINS_MARKETPLACE_NAME,
      marketplacePath:
        marketplace.marketplacePath === undefined
          ? "/marketplaces/openai-curated"
          : marketplace.marketplacePath,
      summary: pluginSummary(pluginName, { installed: true, enabled: true }),
      description: null,
      skills: [],
      apps,
      mcpServers: [],
    },
  };
}

export function appSummary(id: string): v2.AppSummary {
  return {
    id,
    name: id,
    description: null,
    installUrl: null,
    category: null,
  };
}

export function appInfo(id: string, accessible: boolean): v2.AppInfo {
  return {
    id,
    name: id,
    description: null,
    logoUrl: null,
    logoUrlDark: null,
    distributionChannel: null,
    branding: null,
    appMetadata: null,
    labels: null,
    installUrl: null,
    isAccessible: accessible,
    isEnabled: true,
    pluginDisplayNames: [],
  };
}

