  type v2,
} from "./protocol.js";

export type CodexPluginThreadAppAdmissionDiagnostic = {
  code: "account_app_inventory_unavailable" | "account_app_config_unavailable";
  message: string;
};

type CodexPluginThreadAppAdmissionParams = {
  request: CodexPluginRuntimeRequest;
  configCwd?: string;
  threadId?: string;
  appCacheKey: string;
  nowMs?: number;
};

/** Effective Codex config and active layers from one authoritative read. */
export type CodexPluginThreadAppAdmissionConfig = {
  config: JsonObject;
  layers: readonly JsonObject[];
};

export function resolveCodexPluginThreadAppCacheKey(params: {
  appCacheKey: string;
  threadId?: string;
}): string {
  return params.threadId
    ? `${params.appCacheKey}:thread:${encodeURIComponent(params.threadId)}`
    : params.appCacheKey;
}

function createCodexPluginThreadAppInventoryRequest(
  params: CodexPluginThreadAppAdmissionParams,
): CodexAppInventoryRequest {
  return async (method, requestParams) =>
    (await params.request(
      method,
      (method === "app/installed" || method === "app/read") && params.threadId
        ? { ...requestParams, threadId: params.threadId }
        : requestParams,
    )) as CodexAppServerRequestResult<typeof method>;
}

export async function refreshCodexPluginAppInventory(
  params: CodexPluginThreadAppAdmissionParams,
  appCache: CodexAppInventoryCache,
  options: { forceRefetch?: boolean; reason?: string; targetAppIds?: readonly string[] } = {},
): Promise<CodexAppInventorySnapshot | undefined> {
  if (!params.appCacheKey) {
    return undefined;
  }
  const request = createCodexPluginThreadAppInventoryRequest(params);
  try {
    return await appCache.refreshNow({
      key: resolveCodexPluginThreadAppCacheKey(params),
      request,
      nowMs: params.nowMs,
      forceRefetch: options.forceRefetch,
      targetAppIds: options.targetAppIds,
    });
  } catch (error) {
    embeddedAgentLog.warn("codex plugin thread config app inventory refresh failed", {
      reason: options.reason,
      forceRefetch: options.forceRefetch === true,
      error: serializeCodexAppInventoryError(error),
    });
    return undefined;
  }
}

export function collectCodexPluginOwnedAppIds(inventory: CodexPluginInventory): string[] {
  return Array.from(
    new Set(inventory.records.flatMap((record) => record.ownedAppIds).filter(Boolean)),
  ).toSorted();
}

export function collectCodexReservedPluginAppIds(params: {
  policy: ResolvedCodexPluginsPolicy;
  inventory: CodexPluginInventory;
  accountApps: readonly v2.AppInfo[];
}): Set<string> {
  const reserved = new Set(
    params.inventory.records.flatMap((record) =>
      record.appOwnership === "proven" ? record.ownedAppIds : [],
    ),
  );
  const recordsByConfigKey = new Map(
    params.inventory.records.map((record) => [record.policy.configKey, record] as const),
  );
  const configuredOwnerNames = new Set(
    params.policy.pluginPolicies.flatMap((policy) => {
      const record = recordsByConfigKey.get(policy.configKey);
      return [policy.configKey, policy.pluginName, record?.summary.name, record?.summary.id]
        .filter((name): name is string => Boolean(name))
        .map(normalizeCodexPluginOwnerName);
    }),
  );

  for (const app of params.accountApps) {
    if (
      app.pluginDisplayNames.some((name) =>
        configuredOwnerNames.has(normalizeCodexPluginOwnerName(name)),
      )
    ) {
      reserved.add(app.id);
    }
  }
  return reserved;
}

function normalizeCodexPluginOwnerName(name: string): string {
  return name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");
}

export async function readCodexThreadAdmissibleAccountApps(
  params: CodexPluginThreadAppAdmissionParams,
  appCache: CodexAppInventoryCache,
): Promise<{
  apps: v2.AppInfo[];
  diagnostic?: CodexPluginThreadAppAdmissionDiagnostic;
}> {
  // Account-wide policy must use a complete snapshot; a targeted plugin read
  // cannot establish which other account apps are authorized for this thread.
  const request = createCodexPluginThreadAppInventoryRequest(params);
  const cachedInventory = appCache.read({
    key: resolveCodexPluginThreadAppCacheKey(params),
    request,
    nowMs: params.nowMs,
    suppressRefresh: true,
  });
  const snapshot =
    cachedInventory.state === "fresh" && !cachedInventory.snapshot?.targetAppIds?.length
      ? cachedInventory.snapshot
      : await refreshCodexPluginAppInventory(params, appCache, {
          forceRefetch: false,
          reason: "account_apps_all",
          targetAppIds: [],
        });
  if (!snapshot) {
    return {
      apps: [],
      diagnostic: {
        code: "account_app_inventory_unavailable",
        message: "Codex account app inventory was unavailable; account apps were not exposed.",
      },
    };
  }
  const installedAppsById = new Map(snapshot.installedApps.map((app) => [app.id, app]));
  return {
    apps: snapshot.apps
      .filter(
        (app) =>
          resolveCodexInstalledAppThreadAdmission(
            toCodexPluginOwnedAccountApp(app),
            installedAppsById.get(app.id),
          ) !== "blocked",
      )
      .toSorted((left, right) => left.id.localeCompare(right.id)),
  };
}

export function toCodexPluginOwnedAccountApp(app: v2.AppInfo): CodexPluginOwnedApp {
  return {
    id: app.id,
    name: app.name,
    accessible: app.isAccessible,
    enabled: app.isEnabled,
    needsAuth: !app.isAccessible,
    ...resolveOwnedAppReadOnlyToolConfigKeys(app),
  };
}

export function resolveCodexThreadConfigAppsForRecord(params: {
  record: CodexPluginInventoryRecord;
  inventory: CodexPluginInventory;
}): CodexPluginOwnedApp[] {
  return params.inventory.appInventory?.state === "missing" ? [] : params.record.apps;
}

type CodexPluginAppThreadAdmission = "ready" | "provisional" | "blocked";

export function resolveCodexPluginAppThreadAdmission(
  app: CodexPluginOwnedApp,
  inventory: CodexPluginInventory,
): CodexPluginAppThreadAdmission {
  const snapshot = inventory.appInventory?.snapshot;
  if (!snapshot) {
    return "blocked";
  }
  return resolveCodexInstalledAppThreadAdmission(
    app,
    snapshot.installedApps.find((candidate) => candidate.id === app.id),
  );
}

function resolveCodexInstalledAppThreadAdmission(
  app: Pick<CodexPluginOwnedApp, "accessible" | "needsAuth">,
  installed: v2.InstalledApp | undefined,
): CodexPluginAppThreadAdmission {
  if (!app.accessible || app.needsAuth || !installed) {
    return "blocked";
  }
  if (installed.enabled && installed.callable) {
    return "ready";
  }
  // Explicit plugin and account-wide policy can both override deny-by-default.
  // An enabled app with no callable tools cannot be repaired by thread policy.
  return !installed.enabled && !installed.callable ? "provisional" : "blocked";
}

export async function readCodexConfigForAppAdmission(
  params: CodexPluginThreadAppAdmissionParams,
): Promise<CodexPluginThreadAppAdmissionConfig | undefined> {
  try {
    const response = await params.request("config/read", {
      includeLayers: true,
      ...(params.configCwd ? { cwd: params.configCwd } : {}),
    });
    if (
      !isJsonObject(response) ||
      !isJsonObject(response.config) ||
      !Array.isArray(response.layers)
    ) {
      throw new Error("Codex config/read omitted effective config or config layers");
    }
    return {
      config: response.config,
      layers: response.layers.flatMap((layer) => {
        if (!isJsonObject(layer)) {
          throw new Error("Codex config/read returned an invalid config layer");
        }
        if (layer.disabledReason !== undefined && layer.disabledReason !== null) {
          if (typeof layer.disabledReason !== "string") {
            throw new Error("Codex config/read returned an invalid disabled layer");
          }
          return [];
        }
        if (!isJsonObject(layer.config)) {
          throw new Error("Codex config/read returned an invalid layer config");
        }
        return [layer.config];
      }),
    };
  } catch (error) {
    embeddedAgentLog.warn("codex plugin app admission config read failed", {
      error: serializeCodexAppInventoryError(error),
    });
    return undefined;
  }
}

export function resolveCodexExplicitAppEnablement(
  layersHighestPrecedenceFirst: readonly JsonObject[],
  appId: string,
): boolean | undefined {
  // The first active app-specific value wins. `_default` does not prevent an
  // explicitly selected plugin from safely requesting thread-only enablement.
  for (const layer of layersHighestPrecedenceFirst) {
    const apps = layer.apps;
    const app = isJsonObject(apps) ? apps[appId] : undefined;
    if (isJsonObject(app) && Object.hasOwn(app, "enabled")) {
      return app.enabled === true;
    }
  }
  return undefined;
}

export function shouldForceRefreshCodexNotReadyPluginApps(
  params: CodexPluginThreadAppAdmissionParams,
  policy: ResolvedCodexPluginsPolicy,
  inventory: CodexPluginInventory,
): boolean {
  if (
    !params.appCacheKey ||
    !policy.pluginPolicies.some((plugin) => plugin.enabled) ||
    inventory.appInventory?.state === "missing"
  ) {
    return false;
  }
  return inventory.records.some(
    (record) =>
      record.appOwnership === "proven" &&
      record.ownedAppIds.length > 0 &&
      (record.apps.length === 0 || record.apps.some((app) => !app.accessible)),
  );
}

import { describe, expect, it, vi } from "vitest";
import {
  attestCodexPluginThreadApps,
  discardUnattestedCodexPluginThread,
} from "./plugin-thread-attestation.js";
import type { v2 } from "./protocol.js";

describe("Codex plugin thread app attestation", () => {
  it("reads the committed snapshot with the started thread's effective policy", async () => {
    const request = vi.fn(async () => installedApps(["linear-app"]));

    await attestCodexPluginThreadApps({
      client: { request } as never,
      threadId: "thread-linear",
      appIds: ["linear-app", "linear-app"],
    });

    expect(request).toHaveBeenCalledExactlyOnceWith(
      "app/installed",
      { threadId: "thread-linear", forceRefresh: false },
      { signal: undefined },
    );
  });

  it("attests configured plugin and account apps against one thread snapshot", async () => {
    const request = vi.fn(async () => installedApps(["plugin-app", "account-app"]));

    await attestCodexPluginThreadApps({
      client: { request } as never,
      threadId: "thread-mixed-apps",
      appIds: ["plugin-app", "account-app", "plugin-app"],
    });

    expect(request).toHaveBeenCalledExactlyOnceWith(
      "app/installed",
      { threadId: "thread-mixed-apps", forceRefresh: false },
      { signal: undefined },
    );
  });

  it("rejects a mixed snapshot when the thread denies its account-wide app", async () => {
    const request = vi.fn(async () => installedApps(["plugin-app"]));

    await expect(
      attestCodexPluginThreadApps({
        client: { request } as never,
        threadId: "thread-mixed-apps",
        appIds: ["plugin-app", "account-app"],
      }),
    ).rejects.toMatchObject({
      name: "CodexPluginThreadAppAttestationError",
      message: expect.stringContaining("account-app:missing"),
    });

    expect(request).toHaveBeenCalledOnce();
  });

  it("does not read the app snapshot when no apps need attestation", async () => {
    const request = vi.fn();

    await attestCodexPluginThreadApps({
      client: { request } as never,
      threadId: "thread-linear",
      appIds: [],
    });

    expect(request).not.toHaveBeenCalled();
  });

  it.each([
    {
      state: "missing",
      response: installedApps([]),
      failure: "linear-app:missing",
    },
    {
      state: "disabled",
      response: installedApps(["linear-app"], { enabled: false, callable: false }),
      failure: "linear-app:disabled",
    },
    {
      state: "not callable",
      response: installedApps(["linear-app"], { callable: false }),
      failure: "linear-app:not-callable",
    },
  ])("fails closed when an admitted app is $state", async ({ response, failure }) => {
    await expect(
      attestCodexPluginThreadApps({
        client: { request: vi.fn(async () => response) } as never,
        threadId: "thread-linear",
        appIds: ["linear-app"],
      }),
    ).rejects.toMatchObject({
      name: "CodexPluginThreadAppAttestationError",
      message: expect.stringContaining(failure),
    });
  });

  it("preserves the original cause when thread-scoped discovery fails", async () => {
    const cause = new Error("committed app snapshot unavailable");

    await expect(
      attestCodexPluginThreadApps({
        client: {
          request: vi.fn(async () => {
            throw cause;
          }),
        } as never,
        threadId: "thread-linear",
        appIds: ["linear-app"],
      }),
    ).rejects.toMatchObject({
      name: "CodexPluginThreadAppAttestationError",
      cause,
    });
  });
});

describe("unattested Codex plugin thread cleanup", () => {
  it("deletes a persistent thread before its first rollout", async () => {
    const request = vi.fn(async () => ({}));

    await expect(
      discardUnattestedCodexPluginThread({
        client: { request } as never,
        threadId: "thread-persistent",
        ephemeral: false,
      }),
    ).resolves.toBe(true);

    expect(request).toHaveBeenCalledExactlyOnceWith(
      "thread/delete",
      { threadId: "thread-persistent" },
      { timeoutMs: 5_000 },
    );
  });

  it("unsubscribes an ephemeral thread that Codex cannot delete", async () => {
    const request = vi.fn(async () => ({}));

    await expect(
      discardUnattestedCodexPluginThread({
        client: { request } as never,
        threadId: "thread-ephemeral",
        ephemeral: true,
      }),
    ).resolves.toBe(true);

    expect(request).toHaveBeenCalledExactlyOnceWith(
      "thread/unsubscribe",
      { threadId: "thread-ephemeral" },
      { timeoutMs: 5_000 },
    );
  });

  it("does not treat unsubscribe as proof that a persistent thread was deleted", async () => {
    const request = vi.fn(async (method: string) => {
      if (method === "thread/delete") {
        throw new Error("thread deletion unavailable");
      }
      return {};
    });

    await expect(
      discardUnattestedCodexPluginThread({
        client: { request } as never,
        threadId: "thread-persistent",
        ephemeral: false,
      }),
    ).resolves.toBe(false);

    expect(request.mock.calls.map(([method]) => method)).toEqual([
      "thread/delete",
      "thread/unsubscribe",
    ]);
  });
});

function installedApps(
  appIds: string[],
  state: { enabled?: boolean; callable?: boolean } = {},
): v2.AppsInstalledResponse {
  return {
    apps: appIds.map((id) => ({
      id,
      runtimeName: id,
      enabled: state.enabled ?? true,
      callable: state.callable ?? true,
    })),
  };
}

/**
 * Confirms admitted plugin and account apps against their actual Codex thread before
 * OpenClaw commits a binding or starts a turn.
 */
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import {
  CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
  unsubscribeCodexThreadBestEffort,
} from "./attempt-client-cleanup.js";
import type { CodexAppServerClient } from "./client.js";
import type { v2 } from "./protocol.js";

class CodexPluginThreadAppAttestationError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "CodexPluginThreadAppAttestationError";
  }
}

/** Reads the existing runtime snapshot with the started thread's effective app policy. */
export async function attestCodexPluginThreadApps(params: {
  client: CodexAppServerClient;
  threadId: string;
  appIds: readonly string[];
  signal?: AbortSignal;
}): Promise<void> {
  const appIds = Array.from(new Set(params.appIds.filter(Boolean))).toSorted();
  if (appIds.length === 0) {
    return;
  }

  let response: v2.AppsInstalledResponse;
  try {
    response = await params.client.request(
      "app/installed",
      { threadId: params.threadId, forceRefresh: false },
      { signal: params.signal },
    );
  } catch (error) {
    throw new CodexPluginThreadAppAttestationError(
      `Codex could not confirm admitted apps for thread ${params.threadId}`,
      { cause: error },
    );
  }

  const installedById = new Map(response.apps.map((app) => [app.id, app] as const));
  const failures = appIds.flatMap((appId): string[] => {
    const app = installedById.get(appId);
    if (!app) {
      return [`${appId}:missing`];
    }
    if (!app.enabled) {
      return [`${appId}:disabled`];
    }
    return app.callable ? [] : [`${appId}:not-callable`];
  });
  if (failures.length > 0) {
    throw new CodexPluginThreadAppAttestationError(
      `Codex thread ${params.threadId} did not expose admitted apps: ${failures.join(", ")}`,
    );
  }
}

/** Deletes a persistent pre-turn thread; ephemeral threads can only be unsubscribed. */
export async function discardUnattestedCodexPluginThread(params: {
  client: CodexAppServerClient;
  threadId: string;
  ephemeral: boolean;
}): Promise<boolean> {
  if (params.ephemeral) {
    return await unsubscribeCodexThreadBestEffort(params.client, {
      threadId: params.threadId,
      timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
    });
  }

  try {
    await params.client.request(
      "thread/delete",
      { threadId: params.threadId },
      { timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS },
    );
    return true;
  } catch (error) {
    embeddedAgentLog.debug("codex plugin app attestation thread deletion failed", {
      threadId: params.threadId,
      error,
    });
    await unsubscribeCodexThreadBestEffort(params.client, {
      threadId: params.threadId,
      timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
    });
    return false;
  }
}

import {
  AgentHarnessPreflightError,
  type EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
/** Enforces one bounded startup budget across Codex plugin config discovery. */
import {
  defaultCodexAppInventoryCache,
  type CodexAppInventoryCache,
} from "./app-inventory-cache.js";
import type { CodexAppServerClient } from "./client.js";
import {
  resolveCodexPluginsPolicy,
  type CodexPluginConfig,
  type ResolvedCodexPluginsPolicy,
} from "./config.js";
import { disableCodexPluginThreadConfig } from "./dynamic-tool-build.js";
import {
  resolveRecoverableCodexPluginConfigKeys,
  type CodexPluginRuntimeRequest,
} from "./plugin-inventory.js";
import {
  defaultCodexPluginMetadataCache,
  type CodexPluginMetadataCache,
} from "./plugin-metadata-cache.js";
import {
  buildCodexPluginThreadConfig,
  buildCodexPluginThreadConfigTimeoutFallback,
  shouldBuildCodexPluginThreadConfig,
  type CodexPluginThreadConfig,
} from "./plugin-thread-config.js";
import {
  intersectCodexPluginThreadConfigWithScheduledAuthority,
  readCurrentCodexScheduledAppPolicy as readCurrentCodexScheduledAppPolicyShared,
} from "./scheduled-app-authority.js";
import type { CurrentCodexScheduledAppPolicy } from "./scheduled-app-authority.js";
import { withAbortableTimeout } from "./timeout.js";

const CODEX_PLUGIN_THREAD_CONFIG_MAX_TIMEOUT_MS = 60_000;
const CODEX_PLUGIN_THREAD_CONFIG_TIMEOUT_DIVISOR = 4;
const CODEX_PLUGIN_THREAD_CONFIG_MIN_TIMEOUT_MS = 100;

type CodexPluginThreadConfigDeadlineRequest = (
  method: string,
  params: unknown,
  options: { timeoutMs: number; signal: AbortSignal },
) => Promise<unknown>;

type BuildCodexPluginThreadConfigWithinDeadlineParams = Omit<
  Parameters<typeof buildCodexPluginThreadConfig>[0],
  "request"
> & {
  requestTimeoutMs: number;
  signal: AbortSignal;
  request: CodexPluginThreadConfigDeadlineRequest;
  failClosedOnTimeout?: boolean;
  transform?: (
    config: CodexPluginThreadConfig,
    request: CodexPluginRuntimeRequest,
  ) => Promise<CodexPluginThreadConfig>;
};

class CodexPluginThreadConfigDeadlineError extends Error {
  constructor() {
    super("Codex plugin thread config deadline elapsed");
    this.name = "CodexPluginThreadConfigDeadlineError";
  }
}

/** Resolves the plugin policy state reused throughout app-server startup. */
export function resolveCodexPluginThreadConfigStartupPolicy(params: {
  pluginConfig: CodexPluginConfig;
  nativeToolSurfaceEnabled: boolean;
  scheduledRuntimeAuthority?: EmbeddedRunAttemptParams["scheduledRuntimeAuthority"];
}) {
  const pluginThreadConfigRequired =
    Boolean(params.scheduledRuntimeAuthority) ||
    !params.nativeToolSurfaceEnabled ||
    shouldBuildCodexPluginThreadConfig(params.pluginConfig);
  // Restricted runs still need a config so thread/start carries an explicit
  // apps._default denial patch without app inventory discovery.
  const pluginThreadConfigPluginConfig =
    params.nativeToolSurfaceEnabled || params.scheduledRuntimeAuthority
      ? params.pluginConfig
      : disableCodexPluginThreadConfig(params.pluginConfig);
  const resolvedPluginPolicy = pluginThreadConfigRequired
    ? resolveCodexPluginsPolicy(pluginThreadConfigPluginConfig)
    : undefined;
  return {
    pluginThreadConfigRequired,
    pluginThreadConfigPluginConfig,
    resolvedPluginPolicy,
    enabledPluginConfigKeys: resolvedPluginPolicy
      ? resolvedPluginPolicy.pluginPolicies
          .filter((plugin) => plugin.enabled)
          .map((plugin) => plugin.configKey)
          .toSorted()
      : undefined,
  };
}

/** Builds plugin config without allowing sequential RPC timeouts to consume the turn. */
async function buildCodexPluginThreadConfigWithinDeadline(
  params: BuildCodexPluginThreadConfigWithinDeadlineParams,
): Promise<CodexPluginThreadConfig> {
  const { requestTimeoutMs, signal, request, failClosedOnTimeout, transform, ...buildParams } =
    params;
  const timeoutMs = resolveCodexPluginThreadConfigTimeoutMs(requestTimeoutMs);
  // One deadline owns the whole config build; every RPC gets only the remaining
  // budget so discovery cannot consume one full request timeout per call.
  const deadlineMs = Date.now() + timeoutMs;
  const boundedRequest: CodexPluginRuntimeRequest = (method, requestParams) => {
    const remainingTimeoutMs = deadlineMs - Date.now();
    if (remainingTimeoutMs <= 0) {
      throw new CodexPluginThreadConfigDeadlineError();
    }
    return request(method, requestParams, {
      timeoutMs: remainingTimeoutMs,
      signal,
    });
  };
  try {
    return await withAbortableTimeout({
      signal,
      timeoutMs,
      promise: (async () => {
        const config = await buildCodexPluginThreadConfig({
          ...buildParams,
          request: boundedRequest,
        });
        return transform ? await transform(config, boundedRequest) : config;
      })(),
      timeoutMessage: "Codex plugin thread config deadline elapsed",
      createTimeoutError: () => new CodexPluginThreadConfigDeadlineError(),
    });
  } catch (error) {
    if (signal.aborted || !isCodexPluginThreadConfigTimeoutError(error)) {
      throw error;
    }
    if (failClosedOnTimeout) {
      throw new AgentHarnessPreflightError(
        `Scheduled Codex app policy verification exceeded its ${timeoutMs} ms startup budget. No app tools were executed. Retry after Codex app inventory is responsive, or reauthorize the automation.`,
      );
    }
    return buildCodexPluginThreadConfigTimeoutFallback({
      pluginConfig: buildParams.pluginConfig,
      appCacheKey: buildParams.appCacheKey,
      message: `Codex plugin discovery exceeded its ${timeoutMs} ms startup budget; plugin apps were disabled for this turn.`,
    });
  }
}

/** Creates the recovery metadata and bounded builder used by thread startup. */
export function createCodexPluginThreadConfigStartupProvider(params: {
  inputFingerprint: string | undefined;
  enabledPluginConfigKeys: string[] | undefined;
  policy: ResolvedCodexPluginsPolicy | undefined;
  requestTimeoutMs: number;
  signal: AbortSignal;
  pluginConfig?: unknown;
  client: Pick<CodexAppServerClient, "request">;
  configCwd?: string;
  appCache?: CodexAppInventoryCache;
  appCacheKey: string;
  metadataCache?: CodexPluginMetadataCache;
  scheduledRuntimeAuthority?: EmbeddedRunAttemptParams["scheduledRuntimeAuthority"];
}) {
  const {
    client,
    policy,
    inputFingerprint,
    enabledPluginConfigKeys,
    appCache,
    metadataCache: configuredMetadataCache,
    ...buildParams
  } = params;
  const metadataCache = configuredMetadataCache ?? defaultCodexPluginMetadataCache;
  return {
    enabled: true,
    requiresCurrentPolicyCheck: Boolean(params.scheduledRuntimeAuthority),
    inputFingerprint,
    enabledPluginConfigKeys,
    accountAppRecoveryEnabled: policy?.allowAllPlugins,
    recoverablePluginConfigKeys: policy
      ? resolveRecoverableCodexPluginConfigKeys({
          policy,
          metadataCache,
          appCacheKey: params.appCacheKey,
          configCwd: params.configCwd,
        })
      : undefined,
    build: async (buildOptions?: { threadId?: string }) => {
      const config = await buildCodexPluginThreadConfigWithinDeadline({
        ...buildParams,
        threadId: buildOptions?.threadId,
        appCache: appCache ?? defaultCodexAppInventoryCache,
        metadataCache,
        failClosedOnTimeout: Boolean(params.scheduledRuntimeAuthority),
        transform: params.scheduledRuntimeAuthority
          ? async (builtConfig, request) =>
              intersectCodexPluginThreadConfigWithScheduledAuthority(
                builtConfig,
                params.scheduledRuntimeAuthority,
                await readCurrentCodexScheduledAppPolicy(
                  request,
                  params.configCwd,
                  buildOptions?.threadId,
                ),
              )
          : undefined,
        request: (method, requestParams, options) => client.request(method, requestParams, options),
      });
      return params.scheduledRuntimeAuthority && params.inputFingerprint
        ? { ...config, inputFingerprint: params.inputFingerprint }
        : config;
    },
  };
}

async function readCurrentCodexScheduledAppPolicy(
  request: CodexPluginRuntimeRequest,
  cwd: string | undefined,
  threadId: string | undefined,
): Promise<CurrentCodexScheduledAppPolicy> {
  return await readCurrentCodexScheduledAppPolicyShared({
    request,
    configCwd: cwd,
    threadId,
  });
}

function resolveCodexPluginThreadConfigTimeoutMs(requestTimeoutMs: number): number {
  const finiteRequestTimeoutMs =
    Number.isFinite(requestTimeoutMs) && requestTimeoutMs > 0
      ? requestTimeoutMs
      : CODEX_PLUGIN_THREAD_CONFIG_MAX_TIMEOUT_MS * CODEX_PLUGIN_THREAD_CONFIG_TIMEOUT_DIVISOR;
  return Math.min(
    CODEX_PLUGIN_THREAD_CONFIG_MAX_TIMEOUT_MS,
    Math.max(
      CODEX_PLUGIN_THREAD_CONFIG_MIN_TIMEOUT_MS,
      Math.floor(finiteRequestTimeoutMs / CODEX_PLUGIN_THREAD_CONFIG_TIMEOUT_DIVISOR),
    ),
  );
}

function isCodexPluginThreadConfigTimeoutError(error: unknown): boolean {
  return (
    error instanceof CodexPluginThreadConfigDeadlineError ||
    (error instanceof Error &&
      "code" in error &&
      error.code === "CODEX_APP_SERVER_LOCAL_REQUEST_CANCELLED" &&
      error.message.endsWith(" timed out"))
  );
}

