export async function activateCodexAttemptTurn(
  resources: CodexAttemptResources,
  turnRuntime: CodexAttemptTurnState,
  lifecycle: CodexAttemptLifecycleController,
  notifications: CodexAttemptNotificationController,
  turn: CodexTurnStartResponse,
) {
  const {
    prompt,
    state: resourceState,
    projectorRef,
    trajectoryRecorder,
    pendingNativePreToolUseFailures,
  } = resources;
  const { context, turnState } = prompt;
  const { runtime, attemptTools } = context;
  const { connection } = runtime;
  const {
    params,
    runAbortController,
    terminalState,
    abortExplicitly,
    abortFromUpstream,
    bindingStore,
    bindingIdentity,
    sessionAgentId,
    contextSessionKey,
    effectiveCwd,
  } = connection;
  const { dynamicToolParams, compactionPlanState, computerContextEpoch, toolBridge } = attemptTools;
  const { state, userInputBridgeRef, steeringQueueRef, turnWatches, completeTurn, interruptTurn } =
    turnRuntime;
  const { emitExecutionPhaseOnce, emitLifecycleStart, maybeAnnounceFastModeAutoOff } = lifecycle;
  const { enqueueNotification } = notifications;
  const activeTurnId = turn.turn.id;
  const progressCardTool = toolBridge.availableTools.find((tool) => tool.name === "progress_card");
  let nativePlanUpdateOrdinal = 0;
  const prepareNativeMcpAppResultDetails = createCodexNativeMcpAppResultDetailsPreparer({
    client: resourceState.client,
    threadId: resourceState.thread.threadId,
    attempt: dynamicToolParams,
  });
  const streamState = { eventEmitted: false, needsTerminalSnapshot: false };
  emitExecutionPhaseOnce("turn_accepted", { phase: "turn_accepted" });
  userInputBridgeRef.current = createCodexUserInputBridge({
    paramsForRun: params,
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
    signal: runAbortController.signal,
  });
  trajectoryRecorder?.recordEvent("prompt.submitted", {
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
    prompt: turnState.codexTurnPromptText,
    imagesCount: params.images?.length ?? 0,
  });
  projectorRef.current = new CodexAppServerEventProjector(
    {
      ...dynamicToolParams,
      onAgentEvent: (event) => {
        if (event.stream === "assistant" && typeof event.data.delta === "string") {
          streamState.eventEmitted = true;
          streamState.needsTerminalSnapshot ||= event.data.replaceable === true;
        }
        return dynamicToolParams.onAgentEvent?.(event);
      },
    },
    resourceState.thread.threadId,
    activeTurnId,
    {
      initialContextTokens: connection.mutable.startupContextTokens,
      nativePostToolUseRelayEnabled:
        resourceState.nativeHookRelay?.allowedEvents.includes("post_tool_use") === true &&
        resourceState.nativeHookRelay.shouldRelayEvent("post_tool_use"),
      asyncUserMessageAllowed:
        params.disableTools !== true &&
        (params.toolsAllow === undefined ||
          toolBridge.availableTools.some((tool) => tool.name === "message")),
      onAsyncDelivery: async (delivery) => {
        return await codexTranscriptMirrorRuntime.deliverAsyncMessageBestEffort({
          params: dynamicToolParams,
          cwd: effectiveCwd,
          threadId: resourceState.thread.threadId,
          turnId: activeTurnId,
          ...delivery,
        });
      },
      readRecentRateLimits: () => readRecentCodexRateLimits(resourceState.client),
      runAbortSignal: runAbortController.signal,
      remoteWorkspaceRoot: connection.appServer.remoteWorkspaceRoot,
      remoteWorkspaceRequestTimeoutMs: connection.appServer.requestTimeoutMs,
      readRemoteWorkspaceFile: ({ path, maxBytes, signal, timeoutMs }) =>
        readBoundedCodexRemoteWorkspaceFile({
          client: resourceState.client,
          path,
          maxBytes,
          signal,
          timeoutMs,
        }),
      trajectoryRecorder,
      resolveDynamicToolResultContentSource: toolBridge.resultContentSourceForTool,
      onNativeToolResultRecorded: maybeAnnounceFastModeAutoOff,
      ...(progressCardTool
        ? {
            onNativePlanUpdate: async (update: {
              markdown?: string;
              steps: Array<{
                step: string;
                status: "pending" | "in_progress" | "completed";
              }>;
            }) => {
              nativePlanUpdateOrdinal += 1;
              try {
                const input = canonicalizeNativeProgressCardInput(update);
                await progressCardTool.execute(
                  `codex-native-plan:${activeTurnId}:${nativePlanUpdateOrdinal}`,
                  input,
                  runAbortController.signal,
                );
              } catch (error) {
                embeddedAgentLog.warn("failed to persist native Codex plan to progress card", {
                  runId: params.runId,
                  threadId: resourceState.thread.threadId,
                  error: formatErrorMessage(error),
                });
              }
            },
          }
        : {}),
      ...(prepareNativeMcpAppResultDetails ? { prepareNativeMcpAppResultDetails } : {}),
      upstreamUserText: turnState.codexTurnPromptText,
      onContextCompacted: async () => {
        computerContextEpoch.value += 1;
        delete computerContextEpoch.frameToolCallId;
        delete computerContextEpoch.frameImageIdentity;
        try {
          await compactionPlanState.restore({
            client: resourceState.client,
            threadId: resourceState.thread.threadId,
            timeoutMs: connection.appServer.requestTimeoutMs,
            signal: runAbortController.signal,
          });
        } catch (error) {
          embeddedAgentLog.warn("failed to restore Codex plan state after compaction", {
            runId: params.runId,
            threadId: resourceState.thread.threadId,
            error: formatErrorMessage(error),
          });
        }
      },
    },
  );
  if (isTerminalTurnStatus(turn.turn.status)) {
    state.terminalTurnNotificationQueued = true;
  }
  emitLifecycleStart();
  const activeProjector = projectorRef.current;
  turnWatches.armTerminalIdleWatch();
  turnWatches.touchActivity("turn:start", { arm: true });
  turnWatches.armAttemptIdleWatch();
  turnWatches.touchActivity("turn:start", { attemptProgress: true });
  for (const failure of pendingNativePreToolUseFailures.splice(0)) {
    activeProjector.recordNativeToolPreToolUseFailure(failure);
  }
  const notifyUserMessagePersisted = createCodexAppServerUserMessagePersistenceNotifier(params);
  // Buffered async items can persist immediately when the route opens. Commit
  // their owning user admission first so durable history stays chronological.
  const promptMirrorPromise = mirrorPromptAtTurnStartBestEffort({
    params,
    agentId: sessionAgentId,
    notifyUserMessagePersisted,
    sessionKey: contextSessionKey,
    cwd: effectiveCwd,
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
    upstreamUserText: turnState.codexTurnPromptText,
  });
  await promptMirrorPromise;
  // The route buffers early events. Publish full turn context, then release in wire order.
  if (resourceState.turnRoute) {
    try {
      await resourceState.turnRoute.bindTurn(activeTurnId);
    } catch (error) {
      if (!state.terminalTurnNotificationQueued) {
        throw error;
      }
      await resourceState.turnRoute.drain();
      if (!state.completed) {
        turnWatches.clearAllTimers();
        throw error;
      }
    }
  }
  if (!state.completed && isTerminalTurnStatus(turn.turn.status)) {
    if (!isJsonObject(turn.turn)) {
      throw new Error("Codex turn completion payload is not a JSON object");
    }
    await enqueueNotification(
      {
        method: "turn/completed",
        params: {
          threadId: resourceState.thread.threadId,
          turnId: activeTurnId,
          turn: turn.turn,
        },
      },
      { threadId: resourceState.thread.threadId, turnId: activeTurnId },
    );
  }
  const assertSteeringActive = () => {
    params.hostCapabilities.assertActive();
    runAbortController.signal.throwIfAborted();
    if (state.completed || state.terminalTurnNotificationQueued || state.timedOut) {
      throw new Error("codex app-server turn is no longer accepting steering");
    }
  };
  const workspaceOnly = resolveAttemptFsWorkspaceOnly({ config: params.config, sessionAgentId });
  const imageContext = {
    workspaceDir: connection.effectiveWorkspace,
    model: params.model,
    config: params.config,
    workspaceOnly,
    localRoots: workspaceOnly
      ? undefined
      : getAgentScopedMediaLocalRoots(params.config ?? {}, sessionAgentId),
    sandbox:
      connection.sandbox?.enabled && connection.sandbox.fsBridge
        ? { root: connection.sandbox.workspaceDir, bridge: connection.sandbox.fsBridge }
        : undefined,
  };
  const activeSteeringQueue = createCodexSteeringQueue({
    client: resourceState.client,
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
    requestTimeoutMs: connection.appServer.requestTimeoutMs,
    signal: runAbortController.signal,
    assertActive: assertSteeringActive,
    prepareMessage: async (text, options) => {
      const result = await detectAndLoadAgentHarnessPromptImages({
        ...imageContext,
        prompt: text,
        existingImages: options.images,
        imageOrder: options.imageOrder,
        media: options.media,
        userTurnTranscriptRecorder: options.userTurnTranscriptRecorder,
      });
      if (result.failedMediaCount) {
        throw new Error(
          `failed to hydrate ${result.failedMediaCount} structured image attachment(s) for Codex steering`,
        );
      }
      return buildCodexUserInput(text, result.images);
    },
    beforeConfirmConsumed: async (items) => {
      // Internal steering can own a user turn too. Commit its recorder after the
      // preceding answers so source provenance and transcript ordering survive.
      const transcriptItems = items.filter(
        (item) =>
          item.isInboundUserMessage === true || item.userTurnTranscriptRecorder !== undefined,
      );
      if (transcriptItems.length === 0) {
        return;
      }
      await promptMirrorPromise;
      const messages = activeProjector.buildSteeringTranscriptPrefix();
      if (params.sessionTarget && messages.length > 0) {
        await codexTranscriptMirrorRuntime.mirror({
          agentId: sessionAgentId,
          sessionKey: contextSessionKey,
          sessionId: params.sessionId,
          storePath: params.sessionTarget.storePath,
          cwd: effectiveCwd,
          messages,
          idempotencyScope: `codex-app-server:${resourceState.thread.threadId}`,
          runId: params.runId,
          runMirrorIdentityPrefix: `${activeTurnId}:`,
          config: params.config,
        });
        activeProjector.markSteeringTranscriptPersisted();
      }
      for (const item of transcriptItems) {
        const recorder = item.userTurnTranscriptRecorder;
        if (!recorder) {
          continue;
        }
        await recorder.persistApproved();
        if (!recorder.hasPersisted()) {
          throw new Error("Codex consumed steering before its user turn was persisted");
        }
      }
    },
  });
  steeringQueueRef.current = activeSteeringQueue;
  const claimPendingUserInputAnswer = async (
    text: string,
    optionsLocal?: CodexSteeringQueueOptions,
  ) => {
    if (optionsLocal?.isInboundUserMessage !== true || hasPromptImageInput(optionsLocal)) {
      return false;
    }
    assertSteeringActive();
    return await claimPendingAgentQuestionAnswer({
      sessionKey: params.sessionKey ?? params.sessionId,
      text,
      persist: optionsLocal.userTurnTranscriptRecorder
        ? async () => {
            await optionsLocal.userTurnTranscriptRecorder?.persistApproved();
          }
        : undefined,
    });
  };
  const cancelPendingUserInput = (resolvedBy: string) =>
    cancelPendingAgentQuestionForSession({
      sessionKey: params.sessionKey ?? params.sessionId,
      resolvedBy,
    });
  const queueMessage = async (text: string, optionsLocal?: CodexSteeringQueueOptions) => {
    if (await claimPendingUserInputAnswer(text, optionsLocal)) {
      // A question claim is already consumption. Closing the run during its
      // response must not turn that answer into a rejected, replayable steer.
      optionsLocal?.onQueueAccepted?.(true);
      return undefined;
    }
    if (optionsLocal?.isInboundUserMessage === true && hasPromptImageInput(optionsLocal)) {
      assertSteeringActive();
      try {
        await cancelPendingUserInput("image-reply");
      } catch (error) {
        // Cleanup failure must not drop the user's image turn.
        embeddedAgentLog.warn("failed to cancel codex gateway question before image steering", {
          error,
        });
      }
    }
    try {
      await activeSteeringQueue.queue(text, optionsLocal);
    } catch (error) {
      if (error instanceof CodexSteeringAcceptedUnconfirmedError) {
        return {
          transcriptCommit: "unconfirmed" as const,
          errorMessage: formatErrorMessage(error),
        };
      }
      throw error;
    }
    return undefined;
  };
  const handle = {
    kind: "embedded" as const,
    runId: params.runId,
    startedAtMs: params.startedAtMs,
    toolAuthorityFingerprint: params.toolAuthorityFingerprint,
    permissionChangeOwner: params.permissionChange?.owner,
    applyPermissionMode: async (
      mode: NonNullable<typeof params.permissionMode> | null,
      revokeApprovals: () => void,
    ) => {
      if (
        !params.permissionChange ||
        terminalState.terminalOutcomeFrozen ||
        params.abortSignal?.aborted ||
        (!state.permissionChangeRestart && (state.completed || runAbortController.signal.aborted))
      ) {
        return false;
      }
      const applied = params.permissionChange.request(mode);
      state.permissionChangeRestart ??= "requested";
      // A policy replacement cancels this native turn, not the admitted outer
      // run. Its successor must be prepared only after native stop and cleanup.
      runAbortController.abort("permission-change");
      revokeApprovals();
      return await applied;
    },
    claimPendingUserInputAnswer,
    cancelPendingUserInput,
    queueMessage,
    messageInjection: {
      isAvailable: () =>
        !state.completed &&
        !state.terminalTurnNotificationQueued &&
        !state.timedOut &&
        !runAbortController.signal.aborted,
      queueMessage,
    },
    isStreaming: () => !state.completed && !runAbortController.signal.aborted,
    isAborted: () => runAbortController.signal.aborted,
    isStopped: () => state.completed || state.timedOut || runAbortController.signal.aborted,
    isAbortable: () =>
      !terminalState.terminalOutcomeFrozen || terminalState.sharedAbortAllowedAfterTerminalOutcome,
    isCompacting: () => projectorRef.current?.isCompacting() ?? false,
    // queueMessage resolves only after Codex echoes the steered userMessage completion.
    // Gateway-owned turns rely on that boundary before finalizing adoption.
    supportsTranscriptCommitWait: true,
    supportsQueueMessageImages: params.model.input.includes("image"),
    sourceReplyDeliveryMode: params.sourceReplyDeliveryMode,
    taskSuggestionDeliveryMode: params.taskSuggestionDeliveryMode,
    cancel: () => abortExplicitly("cancelled"),
    abort: () => abortExplicitly("aborted"),
  };
  params.replyOperation?.attachBackend(handle);
  setActiveEmbeddedRun(params.sessionId, handle, params.sessionKey, params.sessionFile);
  const freezeRunTerminalOutcome = () => {
    if (terminalState.terminalOutcomeFrozen) {
      return;
    }
    terminalState.terminalOutcomeFrozen = true;
    params.abortSignal?.removeEventListener("abort", abortFromUpstream);
  };
  const abortListener = () => {
    if (state.timedOut) {
      void (async () => {
        // Supervised sessions stay native; clearing scope would silently move the next attempt.
        if (resourceState.thread.connectionScope !== "supervision") {
          await bindingStore.mutate(bindingIdentity, {
            kind: "clear",
            threadId: resourceState.thread.threadId,
          });
        }
        await retireCodexAppServerClientAfterTimedOutTurn(resourceState.client, {
          threadId: resourceState.thread.threadId,
          turnId: activeTurnId,
          reason: String(runAbortController.signal.reason ?? "timeout"),
          suspectPhysicalClient: state.turnWatchTimeoutKind === "terminal",
        });
      })().finally(completeTurn);
      return;
    }
    state.abortCleanup = interruptTurn(activeTurnId).then(async (confirmed) => {
      if (!terminalState.explicitCancellationObserved && !state.permissionChangeRestart) {
        return;
      }
      if (!confirmed) {
        throw new Error(
          state.permissionChangeRestart
            ? "Permission change could not confirm the previous Codex turn stopped."
            : "Codex cancellation could not confirm the turn stopped; background terminals may still be running.",
        );
      }
      // turn/completed leaves native terminals running under their old policy.
      // Keep the route and lease until cancellation or policy replacement cleans them up.
      await terminateCodexBackgroundTerminals(resourceState.client, resourceState.thread.threadId);
      if (state.permissionChangeRestart) {
        state.permissionChangeRestart = "confirmed";
      }
    });
    void state.abortCleanup.then(completeTurn, (error: unknown) => {
      embeddedAgentLog.warn("codex app-server cancellation cleanup failed", { error });
      completeTurn();
    });
  };
  runAbortController.signal.addEventListener("abort", abortListener, { once: true });
  if (runAbortController.signal.aborted) {
    abortListener();
  } else if (params.permissionChange && !params.permissionChange.applied()) {
    state.permissionChangeRestart = "requested";
    runAbortController.abort("permission-change");
  }
  return {
    activeTurnId,
    activeProjector,
    streamState,
    handle,
    freezeRunTerminalOutcome,
    notifyUserMessagePersisted,
    abortListener,
  };
}

export type CodexAttemptActiveTurn = Awaited<ReturnType<typeof activateCodexAttemptTurn>>;

import { clearActiveEmbeddedRun } from "openclaw/plugin-sdk/agent-harness-runtime";
import { isIncognitoSessionKey } from "../incognito-session.js";
import {
  CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
  closeCodexStartupClientBestEffort,
  unsubscribeCodexThreadBestEffort,
} from "./attempt-client-cleanup.js";
import { resolveCodexAppServerClientInstanceId } from "./client.js";
import { scheduleCodexNativeHookRelayUnregister } from "./native-hook-relay.js";
import type { CodexAttemptActiveTurn } from "./run-attempt-active-turn.js";
import type { CodexAttemptLifecycleController } from "./run-attempt-lifecycle-controller.js";
import type { CodexAttemptResources } from "./run-attempt-resources.js";
import type { prepareCodexAttemptTurnRequest } from "./run-attempt-turn-request.js";
import type { CodexAttemptTurnState } from "./run-attempt-turn-state.js";
import { retainCodexAppServerBindingSubscription } from "./thread-ownership.js";

export async function cleanupCodexAttempt(
  resources: CodexAttemptResources,
  turnRuntime: CodexAttemptTurnState,
  lifecycle: CodexAttemptLifecycleController,
  requestRuntime: Awaited<ReturnType<typeof prepareCodexAttemptTurnRequest>>,
  activeTurn: CodexAttemptActiveTurn,
) {
  const {
    prompt,
    state: resourceState,
    trajectoryRecorder,
    releaseCurrentRoute,
    releaseSharedClientLeaseAndRetireOneShotClient,
    releaseSandboxExecEnvironment,
    runCleanupStep,
  } = resources;
  const { connection } = prompt.context.runtime;
  const { params, options, runAbortController, terminalState, bindingStore, bindingIdentity } =
    connection;
  const { state, steeringQueueRef, userInputBridgeRef, turnWatches } = turnRuntime;
  const {
    maybeEmitFastModeAutoResetBestEffort,
    emitLifecycleTerminal,
    buildLifecycleTerminalMeta,
  } = lifecycle;
  const { codexModelCallDiagnostics } = requestRuntime;
  const { activeTurnId, abortListener, handle, freezeRunTerminalOutcome } = activeTurn;
  // Exact-thread cron authority exists only while this creator turn owns the
  // live client/thread. Retained model callbacks must fail after cleanup begins.
  prompt.context.attemptTools.scheduledAppAuthoritySourceRef.current = undefined;
  // Finalization can throw before freezing. Close cancellation admission before
  // any teardown await so it cannot replace the cleanup promise being joined.
  freezeRunTerminalOutcome();
  // Join late cancellation before releasing the subscription, but do not let a
  // failed terminal RPC skip resource cleanup. Surface that failure below.
  await state.abortCleanup.catch(() => undefined);
  try {
    steeringQueueRef.current?.cancel();
    if (params.isFinalFallbackAttempt !== false) {
      await maybeEmitFastModeAutoResetBestEffort();
    }
    codexModelCallDiagnostics.emitError(
      "codex app-server run completed without model-call terminal event",
    );
    emitLifecycleTerminal({
      phase: "error",
      error: "codex app-server run completed without lifecycle terminal event",
      ...buildLifecycleTerminalMeta({
        aborted: runAbortController.signal.aborted && !state.clientClosedAbort,
        timedOut: state.timedOut,
      }),
    });
    if (trajectoryRecorder && !resourceState.trajectoryEndRecorded) {
      trajectoryRecorder.recordEvent("session.ended", {
        status:
          state.timedOut || (runAbortController.signal.aborted && !state.clientClosedAbort)
            ? "interrupted"
            : "cleanup",
        threadId: resourceState.thread.threadId,
        turnId: activeTurnId,
        timedOut: state.timedOut,
        aborted: runAbortController.signal.aborted && !state.clientClosedAbort,
      });
    }
    await runCleanupStep("codex-trajectory-flush", () => trajectoryRecorder?.flush());
    const retainLiveIncognitoThread =
      (terminalState.turnSucceeded ||
        (state.permissionChangeRestart === "confirmed" && !params.abortSignal?.aborted)) &&
      isIncognitoSessionKey(params.sessionKey);
    // Native-preserved and supervision threads have separate ownership and can
    // never enter the ordinary persistent warm-thread cache.
    const retainedPersistentThread =
      terminalState.turnSucceeded &&
      !isIncognitoSessionKey(params.sessionKey) &&
      params.cleanupBundleMcpOnRunEnd !== true &&
      resourceState.thread.liveThreadConfigFingerprint !== undefined &&
      resourceState.thread.clientId ===
        resolveCodexAppServerClientInstanceId(resourceState.client) &&
      resourceState.thread.preserveNativeModel !== true &&
      resourceState.thread.connectionScope !== "supervision" &&
      !resourceState.thread.ringZeroConfigFingerprint
        ? (await bindingStore.read(bindingIdentity))?.threadId === resourceState.thread.threadId &&
          (await bindingStore.withLease(bindingIdentity, async () => {
            // Reset/end uses this same generation lease. Never publish an old
            // active turn after its session binding has already been retired.
            if (
              (await bindingStore.read(bindingIdentity))?.threadId !== resourceState.thread.threadId
            ) {
              return false;
            }
            return await retainCodexAppServerBindingSubscription(
              resourceState.client,
              resourceState.thread.threadId,
              {
                release: resourceState.thread.liveThreadOwnership?.release,
                configFingerprint: resourceState.thread.liveThreadConfigFingerprint,
                serviceTier: connection.mutable.pluginAppServer.serviceTier,
              },
            );
          }))
        : false;
    // Codex keeps approvals in its native session; independent conversations
    // must retain their own subscriptions instead of evicting one another.
    const retainLiveThread = retainLiveIncognitoThread || retainedPersistentThread;
    const bindingReleased =
      isIncognitoSessionKey(params.sessionKey) && !retainLiveIncognitoThread
        ? await bindingStore.mutate(bindingIdentity, {
            kind: "clear",
            threadId: resourceState.thread.threadId,
          })
        : true;
    // Only explicitly retained live threads may skip the next thread/resume.
    if (!state.timedOut && !retainLiveThread) {
      // Clear first: if a newer owner won the binding, its live subscription must remain intact.
      if (bindingReleased) {
        const released = await unsubscribeCodexThreadBestEffort(resourceState.client, {
          threadId: resourceState.thread.threadId,
          timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
        });
        if (!released) {
          // Never reuse a client whose previous thread may still publish notifications.
          await closeCodexStartupClientBestEffort(resourceState.client);
        }
      }
    }
  } finally {
    await runCleanupStep("codex-user-input-cancel", () =>
      userInputBridgeRef.current?.cancelPending(),
    );
    await runCleanupStep("codex-turn-watch-clear", () => turnWatches.clearAllTimers());
    await runCleanupStep("codex-dynamic-tool-cleanup", async () => {
      const cleanupReason = terminalState.turnSucceeded
        ? "completion"
        : state.timedOut
          ? "timeout"
          : runAbortController.signal.aborted
            ? "cancel"
            : "error";
      const cleanups = prompt.context.attemptTools.runCleanups.splice(0);
      await Promise.allSettled(cleanups.map(async (cleanup) => await cleanup(cleanupReason)));
    });
    await runCleanupStep("codex-route-release", releaseCurrentRoute);
    await runCleanupStep("codex-transcript-checkpoint", () =>
      activeTurn.activeProjector.transcriptCheckpoint.flush(true),
    );
    await runCleanupStep(
      "codex-shared-client-release",
      releaseSharedClientLeaseAndRetireOneShotClient,
    );
    const nativeHookRelay = resourceState.nativeHookRelay;
    resourceState.nativeHookRelay = undefined;
    await runCleanupStep("codex-native-hook-relay-release", () => {
      if (!nativeHookRelay) {
        return;
      }
      if (state.shouldDelayNativeHookRelayUnregister) {
        // Native hook subprocesses can finish shortly after turn completion.
        scheduleCodexNativeHookRelayUnregister({
          relay: nativeHookRelay,
          hookTimeoutSec: options.nativeHookRelay?.hookTimeoutSec,
        });
      } else {
        nativeHookRelay.unregister();
      }
    });
    await runCleanupStep("codex-sandbox-release", releaseSandboxExecEnvironment);
    await runCleanupStep("codex-scoped-mcp-dispose", () =>
      prompt.context.attemptTools.scopedMcpTools?.dispose(),
    );
    await runCleanupStep("codex-scheduled-mcp-dispose", () =>
      prompt.context.attemptTools.scheduledConfiguredMcp?.dispose(),
    );
    await runCleanupStep("codex-abort-listener-remove", () => {
      runAbortController.signal.removeEventListener("abort", abortListener);
    });
    await runCleanupStep("codex-steering-cancel", () => steeringQueueRef.current?.cancel());
    await runCleanupStep("codex-reply-backend-detach", () =>
      params.replyOperation?.detachBackend(handle),
    );
    await runCleanupStep("codex-active-run-clear", () => {
      clearActiveEmbeddedRun(params.sessionId, handle, params.sessionKey, params.sessionFile);
    });
  }
  await state.abortCleanup;
}

