export async function finalizeCodexAttempt(
  resources: CodexAttemptResources,
  turnRuntime: CodexAttemptTurnState,
  lifecycle: CodexAttemptLifecycleController,
  notifications: CodexAttemptNotificationController,
  requestRuntime: Awaited<ReturnType<typeof prepareCodexAttemptTurnRequest>>,
  activeTurn: CodexAttemptActiveTurn,
): Promise<EmbeddedRunAttemptResult> {
  const { prompt, state: resourceState, trajectoryRecorder, markTrajectoryEndRecorded } = resources;
  const { context, systemPromptReport } = prompt;
  const { runtime, attemptTools, activeTranscriptTarget, hookContext } = context;
  const { hookContextWindowFields, hookRunner } = context;
  const { connection, preparedAuthBinding } = runtime;
  const { effectiveRuntimeProviderId, effectiveRuntimeModelId } = runtime;
  const {
    params,
    terminalState,
    runAbortController,
    activeContextEngine,
    bindingStore,
    bindingIdentity,
    appServer,
    usesSupervisionConnection,
    sessionAgentId,
    contextSessionKey,
    effectiveCwd,
    agentDir,
    attemptStartedAt,
    startupAuthProfileId,
  } = connection;
  const { toolBridge, toolState } = attemptTools;
  const {
    state,
    completion,
    pendingOpenClawDynamicToolCompletionIds,
    activeTurnItemIds,
    activeCompletionBlockerItemIds,
    activeFinalizationHookRunIds,
    turnWatches,
  } = turnRuntime;
  const { emitLifecycleTerminal, buildLifecycleTerminalMeta } = lifecycle;
  const { drainNotificationQueue } = notifications;
  const { codexModelCallDiagnostics } = requestRuntime;
  const {
    activeTurnId,
    activeProjector,
    streamState,
    freezeRunTerminalOutcome,
    notifyUserMessagePersisted,
  } = activeTurn;
  await completion;
  await state.abortCleanup;
  // Timeout and Stop still join queued projections within the abort grace;
  // normal completion awaits the full drain.
  const drain = drainNotificationQueue();
  const abortGraceElapsed = createDeferred<void>();
  let abortGraceTimer: ReturnType<typeof setTimeout> | undefined;
  const abortListener = addAbortListener(runAbortController.signal, () => {
    abortGraceTimer = setTimeout(
      () => abortGraceElapsed.resolve(),
      TURN_FINALIZE_DRAIN_ABORT_GRACE_MS,
    );
    abortGraceTimer.unref?.();
  });
  try {
    await Promise.race([drain, abortGraceElapsed.promise]);
  } finally {
    abortListener[Symbol.dispose]();
    clearTimeout(abortGraceTimer);
  }
  const hasQuiescentCompletedAssistant =
    activeProjector.hasCompletedTerminalAssistantText() &&
    state.activeAppServerTurnRequests === 0 &&
    activeTurnItemIds.size === 0 &&
    activeCompletionBlockerItemIds.size === 0 &&
    pendingOpenClawDynamicToolCompletionIds.size === 0 &&
    activeFinalizationHookRunIds.size === 0 &&
    state.unsettledFinalizationHookCount === 0 &&
    state.rejectedFinalizationHookAssistant === undefined;
  const hasRecoverableCompletedAssistant =
    !turnWatches.isCompletionIdleWatchPinnedByTerminalError() &&
    turnWatches.isAssistantCompletionIdleWatchArmed() &&
    hasQuiescentCompletedAssistant;
  const recoveredTurnWatchTimeout =
    state.turnCompletionIdleTimedOut &&
    !terminalState.explicitCancellationObserved &&
    hasRecoverableCompletedAssistant &&
    activeProjector.recoverCompletedTerminalAssistantAfterTurnWatchTimeout();
  if (recoveredTurnWatchTimeout) {
    embeddedAgentLog.warn(
      "codex app-server recovered completed assistant output after missing turn completion",
      {
        threadId: resourceState.thread.threadId,
        turnId: activeTurnId,
        timeoutKind: state.turnWatchTimeoutKind,
        idleMs: state.turnWatchTimeoutIdleMs,
        timeoutMs: state.turnWatchTimeoutMs,
      },
    );
    trajectoryRecorder?.recordEvent("turn.watch_timeout_recovered", {
      threadId: resourceState.thread.threadId,
      turnId: activeTurnId,
      timeoutKind: state.turnWatchTimeoutKind,
      idleMs: state.turnWatchTimeoutIdleMs,
      timeoutMs: state.turnWatchTimeoutMs,
    });
  }
  const result = activeProjector.buildResult(toolBridge.telemetry, {
    yieldDetected: toolState.yieldDetected,
  });
  const projectedTerminal = attemptTerminal.project(result.terminal);
  const effectiveTimedOut = state.timedOut && !recoveredTurnWatchTimeout;
  const effectiveTurnCompletionIdleTimedOut =
    state.turnCompletionIdleTimedOut && !recoveredTurnWatchTimeout;
  // Transport loss aborts in-flight work mechanically, but its terminal outcome
  // must remain a failure unless the operator explicitly canceled the attempt.
  const isFinalAborted = () =>
    terminalState.explicitCancellationObserved ||
    (!resourceState.executionDisconnectError &&
      (projectedTerminal.aborted ||
        (runAbortController.signal.aborted &&
          !state.clientClosedAbort &&
          !recoveredTurnWatchTimeout)));
  const clientClosedPromptErrorForFinal =
    state.clientClosedPromptError && hasRecoverableCompletedAssistant
      ? undefined
      : state.clientClosedPromptError;
  let finalPromptError =
    resourceState.executionDisconnectError ??
    clientClosedPromptErrorForFinal ??
    (effectiveTurnCompletionIdleTimedOut
      ? state.turnCompletionIdleTimeoutMessage
      : effectiveTimedOut
        ? "codex app-server attempt timed out"
        : projectedTerminal.promptError);
  const finalPromptErrorMessage =
    typeof finalPromptError === "string"
      ? finalPromptError
      : finalPromptError instanceof Error
        ? finalPromptError.message
        : finalPromptError
          ? formatErrorMessage(finalPromptError)
          : undefined;
  if (isInvalidCodexImagePayloadError(finalPromptErrorMessage)) {
    await clearCodexBindingAfterInvalidImagePayload(bindingStore, bindingIdentity, {
      phase: "turn_completed",
      threadId: resourceState.thread.threadId,
      turnId: activeTurnId,
      error: finalPromptErrorMessage,
    });
  }
  if (
    resourceState.thread.connectionScope !== "supervision" &&
    shouldUseFreshCodexThreadAfterContextEngineOverflow({
      error: finalPromptError,
      contextEngineActive: Boolean(activeContextEngine),
      thread: resourceState.thread,
    })
  ) {
    embeddedAgentLog.warn(
      "codex app-server context-engine turn overflowed after resume; clearing thread binding for recovery",
      {
        threadId: resourceState.thread.threadId,
        turnId: activeTurnId,
        error: finalPromptErrorMessage,
      },
    );
    await bindingStore.mutate(bindingIdentity, {
      kind: "clear",
      threadId: resourceState.thread.threadId,
    });
  }
  const refreshedUsageLimitPromptError = await refreshCodexUsageLimitPromptError({
    client: resourceState.client,
    message: finalPromptErrorMessage,
    timeoutMs: appServer.requestTimeoutMs,
    signal: runAbortController.signal,
  });
  if (refreshedUsageLimitPromptError) {
    await markCodexAuthProfileBlockedFromRateLimits({
      params,
      authProfileId: startupAuthProfileId,
      rateLimits: refreshedUsageLimitPromptError.rateLimitsForProfile,
    });
    finalPromptError = createCodexUsageLimitPromptError(refreshedUsageLimitPromptError.message);
  } else if (
    isCodexUsageLimitPromptError(finalPromptError) &&
    state.rateLimitsRevisionBeforeLastTurnStart !== undefined &&
    readCodexRateLimitsRevision(resourceState.client) > state.rateLimitsRevisionBeforeLastTurnStart
  ) {
    await markCodexAuthProfileBlockedFromRateLimits({
      params,
      authProfileId: startupAuthProfileId,
      rateLimits: readRecentCodexRateLimits(resourceState.client),
    });
  }
  // Device loss can arrive during asynchronous failure enrichment. Re-read its
  // owner before freezing derived success, cancellation, and terminal state.
  finalPromptError = resourceState.executionDisconnectError ?? finalPromptError;
  const finalPromptErrorSource =
    effectiveTimedOut || clientClosedPromptErrorForFinal
      ? "prompt"
      : projectedTerminal.promptErrorSource;
  const codexAppServerFailureKind = clientClosedPromptErrorForFinal
    ? "client_closed_before_turn_completed"
    : effectiveTurnCompletionIdleTimedOut
      ? "turn_completion_idle_timeout"
      : undefined;
  const replayBlockedReason = codexAppServerFailureKind
    ? resolveCodexAppServerReplayBlockedReason(result)
    : undefined;
  const promptTimeoutOutcome = buildCodexAppServerPromptTimeoutOutcome({
    result,
    turnCompletionIdleTimedOut: effectiveTurnCompletionIdleTimedOut,
    turnWatchTimeoutKind: state.turnWatchTimeoutKind,
  });
  const failureDiagnostics =
    codexAppServerFailureKind === "client_closed_before_turn_completed" &&
    state.clientClosedDiagnostic
      ? { transportError: state.clientClosedDiagnostic }
      : codexAppServerFailureKind === "turn_completion_idle_timeout" &&
          state.turnWatchTimeoutKind === "completion"
        ? buildCodexAppServerTimeoutDiagnostics({
            idleMs: state.turnWatchTimeoutIdleMs,
            timeoutMs: state.turnWatchTimeoutMs,
            lastActivityReason: state.turnWatchTimeoutLastActivityReason,
            details: state.turnWatchTimeoutDetails,
          })
        : undefined;
  const codexAppServerFailure = codexAppServerFailureKind
    ? ({
        kind: codexAppServerFailureKind,
        ...(codexAppServerFailureKind === "turn_completion_idle_timeout" &&
        state.turnWatchTimeoutKind
          ? { turnWatchTimeoutKind: state.turnWatchTimeoutKind }
          : {}),
        transport: appServer.start.transport,
        threadId: resourceState.thread.threadId,
        turnId: activeTurnId,
        replaySafe: replayBlockedReason === undefined,
        ...(replayBlockedReason ? { replayBlockedReason } : {}),
        ...(failureDiagnostics ? { diagnostics: failureDiagnostics } : {}),
      } satisfies NonNullable<EmbeddedRunAttemptResult["codexAppServerFailure"]>)
    : undefined;
  const finalAborted = isFinalAborted();
  const completedTurnStatus = activeProjector.getCompletedTurnStatus();
  const locallyCompletedTurn =
    state.completed &&
    (state.localCompletionRequested || !state.terminalTurnNotificationQueued) &&
    !state.timedOut &&
    clientClosedPromptErrorForFinal === undefined;
  const turnSucceeded =
    !finalAborted &&
    !effectiveTimedOut &&
    (finalPromptError === null || finalPromptError === undefined) &&
    (completedTurnStatus === "completed" || recoveredTurnWatchTimeout || locallyCompletedTurn);
  const completedSourceReply = toolBridge.telemetry.messagingToolSentTargets.some(
    (target) => target.sourceReplyFinal === true,
  );
  if (completedSourceReply) {
    // Harness classification only sees assistant/reasoning/plan projections.
    // A reply delivered entirely through the source message tool is visible
    // output, so an empty/reasoning-only classification is stale at this point.
    result.agentHarnessResultClassification = undefined;
  }
  const attemptSucceeded = turnSucceeded && result.agentHarnessResultClassification === undefined;
  terminalState.turnSucceeded = turnSucceeded;
  terminalState.sharedAbortAllowedAfterTerminalOutcome = shouldKeepCodexSharedAbortOpen({
    trigger: params.trigger,
    result,
    attemptSucceeded,
    explicitCancellationObserved: terminalState.explicitCancellationObserved,
  });
  // Every terminal observer must see the same immutable outcome.
  freezeRunTerminalOutcome();
  const modelCallFailureKind =
    classifyCodexModelCallFailureKind({
      error: finalPromptError,
      timedOut: effectiveTimedOut,
      turnCompletionIdleTimedOut: effectiveTurnCompletionIdleTimedOut,
      runAborted: finalAborted,
      abortReason: terminalState.explicitCancellationReason ?? runAbortController.signal.reason,
      clientClosedAbort: state.clientClosedAbort,
      formatError: formatErrorMessage,
    }) ?? (finalAborted ? "aborted" : undefined);
  if (modelCallFailureKind) {
    codexModelCallDiagnostics.emitError(
      finalPromptError ?? "codex app-server attempt interrupted",
      {
        failureKind: modelCallFailureKind,
      },
    );
  } else if (finalPromptError) {
    codexModelCallDiagnostics.emitError(finalPromptError);
  } else {
    codexModelCallDiagnostics.emitCompleted(result);
  }
  const mirrorOutcome = await codexTranscriptMirrorRuntime.mirrorBestEffort({
    params,
    agentId: sessionAgentId,
    notifyUserMessagePersisted,
    result,
    sessionKey: contextSessionKey,
    cwd: effectiveCwd,
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
  });
  const { assistantTranscriptOwned, assistantTranscriptIdempotencyKey, terminalAnchor } =
    mirrorOutcome;
  const shouldCaptureSettledTurnFinalizationContext =
    result.assistantTexts.every((text) => !text.trim()) &&
    result.messagesSnapshot.some((message) => message.role === "toolResult") &&
    (!finalPromptError || activeProjector.settledTurnFailureFinalizationAllowed);
  const settledTurnFinalizationContext = shouldCaptureSettledTurnFinalizationContext
    ? ((await captureCodexSettledTurnFinalizationContext({
        ...activeTranscriptTarget,
        mirroredMessages: mirrorOutcome.mirroredMessages,
        settledMessages: result.messagesSnapshot,
        turnId: activeTurnId,
      })) ?? Object.freeze({ source: "unavailable" as const }))
    : undefined;
  if (settledTurnFinalizationContext?.source === "unavailable") {
    // Unavailable evidence forbids native inference, but must not revoke this
    // eligible turn's path to the existing host-owned fallback.
    embeddedAgentLog.warn("codex settled-turn finalization context is unavailable", {
      threadId: resourceState.thread.threadId,
      turnId: activeTurnId,
    });
  }
  runAgentHarnessLlmOutputHook({
    event: {
      runId: params.runId,
      sessionId: params.sessionId,
      provider: usesSupervisionConnection
        ? (resourceState.thread.modelProvider ?? effectiveRuntimeProviderId)
        : params.provider,
      model: usesSupervisionConnection
        ? (resourceState.thread.model ?? effectiveRuntimeModelId)
        : params.modelId,
      ...hookContextWindowFields,
      resolvedRef: usesSupervisionConnection
        ? `${resourceState.thread.modelProvider ?? effectiveRuntimeProviderId}/${resourceState.thread.model ?? effectiveRuntimeModelId}`
        : (params.runtimePlan?.observability.resolvedRef ?? `${params.provider}/${params.modelId}`),
      ...(!usesSupervisionConnection && params.runtimePlan?.observability.harnessId
        ? { harnessId: params.runtimePlan.observability.harnessId }
        : {}),
      assistantTexts: result.assistantTexts,
      ...(result.lastAssistant ? { lastAssistant: result.lastAssistant } : {}),
      ...(result.attemptUsage ? { usage: result.attemptUsage } : {}),
    },
    ctx: hookContext,
    hookRunner,
  });
  await runCodexAgentEndHook(params, {
    event: {
      messages: result.messagesSnapshot,
      success: !finalAborted && !finalPromptError,
      ...(finalPromptError ? { error: formatErrorMessage(finalPromptError) } : {}),
      durationMs: Date.now() - attemptStartedAt,
    },
    ctx: {
      ...hookContext,
      modelProviderId: resourceState.thread.modelProvider ?? effectiveRuntimeProviderId,
      modelId: resourceState.thread.model ?? effectiveRuntimeModelId,
      authProfileId: resourceState.thread.authProfileId ?? startupAuthProfileId,
      modelIterations: result.modelIterations ?? 0,
      skillWorkshopAvailable: flattenCodexDynamicToolFunctions(
        attemptTools.toolBridge.availableSpecs,
      ).some((tool) => tool.name === "skill_workshop"),
      compacted: (result.compactionCount ?? 0) > 0,
      senderId: params.senderId ?? undefined,
      foregroundPromptContext: buildEmbeddedForegroundPromptContext(
        { ...params, agentId: sessionAgentId },
        agentDir,
      ),
    },
    hookRunner,
  });
  state.shouldDelayNativeHookRelayUnregister =
    completedTurnStatus === "completed" &&
    !effectiveTimedOut &&
    !runAbortController.signal.aborted &&
    !finalAborted &&
    !finalPromptError;
  if (state.shouldDelayNativeHookRelayUnregister) {
    try {
      await markCodexAppServerBindingCoveredThroughTurn({
        bindingStore,
        identity: bindingIdentity,
        threadId: resourceState.thread.threadId,
        // Only turns whose prompt WAS a no-engine continuity projection may
        // calibrate: a dense direct or active-engine prompt must never persist a
        // sample that later shrinks continuity history it did not measure.
        // Normalized usage splits total input into uncached + cacheRead + cacheWrite;
        // the density sample needs the full input cost, or the derived ratio loosens
        // the continuity cap in the unsafe direction.
        continuityCalibration: context.promptState.noEngineContinuityProjectionApplied
          ? buildCodexContinuityCalibration({
              promptChars: prompt.turnState.codexTurnPromptText.length,
              inputTokens:
                (result.attemptUsage?.input ?? 0) +
                (result.attemptUsage?.cacheRead ?? 0) +
                (result.attemptUsage?.cacheWrite ?? 0),
            })
          : undefined,
      });
    } catch (error) {
      if (resourceState.thread.connectionScope === "supervision") {
        throw error;
      }
      const cleared = await bindingStore.mutate(bindingIdentity, {
        kind: "clear",
        threadId: resourceState.thread.threadId,
      });
      if (!cleared) {
        throw error;
      }
      embeddedAgentLog.warn(
        "codex app-server binding coverage update failed after completed turn; cleared stale binding",
        { threadId: resourceState.thread.threadId, turnId: activeTurnId, error },
      );
    }
  }
  recordCodexTrajectoryCompletion(trajectoryRecorder, {
    attempt: params,
    result,
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
    timedOut: effectiveTimedOut,
    yieldDetected: toolState.yieldDetected,
  });
  trajectoryRecorder?.recordEvent("session.ended", {
    status: finalPromptError
      ? "error"
      : finalAborted || effectiveTimedOut
        ? "interrupted"
        : "success",
    threadId: resourceState.thread.threadId,
    turnId: activeTurnId,
    timedOut: effectiveTimedOut,
    yieldDetected: toolState.yieldDetected,
    promptError: normalizeCodexTrajectoryError(finalPromptError),
  });
  markTrajectoryEndRecorded();
  const terminalAssistantText = collectTerminalAssistantText(result);
  if (
    terminalAssistantText &&
    (!streamState.eventEmitted || streamState.needsTerminalSnapshot) &&
    !finalAborted &&
    !finalPromptError
  ) {
    void emitCodexAppServerEvent(params, {
      stream: "assistant",
      data: { text: terminalAssistantText },
    });
  }
  emitLifecycleTerminal(
    finalPromptError
      ? {
          phase: "error",
          error: formatErrorMessage(finalPromptError),
          ...buildLifecycleTerminalMeta({ aborted: finalAborted, timedOut: effectiveTimedOut }),
        }
      : {
          phase: "end",
          ...buildLifecycleTerminalMeta({
            aborted: finalAborted,
            timedOut: effectiveTimedOut,
            yielded: toolState.yieldDetected,
          }),
        },
  );
  // Preserve the exact result identity carrying host-issued TTS delivery provenance.
  const finalizedResult: EmbeddedRunAttemptResult = Object.assign(result, {
    ...(toolState.yieldAcknowledgment
      ? { yieldAcknowledgment: toolState.yieldAcknowledgment }
      : {}),
    terminal: attemptTerminal.normalize({
      timedOut: effectiveTimedOut,
      aborted: finalAborted,
      promptError: finalPromptError,
      promptErrorSource: finalPromptErrorSource,
    }),
    ...(codexAppServerFailure ? { codexAppServerFailure } : {}),
    ...(promptTimeoutOutcome ? { promptTimeoutOutcome } : {}),
    ...(assistantTranscriptOwned ? { assistantTranscriptOwned: true } : {}),
    ...(assistantTranscriptIdempotencyKey ? { assistantTranscriptIdempotencyKey } : {}),
    ...(terminalAnchor ? { contextEngineTerminalAnchor: terminalAnchor } : {}),
    ...(settledTurnFinalizationContext ? { settledTurnFinalizationContext } : {}),
    ...(resourceState.runtimeArtifact ? { runtimeArtifact: resourceState.runtimeArtifact } : {}),
    ...(resourceState.runtimeContinuationStarted ? { runtimeContinuationStarted: true } : {}),
    ...(!finalAborted && !effectiveTimedOut && !finalPromptError && preparedAuthBinding
      ? { authBindingFingerprint: preparedAuthBinding.fingerprint }
      : {}),
    systemPromptReport,
  });
  if (turnSucceeded && toolState.yieldDetected && !runAbortController.signal.aborted) {
    resourceState.nativeHookRelay?.authorizeRetentionAfterSuccessfulYield();
  }
  return finalizedResult;
}

/** Reads the real native-hook relay identity encoded into a Codex thread request. */
export function extractRelayIdFromThreadRequest(params: unknown): string {
  const command = extractNativeHookRelayCommandFromThreadRequest(params);
  const match = command.match(/--relay-id ([^ ]+)/);
  if (!match?.[1]) {
    throw new Error(`relay id missing from command: ${command}`);
  }
  return match[1];
}

export function extractGenerationFromThreadRequest(params: unknown): string {
  const command = extractNativeHookRelayCommandFromThreadRequest(params);
  const match = command.match(/--generation ([^ ]+)/);
  if (!match?.[1]) {
    throw new Error(`relay generation missing from command: ${command}`);
  }
  return match[1];
}

function extractNativeHookRelayCommandFromThreadRequest(params: unknown): string {
  const config = (params as { config?: Record<string, unknown> }).config;
  for (const key of [
    "hooks.PreToolUse",
    "hooks.PostToolUse",
    "hooks.PermissionRequest",
    "hooks.Stop",
  ]) {
    const entries = config?.[key];
    if (!Array.isArray(entries)) {
      continue;
    }
    for (const entry of entries as Array<{ hooks?: Array<{ command?: string }> }>) {
      const command = entry.hooks?.find((hook) => typeof hook.command === "string")?.command;
      if (command) {
        return command;
      }
    }
  }
  throw new Error("native hook relay command missing from thread request");
}

import { describe, expect, it, vi } from "vitest";
import { interruptCodexTurnAndWaitBestEffort } from "./attempt-client-cleanup.js";
import { createCodexAttemptLifecycleController } from "./run-attempt-lifecycle-controller.js";
import { buildCodexLifecycleTerminalMeta } from "./run-attempt-lifecycle-terminal.js";

function createTerminalReleaseHarness() {
  const order: string[] = [];
  const notificationHandlers = new Set<(notification: unknown) => void>();
  const cancel = vi.fn(() => order.push("cancel"));
  const request = vi.fn(async (method: string) => {
    order.push(method);
    return {};
  });
  const resolveCompletion = vi.fn();
  const state = {
    completed: false,
    activeAppServerTurnRequests: 0,
    currentTurnHadNonTerminalDynamicToolResult: false,
    pendingTerminalDynamicToolRelease: undefined,
    terminalDynamicToolReleaseCheckScheduled: false,
    resolveCompletion,
  };
  const client = {
    request,
    addNotificationHandler: (handler: (notification: unknown) => void) => {
      notificationHandlers.add(handler);
      return () => notificationHandlers.delete(handler);
    },
    addRequestHandler: () => () => undefined,
    addCloseHandler: () => () => undefined,
  };
  const controller = createCodexAttemptLifecycleController(
    {
      prompt: {
        context: {
          runtime: {
            connection: {
              params: {},
              attemptStartedAt: 0,
              runAbortController: new AbortController(),
              fastModeAutoProgressState: {},
            },
          },
        },
      },
      state: { client },
    } as never,
    {
      state,
      activeTurnItemIds: new Set(),
      pendingOpenClawDynamicToolCompletionIds: new Set(),
      steeringQueueRef: { current: { cancel } },
      interruptTurn: (turnId: string) =>
        interruptCodexTurnAndWaitBestEffort(client as never, {
          threadId: "thread-1",
          turnId,
        }),
      completeTurn: () => {
        state.completed = true;
        resolveCompletion();
      },
    } as never,
  );
  const completeTurn = () => {
    for (const handler of notificationHandlers) {
      handler({
        method: "turn/completed",
        params: {
          threadId: "thread-1",
          turn: { id: "turn-1", status: "interrupted" },
        },
      });
    }
  };
  return { cancel, completeTurn, controller, order, request, resolveCompletion, state };
}

function terminalYieldResult(success: boolean) {
  return {
    call: {
      threadId: "thread-1",
      turnId: "turn-1",
      callId: "call-yield",
      tool: "sessions_yield",
      arguments: {},
    },
    response: { success, terminate: true, contentItems: [] },
    durationMs: 1,
  };
}

describe("buildCodexLifecycleTerminalMeta", () => {
  it("marks sessions_yield as a paused parent continuation", () => {
    expect(
      buildCodexLifecycleTerminalMeta({
        aborted: false,
        timedOut: false,
        yielded: true,
      }),
    ).toEqual({
      yielded: true,
      livenessState: "paused",
      stopReason: "end_turn",
    });
  });

  it("keeps ordinary successful turns terminal", () => {
    expect(
      buildCodexLifecycleTerminalMeta({
        aborted: false,
        timedOut: false,
        yielded: false,
      }),
    ).toBeUndefined();
  });

  it("keeps cancellation stronger than a stale yield signal", () => {
    expect(
      buildCodexLifecycleTerminalMeta({
        aborted: true,
        timedOut: false,
        yielded: true,
      }),
    ).toEqual({
      aborted: true,
      status: "cancelled",
      stopReason: "stop",
    });
  });
});

describe("Codex terminal dynamic-tool release", () => {
  it("completes a successful yield before native interrupt completion", async () => {
    const harness = createTerminalReleaseHarness();

    harness.controller.scheduleTurnReleaseAfterTerminalDynamicTool(terminalYieldResult(true));
    await new Promise<void>((resolve) => {
      setImmediate(resolve);
    });

    expect(harness.cancel).toHaveBeenCalled();
    expect(harness.request).toHaveBeenCalledWith(
      "turn/interrupt",
      { threadId: "thread-1", turnId: "turn-1" },
      { timeoutMs: 5_000 },
    );
    expect(harness.order.indexOf("cancel")).toBeLessThan(harness.order.indexOf("turn/interrupt"));
    expect(harness.state.completed).toBe(true);
    expect(harness.resolveCompletion).toHaveBeenCalledOnce();

    harness.completeTurn();
    harness.controller.scheduleTurnReleaseAfterTerminalDynamicTool(terminalYieldResult(true));
    await new Promise<void>((resolve) => {
      setImmediate(resolve);
    });

    expect(harness.request).toHaveBeenCalledOnce();
    expect(harness.resolveCompletion).toHaveBeenCalledOnce();
  });

  it("keeps steering open when the yield result fails", async () => {
    const harness = createTerminalReleaseHarness();

    harness.controller.scheduleTurnReleaseAfterTerminalDynamicTool(terminalYieldResult(false));
    await new Promise<void>((resolve) => {
      setImmediate(resolve);
    });

    expect(harness.cancel).not.toHaveBeenCalled();
    expect(harness.request).not.toHaveBeenCalled();
    expect(harness.state.completed).toBe(false);
    expect(harness.resolveCompletion).not.toHaveBeenCalled();
  });
});

import {
  embeddedAgentLog,
  FAST_MODE_AUTO_PROGRESS_KIND,
  formatErrorMessage,
  formatFastModeAutoProgressText,
  resolveAgentRunAbortLifecycleFields,
  resolveFastModeForElapsed,
  type EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { reportCodexExecutionNotification } from "./attempt-notification-state.js";
import {
  resolveTerminalDynamicToolBatchAction,
  shouldReleaseTurnAfterTerminalDynamicTool,
} from "./dynamic-tool-execution.js";
import type {
  CodexDynamicToolCallParams,
  CodexDynamicToolCallResponse,
  CodexServerNotification,
} from "./protocol.js";
import { buildCodexLifecycleTerminalMeta } from "./run-attempt-lifecycle-terminal.js";
import { emitCodexAppServerEvent } from "./run-attempt-lifecycle.js";
import type { CodexAttemptResources } from "./run-attempt-resources.js";
import type { CodexAttemptTurnState } from "./run-attempt-turn-state.js";

export function createCodexAttemptLifecycleController(
  resources: CodexAttemptResources,
  turnRuntime: CodexAttemptTurnState,
) {
  const { prompt, trajectoryRecorder } = resources;
  const { connection } = prompt.context.runtime;
  const {
    params,
    attemptStartedAt,
    runAbortController,
    fastModeAutoStartedAtMs,
    fastModeAutoProgressState,
  } = connection;
  const { state, activeTurnItemIds, pendingOpenClawDynamicToolCompletionIds } = turnRuntime;
  const releaseTurnAfterTerminalDynamicTool = (value: {
    call: CodexDynamicToolCallParams;
    response: CodexDynamicToolCallResponse;
    durationMs: number;
  }) => {
    if (
      !shouldReleaseTurnAfterTerminalDynamicTool({
        completed: state.completed,
        aborted: runAbortController.signal.aborted,
        responseSuccess: value.response.success,
        currentTurnHadNonTerminalDynamicToolResult:
          state.currentTurnHadNonTerminalDynamicToolResult,
        activeAppServerTurnRequests: state.activeAppServerTurnRequests,
        activeTurnItemIdsCount: activeTurnItemIds.size,
        pendingOpenClawDynamicToolCompletionIdsCount: pendingOpenClawDynamicToolCompletionIds.size,
      })
    ) {
      return;
    }
    state.pendingTerminalDynamicToolRelease = undefined;
    trajectoryRecorder?.recordEvent("turn.dynamic_tool_terminal_release", {
      threadId: value.call.threadId,
      turnId: value.call.turnId,
      toolCallId: value.call.callId,
      name: value.call.tool,
      durationMs: value.durationMs,
    });
    embeddedAgentLog.info("codex app-server turn released after terminal dynamic tool result", {
      threadId: value.call.threadId,
      turnId: value.call.turnId,
      toolCallId: value.call.callId,
      tool: value.call.tool,
      durationMs: value.durationMs,
    });
    // Interrupt drops accepted pending input. Reject unconsumed steering first so
    // completion delivery can use its fallback path instead of reporting success.
    turnRuntime.steeringQueueRef.current?.cancel();
    void turnRuntime.interruptTurn(value.call.turnId, { locallyCompleted: true });
    turnRuntime.completeTurn();
  };
  const scheduleTerminalDynamicToolReleaseCheck = () => {
    if (
      state.terminalDynamicToolReleaseCheckScheduled ||
      (!state.pendingTerminalDynamicToolRelease &&
        !state.currentTurnHadNonTerminalDynamicToolResult)
    ) {
      return;
    }
    // The JSON-RPC response must flush before the terminal tool interrupts its turn.
    state.terminalDynamicToolReleaseCheckScheduled = true;
    const immediate = setImmediate(() => {
      state.terminalDynamicToolReleaseCheckScheduled = false;
      if (
        state.pendingTerminalDynamicToolRelease?.response.success === true &&
        !state.currentTurnHadNonTerminalDynamicToolResult &&
        state.activeAppServerTurnRequests === 0 &&
        pendingOpenClawDynamicToolCompletionIds.size === 0
      ) {
        // Tool response flush plus sibling classification commits terminal release.
        // Fence steering now; active Codex items may delay the actual interrupt.
        turnRuntime.steeringQueueRef.current?.cancel();
      }
      const action = resolveTerminalDynamicToolBatchAction({
        activeAppServerTurnRequests: state.activeAppServerTurnRequests,
        activeTurnItemIdsCount: activeTurnItemIds.size,
        pendingOpenClawDynamicToolCompletionIdsCount: pendingOpenClawDynamicToolCompletionIds.size,
        currentTurnHadNonTerminalDynamicToolResult:
          state.currentTurnHadNonTerminalDynamicToolResult,
        hasPendingTerminalDynamicToolRelease: state.pendingTerminalDynamicToolRelease !== undefined,
      });
      if (action === "release-pending-terminal" && state.pendingTerminalDynamicToolRelease) {
        releaseTurnAfterTerminalDynamicTool(state.pendingTerminalDynamicToolRelease);
      } else if (action === "clear-nonterminal-batch") {
        state.pendingTerminalDynamicToolRelease = undefined;
        state.currentTurnHadNonTerminalDynamicToolResult = false;
      }
    });
    immediate.unref?.();
  };
  const scheduleTurnReleaseAfterTerminalDynamicTool = (value: {
    call: CodexDynamicToolCallParams;
    response: CodexDynamicToolCallResponse;
    durationMs: number;
  }) => {
    state.pendingTerminalDynamicToolRelease = value;
    scheduleTerminalDynamicToolReleaseCheck();
  };
  const emitLifecycleStart = () => {
    void emitCodexAppServerEvent(params, {
      stream: "lifecycle",
      data: { phase: "start", startedAt: attemptStartedAt },
    });
    state.lifecycleStarted = true;
  };
  const emitLifecycleTerminal = (data: Record<string, unknown> & { phase: "end" | "error" }) => {
    if (
      !state.lifecycleStarted ||
      state.lifecycleTerminalEmitted ||
      state.permissionChangeRestart
    ) {
      return;
    }
    void emitCodexAppServerEvent(params, {
      stream: "lifecycle",
      data: {
        startedAt: attemptStartedAt,
        endedAt: Date.now(),
        ...data,
        ...(params.deferTerminalLifecycle ? { phase: "finishing" } : {}),
      },
    });
    state.lifecycleTerminalEmitted = true;
  };
  const buildLifecycleTerminalMeta = (input: {
    aborted: boolean;
    timedOut: boolean;
    yielded?: boolean;
  }) => {
    const abortFields = input.aborted
      ? resolveAgentRunAbortLifecycleFields(runAbortController.signal)
      : undefined;
    return buildCodexLifecycleTerminalMeta({
      ...input,
      abortStopReason: abortFields?.stopReason,
    });
  };
  const executionPhaseKeys = new Set<string>();
  const emitExecutionPhaseOnce = (
    key: string,
    info: Parameters<NonNullable<EmbeddedRunAttemptParams["onExecutionPhase"]>>[0],
  ) => {
    if (executionPhaseKeys.has(key)) {
      return;
    }
    executionPhaseKeys.add(key);
    params.onExecutionPhase?.({
      provider: params.provider,
      model: params.modelId,
      backend: "codex-app-server",
      ...info,
    });
  };
  const reportExecutionNotification = (notification: CodexServerNotification) => {
    reportCodexExecutionNotification({ notification, emitExecutionPhaseOnce });
  };
  const emitFastModeAutoProgress = async (payload: {
    enabled: boolean;
    elapsedSeconds: number;
    fastAutoOnSeconds?: number;
  }) => {
    const summary = formatFastModeAutoProgressText(payload);
    await emitCodexAppServerEvent(params, {
      stream: "item",
      data: { kind: "status", title: "Fast", phase: "update", summary },
    });
    try {
      await params.onToolResult?.({
        text: summary,
        channelData: { openclawProgressKind: FAST_MODE_AUTO_PROGRESS_KIND },
      });
    } catch (error) {
      embeddedAgentLog.debug("codex app-server fast mode auto progress delivery failed", { error });
    }
  };
  const maybeAnnounceFastModeAutoOff = async () => {
    if (
      params.fastModeAuto !== true ||
      fastModeAutoStartedAtMs === undefined ||
      fastModeAutoProgressState.offAnnounced
    ) {
      return;
    }
    const next = resolveFastModeForElapsed({
      mode: "auto",
      startedAtMs: fastModeAutoStartedAtMs,
      fastAutoOnSeconds: params.fastModeAutoOnSeconds,
    });
    if (next.enabled) {
      return;
    }
    fastModeAutoProgressState.offAnnounced = true;
    await emitFastModeAutoProgress(next);
  };
  const maybeEmitFastModeAutoReset = async () => {
    if (
      params.fastModeAuto !== true ||
      !fastModeAutoProgressState.offAnnounced ||
      fastModeAutoProgressState.resetAnnounced
    ) {
      return;
    }
    fastModeAutoProgressState.resetAnnounced = true;
    await emitFastModeAutoProgress({
      enabled: true,
      elapsedSeconds: 0,
      fastAutoOnSeconds: params.fastModeAutoOnSeconds,
    });
  };
  const maybeEmitFastModeAutoResetBestEffort = async () => {
    try {
      await maybeEmitFastModeAutoReset();
    } catch (error) {
      embeddedAgentLog.warn(
        `codex app-server fast mode auto reset progress failed: ${formatErrorMessage(error)}`,
      );
    }
  };
  return {
    scheduleTerminalDynamicToolReleaseCheck,
    scheduleTurnReleaseAfterTerminalDynamicTool,
    emitLifecycleStart,
    emitLifecycleTerminal,
    buildLifecycleTerminalMeta,
    emitExecutionPhaseOnce,
    reportExecutionNotification,
    maybeAnnounceFastModeAutoOff,
    maybeEmitFastModeAutoResetBestEffort,
  };
}

export type CodexAttemptLifecycleController = ReturnType<
  typeof createCodexAttemptLifecycleController
>;

export function buildCodexLifecycleTerminalMeta(input: {
  aborted: boolean;
  timedOut: boolean;
  yielded?: boolean;
  abortStopReason?: string;
}) {
  if (input.timedOut || input.abortStopReason === "timeout") {
    return {
      aborted: true,
      status: "timed_out",
      stopReason: "timeout",
      timeoutPhase: "provider",
      providerStarted: true,
    } as const;
  }
  if (input.yielded && !input.aborted) {
    return {
      yielded: true,
      livenessState: "paused",
      stopReason: "end_turn",
    } as const;
  }
  return input.aborted
    ? ({ aborted: true, status: "cancelled", stopReason: "stop" } as const)
    : undefined;
}

import fs from "node:fs/promises";
import path from "node:path";
import {
  awaitAgentEndSideEffects,
  embeddedAgentLog,
  emitAgentEvent as emitGlobalAgentEvent,
  runAgentEndSideEffects,
  type EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { attemptTerminal, type EmbeddedRunAttemptResult } from "./attempt-terminal.js";
import type { CodexAppServerRuntimeOptions } from "./config.js";
import { codexWorkspaceDirCache } from "./workspace-dir-cache.js";

const CODEX_APP_SERVER_PROJECTED_CHARS_PER_TOKEN = 4;

export function shouldKeepCodexSharedAbortOpen(params: {
  trigger: EmbeddedRunAttemptParams["trigger"];
  result: EmbeddedRunAttemptResult;
  attemptSucceeded: boolean;
  explicitCancellationObserved: boolean;
}): boolean {
  const terminal = attemptTerminal.project(params.result.terminal);
  if (params.explicitCancellationObserved || terminal.aborted || terminal.externalAbort) {
    return false;
  }
  // Memory attempts are preparatory. Failed attempts can still enter runner
  // retries or model fallback. The reply orchestrator owns the shared terminal
  // freeze after those paths settle.
  return params.trigger === "memory" || !params.attemptSucceeded;
}

export function withCodexAppServerFastModeServiceTier(
  appServer: CodexAppServerRuntimeOptions,
  params: EmbeddedRunAttemptParams,
): CodexAppServerRuntimeOptions {
  const fastMode = typeof params.fastMode === "function" ? params.fastMode() : params.fastMode;
  const serviceTier =
    fastMode === undefined ? appServer.serviceTier : fastMode ? "priority" : undefined;
  if (serviceTier === appServer.serviceTier) {
    return appServer;
  }
  if (serviceTier) {
    return { ...appServer, serviceTier };
  }
  return { ...appServer, serviceTier: null };
}

export function estimateCodexAppServerProjectedTurnTokens(params: {
  prompt: string;
  developerInstructions?: string;
}): number {
  const inputChars = params.prompt.length + (params.developerInstructions?.length ?? 0);
  return Math.max(1, Math.ceil(inputChars / CODEX_APP_SERVER_PROJECTED_CHARS_PER_TOKEN));
}

export async function ensureCodexWorkspaceDirOnce(workspaceDir: string): Promise<void> {
  const normalized = path.resolve(workspaceDir);
  // Workspace teardown clears this cache before cleanup; never stat a stable path per turn.
  if (codexWorkspaceDirCache.has(normalized)) {
    return;
  }
  await fs.mkdir(normalized, { recursive: true });
  codexWorkspaceDirCache.add(normalized);
}

export async function emitCodexAppServerEvent(
  params: EmbeddedRunAttemptParams,
  event: Parameters<NonNullable<EmbeddedRunAttemptParams["onAgentEvent"]>>[0],
): Promise<void> {
  try {
    emitGlobalAgentEvent({
      runId: params.runId,
      stream: event.stream,
      data: event.data,
      ...(params.sessionKey ? { sessionKey: params.sessionKey } : {}),
    });
  } catch (error) {
    embeddedAgentLog.debug("codex app-server global agent event emit failed", { error });
  }
  try {
    await params.onAgentEvent?.(event);
  } catch (error) {
    // Event consumers are observational; they must not abort or strand the
    // canonical app-server turn lifecycle.
    embeddedAgentLog.debug("codex app-server agent event handler threw", { error });
  }
}

type CodexAgentEndHookParams = Parameters<typeof runAgentEndSideEffects>[0];

export async function runCodexAgentEndHook(
  params: EmbeddedRunAttemptParams,
  hookParams: CodexAgentEndHookParams,
): Promise<void> {
  const sideEffectParams = {
    ...hookParams,
    ctx: { ...hookParams.ctx, config: params.config },
  };
  if (!params.messageChannel && !params.messageProvider) {
    await awaitAgentEndSideEffects(sideEffectParams);
    return;
  }
  runAgentEndSideEffects(sideEffectParams);
}

import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import {
  applyCodexTurnNotificationState,
  isTerminalCodexTurnNotificationForTurn,
} from "./attempt-notification-state.js";
import {
  describeNotificationActivity,
  isAssistantCompletionReleaseNotification,
  isRawFunctionToolOutputCompletionNotification,
  readCodexNotificationItem,
  readRawResponseToolCallId,
} from "./attempt-notifications.js";
import { readCodexTurnCompletedNotification } from "./protocol-validators.js";
import type { CodexServerNotification } from "./protocol.js";
import type { CodexAttemptLifecycleController } from "./run-attempt-lifecycle-controller.js";
import type { CodexAttemptResources } from "./run-attempt-resources.js";
import { readCodexFinalizationHookNotification } from "./run-attempt-state.js";
import type { CodexAttemptTurnState } from "./run-attempt-turn-state.js";
import { CODEX_APP_SERVER_NATIVE_TURN_WAIT_TIMEOUT_MS } from "./turn-router.js";
import type { CodexThreadRouteScope } from "./turn-router.js";

export function createCodexAttemptNotificationController(
  resources: CodexAttemptResources,
  turnRuntime: CodexAttemptTurnState,
  lifecycle: CodexAttemptLifecycleController,
) {
  const { prompt, state: resourceState, projectorRef, registerNativeSubagentMonitor } = resources;
  const { context, turnState } = prompt;
  const { attemptTools, runtime } = context;
  const { connection } = runtime;
  const { appServer, runAbortController } = connection;
  const { allocateCodexToolOutcomeOrdinal } = attemptTools;
  const {
    state,
    turnIdRef,
    userInputBridgeRef,
    steeringQueueRef,
    turnWatches,
    activeTurnItemIds,
    activeCompletionBlockerItemIds,
    activeFinalizationHookRunIds,
    finalizationHookBatchStatuses,
    pendingOpenClawDynamicToolCompletionIds,
    postToolRawAssistantCompletionIdleTimeoutMs,
    completeTurn,
  } = turnRuntime;
  const {
    scheduleTerminalDynamicToolReleaseCheck,
    reportExecutionNotification,
    maybeAnnounceFastModeAutoOff,
  } = lifecycle;
  const isTerminalTurnNotificationForTurn = (
    notification: CodexServerNotification,
    notificationTurnId: string,
  ) =>
    isTerminalCodexTurnNotificationForTurn({
      notification,
      threadId: resourceState.thread.threadId,
      turnId: notificationTurnId,
    });
  const handleNotification = async (notification: CodexServerNotification) => {
    const projector = projectorRef.current;
    const turnId = turnIdRef.current;
    const steeringQueue = steeringQueueRef.current;
    userInputBridgeRef.current?.handleNotification(notification);
    if (!projector || !turnId) {
      if (notification.method === "error") {
        state.latestStartupErrorNotification = notification;
      }
      return;
    }
    if (
      (state.timedOut || state.localCompletionRequested) &&
      notification.method === "turn/completed" &&
      readCodexTurnCompletedNotification(notification.params)?.turn.status === "interrupted"
    ) {
      // Our cleanup interrupt proves the native turn ended; it must not replace
      // an already-owned final answer, yield result, or recorded response usage.
      completeTurn();
      return;
    }
    const notificationState = applyCodexTurnNotificationState({
      notification,
      threadId: resourceState.thread.threadId,
      turnId,
      currentPromptTexts: [turnState.codexTurnPromptText],
      turnWatches,
      activeTurnItemIds,
      activeCompletionBlockerItemIds,
      activeAppServerTurnRequests: state.activeAppServerTurnRequests,
      pendingOpenClawDynamicToolCompletionIds,
      turnCrossedToolHandoff: state.turnCrossedToolHandoff,
      postToolRawAssistantCompletionIdleTimeoutMs,
      onScheduleTerminalDynamicToolReleaseCheck: scheduleTerminalDynamicToolReleaseCheck,
      onReportExecutionNotification: reportExecutionNotification,
    });
    state.turnCrossedToolHandoff = notificationState.turnCrossedToolHandoff;
    if (notificationState.isCurrentTurnNotification && notification.method === "item/completed") {
      const item = readCodexNotificationItem(notification.params);
      if (item?.type === "userMessage" && typeof item.clientId === "string") {
        await steeringQueue?.confirmConsumed(item.clientId);
      }
    }
    if (notificationState.isTurnAbortMarker) {
      state.sawCodexInterruptMarker = true;
    }
    const hookNotification = readCodexFinalizationHookNotification(
      notification,
      resourceState.thread.threadId,
      turnId,
    );
    if (hookNotification?.phase === "started") {
      if (activeFinalizationHookRunIds.size === 0) {
        finalizationHookBatchStatuses.clear();
      }
      activeFinalizationHookRunIds.add(hookNotification.runId);
      turnWatches.disarmAssistantCompletionIdleWatch();
    }
    if (notificationState.isTurnTerminal) {
      state.terminalTurnNotificationQueued = true;
    }
    try {
      await projector.handleNotification(notification);
      const canRelease =
        isAssistantCompletionReleaseNotification(notification, state.turnCrossedToolHandoff) ||
        (notificationState.isCurrentTurnNotification &&
          state.turnCrossedToolHandoff &&
          notification.method === "rawResponseItem/completed" &&
          projector.canReleaseLatestTerminalAssistantAfterToolHandoff());
      if (notificationState.isCurrentTurnNotification && canRelease) {
        const itemId = projector.getLatestTerminalAssistantCandidate()?.itemId;
        if (
          state.rejectedFinalizationHookAssistant &&
          itemId &&
          itemId !== state.rejectedFinalizationHookAssistant.itemId
        ) {
          state.rejectedFinalizationHookAssistant = undefined;
        } else if (state.rejectedFinalizationHookAssistant) {
          turnWatches.disarmAssistantCompletionIdleWatch();
        } else if (
          activeFinalizationHookRunIds.size === 0 &&
          !state.terminalTurnNotificationQueued &&
          state.activeAppServerTurnRequests === 0 &&
          activeTurnItemIds.size === 0 &&
          activeCompletionBlockerItemIds.size === 0 &&
          pendingOpenClawDynamicToolCompletionIds.size === 0 &&
          projector.hasLatestTerminalAssistantCandidateText()
        ) {
          turnWatches.armAssistantCompletionIdleWatch(describeNotificationActivity(notification));
        }
      }
      if (
        notificationState.isCurrentTurnNotification &&
        activeTurnItemIds.size === 0 &&
        isRawFunctionToolOutputCompletionNotification(notification)
      ) {
        await maybeAnnounceFastModeAutoOff();
      }
    } catch (error) {
      embeddedAgentLog.debug("codex app-server projector notification threw", {
        method: notification.method,
        error,
      });
    } finally {
      if (hookNotification?.phase === "completed") {
        state.unsettledFinalizationHookCount = Math.max(
          0,
          state.unsettledFinalizationHookCount - 1,
        );
        activeFinalizationHookRunIds.delete(hookNotification.runId);
        finalizationHookBatchStatuses.set(hookNotification.runId, hookNotification.status);
        if (activeFinalizationHookRunIds.size === 0) {
          const statuses = new Set(finalizationHookBatchStatuses.values());
          if (statuses.has("blocked") && !statuses.has("stopped")) {
            const itemId = projector.getLatestTerminalAssistantCandidate()?.itemId;
            state.rejectedFinalizationHookAssistant = itemId ? { itemId } : {};
            turnWatches.disarmAssistantCompletionIdleWatch();
          } else {
            state.rejectedFinalizationHookAssistant = undefined;
          }
        }
        if (
          activeFinalizationHookRunIds.size === 0 &&
          state.rejectedFinalizationHookAssistant === undefined &&
          !state.terminalTurnNotificationQueued &&
          state.activeAppServerTurnRequests === 0 &&
          activeTurnItemIds.size === 0 &&
          activeCompletionBlockerItemIds.size === 0 &&
          pendingOpenClawDynamicToolCompletionIds.size === 0 &&
          projector.hasLatestTerminalAssistantCandidateText()
        ) {
          turnWatches.armAssistantCompletionIdleWatch({
            lastNotificationMethod: notification.method,
            hookRunId: hookNotification.runId,
            hookStatus: hookNotification.status,
          });
        }
      }
      if (notificationState.isTurnTerminal) {
        const completedTurn = readCodexTurnCompletedNotification(notification.params)?.turn;
        // App-server collapses abort reasons; interrupted plus this marker is the
        // only user-interrupt discriminator until Codex exposes abortReason.
        if (completedTurn?.status === "interrupted" && state.sawCodexInterruptMarker) {
          projector.markAborted();
        }
        completeTurn();
      }
    }
  };
  const waitForActiveNativeTurnCompletion = async () => {
    const route = resourceState.turnRoute;
    const activeNativeTurnId =
      resourceState.thread.lifecycle.activeTurnIds?.at(-1) ?? route?.observedNativeTurnId;
    if (!route || !activeNativeTurnId) {
      return false;
    }
    const watch = resourceState.turnRouter.watchNativeTurnCompletion({
      threadId: route.threadId,
      turnId: activeNativeTurnId,
      timeoutMs: Math.min(appServer.requestTimeoutMs, CODEX_APP_SERVER_NATIVE_TURN_WAIT_TIMEOUT_MS),
      signal: runAbortController.signal,
    });
    try {
      return await watch.completion;
    } finally {
      watch.cancel();
    }
  };
  const noteNotificationReceived = (
    notification: CodexServerNotification,
    scope: CodexThreadRouteScope,
    receivedAtMs: number,
  ) => {
    const projector = projectorRef.current;
    const turnId = turnIdRef.current;
    if (!projector || !turnId) {
      return;
    }
    if (isTerminalTurnNotificationForTurn(notification, turnId)) {
      state.terminalTurnNotificationQueued = true;
      steeringQueueRef.current?.sealAdmission();
    }
    if (scope.turnId === turnId) {
      const modelToolCallId = readRawResponseToolCallId(notification);
      if (modelToolCallId) {
        allocateCodexToolOutcomeOrdinal?.(modelToolCallId);
      }
      const nativeItem = readCodexNotificationItem(notification.params);
      if (nativeItem?.type === "webSearch") {
        projector.recordNativeToolOutcome(nativeItem);
      }
    }
    const hookNotification = readCodexFinalizationHookNotification(
      notification,
      resourceState.thread.threadId,
      turnId,
    );
    if (hookNotification?.phase === "started") {
      state.unsettledFinalizationHookCount += 1;
      turnWatches.disarmAssistantCompletionIdleWatch();
    }
    turnWatches.noteNotificationReceived(notification.method, { receivedAtMs });
  };
  const enqueueNotification = async (
    notification: CodexServerNotification,
    scope: CodexThreadRouteScope,
  ) => {
    embeddedAgentLog.trace("codex app-server raw notification received", {
      method: notification.method,
      ...scope,
    });
    await handleNotification(notification);
  };
  const drainNotificationQueue = async () => {
    await resourceState.turnRoute?.drain();
  };
  registerNativeSubagentMonitor(resourceState.thread.threadId);
  return {
    waitForActiveNativeTurnCompletion,
    noteNotificationReceived,
    enqueueNotification,
    drainNotificationQueue,
  };
}

