export function createCodexAttemptServerRequestController(
  resources: CodexAttemptResources,
  turnRuntime: CodexAttemptTurnState,
  lifecycle: CodexAttemptLifecycleController,
) {
  const { prompt, state: resourceState, projectorRef, trajectoryRecorder } = resources;
  const { context } = prompt;
  const { runtime, attemptTools } = context;
  const { connection } = runtime;
  const { params, computerUseConfig, runAbortController, appServer, sessionAgentId } = connection;
  const {
    compactionPlanState,
    toolBridge,
    toolOutcomeOrdinals,
    suppressedDynamicToolOutcomeOrdinals,
    allocateCodexToolOutcomeOrdinal,
  } = attemptTools;
  const {
    state,
    turnIdRef,
    userInputBridgeRef,
    openClawDynamicToolExecutions,
    pendingOpenClawDynamicToolCompletionIds,
    postToolRawAssistantCompletionIdleTimeoutMs,
    turnWatches,
  } = turnRuntime;
  const {
    emitExecutionPhaseOnce,
    scheduleTurnReleaseAfterTerminalDynamicTool,
    scheduleTerminalDynamicToolReleaseCheck,
  } = lifecycle;
  const handleServerRequest = async (
    request: CodexAppServerServerRequest,
    scope: CodexThreadRouteScope,
    requestSignal: AbortSignal = new AbortController().signal,
  ) => {
    const signal = AbortSignal.any([runAbortController.signal, requestSignal]);
    const turnId = turnIdRef.current;
    const projector = projectorRef.current;
    let armCompletionWatchOnResponse = false;
    let requestCountsAsTurnActivity = false;
    let requestKeepsAttemptWatchArmed = false;
    const markCurrentTurnRequestProgress = (options?: { hasIndependentTimeout?: boolean }) => {
      state.activeAppServerTurnRequests += 1;
      requestKeepsAttemptWatchArmed = options?.hasIndependentTimeout !== true;
      if (requestKeepsAttemptWatchArmed) {
        state.activeAppServerTurnRequestsWithoutTimeout += 1;
      }
      turnWatches.clearCompletionIdleTimer();
      turnWatches.disarmAssistantCompletionIdleWatch();
      requestCountsAsTurnActivity = true;
      turnWatches.touchActivity(`request:${request.method}:start`, { attemptProgress: true });
    };
    try {
      if (!turnId) {
        return undefined;
      }
      if (request.method === "mcpServer/elicitation/request") {
        if (!scope.turnId || scope.turnId === turnId) {
          armCompletionWatchOnResponse = true;
          markCurrentTurnRequestProgress();
        }
        const approvalResult = await routeCodexAppServerElicitationRequest({
          requestParams: request.params,
          paramsForRun: params,
          threadId: resourceState.thread.threadId,
          turnId,
          pluginAppPolicyContext: resourceState.thread.pluginAppPolicyContext,
          ...(computerUseConfig.enabled
            ? { computerUseMcpServerName: computerUseConfig.mcpServerName }
            : {}),
          signal,
        });
        if (approvalResult.kind === "handled") {
          return approvalResult.response;
        }
        return await userInputBridgeRef.current?.handleElicitationRequest({
          id: request.id,
          params: request.params,
        });
      }
      if (request.method === "item/tool/requestUserInput") {
        if (scope.turnId === turnId) {
          armCompletionWatchOnResponse = true;
          markCurrentTurnRequestProgress();
        }
        return await userInputBridgeRef.current?.handleRequest({
          id: request.id,
          params: request.params,
        });
      }
      if (request.method !== "item/tool/call") {
        if (isCodexAppServerApprovalRequest(request.method)) {
          if (scope.turnId === turnId) {
            armCompletionWatchOnResponse = true;
            markCurrentTurnRequestProgress();
          }
          return await handleCodexAppServerApprovalRequest({
            method: request.method,
            requestParams: request.params,
            paramsForRun: params,
            threadId: resourceState.thread.threadId,
            turnId,
            nativeHookRelay: resourceState.nativeHookRelay,
            autoApprove: shouldAutoApproveCodexAppServerApprovals(appServer),
            signal,
            onNativeToolFailureDisposition: (itemId, disposition, approvalKind) =>
              projector?.recordNativeToolApprovalFailure(itemId, disposition, approvalKind),
          });
        }
        return undefined;
      }
      const call = readCodexDynamicToolCallParams(request.params);
      if (!call || call.threadId !== resourceState.thread.threadId || call.turnId !== turnId) {
        return undefined;
      }
      const replayedExecution = openClawDynamicToolExecutions.get(call);
      if (replayedExecution) {
        armCompletionWatchOnResponse = true;
        markCurrentTurnRequestProgress({ hasIndependentTimeout: true });
        state.turnCrossedToolHandoff = true;
        return toCodexDynamicToolProtocolResponse(await replayedExecution) as JsonValue;
      }
      const toolCallOrdinal = allocateCodexToolOutcomeOrdinal?.(call.callId);
      armCompletionWatchOnResponse = true;
      markCurrentTurnRequestProgress({ hasIndependentTimeout: true });
      state.turnCrossedToolHandoff = true;
      pendingOpenClawDynamicToolCompletionIds.add(call.callId);
      trajectoryRecorder?.recordEvent("tool.call", {
        threadId: call.threadId,
        turnId: call.turnId,
        toolCallId: call.callId,
        name: call.tool,
        arguments: call.arguments,
      });
      projector?.recordDynamicToolCall({
        callId: call.callId,
        tool: call.tool,
        arguments: call.arguments,
      });
      emitExecutionPhaseOnce(`tool:${call.callId}`, {
        phase: "tool_execution_started",
        tool: call.tool,
        toolCallId: call.callId,
      });
      const toolMeta = inferCodexDynamicToolMeta(
        call,
        resolveCodexToolProgressDetailMode(params.toolProgressDetail),
      );
      const toolArgs = sanitizeCodexToolArguments(call.arguments);
      const commandBearing = isCodexCommandBearingToolCall(call.tool, toolArgs);
      const shouldEmitDynamicToolProgress = shouldEmitTranscriptToolProgress(call.tool, toolArgs);
      if (shouldEmitDynamicToolProgress) {
        void emitCodexAppServerEvent(params, {
          stream: "tool",
          data: {
            phase: "start",
            name: call.tool,
            itemId: call.callId,
            toolCallId: call.callId,
            ...(toolMeta ? { meta: toolMeta } : {}),
            ...(toolArgs ? { args: toolArgs } : {}),
            ...(commandBearing ? { commandBearing: true } : {}),
          },
        });
      }
      const dynamicToolTimeoutMs = resolveDynamicToolCallTimeoutMs({ call, config: params.config });
      const toolStartedAt = Date.now();
      let terminalDiagnosticObserved = false;
      const unsubscribeToolDiagnosticObserver = onInternalDiagnosticEvent(
        (event) => {
          if (
            isDynamicToolTerminalDiagnosticEvent(event) &&
            isMatchingDynamicToolTerminalDiagnostic({
              event,
              call,
              runId: params.runId,
              sessionId: params.sessionId,
              sessionKey: params.sessionKey,
            })
          ) {
            terminalDiagnosticObserved = true;
          }
        },
        { include: DYNAMIC_TOOL_TERMINAL_DIAGNOSTIC_TYPES },
      );
      try {
        const { execution } = openClawDynamicToolExecutions.claim(call, async () => {
          // Publish the execution claim before persistence yields, so a replay
          // cannot become another owner of this call's progress or result.
          await projector?.transcriptCheckpoint.flush();
          emitDynamicToolStartedDiagnostic({
            call,
            agentId: sessionAgentId,
            runId: params.runId,
            sessionId: params.sessionId,
            sessionKey: params.sessionKey,
          });
          const response = await handleDynamicToolCallWithTimeout({
            call,
            toolBridge,
            signal,
            timeoutMs: dynamicToolTimeoutMs,
            toolMeta,
            toolCallOrdinal,
            onAgentToolResult: params.onAgentToolResult,
            observeToolTerminal: params.observeToolTerminal,
            onFallbackSelected: () => {
              if (toolCallOrdinal !== undefined) {
                suppressedDynamicToolOutcomeOrdinals.add(toolCallOrdinal);
              }
            },
            onTimeout: () => {
              trajectoryRecorder?.recordEvent("tool.timeout", {
                threadId: call.threadId,
                turnId: call.turnId,
                toolCallId: call.callId,
                name: call.tool,
                timeoutMs: dynamicToolTimeoutMs,
              });
            },
          });
          recordCodexDynamicToolResult(
            projector,
            call,
            response,
            toCodexDynamicToolProtocolResponse(response),
          );
          await projector?.transcriptCheckpoint.flush();
          return response;
        });
        const response = await execution;
        const protocolResponse = toCodexDynamicToolProtocolResponse(response);
        if (!protocolResponse.success && toolCallOrdinal !== undefined) {
          suppressedDynamicToolOutcomeOrdinals.add(toolCallOrdinal);
          params.onToolOutcome?.({
            toolName: call.tool,
            argsHash: "",
            resultHash: "",
            toolCallOrdinal,
            terminalPresentation: undefined,
            presentationOnly: true,
          });
        }
        const toolDurationMs = Math.max(0, Date.now() - toolStartedAt);
        trajectoryRecorder?.recordEvent("tool.result", {
          threadId: call.threadId,
          turnId: call.turnId,
          toolCallId: call.callId,
          name: call.tool,
          success: protocolResponse.success,
          contentItems: protocolResponse.contentItems,
        });
        if (protocolResponse.success && call.tool === "progress_card") {
          const progressCardInput = response.executedArguments ?? call.arguments;
          await projector?.recordDynamicProgressCardUpdate(progressCardInput);
          compactionPlanState.recordProgressCardInput(progressCardInput);
        }
        if (shouldEmitDynamicToolProgress) {
          const progressResponse = toCodexDynamicToolProgressResponse(response, protocolResponse);
          void emitCodexAppServerEvent(params, {
            stream: "tool",
            data: {
              phase: "result",
              name: call.tool,
              itemId: call.callId,
              toolCallId: call.callId,
              ...(toolMeta ? { meta: toolMeta } : {}),
              ...(commandBearing ? { commandBearing: true } : {}),
              isError: !protocolResponse.success,
              result: toTranscriptToolResult(progressResponse),
            },
          });
        }
        if (
          !terminalDiagnosticObserved &&
          !hasPendingDynamicToolTerminalDiagnostic({
            call,
            runId: params.runId,
            sessionId: params.sessionId,
            sessionKey: params.sessionKey,
          })
        ) {
          emitDynamicToolTerminalDiagnostic({
            response,
            call,
            agentId: sessionAgentId,
            runId: params.runId,
            sessionId: params.sessionId,
            sessionKey: params.sessionKey,
            durationMs: toolDurationMs,
          });
        }
        pendingOpenClawDynamicToolCompletionIds.delete(call.callId);
        if (response.terminate === true && response.success) {
          scheduleTurnReleaseAfterTerminalDynamicTool({
            call,
            response,
            durationMs: toolDurationMs,
          });
        } else if (!shouldBlockTerminalReleaseForNonTerminalDynamicToolResult(response)) {
          scheduleTerminalDynamicToolReleaseCheck();
        } else {
          state.currentTurnHadNonTerminalDynamicToolResult = true;
          state.pendingTerminalDynamicToolRelease = undefined;
        }
        return protocolResponse as JsonValue;
      } catch (error) {
        pendingOpenClawDynamicToolCompletionIds.delete(call.callId);
        if (
          !terminalDiagnosticObserved &&
          !hasPendingDynamicToolTerminalDiagnostic({
            call,
            runId: params.runId,
            sessionId: params.sessionId,
            sessionKey: params.sessionKey,
          })
        ) {
          emitDynamicToolErrorDiagnostic({
            call,
            agentId: sessionAgentId,
            runId: params.runId,
            sessionId: params.sessionId,
            sessionKey: params.sessionKey,
            durationMs: Math.max(0, Date.now() - toolStartedAt),
          });
        }
        throw error;
      } finally {
        toolOutcomeOrdinals.delete(call.callId);
        unsubscribeToolDiagnosticObserver();
      }
    } finally {
      if (requestCountsAsTurnActivity) {
        state.activeAppServerTurnRequests = Math.max(0, state.activeAppServerTurnRequests - 1);
        if (requestKeepsAttemptWatchArmed) {
          state.activeAppServerTurnRequestsWithoutTimeout = Math.max(
            0,
            state.activeAppServerTurnRequestsWithoutTimeout - 1,
          );
        }
        const postToolContinuationTimeoutMs =
          request.method === "item/tool/call" && state.turnCrossedToolHandoff
            ? postToolRawAssistantCompletionIdleTimeoutMs
            : undefined;
        turnWatches.touchActivity(`request:${request.method}:response`, {
          arm: armCompletionWatchOnResponse,
          attemptProgress: true,
          ...(postToolContinuationTimeoutMs !== undefined
            ? { attemptTimeoutMs: postToolContinuationTimeoutMs }
            : {}),
        });
        if (armCompletionWatchOnResponse && postToolContinuationTimeoutMs !== undefined) {
          turnWatches.armCompletionIdleWatch({ timeoutMs: postToolContinuationTimeoutMs });
        }
        scheduleTerminalDynamicToolReleaseCheck();
      } else {
        turnWatches.scheduleProgressWatches();
      }
    }
  };
  return { handleServerRequest };
}

import {
  embeddedAgentLog,
  hasBeforeToolCallPolicy,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { resolveAgentConfig } from "openclaw/plugin-sdk/agent-scope-runtime";
import { resolveCodexAppServerForModelProvider } from "./app-server-policy.js";
import { startCodexAttemptThread } from "./attempt-startup.js";
import { flattenCodexDynamicToolFunctions } from "./protocol.js";
import { readBoundedCodexRemoteWorkspaceFile } from "./remote-workspace-media.js";
import {
  emitCodexAppServerEvent,
  withCodexAppServerFastModeServiceTier,
} from "./run-attempt-lifecycle.js";
import type { CodexAttemptResources } from "./run-attempt-resources.js";
import { joinPresentSections } from "./run-attempt-state.js";
import { recordCodexTrajectoryContext } from "./trajectory.js";

export async function startCodexAttemptRuntime(resources: CodexAttemptResources) {
  const {
    prompt,
    state,
    trajectoryRecorder,
    activateNativePreToolUseFailureFallback,
    releaseSandboxExecEnvironment,
    releaseSharedClientLeaseAndRetireOneShotClient,
    releaseCurrentRoute,
    runCleanupStep,
    startupTimeoutMs,
    buildNativeHookRelayFinalConfigPatch,
  } = resources;
  const {
    context,
    turnState,
    buildRenderedCodexDeveloperInstructions,
    rebuildCodexTurnPromptTextFromCurrentProjection,
    applyNoContextEngineContinuityProjection,
  } = prompt;
  const { runtime, attemptTools, promptState } = context;
  const {
    connection,
    runtimeParams,
    preparedAuthBinding,
    buildActiveRunAttemptParams,
    startupAuthAccountCacheKey,
    startupEnvApiKeyCacheKey,
    bundleMcpThreadConfig,
    nativeToolSurfaceEnabled,
    nativeProviderWebSearchSupport,
    effectiveRuntimeModelId,
    sandboxExecServerEnabled,
  } = runtime;
  const { toolBridge, toolState } = attemptTools;
  const developerInstructions = joinPresentSections(
    turnState.promptBuild.developerInstructions,
    attemptTools.scheduledConfiguredMcp?.diagnosticNotice,
  );
  const {
    params,
    attemptClientFactory,
    bindingStore,
    appServer,
    pluginConfig,
    computerUseConfig,
    startupClientAuthProfileId,
    runtimeArtifactRequest,
    startupPreparedAuth,
    agentDir,
    sessionAgentId,
    effectiveWorkspace,
    effectiveCwd,
    sandbox,
    runAbortController,
    usesSupervisionConnection,
    resolveReviewerPolicyContext,
    resolveRuntimeOptionsForCurrentBinding,
    startupAuthProfileId,
    startupAuthRequirement,
    abortFromUpstream,
  } = connection;
  let pluginAppServer = withCodexAppServerFastModeServiceTier(appServer, runtimeParams);
  const loopDetectionEnabled =
    (sessionAgentId && params.config
      ? resolveAgentConfig(params.config, sessionAgentId)?.tools?.loopDetection?.enabled
      : undefined) ??
    params.config?.tools?.loopDetection?.enabled ??
    false;
  try {
    void emitCodexAppServerEvent(params, {
      stream: "codex_app_server.lifecycle",
      data: { phase: "startup" },
    });
    const startupResult = await startCodexAttemptThread({
      attemptClientFactory,
      bindingStore,
      runtime: connection.options.runtime,
      appServer: pluginAppServer,
      pluginConfig,
      computerUseConfig,
      startupAuthProfileId: startupClientAuthProfileId,
      startupAuthRequirement,
      startupAuthBindingFingerprint: preparedAuthBinding?.fingerprint,
      ...(runtimeArtifactRequest ? { runtimeArtifactRequest } : {}),
      startupPreparedAuth,
      startupAuthAccountCacheKey,
      startupEnvApiKeyCacheKey,
      agentDir,
      config: params.config,
      shellEnvironment: connection.shellEnvironment,
      disableLoginShell: connection.disableLoginShell,
      buildAttemptParams: buildActiveRunAttemptParams,
      ...(effectiveRuntimeModelId !== runtimeParams.modelId
        ? { runtimeModelId: effectiveRuntimeModelId }
        : {}),
      sessionAgentId,
      effectiveWorkspace,
      effectiveCwd,
      dynamicTools: toolBridge.specs,
      persistentWebSearchAllowed: toolState.persistentWebSearchAllowed,
      webSearchAllowed: toolState.webSearchAllowed,
      developerInstructions,
      agentWorkspaceDeveloperInstructions: context.agentWorkspaceDeveloperInstructions,
      buildFinalConfigPatch: buildNativeHookRelayFinalConfigPatch,
      nativeHookRelayRequired:
        connection.options.nativeHookRelay?.enabled !== false &&
        params.pluginHarnessToolPolicyRestricted !== true &&
        connection.nativeHookRelayEvents.includes("pre_tool_use") &&
        (hasBeforeToolCallPolicy() ||
          (appServer.loopDetectionPreToolUseRelay &&
            Boolean(connection.sandboxSessionKey) &&
            loopDetectionEnabled)),
      bundleMcpThreadConfig,
      configuredMcpOwnershipVersion: attemptTools.configuredMcpOwnershipVersion,
      nativeToolSurfaceEnabled,
      nativeProviderWebSearchSupport,
      sandboxExecServerEnabled,
      sandbox,
      contextEngineProjection: promptState.contextEngineProjection,
      startupTimeoutMs,
      signal: runAbortController.signal,
      onStartupTimeout: () => runAbortController.abort("codex_startup_timeout"),
      onExecutionDisconnect: (error) => {
        state.executionDisconnectError = error;
        embeddedAgentLog.warn(error.message);
        runAbortController.abort("client_closed");
      },
      spawnedBy: params.spawnedBy,
    });
    state.client = startupResult.client;
    state.thread = startupResult.thread;
    state.runtimeArtifact = startupResult.runtimeArtifact;
    state.turnRouter = startupResult.turnRouter;
    state.turnRoute = startupResult.turnRoute;
    // Adopt cleanup ownership before any fallible validation of the started thread.
    state.sandboxExecEnvironment = startupResult.sandboxEnvironment;
    state.releaseSharedClientLease = startupResult.releaseSharedClientLease;
    state.restartContextEngineCodexThread = startupResult.restartContextEngineCodexThread;
    pluginAppServer = startupResult.pluginAppServer;
    toolBridge.setRemoteWorkspaceFileReader?.(
      ({ path, maxBytes, workspaceRoot, signal, timeoutMs }) =>
        readBoundedCodexRemoteWorkspaceFile({
          client: startupResult.client,
          path,
          maxBytes,
          workspaceRoot,
          signal,
          timeoutMs,
        }),
    );
    if (
      usesSupervisionConnection &&
      (state.thread.connectionScope !== "supervision" ||
        state.thread.supervisionSourceThreadId !==
          connection.mutable.startupBinding?.supervisionSourceThreadId)
    ) {
      throw new Error("Codex supervised thread lost its private connection ownership");
    }
    if (state.thread.lifecycle.action === "started" || state.thread.lifecycle.action === "forked") {
      const activePolicy = resolveReviewerPolicyContext(state.thread);
      const activeConfig = resolveRuntimeOptionsForCurrentBinding({
        modelProvider: activePolicy.modelProvider,
        model: activePolicy.model,
      });
      const activeAppServer = resolveCodexAppServerForModelProvider({
        appServer: activeConfig,
        provider: activePolicy.modelProvider,
        model: activePolicy.model,
        config: params.config,
        env: process.env,
        agentDir,
      });
      const previousReviewer = pluginAppServer.approvalsReviewer;
      pluginAppServer = {
        ...pluginAppServer,
        approvalsReviewer: activeAppServer.approvalsReviewer,
      };
      if (pluginAppServer.approvalsReviewer !== previousReviewer) {
        embeddedAgentLog.info(
          "codex app-server approval reviewer updated from active thread model provider",
          {
            from: previousReviewer,
            to: pluginAppServer.approvalsReviewer,
            modelProvider: activePolicy.modelProvider,
          },
        );
      }
    }
    state.codexEnvironmentSelection = startupResult.environmentSelection;
    state.codexExecutionCwd = startupResult.executionCwd;
    state.codexSandboxPolicy = startupResult.sandboxPolicy;
    void emitCodexAppServerEvent(params, {
      stream: "codex_app_server.lifecycle",
      data: {
        phase: "thread_ready",
        threadId: state.thread.threadId,
        action: state.thread.lifecycle.action,
        clientId: state.client.getInstanceId(),
      },
    });
    if (applyNoContextEngineContinuityProjection(state.thread.lifecycle.action, state.thread)) {
      await rebuildCodexTurnPromptTextFromCurrentProjection();
    }
    trajectoryRecorder?.recordEvent("session.started", {
      sessionFile: params.sessionFile,
      threadId: state.thread.threadId,
      authProfileId: startupAuthProfileId,
      workspaceDir: effectiveWorkspace,
      toolCount: flattenCodexDynamicToolFunctions(toolBridge.specs).length,
    });
    recordCodexTrajectoryContext(trajectoryRecorder, {
      attempt: params,
      cwd: effectiveCwd,
      developerInstructions: joinPresentSections(
        buildRenderedCodexDeveloperInstructions(),
        attemptTools.scheduledConfiguredMcp?.diagnosticNotice,
      ),
      prompt: turnState.codexTurnPromptText,
      tools: toolBridge.availableSpecs,
    });
    connection.mutable.pluginAppServer = pluginAppServer;
  } catch (error) {
    await runCleanupStep(
      "codex-start-failure-hook-fallback",
      activateNativePreToolUseFailureFallback,
    );
    await runCleanupStep("codex-start-failure-route-release", releaseCurrentRoute);
    const nativeHookRelay = state.nativeHookRelay;
    state.nativeHookRelay = undefined;
    await runCleanupStep("codex-start-failure-native-hook-relay", () =>
      nativeHookRelay?.unregister(),
    );
    await runCleanupStep("codex-start-failure-sandbox-release", releaseSandboxExecEnvironment);
    await runCleanupStep(
      "codex-start-failure-shared-client-release",
      releaseSharedClientLeaseAndRetireOneShotClient,
    );
    await runCleanupStep("codex-start-failure-abort-listener", () =>
      params.abortSignal?.removeEventListener("abort", abortFromUpstream),
    );
    throw state.executionDisconnectError ?? error;
  }
}

// Codex tests cover run-attempt prompt state helpers.
import { describe, expect, it } from "vitest";
import { prependCurrentInboundContext } from "./run-attempt-state.js";

describe("prependCurrentInboundContext", () => {
  it("neutralizes explicit mention sigils in inbound context but not the prompt", () => {
    const joined = prependCurrentInboundContext("run $current-skill now", {
      text: "Quoted reply: please try $example-manual later",
    });

    expect(joined).toBe(
      "Quoted reply: please try ＄example-manual later\n\nrun $current-skill now",
    );
  });

  it("returns the prompt unchanged without inbound context", () => {
    expect(prependCurrentInboundContext("run $current-skill now", undefined)).toBe(
      "run $current-skill now",
    );
  });
});

import {
  embeddedAgentLog,
  formatErrorMessage,
  type EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import {
  asBoolean,
  asFiniteNumber,
  hasNonEmptyString,
} from "openclaw/plugin-sdk/string-coerce-runtime";
import type { EmbeddedRunAttemptResult } from "./attempt-terminal.js";
import { CodexAppServerRpcError } from "./client.js";
import { neutralizeCodexExplicitMentionSigils } from "./context-engine-projection.js";
import { isJsonObject, type CodexServerNotification } from "./protocol.js";
import type {
  CodexAppServerBindingIdentity,
  CodexAppServerBindingStore,
} from "./session-binding.js";
import type { CodexAppServerThreadLifecycleBinding } from "./thread-lifecycle.js";

export async function clearCodexBindingAfterInvalidImagePayload(
  bindingStore: CodexAppServerBindingStore,
  identity: CodexAppServerBindingIdentity,
  fields: { phase: string; threadId?: string; turnId?: string; error?: string },
): Promise<void> {
  const currentBinding = await bindingStore.read(identity);
  const expectedThreadId = fields.threadId ?? currentBinding?.threadId;
  if (!expectedThreadId) {
    return;
  }
  if (currentBinding && currentBinding.threadId !== expectedThreadId) {
    embeddedAgentLog.warn(
      "codex app-server image payload error detected for unbound thread; preserving thread binding",
      { ...fields, boundThreadId: currentBinding.threadId },
    );
    return;
  }
  if (currentBinding?.connectionScope === "supervision") {
    embeddedAgentLog.warn(
      "codex app-server image payload error detected for supervised thread; preserving native binding",
      fields,
    );
    return;
  }
  embeddedAgentLog.warn(
    "codex app-server image payload error detected; clearing thread binding",
    fields,
  );
  await bindingStore.mutate(identity, { kind: "clear", threadId: expectedThreadId });
}

export async function markCodexAppServerBindingCoveredThroughTurn(params: {
  bindingStore: CodexAppServerBindingStore;
  identity: CodexAppServerBindingIdentity;
  threadId: string;
  continuityCalibration?: { promptChars: number; inputTokens: number };
}): Promise<void> {
  await params.bindingStore.mutate(params.identity, {
    kind: "patch",
    threadId: params.threadId,
    patch: {
      historyCoveredThrough: new Date().toISOString(),
      ...(params.continuityCalibration
        ? { continuityCalibration: params.continuityCalibration }
        : {}),
    },
  });
}

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

export function shouldUseFreshCodexThreadAfterContextEngineOverflow(params: {
  error: unknown;
  contextEngineActive: boolean;
  thread: CodexAppServerThreadLifecycleBinding;
}): boolean {
  if (!params.contextEngineActive || params.thread.lifecycle.action !== "resumed") {
    return false;
  }
  const message = formatErrorMessage(params.error);
  return (
    /ran out of room in the model'?s context window/iu.test(message) ||
    /context window/iu.test(message) ||
    /context length/iu.test(message) ||
    /maximum context/iu.test(message) ||
    /too many tokens/iu.test(message)
  );
}

export function isCodexActiveCompactTurnError(error: unknown): boolean {
  if (!(error instanceof CodexAppServerRpcError)) {
    return false;
  }
  const data = isJsonObject(error.data) ? error.data : undefined;
  const codexErrorInfo = isJsonObject(data?.codexErrorInfo) ? data.codexErrorInfo : undefined;
  const activeTurn = isJsonObject(codexErrorInfo?.activeTurnNotSteerable)
    ? codexErrorInfo.activeTurnNotSteerable
    : undefined;
  return activeTurn?.turnKind === "compact";
}

export function readCodexFinalizationHookNotification(
  notification: CodexServerNotification,
  threadId: string,
  turnId: string,
):
  | { phase: "started"; runId: string }
  | { phase: "completed"; runId: string; status: string | undefined }
  | undefined {
  if (notification.method !== "hook/started" && notification.method !== "hook/completed") {
    return undefined;
  }
  const params = isJsonObject(notification.params) ? notification.params : undefined;
  const run = params && isJsonObject(params.run) ? params.run : undefined;
  // Codex selects exactly one of Stop or SubagentStop from the turn's session
  // source, so these event names share aggregation state but cannot coexist.
  if (
    params?.threadId !== threadId ||
    params.turnId !== turnId ||
    (run?.eventName !== "stop" && run?.eventName !== "subagentStop") ||
    typeof run.id !== "string" ||
    !run.id
  ) {
    return undefined;
  }
  if (notification.method === "hook/started") {
    return { phase: "started", runId: run.id };
  }
  return {
    phase: "completed",
    runId: run.id,
    status: typeof run.status === "string" ? run.status : undefined,
  };
}

export function joinPresentSections(...sections: Array<string | undefined>): string {
  return sections.filter((section): section is string => Boolean(section?.trim())).join("\n\n");
}

export function prependCurrentInboundContext(
  prompt: string,
  context: EmbeddedRunAttemptParams["currentInboundContext"],
): string {
  // Inbound context carries quoted replies and room backlog, not the raw
  // current request; Codex must not resolve explicit mentions from it.
  const text = context?.text.trim();
  return text
    ? [neutralizeCodexExplicitMentionSigils(text), prompt].filter(Boolean).join("\n\n")
    : prompt;
}

export function buildCodexAppServerTimeoutDiagnostics(params: {
  idleMs?: number;
  timeoutMs?: number;
  lastActivityReason?: string;
  details?: Record<string, unknown>;
}): NonNullable<EmbeddedRunAttemptResult["codexAppServerFailure"]>["diagnostics"] {
  const readNonBlankDetailString = (key: string) => {
    const value = params.details?.[key];
    return hasNonEmptyString(value) ? value : undefined;
  };
  const activeAppServerTurnRequests = asFiniteNumber(params.details?.activeAppServerTurnRequests);
  const activeTurnItemCount = asFiniteNumber(params.details?.activeTurnItemCount);
  const terminalTurnNotificationQueued = asBoolean(params.details?.terminalTurnNotificationQueued);
  const completionIdleWatchArmed = asBoolean(params.details?.completionIdleWatchArmed);
  const assistantCompletionIdleWatchArmed = asBoolean(
    params.details?.assistantCompletionIdleWatchArmed,
  );
  const terminalIdleWatchArmed = asBoolean(params.details?.terminalIdleWatchArmed);
  return {
    ...(params.idleMs !== undefined ? { idleMs: params.idleMs } : {}),
    ...(params.timeoutMs !== undefined ? { timeoutMs: params.timeoutMs } : {}),
    ...(params.lastActivityReason ? { lastActivityReason: params.lastActivityReason } : {}),
    ...(readNonBlankDetailString("lastNotificationMethod")
      ? { lastNotificationMethod: readNonBlankDetailString("lastNotificationMethod") }
      : {}),
    ...(readNonBlankDetailString("lastNotificationItemId")
      ? { lastNotificationItemId: readNonBlankDetailString("lastNotificationItemId") }
      : {}),
    ...(readNonBlankDetailString("lastNotificationItemType")
      ? { lastNotificationItemType: readNonBlankDetailString("lastNotificationItemType") }
      : {}),
    ...(readNonBlankDetailString("lastNotificationItemRole")
      ? { lastNotificationItemRole: readNonBlankDetailString("lastNotificationItemRole") }
      : {}),
    ...(readNonBlankDetailString("lastAssistantTextPreview")
      ? { lastAssistantTextPreview: readNonBlankDetailString("lastAssistantTextPreview") }
      : {}),
    ...(activeAppServerTurnRequests !== undefined ? { activeAppServerTurnRequests } : {}),
    ...(activeTurnItemCount !== undefined ? { activeTurnItemCount } : {}),
    ...(terminalTurnNotificationQueued !== undefined ? { terminalTurnNotificationQueued } : {}),
    ...(completionIdleWatchArmed !== undefined ? { completionIdleWatchArmed } : {}),
    ...(assistantCompletionIdleWatchArmed !== undefined
      ? { assistantCompletionIdleWatchArmed }
      : {}),
    ...(terminalIdleWatchArmed !== undefined ? { terminalIdleWatchArmed } : {}),
  };
}

