      const steer = harness.requests.find((entry) => entry.method === "turn/steer")
        ?.params as SteerRequest;
      expect(steer).toMatchObject({
        threadId: "thread-1",
        expectedTurnId: "turn-1",
        clientUserMessageId: expect.any(String),
      });
