      await notifyConsumed(harness, steer.clientUserMessageId);
      expect(fixture.recorder.persistApproved).not.toHaveBeenCalled();
      expect(await fixture.readSteeredMessages()).toEqual([]);
      await result?.recorder?.persistApproved();
