  setCodexAppServerClientFactoryForTest(async () => {
    const client = {
      ...mockClientRuntimeMethods(),
      request: vi.fn(async (method: string) => {
        events.push(`request:${method}`);
        if (method === "thread/start") {
          return threadStartResult();
