      addRequestHandler: vi.fn(() => () => undefined),
      addCloseHandler: vi.fn(() => () => undefined),
      closeAndWait,
    };
    state.client = client;
    return client as never;
  });
  return { closeAndWait, events, retireSpy, state };
}

