      expect(result.codexAppServerFailure?.turnWatchTimeoutKind).toBe("terminal");
      expect(resolveActiveEmbeddedRunSessionId(params.sessionKey!)).toBeUndefined();
    } finally {
      projection.resolve();
      blockedReply.resolve();
      vi.useRealTimers();
