/**
 * Implements filesystem JSON-RPC handlers for the Codex sandbox exec-server
 * with OpenClaw sandbox policy checks before every bridge operation.
 */
import { posix as pathPosix } from "node:path";
import type { SandboxFsStat } from "openclaw/plugin-sdk/sandbox";
import type { JsonObject, JsonValue } from "../protocol.js";
import {
  assertFsSandboxAccess,
  assertNoReadOnlyDescendant,
  assertResolvedFsSandboxAccess,
  joinSandboxChildPath,
  normalizeSandboxAbsolutePath,
  pathContains,
  resolveFsSandboxPolicy,
} from "./fs-policy.js";
import {
  JSON_RPC_NOT_FOUND,
  JsonRpcProtocolError,
  requireBase64String,
  requireNumber,
  requireObject,
  requireString,
} from "./json-rpc.js";
import { resolveExecServerPath } from "./path-uri.js";
import type { DirectoryEntry, OpenClawExecServer, ResolvedFsSandboxPolicy } from "./types.js";

const CODEX_SANDBOX_EXEC_SERVER_MAX_READ_FILE_BYTES = 512 * 1024 * 1024;
const CODEX_SANDBOX_EXEC_SERVER_MAX_OPEN_FILE_READS = 128;
const CODEX_SANDBOX_EXEC_SERVER_MAX_BUFFERED_FILE_READ_BYTES = 64 * 1024 * 1024;
const CODEX_SANDBOX_EXEC_SERVER_MAX_READ_BLOCK_BYTES = 1024 * 1024;
const CODEX_SANDBOX_EXEC_SERVER_MAX_FILE_READ_HANDLE_ID_BYTES = 32;

type CodexSandboxFileReadHandle = {
  abortController: AbortController;
  closeRequested: boolean;
  reservedBytes: number;
  data?: Buffer;
};

/** Sandboxed file contents and pending reservations owned by one connection. */
export type CodexSandboxFileReadHandles = Map<string, CodexSandboxFileReadHandle> & {
  closed?: boolean;
};

/** Opens a policy-checked sandbox file under a bounded, connection-owned handle. */
export async function openFile(
  execServer: OpenClawExecServer,
  handles: CodexSandboxFileReadHandles,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "fs/open params");
  const handleId = requireFileReadHandleId(record.handleId);
  if (handles.closed) {
    throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, `unknown file read handle \`${handleId}\``);
  }
  if (handles.has(handleId)) {
    throw new JsonRpcProtocolError(-32600, `file read handle \`${handleId}\` already exists`);
  }
  if (handles.size >= CODEX_SANDBOX_EXEC_SERVER_MAX_OPEN_FILE_READS) {
    throw new JsonRpcProtocolError(
      -32600,
      `at most ${CODEX_SANDBOX_EXEC_SERVER_MAX_OPEN_FILE_READS} file reads may be open per connection`,
    );
  }

  const filePath = resolveExecServerPath(requireString(record.path, "path"), "read path");
  assertFsSandboxAccess(execServer, record, [{ path: filePath, access: "read" }]);
  const fsBridge = execServer.fsBridge;
  // Claim the handle before even stat so slow or cancelled stats cannot bypass
  // the connection's handle cap or lose their cancellation and ownership.
  const handle: CodexSandboxFileReadHandle = {
    abortController: new AbortController(),
    closeRequested: false,
    reservedBytes: 0,
  };
  handles.set(handleId, handle);
  try {
    const stat = await fsBridge.stat({ filePath, signal: handle.abortController.signal });
    if (handles.get(handleId) !== handle || handle.closeRequested || handles.closed) {
      throw new JsonRpcProtocolError(
        JSON_RPC_NOT_FOUND,
        `unknown file read handle \`${handleId}\``,
      );
    }
    if (!stat) {
      throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, "file not found");
    }
    if (stat.type !== "file") {
      throw new JsonRpcProtocolError(-32600, "file read handle requires a regular file");
    }
    if (!Number.isSafeInteger(stat.size) || stat.size < 0) {
      throw new JsonRpcProtocolError(-32600, "file size must be a non-negative safe integer");
    }
    if (
      stat.size >
      CODEX_SANDBOX_EXEC_SERVER_MAX_BUFFERED_FILE_READ_BYTES - bufferedFileReadBytes(handles)
    ) {
      throw new JsonRpcProtocolError(
        -32600,
        "sandbox file read exceeds the per-connection buffered file limit",
      );
    }
    // Charge actual bytes before awaiting the bounded read; concurrent stats
    // cannot overbook memory, even when a backend ignores cancellation.
    handle.reservedBytes = stat.size;
    const data = await fsBridge.readFile({
      filePath,
      maxBytes: handle.reservedBytes,
      signal: handle.abortController.signal,
    });
    if (handles.get(handleId) !== handle || handle.closeRequested || handles.closed) {
      throw new JsonRpcProtocolError(
        JSON_RPC_NOT_FOUND,
        `unknown file read handle \`${handleId}\``,
      );
    }
    if (data.byteLength > handle.reservedBytes) {
      throw new JsonRpcProtocolError(
        -32600,
        "sandbox file read exceeds the per-connection buffered file limit",
      );
    }
    handle.reservedBytes = data.byteLength;
    handle.data = data;
    return { handleId };
  } catch (error) {
    if (handles.get(handleId) === handle) {
      handles.delete(handleId);
    }
    throw error;
  }
}

/** Reads a bounded base64 block from a handle belonging to this connection. */
export function readFileBlock(
  handles: CodexSandboxFileReadHandles,
  params: JsonValue | undefined,
): JsonObject {
  const record = requireObject(params, "fs/readBlock params");
  const handleId = requireFileReadHandleId(record.handleId);
  const handle = handles.get(handleId);
  if (!handle?.data) {
    throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, `unknown file read handle \`${handleId}\``);
  }
  const offset = requireNumber(record.offset, "offset");
  const length = requireNumber(record.len, "len");
  if (!Number.isSafeInteger(offset) || offset < 0) {
    throw new JsonRpcProtocolError(-32600, "file read offset must be a non-negative safe integer");
  }
  if (
    !Number.isSafeInteger(length) ||
    length < 1 ||
    length > CODEX_SANDBOX_EXEC_SERVER_MAX_READ_BLOCK_BYTES
  ) {
    throw new JsonRpcProtocolError(
      -32600,
      `file read block length must be between 1 and ${CODEX_SANDBOX_EXEC_SERVER_MAX_READ_BLOCK_BYTES}`,
    );
  }
  const chunk = handle.data.subarray(offset, Math.min(offset + length, handle.data.byteLength));
  // The complete buffered file makes exactly filled final blocks terminal without another RPC.
  return {
    chunk: chunk.toString("base64"),
    eof: offset + chunk.byteLength >= handle.data.byteLength,
  };
}

/** Closes one connection-owned file handle; repeated closes are harmless. */
export function closeFile(
  handles: CodexSandboxFileReadHandles,
  params: JsonValue | undefined,
): JsonObject {
  const record = requireObject(params, "fs/close params");
  closeFileReadHandle(handles, requireFileReadHandleId(record.handleId));
  return {};
}

/** Cancels a disconnected socket without releasing unsettled read reservations. */
export function closeAllFileReads(handles: CodexSandboxFileReadHandles): void {
  handles.closed = true;
  for (const handleId of handles.keys()) {
    closeFileReadHandle(handles, handleId);
  }
}

function closeFileReadHandle(handles: CodexSandboxFileReadHandles, handleId: string): void {
  const handle = handles.get(handleId);
  if (!handle) {
    return;
  }
  handle.closeRequested = true;
  if (handle.data !== undefined) {
    handles.delete(handleId);
    return;
  }
  // A backend may not honor abort; retain its reservation until readFile settles.
  handle.abortController.abort();
}

function bufferedFileReadBytes(handles: CodexSandboxFileReadHandles): number {
  let total = 0;
  for (const handle of handles.values()) {
    total += handle.reservedBytes;
  }
  return total;
}

function requireFileReadHandleId(value: unknown): string {
  const handleId = requireString(value, "handleId");
  if (
    Buffer.byteLength(handleId, "utf8") > CODEX_SANDBOX_EXEC_SERVER_MAX_FILE_READ_HANDLE_ID_BYTES
  ) {
    throw new JsonRpcProtocolError(
      -32600,
      `file read handle ID must not exceed ${CODEX_SANDBOX_EXEC_SERVER_MAX_FILE_READ_HANDLE_ID_BYTES} bytes`,
    );
  }
  return handleId;
}

/** Reads a sandbox file as base64 after read-policy and size checks. */
export async function readFile(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "fs/readFile params");
  const filePath = resolveExecServerPath(requireString(record.path, "path"), "read path");
  assertFsSandboxAccess(execServer, record, [{ path: filePath, access: "read" }]);
  const fsBridge = execServer.fsBridge;
  const stat = await fsBridge.stat({ filePath });
  if (!stat) {
    throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, "file not found");
  }
  assertSandboxFileReadWithinLimit(stat);
  const data = await fsBridge.readFile({
    filePath,
    maxBytes: CODEX_SANDBOX_EXEC_SERVER_MAX_READ_FILE_BYTES,
  });
  return { dataBase64: data.toString("base64") };
}

/** Writes base64 data to an existing sandbox directory after write-policy checks. */
export async function writeFile(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<void> {
  const record = requireObject(params, "fs/writeFile params");
  const filePath = resolveExecServerPath(requireString(record.path, "path"), "write path");
  assertFsSandboxAccess(execServer, record, [{ path: filePath, access: "write" }]);
  const fsBridge = execServer.fsBridge;
  const parent = await fsBridge.stat({ filePath: pathPosix.dirname(filePath) });
  if (parent?.type !== "directory") {
    throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, "parent directory not found");
  }
  await fsBridge.writeFile({
    filePath,
    data: Buffer.from(requireBase64String(record.dataBase64, "dataBase64"), "base64"),
    mkdir: false,
  });
}

/** Creates a sandbox directory, respecting recursive and parent-directory semantics. */
export async function createDirectory(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<void> {
  const record = requireObject(params, "fs/createDirectory params");
  const filePath = resolveExecServerPath(
    requireString(record.path, "path"),
    "create-directory path",
  );
  assertFsSandboxAccess(execServer, record, [{ path: filePath, access: "write" }]);
  const fsBridge = execServer.fsBridge;
  if (record.recursive === false) {
    const parentPath = pathPosix.dirname(filePath);
    const parent = await fsBridge.stat({ filePath: parentPath });
    if (parent?.type !== "directory") {
      throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, "parent directory not found");
    }
  }
  await fsBridge.mkdirp({
    filePath,
  });
}

/** Returns normalized metadata for a sandbox path. */
export async function getMetadata(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "fs/getMetadata params");
  const filePath = resolveExecServerPath(requireString(record.path, "path"), "metadata path");
  assertFsSandboxAccess(execServer, record, [{ path: filePath, access: "read" }]);
  const stat = await execServer.fsBridge.stat({
    filePath,
  });
  if (!stat) {
    throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, "file not found");
  }
  return metadataResponse(stat);
}

/** Lists sandbox directory entries visible under the resolved filesystem policy. */
export async function readDirectory(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "fs/readDirectory params");
  const filePath = resolveExecServerPath(requireString(record.path, "path"), "read-directory path");
  const fsSandboxPolicy = resolveFsSandboxPolicy(execServer, record);
  return {
    entries: await listDirectoryEntries(execServer, filePath, fsSandboxPolicy),
  };
}

async function listDirectoryEntries(
  execServer: OpenClawExecServer,
  filePath: string,
  fsSandboxPolicy: ResolvedFsSandboxPolicy | undefined,
): Promise<DirectoryEntry[]> {
  assertResolvedFsSandboxAccess(fsSandboxPolicy, [{ path: filePath, access: "read" }]);
  const resolved = execServer.fsBridge.resolvePath({
    filePath,
  });
  if (!resolved) {
    throw new Error(`Cannot resolve sandbox path: ${filePath}`);
  }
  const result = await execServer.backend.runShellCommand({
    script:
      'find "$1" -mindepth 1 -maxdepth 1 -exec sh -c \'for path do name=${path##*/}; if [ -L "$path" ]; then kind=o; elif [ -d "$path" ]; then kind=d; elif [ -f "$path" ]; then kind=f; else kind=o; fi; printf "%s\\t%s\\n" "$kind" "$name"; done\' sh {} +',
    args: [resolved.containerPath],
    allowFailure: true,
  });
  if (result.code !== 0) {
    const stderr = result.stderr.toString("utf8").trim();
    throw new Error(stderr || `sandbox directory listing failed with code ${result.code}`);
  }
  const lines = result.stdout.toString("utf8").split("\n").filter(Boolean);
  return lines.map((line) => {
    const [kind = "o", fileName = ""] = line.split("\t");
    return {
      fileName,
      isDirectory: kind === "d",
      isFile: kind === "f",
    };
  });
}

/** Removes a sandbox path after rejecting writes outside policy or under read-only descendants. */
export async function removePath(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<void> {
  const record = requireObject(params, "fs/remove params");
  const filePath = resolveExecServerPath(requireString(record.path, "path"), "remove path");
  const fsSandboxPolicy = resolveFsSandboxPolicy(execServer, record);
  assertResolvedFsSandboxAccess(fsSandboxPolicy, [{ path: filePath, access: "write" }]);
  if (record.recursive !== false) {
    assertNoReadOnlyDescendant(fsSandboxPolicy, filePath, "remove");
  }
  await execServer.fsBridge.remove({
    filePath,
    recursive: record.recursive !== false,
    force: record.force !== false,
  });
}

/** Copies sandbox files or recursive directories while enforcing source and destination policy. */
export async function copyPath(
  execServer: OpenClawExecServer,
  params: JsonValue | undefined,
): Promise<void> {
  const record = requireObject(params, "fs/copy params");
  const sourcePath = resolveExecServerPath(
    requireString(record.sourcePath ?? record.source, "sourcePath"),
    "copy source path",
  );
  const destinationPath = resolveExecServerPath(
    requireString(record.destinationPath ?? record.destination, "destinationPath"),
    "copy destination path",
  );
  const fsSandboxPolicy = resolveFsSandboxPolicy(execServer, record);
  assertResolvedFsSandboxAccess(fsSandboxPolicy, [
    { path: sourcePath, access: "read" },
    { path: destinationPath, access: "write" },
  ]);
  await copySandboxPath(execServer, {
    sourcePath,
    destinationPath,
    recursive: record.recursive === true,
    fsSandboxPolicy,
  });
}

async function copySandboxPath(
  execServer: OpenClawExecServer,
  params: {
    sourcePath: string;
    destinationPath: string;
    recursive: boolean;
    fsSandboxPolicy: ResolvedFsSandboxPolicy | undefined;
  },
): Promise<void> {
  const fsBridge = execServer.fsBridge;
  assertResolvedFsSandboxAccess(params.fsSandboxPolicy, [
    { path: params.sourcePath, access: "read" },
    { path: params.destinationPath, access: "write" },
  ]);
  const sourceStat = await fsBridge.stat({ filePath: params.sourcePath });
  if (!sourceStat) {
    throw new JsonRpcProtocolError(JSON_RPC_NOT_FOUND, "file not found");
  }
  if (sourceStat?.type === "directory") {
    if (!params.recursive) {
      throw new Error(`Cannot copy directory without recursive=true: ${params.sourcePath}`);
    }
    if (
      pathContains(
        normalizeSandboxAbsolutePath(params.sourcePath, "copy source path"),
        normalizeSandboxAbsolutePath(params.destinationPath, "copy destination path"),
      )
    ) {
      throw new Error("Cannot recursively copy a directory into itself.");
    }
    await fsBridge.mkdirp({ filePath: params.destinationPath });
    for (const entry of await listDirectoryEntries(
      execServer,
      params.sourcePath,
      params.fsSandboxPolicy,
    )) {
      if (!entry.isDirectory && !entry.isFile) {
        throw new Error(`Cannot copy unsupported filesystem entry: ${entry.fileName}`);
      }
      await copySandboxPath(execServer, {
        sourcePath: joinSandboxChildPath(params.sourcePath, entry.fileName),
        destinationPath: joinSandboxChildPath(params.destinationPath, entry.fileName),
        recursive: true,
        fsSandboxPolicy: params.fsSandboxPolicy,
      });
    }
    return;
  }

  if (sourceStat.type === "file" && fsBridge.copyFile) {
    await fsBridge.copyFile({
      sourcePath: params.sourcePath,
      destinationPath: params.destinationPath,
      mkdir: true,
    });
    return;
  }

  // Shipped third-party bridges may not expose streaming copy yet. Keep their
  // buffered fallback bounded while built-in bridges use the path-native copy above.
  assertSandboxFileReadWithinLimit(sourceStat);
  const data = await fsBridge.readFile({
    filePath: params.sourcePath,
    maxBytes: CODEX_SANDBOX_EXEC_SERVER_MAX_READ_FILE_BYTES,
  });
  await fsBridge.writeFile({
    filePath: params.destinationPath,
    data,
    mkdir: true,
  });
}

function assertSandboxFileReadWithinLimit(stat: SandboxFsStat): void {
  if (stat.type === "file" && stat.size > CODEX_SANDBOX_EXEC_SERVER_MAX_READ_FILE_BYTES) {
    throw new Error(
      `file is too large to read through Codex sandbox exec-server: ${stat.size} bytes`,
    );
  }
}

function metadataResponse(stat: SandboxFsStat | null): JsonObject {
  return {
    isDirectory: stat?.type === "directory",
    isFile: stat?.type === "file",
    isSymlink: false,
    size: stat?.size ?? 0,
    createdAtMs: 0,
    modifiedAtMs: stat?.mtimeMs ?? 0,
  };
}

/**
 * Resolves Codex filesystem sandbox policy payloads into OpenClaw path/glob
 * checks for sandbox exec-server filesystem operations.
 */
import { posix as pathPosix } from "node:path";
import type { JsonObject } from "../protocol.js";
import { requireObject, requireString } from "./json-rpc.js";
import { resolveExecServerPath } from "./path-uri.js";
import type {
  FsAccessMode,
  OpenClawExecServer,
  ResolvedFsSandboxEntry,
  ResolvedFsSandboxPolicy,
} from "./types.js";

/** Resolves request-local sandbox policy and asserts each requested path has the needed access. */
export function assertFsSandboxAccess(
  execServer: OpenClawExecServer,
  record: JsonObject,
  requests: Array<{ path: string; access: "read" | "write" }>,
): void {
  assertResolvedFsSandboxAccess(resolveFsSandboxPolicy(execServer, record), requests);
}

/** Parses a Codex managed filesystem sandbox context into normalized access entries. */
export function resolveFsSandboxPolicy(
  execServer: OpenClawExecServer,
  record: JsonObject,
): ResolvedFsSandboxPolicy | undefined {
  if (record.sandbox === undefined || record.sandbox === null) {
    return undefined;
  }
  const sandbox = requireObject(record.sandbox, "fs sandbox context");
  const permissions = requireObject(sandbox.permissions, "fs sandbox permissions");
  const permissionType = requireString(permissions.type, "fs sandbox permissions type");
  if (permissionType === "disabled" || permissionType === "external") {
    return { unrestricted: true, entries: [] };
  }
  if (permissionType !== "managed") {
    throw new Error(`Unsupported Codex fs sandbox permission type: ${permissionType}`);
  }

  const fileSystem = requireObject(permissions.file_system, "fs sandbox file system permissions");
  const fileSystemType = requireString(fileSystem.type, "fs sandbox file system permissions type");
  if (fileSystemType === "unrestricted") {
    return { unrestricted: true, entries: [] };
  }
  if (fileSystemType !== "restricted") {
    throw new Error(`Unsupported Codex fs sandbox file system type: ${fileSystemType}`);
  }
  if (!Array.isArray(fileSystem.entries)) {
    throw new Error("fs sandbox file system entries must be an array.");
  }
  const cwd = readFsSandboxCwd(execServer, sandbox);
  return {
    unrestricted: false,
    entries: fileSystem.entries.flatMap((entry, index) => {
      const resolved = resolveFsSandboxEntry(
        requireObject(entry, `fs sandbox entry ${index}`),
        cwd,
      );
      return resolved ? [resolved] : [];
    }),
  };
}

function readFsSandboxCwd(execServer: OpenClawExecServer, sandbox: JsonObject): string {
  if (sandbox.cwd === undefined || sandbox.cwd === null) {
    return normalizeSandboxAbsolutePath(execServer.sandbox.containerWorkdir, "sandbox cwd");
  }
  return normalizeSandboxAbsolutePath(
    resolveExecServerPath(requireString(sandbox.cwd, "sandbox cwd"), "sandbox cwd"),
    "sandbox cwd",
  );
}

function resolveFsSandboxEntry(entry: JsonObject, cwd: string): ResolvedFsSandboxEntry | undefined {
  const access = readFsAccessMode(entry.access);
  const pathSpec = requireObject(entry.path, "fs sandbox entry path");
  const pathType = requireString(pathSpec.type, "fs sandbox entry path type");
  if (pathType === "path") {
    return {
      kind: "path",
      path: normalizeSandboxAbsolutePath(
        resolveExecServerPath(requireString(pathSpec.path, "fs sandbox path"), "fs sandbox path"),
        "fs sandbox path",
      ),
      access,
    };
  }
  if (pathType === "special") {
    if (isNonGrantingFsSpecialPath(requireObject(pathSpec.value, "fs sandbox special path"))) {
      return undefined;
    }
    return {
      kind: "path",
      path: resolveFsSpecialPath(requireObject(pathSpec.value, "fs sandbox special path"), cwd),
      access,
    };
  }
  if (pathType === "glob_pattern") {
    const pattern = requireString(pathSpec.pattern, "fs sandbox glob pattern");
    const absolutePattern = normalizeSandboxGlobPattern(
      pattern.startsWith("/") ? pattern : pathPosix.join(cwd, pattern),
    );
    return {
      kind: "glob",
      pattern: absolutePattern,
      matcher: compileSandboxGlobPattern(absolutePattern),
      literalPrefix: sandboxGlobLiteralPrefix(absolutePattern),
      access,
    };
  }
  throw new Error(`Unsupported Codex fs sandbox path type: ${pathType}`);
}

function isNonGrantingFsSpecialPath(value: JsonObject): boolean {
  const kind = requireString(value.kind, "fs sandbox special path kind");
  return kind === "minimal" || kind === "unknown";
}

function readFsAccessMode(value: unknown): FsAccessMode {
  if (value === "read" || value === "write" || value === "none") {
    return value;
  }
  if (value === "deny") {
    return "none";
  }
  throw new Error("fs sandbox entry access must be read, write, none, or deny.");
}

function resolveFsSpecialPath(value: JsonObject, cwd: string): string {
  const kind = requireString(value.kind, "fs sandbox special path kind");
  if (kind === "root") {
    return "/";
  }
  if (kind === "project_roots" || kind === "current_working_directory") {
    const subpath =
      value.subpath === undefined || value.subpath === null
        ? undefined
        : requireString(value.subpath, "fs sandbox project roots subpath");
    return normalizeSandboxAbsolutePath(
      subpath ? pathPosix.join(cwd, subpath) : cwd,
      "fs sandbox project roots path",
    );
  }
  if (kind === "slash_tmp" || kind === "tmpdir") {
    return "/tmp";
  }
  throw new Error(`Unsupported Codex fs sandbox special path: ${kind}`);
}

/** Asserts access against an already resolved filesystem sandbox policy. */
export function assertResolvedFsSandboxAccess(
  policy: ResolvedFsSandboxPolicy | undefined,
  requests: Array<{ path: string; access: "read" | "write" }>,
): void {
  if (!policy?.unrestricted && policy) {
    for (const request of requests) {
      const access = resolveFsAccess(policy, request.path);
      if (request.access === "read" && access === "none") {
        throw new Error(`Codex fs sandbox denied read access to ${request.path}`);
      }
      if (request.access === "write" && access !== "write") {
        throw new Error(`Codex fs sandbox denied write access to ${request.path}`);
      }
    }
  }
}

function resolveFsAccess(policy: ResolvedFsSandboxPolicy, rawPath: string): FsAccessMode {
  if (policy.unrestricted) {
    return "write";
  }
  const target = normalizeSandboxAbsolutePath(rawPath, "fs path");
  let selected: { specificity: number; rank: number; access: FsAccessMode } | undefined;
  for (const entry of policy.entries) {
    if (!fsSandboxEntryMatches(entry, target)) {
      continue;
    }
    const candidate = {
      specificity: fsSandboxEntrySpecificity(entry),
      rank: fsAccessRank(entry.access),
      access: entry.access,
    };
    if (
      !selected ||
      candidate.specificity > selected.specificity ||
      (candidate.specificity === selected.specificity && candidate.rank > selected.rank)
    ) {
      selected = candidate;
    }
  }
  return selected?.access ?? "none";
}

/** Rejects recursive writes/removes that would cross protected read-only descendants. */
export function assertNoReadOnlyDescendant(
  policy: ResolvedFsSandboxPolicy | undefined,
  rawPath: string,
  operation: string,
): void {
  if (!policy || policy.unrestricted) {
    return;
  }
  const target = normalizeSandboxAbsolutePath(rawPath, "fs path");
  const protectedDescendant = policy.entries.find((entry) => {
    if (entry.access === "write" || !fsSandboxEntryCanAffectDescendant(entry, target)) {
      return false;
    }
    if (entry.kind === "glob") {
      return true;
    }
    const protectedPath = entry.path;
    return protectedPath && resolveFsAccess(policy, protectedPath) !== "write";
  });
  if (protectedDescendant) {
    const protectedPath =
      protectedDescendant.kind === "path" ? protectedDescendant.path : protectedDescendant.pattern;
    throw new Error(
      `Codex fs sandbox denied recursive ${operation} of ${rawPath} because ${protectedPath} is not writable.`,
    );
  }
}

/** Normalizes and validates an absolute POSIX path inside the sandbox namespace. */
export function normalizeSandboxAbsolutePath(rawPath: string, label: string): string {
  if (!rawPath || rawPath.includes("\0") || !rawPath.startsWith("/")) {
    throw new Error(`${label} must be an absolute sandbox path.`);
  }
  const normalized = pathPosix.normalize(rawPath);
  return normalized === "//" ? "/" : normalized;
}

/** Returns true when target is root itself or a descendant of root. */
export function pathContains(root: string, target: string): boolean {
  return root === "/" || target === root || target.startsWith(`${root}/`);
}

function fsSandboxEntryMatches(entry: ResolvedFsSandboxEntry, target: string): boolean {
  if (entry.kind === "path") {
    return pathContains(entry.path, target);
  }
  return entry.matcher.test(target);
}

function fsSandboxEntryCanAffectDescendant(entry: ResolvedFsSandboxEntry, target: string): boolean {
  if (entry.kind === "path") {
    return pathContains(target, entry.path) && target !== entry.path;
  }
  return pathContains(target, entry.literalPrefix) || pathContains(entry.literalPrefix, target);
}

function fsSandboxEntrySpecificity(entry: ResolvedFsSandboxEntry): number {
  return pathSpecificity(entry.kind === "path" ? entry.path : entry.literalPrefix);
}

function pathSpecificity(filePath: string): number {
  return filePath === "/" ? 0 : filePath.split("/").filter(Boolean).length;
}

function fsAccessRank(access: FsAccessMode): number {
  if (access === "none") {
    return 2;
  }
  if (access === "write") {
    return 1;
  }
  return 0;
}

function normalizeSandboxGlobPattern(pattern: string): string {
  if (!pattern || pattern.includes("\0") || !pattern.startsWith("/")) {
    throw new Error("fs sandbox glob pattern must be absolute.");
  }
  return pattern.replace(/\/{2,}/gu, "/");
}

function compileSandboxGlobPattern(pattern: string): RegExp {
  // Codex sends POSIX-style sandbox globs. Compile only the supported subset so
  // access decisions stay deterministic and path separators cannot be matched
  // by single-segment wildcards.
  let source = "^";
  for (let index = 0; index < pattern.length; index += 1) {
    const char = pattern[index];
    const next = pattern[index + 1];
    if (char === "*" && next === "*" && pattern[index + 2] === "/") {
      source += "(?:.*/)?";
      index += 2;
    } else if (char === "*" && next === "*") {
      source += ".*";
      index += 1;
    } else if (char === "*") {
      source += "[^/]*";
    } else if (char === "?") {
      source += "[^/]";
    } else if (char === "[") {
      const compiledClass = compileSandboxGlobCharacterClass(pattern, index);
      source += compiledClass.source;
      index = compiledClass.endIndex;
    } else {
      source += char?.replace(/[\\^$+?.()|[\]{}]/gu, "\\$&") ?? "";
    }
  }
  source += "$";
  return new RegExp(source, "u");
}

function compileSandboxGlobCharacterClass(
  pattern: string,
  startIndex: number,
): { source: string; endIndex: number } {
  let index = startIndex + 1;
  if (index >= pattern.length) {
    throw new Error("fs sandbox glob character class must be closed.");
  }
  const negated = pattern[index] === "!" || pattern[index] === "^";
  if (negated) {
    index += 1;
  }
  let body = "";
  for (; index < pattern.length; index += 1) {
    const char = pattern[index];
    if (char === "]" && body) {
      return {
        source: `[${negated ? "^" : ""}${body}]`,
        endIndex: index,
      };
    }
    if (!char || char === "/") {
      throw new Error("fs sandbox glob character class cannot match path separators.");
    }
    body += escapeSandboxGlobCharacterClassChar(char, body.length === 0);
  }
  throw new Error("fs sandbox glob character class must be closed.");
}

function escapeSandboxGlobCharacterClassChar(char: string, first: boolean): string {
  if (char === "\\" || char === "]") {
    return `\\${char}`;
  }
  if (first && char === "^") {
    return "\\^";
  }
  return char;
}

function sandboxGlobLiteralPrefix(pattern: string): string {
  const wildcardIndex = pattern.search(/[*?[]/u);
  const prefix = wildcardIndex === -1 ? pattern : pattern.slice(0, wildcardIndex);
  const slash = prefix.lastIndexOf("/");
  if (slash <= 0) {
    return "/";
  }
  return normalizeSandboxAbsolutePath(prefix.slice(0, slash), "fs sandbox glob prefix");
}

/** Safely joins a single directory entry name onto a sandbox parent path. */
export function joinSandboxChildPath(parent: string, child: string): string {
  if (!child || child === "." || child === ".." || child.includes("/") || child.includes("\0")) {
    throw new Error(`Invalid sandbox directory entry name: ${child}`);
  }
  return parent.endsWith("/") ? `${parent}${child}` : `${parent}/${child}`;
}

/**
 * Implements sandboxed HTTP requests for Codex native tools by routing network
 * access through the active OpenClaw sandbox backend.
 */
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import { SsrFBlockedError, isBlockedHostnameOrIp } from "openclaw/plugin-sdk/ssrf-runtime";
import { sliceUtf16Safe } from "openclaw/plugin-sdk/text-utility-runtime";
import type { JsonObject, JsonValue } from "../protocol.js";
import { readHttpHeaders, requireNumber, requireObject, requireString } from "./json-rpc.js";
import {
  prepareSandboxChildExec,
  spawnSandboxChild,
  type SandboxChildOwner,
} from "./sandbox-child.js";
import type {
  CodexSandboxExecSessionNotifications,
  HttpHeader,
  OpenClawExecServer,
} from "./types.js";

/** Maximum JSON-line size accepted from the streaming HTTP helper process. */
const SANDBOX_HTTP_STREAM_LINE_MAX_CHARS = 256 * 1024;

/** Handles one sandbox HTTP JSON-RPC request, optionally streaming response body deltas. */
export async function httpRequest(
  execServer: OpenClawExecServer,
  notifications: CodexSandboxExecSessionNotifications,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "http/request params");
  const requestId = requireString(record.requestId, "requestId");
  const url = requireString(record.url, "url");
  const redirectPolicy = record.redirectPolicy ?? "follow";
  if (redirectPolicy !== "follow" && redirectPolicy !== "stop") {
    throw new Error("http/request redirectPolicy must be follow or stop");
  }
  assertSandboxHttpRequestTargetAllowed(url);
  const request: SandboxHttpRequest = {
    method: requireString(record.method, "method"),
    url,
    headers: readHttpHeaders(record.headers),
    bodyBase64: typeof record.bodyBase64 === "string" ? record.bodyBase64 : undefined,
    timeoutMs:
      typeof record.timeoutMs === "number" && record.timeoutMs > 0
        ? Math.floor(record.timeoutMs)
        : undefined,
    redirectPolicy,
    streamResponse: record.streamResponse === true,
  };
  if (request.streamResponse) {
    return await runStreamingSandboxHttpRequest(execServer, notifications, requestId, request);
  }
  const result = await runSandboxHttpRequest(execServer, {
    ...request,
    streamResponse: false,
  });
  return result;
}

type SandboxHttpRequest = {
  method: string;
  url: string;
  headers: HttpHeader[];
  bodyBase64?: string;
  timeoutMs?: number;
  redirectPolicy: "follow" | "stop";
  streamResponse: boolean;
};

function assertSandboxHttpRequestTargetAllowed(url: string): void {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new SsrFBlockedError("Invalid URL supplied to sandbox http/request");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new SsrFBlockedError(
      `Blocked non-HTTP(S) protocol in sandbox http/request: ${parsed.protocol}`,
    );
  }
  if (isBlockedHostnameOrIp(parsed.hostname)) {
    throw new SsrFBlockedError(
      `Blocked hostname or private/internal IP in sandbox http/request: ${parsed.hostname}`,
    );
  }
}

async function runSandboxHttpRequest(
  execServer: OpenClawExecServer,
  params: SandboxHttpRequest,
): Promise<JsonObject & { status: number; headers: HttpHeader[]; bodyBase64: string }> {
  const result = await execServer.backend.runShellCommand({
    script: SANDBOX_HTTP_REQUEST_SCRIPT,
    stdin: JSON.stringify(params),
    allowFailure: true,
  });
  if (result.code !== 0) {
    const stderr = result.stderr.toString("utf8").trim();
    throw new Error(stderr || `sandbox http/request failed with code ${result.code}`);
  }
  const parsed = JSON.parse(result.stdout.toString("utf8")) as {
    status?: unknown;
    headers?: unknown;
    bodyBase64?: unknown;
  };
  if (typeof parsed.status !== "number" || !Array.isArray(parsed.headers)) {
    throw new Error("sandbox http/request returned an invalid response envelope");
  }
  return {
    status: parsed.status,
    headers: readHttpHeaders(parsed.headers),
    bodyBase64: typeof parsed.bodyBase64 === "string" ? parsed.bodyBase64 : "",
  };
}

async function runStreamingSandboxHttpRequest(
  execServer: OpenClawExecServer,
  notifications: CodexSandboxExecSessionNotifications,
  requestId: string,
  params: SandboxHttpRequest,
): Promise<JsonObject> {
  const backend = execServer.backend;
  const remoteExec = prepareSandboxChildExec(backend, {});
  const execSpec = await backend.buildExecSpec({
    command: SANDBOX_HTTP_REQUEST_SCRIPT,
    workdir: execServer.sandbox.containerWorkdir,
    env: remoteExec.env,
    usePty: false,
  });
  const lifecycle = { failed: false };
  const owner = await spawnSandboxChild({
    argv: execSpec.argv,
    env: execSpec.env,
    finalizeExec: backend.finalizeExec,
    finalizeToken: execSpec.finalizeToken,
    finalizeStatus: (outcome) =>
      lifecycle.failed || outcome.exitCode !== 0 ? "failed" : "completed",
    onFinalizeError: (error) => {
      embeddedAgentLog.warn("codex sandbox http/request finalize failed", { error });
    },
    owners: execServer.children,
    terminateRemote: remoteExec.terminate,
  });
  const child = owner.process;
  const abortOnSessionClose = () => {
    lifecycle.failed = true;
    void owner.terminate().catch((error: unknown) => {
      embeddedAgentLog.warn("codex sandbox http/request cleanup failed", { error });
    });
  };
  notifications.signal.addEventListener("abort", abortOnSessionClose, { once: true });
  child.once("close", () => {
    notifications.signal.removeEventListener("abort", abortOnSessionClose);
  });
  if (notifications.signal.aborted) {
    abortOnSessionClose();
  }
  child.stdin.on("error", (error: NodeJS.ErrnoException) => {
    if (error.code === "EPIPE" || error.code === "ERR_STREAM_DESTROYED") {
      return;
    }
    embeddedAgentLog.warn("codex sandbox http/request stdin write failed", { error });
  });
  child.stdin.end(JSON.stringify(params));
  return await readStreamingSandboxHttpResponse({
    child,
    lifecycle,
    owner,
    requestId,
    notifications,
  });
}

function readStreamingSandboxHttpResponse(params: {
  child: SandboxChildOwner["process"];
  lifecycle: { failed: boolean };
  owner: SandboxChildOwner;
  requestId: string;
  notifications: CodexSandboxExecSessionNotifications;
}): Promise<JsonObject> {
  return new Promise((resolve, reject) => {
    let headerResolved = false;
    let failed = false;
    let childFailure: string | null = null;
    let lastBodySeq = 0;
    let stdoutBuffer = "";
    let stderr = "";
    const fail = (message: string, _exitCode: number | null) => {
      if (failed) {
        return;
      }
      failed = true;
      params.lifecycle.failed = true;
      void params.owner.terminate().catch((error: unknown) => {
        embeddedAgentLog.warn("codex sandbox http/request cleanup failed", { error });
      });
      if (headerResolved) {
        if (params.notifications.isOpen()) {
          params.notifications.send("http/request/bodyDelta", {
            requestId: params.requestId,
            seq: lastBodySeq + 1,
            deltaBase64: "",
            done: true,
            error: message,
          });
        }
        return;
      }
      reject(new Error(message));
    };
    params.child.stdout.setEncoding("utf8");
    params.child.stdout.on("data", (chunk: string) => {
      stdoutBuffer += chunk;
      let newline = stdoutBuffer.indexOf("\n");
      while (newline >= 0) {
        const line = stdoutBuffer.slice(0, newline).trim();
        stdoutBuffer = stdoutBuffer.slice(newline + 1);
        if (line) {
          try {
            const message = requireObject(JSON.parse(line) as JsonValue, "http stream message");
            const type = requireString(message.type, "http stream message type");
            if (type === "headers") {
              headerResolved = true;
              resolve({
                status: requireNumber(message.status, "http status"),
                headers: readHttpHeaders(message.headers),
                bodyBase64: "",
              });
            } else if (type === "bodyDelta") {
              const seq = requireNumber(message.seq, "http body sequence");
              lastBodySeq = Math.max(lastBodySeq, seq);
              if (params.notifications.isOpen()) {
                params.notifications.send("http/request/bodyDelta", {
                  requestId: params.requestId,
                  seq,
                  deltaBase64: typeof message.deltaBase64 === "string" ? message.deltaBase64 : "",
                  done: message.done === true,
                  error: typeof message.error === "string" ? message.error : null,
                });
              }
            }
          } catch (error) {
            fail(error instanceof Error ? error.message : String(error), null);
          }
        }
        newline = stdoutBuffer.indexOf("\n");
      }
      if (stdoutBuffer.length > SANDBOX_HTTP_STREAM_LINE_MAX_CHARS) {
        fail(
          `sandbox http/request produced an unterminated stdout line longer than ${SANDBOX_HTTP_STREAM_LINE_MAX_CHARS} characters`,
          null,
        );
      }
    });
    params.child.stderr.setEncoding("utf8");
    params.child.stderr.on("data", (chunk: string) => {
      stderr = sliceUtf16Safe(`${stderr}${chunk}`, -4096);
    });
    params.child.once("error", (error) => {
      // ChildProcess error can precede close while the helper is still alive.
      // Keep its backend lease until close provides the terminal exit state.
      childFailure ??= error.message;
      params.lifecycle.failed = true;
    });
    params.child.once("close", (code) => {
      const exitCode = code ?? 1;
      if (failed) {
        return;
      }
      if (childFailure) {
        fail(childFailure, exitCode);
        return;
      }
      if (exitCode === 0) {
        if (!headerResolved) {
          params.lifecycle.failed = true;
          reject(new Error("sandbox http/request exited before returning headers"));
        }
        return;
      }
      fail(stderr.trim() || `sandbox http/request failed with code ${exitCode}`, exitCode);
    });
  });
}

const SANDBOX_HTTP_REQUEST_SCRIPT = String.raw`
tmp=$(mktemp "$TMPDIR/openclaw-http.XXXXXX.py" 2>/dev/null || mktemp "/tmp/openclaw-http.XXXXXX.py") || exit 1
trap 'rm -f "$tmp"' EXIT
cat > "$tmp" <<'PY'
import base64
import json
import ipaddress
import socket
import sys
import urllib.error
import urllib.parse
import urllib.request

def emit(payload):
    print(json.dumps(payload, separators=(",", ":")), flush=True)

def response_headers(response):
    return [{"name": name, "value": value} for name, value in response.headers.items()]

BLOCKED_HOSTNAMES = {
    "localhost",
    "localhost.localdomain",
    "metadata.google.internal",
}
CLOUD_METADATA_IP_ADDRESSES = {
    "100.100.100.200",
    "fd00:ec2::254",
}
BLOCKED_IPV4_NETWORKS = tuple(
    ipaddress.ip_network(network)
    for network in (
        "100.64.0.0/10",
        "198.18.0.0/15",
    )
)
BLOCKED_IPV6_NETWORKS = tuple(
    ipaddress.ip_network(network)
    for network in (
        "100::/64",
        "2001:2::/48",
        "2001:20::/28",
        "2001:db8::/32",
        "fec0::/10",
    )
)
PINNED_ADDRESSES = {}

def normalize_hostname(hostname):
    return (hostname or "").strip("[]").rstrip(".").lower()

def is_blocked_hostname(hostname):
    normalized = normalize_hostname(hostname)
    return (
        normalized in BLOCKED_HOSTNAMES
        or normalized.endswith(".localhost")
        or normalized.endswith(".local")
        or normalized.endswith(".internal")
    )

def is_blocked_ip(address):
    try:
        parsed = ipaddress.ip_address(address)
    except ValueError:
        return False
    embedded_ipv4 = extract_embedded_ipv4(parsed)
    if embedded_ipv4 is not None and is_blocked_ip(str(embedded_ipv4)):
        return True
    if str(parsed).lower() in CLOUD_METADATA_IP_ADDRESSES:
        return True
    if isinstance(parsed, ipaddress.IPv4Address):
        if any(parsed in network for network in BLOCKED_IPV4_NETWORKS):
            return True
    else:
        if any(parsed in network for network in BLOCKED_IPV6_NETWORKS):
            return True
    return (
        parsed.is_loopback
        or parsed.is_private
        or parsed.is_link_local
        or parsed.is_multicast
        or parsed.is_reserved
        or parsed.is_unspecified
    )

def ipv4_from_int(value):
    return ipaddress.IPv4Address(value & 0xffffffff)

def extract_embedded_ipv4(address):
    if not isinstance(address, ipaddress.IPv6Address):
        return None
    if address.ipv4_mapped is not None:
        return address.ipv4_mapped
    value = int(address)
    hextets = [(value >> shift) & 0xffff for shift in range(112, -1, -16)]
    if hextets[:6] == [0, 0, 0, 0, 0, 0]:
        return ipv4_from_int(value)
    if hextets[:6] == [0x64, 0xff9b, 0, 0, 0, 0]:
        return ipv4_from_int(value)
    if hextets[:6] == [0x64, 0xff9b, 1, 0, 0, 0]:
        return ipv4_from_int(value)
    if hextets[0] == 0x2002:
        return ipv4_from_int((hextets[1] << 16) | hextets[2])
    if hextets[0] == 0x2001 and hextets[1] == 0:
        return ipv4_from_int(((hextets[6] << 16) | hextets[7]) ^ 0xffffffff)
    if (hextets[4] & 0xfcff) == 0 and hextets[5] == 0x5efe:
        return ipv4_from_int((hextets[6] << 16) | hextets[7])
    return None

def assert_url_allowed(url):
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("http/request only supports http and https URLs")
    hostname = normalize_hostname(parsed.hostname)
    if not hostname or is_blocked_hostname(hostname) or is_blocked_ip(hostname):
        raise ValueError("Blocked hostname or private/internal/special-use IP address")
    try:
        results = socket.getaddrinfo(hostname, parsed.port, proto=socket.IPPROTO_TCP)
    except socket.gaierror as error:
        raise ValueError(f"Unable to resolve hostname: {hostname}") from error
    addresses = {entry[4][0] for entry in results if entry[4]}
    if not addresses or any(is_blocked_ip(address) for address in addresses):
        raise ValueError("Blocked: resolves to private/internal/special-use IP address")
    PINNED_ADDRESSES[hostname] = sorted(addresses)

class GuardedRedirectHandler(urllib.request.HTTPRedirectHandler):
    # Python 3.9 lacks the 308 dispatch alias; use the same guarded redirect path.
    http_error_308 = urllib.request.HTTPRedirectHandler.http_error_302

    def __init__(self, redirect_policy):
        self.redirect_policy = redirect_policy

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if self.redirect_policy == "stop":
            return None
        assert_url_allowed(newurl)
        method = req.get_method()
        drop_body = code == 303 or (code in (301, 302) and method == "POST")
        next_headers = dict(req.headers)
        if drop_body:
            if method != "HEAD":
                method = "GET"
            for name in ("content-type", "content-length", "content-encoding", "transfer-encoding"):
                next_headers.pop(name.capitalize(), None)
        redirected = urllib.request.Request(
            newurl,
            data=None if drop_body else req.data,
            headers=next_headers,
            method=method,
            origin_req_host=req.origin_req_host,
            unverifiable=True,
        )
        previous = urllib.parse.urlsplit(req.full_url)
        target = urllib.parse.urlsplit(newurl)
        previous_port = previous.port or (443 if previous.scheme == "https" else 80)
        target_port = target.port or (443 if target.scheme == "https" else 80)
        if (previous.scheme, previous.hostname, previous_port) != (
            target.scheme, target.hostname, target_port
        ):
            # Match Codex's route-aware client: cross-origin hops never inherit secrets.
            for name in ("authorization", "cookie", "proxy-authorization", "www-authenticate", "cookie2"):
                redirected.remove_header(name.capitalize())
        return redirected

def pinned_getaddrinfo(original_getaddrinfo):
    def getaddrinfo(host, port, family=0, type=0, proto=0, flags=0):
        pinned = PINNED_ADDRESSES.get(normalize_hostname(host))
        if not pinned:
            return original_getaddrinfo(host, port, family, type, proto, flags)
        results = []
        for address in pinned:
            results.extend(original_getaddrinfo(address, port, family, type, proto, flags))
        return results
    return getaddrinfo

def handle_response(input_data, response):
    headers = response_headers(response)
    status = int(getattr(response, "status", getattr(response, "code", 0)))
    if input_data.get("streamResponse"):
        emit({"type": "headers", "status": status, "headers": headers})
        seq = 1
        while True:
            chunk = response.read(65536)
            if not chunk:
                break
            emit({
                "type": "bodyDelta",
                "seq": seq,
                "deltaBase64": base64.b64encode(chunk).decode("ascii"),
                "done": False,
            })
            seq += 1
        emit({"type": "bodyDelta", "seq": seq, "deltaBase64": "", "done": True})
        return
    body = response.read()
    emit({
        "status": status,
        "headers": headers,
        "bodyBase64": base64.b64encode(body).decode("ascii"),
    })

def main():
    input_data = json.load(sys.stdin)
    url = str(input_data.get("url", ""))
    assert_url_allowed(url)
    body_base64 = input_data.get("bodyBase64")
    data = base64.b64decode(body_base64) if isinstance(body_base64, str) else None
    request = urllib.request.Request(
        url,
        data=data,
        method=str(input_data.get("method", "GET")),
    )
    for header in input_data.get("headers") or []:
        request.add_header(str(header.get("name", "")), str(header.get("value", "")))
    timeout_ms = input_data.get("timeoutMs")
    timeout = None
    if isinstance(timeout_ms, (int, float)) and timeout_ms > 0:
        timeout = timeout_ms / 1000
    redirect_handler = GuardedRedirectHandler(input_data.get("redirectPolicy", "follow"))
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), redirect_handler)
    original_getaddrinfo = socket.getaddrinfo
    socket.getaddrinfo = pinned_getaddrinfo(original_getaddrinfo)
    try:
        with opener.open(request, timeout=timeout) as response:
            handle_response(input_data, response)
    except urllib.error.HTTPError as response:
        handle_response(input_data, response)
    finally:
        socket.getaddrinfo = original_getaddrinfo

if __name__ == "__main__":
    main()
