/**
 * JSON-RPC parsing, validation, and response helpers for the sandbox
 * transport-neutral exec-server protocol.
 */
import type { JsonObject, JsonValue } from "../protocol.js";
import type { CodexSandboxExecMessageTransport, HttpHeader, JsonRpcRequest } from "./types.js";

/** JSON-RPC error code used when a sandbox filesystem resource does not exist. */
export const JSON_RPC_NOT_FOUND = -32004;

/** JSON-RPC error code used when a sandbox exec-server method is unsupported. */
export const JSON_RPC_METHOD_NOT_FOUND = -32601;

/** Protocol-level error carrying the JSON-RPC error code to send to the client. */
export class JsonRpcProtocolError extends Error {
  constructor(
    readonly code: number,
    message: string,
  ) {
    super(message);
  }
}

/** Parses a normalized JSON message into a JSON-RPC request object. */
export function parseRequest(text: string): JsonRpcRequest {
  const parsed = JSON.parse(text) as unknown;
  return requireObject(parsed, "JSON-RPC request") as JsonRpcRequest;
}

/** Validates that a JSON value is a non-array object. */
export function requireObject(value: unknown, label: string): JsonObject {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} must be an object.`);
  }
  return value as JsonObject;
}

/** Validates a non-empty string JSON-RPC parameter. */
export function requireString(value: unknown, label: string): string {
  if (typeof value !== "string" || !value) {
    throw new Error(`${label} must be a non-empty string.`);
  }
  return value;
}

/** Validates a base64 payload parameter as a string; decoding happens at call sites. */
export function requireBase64String(value: unknown, label: string): string {
  if (typeof value !== "string") {
    throw new Error(`${label} must be a string.`);
  }
  return value;
}

/** Validates a finite numeric JSON-RPC parameter. */
export function requireNumber(value: unknown, label: string): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error(`${label} must be a finite number.`);
  }
  return value;
}

/** Validates a non-empty string-array JSON-RPC parameter. */
export function requireStringArray(value: unknown, label: string): string[] {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
    throw new Error(`${label} must be a string array.`);
  }
  if (value.length === 0) {
    throw new Error(`${label} must not be empty.`);
  }
  return value;
}

/** Reads HTTP headers from JSON-RPC params, defaulting to an empty header list. */
export function readHttpHeaders(value: unknown): HttpHeader[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.map((entry, index) => {
    const record = requireObject(entry as JsonValue, `header ${index}`);
    return {
      name: requireString(record.name, "header name"),
      value: requireString(record.value, "header value"),
    };
  });
}

/** Sends a JSON-RPC success response through the connection message sink. */
export function sendResult(
  send: CodexSandboxExecMessageTransport["send"],
  id: string | number,
  result: JsonValue,
): void {
  send({ jsonrpc: "2.0", id, result });
}

/** Sends a JSON-RPC error response through the connection message sink. */
export function sendError(
  send: CodexSandboxExecMessageTransport["send"],
  id: string | number | undefined,
  code: number,
  message: string,
): void {
  send({ jsonrpc: "2.0", id: id ?? null, error: { code, message } });
}

/** Converts Codex PathUri protocol values into sandbox-backend path strings. */
import { fileURLToPath } from "node:url";

const WINDOWS_DRIVE_PATH_RE = /^\/[A-Za-z]:(?:\/|$)/u;

/** Resolves one Codex exec-server PathUri into a POSIX sandbox path. */
export function resolveExecServerPath(rawPath: string, label: string): string {
  let pathUrl: URL;
  try {
    pathUrl = new URL(rawPath);
  } catch (error) {
    throw new Error(
      `${label} must be a valid file URI: ${error instanceof Error ? error.message : String(error)}`,
      { cause: error },
    );
  }
  if (pathUrl.protocol !== "file:") {
    throw new Error(
      `${label} URI must use the file scheme, received ${pathUrl.protocol.slice(0, -1)}.`,
    );
  }
  if (pathUrl.search || pathUrl.hash) {
    throw new Error(`${label} file URI must not include a query or fragment.`);
  }
  let resolved: string;
  try {
    // The URI names the sandbox target, so decode with POSIX rules even when
    // the Gateway host is Windows. Docker and SSH backends own POSIX workdirs.
    resolved = fileURLToPath(pathUrl, { windows: false });
  } catch (error) {
    throw new Error(
      `${label} file URI is not valid for the sandbox: ${error instanceof Error ? error.message : String(error)}`,
      { cause: error },
    );
  }
  if (WINDOWS_DRIVE_PATH_RE.test(resolved)) {
    // OpenClaw exec-server backends currently expose Docker/SSH POSIX paths.
    // Reject foreign drive URIs instead of silently rewriting their meaning.
    throw new Error(`${label} Windows file URI is not supported by the sandbox.`);
  }
  if (resolved.includes("\0")) {
    throw new Error(`${label} file URI must not contain a null byte.`);
  }
  return resolved;
}

/**
 * Manages subprocess lifecycle, streaming output buffers, stdin writes, and
 * termination for Codex sandbox exec-server process RPCs.
 */
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import { coerceErrorMessage } from "openclaw/plugin-sdk/error-runtime";
import { buildRemoteCommand, sanitizeEnvVars } from "openclaw/plugin-sdk/sandbox";
import type { JsonObject, JsonValue } from "../protocol.js";
import { resolveFsSandboxPolicy } from "./fs-policy.js";
import { requireObject, requireString, requireStringArray } from "./json-rpc.js";
import { resolveExecServerPath } from "./path-uri.js";
import { prepareSandboxChildExec, spawnSandboxChild } from "./sandbox-child.js";
import type { ManagedProcess, OpenClawExecServer, ProcessChunk } from "./types.js";

const ENV_KEY_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;
const RETAINED_PROCESS_OUTPUT_BYTES = 1024 * 1024;
const CLOSED_PROCESS_EVICTION_MS = 60_000;

/** Starts a sandbox-backed process and registers it in the connection-local process table. */
export async function startProcess(
  execServer: OpenClawExecServer,
  processes: Map<string, ManagedProcess>,
  notify: ManagedProcess["emitNotification"],
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "process/start params");
  const processId = requireString(record.processId, "processId");
  if (processes.has(processId)) {
    throw new Error(`process already exists: ${processId}`);
  }
  const argv = requireStringArray(record.argv, "argv");
  const cwd = resolveExecServerPath(requireString(record.cwd, "cwd"), "process cwd");
  rejectUnsupportedArg0(record.arg0);
  assertSupportedProcessSandbox(execServer, record);
  const env = readProcessEnv(record);
  const tty = record.tty === true;
  const pipeStdin = record.pipeStdin === true;
  const managed: ManagedProcess = {
    processId,
    chunks: [],
    retainedOutputBytes: 0,
    nextSeq: 1,
    exited: false,
    exitCode: null,
    closed: false,
    failure: null,
    tty,
    pipeStdin,
    terminationRequested: false,
    child: null,
    waiters: [],
    emitNotification: notify,
    evictProcess: () => {
      if (managed.evictionTimer) {
        return;
      }
      managed.evictionTimer = setTimeout(() => {
        if (processes.get(processId) === managed && managed.closed) {
          processes.delete(processId);
        }
      }, CLOSED_PROCESS_EVICTION_MS);
      managed.evictionTimer.unref?.();
    },
  };
  processes.set(processId, managed);
  const startPromise = runProcess(execServer, managed, { argv, cwd, env });
  managed.startPromise = startPromise;
  try {
    await startPromise;
  } catch (error) {
    processes.delete(processId);
    managed.failure = coerceErrorMessage(error);
    managed.exitCode = null;
    managed.exited = true;
    managed.closed = true;
    notifyProcessWaiters(managed);
    throw error;
  } finally {
    if (managed.startPromise === startPromise) {
      managed.startPromise = undefined;
    }
  }
  return { processId, sandboxType: "none" };
}

function assertSupportedProcessSandbox(execServer: OpenClawExecServer, record: JsonObject): void {
  if (record.networkProxy !== undefined && record.networkProxy !== null) {
    throw new Error("Codex sandbox exec-server network proxy launch is not supported.");
  }
  if (
    record.enforceManagedNetwork === true ||
    (record.managedNetwork !== undefined && record.managedNetwork !== null)
  ) {
    throw new Error(
      "Codex managed network restrictions cannot be enforced by the sandbox backend.",
    );
  }
  // Docker/SSH owns the outer sandbox; it cannot impose narrower Codex process-local policy.
  if (resolveFsSandboxPolicy(execServer, record)?.unrestricted === false) {
    throw new Error(
      "Codex process filesystem sandbox restrictions cannot be enforced by the backend.",
    );
  }
  if (record.sandbox === undefined || record.sandbox === null) {
    return;
  }
  const sandbox = requireObject(record.sandbox, "process sandbox context");
  const permissions = requireObject(sandbox.permissions, "process sandbox permissions");
  if (permissions.network !== "restricted") {
    return;
  }
  if (!execServer.networkIsolated) {
    throw new Error("Codex network restrictions cannot be enforced by the sandbox backend.");
  }
}

async function runProcess(
  execServer: OpenClawExecServer,
  managed: ManagedProcess,
  params: { argv: string[]; cwd: string; env: Record<string, string> },
): Promise<void> {
  const backend = execServer.backend;
  throwIfProcessStartCancelled(managed);
  const remoteExec = prepareSandboxChildExec(backend, params.env);
  const execSpec = await backend.buildExecSpec({
    command: buildRemoteCommand(params.argv),
    workdir: params.cwd,
    env: remoteExec.env,
    // This bridge currently owns only pipe-backed child processes. Asking the
    // backend for a PTY can produce commands such as `docker exec -t`, which
    // require this process itself to own a real TTY.
    usePty: false,
  });
  if (managed.terminationRequested) {
    await backend.finalizeExec?.({
      status: "failed",
      exitCode: null,
      timedOut: false,
      token: execSpec.finalizeToken,
    });
    throw new Error("process start cancelled");
  }
  const owner = await spawnSandboxChild({
    argv: execSpec.argv,
    env: execSpec.env,
    finalizeExec: backend.finalizeExec,
    finalizeToken: execSpec.finalizeToken,
    finalizeStatus: () => (managed.failure ? "failed" : "completed"),
    onFinalizeError: (error) => {
      const message = coerceErrorMessage(error);
      managed.failure ??= message;
      embeddedAgentLog.warn("codex sandbox exec-server finalize failed", {
        processId: managed.processId,
        error: message,
      });
    },
    owners: execServer.children,
    terminateRemote: remoteExec.terminate,
  });
  managed.child = owner;
  const child = owner.process;
  child.stdout.on("data", (chunk: Buffer) =>
    appendProcessChunk(managed, managed.tty ? "pty" : "stdout", chunk),
  );
  child.stderr.on("data", (chunk: Buffer) => appendProcessChunk(managed, "stderr", chunk));
  child.once("error", (error) => {
    // Node can report an abort or transport error before the child exits. The
    // backend lease and Codex terminal notifications stay owned until close.
    managed.failure ??= error.message;
    notifyProcessWaiters(managed);
  });
  child.once("close", (code) => {
    emitProcessClosed(managed, code ?? 1);
  });
  if (!managed.tty && !managed.pipeStdin) {
    child.stdin.end();
  }
}

function throwIfProcessStartCancelled(managed: ManagedProcess): void {
  if (managed.terminationRequested) {
    throw new Error("process start cancelled");
  }
}

function appendProcessChunk(
  managed: ManagedProcess,
  stream: ProcessChunk["stream"],
  data: Buffer,
): void {
  if (data.length === 0) {
    return;
  }
  const chunk = {
    seq: managed.nextSeq,
    stream,
    chunk: data.toString("base64"),
  };
  managed.chunks.push(chunk);
  managed.retainedOutputBytes += data.length;
  // Keep enough recent output for polling clients without letting long-running
  // processes grow the app-server bridge memory without bound.
  while (managed.retainedOutputBytes > RETAINED_PROCESS_OUTPUT_BYTES && managed.chunks.length > 1) {
    const removed = managed.chunks.shift();
    if (!removed) {
      break;
    }
    managed.retainedOutputBytes -= Buffer.from(removed.chunk, "base64").byteLength;
  }
  managed.nextSeq += 1;
  managed.emitNotification("process/output", {
    processId: managed.processId,
    seq: chunk.seq,
    stream: chunk.stream,
    chunk: chunk.chunk,
  });
  notifyProcessWaiters(managed);
}

function emitProcessClosed(managed: ManagedProcess, exitCode: number | null): void {
  if (!managed.exited) {
    const exitSeq = managed.nextSeq;
    managed.nextSeq += 1;
    managed.exitCode = exitCode;
    managed.exited = true;
    if (exitCode !== null) {
      managed.emitNotification("process/exited", {
        processId: managed.processId,
        seq: exitSeq,
        exitCode,
      });
    }
  }
  if (!managed.closed) {
    const closeSeq = managed.nextSeq;
    managed.nextSeq += 1;
    managed.closed = true;
    managed.emitNotification("process/closed", {
      processId: managed.processId,
      seq: closeSeq,
    });
  }
  // Closed processes stay briefly readable so clients that observe close before
  // their final poll can still drain exit/output state.
  managed.evictProcess();
  notifyProcessWaiters(managed);
}

function limitProcessChunks(chunks: ProcessChunk[], maxBytes: number | undefined): ProcessChunk[] {
  if (!maxBytes) {
    return chunks;
  }
  const retained: ProcessChunk[] = [];
  let retainedBytes = 0;
  for (const chunk of chunks) {
    const byteLength = Buffer.from(chunk.chunk, "base64").byteLength;
    if (retained.length > 0 && retainedBytes + byteLength > maxBytes) {
      break;
    }
    retained.push(chunk);
    retainedBytes += byteLength;
    if (retainedBytes >= maxBytes) {
      break;
    }
  }
  return retained;
}

/** Reads buffered process output, optionally waiting for new output or process close. */
export async function readProcess(
  processes: Map<string, ManagedProcess>,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "process/read params");
  const processId = requireString(record.processId, "processId");
  const managed = requireProcess(processes, processId);
  const afterSeq = typeof record.afterSeq === "number" ? record.afterSeq : 0;
  const waitMs = typeof record.waitMs === "number" && record.waitMs > 0 ? record.waitMs : 0;
  if (!managed.exited && !hasChunksAtOrAfter(managed, afterSeq) && waitMs > 0) {
    await waitForProcessUpdate(managed, waitMs);
  }
  const chunks = limitProcessChunks(
    managed.chunks.filter((chunk) => chunk.seq > afterSeq),
    typeof record.maxBytes === "number" && record.maxBytes > 0 ? record.maxBytes : undefined,
  );
  const lastChunk = chunks.at(-1);
  return {
    chunks,
    nextSeq: lastChunk ? lastChunk.seq + 1 : managed.nextSeq,
    exited: managed.exited,
    exitCode: managed.exitCode,
    closed: managed.closed,
    failure: managed.failure,
  };
}

/** Writes base64 stdin data to a running process when stdin is still open. */
export function writeProcess(
  processes: Map<string, ManagedProcess>,
  params: JsonValue | undefined,
): JsonObject {
  const record = requireObject(params, "process/write params");
  const processId = requireString(record.processId, "processId");
  const managed = processes.get(processId);
  if (!managed) {
    return { status: "unknownProcess" };
  }
  const chunk = Buffer.from(requireString(record.chunk, "chunk"), "base64");
  if (
    (!managed.tty && !managed.pipeStdin) ||
    managed.closed ||
    !managed.child?.process.stdin.writable
  ) {
    return { status: "stdinClosed" };
  }
  managed.child.process.stdin.write(chunk);
  return { status: "accepted" };
}

/** Requests process termination and reports whether it was running at call time. */
export async function terminateProcess(
  processes: Map<string, ManagedProcess>,
  params: JsonValue | undefined,
): Promise<JsonObject> {
  const record = requireObject(params, "process/terminate params");
  const processId = requireString(record.processId, "processId");
  const managed = processes.get(processId);
  if (!managed) {
    return { running: false };
  }
  const running = !managed.exited;
  managed.terminationRequested = true;
  await managed.startPromise?.catch(() => undefined);
  if (managed.child) {
    await managed.child.terminate();
  } else if (running && !managed.closed) {
    emitProcessClosed(managed, null);
  }
  return { running };
}

function waitForProcessUpdate(managed: ManagedProcess, waitMs: number): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(done, Math.min(waitMs, 30_000));
    function done() {
      clearTimeout(timer);
      managed.waiters = managed.waiters.filter((waiter) => waiter !== done);
      resolve();
    }
    managed.waiters.push(done);
  });
}

function notifyProcessWaiters(managed: ManagedProcess): void {
  const waiters = managed.waiters;
  managed.waiters = [];
  for (const waiter of waiters) {
    waiter();
  }
}

function hasChunksAtOrAfter(managed: ManagedProcess, afterSeq: number): boolean {
  return managed.chunks.some((chunk) => chunk.seq > afterSeq);
}

function requireProcess(processes: Map<string, ManagedProcess>, processId: string): ManagedProcess {
  const managed = processes.get(processId);
  if (!managed) {
    throw new Error(`unknown process: ${processId}`);
  }
  return managed;
}

function rejectUnsupportedArg0(value: unknown): void {
  if (value === undefined || value === null) {
    return;
  }
  if (typeof value === "string") {
    throw new Error("Codex sandbox exec-server does not support arg0 overrides.");
  }
  throw new Error("arg0 must be a string or null.");
}

function readEnv(value: unknown): Record<string, string> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }
  const env: Record<string, string> = {};
  for (const [key, rawValue] of Object.entries(value)) {
    if (typeof rawValue === "string" && ENV_KEY_RE.test(key)) {
      env[key] = rawValue;
    }
  }
  return env;
}

function readProcessEnv(record: JsonObject): Record<string, string> {
  const policyEnv = buildEnvFromPolicy(record.envPolicy);
  const requestedEnv = {
    ...policyEnv,
    ...readEnv(record.env),
  };
  // Codex inherits its app-server's full environment by default. Scrub again at
  // this last boundary so no credential can cross into any sandbox backend.
  return sanitizeEnvVars(requestedEnv).allowed;
}

function buildEnvFromPolicy(value: unknown): Record<string, string> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }
  const policy = value as Record<string, unknown>;
  const inheritedEnv = readEnv(policy.set);
  const includeOnly = readStringList(policy.includeOnly);
  if (includeOnly.length > 0) {
    filterEnvKeys(inheritedEnv, includeOnly, true);
  }
  return inheritedEnv;
}

function filterEnvKeys(
  env: Record<string, string>,
  patterns: string[],
  keepMatches: boolean,
): void {
  if (patterns.length === 0) {
    return;
  }
  const regexes = patterns.map((pattern) => wildcardPatternToRegex(pattern));
  for (const key of Object.keys(env)) {
    const matches = regexes.some((regex) => regex.test(key));
    if (matches !== keepMatches) {
      delete env[key];
    }
  }
}

function wildcardPatternToRegex(pattern: string): RegExp {
  const escaped = pattern.replace(/[.+^${}()|[\]\\]/gu, "\\$&");
  return new RegExp(`^${escaped.replaceAll("*", ".*").replaceAll("?", ".")}$`, "iu");
}

function readStringList(value: unknown): string[] {
  return Array.isArray(value)
    ? value.filter((entry): entry is string => typeof entry === "string")
    : [];
}

/** Owns one sandbox subprocess tree through close, reaping, and backend finalization. */
import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { randomUUID } from "node:crypto";
import { killProcessTree } from "openclaw/plugin-sdk/process-runtime";
import type { SandboxContext } from "openclaw/plugin-sdk/sandbox";

const SANDBOX_CHILD_TERM_GRACE_MS = 1_000;
// Covers the post-TERM tree kill plus Windows taskkill completion before failure is reported.
const SANDBOX_CHILD_REAP_TIMEOUT_MS = 4_500;
const SANDBOX_EXEC_MARKER = "CODEX_SANDBOX_EXEC_ID";

type SandboxChildOutcome = { exitCode: number; signal: NodeJS.Signals | null };

export type SandboxChildOwner = {
  process: ChildProcessWithoutNullStreams;
  settled: Promise<SandboxChildOutcome>;
  terminate: () => Promise<SandboxChildOutcome>;
};

export async function spawnSandboxChild(params: {
  argv: string[];
  env: NodeJS.ProcessEnv;
  finalizeExec?: NonNullable<SandboxContext["backend"]>["finalizeExec"];
  finalizeToken?: unknown;
  finalizeStatus: (outcome: SandboxChildOutcome) => "completed" | "failed";
  onFinalizeError: (error: unknown) => void;
  owners: Set<SandboxChildOwner>;
  terminateRemote?: () => Promise<void>;
}): Promise<SandboxChildOwner> {
  const [command, ...args] = params.argv;
  const finalize = async (status: "completed" | "failed", exitCode: number | null) =>
    await params.finalizeExec?.({
      status,
      exitCode,
      timedOut: false,
      token: params.finalizeToken,
    });
  if (!command) {
    await finalize("failed", null).catch(params.onFinalizeError);
    throw new Error("OpenClaw sandbox exec spec did not provide a command.");
  }
  let child: ChildProcessWithoutNullStreams;
  try {
    child = spawn(command, args, {
      detached: process.platform !== "win32",
      env: params.env,
      stdio: ["pipe", "pipe", "pipe"],
    });
  } catch (error) {
    await finalize("failed", null).catch(params.onFinalizeError);
    throw error;
  }

  let outcome: SandboxChildOutcome | undefined;
  const closed = new Promise<SandboxChildOutcome>((resolve) => {
    child.once("close", (code, signal) => resolve((outcome = { exitCode: code ?? 1, signal })));
  });
  let finalizePromise: Promise<void> | undefined;
  let terminationCleanup: Promise<void> | undefined;
  let terminationError: Error | undefined;
  const settled = closed.then(async (result) => {
    await terminationCleanup;
    child.stdin.destroy();
    await (finalizePromise ??= finalize(params.finalizeStatus(result), result.exitCode));
    return result;
  });
  void settled.catch(params.onFinalizeError);

  let terminationPromise: Promise<SandboxChildOutcome> | undefined;
  const owner: SandboxChildOwner = {
    process: child,
    settled,
    terminate: () =>
      (terminationPromise ??= (async () => {
        child.stdin.destroy();
        terminationCleanup = params.terminateRemote?.().catch((error: unknown) => {
          terminationError = error instanceof Error ? error : new Error(String(error));
        });
        await terminationCleanup;
        if (!outcome) {
          if (child.pid) {
            killProcessTree(child.pid, {
              detached: process.platform !== "win32",
              graceMs: SANDBOX_CHILD_TERM_GRACE_MS,
            });
          } else {
            child.kill("SIGTERM");
          }
          const reaped = await Promise.race([
            closed.then(() => true),
            delay(SANDBOX_CHILD_REAP_TIMEOUT_MS).then(() => false),
          ]);
          if (!reaped) {
            throw new Error(
              `Sandbox child process tree ${child.pid ?? "unknown"} survived SIGKILL; tear down the sandbox environment and inspect the surviving process tree before retrying.`,
            );
          }
        }
        const result = await settled;
        if (terminationError) {
          throw terminationError;
        }
        return result;
      })()),
  };
  params.owners.add(owner);
  void settled.then(
    () => params.owners.delete(owner),
    () => params.owners.delete(owner),
  );
  return owner;
}

export function prepareSandboxChildExec(
  backend: NonNullable<SandboxContext["backend"]>,
  env: Record<string, string>,
): { env: Record<string, string>; terminate: () => Promise<void> } {
  const marker = randomUUID();
  return {
    env: { ...env, [SANDBOX_EXEC_MARKER]: marker },
    terminate: async () => {
      const result = await backend.runShellCommand({
        script: SANDBOX_REMOTE_TERMINATE_SCRIPT,
        args: [`${SANDBOX_EXEC_MARKER}=${marker}`],
        allowFailure: true,
        signal: AbortSignal.timeout(SANDBOX_CHILD_REAP_TIMEOUT_MS),
      });
      if (result.code !== 0) {
        const detail =
          result.stderr.toString("utf8").trim() || result.stdout.toString("utf8").trim();
        throw new Error(
          detail ||
            `Sandbox process tree cleanup failed with code ${result.code}; tear down the sandbox environment and inspect surviving processes before retrying.`,
        );
      }
    },
  };
}

const SANDBOX_REMOTE_TERMINATE_SCRIPT = String.raw`
find_owned_pids() {
  for env_file in /proc/[0-9]*/environ; do
    if [ -r "$env_file" ] && tr '\0' '\n' < "$env_file" 2>/dev/null | grep -Fqx "$1"; then
      basename "$(dirname "$env_file")"
    fi
  done
}
owned="$(find_owned_pids "$1")"
[ -z "$owned" ] || kill -TERM $owned 2>/dev/null || true
sleep 1
owned="$(find_owned_pids "$1")"
[ -z "$owned" ] || kill -KILL $owned 2>/dev/null || true
sleep 1
owned="$(find_owned_pids "$1")"
[ -z "$owned" ] || { echo "Sandbox process IDs survived SIGKILL: $owned" >&2; exit 1; }
`.trim();

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(resolve, ms);
    timer.unref?.();
  });
}

/** Owns the JSON-RPC protocol and resources of one sandbox execution connection. */
import { randomUUID } from "node:crypto";
import { pathToFileURL } from "node:url";
import type { JsonValue } from "../protocol.js";
import {
  closeAllFileReads,
  closeFile,
  copyPath,
  createDirectory,
  getMetadata,
  openFile,
  readDirectory,
  readFile,
  readFileBlock,
  removePath,
  writeFile,
  type CodexSandboxFileReadHandles,
} from "./filesystem.js";
import { httpRequest } from "./http.js";
import {
  JSON_RPC_METHOD_NOT_FOUND,
  JsonRpcProtocolError,
  sendError,
  sendResult,
} from "./json-rpc.js";
import { readProcess, startProcess, terminateProcess, writeProcess } from "./processes.js";
import type {
  CodexSandboxExecMessageTransport,
  CodexSandboxExecSessionNotifications,
  JsonRpcRequest,
  ManagedProcess,
  OpenClawExecServer,
} from "./types.js";

/** Connection-local execution state; closing it never enables session resumption. */
export class CodexSandboxExecSession {
  private readonly processes = new Map<string, ManagedProcess>();
  private readonly fileReads: CodexSandboxFileReadHandles = new Map();
  private readonly closeController = new AbortController();
  private readonly notifications: CodexSandboxExecSessionNotifications;
  private cleanup?: Promise<void>;

  constructor(
    private readonly execServer: OpenClawExecServer,
    private readonly transport: CodexSandboxExecMessageTransport,
  ) {
    this.notifications = {
      isOpen: transport.isOpen,
      signal: this.closeController.signal,
      send: (method, params) => {
        if (transport.isOpen()) {
          transport.send({ jsonrpc: "2.0", method, params });
        }
      },
    };
  }

  async handleRequest(request: JsonRpcRequest): Promise<void> {
    const method = request.method;
    if (!method) {
      sendError(this.transport.send, request.id, -32600, "Invalid Request");
      return;
    }
    if (request.id === undefined) {
      if (method !== "initialized") {
        sendError(this.transport.send, -1, -32600, `Unexpected notification: ${method}`);
      }
      return;
    }
    try {
      const result = await this.dispatchRequest(method, request.params);
      sendResult(this.transport.send, request.id, result);
    } catch (error) {
      sendError(
        this.transport.send,
        request.id,
        error instanceof JsonRpcProtocolError ? error.code : -32603,
        error instanceof Error ? error.message : String(error),
      );
    }
  }

  close(): Promise<void> {
    if (!this.cleanup) {
      // Abort streamed HTTP and file reservations before reaping connection-owned processes.
      this.closeController.abort();
      closeAllFileReads(this.fileReads);
      this.cleanup = Promise.all(
        [...this.processes.keys()].map(async (processId) =>
          terminateProcess(this.processes, { processId }),
        ),
      ).then(() => undefined);
    }
    return this.cleanup;
  }

  private async dispatchRequest(method: string, params?: JsonValue): Promise<JsonValue> {
    switch (method) {
      case "initialize":
        return { sessionId: randomUUID() };
      case "environment/info":
        // Shell and cwd describe the sandbox target, never the Gateway host.
        return {
          shell: { name: "sh", path: "/bin/sh" },
          cwd: pathToFileURL(this.execServer.sandbox.containerWorkdir, { windows: false }).href,
          capabilities: { networkProxyLaunch: false },
        };
      case "environment/status":
        return { status: "ready" };
      // Registered exec-server URLs use these process methods, not app-server process/spawn.
      case "process/start":
        return startProcess(this.execServer, this.processes, this.notifications.send, params);
      case "process/read":
        return await readProcess(this.processes, params);
      case "process/write":
        return writeProcess(this.processes, params);
      case "process/terminate":
        return await terminateProcess(this.processes, params);
      case "fs/open":
        return await openFile(this.execServer, this.fileReads, params);
      case "fs/readBlock":
        return readFileBlock(this.fileReads, params);
      case "fs/close":
        return closeFile(this.fileReads, params);
      case "fs/readFile":
        return await readFile(this.execServer, params);
      case "fs/writeFile":
        await writeFile(this.execServer, params);
        return {};
      case "fs/createDirectory":
        await createDirectory(this.execServer, params);
        return {};
      case "fs/getMetadata":
        return await getMetadata(this.execServer, params);
      case "fs/readDirectory":
        return await readDirectory(this.execServer, params);
      case "fs/remove":
        await removePath(this.execServer, params);
        return {};
      case "fs/copy":
        await copyPath(this.execServer, params);
        return {};
      case "http/request":
        return await httpRequest(this.execServer, this.notifications, params);
      default:
        throw new JsonRpcProtocolError(
          JSON_RPC_METHOD_NOT_FOUND,
          `Unsupported OpenClaw sandbox exec-server method: ${method}`,
        );
    }
  }
}

/**
 * Shared protocol and runtime state types for the Codex sandbox exec-server
 * transport-neutral execution session.
 */
import type { PluginRuntime } from "openclaw/plugin-sdk/plugin-runtime";
import type { SandboxContext } from "openclaw/plugin-sdk/sandbox";
import type { JsonObject, JsonValue } from "../protocol.js";
import type { SandboxChildOwner } from "./sandbox-child.js";

/** Minimal JSON-RPC request shape accepted by the sandbox exec-server. */
export type JsonRpcRequest = {
  id?: string | number;
  method?: string;
  params?: JsonValue;
};

/** Narrow JSON-RPC message sink for one connection-owned execution session. */
export type CodexSandboxExecMessageTransport = {
  send: (message: JsonObject) => void;
  isOpen: () => boolean;
};

/** Notification delivery and lifetime owned by one execution session. */
export type CodexSandboxExecSessionNotifications = {
  send: (method: string, params: JsonObject) => void;
  isOpen: () => boolean;
  signal: AbortSignal;
};

/** Buffered process output chunk retained for polling and stream replay. */
export type ProcessChunk = {
  seq: number;
  stream: "stdout" | "stderr" | "pty";
  chunk: string;
};

/** Directory entry metadata returned through the sandbox filesystem bridge. */
export type DirectoryEntry = {
  fileName: string;
  isDirectory: boolean;
  isFile: boolean;
};

/** Access level granted by resolved sandbox filesystem policy. */
export type FsAccessMode = "read" | "write" | "none";

/** Normalized filesystem sandbox policy entry, either literal path or glob matcher. */
export type ResolvedFsSandboxEntry =
  | {
      kind: "path";
      path: string;
      access: FsAccessMode;
    }
  | {
      kind: "glob";
      pattern: string;
      matcher: RegExp;
      literalPrefix: string;
      access: FsAccessMode;
    };

/** Fully resolved filesystem sandbox policy for one exec-server environment. */
export type ResolvedFsSandboxPolicy = {
  unrestricted: boolean;
  entries: ResolvedFsSandboxEntry[];
};

/** Header pair accepted by sandboxed HTTP requests. */
export type HttpHeader = {
  name: string;
  value: string;
};

/** Runtime state for one process launched through the sandbox exec-server. */
export type ManagedProcess = {
  processId: string;
  chunks: ProcessChunk[];
  retainedOutputBytes: number;
  nextSeq: number;
  exited: boolean;
  exitCode: number | null;
  closed: boolean;
  failure: string | null;
  tty: boolean;
  pipeStdin: boolean;
  terminationRequested: boolean;
  child: SandboxChildOwner | null;
  startPromise?: Promise<void>;
  evictionTimer?: ReturnType<typeof setTimeout>;
  waiters: Array<() => void>;
  emitNotification: (method: string, params: JsonObject) => void;
  evictProcess: () => void;
};

/** Common loopback server and lease ownership shared by both execution transports. */
type OpenClawExecServerLease = {
  environmentId: string;
  authPath: string;
  refCount: number;
  closed: boolean;
  url: string;
  sandbox: SandboxContext;
  server: {
    clients: Iterable<{ close: (code?: number, reason?: string) => void }>;
    close: (callback: (error?: Error) => void) => void;
  };
  children: Set<SandboxChildOwner>;
  cleanupTasks: Set<Promise<void>>;
};

/** Locally interpreted exec-server protocol backed by an OpenClaw sandbox. */
export type OpenClawExecServer = OpenClawExecServerLease & {
  backend: NonNullable<SandboxContext["backend"]>;
  fsBridge: NonNullable<SandboxContext["fsBridge"]>;
  readonly networkIsolated: boolean;
};

/** One pre-authorized, single-use Codex stdio connection. */
export type CodexNodeExecServerLease = {
  id: string;
  channel: Awaited<ReturnType<PluginRuntime["nodes"]["openDuplex"]>>;
  claimed: boolean;
  closed: boolean;
  closeRelay?: () => void;
  onDisconnected?: (error: Error) => void;
  onChannelClosed?: (result: { failed: boolean; error?: unknown }) => void;
};

/** Opaque exec-server relay backed by the exact prepared paired-device placement. */
export type OpenClawNodeExecServer = OpenClawExecServerLease & {
  node: {
    id: string;
    leases: Map<string, CodexNodeExecServerLease>;
  };
};

/** One canonical loopback/refcount owner with either local or node connection handling. */
export type OpenClawLeasedExecServer = OpenClawExecServer | OpenClawNodeExecServer;

