/** Reads model context separately from full-fidelity Codex mirror evidence. */
import fs from "node:fs/promises";
import type { AgentMessage } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { SessionEntry } from "openclaw/plugin-sdk/agent-sessions";
import {
  buildSessionContext,
  migrateSessionEntries,
  parseSessionEntries,
  SessionManager,
} from "openclaw/plugin-sdk/agent-sessions";
import {
  getSessionEntry,
  parseSqliteSessionFileMarker,
  resolveTranscriptSessionKeyBySessionId,
  type SqliteSessionFileMarker,
} from "openclaw/plugin-sdk/session-store-runtime";
import type {
  TranscriptTurnAdmission,
  SessionTranscriptTargetParams,
} from "openclaw/plugin-sdk/session-transcript-runtime";
import { isRecord } from "openclaw/plugin-sdk/string-coerce-runtime";
import { sanitizeCodexHistoryImagePayloads } from "./image-payload-sanitizer.js";

type CodexHistoryView = "native-evidence" | "model-context";
export type CodexMirroredSessionHistoryTarget = {
  agentId?: string;
  sessionFile: string;
  sessionId: string;
  sessionKey?: string;
  sessionTarget?: Partial<SessionTranscriptTargetParams>;
};

/** Returns sanitized session-context messages for consumers that need an owned array. */
export async function readCodexMirroredSessionHistoryMessages(
  target: CodexMirroredSessionHistoryTarget,
  admission?: TranscriptTurnAdmission,
  view: CodexHistoryView = "native-evidence",
): Promise<AgentMessage[] | undefined> {
  return readCodexMirroredSessionHistory(
    target,
    (messages) => Array.from(messages),
    admission,
    view,
  );
}

/** The synchronous consumer can reject before further SQLite message payloads are acquired. */
export async function readCodexMirroredSessionHistory<T>(
  target: CodexMirroredSessionHistoryTarget,
  read: (messages: Iterable<AgentMessage>) => T,
  admission?: TranscriptTurnAdmission,
  view: CodexHistoryView = "native-evidence",
): Promise<T | undefined> {
  const consume = (
    messages: Iterable<AgentMessage>,
    header: unknown,
    imageLabel = "codex mirrored history",
  ): T | undefined => {
    // Foreign or absent headers are empty history; malformed session headers are read failures.
    if (!isRecord(header) || header.type !== "session") {
      return read([]);
    }
    if (typeof header.id !== "string") {
      return undefined;
    }
    if (header.id !== target.sessionId) {
      return read([]);
    }
    return read(
      (function* () {
        for (const message of messages) {
          yield sanitizeCodexHistoryImagePayloads(message, imageLabel);
        }
      })(),
    );
  };
  const readTarget = (
    transcriptTarget: Required<
      Pick<SessionTranscriptTargetParams, "agentId" | "sessionId" | "sessionKey" | "storePath">
    >,
  ) => {
    if (view === "native-evidence") {
      return SessionManager.readSessionContext(transcriptTarget, consume, { admission });
    }
    const loaded = SessionManager.openModelContext(transcriptTarget, { admission });
    return consume(
      loaded.buildSessionContext().messages,
      loaded.getHeader(),
      "codex mirrored model context",
    );
  };
  try {
    if (target.sessionTarget) {
      const { agentId, sessionId, sessionKey, storePath } = target.sessionTarget;
      if (
        !agentId ||
        !sessionId ||
        !sessionKey ||
        !storePath ||
        sessionId !== target.sessionId ||
        (target.agentId !== undefined && agentId !== target.agentId) ||
        (target.sessionKey !== undefined && sessionKey !== target.sessionKey)
      ) {
        return read([]);
      }
      return readTarget({ agentId, sessionId, sessionKey, storePath });
    }
    const sqliteMarker = parseSqliteSessionFileMarker(target.sessionFile);
    if (sqliteMarker) {
      if (
        sqliteMarker.sessionId !== target.sessionId ||
        (target.agentId !== undefined && sqliteMarker.agentId !== target.agentId)
      ) {
        return read([]);
      }
      const sessionKey = resolveSqliteMarkerSessionKey(target, sqliteMarker);
      if (!sessionKey) {
        return read([]);
      }
      return readTarget({
        agentId: sqliteMarker.agentId,
        sessionId: sqliteMarker.sessionId,
        sessionKey,
        storePath: sqliteMarker.storePath,
      });
    }
    if (admission) {
      if (
        admission.sessionId !== target.sessionId ||
        (target.agentId !== undefined && admission.agentId !== target.agentId) ||
        (target.sessionKey !== undefined && admission.sessionKey !== target.sessionKey)
      ) {
        return read([]);
      }
      return readTarget({
        agentId: admission.agentId,
        sessionId: admission.sessionId,
        sessionKey: admission.sessionKey,
        storePath: admission.storePath,
      });
    }
    // File-only callers retain the legacy import codec; runtime identities never read this path.
    const entries = parseSessionEntries(await fs.readFile(target.sessionFile, "utf-8"));
    return consume(
      (function* () {
        migrateSessionEntries(entries);
        const sessionEntries = entries.filter(
          (entry): entry is SessionEntry => isRecord(entry) && entry.type !== "session",
        );
        yield* buildSessionContext(sessionEntries).messages;
      })(),
      entries[0],
    );
  } catch (error) {
    // A new session can be read before its transcript exists; other failures still warn.
    if (isRecord(error) && error.code === "ENOENT") {
      return read([]);
    }
    return undefined;
  }
}

function resolveSqliteMarkerSessionKey(
  target: CodexMirroredSessionHistoryTarget,
  marker: SqliteSessionFileMarker,
): string | undefined {
  const explicitSessionKey = target.sessionKey?.trim();
  if (explicitSessionKey) {
    // The SDK exact-entry accessor uses a read-only database handle.
    const explicitEntry = getSessionEntry({
      agentId: marker.agentId,
      sessionKey: explicitSessionKey,
      storePath: marker.storePath,
    });
    if (explicitEntry) {
      return explicitEntry.sessionId === marker.sessionId ? explicitSessionKey : undefined;
    }
  }
  return resolveTranscriptSessionKeyBySessionId({
    agentId: marker.agentId,
    sessionId: marker.sessionId,
    storePath: marker.storePath,
  });
}

import { describe, expect, it } from "vitest";
import type { CodexAppServerRuntimeOptions, CodexPluginConfig } from "./config.js";
import {
  applyCodexSessionPermissionPolicy,
  resolveCodexEffectiveSessionPermissionPolicy,
  resolveCodexSessionPermissionCwd,
} from "./session-permission-policy.js";

const pluginConfig: CodexPluginConfig = {};
const defaultRoot = "/workspace";

function appServer(): CodexAppServerRuntimeOptions {
  return {
    start: { transport: "stdio", command: "codex", args: ["app-server"], headers: {} },
    connectionClass: "local-loopback",
    remoteAppsSubstrate: "preconfigured",
    codeModeOnly: false,
    loopDetectionPreToolUseRelay: true,
    requestTimeoutMs: 60_000,
    turnCompletionIdleTimeoutMs: 60_000,
    approvalPolicy: "never",
    approvalsReviewer: "user",
    sandbox: "danger-full-access",
  };
}

describe("Codex session permission policy", () => {
  it.each([
    {
      mode: "read-only" as const,
      sandbox: "read-only",
      approvalPolicy: "on-request",
      approvalsReviewer: "user",
    },
    {
      mode: "guarded" as const,
      sandbox: "workspace-write",
      approvalPolicy: "on-request",
      approvalsReviewer: "user",
    },
    {
      mode: "workspace" as const,
      sandbox: "workspace-write",
      approvalPolicy: "on-request",
      approvalsReviewer: "auto_review",
    },
    {
      mode: "full" as const,
      sandbox: "danger-full-access",
      approvalPolicy: "never",
      approvalsReviewer: "user",
    },
  ])("maps $mode to one complete app-server tuple", (expected) => {
    const resolved = applyCodexSessionPermissionPolicy({
      appServer: appServer(),
      permissionMode: expected.mode,
      sessionRoot: "/workspace/project",
      defaultRoot,
      pluginConfig,
      canUseAutoReview: true,
    });

    expect(resolved).toMatchObject({
      sandbox: expected.sandbox,
      approvalPolicy: expected.approvalPolicy,
      approvalsReviewer: expected.approvalsReviewer,
      sessionRoot: "/workspace/project",
    });
  });

  it("downgrades workspace review to the user when model-backed review is untrusted", () => {
    expect(
      applyCodexSessionPermissionPolicy({
        appServer: appServer(),
        permissionMode: "workspace",
        sessionRoot: "/workspace/project",
        defaultRoot,
        pluginConfig,
        canUseAutoReview: false,
      }).approvalsReviewer,
    ).toBe("user");
  });

  it("atomically downgrades a disallowed full tuple to guardian requirements", () => {
    const resolved = applyCodexSessionPermissionPolicy({
      appServer: appServer(),
      permissionMode: "full",
      sessionRoot: "/workspace/project",
      defaultRoot,
      pluginConfig,
      canUseAutoReview: true,
      requirementsToml: [
        'allowed_sandbox_modes = ["workspace-write"]',
        'allowed_approval_policies = ["on-request"]',
        'allowed_approvals_reviewers = ["auto_review"]',
      ].join("\n"),
    });

    expect(resolved).toMatchObject({
      sandbox: "workspace-write",
      approvalPolicy: "on-request",
      approvalsReviewer: "auto_review",
    });
  });

  it.each([
    {
      mode: "guarded" as const,
      policies: ["untrusted"],
      approvalsReviewer: "user",
    },
    {
      mode: "workspace" as const,
      policies: ["untrusted", "never"],
      approvalsReviewer: "auto_review",
    },
  ])("preserves managed prompting approval for a $mode session", (expected) => {
    const resolved = applyCodexSessionPermissionPolicy({
      appServer: appServer(),
      permissionMode: expected.mode,
      sessionRoot: "/workspace/project",
      defaultRoot,
      pluginConfig,
      canUseAutoReview: true,
      requirementsToml: `allowed_approval_policies = [${expected.policies
        .map((policy) => `"${policy}"`)
        .join(", ")}]`,
    });

    expect(resolved).toMatchObject({
      sandbox: "workspace-write",
      approvalPolicy: "untrusted",
      approvalsReviewer: expected.approvalsReviewer,
    });
  });

  it.each([
    {
      mode: "read-only" as const,
      allowedSandbox: "workspace-write",
    },
    {
      mode: "read-only" as const,
      allowedSandbox: "danger-full-access",
    },
    {
      mode: "guarded" as const,
      allowedSandbox: "danger-full-access",
    },
    {
      mode: "workspace" as const,
      allowedSandbox: "danger-full-access",
    },
  ])("never widens $mode access to the managed $allowedSandbox sandbox", (params) => {
    expect(() =>
      applyCodexSessionPermissionPolicy({
        appServer: appServer(),
        permissionMode: params.mode,
        sessionRoot: "/workspace/project",
        defaultRoot,
        pluginConfig,
        canUseAutoReview: true,
        requirementsToml: `allowed_sandbox_modes = ["${params.allowedSandbox}"]`,
      }),
    ).toThrow(
      `Codex session permission mode=${params.mode} cannot satisfy managed sandbox requirements`,
    );
  });

  it("lets managed requirements further restrict a guarded session to read-only", () => {
    expect(
      applyCodexSessionPermissionPolicy({
        appServer: appServer(),
        permissionMode: "guarded",
        sessionRoot: "/workspace/project",
        defaultRoot,
        pluginConfig,
        canUseAutoReview: true,
        requirementsToml: 'allowed_sandbox_modes = ["read-only"]',
      }),
    ).toMatchObject({ sandbox: "read-only", approvalsReviewer: "user" });
  });

  it("lets a deny exec floor tighten a guarded tuple", () => {
    const resolved = applyCodexSessionPermissionPolicy({
      appServer: appServer(),
      permissionMode: "guarded",
      sessionRoot: "/workspace/project",
      defaultRoot,
      pluginConfig,
      canUseAutoReview: true,
      execMode: "deny",
    });

    expect(resolved).toMatchObject({
      sandbox: "read-only",
      approvalPolicy: "on-request",
      approvalsReviewer: "user",
    });
  });

  it.each([
    {
      requested: "full" as const,
      runtime: {
        sandbox: "workspace-write" as const,
        approvalPolicy: "on-request" as const,
        approvalsReviewer: "auto_review" as const,
      },
      effective: "workspace",
      execMode: "auto",
    },
    {
      requested: "workspace" as const,
      runtime: {
        sandbox: "workspace-write" as const,
        approvalPolicy: "on-request" as const,
        approvalsReviewer: "user" as const,
      },
      effective: "guarded",
      execMode: "ask",
    },
    {
      requested: "read-only" as const,
      runtime: {
        sandbox: "danger-full-access" as const,
        approvalPolicy: "never" as const,
        approvalsReviewer: "user" as const,
      },
      effective: "read-only",
      execMode: "deny",
    },
  ])(
    "keeps dynamic authority at $effective when the requested $requested tuple changes",
    ({ requested, runtime, effective, execMode }) => {
      expect(
        resolveCodexEffectiveSessionPermissionPolicy({
          appServer: { ...appServer(), ...runtime },
          permissionMode: requested,
          sessionRoot: "/workspace/project",
          defaultRoot,
        }),
      ).toEqual({ mode: effective, root: "/workspace/project", execMode });
    },
  );

  it.each(["read-only", "guarded", "workspace"] as const)(
    "keeps mandatory per-command approval when applying %s session permissions",
    (permissionMode) => {
      expect(
        applyCodexSessionPermissionPolicy({
          appServer: { ...appServer(), approvalPolicy: "untrusted" },
          permissionMode,
          sessionRoot: "/workspace/project",
          defaultRoot,
          pluginConfig,
          canUseAutoReview: true,
          execMode: "ask",
        }),
      ).toMatchObject({ approvalPolicy: "untrusted", approvalsReviewer: "user" });
    },
  );

  it("fails closed when session requirements exclude mandatory per-command approval", () => {
    expect(() =>
      applyCodexSessionPermissionPolicy({
        appServer: { ...appServer(), approvalPolicy: "untrusted" },
        permissionMode: "guarded",
        sessionRoot: "/workspace/project",
        defaultRoot,
        pluginConfig,
        canUseAutoReview: true,
        execMode: "ask",
        requirementsToml: 'allowed_approval_policies = ["on-request"]',
      }),
    ).toThrow("tools.exec.ask=always requires Codex app-server per-command approvals");
  });

  it("fails closed when requirements cannot provide mandatory user review", () => {
    expect(() =>
      applyCodexSessionPermissionPolicy({
        appServer: appServer(),
        permissionMode: "guarded",
        sessionRoot: "/workspace/project",
        defaultRoot,
        pluginConfig,
        canUseAutoReview: true,
        requirementsToml: [
          'allowed_sandbox_modes = ["workspace-write"]',
          'allowed_approval_policies = ["on-request"]',
          'allowed_approvals_reviewers = ["auto_review"]',
        ].join("\n"),
      }),
    ).toThrow("requires Codex app-server user approvals");
  });

  it("keeps a nested cwd and clamps an outside cwd to the prepared root", () => {
    expect(
      resolveCodexSessionPermissionCwd({
        permissionMode: "workspace",
        sessionRoot: "/workspace/project",
        defaultRoot,
        requestedCwd: "/workspace/project/packages/app",
        fallbackCwd: "/workspace",
      }),
    ).toBe("/workspace/project/packages/app");
    expect(
      resolveCodexSessionPermissionCwd({
        permissionMode: "workspace",
        sessionRoot: "/workspace/project",
        defaultRoot,
        requestedCwd: "/workspace/other",
        fallbackCwd: "/workspace",
      }),
    ).toBe("/workspace/project");
  });

  it("uses the agent workspace for rootless policies and clamps requested cwd to it", () => {
    const runtime = applyCodexSessionPermissionPolicy({
      appServer: appServer(),
      permissionMode: "workspace",
      defaultRoot,
      pluginConfig,
      canUseAutoReview: true,
    });

    expect(runtime).toMatchObject({ sessionRoot: defaultRoot, sandbox: "workspace-write" });
    expect(
      resolveCodexEffectiveSessionPermissionPolicy({
        appServer: runtime,
        permissionMode: "workspace",
        defaultRoot,
      }),
    ).toEqual({ mode: "workspace", root: defaultRoot, execMode: "auto" });
    expect(
      resolveCodexSessionPermissionCwd({
        permissionMode: "workspace",
        defaultRoot,
        requestedCwd: "/workspace/packages/app",
        fallbackCwd: "/outside",
      }),
    ).toBe("/workspace/packages/app");
    expect(
      resolveCodexSessionPermissionCwd({
        permissionMode: "workspace",
        defaultRoot,
        requestedCwd: "/outside",
        fallbackCwd: "/outside",
      }),
    ).toBe(defaultRoot);
  });
});

import { hostname as readHostName } from "node:os";
import type { EmbeddedRunAttemptParamsV2 } from "openclaw/plugin-sdk/agent-harness-runtime";
import { isPathInside } from "openclaw/plugin-sdk/file-access-runtime";
import type {
  CodexAppServerApprovalsReviewer,
  CodexAppServerManagedApprovalPolicy,
  CodexAppServerRuntimeOptions,
  CodexAppServerSandboxMode,
  CodexPluginConfig,
  OpenClawExecMode,
} from "./config-contracts.js";
import { selectGuardianSandbox } from "./config-exec-policy.js";
import {
  parseAllowedApprovalPoliciesFromCodexRequirements,
  parseAllowedApprovalsReviewersFromCodexRequirements,
  parseAllowedSandboxModesFromCodexRequirements,
  selectGuardianApprovalPolicy,
  selectGuardianApprovalsReviewer,
  selectUserApprovalsReviewer,
} from "./config-requirements.js";
import { resolveCodexAppServerNetworkProxy } from "./config-security.js";

type SessionPermissionMode = NonNullable<EmbeddedRunAttemptParamsV2["permissionMode"]>;

export type CodexEffectiveSessionPermissionPolicy = {
  mode: SessionPermissionMode;
  root: string;
  execMode: OpenClawExecMode;
};

export const CODEX_SESSION_PERMISSION_EXEC_MODES = {
  "read-only": "deny",
  guarded: "ask",
  workspace: "auto",
  full: "full",
} satisfies Record<SessionPermissionMode, OpenClawExecMode>;

type CodexSessionPermissionTuple = {
  approvalPolicy: CodexAppServerManagedApprovalPolicy;
  approvalsReviewer: CodexAppServerApprovalsReviewer;
  sandbox: CodexAppServerSandboxMode;
};

function tupleForMode(
  mode: SessionPermissionMode,
  canUseAutoReview: boolean,
): CodexSessionPermissionTuple {
  switch (mode) {
    case "read-only":
      return { sandbox: "read-only", approvalPolicy: "on-request", approvalsReviewer: "user" };
    case "guarded":
      return {
        sandbox: "workspace-write",
        approvalPolicy: "on-request",
        approvalsReviewer: "user",
      };
    case "workspace":
      return {
        sandbox: "workspace-write",
        approvalPolicy: "on-request",
        approvalsReviewer: canUseAutoReview ? "auto_review" : "user",
      };
    case "full":
      return {
        sandbox: "danger-full-access",
        approvalPolicy: "never",
        approvalsReviewer: "user",
      };
  }
  return mode satisfies never;
}

function requirementsAllowTuple(
  tuple: CodexSessionPermissionTuple,
  allowed: {
    sandboxes: Set<CodexAppServerSandboxMode> | undefined;
    approvalPolicies: Set<CodexAppServerManagedApprovalPolicy> | undefined;
    reviewers: Set<CodexAppServerApprovalsReviewer> | undefined;
  },
): boolean {
  return (
    (allowed.sandboxes === undefined || allowed.sandboxes.has(tuple.sandbox)) &&
    (allowed.approvalPolicies === undefined ||
      allowed.approvalPolicies.has(tuple.approvalPolicy)) &&
    (allowed.reviewers === undefined || allowed.reviewers.has(tuple.approvalsReviewer))
  );
}

function tightenTupleForExecMode(
  tuple: CodexSessionPermissionTuple,
  execMode: OpenClawExecMode | undefined,
  requiresPerCommandApproval: boolean,
): CodexSessionPermissionTuple {
  switch (execMode) {
    case "deny":
    case "allowlist":
      return { sandbox: "read-only", approvalPolicy: "on-request", approvalsReviewer: "user" };
    case "ask":
      return {
        ...tuple,
        approvalPolicy: requiresPerCommandApproval ? "untrusted" : "on-request",
        approvalsReviewer: "user",
      };
    case "auto":
    case "full":
    case undefined:
      return tuple;
  }
  return execMode satisfies never;
}

function clampSessionPermissionTuple(params: {
  mode: SessionPermissionMode;
  requested: CodexSessionPermissionTuple;
  requirementsToml?: string;
  hostName?: string;
  canUseAutoReview: boolean;
}): CodexSessionPermissionTuple {
  if (!params.requirementsToml) {
    return params.requested;
  }
  const allowed = {
    sandboxes: parseAllowedSandboxModesFromCodexRequirements(
      params.requirementsToml,
      params.hostName ?? readHostName(),
    ),
    approvalPolicies: parseAllowedApprovalPoliciesFromCodexRequirements(params.requirementsToml),
    reviewers: parseAllowedApprovalsReviewersFromCodexRequirements(params.requirementsToml),
  };
  if (requirementsAllowTuple(params.requested, allowed)) {
    return params.requested;
  }
  if (
    params.requested.approvalPolicy === "untrusted" &&
    allowed.approvalPolicies?.has("untrusted") === false
  ) {
    throw new Error("tools.exec.ask=always requires Codex app-server per-command approvals");
  }

  const userReviewRequired =
    params.mode === "read-only" ||
    params.mode === "guarded" ||
    (params.mode === "workspace" && !params.canUseAutoReview);
  const sandboxAuthority = {
    "read-only": 0,
    "workspace-write": 1,
    "danger-full-access": 2,
  } satisfies Record<CodexAppServerSandboxMode, number>;
  const allowedSandboxes = new Set(
    (["read-only", "workspace-write", "danger-full-access"] as const).filter(
      (sandbox) =>
        sandboxAuthority[sandbox] <= sandboxAuthority[params.requested.sandbox] &&
        (allowed.sandboxes === undefined || allowed.sandboxes.has(sandbox)),
    ),
  );
  if (allowedSandboxes.size === 0) {
    throw new Error(
      `Codex session permission mode=${params.mode} cannot satisfy managed sandbox requirements without widening access`,
    );
  }
  return {
    sandbox: selectGuardianSandbox(allowedSandboxes),
    approvalPolicy:
      params.requested.approvalPolicy === "untrusted"
        ? "untrusted"
        : selectGuardianApprovalPolicy(
            allowed.approvalPolicies,
            userReviewRequired ? "ask" : "auto",
          ),
    approvalsReviewer: userReviewRequired
      ? selectUserApprovalsReviewer(allowed.reviewers)
      : selectGuardianApprovalsReviewer(allowed.reviewers, "auto"),
  };
}

/** Applies one complete session-mode tuple without mixing requirements-clamped fields. */
export function applyCodexSessionPermissionPolicy(params: {
  appServer: CodexAppServerRuntimeOptions;
  permissionMode?: SessionPermissionMode;
  sessionRoot?: string;
  defaultRoot: string;
  pluginConfig: CodexPluginConfig;
  canUseAutoReview: boolean;
  requirementsToml?: string;
  hostName?: string;
  policyLocked?: boolean;
  execMode?: OpenClawExecMode;
}): CodexAppServerRuntimeOptions {
  if (!params.permissionMode) {
    return params.appServer;
  }
  const sessionRoot = params.sessionRoot?.trim() || params.defaultRoot;
  if (params.policyLocked) {
    return { ...params.appServer, sessionRoot };
  }

  const requested = tightenTupleForExecMode(
    tupleForMode(params.permissionMode, params.canUseAutoReview),
    params.execMode,
    params.appServer.approvalPolicy === "untrusted",
  );
  const tuple =
    params.appServer.start.transport === "stdio"
      ? clampSessionPermissionTuple({
          mode: params.permissionMode,
          requested,
          requirementsToml: params.requirementsToml,
          hostName: params.hostName,
          canUseAutoReview: params.canUseAutoReview,
        })
      : requested;
  const networkProxy = params.appServer.networkProxy
    ? resolveCodexAppServerNetworkProxy(params.pluginConfig.appServer?.networkProxy, tuple.sandbox)
        .networkProxy
    : undefined;
  const resolved = {
    ...params.appServer,
    ...tuple,
    sessionRoot,
  };
  if (networkProxy) {
    resolved.networkProxy = networkProxy;
  } else {
    delete resolved.networkProxy;
  }
  return resolved;
}

export function resolveCodexEffectiveSessionPermissionPolicy(params: {
  appServer: CodexAppServerRuntimeOptions;
  permissionMode?: SessionPermissionMode;
  sessionRoot?: string;
  defaultRoot: string;
}): CodexEffectiveSessionPermissionPolicy | undefined {
  if (!params.permissionMode) {
    return undefined;
  }
  const root = params.sessionRoot?.trim() || params.defaultRoot;
  const { sandbox, approvalPolicy, approvalsReviewer } = params.appServer;
  const fullAccess =
    params.permissionMode === "full" &&
    sandbox === "danger-full-access" &&
    approvalPolicy === "never";
  const guardianReview =
    params.permissionMode !== "guarded" &&
    sandbox === "workspace-write" &&
    approvalPolicy === "on-request" &&
    approvalsReviewer !== "user";
  const mode =
    params.permissionMode === "read-only" || sandbox === "read-only"
      ? "read-only"
      : fullAccess
        ? "full"
        : guardianReview
          ? "workspace"
          : "guarded";
  return { mode, root, execMode: CODEX_SESSION_PERMISSION_EXEC_MODES[mode] };
}

/** Keeps relative execution inside the prepared root without filesystem rediscovery. */
export function resolveCodexSessionPermissionCwd(params: {
  permissionMode?: SessionPermissionMode;
  sessionRoot?: string;
  defaultRoot: string;
  requestedCwd?: string;
  fallbackCwd: string;
}): string {
  if (!params.permissionMode) {
    return params.requestedCwd ?? params.fallbackCwd;
  }
  const sessionRoot = params.sessionRoot?.trim() || params.defaultRoot;
  const requestedCwd = params.requestedCwd?.trim();
  return requestedCwd && isPathInside(sessionRoot, requestedCwd) ? requestedCwd : sessionRoot;
}

import { randomUUID } from "node:crypto";
import { createDeferred } from "openclaw/plugin-sdk/extension-shared";
import { afterEach, describe, expect, it, vi } from "vitest";
import { legacyCodexConversationBindingId } from "../conversation-binding-data.js";
import {
  claimCodexAppServerLiveThread,
  consumeCodexAppServerLiveThread,
  ensureCodexAppServerClientRuntime,
  hasCodexAppServerLiveThread,
  isCodexAppServerLiveThreadClaimed,
} from "./client-runtime.js";
import { createCodexTestBindingStore } from "./session-binding.test-helpers.js";
import { withCodexAppServerSessionDeletion } from "./session-retirement.js";
import * as sharedClients from "./shared-client.js";
import { createClientHarness } from "./test-support.js";
import {
  retainCodexAppServerBindingSubscription,
  withCodexAppServerThreadMutation,
  withExclusiveCodexAppServerThread,
} from "./thread-ownership.js";
import { withTimeout } from "./timeout.js";

const session = {
  kind: "session" as const,
  agentId: "main",
  sessionKey: "agent:main:dashboard:retirement",
  sessionId: "session-before-deletion",
};

describe("Codex session deletion subscriptions", () => {
  const clients: ReturnType<typeof createClientHarness>[] = [];

  afterEach(() => {
    for (const harness of clients) {
      harness.client.close();
      harness.emitExit();
    }
    clients.length = 0;
    vi.restoreAllMocks();
  });

  function createFixture() {
    const harness = createClientHarness();
    clients.push(harness);
    const { client } = harness;
    const bindingStore = createCodexTestBindingStore();
    const binding = {
      threadId: `thread-${randomUUID()}`,
      clientId: client.getInstanceId(),
      cwd: "/repo",
    };
    const request = vi.spyOn(client, "request").mockResolvedValue({ status: "unsubscribed" });
    const releaseClientLease = vi.fn();
    vi.spyOn(sharedClients, "retainSharedCodexAppServerClientByInstanceId").mockImplementation(
      (clientId) =>
        clientId === binding.clientId ? { client, release: releaseClientLease } : undefined,
    );
    ensureCodexAppServerClientRuntime(client, {
      agentDir: "/tmp/codex-retirement-agent",
      authMode: "prepared-api-key",
    });

    const seed = async (identity = session) => {
      await bindingStore.mutate(identity, { kind: "set", binding });
    };
    const remove = (
      identity = session,
      run: Parameters<typeof withCodexAppServerSessionDeletion<void>>[2] = async (mutation) => {
        mutation.commit();
      },
    ) =>
      withCodexAppServerSessionDeletion(
        bindingStore,
        { ...identity, assertCurrent: () => {} },
        run,
      );
    const resume = async (identity: typeof session) => {
      await bindingStore.withLease(identity, async () => {
        await client.request("thread/resume", { threadId: binding.threadId });
        await retainCodexAppServerBindingSubscription(client, binding.threadId);
        if (!(await bindingStore.mutate(identity, { kind: "set", binding }))) {
          throw new Error("resumed binding did not commit");
        }
      });
    };
    return { bindingStore, binding, client, remove, request, resume, seed };
  }

  it("rejects a claimed native thread before invoking the session transaction", async () => {
    const fixture = createFixture();
    await fixture.seed();
    await claimCodexAppServerLiveThread(fixture.client, fixture.binding.threadId);
    const transaction = vi.fn(async () => {});

    await expect(fixture.remove(session, transaction)).rejects.toThrow("claimed by active work");

    expect(transaction).not.toHaveBeenCalled();
    expect(await fixture.bindingStore.read(session)).toEqual(fixture.binding);
    expect(isCodexAppServerLiveThreadClaimed(fixture.client, fixture.binding.threadId)).toBe(true);
    expect(fixture.request).not.toHaveBeenCalled();
  });

  it("removes a migrated session binding without unsubscribing its surviving legacy conversation", async () => {
    const fixture = createFixture();
    const conversation = {
      kind: "conversation" as const,
      bindingId: legacyCodexConversationBindingId("/repo/legacy-session.jsonl"),
    };
    await fixture.seed();
    await fixture.bindingStore.mutate(conversation, { kind: "set", binding: fixture.binding });
    await retainCodexAppServerBindingSubscription(fixture.client, fixture.binding.threadId);

    await fixture.remove();

    expect(await fixture.bindingStore.read(session)).toBeUndefined();
    expect(await fixture.bindingStore.read(conversation)).toEqual(fixture.binding);
    expect(
      await consumeCodexAppServerLiveThread(fixture.client, fixture.binding.threadId),
    ).toBeDefined();
    expect(fixture.request).not.toHaveBeenCalled();
  });

  it("preserves a same-key successor when resume owns the native queue before deletion cleanup", async () => {
    const fixture = createFixture();
    await fixture.seed();
    await retainCodexAppServerBindingSubscription(fixture.client, fixture.binding.threadId);
    const successor = { ...session, sessionId: "session-after-deletion" };
    const resumeEntered = createDeferred<void>();
    const allowResume = createDeferred<void>();
    const committed = createDeferred<void>();
    const resuming = withCodexAppServerThreadMutation(fixture.binding.threadId, async () => {
      resumeEntered.resolve();
      await allowResume.promise;
      await fixture.resume(successor);
    });
    await withTimeout(resumeEntered.promise, 5_000, "resume did not enter the native queue");
    const deletion = fixture.remove(session, async (mutation) => {
      mutation.commit();
      committed.resolve();
    });
    const completion = Promise.allSettled([resuming, deletion]);
    try {
      await withTimeout(committed.promise, 5_000, "native resume queue blocked session deletion");
      allowResume.resolve();
      expect(
        await withTimeout(completion, 5_000, "native deletion cleanup did not settle"),
      ).toEqual([
        { status: "fulfilled", value: undefined },
        { status: "fulfilled", value: undefined },
      ]);
      expect(await fixture.bindingStore.read(successor)).toEqual(fixture.binding);
      expect(
        await consumeCodexAppServerLiveThread(fixture.client, fixture.binding.threadId),
      ).toBeDefined();
      expect(fixture.request.mock.calls.map(([method]) => method)).toEqual(["thread/resume"]);
    } finally {
      allowResume.resolve();
      await withTimeout(completion, 5_000, "resume and deletion cleanup did not settle");
    }
  });

  it("holds the native queue through unsubscribe acknowledgement before a successor resumes", async () => {
    const fixture = createFixture();
    await fixture.seed();
    await retainCodexAppServerBindingSubscription(fixture.client, fixture.binding.threadId);
    const unsubscribeStarted = createDeferred<void>();
    const unsubscribeAcknowledged = createDeferred<void>();
    fixture.request.mockImplementation(async (method) => {
      if (method === "thread/unsubscribe") {
        unsubscribeStarted.resolve();
        await unsubscribeAcknowledged.promise;
      }
      return {};
    });
    const deletion = fixture.remove();
    const deletionCompletion = Promise.allSettled([deletion]);
    let resuming: Promise<void> | undefined;
    try {
      await withTimeout(unsubscribeStarted.promise, 5_000, "deletion did not unsubscribe");
      const successor = { ...session, sessionId: "session-after-deletion" };
      let resumeEntered = false;
      resuming = withExclusiveCodexAppServerThread({
        bindingStore: fixture.bindingStore,
        identity: successor,
        threadId: fixture.binding.threadId,
        run: async () => {
          resumeEntered = true;
          await fixture.resume(successor);
        },
      });
      const completion = Promise.allSettled([deletion, resuming]);
      await withCodexAppServerThreadMutation(`other-${fixture.binding.threadId}`, async () => {});
      expect(resumeEntered).toBe(false);
      expect(await fixture.bindingStore.read(session)).toBeUndefined();
      unsubscribeAcknowledged.resolve();
      expect(
        await withTimeout(completion, 5_000, "resume did not follow deletion cleanup"),
      ).toEqual([
        { status: "fulfilled", value: undefined },
        { status: "fulfilled", value: undefined },
      ]);
      expect(fixture.request.mock.calls.map(([method]) => method)).toEqual([
        "thread/unsubscribe",
        "thread/resume",
      ]);
      expect(await fixture.bindingStore.read(successor)).toEqual(fixture.binding);
      expect(hasCodexAppServerLiveThread(fixture.client, fixture.binding.threadId)).toBe(true);
    } finally {
      unsubscribeAcknowledged.resolve();
      await withTimeout(
        Promise.allSettled([deletionCompletion, resuming]),
        5_000,
        "unsubscribe and resume cleanup did not settle",
      );
    }
  });

  it("deletes nested same-thread owners without deadlock and releases their subscription once", async () => {
    const fixture = createFixture();
    const sibling = { ...session, sessionKey: "agent:main:cron:retirement:run:child" };
    await fixture.seed();
    await fixture.seed(sibling);
    await retainCodexAppServerBindingSubscription(fixture.client, fixture.binding.threadId);

    await withTimeout(
      fixture.remove(session, async (first) => {
        await fixture.remove(sibling, async (second) => {
          first.commit();
          second.commit();
        });
      }),
      5_000,
      "nested deletion deadlocked on a shared native thread",
    );

    expect(await fixture.bindingStore.read(session)).toBeUndefined();
    expect(await fixture.bindingStore.read(sibling)).toBeUndefined();
    expect(fixture.request.mock.calls.map(([method]) => method)).toEqual(["thread/unsubscribe"]);
    expect(hasCodexAppServerLiveThread(fixture.client, fixture.binding.threadId)).toBe(false);
  });

  it("unsubscribes an incognito thread without an idle registry entry", async () => {
    const fixture = createFixture();
    const incognito = { ...session, sessionKey: "agent:main:dashboard:incognito-retirement" };
    await fixture.seed(incognito);

    await fixture.remove(incognito);

    expect(await fixture.bindingStore.read(incognito)).toBeUndefined();
    expect(fixture.request).toHaveBeenCalledExactlyOnceWith(
      "thread/unsubscribe",
      { threadId: fixture.binding.threadId },
      { timeoutMs: 5_000, assertCurrent: expect.any(Function) },
    );
  });
});

import type {
  AgentHarnessSessionDeletionMutation,
  AgentHarnessSessionDeletionParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { isIncognitoSessionKey } from "../incognito-session.js";
import {
  CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
  closeCodexStartupClientBestEffort,
  CodexAppServerUnsafeSubscriptionError,
  unsubscribeCodexThreadBestEffort,
} from "./attempt-client-cleanup.js";
import {
  hasCodexAppServerLiveThread,
  isCodexAppServerLiveThreadClaimed,
  releaseCodexAppServerLiveThread,
} from "./client-runtime.js";
import { codexNativeSubagentMonitorRuntime } from "./native-subagent-monitor.js";
import type {
  CodexAppServerBindingIdentity,
  CodexAppServerBindingStore,
  CodexAppServerThreadBinding,
  CodexSessionGenerationRetirementResult,
} from "./session-binding.js";
import { retainSharedCodexAppServerClientByInstanceId } from "./shared-client.js";
import { withCodexAppServerThreadMutation } from "./thread-ownership.js";

async function releaseSessionSubscription(
  client: NonNullable<ReturnType<typeof retainSharedCodexAppServerClientByInstanceId>>["client"],
  binding: CodexAppServerThreadBinding,
  sessionKey: string | undefined,
  assertCurrent?: () => void,
): Promise<void> {
  assertCurrent?.();
  // End child ownership before the parent subscription, so late completions
  // cannot deliver into a replacement OpenClaw session generation.
  codexNativeSubagentMonitorRuntime.retireParent(client, binding.threadId);
  const released = await releaseCodexAppServerLiveThread(client, binding.threadId, assertCurrent);
  assertCurrent?.();
  if (!released && isIncognitoSessionKey(sessionKey)) {
    const unsubscribed = await unsubscribeCodexThreadBestEffort(client, {
      threadId: binding.threadId,
      timeoutMs: CODEX_APP_SERVER_UNSUBSCRIBE_TIMEOUT_MS,
      assertCurrent,
    });
    assertCurrent?.();
    if (!unsubscribed) {
      await closeCodexStartupClientBestEffort(client);
      throw new CodexAppServerUnsafeSubscriptionError(
        `Codex retired session subscription could not be released: ${binding.threadId}`,
      );
    }
  }
}

/** Prepare exact binding deletion before the session owner commits either database. */
export async function withCodexAppServerSessionDeletion<T>(
  bindingStore: CodexAppServerBindingStore,
  params: AgentHarnessSessionDeletionParams,
  run: (mutation: AgentHarnessSessionDeletionMutation) => Promise<T>,
): Promise<T> {
  const { assertCurrent } = params;
  const identity = {
    kind: "session" as const,
    agentId: params.agentId,
    sessionKey: params.sessionKey,
    sessionId: params.sessionId,
  };
  return await bindingStore.withSessionDeletion(
    identity,
    assertCurrent,
    async (binding, mutation) => {
      assertCurrent();
      if (binding?.connectionScope === "supervision") {
        throw new Error("Cannot delete a session while its Codex binding is owned by supervision");
      }
      const clientLease = binding?.clientId
        ? retainSharedCodexAppServerClientByInstanceId(binding.clientId)
        : undefined;
      const assertUnclaimed = () => {
        assertCurrent();
        if (
          clientLease &&
          binding &&
          isCodexAppServerLiveThreadClaimed(clientLease.client, binding.threadId)
        ) {
          throw new Error(
            "Cannot delete a session while its Codex thread is claimed by active work",
          );
        }
      };
      let committed = false;
      try {
        assertUnclaimed();
        return await run({
          commit() {
            assertUnclaimed();
            mutation.commit();
            committed = true;
          },
          rollback() {
            mutation.rollback();
            committed = false;
          },
        });
      } finally {
        try {
          // An artifact publication failure after COMMIT still ends this subscription;
          // only the session owner's transaction rollback may restore the binding.
          if (committed && binding && clientLease) {
            await withCodexAppServerThreadMutation(binding.threadId, async () => {
              assertCurrent();
              // Most expired bindings no longer have a live subscription. Only
              // live threads need the persisted-owner check (idle retention is bounded).
              if (
                !hasCodexAppServerLiveThread(clientLease.client, binding.threadId) &&
                !isIncognitoSessionKey(params.sessionKey)
              ) {
                return;
              }
              // The deleted row is absent now. Any surviving owner, including a
              // successor at the same key, keeps its connection-scoped subscription.
              if (await bindingStore.hasOtherThreadOwner(binding.threadId)) {
                return;
              }
              await releaseSessionSubscription(
                clientLease.client,
                binding,
                params.sessionKey,
                assertUnclaimed,
              );
            });
          }
        } finally {
          clientLease?.release();
        }
      }
    },
  );
}

/** Retire binding and native subscription under the same generation/physical-client ownership fence. */
export async function retireCodexAppServerSessionGeneration(params: {
  bindingStore: CodexAppServerBindingStore;
  identity: Extract<CodexAppServerBindingIdentity, { kind: "session" }>;
  mode: "reset" | "retire";
}): Promise<CodexSessionGenerationRetirementResult> {
  const retireGeneration = () =>
    params.mode === "reset"
      ? params.bindingStore.resetSessionGeneration(params.identity)
      : params.bindingStore.retireSessionGeneration(params.identity);
  const expectedBinding = await params.bindingStore.read(params.identity);
  if (!expectedBinding) {
    // Leasing an absent/retired row manufactures state or rejects its fence;
    // callers need the original absent/conflict result for reset reclamation.
    return await retireGeneration();
  }
  return await params.bindingStore.withLease(params.identity, async () => {
    const binding = await params.bindingStore.read(params.identity);
    if (binding?.threadId !== expectedBinding.threadId) {
      return "conflict";
    }
    const result = await retireGeneration();
    if (result !== "applied" || !binding?.clientId) {
      return result;
    }

    // Locate the original physical client only after its exact binding was
    // retired; delayed reset events must never unsubscribe a newer generation.
    const clientLease = retainSharedCodexAppServerClientByInstanceId(binding.clientId);
    if (!clientLease) {
      return result;
    }
    try {
      await releaseSessionSubscription(clientLease.client, binding, params.identity.sessionKey);
    } finally {
      clientLease.release();
    }
    return result;
  });
}

import type { AgentMessage } from "openclaw/plugin-sdk/agent-harness-runtime";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { captureCodexSettledTurnFinalizationContext } from "./settled-turn-context.js";
import { attachCodexMirrorAttestation } from "./transcript-mirror-attestation.js";
import {
  attachCodexMirrorIdentity,
  attachUpstreamUserText,
  readMirrorIdentity,
  readUpstreamUserText,
} from "./upstream-prompt-provenance.js";

const mocks = vi.hoisted(() => ({
  readHistory: vi.fn(),
}));

vi.mock("./session-history.js", () => ({
  readCodexMirroredSessionHistory: mocks.readHistory,
}));

function message(value: unknown, identity: string): AgentMessage {
  return attachCodexMirrorIdentity(value as AgentMessage, identity);
}

function settledTurn() {
  return [
    message({ role: "user", content: "Send it." }, "turn-2:prompt"),
    message(
      {
        role: "assistant",
        content: [{ type: "toolCall", id: "call-2", name: "message", arguments: {} }],
      },
      "turn-2:tool:call-2:call",
    ),
    message(
      {
        role: "toolResult",
        toolCallId: "call-2",
        toolName: "message",
        content: [{ type: "text", text: "sent" }],
      },
      "turn-2:tool:call-2:result",
    ),
  ];
}

function settledHostPromptTurn() {
  const settledMessages = settledTurn();
  settledMessages[0] = attachUpstreamUserText(
    message(
      { role: "user", content: "Send it.", idempotencyKey: "durable-user-turn" },
      "turn-2:prompt",
    ),
    "Decorated upstream prompt: Send it.",
  );
  const persistedPrompt = {
    role: "user",
    content: "Send it.",
    timestamp: 1,
    idempotencyKey: "durable-user-turn",
    __openclaw: { senderIsOwner: true, transport: { messageId: "transport-message" } },
  } as AgentMessage;
  return {
    settledMessages,
    persistedPrompt,
    historyMessages: [persistedPrompt, ...settledMessages.slice(1)],
    mirroredMessages: settledMessages.slice(1),
  };
}

async function captureContext(params: {
  historyMessages: AgentMessage[];
  mirroredMessages: AgentMessage[];
  settledMessages: AgentMessage[];
  turnId?: string;
}) {
  mocks.readHistory.mockImplementation(
    (_target, read: (messages: Iterable<AgentMessage>) => unknown) => read(params.historyMessages),
  );
  return captureCodexSettledTurnFinalizationContext({
    sessionFile: "/tmp/session.jsonl",
    sessionId: "session-1",
    mirroredMessages: params.mirroredMessages,
    settledMessages: params.settledMessages,
    turnId: params.turnId ?? "turn-2",
  });
}

describe("captureCodexSettledTurnFinalizationContext", () => {
  beforeEach(() => {
    mocks.readHistory.mockReset();
  });

  it("freezes the complete active branch exactly through the current tool-result boundary", async () => {
    const prior = message({ role: "user", content: "Alice is the recipient." }, "turn-1:prompt");
    const settledMessages = settledTurn();
    const later = message({ role: "user", content: "later message" }, "turn-3:prompt");
    const historyMessages = [prior, ...settledMessages, later];

    const context = await captureContext({
      historyMessages,
      mirroredMessages: settledMessages,
      settledMessages,
      turnId: "turn-2",
    });

    Object.assign(prior, { content: "changed after capture" });
    expect(context?.data).toEqual([
      {
        type: "message",
        role: "user",
        content: [{ type: "input_text", text: "Alice is the recipient." }],
      },
      { type: "message", role: "user", content: [{ type: "input_text", text: "Send it." }] },
      { type: "function_call", call_id: "call-2", name: "message", arguments: "{}" },
      { type: "function_call_output", call_id: "call-2", output: "sent" },
    ]);
    expect(Object.isFrozen(context)).toBe(true);
    expect(Object.isFrozen(context?.data)).toBe(true);
    expect(Object.isFrozen(context?.data[0])).toBe(true);
  });

  it("adopts an exact host-persisted prompt without rewriting its canonical metadata", async () => {
    const { persistedPrompt, ...turn } = settledHostPromptTurn();

    const context = await captureContext(turn);

    expect(context?.data[0]).toEqual({
      type: "message",
      role: "user",
      content: [{ type: "input_text", text: "Send it." }],
    });
    expect(readMirrorIdentity(persistedPrompt)).toBeUndefined();
    expect(readUpstreamUserText(persistedPrompt)).toBeUndefined();
    expect(persistedPrompt).toMatchObject({
      __openclaw: { senderIsOwner: true, transport: { messageId: "transport-message" } },
    });
  });

  it.each([
    {
      name: "missing persisted key",
      change: (prompt: AgentMessage) => ({ ...prompt, idempotencyKey: undefined }),
    },
    {
      name: "different persisted key",
      change: (prompt: AgentMessage) => ({ ...prompt, idempotencyKey: "different-user-turn" }),
    },
    {
      name: "changed prompt content",
      change: (prompt: AgentMessage) => ({ ...prompt, content: "Send something else." }),
    },
    {
      name: "conflicting mirror identity",
      change: (prompt: AgentMessage) => attachCodexMirrorIdentity(prompt, "foreign-turn:prompt"),
    },
    {
      name: "Codex mirror origin without a fingerprint",
      change: (prompt: AgentMessage) => attachCodexMirrorAttestation(prompt),
    },
    {
      name: "Codex source fingerprint without an origin",
      change: (prompt: AgentMessage) => ({
        ...prompt,
        __openclaw: { mirrorSourceFingerprint: "stale-fingerprint" },
      }),
    },
    {
      name: "conflicting upstream prompt",
      change: (prompt: AgentMessage) =>
        attachUpstreamUserText(prompt, "Untrusted upstream prompt."),
    },
  ])("rejects host-persisted prompt adoption with $name", async ({ change }) => {
    const turn = settledHostPromptTurn();
    turn.historyMessages[0] = change(turn.persistedPrompt) as AgentMessage;

    await expect(captureContext(turn)).resolves.toBeUndefined();
  });

  it.each(["before", "after"])(
    "rejects duplicate host prompt keys %s the settled boundary",
    async (position) => {
      const turn = settledHostPromptTurn();
      if (position === "before") {
        turn.historyMessages.unshift({ ...turn.persistedPrompt });
      } else {
        turn.historyMessages.push({ ...turn.persistedPrompt });
      }
      await expect(captureContext(turn)).resolves.toBeUndefined();
    },
  );

  it.each([
    {
      name: "missing current prompt",
      settledMessages: settledTurn().slice(1),
      historyMessages: settledTurn(),
    },
    {
      name: "missing current tool call",
      settledMessages: settledTurn(),
      historyMessages: [settledTurn()[0]!, settledTurn()[2]!],
    },
    {
      name: "duplicate persisted identity",
      settledMessages: settledTurn(),
      historyMessages: [...settledTurn(), settledTurn()[2]!],
    },
    {
      name: "foreign boundary turn",
      settledMessages: settledTurn(),
      historyMessages: settledTurn(),
      turnId: "turn-3",
    },
  ])("fails closed for $name", async ({ settledMessages, historyMessages, turnId }) => {
    await expect(
      captureContext({
        historyMessages,
        mirroredMessages: settledMessages,
        settledMessages,
        turnId: turnId ?? "turn-2",
      }),
    ).resolves.toBeUndefined();
  });

  it("fails closed when a persisted payload drifts under the same mirror identity", async () => {
    const settledMessages = settledTurn();
    const historyMessages = settledTurn();
    historyMessages[2] = message(
      {
        role: "toolResult",
        toolCallId: "call-2",
        toolName: "message",
        content: [{ type: "text", text: "different result" }],
      },
      "turn-2:tool:call-2:result",
    );

    await expect(
      captureContext({
        historyMessages,
        mirroredMessages: settledMessages,
        settledMessages,
        turnId: "turn-2",
      }),
    ).resolves.toBeUndefined();
  });

  it("fails closed when current mirrored messages are reordered", async () => {
    const settledMessages = settledTurn();
    await expect(
      captureContext({
        historyMessages: settledMessages,
        mirroredMessages: [settledMessages[1]!, settledMessages[0]!, settledMessages[2]!],
        settledMessages,
        turnId: "turn-2",
      }),
    ).resolves.toBeUndefined();
  });

  it("contains transcript read failures after tools have settled", async () => {
    mocks.readHistory.mockRejectedValue(new Error("read failed"));

    await expect(
      captureCodexSettledTurnFinalizationContext({
        sessionFile: "/tmp/session.jsonl",
        sessionId: "session-1",
        mirroredMessages: settledTurn(),
        settledMessages: settledTurn(),
        turnId: "turn-2",
      }),
    ).resolves.toBeUndefined();
  });

  it("retains replay evidence without copying storage-only tool details", async () => {
    const historyMessages = settledTurn();
    Object.assign(historyMessages[2]!, { details: { payload: "x".repeat(1024 * 1024) } });
    const context = await captureContext({
      historyMessages,
      mirroredMessages: historyMessages,
      settledMessages: historyMessages,
    });
    expect(context?.data.at(-1)).toEqual({
      type: "function_call_output",
      call_id: "call-2",
      output: "sent",
    });
    expect(JSON.stringify(context).length).toBeLessThan(1024);
  });

  it("rejects a read failure after the complete prefix instead of accepting partial verification", async () => {
    const settledMessages = settledTurn();
    mocks.readHistory.mockImplementation(
      (_target, read: (messages: Iterable<AgentMessage>) => unknown) =>
        read(
          (function* () {
            yield* settledMessages;
            throw new Error("synthetic suffix read failure");
          })(),
        ),
    );
    await expect(
      captureCodexSettledTurnFinalizationContext({
        sessionFile: "/tmp/session.jsonl",
        sessionId: "session-1",
        mirroredMessages: settledMessages,
        settledMessages,
        turnId: "turn-2",
      }),
    ).resolves.toBeUndefined();
  });
});

import {
  embeddedAgentLog,
  formatErrorMessage,
  type AgentMessage,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import type { JsonValue } from "./protocol.js";
import {
  readCodexMirroredSessionHistory,
  type CodexMirroredSessionHistoryTarget,
} from "./session-history.js";
import { projectSettledCodexMessages } from "./settled-turn-projection.js";
import {
  hasCodexMirrorOrigin,
  readCodexMirrorSourceFingerprint,
  serializeCodexMirrorSourceEvidence,
} from "./transcript-mirror-attestation.js";
import {
  attachCodexMirrorIdentity,
  attachUpstreamUserText,
  readMirrorIdentity,
  readUpstreamUserText,
} from "./upstream-prompt-provenance.js";

function freezeProjection(value: JsonValue): void {
  if (value !== null && typeof value === "object") {
    for (const child of Object.values(value)) {
      freezeProjection(child);
    }
    Object.freeze(value);
  }
}

/** Only the Codex owner interprets this bounded, detached replay projection. */
export class CodexSettledTurnContext {
  readonly source = "harness";

  constructor(readonly data: JsonValue[]) {
    freezeProjection(data);
    Object.freeze(this);
  }
}

type SettledTurnMessages = {
  mirroredMessages: readonly AgentMessage[];
  settledMessages: readonly AgentMessage[];
  turnId: string;
};

function rejectEvidence(): never {
  throw new Error("Codex settled-turn transcript does not match the settled turn");
}

function adoptPersistedHostPrompt(message: AgentMessage, source: AgentMessage): AgentMessage {
  const sourceText = readUpstreamUserText(source);
  const persistedText = readUpstreamUserText(message);
  if (
    readMirrorIdentity(message) !== undefined ||
    readCodexMirrorSourceFingerprint(message) !== undefined ||
    hasCodexMirrorOrigin(message) ||
    (persistedText !== undefined && persistedText !== sourceText)
  ) {
    rejectEvidence();
  }
  let logical = attachCodexMirrorIdentity(message, readMirrorIdentity(source)!);
  if (sourceText !== undefined) {
    logical = attachUpstreamUserText(logical, sourceText);
  }
  if (serializeCodexMirrorSourceEvidence(logical) !== serializeCodexMirrorSourceEvidence(source)) {
    rejectEvidence();
  }
  return logical;
}

/** Yields only the settled prefix, but exhausts suffix identity checks before accepting it. */
function* verifiedSettledMessages(
  history: Iterable<AgentMessage>,
  params: SettledTurnMessages,
): Generator<AgentMessage> {
  const promptIdentity = `${params.turnId}:prompt`;
  const boundaryIndex = params.settledMessages.findLastIndex(
    (message) => message.role === "toolResult",
  );
  const boundary = params.settledMessages[boundaryIndex];
  const boundaryIdentity = boundary && readMirrorIdentity(boundary);
  const requiredIds = params.settledMessages
    .slice(0, boundaryIndex + 1)
    .flatMap((message) => readMirrorIdentity(message) ?? []);
  if (
    !boundaryIdentity?.startsWith(`${params.turnId}:tool:`) ||
    requiredIds.length !== boundaryIndex + 1 ||
    new Set(requiredIds).size !== requiredIds.length ||
    !requiredIds.includes(promptIdentity)
  ) {
    rejectEvidence();
  }
  const sourcePrompt = params.settledMessages[0];
  const sourceKey = (sourcePrompt as { idempotencyKey?: unknown } | undefined)?.idempotencyKey;
  const adoption =
    !params.mirroredMessages.some((message) => readMirrorIdentity(message) === promptIdentity) &&
    sourcePrompt?.role === "user" &&
    readMirrorIdentity(sourcePrompt) === promptIdentity &&
    typeof sourceKey === "string" &&
    sourceKey.trim().length > 0
      ? { prompt: sourcePrompt, key: sourceKey }
      : undefined;
  const mirrored = adoption
    ? [adoption.prompt, ...params.mirroredMessages]
    : params.mirroredMessages;
  const mirroredIds = mirrored.flatMap((message) => readMirrorIdentity(message) ?? []);
  const mirroredBoundaryIndex = mirrored.findIndex(
    (message) => readMirrorIdentity(message) === boundaryIdentity,
  );
  if (
    new Set(mirroredIds).size !== mirroredIds.length ||
    mirroredBoundaryIndex + 1 !== requiredIds.length ||
    requiredIds.some((id, index) => readMirrorIdentity(mirrored[index]!) !== id)
  ) {
    rejectEvidence();
  }
  const required = new Map(requiredIds.map((id, index) => [id, mirrored[index]!]));
  const seen = new Set<string>();
  let matched = 0;
  let hostPromptMatches = 0;
  let throughBoundary = false;
  for (const message of history) {
    let verificationMessage = message;
    if (
      adoption &&
      message.role === "user" &&
      (message as { idempotencyKey?: unknown }).idempotencyKey === adoption.key
    ) {
      hostPromptMatches += 1;
      if (hostPromptMatches > 1) {
        rejectEvidence();
      }
      verificationMessage = adoptPersistedHostPrompt(message, adoption.prompt);
    }
    const identity = readMirrorIdentity(verificationMessage);
    if (identity) {
      if (seen.has(identity)) {
        rejectEvidence();
      }
      seen.add(identity);
      const expected = required.get(identity);
      if (expected) {
        if (
          identity !== requiredIds[matched] ||
          serializeCodexMirrorSourceEvidence(verificationMessage) !==
            serializeCodexMirrorSourceEvidence(expected)
        ) {
          rejectEvidence();
        }
        matched += 1;
      }
    }
    if (!throughBoundary) {
      // Adoption is verification-only: replay the canonical persisted prompt, not its synthetic view.
      yield message;
    }
    throughBoundary ||= identity === boundaryIdentity;
  }
  if (!throughBoundary || matched !== requiredIds.length || (adoption && hostPromptMatches !== 1)) {
    rejectEvidence();
  }
}

/** Verifies and freezes a complete replay projection while reading the active branch. */
export async function captureCodexSettledTurnFinalizationContext(
  params: CodexMirroredSessionHistoryTarget & SettledTurnMessages,
): Promise<CodexSettledTurnContext | undefined> {
  try {
    return await readCodexMirroredSessionHistory(
      params,
      (messages) =>
        new CodexSettledTurnContext(
          projectSettledCodexMessages(verifiedSettledMessages(messages, params)),
        ),
    );
  } catch (error) {
    // Capture follows settled side effects; any failure must preserve the incomplete-turn result.
    embeddedAgentLog.warn("codex settled-turn finalization context capture failed", {
      error: formatErrorMessage(error),
      turnId: params.turnId,
    });
    return undefined;
  }
}

