/** Creates an in-memory Codex app-server client harness with writable stdout frames. */
export function createClientHarness(options: { autoEmitExit?: boolean } = {}) {
  const stdout = new PassThrough();
  const writes: string[] = [];
  const writeEvents = new EventEmitter();
  let stdinDestroyed = false;
  let exitEmitted = false;
  let emitProcessExit: () => void = () => undefined;
  const emitExit = () => {
    if (!exitEmitted) {
      exitEmitted = true;
      emitProcessExit();
    }
  };
  type HarnessProcess = EventEmitter & {
    stdin: Writable;
    stdout: PassThrough;
    stderr: PassThrough;
    killed: boolean;
    kill: (signal?: NodeJS.Signals) => unknown;
  };
  const stdin = new Writable({
    write(chunk, _encoding, callback) {
      writes.push(chunk.toString());
      callback();
      writeEvents.emit("write");
    },
  });
  const destroyStdin = stdin.destroy.bind(stdin);
  stdin.destroy = ((error?: Error) => {
    stdinDestroyed = true;
    const result = destroyStdin(error);
    if (!exitEmitted && options.autoEmitExit !== false) {
      // Let stdin surface pipe errors before the harness emits the fake child exit.
      // Otherwise close-reason tests can race EPIPE against a synthetic clean exit.
      setImmediate(emitExit);
    }
    return result;
  }) as typeof stdin.destroy;
  const process: HarnessProcess = Object.assign(new EventEmitter(), {
    stdin,
    stdout,
    stderr: new PassThrough(),
    killed: false,
    kill: vi.fn((_signal?: NodeJS.Signals) => {
      process.killed = true;
    }),
  });
  emitProcessExit = () => {
    process.emit("exit", 0, null);
  };
  const client = CodexAppServerClient.fromTransportForTests(process);
  return {
    client,
    process,
    writes,
    async waitForWrite(index: number): Promise<string> {
      if (writes[index] !== undefined) {
        return writes[index];
      }
      return await new Promise<string>((resolve, reject) => {
        const cleanup = () => {
          clearTimeout(timer);
          writeEvents.off("write", onWrite);
        };
        const onWrite = () => {
          if (writes[index] !== undefined) {
            cleanup();
            resolve(writes[index]);
          }
        };
        const timer = setTimeout(() => {
          cleanup();
          reject(new Error(`Timed out waiting for app-server harness write ${index}`));
        }, 1_000);
        writeEvents.on("write", onWrite);
      });
    },
    get stdinDestroyed() {
      return stdinDestroyed;
    },
    emitExit,
    send(message: unknown) {
      stdout.write(`${JSON.stringify(message)}\n`);
    },
  };
}

import { normalizeBoundedOptionalString as readBoundedId } from "openclaw/plugin-sdk/string-coerce-runtime";
import { isJsonObject, type CodexThreadListParams } from "./protocol.js";
import type { CodexAppServerBindingStore } from "./session-binding.js";

const DESCENDANT_PAGE_LIMIT = 100;
const MAX_DESCENDANT_PAGES = 100;
const MAX_THREAD_ID_LENGTH = 256;
const MAX_CURSOR_LENGTH = 4096;

function readNextCursor(value: unknown): string | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== "string" || !value.trim() || value.length > MAX_CURSOR_LENGTH) {
    throw new Error("Codex app-server returned an invalid descendant-list cursor");
  }
  return value;
}

/**
 * Native archive includes the spawned subtree. Enumerate that same subtree first so an
 * OpenClaw-owned descendant cannot be stopped as an undocumented side effect.
 */
export async function assertCodexArchiveDescendantsUnowned(params: {
  bindingStore: CodexAppServerBindingStore;
  threadId: string;
  listPage: (request: CodexThreadListParams) => Promise<unknown>;
  assertDescendantIdle: (threadId: string) => Promise<void>;
}): Promise<void> {
  const ancestorThreadId = readBoundedId(params.threadId, MAX_THREAD_ID_LENGTH);
  if (!ancestorThreadId) {
    throw new Error("cannot verify Codex archive descendants for an invalid thread id");
  }

  const seenCursors = new Set<string>();
  const seenThreadIds = new Set<string>([ancestorThreadId]);
  let cursor: string | undefined;

  for (let pageIndex = 0; pageIndex < MAX_DESCENDANT_PAGES; pageIndex += 1) {
    const response = await params.listPage({
      ancestorThreadId,
      archived: false,
      limit: DESCENDANT_PAGE_LIMIT,
      sortKey: "created_at",
      sortDirection: "desc",
      useStateDbOnly: true,
      ...(cursor ? { cursor } : {}),
    });
    if (!isJsonObject(response) || !Array.isArray(response.data)) {
      throw new Error("Codex app-server returned an invalid descendant-list response");
    }
    if (response.data.length > DESCENDANT_PAGE_LIMIT) {
      throw new Error("Codex app-server exceeded the descendant-list page limit");
    }

    for (const value of response.data) {
      if (!isJsonObject(value)) {
        throw new Error("Codex app-server returned an invalid descendant thread");
      }
      const descendantThreadId = readBoundedId(value.id, MAX_THREAD_ID_LENGTH);
      if (!descendantThreadId) {
        throw new Error("Codex app-server returned a descendant without a valid thread id");
      }
      if (seenThreadIds.has(descendantThreadId)) {
        throw new Error("Codex app-server returned a cyclic descendant thread list");
      }
      seenThreadIds.add(descendantThreadId);
      await params.assertDescendantIdle(descendantThreadId);
      if (await params.bindingStore.hasOtherThreadOwner(descendantThreadId)) {
        throw new Error(
          "cannot archive a Codex thread while a spawned descendant is owned by an OpenClaw session",
        );
      }
    }

    const nextCursor = readNextCursor(response.nextCursor);
    if (!nextCursor) {
      return;
    }
    if (seenCursors.has(nextCursor)) {
      throw new Error("Codex app-server returned a repeated descendant-list cursor");
    }
    seenCursors.add(nextCursor);
    cursor = nextCursor;
  }

  throw new Error("Codex descendant enumeration exceeded its safety limit");
}

import type { CodexAppServerConnectionClass } from "./config-contracts.js";
import { normalizeCodexDynamicToolName } from "./dynamic-tool-profile.js";
import type { CodexAppServerThreadBinding } from "./session-binding.js";
import type {
  CodexPluginThreadConfigProvider,
  CodexStartOrResumeThreadParams,
} from "./thread-lifecycle-types.js";

export function shouldRotateCodexAppServerBindingForRuntime(params: {
  connectionClass: CodexAppServerConnectionClass;
  current?: string;
  binding?: string;
}): boolean {
  if (!params.current) {
    return false;
  }
  if (params.binding === params.current) {
    return false;
  }
  return params.connectionClass === "remote" || Boolean(params.binding);
}

type CodexGpt56MultiAgentVersion = "v1" | "v2";

export function resolveCodexGpt56MultiAgentVersion(
  modelRef: string | undefined,
): CodexGpt56MultiAgentVersion | undefined {
  let modelId = modelRef?.trim().toLowerCase();
  if (!modelId) {
    return undefined;
  }
  const slashIndex = modelId.indexOf("/");
  if (slashIndex > 0) {
    const provider = modelId.slice(0, slashIndex);
    if (provider !== "openai" && provider !== "codex") {
      return undefined;
    }
    modelId = modelId.slice(slashIndex + 1);
  }
  if (modelId === "gpt-5.6-sol" || modelId === "gpt-5.6-terra") {
    return "v2";
  }
  return modelId === "gpt-5.6-luna" ? "v1" : undefined;
}

export function shouldRotateCodexGpt56MultiAgentBinding(params: {
  bindingModel?: string;
  requestedModel: string;
}): boolean {
  const bindingVersion = resolveCodexGpt56MultiAgentVersion(params.bindingModel);
  const requestedVersion = resolveCodexGpt56MultiAgentVersion(params.requestedModel);
  return Boolean(bindingVersion && requestedVersion && bindingVersion !== requestedVersion);
}

export function isTransientWebSearchRestriction(
  params: Pick<
    CodexStartOrResumeThreadParams,
    | "params"
    | "nativeCodeModeEnabled"
    | "nativeProviderWebSearchSupport"
    | "persistentWebSearchAllowed"
    | "webSearchAllowed"
  >,
): boolean {
  if (params.nativeProviderWebSearchSupport === "unknown") {
    return true;
  }
  if (params.params.config?.tools?.web?.search?.enabled === false) {
    return false;
  }
  if (params.params.disableTools === true) {
    return true;
  }
  const persistentWebSearchRestriction =
    params.webSearchAllowed === false && params.persistentWebSearchAllowed === false;
  if (params.nativeCodeModeEnabled === false && !persistentWebSearchRestriction) {
    return true;
  }
  if (params.webSearchAllowed !== false) {
    return false;
  }
  if (params.persistentWebSearchAllowed !== undefined) {
    return params.persistentWebSearchAllowed;
  }
  if (params.params.toolsAllow === undefined) {
    return false;
  }
  return !params.params.toolsAllow.some((name) => {
    const normalized = normalizeCodexDynamicToolName(name);
    return normalized === "*" || normalized === "web_search";
  });
}
export function shouldRecheckRecoverablePluginBinding(params: {
  binding: CodexAppServerThreadBinding;
  pluginThreadConfig?: CodexPluginThreadConfigProvider;
}): boolean {
  if (!params.pluginThreadConfig?.enabled) {
    return false;
  }
  if (
    !params.binding.pluginAppsFingerprint ||
    !params.binding.pluginAppsInputFingerprint ||
    params.binding.pluginAppsInputFingerprint !== params.pluginThreadConfig.inputFingerprint
  ) {
    return false;
  }
  const policyContext = params.binding.pluginAppPolicyContext;
  if (!policyContext) {
    return false;
  }
  const enabledPluginConfigKeys = params.pluginThreadConfig.enabledPluginConfigKeys ?? [];
  const recoverablePluginConfigKeys =
    params.pluginThreadConfig.recoverablePluginConfigKeys ?? enabledPluginConfigKeys;
  const recoverablePluginConfigKeySet = new Set(recoverablePluginConfigKeys);
  const settledPluginConfigKeys = enabledPluginConfigKeys.filter(
    (configKey) => !recoverablePluginConfigKeySet.has(configKey),
  );
  const bindingContainsSettledPlugin = settledPluginConfigKeys.some(
    (configKey) =>
      (policyContext.pluginAppIds[configKey]?.length ?? 0) > 0 ||
      Object.values(policyContext.apps).some(
        (app) => app.source !== "account" && app.configKey === configKey,
      ),
  );
  const accountAppRecoveryEnabled =
    params.pluginThreadConfig.accountAppRecoveryEnabled ?? enabledPluginConfigKeys.length === 0;
  return (
    bindingContainsSettledPlugin ||
    (accountAppRecoveryEnabled && Object.keys(policyContext.apps).length === 0) ||
    recoverablePluginConfigKeys.length > 0
  );
}

import {
  isActiveHarnessContextEngine,
  type EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { isRecord } from "openclaw/plugin-sdk/string-coerce-runtime";
import {
  resolveCodexContextEngineProjectionMaxChars,
  resolveCodexContextEngineProjectionReserveTokens,
} from "./context-engine-projection.js";
import type { JsonValue } from "./protocol.js";
import type {
  CodexAppServerContextEngineBinding,
  CodexAppServerContextEngineProjectionBinding,
} from "./session-binding.js";

export type CodexContextEngineThreadBootstrapProjection = {
  mode: "thread_bootstrap";
  epoch: string;
  fingerprint?: string;
};

export function buildContextEngineBinding(
  params: EmbeddedRunAttemptParams,
  projection?: CodexContextEngineThreadBootstrapProjection,
): CodexAppServerContextEngineBinding | undefined {
  const contextEngine = isActiveHarnessContextEngine(params.contextEngine)
    ? params.contextEngine
    : undefined;
  const engineId = contextEngine?.info?.id?.trim();
  if (!contextEngine || !engineId) {
    return undefined;
  }
  return {
    schemaVersion: 1,
    engineId,
    policyFingerprint: JSON.stringify({
      schemaVersion: 1,
      engineId,
      engineVersion: contextEngine.info.version,
      ownsCompaction: contextEngine.info.ownsCompaction === true,
      turnMaintenanceMode: contextEngine.info.turnMaintenanceMode,
      citationsMode: resolveContextEngineCitationsMode(params.config),
      contextTokenBudget: params.contextTokenBudget,
      projectionMaxChars: resolveCodexContextEngineProjectionMaxChars({
        contextTokenBudget: params.contextTokenBudget,
        reserveTokens: resolveCodexContextEngineProjectionReserveTokens(),
      }),
    }),
    projection: projection ? buildContextEngineProjectionBinding(projection) : undefined,
  };
}

function buildContextEngineProjectionBinding(
  projection: CodexContextEngineThreadBootstrapProjection,
): CodexAppServerContextEngineProjectionBinding {
  return {
    schemaVersion: 1,
    mode: "thread_bootstrap",
    epoch: projection.epoch,
    fingerprint: projection.fingerprint,
  };
}

export function isContextEngineBindingCompatible(
  previous: CodexAppServerContextEngineBinding | undefined,
  next: CodexAppServerContextEngineBinding,
): boolean {
  return (
    previous?.schemaVersion === next.schemaVersion &&
    previous.engineId === next.engineId &&
    previous.policyFingerprint === next.policyFingerprint &&
    areContextEngineProjectionBindingsCompatible(previous.projection, next.projection)
  );
}

function areContextEngineProjectionBindingsCompatible(
  previous: CodexAppServerContextEngineProjectionBinding | undefined,
  next: CodexAppServerContextEngineProjectionBinding | undefined,
): boolean {
  if (!next) {
    return previous === undefined;
  }
  return (
    previous?.schemaVersion === next.schemaVersion &&
    previous.mode === next.mode &&
    previous.epoch === next.epoch &&
    previous.fingerprint === next.fingerprint
  );
}

function resolveContextEngineCitationsMode(config: unknown): JsonValue | undefined {
  const rootConfig = isRecord(config) ? config : undefined;
  const memoryConfig = isRecord(rootConfig?.memory) ? rootConfig.memory : undefined;
  const citations = memoryConfig?.citations;
  return isJsonConfigValue(citations) ? citations : undefined;
}

function isJsonConfigValue(value: unknown): value is JsonValue {
  if (value === null || typeof value === "string" || typeof value === "boolean") {
    return true;
  }
  if (typeof value === "number") {
    return Number.isFinite(value);
  }
  if (Array.isArray(value)) {
    return value.every(isJsonConfigValue);
  }
  return isRecord(value) && Object.values(value).every(isJsonConfigValue);
}

import { describe, expect, it } from "vitest";
