  readCodexInheritedMcpServerNames,
} from "./thread-requests.js";
import { resolveCodexWebSearchPlan } from "./web-search.js";

export async function prepareCodexThreadLifecyclePreflight(params: CodexStartOrResumeThreadParams) {
  await assertCodexModelBackedReviewerEffectiveConfig({
    client: params.client,
    approvalsReviewer: params.appServer.approvalsReviewer,
    cwd: params.cwd,
    signal: params.signal,
  });
  if (params.nativeHookRelayRequired) {
    await assertCodexNativeHookRelayAllowed(params.client, params.signal);
  }
  // Thread lifecycle spans are useful when profiling startup churn, but normal
  // turns should not pay Date.now/span-array overhead while resuming threads.
  const lifecycleTiming = createCodexThreadLifecycleTimingTracker({
    ...params.timing,
    enabled: params.timing?.enabled ?? isCodexAppServerProfilerEnabled(params.params.config),
  });
  const legacyDynamicToolsFingerprint = lifecycleTiming.measureSync(
    "legacy-dynamic-tools-fingerprint",
    () => legacyFingerprintDynamicTools(params.dynamicTools),
  );
  const dynamicToolsFingerprint = lifecycleTiming.measureSync("dynamic-tools-fingerprint", () =>
    hashCodexAppServerBindingFingerprint(legacyDynamicToolsFingerprint),
  );
  const dynamicToolsContainDeferred = flattenCodexDynamicToolFunctions(params.dynamicTools).some(
    (tool) => tool.deferLoading === true,
  );
  const webSearchPlan = lifecycleTiming.measureSync("web-search-plan", () =>
    resolveCodexWebSearchPlan({
      config: params.params.config,
      disableTools: params.params.disableTools,
      nativeToolSurfaceEnabled: params.nativeCodeModeEnabled,
      nativeProviderWebSearchSupport: params.nativeProviderWebSearchSupport,
      webSearchAllowed: params.webSearchAllowed,
    }),
  );
  const webSearchThreadConfigFingerprint = fingerprintJsonObject(webSearchPlan.threadConfig);
  const networkProxyConfigFingerprint = params.appServer.networkProxy?.configFingerprint;
  const contextEngineBinding = lifecycleTiming.measureSync("context-engine-binding", () =>
    buildContextEngineBinding(params.params, params.contextEngineProjection),
  );
  const userMcpServersConfigPatch =
    params.userMcpServersEnabled === false
      ? undefined
      : await buildCodexUserMcpServersThreadConfigPatchForRun({
          run: params.params,
          cwd: params.cwd,
          agentId: params.agentId ?? params.params.agentId,
          allowLiteralOAuthProjection: params.appServer.connectionClass !== "remote",
          warn: (message) => embeddedAgentLog.warn(message),
          onServerUnavailable: (serverName, error) =>
            embeddedAgentLog.warn("skipping unavailable MCP OAuth server", {
              serverName,
              error: formatErrorMessage(error),
            }),
        });
  const nativeSkillIsolation = await lifecycleTiming.measure("native-skill-isolation", () =>
    resolveCodexNativeSkillIsolation({
      client: params.client,
      codexHome: params.appServer.start.env?.CODEX_HOME,
      cwd: params.cwd,
      home: params.appServer.start.env?.HOME,
      signal: params.signal,
      userProfile: params.appServer.start.env?.USERPROFILE,
    }),
  );
  const nativeSkillIsolationFingerprint = nativeSkillIsolation
    ? fingerprintJsonObject({
        version: 1,
        disabledUserSkillPaths: nativeSkillIsolation.disabledUserSkillPaths,
      })
    : undefined;
  const legacyUserMcpServersFingerprint =
    legacyFingerprintUserMcpServersConfigPatch(userMcpServersConfigPatch);
  const userMcpServersFingerprint = fingerprintUserMcpServersConfigPatch(userMcpServersConfigPatch);
  const environmentSelectionFingerprint = fingerprintEnvironmentSelection(
    params.environmentSelection,
  );
  const hostSystemAgentActive =
    params.hostSystemAgentActive ?? isHostScopedAgentToolActive("openclaw");
  const ringZeroActive =
    hostSystemAgentActive && isSystemAgentOnlyCodexDynamicToolAllowlist(params.params.toolsAllow);
  const messageOnlySourceReply = isMessageOnlyCodexSourceReply(params.params);
  const restrictedToolSurface =
    ringZeroActive ||
    messageOnlySourceReply ||
    params.params.pluginHarnessToolPolicyRestricted === true;
  const imageGenerationDenied =
    params.params.pluginHarnessToolPolicySafeDeniedTools?.includes("image_generate") === true;
  if (restrictedToolSurface && params.nativeCodeModeEnabled !== false) {
    throw new Error("Codex restricted tool surfaces require native code mode to be disabled");
  }
  const restrictedToolSurfaceInheritedMcpServerNames = restrictedToolSurface
    ? await lifecycleTiming.measure("restricted-tool-surface-mcp-config-read", () =>
        readCodexInheritedMcpServerNames(params.client, params.cwd, params.signal),
      )
    : [];
  if (restrictedToolSurface || imageGenerationDenied) {
    await lifecycleTiming.measure("tool-policy-config-requirements-read", () =>
      assertCodexManagedRequirementsDoNotOverrideToolPolicy(
        params.client,
        {
          restrictedToolSurface,
          additionalDeniedFeatures: imageGenerationDenied ? ["image_generation"] : undefined,
        },
        params.signal,
      ),
    );
  }
  const ringZeroConfigFingerprint = ringZeroActive
    ? fingerprintJsonObject({
        version: 1,
        baseInstructions: CODEX_RING_ZERO_BASE_INSTRUCTIONS,
        config: buildCodexRingZeroThreadConfigPatch(
          params.params,
          true,
          restrictedToolSurfaceInheritedMcpServerNames,
        )!,
      })
    : undefined;
  const ringZeroClientInstanceId = ringZeroActive
    ? getCodexAppServerClientInstanceId(params.client)
    : undefined;
  return {
    contextEngineBinding,
    dynamicToolsContainDeferred,
    dynamicToolsFingerprint,
    environmentSelectionFingerprint,
    hostSystemAgentActive,
    legacyDynamicToolsFingerprint,
    legacyUserMcpServersFingerprint,
    lifecycleTiming,
    nativeSkillIsolation,
    nativeSkillIsolationFingerprint,
    networkProxyConfigFingerprint,
    ringZeroActive,
    ringZeroClientInstanceId,
    ringZeroConfigFingerprint,
    restrictedToolSurface,
    restrictedToolSurfaceInheritedMcpServerNames,
    userMcpServersConfigPatch,
    userMcpServersFingerprint,
    webSearchThreadConfigFingerprint,
  };
}

import type { CodexPluginThreadConfig } from "./plugin-thread-config.js";
import type { CodexThreadStartParams, CodexThreadStartResponse } from "./protocol.js";
import type { CodexAppServerContextEngineBinding } from "./session-binding.js";
import { fingerprintCodexThreadConfig } from "./thread-fingerprints.js";
import type {
  CodexAppServerThreadLifecycleBinding,
  CodexStartOrResumeThreadParams,
} from "./thread-lifecycle-types.js";

type StartedThreadContext = {
  contextEngineBinding?: CodexAppServerContextEngineBinding;
  dynamicToolsContainDeferred: boolean;
  dynamicToolsFingerprint: string;
  environmentSelectionFingerprint?: string;
  nativeSkillIsolationFingerprint?: string;
  networkProxyConfigFingerprint?: string;
  preserveExistingBinding: boolean;
  ringZeroClientInstanceId?: string;
  ringZeroConfigFingerprint?: string;
  rotatedContextEngineBinding: boolean;
  userMcpServersFingerprint?: string;
};

/** Materializes the public lifecycle result after a fresh thread is durably committed. */
export function buildStartedCodexThreadBinding(input: {
  bindingModelProvider?: string;
  clientId?: string;
  context: StartedThreadContext;
  finalConfigPatch: { nativeHookRelayGeneration?: string };
  nextMcpServersFingerprint?: string;
  params: CodexStartOrResumeThreadParams;
  pluginThreadConfig?: CodexPluginThreadConfig;
  response: CodexThreadStartResponse;
  rolloutPath?: string;
  startModelProvider?: string;
  startParams: CodexThreadStartParams;
  modelProvider?: string;
}): CodexAppServerThreadLifecycleBinding {
  const { context, params, response, startParams } = input;
  return {
    threadId: response.thread.id,
    ...(input.clientId ? { clientId: input.clientId } : {}),
    cwd: params.cwd,
    ...(input.rolloutPath ? { rolloutPath: input.rolloutPath } : {}),
    authProfileId: params.params.authProfileId,
    agentWorkspaceDeveloperInstructions: params.agentWorkspaceDeveloperInstructions,
    model: response.model ?? startParams.model ?? params.params.modelId,
    modelProvider: response.modelProvider ?? input.startModelProvider ?? input.modelProvider,
    dynamicToolsFingerprint: context.dynamicToolsFingerprint,
    dynamicToolsContainDeferred: context.dynamicToolsContainDeferred,
    nativeSkillIsolationFingerprint: context.nativeSkillIsolationFingerprint,
    userMcpServersFingerprint: context.userMcpServersFingerprint,
    mcpServersFingerprint: input.nextMcpServersFingerprint,
    configuredMcpOwnershipVersion: params.configuredMcpOwnershipVersion,
    ringZeroConfigFingerprint: context.ringZeroConfigFingerprint,
    ringZeroClientInstanceId: context.ringZeroClientInstanceId,
    networkProxyProfileName: params.appServer.networkProxy?.profileName,
    networkProxyConfigFingerprint: context.networkProxyConfigFingerprint,
    nativeHookRelayGeneration: input.finalConfigPatch.nativeHookRelayGeneration,
    appServerRuntimeFingerprint: params.appServerRuntimeFingerprint,
    pluginAppsFingerprint: input.pluginThreadConfig?.fingerprint,
    pluginAppsInputFingerprint: input.pluginThreadConfig?.inputFingerprint,
    pluginAppPolicyContext: input.pluginThreadConfig?.policyContext,
    contextEngine: context.contextEngineBinding,
    environmentSelectionFingerprint: context.environmentSelectionFingerprint,
    // Transient starts do not own the persisted binding, so their native
    // subscriptions must be released instead of entering the warm cache.
    ...(!context.preserveExistingBinding
      ? {
          liveThreadConfigFingerprint: fingerprintCodexThreadConfig(
            {
              ...startParams,
              model: response.model ?? startParams.model ?? null,
              requestedModel: startParams.model ?? null,
              modelProvider: input.bindingModelProvider ?? null,
              requestedModelProvider:
                startParams.modelProvider ?? input.bindingModelProvider ?? null,
            },
            params.params.authProfileId,
            context.dynamicToolsFingerprint,
          ),
        }
      : {}),
    lifecycle: {
      action: "started",
      ...(context.rotatedContextEngineBinding ? { rotatedContextEngineBinding: true } : {}),
    },
  };
}

import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import { isIncognitoSessionKey } from "../incognito-session.js";
import { closeCodexStartupClientBestEffort } from "./attempt-client-cleanup.js";
import { isCodexAppServerLiveThreadClaimed } from "./client-runtime.js";
import { resolveCodexAppServerClientInstanceId } from "./client.js";
import { applyCodexNativeSkillIsolation } from "./native-skill-isolation.js";
import { buildCodexAppServerConnectionFingerprint } from "./plugin-app-cache-key.js";
import {
  isCodexPluginThreadBindingStale,
  mergeCodexThreadConfigs,
  type CodexPluginThreadConfig,
} from "./plugin-thread-config.js";
import {
  assertCodexBindingMayBeReplaced,
  createCodexSessionGenerationSupersededError,
  normalizeCodexAppServerBindingModelProvider,
  reclaimCurrentCodexSessionGeneration,
  type CodexAppServerPendingSupervisionBranch,
  type CodexAppServerThreadBinding,
} from "./session-binding.js";
import {
  captureExclusiveSharedCodexAppServerClient,
  retainSharedCodexAppServerClientByInstanceId,
} from "./shared-client.js";
import {
  isTransientWebSearchRestriction,
  shouldRecheckRecoverablePluginBinding,
  shouldRotateCodexAppServerBindingForRuntime,
  shouldRotateCodexGpt56MultiAgentBinding,
} from "./thread-binding-policy.js";
import { isContextEngineBindingCompatible } from "./thread-context-engine.js";
import {
  areDynamicToolFingerprintsCompatible,
  areUserMcpServersFingerprintsCompatible,
  shouldStartTransientNoToolThread,
} from "./thread-fingerprints.js";
import {
  assertAdoptedCodexThreadResumeAllowed,
  resumePendingCodexThread,
  withCodexThreadLifecycleBinding,
} from "./thread-lifecycle-adoption.js";
import { CodexThreadBindingConflictError } from "./thread-lifecycle-errors.js";
import { resumeExistingCodexThread, startFreshCodexThread } from "./thread-lifecycle-io.js";
import { prepareCodexThreadLifecyclePreflight } from "./thread-lifecycle-preflight.js";
import type {
  CodexAppServerThreadLifecycleBinding,
  CodexStartOrResumeThreadParams,
} from "./thread-lifecycle-types.js";
import {
  releaseCodexRetainedLiveThread,
  throwIfCodexThreadLifecycleAborted,
  tryReuseCodexLiveThread,
} from "./thread-lifecycle-warm.js";
import { resolveCodexAppServerThreadModelSelection } from "./thread-model-selection.js";
import { materializePendingSupervisionBranch } from "./thread-supervision.js";

export async function startOrResumeThread(
  params: CodexStartOrResumeThreadParams,
): Promise<CodexAppServerThreadLifecycleBinding> {
  const incognito = isIncognitoSessionKey(params.params.sessionKey);
  const clientId = resolveCodexAppServerClientInstanceId(params.client);
  return await withCodexThreadLifecycleBinding(params, async (bindingIdentity, currentBinding) => {
    let binding = currentBinding;
    const preflight = await prepareCodexThreadLifecyclePreflight(params);
    const {
      contextEngineBinding,
      dynamicToolsContainDeferred,
      dynamicToolsFingerprint,
      environmentSelectionFingerprint,
      hostSystemAgentActive,
      legacyDynamicToolsFingerprint,
      legacyUserMcpServersFingerprint,
      lifecycleTiming,
      nativeSkillIsolation,
      nativeSkillIsolationFingerprint,
      networkProxyConfigFingerprint,
      ringZeroActive,
      ringZeroClientInstanceId,
      ringZeroConfigFingerprint,
      restrictedToolSurface,
      restrictedToolSurfaceInheritedMcpServerNames,
      userMcpServersConfigPatch,
      userMcpServersFingerprint,
      webSearchThreadConfigFingerprint,
    } = preflight;
    let replacementPredecessor: CodexAppServerThreadBinding | undefined;
    const initialBoundThreadId = binding?.threadId;
    const initialBoundClientId = binding?.clientId;
    const normalizeBindingModelProvider = (
      authProfileId: string | undefined,
      modelProvider: string | undefined,
    ) =>
      normalizeCodexAppServerBindingModelProvider({
        authProfileId,
        modelProvider,
        authProfileStore: params.params.authProfileStore,
        agentDir: params.params.agentDir,
        config: params.params.config,
      });
    const throwIfAborted = () => throwIfCodexThreadLifecycleAborted(params.signal);
    const releaseRetainedThread = async (
      threadId: string,
      ownerClientId = initialBoundClientId,
      assertCurrent?: () => void,
    ) => {
      if (ownerClientId && ownerClientId !== clientId) {
        // Auth/runtime rotation selects a new physical client, but its map
        // cannot release a subscription owned by the previous app-server.
        const previousClient = retainSharedCodexAppServerClientByInstanceId(ownerClientId);
        if (!previousClient) {
          return false;
        }
        try {
          const assertPrevious = assertCurrent
            ? captureExclusiveSharedCodexAppServerClient(previousClient.client)
            : undefined;
          if (isCodexAppServerLiveThreadClaimed(previousClient.client, threadId)) {
            throw new Error(`Codex thread ${threadId} is claimed by active work; stop it first.`);
          }
          return await releaseCodexRetainedLiveThread({
            client: previousClient.client,
            lifecycleTiming,
            threadId,
            assertCurrent: assertCurrent
              ? () => {
                  assertCurrent();
                  assertPrevious?.();
                }
              : undefined,
          });
        } finally {
          previousClient.release();
        }
      }
      if (isCodexAppServerLiveThreadClaimed(params.client, threadId)) {
        throw new Error(`Codex thread ${threadId} is claimed by active work; stop it first.`);
      }
      return await releaseCodexRetainedLiveThread({
        client: params.client,
        abandonClient: params.abandonClient,
        lifecycleTiming,
        threadId,
        assertCurrent,
      });
    };
    if (!binding && bindingIdentity.kind === "session" && bindingIdentity.sessionKey) {
      // Reset may rotate the OpenClaw session while this plugin is unloaded. Only
      // the authoritative session store may let its successor displace that stale owner.
      const reclaimed = await lifecycleTiming.measure("reclaim-binding-generation", () =>
        reclaimCurrentCodexSessionGeneration({
          bindingStore: params.bindingStore,
          identity: bindingIdentity,
          config: params.params.config,
        }),
      );
      if (!reclaimed) {
        throw createCodexSessionGenerationSupersededError(bindingIdentity.sessionId);
      }
    }
    if (binding?.pendingSupervisionBranch) {
      await releaseRetainedThread(binding.threadId);
      const pendingBinding = binding as CodexAppServerThreadBinding & {
        pendingSupervisionBranch: CodexAppServerPendingSupervisionBranch;
      };
      const pluginThreadConfig = params.pluginThreadConfig?.enabled
        ? await lifecycleTiming.measure("plugin-config-build", () =>
            params.pluginThreadConfig?.build(),
          )
        : undefined;
      const finalConfigPatch = params.buildFinalConfigPatch?.({ action: "start" }) ?? {
        configPatch: params.finalConfigPatch,
        nativeHookRelayGeneration: params.nativeHookRelayGeneration,
      };
      const config = lifecycleTiming.measureSync("merge-thread-config", () =>
        applyCodexNativeSkillIsolation(
          mergeCodexThreadConfigs(
            params.config,
            userMcpServersConfigPatch,
            pluginThreadConfig?.configPatch,
            finalConfigPatch.configPatch,
          ),
          nativeSkillIsolation,
        ),
      );
      return await materializePendingSupervisionBranch({
        client: params.client,
        abandonClient:
          params.abandonClient ?? (() => closeCodexStartupClientBestEffort(params.client)),
        bindingStore: params.bindingStore,
        bindingIdentity,
        binding: pendingBinding,
        attempt: params.params,
        cwd: params.cwd,
        dynamicTools: params.dynamicTools,
        appServer: params.appServer,
        developerInstructions: params.developerInstructions,
        config,
        nativeCodeModeEnabled: params.nativeCodeModeEnabled,
        nativeProviderWebSearchSupport: params.nativeProviderWebSearchSupport,
        nativeCodeModeOnlyEnabled: params.nativeCodeModeOnlyEnabled,
        webSearchAllowed: params.webSearchAllowed,
        hostSystemAgentActive,
        restrictedToolSurface,
        restrictedToolSurfaceInheritedMcpServerNames,
        shellEnvironment: params.shellEnvironment,
        disableLoginShell: params.disableLoginShell,
        environmentSelection: params.environmentSelection,
        provisionalAppIds: pluginThreadConfig?.provisionalAppIds,
        signal: params.signal,
        throwIfAborted,
        lifecycleTiming,
        normalizeBindingModelProvider,
        bindingPatch: {
          cwd: params.cwd,
          ...(clientId ? { clientId } : {}),
          // Supervised threads stay on the native user-home connection. Never
          // persist an outer OpenClaw auth profile onto that private ownership.
          authProfileId: undefined,
          agentWorkspaceDeveloperInstructions: params.agentWorkspaceDeveloperInstructions,
          preserveNativeModel: true,
          dynamicToolsFingerprint,
          dynamicToolsContainDeferred,
          webSearchThreadConfigFingerprint,
          nativeSkillIsolationFingerprint,
          userMcpServersFingerprint,
          mcpServersFingerprint:
            params.mcpServersFingerprintEvaluated === true
              ? params.mcpServersFingerprint
              : pendingBinding.mcpServersFingerprint,
          configuredMcpOwnershipVersion: params.configuredMcpOwnershipVersion,
          networkProxyProfileName: params.appServer.networkProxy?.profileName,
          networkProxyConfigFingerprint,
          nativeHookRelayGeneration: finalConfigPatch.nativeHookRelayGeneration,
          appServerRuntimeFingerprint: buildCodexAppServerConnectionFingerprint(
            params.appServer,
            params.params.agentDir,
          ),
          pluginAppsFingerprint: pluginThreadConfig?.fingerprint,
          pluginAppsInputFingerprint: pluginThreadConfig?.inputFingerprint,
          pluginAppPolicyContext: pluginThreadConfig?.policyContext,
          contextEngine: contextEngineBinding,
          environmentSelectionFingerprint,
          conversationSourceTransferComplete: true,
        },
      });
    }
    const clearCurrentBinding = async (operation: string) => {
      const current = binding;
      if (!current?.threadId) {
        return;
      }
      assertCodexBindingMayBeReplaced(current, operation);
      const cleared = await params.bindingStore.mutate(bindingIdentity, {
        kind: "clear",
        threadId: current.threadId,
      });
      if (!cleared) {
        throw new CodexThreadBindingConflictError(current.threadId, operation);
      }
      binding = undefined;
    };
    const resolveRequestContext = () => {
      const startModelSelection = resolveCodexAppServerThreadModelSelection({
        provider: params.params.provider,
        model: params.runtimeModelId ?? params.params.modelId,
        binding,
        authProfileId: params.params.authProfileId,
        authProfileStore: params.params.authProfileStore,
        agentDir: params.params.agentDir,
        config: params.params.config,
      });
      return {
        ...preflight,
        bindingIdentity,
        startModelSelection,
        startModelProvider: startModelSelection.modelProvider,
        normalizeBindingModelProvider,
        throwIfAborted,
      };
    };
    const transientDelegationRestriction = params.params.delegationCapability === "report_only";
    const persistentWebSearchRestriction =
      params.webSearchAllowed === false && params.persistentWebSearchAllowed === false;
    const transientNativeToolRestriction =
      params.nativeCodeModeEnabled === false && !persistentWebSearchRestriction;
    const transientWebSearchRestriction = isTransientWebSearchRestriction(params);
    if (binding?.pendingResumeConfiguration) {
      return await resumePendingCodexThread(params, {
        ...resolveRequestContext(),
        binding,
        clearCurrentBinding,
        releaseRetainedThread: (threadId, assertCurrent) =>
          releaseRetainedThread(threadId, initialBoundClientId, assertCurrent),
        transientRestriction:
          transientDelegationRestriction ||
          transientNativeToolRestriction ||
          transientWebSearchRestriction,
      });
    }

    if (
      binding?.threadId &&
      !restrictedToolSurface &&
      binding.nativeToolPolicyRestricted === true
    ) {
      await clearCurrentBinding("rotating a host-policy-restricted thread binding");
    }
    if (
      binding?.threadId &&
      binding.nativeSkillIsolationFingerprint !== nativeSkillIsolationFingerprint
    ) {
      embeddedAgentLog.debug(
        "codex app-server native skill isolation changed; starting a new thread",
        { threadId: binding.threadId },
      );
      await clearCurrentBinding("rotating stale native skill isolation");
    }
    if (
      binding?.threadId &&
      (binding.ringZeroConfigFingerprint !== ringZeroConfigFingerprint ||
        binding.ringZeroClientInstanceId !== ringZeroClientInstanceId) &&
      (ringZeroActive || binding.ringZeroConfigFingerprint !== undefined)
    ) {
      // Resume config cannot safely change a loaded Codex thread. Reuse a
      // ring-zero thread only when its creation-time restrictions still match.
      embeddedAgentLog.debug("codex app-server ring-zero restriction changed; rotating thread", {
        threadId: binding.threadId,
      });
      await clearCurrentBinding("rotating a ring-zero thread binding");
    }
    if (
      binding?.threadId &&
      shouldRotateCodexAppServerBindingForRuntime({
        connectionClass: params.appServer.connectionClass,
        current:
          binding.connectionScope === "supervision"
            ? buildCodexAppServerConnectionFingerprint(params.appServer, params.params.agentDir)
            : params.appServerRuntimeFingerprint,
        binding: binding.appServerRuntimeFingerprint,
      })
    ) {
      embeddedAgentLog.debug("codex app-server runtime identity changed; starting a new thread", {
        threadId: binding.threadId,
        connectionClass: params.appServer.connectionClass,
      });
      await clearCurrentBinding("rotating a stale thread binding");
      binding = undefined;
    }
    if (
      binding?.threadId &&
      shouldRotateCodexGpt56MultiAgentBinding({
        bindingModel: binding.model,
        requestedModel: params.params.modelId,
      })
    ) {
      // Codex locks the model-selected multi-agent version on the first turn.
      // Sol/Terra (V2) and Luna (V1) therefore cannot share one resumed thread.
      embeddedAgentLog.debug(
        "codex app-server GPT-5.6 multi-agent version changed; starting a new thread",
        {
          threadId: binding.threadId,
          bindingModel: binding.model,
          requestedModel: params.params.modelId,
        },
      );
      await clearCurrentBinding("rotating a GPT-5.6 multi-agent thread binding");
      binding = undefined;
    }
    const requestContext = resolveRequestContext();
    // Capability read failures use managed search for this turn but must not
    // create a binding that later looks like a confirmed provider-policy change.
    let preserveExistingBinding =
      transientDelegationRestriction ||
      (!ringZeroActive &&
        params.nativeProviderWebSearchSupport === "unknown" &&
        !binding?.threadId);
    let rotatedContextEngineBinding = false;
    let prebuiltPluginThreadConfig: CodexPluginThreadConfig | undefined;
    // Scoped inventory requires a loaded native thread. The warm/resume owner
    // calls this only after acquiring that exact subscription, before admission.
    const buildLoadedPluginThreadConfig = async (
      current: CodexAppServerThreadBinding,
    ): Promise<CodexPluginThreadConfig | undefined> => {
      if (
        !params.pluginThreadConfig?.requiresCurrentPolicyCheck &&
        !shouldRecheckRecoverablePluginBinding({
          binding: current,
          pluginThreadConfig: params.pluginThreadConfig,
        })
      ) {
        return undefined;
      }
      try {
        prebuiltPluginThreadConfig = await lifecycleTiming.measure("plugin-config-recovery", () =>
          params.pluginThreadConfig?.build({ threadId: current.threadId }),
        );
      } catch (error) {
        throwIfAborted();
        if (params.pluginThreadConfig?.requiresCurrentPolicyCheck) {
          throw error;
        }
        embeddedAgentLog.warn("codex app-server plugin app config recovery check failed", {
          error,
          threadId: current.threadId,
        });
        return undefined;
      }
      throwIfAborted();
      return prebuiltPluginThreadConfig;
    };
    const webSearchBindingChanged =
      binding?.threadId &&
      binding.webSearchThreadConfigFingerprint !== webSearchThreadConfigFingerprint;
    const explicitTransientWebSearchRestriction =
      params.webSearchAllowed === false &&
      params.persistentWebSearchAllowed !== false &&
      transientWebSearchRestriction;
    const unknownProviderWebSearchSupport = params.nativeProviderWebSearchSupport === "unknown";
    const configuredMcpOwnershipChanged =
      binding?.threadId &&
      ((params.configuredMcpOwnershipVersion === 1 &&
        (binding.configuredMcpOwnershipVersion !== 1 ||
          binding.dynamicToolsFingerprint === undefined ||
          binding.mcpServersFingerprint !== undefined ||
          binding.userMcpServersFingerprint !== undefined)) ||
        (params.configuredMcpOwnershipVersion !== 1 &&
          binding.configuredMcpOwnershipVersion === 1));
    if (configuredMcpOwnershipChanged && binding?.threadId) {
      const predecessorBinding = binding;
      // Scheduled configured MCP moved from Codex-native config to OpenClaw dynamic tools.
      // A persistent main/named session has one binding: rotate its exact predecessor instead
      // of retaining native and scheduled variants that could diverge or widen authority.
      assertCodexBindingMayBeReplaced(predecessorBinding, "changing configured MCP ownership");
      embeddedAgentLog.debug(
        "codex app-server configured MCP ownership changed; starting a new thread",
        { threadId: predecessorBinding.threadId },
      );
      replacementPredecessor = predecessorBinding;
      binding = undefined;
      preserveExistingBinding = false;
    }
    if (
      binding?.threadId &&
      params.mcpServersFingerprintEvaluated === true &&
      binding.mcpServersFingerprint !== params.mcpServersFingerprint
    ) {
      assertCodexBindingMayBeReplaced(binding, "changing MCP configuration");
      if (
        !ringZeroActive &&
        (transientNativeToolRestriction ||
          (webSearchBindingChanged &&
            (explicitTransientWebSearchRestriction || unknownProviderWebSearchSupport)))
      ) {
        embeddedAgentLog.debug(
          "codex app-server MCP config changed during transient restricted turn; starting transient thread",
          {
            threadId: binding.threadId,
          },
        );
        preserveExistingBinding = true;
      } else {
        embeddedAgentLog.debug("codex app-server MCP config changed; starting a new thread", {
          threadId: binding.threadId,
        });
        await clearCurrentBinding("rotating a stale thread binding");
      }
      binding = undefined;
    }
    // A transient native-tool restriction must not replace a legacy binding just
    // because that binding predates search fingerprints. Explicit persistent
    // search denial still rotates first so the restricted thread can persist.
    const deferLegacyWebSearchRotationToTransientNativeSurface =
      params.nativeCodeModeEnabled === false &&
      binding?.webSearchThreadConfigFingerprint === undefined &&
      !persistentWebSearchRestriction;
    if (
      binding?.threadId &&
      webSearchBindingChanged &&
      !deferLegacyWebSearchRotationToTransientNativeSurface
    ) {
      assertCodexBindingMayBeReplaced(binding, "changing web-search configuration");
      if (!ringZeroActive && transientWebSearchRestriction) {
        embeddedAgentLog.debug(
          "codex app-server tool surface restricted for turn; starting transient thread",
          {
            threadId: binding.threadId,
          },
        );
        preserveExistingBinding = true;
      } else {
        // Codex can ignore resume overrides for a loaded thread, so persistent
        // search-policy changes and legacy bindings without metadata rotate first.
        embeddedAgentLog.debug(
          "codex app-server web search config changed; starting a new thread",
          {
            threadId: binding.threadId,
          },
        );
        await clearCurrentBinding("rotating a stale thread binding");
      }
      binding = undefined;
    }
    if (binding?.threadId && transientNativeToolRestriction && !ringZeroActive) {
      assertCodexBindingMayBeReplaced(binding, "starting a native-tool-restricted turn");
      embeddedAgentLog.debug(
        "codex app-server native tool surface disabled for turn; starting transient thread",
        {
          threadId: binding.threadId,
        },
      );
      preserveExistingBinding = true;
      binding = undefined;
    }
    if (binding?.threadId && transientDelegationRestriction) {
      assertCodexBindingMayBeReplaced(binding, "starting a delegation-restricted turn");
      // Loaded Codex threads ignore resume config overrides. Keep the normal
      // binding intact and start a transient thread with collaboration disabled.
      embeddedAgentLog.debug(
        "codex app-server delegation restricted for turn; starting transient thread",
        { threadId: binding.threadId },
      );
      binding = undefined;
    }
    if (binding?.threadId && (binding.contextEngine || contextEngineBinding)) {
      if (
        !contextEngineBinding ||
        !isContextEngineBindingCompatible(binding.contextEngine, contextEngineBinding)
      ) {
        embeddedAgentLog.debug(
          "codex app-server context-engine binding changed; starting a new thread",
          {
            threadId: binding.threadId,
            engineId: contextEngineBinding?.engineId,
            previousEngineId: binding.contextEngine?.engineId,
            epoch: contextEngineBinding?.projection?.epoch,
            previousEpoch: binding.contextEngine?.projection?.epoch,
            fingerprint: contextEngineBinding?.projection?.fingerprint,
            previousFingerprint: binding.contextEngine?.projection?.fingerprint,
            policyFingerprint: contextEngineBinding?.policyFingerprint,
            previousPolicyFingerprint: binding.contextEngine?.policyFingerprint,
          },
        );
        await clearCurrentBinding("rotating a stale thread binding");
        binding = undefined;
        rotatedContextEngineBinding = true;
      }
    }
    if (
      binding?.threadId &&
      !areUserMcpServersFingerprintsCompatible({
        previous: binding.userMcpServersFingerprint,
        next: userMcpServersFingerprint,
        nextLegacy: legacyUserMcpServersFingerprint,
      })
    ) {
      embeddedAgentLog.debug("codex app-server user MCP config changed; starting a new thread", {
        threadId: binding.threadId,
      });
      await clearCurrentBinding("rotating a stale thread binding");
      binding = undefined;
    }
    if (
      binding?.threadId &&
      (binding.networkProxyConfigFingerprint !== networkProxyConfigFingerprint ||
        binding.networkProxyProfileName !== params.appServer.networkProxy?.profileName)
    ) {
      embeddedAgentLog.debug(
        "codex app-server network proxy config changed; starting a new thread",
        {
          threadId: binding.threadId,
        },
      );
      await clearCurrentBinding("rotating a stale thread binding");
      binding = undefined;
    }
    if (binding?.threadId) {
      const pluginBindingStale = isCodexPluginThreadBindingStale({
        codexPluginsEnabled: params.pluginThreadConfig?.enabled ?? false,
        bindingFingerprint: binding.pluginAppsFingerprint,
        bindingInputFingerprint: binding.pluginAppsInputFingerprint,
        currentInputFingerprint: params.pluginThreadConfig?.inputFingerprint,
        hasBindingPolicyContext: Boolean(binding.pluginAppPolicyContext),
      });
      if (pluginBindingStale) {
        embeddedAgentLog.debug(
          "codex app-server plugin app config changed; starting a new thread",
          {
            threadId: binding.threadId,
          },
        );
        await clearCurrentBinding("rotating a stale thread binding");
        binding = undefined;
      }
    }
    if (binding?.threadId) {
      if (
        binding.dynamicToolsFingerprint &&
        params.dynamicTools.length > 0 &&
        binding.dynamicToolsContainDeferred !== dynamicToolsContainDeferred &&
        (binding.dynamicToolsContainDeferred !== undefined || !dynamicToolsContainDeferred)
      ) {
        embeddedAgentLog.debug(
          "codex app-server dynamic tool loading changed; starting a new thread",
          {
            threadId: binding.threadId,
          },
        );
        await clearCurrentBinding("rotating a stale thread binding");
        binding = undefined;
      }
    }
    if (binding?.threadId) {
      // `/codex resume <thread>` writes a binding before the next turn can know
      // the dynamic tool catalog, so only invalidate fingerprints we actually have.
      if (
        binding.dynamicToolsFingerprint &&
        !areDynamicToolFingerprintsCompatible(
          binding.dynamicToolsFingerprint,
          dynamicToolsFingerprint,
          legacyDynamicToolsFingerprint,
        )
      ) {
        assertCodexBindingMayBeReplaced(binding, "changing the dynamic tool catalog");
        preserveExistingBinding = shouldStartTransientNoToolThread({
          previous: binding.dynamicToolsFingerprint,
          nextHasDynamicTools: params.dynamicTools.length > 0,
        });
        if (preserveExistingBinding) {
          embeddedAgentLog.debug(
            "codex app-server dynamic tools unavailable for turn; starting transient thread",
            {
              threadId: binding.threadId,
            },
          );
        } else {
          embeddedAgentLog.debug(
            "codex app-server dynamic tool catalog changed; starting a new thread",
            {
              threadId: binding.threadId,
            },
          );
          await clearCurrentBinding("rotating a stale thread binding");
        }
      } else if (incognito) {
        if (
          binding.clientId &&
          binding.clientId === clientId &&
          ((await buildLoadedPluginThreadConfig(binding))?.fingerprint ??
            binding.pluginAppsFingerprint) === binding.pluginAppsFingerprint
        ) {
          // Ephemeral threads have no cold-resume source; reuse only the live client that started it.
          params.buildFinalConfigPatch?.({ action: "resume", binding });
          throwIfAborted();
          lifecycleTiming.mark("thread-ready");
          lifecycleTiming.logSummary({
            runId: params.params.runId,
            sessionId: params.params.sessionId,
            sessionKey: params.params.sessionKey,
            threadId: binding.threadId,
            action: "resumed",
          });
          return { ...binding, lifecycle: { action: "resumed" } };
        }
        await clearCurrentBinding("rotating an unavailable ephemeral thread binding");
        binding = undefined;
      } else {
        const warmReuse = await tryReuseCodexLiveThread({
          ...requestContext,
          params,
          binding,
          clientId,
          buildLoadedPluginThreadConfig,
        });
        if (warmReuse.kind === "ready") {
          return warmReuse.binding;
        }
        if (warmReuse.kind === "rotate") {
          throwIfAborted();
          await clearCurrentBinding("rotating a stale plugin app binding");
        } else {
          // Native adoption must be checked before releasing any retained owner;
          // a passive refusal neither acquires nor authorizes dropping a subscription.
          if (binding.preserveNativeModel === true) {
            await assertAdoptedCodexThreadResumeAllowed(params, binding.threadId, requestContext);
          }
          // Codex cold-resumes a changed idle thread after its last subscriber
          // leaves; resume_running_thread shuts down the old cached session.
          await releaseRetainedThread(binding.threadId);
          const resumed = await resumeExistingCodexThread(params, {
            ...requestContext,
            binding,
            clearCurrentBinding,
            prebuiltFinalConfigPatch: warmReuse.prebuiltFinalConfigPatch,
            prebuiltPluginThreadConfig,
            buildLoadedPluginThreadConfig,
          });
          if (resumed) {
            return resumed;
          }
        }
      }
    }

    if (initialBoundThreadId && !preserveExistingBinding && !replacementPredecessor) {
      await releaseRetainedThread(initialBoundThreadId);
    }
    const started = await startFreshCodexThread(params, {
      ...requestContext,
      prebuiltPluginThreadConfig,
      preserveExistingBinding,
      rotatedContextEngineBinding,
      replacementPredecessor,
    });
    if (replacementPredecessor) {
      // The predecessor remains authoritative through thread/start and exact-owner CAS.
      // Release only that prior subscription after the successor has committed.
      await releaseRetainedThread(replacementPredecessor.threadId, replacementPredecessor.clientId);
    }
    return started;
  });
}

import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";

type CodexThreadLifecycleTimingSpan = {
  name: string;
  durationMs: number;
  elapsedMs: number;
};

type CodexThreadLifecycleTimingSummary = {
  totalMs: number;
  spans: CodexThreadLifecycleTimingSpan[];
};

type CodexThreadLifecycleTimingLogger = {
  isEnabled?: (level: "trace") => boolean;
  trace: (message: string, meta?: Record<string, unknown>) => void;
  warn: (message: string, meta?: Record<string, unknown>) => void;
};

type CodexThreadLifecycleTimingAction = "started" | "resumed" | "forked" | "rotated";

export type CodexThreadLifecycleTimingOptions = {
  enabled?: boolean;
  now?: () => number;
  log?: CodexThreadLifecycleTimingLogger;
  totalThresholdMs?: number;
  stageThresholdMs?: number;
};

export type CodexThreadLifecycleTimingTracker = {
  measure: <T>(name: string, run: () => Promise<T> | T) => Promise<T>;
  measureSync: <T>(name: string, run: () => T) => T;
  mark: (name: string) => void;
  logSummary: (params: {
    runId: string;
    sessionId: string;
    sessionKey?: string;
    action: CodexThreadLifecycleTimingAction;
    threadId?: string;
  }) => void;
};

const CODEX_THREAD_LIFECYCLE_TIMING_WARN_TOTAL_MS = 1_000;
const CODEX_THREAD_LIFECYCLE_TIMING_WARN_STAGE_MS = 500;

function shouldWarnCodexThreadLifecycleTimingSummary(
  summary: CodexThreadLifecycleTimingSummary,
  options: CodexThreadLifecycleTimingOptions = {},
): boolean {
  const totalThresholdMs = options.totalThresholdMs ?? CODEX_THREAD_LIFECYCLE_TIMING_WARN_TOTAL_MS;
  const stageThresholdMs = options.stageThresholdMs ?? CODEX_THREAD_LIFECYCLE_TIMING_WARN_STAGE_MS;
  return (
    summary.totalMs >= totalThresholdMs ||
    summary.spans.some((span) => span.durationMs >= stageThresholdMs)
  );
}

function formatCodexThreadLifecycleTimingSummary(params: {
  runId: string;
  sessionId: string;
  sessionKey?: string;
  action: CodexThreadLifecycleTimingAction;
  summary: CodexThreadLifecycleTimingSummary;
}): string {
  const spans =
    params.summary.spans.length > 0
      ? params.summary.spans
          .map((span) => `${span.name}:${span.durationMs}ms@${span.elapsedMs}ms`)
          .join(",")
      : "none";
  return (
    `[trace:codex-app-server] thread lifecycle: runId=${params.runId} ` +
    `sessionId=${params.sessionId} sessionKey=${params.sessionKey ?? "unknown"} ` +
    `action=${params.action} totalMs=${params.summary.totalMs} stages=${spans}`
  );
}

export function createCodexThreadLifecycleTimingTracker(
  options: CodexThreadLifecycleTimingOptions = {},
): CodexThreadLifecycleTimingTracker {
  const log = options.log ?? embeddedAgentLog;
  if (!options.enabled && log.isEnabled?.("trace") !== true) {
    return {
      async measure(_name, run) {
        return await run();
      },
      measureSync(_name, run) {
        return run();
      },
      mark() {},
      logSummary() {},
    };
  }

  const now = options.now ?? Date.now;
  const startedAt = now();
  let didLog = false;
  const spans: CodexThreadLifecycleTimingSpan[] = [];
  const toMs = (value: number) => Math.max(0, Math.round(value));
  const record = (name: string, spanStartedAt: number) => {
    const currentAt = now();
    spans.push({
      name,
      durationMs: toMs(currentAt - spanStartedAt),
      elapsedMs: toMs(currentAt - startedAt),
    });
  };
  const snapshot = (): CodexThreadLifecycleTimingSummary => ({
    totalMs: toMs(now() - startedAt),
    spans: spans.slice(),
  });
  return {
    async measure(name, run) {
      const spanStartedAt = now();
      try {
        return await run();
      } finally {
        record(name, spanStartedAt);
      }
    },
    measureSync(name, run) {
      const spanStartedAt = now();
      try {
        return run();
      } finally {
        record(name, spanStartedAt);
      }
    },
    mark(name) {
      record(name, now());
    },
    logSummary(params) {
      if (didLog) {
        return;
      }
      const summary = snapshot();
      const shouldWarn = shouldWarnCodexThreadLifecycleTimingSummary(summary, options);
      if (!shouldWarn && !log.isEnabled?.("trace")) {
        return;
      }
      didLog = true;
      const message = formatCodexThreadLifecycleTimingSummary({
        runId: params.runId,
        sessionId: params.sessionId,
        sessionKey: params.sessionKey,
        action: params.action,
        summary,
      });
      const meta = {
        runId: params.runId,
        sessionId: params.sessionId,
        sessionKey: params.sessionKey,
        action: params.action,
        threadId: params.threadId,
        totalMs: summary.totalMs,
        spans: summary.spans,
      };
      if (shouldWarn) {
        log.warn(message, meta);
      } else {
        log.trace(message, meta);
      }
    },
  };
}

