      () => undefined,
      (error: unknown) => error,
    );
    try {
      await Promise.race([
        guardEntered.promise,
        settled.then(() => {
          throw new Error("manual resume settled before reaching its native config fence");
        }),
      ]);
      const releaseSibling = retainSharedCodexAppServerClientIfCurrent(fixture.client);
