      "mcpServerStatus/list",
      { threadId: "thread-restricted", detail: "toolsAndAuthOnly" },
      { signal: undefined },
    );
  });

  it.each([
    {
      name: "an unexpected server",
      status: { name: "unexpected", serverInfo: null, tools: {} },
      failure: "found unexpected server unexpected",
    },
