      (event) => event.type === "model.completed" && event.data?.turnId === "turn-compact",
    );
    expect(exportedCompletion?.data).toEqual(completion?.data);
    expect(exportedCompactCompletion?.data).toEqual(compactCompletion?.data);
  });
});

/** Records optional Codex runtime trajectory events through the host recorder. */
import type { EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams } from "openclaw/plugin-sdk/agent-harness-runtime";
import { attemptTerminal, type EmbeddedRunAttemptResult } from "./attempt-terminal.js";
import { flattenCodexDynamicToolFunctions, type CodexDynamicToolSpec } from "./protocol.js";

/** Runtime trajectory recorder used by Codex run attempts and event projectors. */
export type CodexTrajectoryRecorder = {
  recordEvent: (type: string, data?: Record<string, unknown>) => void;
  flush: () => Promise<void>;
};

type CodexTrajectoryInit = {
  attempt: EmbeddedRunAttemptParams;
  cwd: string;
  developerInstructions?: string;
  prompt?: string;
  trajectory?: NonNullable<EmbeddedRunAttemptParams["hostCapabilities"]["trajectory"]> | null;
  tools?: CodexDynamicToolSpec[];
};

/** Creates a trajectory recorder when the host exposes its capture capability. */
export function createCodexTrajectoryRecorder(
  params: CodexTrajectoryInit,
): CodexTrajectoryRecorder | null {
  if (!params.trajectory) {
    return null;
  }
  const trajectory = params.trajectory;

  return {
    recordEvent: (type, data) => {
      try {
        trajectory.recordEvent(type, data);
      } catch {
        // Host authority can close before transport callbacks finish during shutdown.
        // Optional diagnostics must not interrupt the owning run lifecycle.
      }
    },
    flush: trajectory.flush,
  };
}

/** Records compiled prompt/tool context at the start of a Codex runtime attempt. */
export function recordCodexTrajectoryContext(
  recorder: CodexTrajectoryRecorder | null,
  params: CodexTrajectoryInit,
): void {
  if (!recorder) {
    return;
  }
  recorder.recordEvent("context.compiled", {
    systemPrompt: params.developerInstructions,
    prompt: params.prompt ?? params.attempt.prompt,
    imagesCount: params.attempt.images?.length ?? 0,
    tools: toTrajectoryToolDefinitions(params.tools),
  });
}

/** Records final Codex model completion metadata and assistant snapshots. */
export function recordCodexTrajectoryCompletion(
  recorder: CodexTrajectoryRecorder | null,
  params: {
    attempt: EmbeddedRunAttemptParams;
    result: EmbeddedRunAttemptResult;
    threadId: string;
    turnId: string;
    timedOut: boolean;
    yieldDetected?: boolean;
  },
): void {
  if (!recorder) {
    return;
  }
  const terminal = attemptTerminal.project(params.result.terminal);
  recorder.recordEvent("model.completed", {
    threadId: params.threadId,
    turnId: params.turnId,
    timedOut: params.timedOut,
    yieldDetected: params.yieldDetected ?? false,
    aborted: terminal.aborted,
    promptError: normalizeCodexTrajectoryError(terminal.promptError),
    usage: params.result.attemptUsage,
    assistantTexts: params.result.assistantTexts,
    messagesSnapshot: params.result.messagesSnapshot,
  });
}

function toTrajectoryToolDefinitions(
  tools: readonly CodexDynamicToolSpec[] | undefined,
): Array<{ name: string; description?: string; parameters?: unknown }> | undefined {
  if (!tools || tools.length === 0) {
    return undefined;
  }
  return flattenCodexDynamicToolFunctions(tools)
    .flatMap((tool) => {
      const name = tool.name?.trim();
      if (!name) {
        return [];
      }
      return [
        {
          name,
          description: tool.description,
          parameters: tool.inputSchema,
        },
      ];
    })
    .toSorted((left, right) => left.name.localeCompare(right.name));
}

/** Converts arbitrary prompt errors into trajectory-safe text. */
export function normalizeCodexTrajectoryError(value: unknown): string | null {
  if (!value) {
    return null;
  }
  if (value instanceof Error) {
    return value.message;
  }
  if (typeof value === "string") {
    return value;
  }
  try {
    return JSON.stringify(value);
  } catch {
    return "Unknown error";
  }
}

import {
  embeddedAgentLog,
  formatErrorMessage,
  projectAgentHarnessTranscriptMessageForDisplay,
  type AgentMessage,
  type EmbeddedRunAttemptParamsV2,
} from "openclaw/plugin-sdk/agent-harness-runtime";
import { applyCodexTranscriptTaint } from "./transcript-mirror-attestation.js";
import { codexTranscriptMirrorRuntime } from "./transcript-mirror.js";
import { attachCodexMirrorIdentity } from "./upstream-prompt-provenance.js";

export type CodexTranscriptCheckpointEntry = {
  read: () => AgentMessage | undefined;
  ready?: () => boolean;
};

/** Commits completed work in receipt order without waiting for the enclosing turn. */
export class CodexTranscriptCheckpoint {
  private readonly pending: CodexTranscriptCheckpointEntry[] = [];
  private readonly commentaryItemIds = new Set<string>();
  private lastTimestamp = 0;
  private writing = Promise.resolve();
  private tainted = false;
  private closed = false;

  constructor(
    private readonly params: EmbeddedRunAttemptParamsV2,
    private readonly threadId: string,
    private readonly turnId: string,
  ) {}

  nextTimestamp = (): number => {
    // Commentary and tool mirrors share this clock so equal wall-clock values
    // still preserve the app-server receipt order in the durable transcript.
    this.lastTimestamp = Math.max(Date.now(), this.lastTimestamp + 1);
    return this.lastTimestamp;
  };

  enqueueCommentary = (itemId: string, entry: CodexTranscriptCheckpointEntry): void => {
    if (
      this.params.config?.ui?.prefs?.chatPersistCommentary === false ||
      this.commentaryItemIds.has(itemId)
    ) {
      return;
    }
    this.commentaryItemIds.add(itemId);
    this.enqueue({
      ...entry,
      read: () => {
        const message = entry.read();
        return message
          ? attachCodexMirrorIdentity(message, `${this.turnId}:commentary:${itemId}`)
          : undefined;
      },
    });
  };

  enqueue = (entry: CodexTranscriptCheckpointEntry): void => {
    if (this.params.sessionTarget && !this.closed) {
      this.pending.push(entry);
    }
  };

  flush(close = false): Promise<void> {
    if (this.closed) {
      return this.writing;
    }
    this.closed = close;
    this.writing = this.writing.then(async () => {
      // An unfinished commentary item or linked raw patch output owns its place
      // in history. Later work cannot overtake it; teardown records what arrived.
      const blocked = close ? -1 : this.pending.findIndex((entry) => entry.ready?.() === false);
      const count = blocked < 0 ? this.pending.length : blocked;
      if (count === 0) {
        return;
      }
      const taint = { tainted: this.tainted };
      const messages = this.pending.slice(0, count).flatMap((entry) => {
        const message = entry.read();
        return message
          ? [
              projectAgentHarnessTranscriptMessageForDisplay({
                hidden: this.params.trigger === "memory",
                message: applyCodexTranscriptTaint(message, taint),
              }),
            ]
          : [];
      });
      try {
        await codexTranscriptMirrorRuntime.mirror({
          ...this.params.sessionTarget,
          sessionId: this.params.sessionId,
          cwd: this.params.workspaceDir,
          messages,
          idempotencyScope: `codex-app-server:${this.threadId}`,
          runId: this.params.runId,
          runMirrorIdentityPrefix: `${this.turnId}:`,
          config: this.params.config,
        });
        this.pending.splice(0, count);
        this.tainted = taint.tainted;
      } catch (error) {
        // Keep the pending prefix for the next observed boundary/final mirror.
        // Persistence failure must not turn completed tool work into a retry.
        embeddedAgentLog.warn("failed to checkpoint codex app-server transcript", {
          runId: this.params.runId,
          sessionId: this.params.sessionId,
          error: formatErrorMessage(error),
        });
      }
    });
    return this.writing;
  }
}

import { Buffer } from "node:buffer";
import type { AgentMessage } from "openclaw/plugin-sdk/agent-harness-runtime";
import type { AssistantMessage, Usage } from "openclaw/plugin-sdk/llm";
import type { SessionTranscriptMessageEntry } from "openclaw/plugin-sdk/session-transcript-runtime";
import { normalizeOptionalString } from "openclaw/plugin-sdk/string-coerce-runtime";
import { truncateUtf8Prefix } from "openclaw/plugin-sdk/text-utility-runtime";
import type { CodexThread, JsonValue } from "./protocol.js";
import { attachCodexMirrorIdentity } from "./upstream-prompt-provenance.js";

const CODEX_HISTORY_IMPORT_MAX_MESSAGES = 200;
const CODEX_HISTORY_IMPORT_MAX_BYTES = 512 * 1024;
const CODEX_HISTORY_IMPORT_MAX_MESSAGE_BYTES = 64 * 1024;
const CODEX_HISTORY_TRUNCATION_SUFFIX = "\n\n[Message truncated during Codex history import.]";
const CODEX_HISTORY_ASSISTANT_API = "openai-chatgpt-responses" as const;
const CODEX_HISTORY_ASSISTANT_PROVIDER = "openai";
const CODEX_HISTORY_ASSISTANT_MODEL = "native-history";
const CODEX_HISTORY_ZERO_USAGE: Usage = {
  input: 0,
  output: 0,
  cacheRead: 0,
  cacheWrite: 0,
  totalTokens: 0,
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
};

export type CodexThreadHistoryImportResult = {
  importedMessages: number;
  omittedMessages: number;
};

type BoundedCodexThreadHistoryProjection = CodexThreadHistoryImportResult & {
  responseItems: JsonValue[];
  transcriptMessages: AgentMessage[];
};

type ProjectedCodexHistoryMessage = {
  message: AgentMessage;
  responseItem: JsonValue;
  textBytes: number;
};

function normalizeImportedHistoryText(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }
  const text = value.trim();
  if (!text) {
    return undefined;
  }
  if (Buffer.byteLength(text, "utf8") <= CODEX_HISTORY_IMPORT_MAX_MESSAGE_BYTES) {
    return text;
  }
  const suffixBytes = Buffer.byteLength(CODEX_HISTORY_TRUNCATION_SUFFIX, "utf8");
  const contentLimitBytes = Math.max(0, CODEX_HISTORY_IMPORT_MAX_MESSAGE_BYTES - suffixBytes);
  return `${truncateUtf8Prefix(text, contentLimitBytes)}${CODEX_HISTORY_TRUNCATION_SUFFIX}`;
}

export function projectCodexUserItemText(item: Record<string, unknown>): string | undefined {
  if (!Array.isArray(item.content)) {
    return undefined;
  }
  const parts: string[] = [];
  for (const value of item.content) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      continue;
    }
    const input = value as Record<string, unknown>;
    if (input.type === "text") {
      const text = normalizeImportedHistoryText(input.text);
      if (text) {
        parts.push(text);
      }
      continue;
    }
    if (input.type === "image" || input.type === "localImage") {
      parts.push("[Image attachment]");
      continue;
    }
    if (input.type === "audio" || input.type === "localAudio" || input.type === "local_audio") {
      parts.push("[Audio attachment]");
    }
    if (input.type === "skill" || input.type === "mention") {
      const name = normalizeOptionalString(input.name);
      if (name) {
        parts.push(`${input.type === "skill" ? "$" : "@"}${name}`);
      }
    }
  }
  return normalizeImportedHistoryText(parts.join("\n"));
}

function selectTurnsThroughBoundary(
  thread: CodexThread,
  throughTurnId: string | null,
): NonNullable<CodexThread["turns"]> {
  if (throughTurnId === null) {
    return [];
  }
  const turns = thread.turns ?? [];
  const boundaryIndex = turns.findIndex((turn) => turn.id === throughTurnId);
  if (boundaryIndex < 0) {
    throw new Error(`Codex history boundary turn not found: ${throughTurnId}`);
  }
  const boundary = turns[boundaryIndex];
  if (
    boundary?.status !== "completed" &&
    boundary?.status !== "interrupted" &&
    boundary?.status !== "failed"
  ) {
    throw new Error(`Codex history boundary turn is not terminal: ${throughTurnId}`);
  }
  return turns.slice(0, boundaryIndex + 1);
}

function projectCodexThreadHistory(params: {
  thread: CodexThread;
  throughTurnId: string | null;
  importedAt: number;
  modelProvider?: string;
}): ProjectedCodexHistoryMessage[] {
  const projected: ProjectedCodexHistoryMessage[] = [];
  const threadTimestamp =
    typeof params.thread.createdAt === "number" && Number.isFinite(params.thread.createdAt)
      ? params.thread.createdAt * 1000
      : params.importedAt;
  let itemOffset = 0;
  for (const turn of selectTurnsThroughBoundary(params.thread, params.throughTurnId)) {
    for (const value of turn.items) {
      const item = value;
      const itemId = normalizeOptionalString(item.id);
      const identity = `${turn.id}:${itemId ?? itemOffset}`;
      const timestampSeconds =
        item.type === "agentMessage"
          ? (turn.completedAt ?? turn.startedAt)
          : (turn.startedAt ?? turn.completedAt);
      const timestamp =
        typeof timestampSeconds === "number" && Number.isFinite(timestampSeconds)
          ? timestampSeconds * 1000 + itemOffset
          : threadTimestamp + itemOffset;
      const text =
        item.type === "userMessage"
          ? projectCodexUserItemText(item)
          : item.type === "agentMessage"
            ? normalizeImportedHistoryText(item.text)
            : undefined;
      const role =
        item.type === "userMessage"
          ? ("user" as const)
          : item.type === "agentMessage"
            ? ("assistant" as const)
            : undefined;
      itemOffset += 1;
      if (!text || !role) {
        continue;
      }
      const phase =
        item.phase === "commentary" || item.phase === "final_answer" ? item.phase : undefined;
      const asyncDelivery = item.delivery === "async";
      const message =
        role === "assistant"
          ? attachCodexMirrorIdentity(
              {
                role,
                content: [{ type: "text", text }],
                api: CODEX_HISTORY_ASSISTANT_API,
                provider:
                  normalizeOptionalString(params.modelProvider) ??
                  normalizeOptionalString(params.thread.modelProvider) ??
                  CODEX_HISTORY_ASSISTANT_PROVIDER,
                model: CODEX_HISTORY_ASSISTANT_MODEL,
                usage: CODEX_HISTORY_ZERO_USAGE,
                stopReason:
                  turn.status === "interrupted"
                    ? "aborted"
                    : turn.status === "failed"
                      ? "error"
                      : "stop",
                ...(turn.status === "failed" && turn.error?.message
                  ? { errorMessage: turn.error.message }
                  : {}),
                ...(phase ? { phase } : {}),
                ...(asyncDelivery && itemId ? { openclawAsyncDelivery: { itemId } } : {}),
                timestamp,
              } satisfies AssistantMessage,
              identity,
            )
          : attachCodexMirrorIdentity({ role, content: text, timestamp } as AgentMessage, identity);
      projected.push({
        message,
        responseItem: {
          type: "message",
          role,
          content: [
            {
              type: role === "assistant" ? "output_text" : "input_text",
              text,
            },
          ],
          ...(role === "assistant" && phase ? { phase } : {}),
        },
        textBytes: Buffer.byteLength(text, "utf8"),
      });
    }
  }
  return projected;
}

function selectBoundedCodexHistoryTail(
  projected: ProjectedCodexHistoryMessage[],
): ProjectedCodexHistoryMessage[] {
  const selected: ProjectedCodexHistoryMessage[] = [];
  let selectedBytes = 0;
  for (let index = projected.length - 1; index >= 0; index -= 1) {
    const candidate = projected[index];
    if (!candidate) {
      continue;
    }
    if (
      selected.length >= CODEX_HISTORY_IMPORT_MAX_MESSAGES ||
      selectedBytes + candidate.textBytes > CODEX_HISTORY_IMPORT_MAX_BYTES
    ) {
      break;
    }
    selected.push(candidate);
    selectedBytes += candidate.textBytes;
  }
  return selected.toReversed();
}

/** Projects one terminal Codex history prefix into transcript and Responses API items. */
export function projectBoundedCodexThreadHistory(params: {
  thread: CodexThread;
  throughTurnId: string | null;
  importedAt: number;
  modelProvider?: string | null;
}): BoundedCodexThreadHistoryProjection {
  const projected = projectCodexThreadHistory({
    thread: params.thread,
    throughTurnId: params.throughTurnId,
    importedAt: params.importedAt,
    ...(params.modelProvider ? { modelProvider: params.modelProvider } : {}),
  });
  const selected = selectBoundedCodexHistoryTail(projected);
  return {
    importedMessages: selected.length,
    omittedMessages: projected.length - selected.length,
    // Failed assistant fragments remain visible in operator transcripts, but
    // injecting them would permanently replay incomplete model output.
    responseItems: selected
      .filter(
        ({ message }) =>
          message.role !== "assistant" ||
          (message.stopReason !== "aborted" &&
            message.stopReason !== "error" &&
            !("openclawAsyncDelivery" in message)),
      )
      .map(({ responseItem }) => responseItem),
    transcriptMessages: selected.map(({ message }) => message),
  };
}

/** Projects only visible local user/assistant messages through the same bounded history policy. */
export function projectBoundedCodexVisibleSessionHistory(
  entries: readonly SessionTranscriptMessageEntry[],
): JsonValue[] {
  const projected: ProjectedCodexHistoryMessage[] = [];
  for (const entry of entries) {
    if ((entry.role !== "user" && entry.role !== "assistant") || !("content" in entry.message)) {
      continue;
    }
    if (
      entry.role === "assistant" &&
      (("stopReason" in entry.message &&
        (entry.message.stopReason === "aborted" || entry.message.stopReason === "error")) ||
        "openclawAsyncDelivery" in entry.message)
    ) {
      continue;
    }
    const content = entry.message.content;
    const text = normalizeImportedHistoryText(
      typeof content === "string"
        ? content
        : Array.isArray(content)
          ? content
              .flatMap((part) =>
                part && typeof part === "object" && "text" in part && typeof part.text === "string"
                  ? [part.text]
                  : [],
              )
              .join("\n")
          : undefined,
    );
    if (!text) {
      continue;
    }
    projected.push({
      message: entry.message,
      responseItem: {
        type: "message",
        role: entry.role,
        content: [
          {
            type: entry.role === "assistant" ? "output_text" : "input_text",
            text,
          },
        ],
      },
      textBytes: Buffer.byteLength(text, "utf8"),
    });
  }
  return selectBoundedCodexHistoryTail(projected).map(({ responseItem }) => responseItem);
}

import { createHash } from "node:crypto";
import type { AgentMessage } from "openclaw/plugin-sdk/agent-harness-runtime";
import { asOptionalRecord } from "openclaw/plugin-sdk/string-coerce-runtime";
import { readUpstreamUserText } from "./upstream-prompt-provenance.js";

type MirroredAgentMessage = Extract<AgentMessage, { role: "user" | "assistant" | "toolResult" }>;

const MIRROR_ORIGIN_META_KEY = "mirrorOrigin" as const;
const MIRROR_SOURCE_FINGERPRINT_META_KEY = "mirrorSourceFingerprint" as const;
const CODEX_APP_SERVER_MIRROR_ORIGIN = "codex-app-server" as const;
const CODEX_META_KEY = "__openclaw";

export function applyCodexTranscriptTaint(
  message: AgentMessage,
  state: { tainted: boolean },
): AgentMessage {
  if (message.role === "user") {
    state.tainted = false;
    return message;
  }
  const existing = CODEX_META_KEY in message ? message[CODEX_META_KEY] : undefined;
  const metadata = asOptionalRecord(existing);
  state.tainted ||= metadata?.turnTainted === true || metadata?.resultContentSource === "network";
  return message.role === "assistant" && state.tainted
    ? ({ ...message, __openclaw: { ...metadata, turnTainted: true } } as AgentMessage) // SAFETY: Only provider metadata changes.
    : message;
}

export function attachCodexMirrorAttestation(
  message: AgentMessage,
  sourceFingerprint?: string,
): AgentMessage {
  const existing = CODEX_META_KEY in message ? message[CODEX_META_KEY] : undefined;
  const baseMeta =
    existing && typeof existing === "object" && !Array.isArray(existing)
      ? (existing as Record<string, unknown>)
      : {};
  const attested: AgentMessage & { [CODEX_META_KEY]: Record<string, unknown> } = {
    ...message,
    [CODEX_META_KEY]: {
      ...baseMeta,
      [MIRROR_ORIGIN_META_KEY]: CODEX_APP_SERVER_MIRROR_ORIGIN,
      ...(sourceFingerprint ? { [MIRROR_SOURCE_FINGERPRINT_META_KEY]: sourceFingerprint } : {}),
    },
  };
  return attested;
}

export function attachCodexMirrorRunId<T extends AgentMessage>(
  message: T,
  runId: string,
  terminal = false,
): T {
  const existing = CODEX_META_KEY in message ? message[CODEX_META_KEY] : undefined;
  const metadata = asOptionalRecord(existing) ?? {};
  const { runTerminal: _staleTerminal, ...current } = metadata;
  return {
    ...message,
    [CODEX_META_KEY]: {
      ...current,
      runId,
      ...(terminal ? { runTerminal: true } : {}),
    },
  } as T; // SAFETY: AgentMessage variants permit provider metadata at runtime; preserve T.
}

export function hasCodexMirrorOrigin(message: AgentMessage): boolean {
  const meta = CODEX_META_KEY in message ? message[CODEX_META_KEY] : undefined;
  return asOptionalRecord(meta)?.[MIRROR_ORIGIN_META_KEY] === CODEX_APP_SERVER_MIRROR_ORIGIN;
}

export function readCodexMirrorSourceFingerprint(message: AgentMessage): string | undefined {
  const meta = CODEX_META_KEY in message ? message[CODEX_META_KEY] : undefined;
  if (!meta || typeof meta !== "object" || Array.isArray(meta)) {
    return undefined;
  }
  const value = (meta as Record<string, unknown>)[MIRROR_SOURCE_FINGERPRINT_META_KEY];
  return typeof value === "string" && value ? value : undefined;
}

export function serializeCodexMirrorSourceEvidence(message: AgentMessage): string {
  const content = "content" in message ? message.content : undefined;
  return JSON.stringify({
    role: message.role,
    content,
    ...(message.role === "user" ? { upstreamUserText: readUpstreamUserText(message) } : {}),
    ...(message.role === "toolResult"
      ? {
          toolCallId: message.toolCallId,
          toolName: message.toolName,
          isError: message.isError,
        }
      : {}),
  });
}

export function fingerprintCodexMirrorSourceMessage(message: MirroredAgentMessage): string {
  return createHash("sha256")
    .update(serializeCodexMirrorSourceEvidence(message))
    .digest("hex")
    .slice(0, 32);
}

