    await importOriginal<typeof import("openclaw/plugin-sdk/codex-session-transcript-runtime")>();
  return {
    ...actual,
    withCodexSessionTranscriptMirrorWriteLock: async (
      params: Parameters<typeof actual.withCodexSessionTranscriptMirrorWriteLock>[0],
      run: Parameters<typeof actual.withCodexSessionTranscriptMirrorWriteLock>[1],
    ) =>
      await actual.withCodexSessionTranscriptMirrorWriteLock(params, async (locked) => {
        const competingMessage = transcriptRace.competingMessage;
        if (!competingMessage) {
          return await run(locked);
        }
        transcriptRace.competingMessage = undefined;
        const intercepted: CodexSessionTranscriptMirrorWriteLockContext = {
          ...locked,
          readMessageFacts: async (factParams) => {
            const staleFacts = await locked.readMessageFacts(factParams);
            await locked.appendMessage({
              message: competingMessage as AgentMessage,
              idempotencyLookup: "scan",
            });
            return staleFacts;
          },
          appendMessageWithMessageSequence: async (options) => {
            transcriptRace.lookups.push(options.idempotencyLookup);
            const result = await locked.appendMessageWithMessageSequence(options);
            const appended = result.result;
            const message = appended?.message as AgentMessage | undefined;
            if (appended && message?.role === "user") {
              transcriptRace.userAnchor = appended.anchor;
            }
            return result;
          },
        };
        return await run(intercepted);
      }),
  };
});

afterEach(() => {
  resetGlobalHookRunner();
  transcriptRace.competingMessage = undefined;
  transcriptRace.lookups.length = 0;
  transcriptRace.publish.mockReset();
  transcriptRace.userAnchor = undefined;
});

it("adopts a competing indexed user without duplicating writes or slowing assistant mirrors", async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "codex-mirror-user-race-"));
  try {
    const target = {
      agentId: "main",
      sessionId: "user-race",
      sessionKey: "agent:main:user-race",
      storePath: path.join(root, "openclaw-agent.sqlite"),
    };
    await upsertSessionEntry({
      agentId: target.agentId,
      sessionKey: target.sessionKey,
      storePath: target.storePath,
      entry: {
        sessionFile: `sqlite:${target.agentId}:${target.sessionId}:${target.storePath}`,
        sessionId: target.sessionId,
        updatedAt: 1,
      },
    });

    const beforeMessageWrite = vi.fn((...args: unknown[]) => {
      const event = args[0] as { message: AgentMessage };
      return {
        message:
          event.message.role === "user"
            ? castAgentMessage({
                ...event.message,
                content: [{ type: "text", text: "[redacted by hook]" }],
              })
            : event.message,
      };
    });
    initializeGlobalHookRunner(
      createMockPluginRegistry([{ hookName: "before_message_write", handler: beforeMessageWrite }]),
    );

    const sourceUser = attachCodexMirrorIdentity(
      castAgentMessage({
        ...makeAgentUserMessage({
          content: [{ type: "text", text: "private user prompt" }],
          timestamp: 1,
        }),
        idempotencyKey: "codex-user-race:prompt",
      }),
      "turn-1:prompt",
    );
    const userFingerprint = fingerprintCodexMirrorSourceMessage(
      sourceUser as Extract<AgentMessage, { role: "user" }>,
    );
    transcriptRace.competingMessage = attachCodexMirrorAttestation(
      castAgentMessage({
        ...sourceUser,
        content: [{ type: "text", text: "[redacted by hook]" }],
      }),
      userFingerprint,
    );
    const sourceAssistant = attachCodexMirrorIdentity(
      makeAgentAssistantMessage({
        content: [{ type: "text", text: "answer" }],
        timestamp: 2,
      }),
      "turn-1:assistant",
    );

    const result = await codexTranscriptMirrorRuntime.mirror({
      ...target,
      messages: [sourceUser, sourceAssistant],
      idempotencyScope: "codex-app-server:thread-1",
    });

    const messageEvents = (await readSessionTranscriptEvents(target)).filter(
      (event): event is { id: string; type: "message"; message: AgentMessage } => {
        return Boolean(
          event &&
          typeof event === "object" &&
          "id" in event &&
          typeof event.id === "string" &&
          "type" in event &&
          event.type === "message",
        );
      },
    );
    const messages = messageEvents.map((event) => event.message);

    expect(messages.filter((message) => message.role === "user")).toHaveLength(1);
    expect(messages.filter((message) => message.role === "assistant")).toHaveLength(1);
    expect(result.userMessagesPresent).toEqual([
      expect.objectContaining({
        role: "user",
        content: [{ type: "text", text: "[redacted by hook]" }],
        idempotencyKey: "codex-user-race:prompt",
        __openclaw: expect.objectContaining({
          mirrorOrigin: "codex-app-server",
          mirrorSourceFingerprint: userFingerprint,
        }),
      }),
    ]);
    expect(result.userMessageReceipts).toHaveLength(1);
    expect(result.userMessageReceipts[0]?.message).toBe(result.userMessagesPresent[0]);
    expect(result.userMessageReceipts[0]?.anchor).toBe(transcriptRace.userAnchor);
    expect(result.userMessageReceipts[0]?.anchor.entryId).toBe(
      messageEvents.find((event) => event.message.role === "user")?.id,
    );
    expect(result.assistantMirrorIdentitiesOwned).toEqual(["turn-1:assistant"]);
    expect(transcriptRace.lookups).toEqual(["scan", "scan"]);
    expect(transcriptRace.publish).toHaveBeenCalledTimes(1);
    expect(transcriptRace.publish).toHaveBeenCalledWith(
      expect.objectContaining({
        update: expect.objectContaining({
          message: expect.objectContaining({ role: "assistant" }),
          messageSeq: 2,
        }),
      }),
    );
    expect(beforeMessageWrite).toHaveBeenCalledTimes(2);
  } finally {
    await fs.rm(root, { recursive: true, force: true });
  }
});

// Codex tests cover transcript repair runtime contract plugin behavior.
import {
  assistantHistoryMessage,
  currentPromptHistoryMessage,
  mediaOnlyHistoryMessage,
  structuredHistoryMessage,
} from "openclaw/plugin-sdk/agent-runtime-test-contracts";
import { describe, expect, it } from "vitest";
import { projectContextEngineAssemblyForCodex } from "./context-engine-projection.js";

describe("Codex transcript projection runtime contract", () => {
  it("drops only the duplicate trailing current prompt while preserving prior structured context", () => {
    const prompt = "newest inbound message";

    const result = projectContextEngineAssemblyForCodex({
      prompt,
      originalHistoryMessages: [structuredHistoryMessage()],
      assembledMessages: [
        structuredHistoryMessage(),
        assistantHistoryMessage(),
        currentPromptHistoryMessage(prompt),
      ],
    });

    expect(result.promptText).toContain("Current user request:\nnewest inbound message");
    expect(result.promptText).toContain("[user]\nolder structured context\n[image omitted]");
    expect(result.promptText).toContain("[assistant]\nack");
    expect(result.promptText).not.toContain("[user]\nnewest inbound message");
  });

  it("keeps media-only user history visible as omitted media instead of dropping the turn", () => {
    const result = projectContextEngineAssemblyForCodex({
      prompt: "newest inbound message",
      originalHistoryMessages: [mediaOnlyHistoryMessage()],
      assembledMessages: [
        mediaOnlyHistoryMessage(),
        currentPromptHistoryMessage("newest inbound message"),
      ],
    });

    expect(result.promptText).toContain("[user]\n[image omitted]");
    expect(result.promptText).not.toContain("data:image/png");
    expect(result.promptText).not.toContain("bbbb");
  });
});

import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";

const fixture = fileURLToPath(import.meta.url);
if (process.argv[2] === "child") {
  const descendant = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"], {
    detached: true,
    stdio: "ignore",
  });
  process.stdout.write(`${JSON.stringify({ child: process.pid, descendant: descendant.pid })}\n`);
  process.stdin.resume();
  setInterval(() => {}, 1000);
} else {
  const { createStdioTransport } = await import("./transport-stdio.js");
  if (process.argv[2] === "native") {
    const command = process.argv[4]!;
    const cwd = process.argv[5]!;
    const child = await createStdioTransport(
      {
        transport: "stdio",
        command,
        args: ["app-server", "--listen", "stdio://"],
        cwd,
        headers: {},
      },
      process.env,
    );
    child.stderr.pipe(process.stderr);
    const send = (message: object) => child.stdin.write(`${JSON.stringify(message)}\n`);
    createInterface({ input: child.stdout }).on("line", (line) => {
      // SAFETY: The pinned native test binary emits Codex JSON-RPC envelopes on stdout.
      const message = JSON.parse(line) as {
        id?: number;
        method?: string;
        error?: unknown;
        params: { deltaBase64: string };
      };
      if (message.error) {
        throw new Error(JSON.stringify(message.error));
      }
      if (message.id === 1) {
        send({ method: "initialized", params: {} });
        send({
          id: 2,
          method: "command/exec",
          params: {
            command: [
              process.execPath,
              "-e",
              "process.stdout.write(String(process.pid)+'\\n');setInterval(()=>{},1000)",
            ],
            processId: "orphan-proof",
            streamStdoutStderr: true,
            disableTimeout: true,
            sandboxPolicy: { type: "dangerFullAccess" },
            cwd,
          },
        });
      } else if (message.method === "command/exec/outputDelta") {
        const descendant = Number(
          Buffer.from(message.params.deltaBase64, "base64").toString().trim(),
        );
        if (Number.isSafeInteger(descendant) && descendant > 0) {
          process.stdout.write(
            `${JSON.stringify({ parent: process.pid, child: child.pid, descendant })}\n`,
          );
        }
      }
    });
    send({
      id: 1,
      method: "initialize",
      params: {
        clientInfo: { name: "openclaw_orphan_test", version: "1.0.0" },
        capabilities: { experimentalApi: true },
      },
    });
  } else {
    const child = await createStdioTransport({
      transport: "stdio",
      command: process.execPath,
      args: ["--import", "tsx", fixture, "child"],
      headers: {},
    });
    child.stderr.pipe(process.stderr);
    createInterface({ input: child.stdout }).once("line", (line) => {
      process.stdout.write(`${JSON.stringify({ parent: process.pid, ...JSON.parse(line) })}\n`);
    });
    child.once("error", (error) => {
      throw error;
    });
  }
}

import { execFileSync, spawn, type ChildProcess } from "node:child_process";
import { once } from "node:events";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { createCodexNativeTestState } from "./native-app-server.test-support.js";

type ProcessTree = { parent: number; child: number; descendant: number };
const fixture = fileURLToPath(new URL("./transport-orphan.test-helper.ts", import.meta.url));

function isAlive(pid: number) {
  try {
    process.kill(pid, 0);
    return !execFileSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" })
      .trim()
      .startsWith("Z");
  } catch {
    return false;
  }
}

describe.skipIf(process.platform === "win32")("Codex stdio crash recovery", () => {
  it.for(["fixture", "native"])(
    "reaps the dead $0 owner before a fresh spawn and preserves live owners",
    { timeout: 60_000 },
    async (mode, ctx) => {
      const root = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-codex-orphan-"));
      const fakeBin = path.join(root, "bin");
      await fs.mkdir(fakeBin);
      await fs.writeFile(path.join(fakeBin, "ps"), "#!/bin/sh\nexit 1\n", { mode: 0o755 });
      const unavailablePs = `${fakeBin}${path.delimiter}${process.env.PATH}`;
      const parents: ChildProcess[] = [];
      const trees: ProcessTree[] = [];
      ctx.onTestFinished(async () => {
        // Also capture children of a fixture that failed before reporting ready.
        const rows = execFileSync("ps", ["-axo", "pid=,ppid="], { encoding: "utf8" })
          .trim()
          .split("\n")
          .map((line) => line.trim().split(/\s+/).map(Number));
        const owned = new Set(parents.flatMap((parent) => (parent.pid ? [parent.pid] : [])));
        for (const pid of owned) {
          for (const [child, parent] of rows) {
            if (parent === pid && child) {
              owned.add(child);
            }
          }
        }
        for (const pid of [...owned].toReversed()) {
          try {
            process.kill(pid, "SIGKILL");
          } catch {
            /* Already exited. */
          }
        }
        for (const tree of trees) {
          for (const pid of [tree.descendant, tree.child, tree.parent]) {
            try {
              process.kill(pid, "SIGKILL");
            } catch {
              // Test-owned processes may already have been reaped by the successor.
            }
          }
        }
        for (const parent of parents) {
          parent.kill("SIGKILL");
          parent.stdout?.destroy();
          parent.stderr?.destroy();
        }
        await fs.rm(root, { recursive: true, force: true });
      });
      const start = async (
        stateDir: string,
        searchPath = process.platform === "linux" ? unavailablePs : process.env.PATH,
      ) => {
        const native =
          mode === "native"
            ? await createCodexNativeTestState(path.join(root, `native-${parents.length}`))
            : undefined;
        if (native) {
          await fs.writeFile(
            path.join(native.codexHome, "config.toml"),
            'cli_auth_credentials_store="ephemeral"\n[features]\nrespect_system_proxy=false\nshell_snapshot=false\n[analytics]\nenabled=false\n[feedback]\nenabled=false\n',
          );
        }
        const args = [
          "--import",
          "tsx",
          fixture,
          mode,
          root,
          ...(native ? [native.command, native.cwd] : []),
        ];
        const parent = spawn(process.execPath, args, {
          env: {
            HOME: root,
            ...native?.env,
            PATH: searchPath,
            OPENCLAW_STATE_DIR: stateDir,
            NODE_ENV: "test",
          },
          stdio: ["ignore", "pipe", "pipe"],
        });
        parents.push(parent);
        let stderr = "";
        parent.stderr?.on("data", (chunk: Buffer) => {
          stderr = (stderr + chunk.toString()).slice(-4_000);
        });
        const lines = createInterface({ input: parent.stdout! });
        const tree = await new Promise<ProcessTree>((resolve, reject) => {
          parent.once("error", reject);
          parent.once("exit", () => reject(new Error(`Fixture exited: ${stderr}`)));
          lines.once("line", (line) => resolve(JSON.parse(line) as ProcessTree));
        });
        lines.close();
        trees.push(tree);
        return { parent, tree };
      };
      const stateDir = path.join(root, "state");
      const old = await start(stateDir);
      const live = await start(stateDir);
      const other = await start(path.join(root, "other-state"));
      expect(isAlive(old.tree.child)).toBe(true);
      if (mode === "native") {
        // Freeze a real app-server mid-command so EOF cannot complete its cleanup.
        process.kill(old.tree.child, "SIGSTOP");
      }
      const exited = once(old.parent, "exit");
      old.parent.kill("SIGKILL");
      await exited;
      expect(isAlive(old.tree.child)).toBe(true);
      expect(isAlive(old.tree.descendant)).toBe(true);

      if (process.platform !== "linux") {
        await expect(start(stateDir, unavailablePs)).rejects.toThrow(
          "Cannot inspect Codex processes. Process identity is unavailable or invalid.",
        );
        expect(isAlive(old.tree.child)).toBe(true);
      }

      const fresh = await start(stateDir);
      expect(isAlive(old.tree.child)).toBe(false);
      expect(isAlive(old.tree.descendant)).toBe(false);
      for (const tree of [live.tree, other.tree, fresh.tree]) {
        expect(isAlive(tree.child)).toBe(true);
        expect(isAlive(tree.descendant)).toBe(true);
      }
    },
  );
});

import {
  readCodexAppServerProcess,
  readCodexAppServerProcessSnapshot,
  type PosixProcess,
} from "./transport-process-snapshot.js";

type ContainableTransport = {
  pid?: number;
  exitCode?: number | null;
  signalCode?: string | null;
  kill?: (signal?: NodeJS.Signals) => unknown;
};

export type CodexAppServerProcessIdentity = Pick<PosixProcess, "pid" | "pgid" | "startedAt">;

const MAX_CONTAINED_PROCESSES = 512;
const MAX_PROCESS_CONTAINMENT_MS = 2_000;
const MAX_PROCESS_QUIESCE_PASSES = 16;

export async function terminateCodexAppServerDescendants(
  child: ContainableTransport,
): Promise<(() => void) | "exited" | undefined> {
  const contained = await containDescendants(child);
  return contained === "exited" ? contained : contained?.resume;
}

/** A durable spawn fact, never a command-line match, selects the orphan root. */
export async function terminateCodexAppServerOrphan(
  expected: CodexAppServerProcessIdentity,
): Promise<boolean> {
  const deadline = Date.now() + MAX_PROCESS_CONTAINMENT_MS;
  const result = await containDescendants(
    { pid: expected.pid, kill: (signal) => signalProcess(expected.pid, signal ?? "SIGTERM") },
    expected,
    deadline,
  );
  const contained = result === "exited" ? undefined : result;
  let gone = false;
  try {
    if (contained) {
      const current = await readCodexAppServerProcess(expected.pid, deadline).catch(
        () => undefined,
      );
      if (current && isSameLiveRoot(current, contained.root, true)) {
        // Keep the verified leader stopped until its whole group is killed;
        // a QA-owned child may share its parent's group and must use its PID.
        signalProcess(current.pgid === current.pid ? -current.pid : current.pid, "SIGKILL");
      }
    }
    while (Date.now() < deadline) {
      const snapshot = await readCodexAppServerProcessSnapshot(deadline).catch(() => undefined);
      if (!snapshot?.some((row) => row.pid === process.pid)) {
        return false;
      }
      const current = snapshot.find((row) => row.pid === expected.pid);
      if (!current || !hasSameIdentity(current, expected) || current.state.startsWith("Z")) {
        gone = true;
        return true;
      }
      if (!contained) {
        return false;
      }
      await new Promise((resolve) => {
        setTimeout(resolve, 20);
      });
    }
    return false;
  } finally {
    if (contained && !gone) {
      await signalSameRoot(contained.root, "SIGCONT", Date.now() + MAX_PROCESS_CONTAINMENT_MS);
    }
  }
}

async function containDescendants(
  child: ContainableTransport,
  expected?: CodexAppServerProcessIdentity,
  deadline = Date.now() + MAX_PROCESS_CONTAINMENT_MS,
): Promise<{ root: PosixProcess; resume: () => void } | "exited" | undefined> {
  const rootPid = child.pid;
  if (hasExited(child)) {
    return "exited";
  }
  if (process.platform === "win32" || !rootPid || !child.kill) {
    return undefined;
  }
  // Inspection failures never grant containment or signal authority.
  const snapshot = await readCodexAppServerProcessSnapshot(deadline).catch(() => undefined);
  if (!snapshot || Date.now() >= deadline) {
    return undefined;
  }
  const root = snapshot.find((row) => row.pid === rootPid);
  // A retained direct child cannot have its PID reused before Node reaps it.
  // Preserve an OS-observed exit even when Node's exit callback is still queued.
  if (!expected && (!root || root.state.startsWith("Z"))) {
    return "exited";
  }
  if (
    !root ||
    !(expected ? isSameLiveProcess(root, expected) : root.ppid === process.pid) ||
    root.state.startsWith("Z")
  ) {
    return undefined;
  }

  const initialDescendants = collectDescendants(snapshot, [rootPid]);
  if (initialDescendants.length > MAX_CONTAINED_PROCESSES) {
    return undefined;
  }
  const stoppedDescendants = new Map<string, PosixProcess>();
  if (!(await signalSameRoot(root, "SIGSTOP", deadline))) {
    return undefined;
  }
  let resumeRootOnUnwind = true;
  try {
    const descendants = await quiesceDescendants(
      root,
      initialDescendants,
      stoppedDescendants,
      deadline,
    );
    if (!descendants) {
      return undefined;
    }

    // Parents are last: every destructive signal revalidates the exact live PID
    // while the stopped ancestry still prevents new descendants.
    for (const descendant of descendants.toReversed()) {
      if (Date.now() >= deadline) {
        return undefined;
      }
      if (!descendant.state.startsWith("Z")) {
        if (!(await signalSameProcess(descendant, "SIGKILL", deadline)) || Date.now() >= deadline) {
          return undefined;
        }
      }
    }
    resumeRootOnUnwind = false;
    let resumed = false;
    return {
      root,
      resume: () => {
        if (resumed) {
          return;
        }
        resumed = true;
        resumeTransportRoot(child, root, false);
      },
    };
  } finally {
    if (resumeRootOnUnwind) {
      if (expected) {
        // Orphans have no retained child handle. Failed inspection leaves the
        // registration intact; never release a reused PID while unwinding.
        const releaseDeadline = Date.now() + MAX_PROCESS_CONTAINMENT_MS;
        for (const descendant of stoppedDescendants.values()) {
          await signalSameProcess(descendant, "SIGCONT", releaseDeadline);
        }
        await signalSameRoot(root, "SIGCONT", releaseDeadline);
      } else {
        // A live parent still owns these stopped children when inspection fails.
        for (const descendant of stoppedDescendants.values()) {
          signalProcess(descendant.pid, "SIGCONT");
        }
        resumeTransportRoot(child, root, true);
      }
    }
  }
}

async function quiesceDescendants(
  root: PosixProcess,
  initialDescendants: PosixProcess[],
  stopped: Map<string, PosixProcess>,
  deadline: number,
): Promise<PosixProcess[] | undefined> {
  const provenByPid = new Map(initialDescendants.map((descendant) => [descendant.pid, descendant]));
  const stopFailures = new Map<string, number>();
  for (let pass = 0; pass < MAX_PROCESS_QUIESCE_PASSES; pass += 1) {
    if (Date.now() >= deadline) {
      return undefined;
    }
    const snapshot = await readCodexAppServerProcessSnapshot(deadline).catch(() => undefined);
    if (!snapshot || Date.now() >= deadline) {
      return undefined;
    }
    const currentRoot = snapshot.find((row) => row.pid === root.pid);
    if (!currentRoot || !isSameLiveRoot(currentRoot, root)) {
      return undefined;
    }
    if (!isSameLiveRoot(currentRoot, root, true)) {
      if (!(await signalSameRoot(root, "SIGSTOP", deadline)) || Date.now() >= deadline) {
        return undefined;
      }
      continue;
    }
    const snapshotByPid = new Map(snapshot.map((process) => [process.pid, process]));
    const liveProven: PosixProcess[] = [];
    for (const proven of provenByPid.values()) {
      const current = snapshotByPid.get(proven.pid);
      if (!current) {
        provenByPid.delete(proven.pid);
        stopped.delete(identityKey(proven));
        continue;
      }
      if (!hasSameIdentity(proven, current)) {
        return undefined;
      }
      provenByPid.set(current.pid, current);
      const key = identityKey(current);
      if (stopped.has(key)) {
        stopped.set(key, current);
      }
      liveProven.push(current);
    }
    const descendants = collectDescendants(snapshot, [
      root.pid,
      ...liveProven.map(({ pid }) => pid),
    ]);
    for (const descendant of descendants) {
      const proven = provenByPid.get(descendant.pid);
      if (proven && !hasSameIdentity(proven, descendant)) {
        return undefined;
      }
      provenByPid.set(descendant.pid, descendant);
    }
    if (provenByPid.size > MAX_CONTAINED_PROCESSES) {
      return undefined;
    }
    const quiescenceTargets = new Map(liveProven.map((process) => [process.pid, process]));
    for (const descendant of descendants) {
      quiescenceTargets.set(descendant.pid, descendant);
    }
    let allStopped = true;
    for (const descendant of quiescenceTargets.values()) {
      if (Date.now() >= deadline) {
        return undefined;
      }
      if (isStoppedState(descendant.state)) {
        continue;
      }
      const stopQueued = await signalSameProcess(descendant, "SIGSTOP", deadline);
      if (Date.now() >= deadline) {
        return undefined;
      }
      if (stopQueued) {
        stopFailures.delete(identityKey(descendant));
        stopped.set(identityKey(descendant), descendant);
      } else {
        const key = identityKey(descendant);
        const failures = (stopFailures.get(key) ?? 0) + 1;
        if (failures >= 2) {
          return undefined;
        }
        stopFailures.set(key, failures);
      }
      if (!isUninterruptibleState(descendant.state) || !stopQueued) {
        allStopped = false;
      }
    }
    if (allStopped) {
      return [...provenByPid.values()];
    }
  }
  return undefined;
}

function collectDescendants(snapshot: PosixProcess[], rootPids: number[]): PosixProcess[] {
  const childrenByParent = new Map<number, PosixProcess[]>();
  for (const row of snapshot) {
    const children = childrenByParent.get(row.ppid) ?? [];
    children.push(row);
    childrenByParent.set(row.ppid, children);
  }
  const descendants: PosixProcess[] = [];
  const pending = [...new Set(rootPids)];
  const seen = new Set(pending);
  for (const parentPid of pending) {
    for (const child of childrenByParent.get(parentPid) ?? []) {
      if (seen.has(child.pid)) {
        continue;
      }
      seen.add(child.pid);
      descendants.push(child);
      pending.push(child.pid);
    }
  }
  return descendants;
}

function isStoppedState(state: string): boolean {
  return state.startsWith("T") || state.startsWith("t") || state.startsWith("Z");
}

function isQuiescedState(state: string): boolean {
  return isStoppedState(state) || isUninterruptibleState(state);
}

function isUninterruptibleState(state: string): boolean {
  return state.startsWith("D") || state.startsWith("U");
}

function isSameLiveProcess(
  current: PosixProcess,
  expected: CodexAppServerProcessIdentity,
): boolean {
  return (
    current.pgid === expected.pgid &&
    !current.state.startsWith("Z") &&
    hasSameIdentity(current, expected)
  );
}

function isSameLiveRoot(
  current: PosixProcess,
  expected: PosixProcess,
  requireStopped = false,
): boolean {
  return (
    current.ppid === expected.ppid &&
    (!requireStopped || isQuiescedState(current.state)) &&
    isSameLiveProcess(current, expected)
  );
}

async function signalSameRoot(
  root: PosixProcess,
  signal: NodeJS.Signals,
  deadline: number,
): Promise<boolean> {
  const current = await readCodexAppServerProcess(root.pid, deadline).catch(() => undefined);
  return Boolean(current && isSameLiveRoot(current, root) && signalProcess(current.pid, signal));
}

function resumeTransportRoot(
  child: ContainableTransport,
  root: PosixProcess,
  allowSynchronousPidFallback: boolean,
): void {
  try {
    if (child.kill) {
      child.kill("SIGCONT");
      return;
    }
  } catch {
    if (!allowSynchronousPidFallback) {
      return;
    }
  }
  if (allowSynchronousPidFallback) {
    // Failure unwind has not crossed an asynchronous boundary, so the saved
    // PID is still bounded to this synchronous stopped-root custody window.
    signalProcess(root.pid, "SIGCONT");
  }
}

async function signalSameProcess(
  expected: PosixProcess,
  signal: NodeJS.Signals,
  deadline: number,
): Promise<boolean> {
  // Portable Node POSIX signals are PID-based, so never retain numeric authority:
  // take this final identity snapshot synchronously immediately before every signal.
  const current = await readCodexAppServerProcess(expected.pid, deadline).catch(() => undefined);
  return Boolean(
    current && isSameLiveProcess(current, expected) && signalProcess(current.pid, signal),
  );
}

function hasSameIdentity(
  left: CodexAppServerProcessIdentity,
  right: CodexAppServerProcessIdentity,
): boolean {
  return identityKey(left) === identityKey(right);
}

function identityKey(row: CodexAppServerProcessIdentity): string {
  return `${row.pid}\0${row.startedAt}`;
}

function hasExited(child: ContainableTransport): boolean {
  return child.exitCode != null || child.signalCode != null;
}

function signalProcess(pid: number, signal: NodeJS.Signals): boolean {
  try {
    process.kill(pid, signal);
    return true;
  } catch {
    return false;
  }
}

import { ChildProcess } from "node:child_process";
import { createHash } from "node:crypto";
import { PassThrough } from "node:stream";
import { createPluginStateSyncKeyedStore } from "openclaw/plugin-sdk/plugin-state-store-runtime";
import { createOpenClawTestState } from "openclaw/plugin-sdk/test-state";
import { afterEach, beforeEach, describe, expect, it, vi, type MockInstance } from "vitest";
import { terminateCodexAppServerOrphan } from "./transport-process-containment.js";
import { prepareCodexAppServerProcessRegistration } from "./transport-process-registration.js";
import { readCodexAppServerProcessSnapshot } from "./transport-process-snapshot.js";

const procfs = vi.hoisted(() => ({ files: new Map<string, string | Error | (() => string)>() }));
vi.mock("node:fs/promises", async (importOriginal) => {
  const original = await importOriginal<typeof import("node:fs/promises")>();
  return {
    ...original,
    readFile: (...args: Parameters<typeof original.readFile>) => {
      const file = args[0];
      if (typeof file !== "string" || !file.startsWith("/proc/")) {
        return original.readFile(...args);
      }
      const stored = procfs.files.get(file);
      const value = typeof stored === "function" ? stored() : stored;
      return typeof value === "string"
        ? Promise.resolve(value)
        : Promise.reject(value ?? Object.assign(new Error("gone"), { code: "ENOENT" }));
    },
    readdir: (...args: Parameters<typeof original.readdir>) =>
      args[0] === "/proc"
        ? Promise.resolve(
            [...procfs.files.keys()].flatMap(
              (file) => /^\/proc\/(\d+)\/stat$/.exec(file)?.[1] ?? [],
            ),
          )
        : original.readdir(...args),
  };
});

const bootId = "00000000-0000-0000-0000-000000000001";
const identity = (pid: number) => ({ pid, pgid: pid, startedAt: `${bootId}:12345` });
const parent = identity(500001);
const child = identity(500002);
const neighbor = 500003;
const command = "/opt/codex app-server --listen stdio://";
const commandFingerprint = createHash("sha256").update(command).digest("hex");

function addProcess(pid: number, ppid: number) {
  procfs.files.set(
    `/proc/${pid}/stat`,
    `${pid} (worker) S ${ppid} ${pid}${" 0".repeat(16)} 12345\n`,
  );
  procfs.files.set(`/proc/${pid}/cmdline`, command.replaceAll(" ", "\0"));
}

describe("Codex registration procfs boundary", () => {
  let state: Awaited<ReturnType<typeof createOpenClawTestState>>;
  let store: ReturnType<
    typeof createPluginStateSyncKeyedStore<{
      parent: ReturnType<typeof identity>;
      child: ReturnType<typeof identity> & { commandFingerprint: string };
    }>
  >;
  let kill: MockInstance<typeof process.kill>;

  beforeEach(async () => {
    state = await createOpenClawTestState({ prefix: "codex-registration-procfs-" });
    store = createPluginStateSyncKeyedStore("codex", {
      namespace: "app-server-processes",
      maxEntries: 512,
      overflowPolicy: "reject-new",
    });
    vi.spyOn(process, "platform", "get").mockReturnValue("linux");
    // Synthetic PIDs must never reach the real signal syscall, even on regression.
    kill = vi.spyOn(process, "kill").mockImplementation(() => {
      throw new Error("unexpected signal");
    });
    procfs.files.set("/proc/sys/kernel/random/boot_id", bootId);
    addProcess(process.pid, process.ppid);
    addProcess(parent.pid, 1);
    addProcess(child.pid, parent.pid);
    procfs.files.set(
      `/proc/${neighbor}/stat`,
      Object.assign(new Error("unreadable neighbor"), { code: "EACCES" }),
    );
  });

  afterEach(async () => {
    store.clear();
    vi.restoreAllMocks();
    procfs.files.clear();
    await state.cleanup();
  });

  it("preserves a live owner's registration despite an unreadable unrelated process", async () => {
    const registration = { parent, child: { ...child, commandFingerprint } };
    store.register("owned", registration);

    await expect(
      Promise.all([
        prepareCodexAppServerProcessRegistration(),
        prepareCodexAppServerProcessRegistration(),
      ]),
    ).resolves.toHaveLength(2);

    expect(store.lookup("owned")).toEqual(registration);
    expect(kill).not.toHaveBeenCalled();
  });

  it.for(["readable", "startup", "permission", "malformed", "deadline", "missing-observer"])(
    "registers a direct child despite an unreadable unrelated process only with usable ownership: %s",
    async (mode, ctx) => {
      addProcess(child.pid, process.pid);
      const stdin = new PassThrough();
      const stdout = new PassThrough();
      const stderr = new PassThrough();
      const spawned = Object.assign(new ChildProcess(), {
        pid: child.pid,
        stdin,
        stdout,
        stderr,
        stdio: [stdin, stdout, stderr, null, null] as [
          PassThrough,
          PassThrough,
          PassThrough,
          null,
          null,
        ],
      });
      ctx.onTestFinished(() => {
        stdin.destroy();
        stdout.destroy();
        stderr.destroy();
        spawned.removeAllListeners();
      });
      const register = await prepareCodexAppServerProcessRegistration();
      if (mode === "startup") {
        let reads = 0;
        procfs.files.set(`/proc/${child.pid}/cmdline`, () => {
          expect(store.entries()).toEqual([]);
          return reads++ === 0 ? "" : command.replaceAll(" ", "\0");
        });
      } else if (mode === "missing-observer") {
        procfs.files.delete(`/proc/${process.pid}/stat`);
      } else if (mode !== "readable") {
        procfs.files.set(
          `/proc/${child.pid}/stat`,
          mode === "malformed"
            ? ""
            : Object.assign(new Error("child inspection failed"), {
                code: mode === "deadline" ? "ABORT_ERR" : "EACCES",
              }),
        );
      }
      const registered = register(spawned);
      spawned.emit("spawn");

      if (mode !== "readable" && mode !== "startup") {
        await expect(registered).rejects.toMatchObject({
          reason: mode === "permission" || mode === "deadline" ? mode : "unavailable",
        });
        expect(store.entries()).toEqual([]);
        expect(kill).not.toHaveBeenCalled();
        return;
      }
      await registered;

      expect(store.entries().map((entry) => entry.value)).toEqual([
        { parent: identity(process.pid), child: { ...child, commandFingerprint } },
      ]);
      expect(kill).not.toHaveBeenCalled();
      spawned.emit("exit", 0, null);
      expect(store.entries()).toEqual([]);
    },
  );

  it.for([
    ["permission", "EACCES"],
    ["unavailable", "EIO"],
    ["deadline", "ABORT_ERR"],
    ["unavailable", "empty"],
    ["unavailable", "group-zero"],
    ["unavailable", "missing-observer"],
  ] as const)(
    "retains registrations when required identity inspection fails: %s/%s",
    async ([reason, fault]) => {
      const registration = { parent, child: { ...child, commandFingerprint } };
      store.register("owned", registration);
      if (fault === "missing-observer") {
        procfs.files.delete(`/proc/${process.pid}/stat`);
      } else {
        procfs.files.set(
          `/proc/${parent.pid}/stat`,
          fault === "empty"
            ? ""
            : fault === "group-zero"
              ? `${parent.pid} (worker) S 1 0${" 0".repeat(16)} 12345\n`
              : Object.assign(new Error("required inspection failed"), { code: fault }),
        );
      }

      await expect(prepareCodexAppServerProcessRegistration()).rejects.toMatchObject({ reason });
      expect(store.lookup("owned")).toEqual(registration);
      expect(kill).not.toHaveBeenCalled();
    },
  );

  it("keeps full-tree inspection fail-closed with the same unreadable neighbor", async () => {
    await expect(readCodexAppServerProcessSnapshot()).rejects.toMatchObject({
      reason: "permission",
    });
    await expect(terminateCodexAppServerOrphan(child)).resolves.toBe(false);
    expect(kill).not.toHaveBeenCalled();
  });

  it.for(["ENOENT", "ESRCH"])(
    "retires verified disappeared identities only after full containment inspection: %s",
    async (code) => {
      store.register("orphan", { parent, child: { ...child, commandFingerprint } });
      for (const pid of [parent.pid, child.pid]) {
        procfs.files.set(`/proc/${pid}/stat`, Object.assign(new Error("gone"), { code }));
      }
      // Selected identities are gone, but an unreadable full tree still blocks retirement.
      await expect(prepareCodexAppServerProcessRegistration()).rejects.toThrow(
        "Cannot reap registered Codex process",
      );
      expect(store.lookup("orphan")).toBeDefined();
      procfs.files.delete(`/proc/${neighbor}/stat`);
      await prepareCodexAppServerProcessRegistration();
      expect(store.lookup("orphan")).toBeUndefined();
      expect(kill).not.toHaveBeenCalled();
    },
  );
});

