  it.for(["live", "unreadable command", "exited during inspection", "windows"])(
    "registers only a live child with its command: %s",
    async (mode, ctx) => {
      if (mode === "windows") {
        vi.spyOn(process, "platform", "get").mockReturnValue("win32");
      }
      const stdin = new PassThrough();
      const stdout = new PassThrough();
      const stderr = new PassThrough();
      // The typed stdio tuple makes this fixture structurally a
      // ChildProcessWithoutNullStreams without widening casts.
      const spawned = Object.assign(new ChildProcess(), {
        pid: child.pid,
        stdin,
        stdout,
        stderr,
        stdio: [stdin, stdout, stderr, null, null] as [
          PassThrough,
          PassThrough,
          PassThrough,
          null,
          null,
        ],
      });
      ctx.onTestFinished(() => {
        spawned.stdin.destroy();
        spawned.stdout.destroy();
        spawned.stderr.destroy();
        spawned.removeAllListeners();
      });
      const kill = vi.spyOn(spawned, "kill").mockReturnValue(true);
      vi.mocked(readCodexAppServerProcessSnapshot).mockResolvedValue([
        observer,
        { ...liveChild, ppid: process.pid },
      ]);
      vi.mocked(readCodexAppServerProcessCommand).mockImplementation(async () => {
        if (mode === "exited during inspection") {
          Object.defineProperty(spawned, "exitCode", { value: 0, configurable: true });
          spawned.emit("exit", 0, null);
        }
        if (mode === "unreadable command") {
          throw new ProcessInspectionError("permission");
        }
        return command;
      });
      const register = await prepareCodexAppServerProcessRegistration();
      const registered = register(spawned);
      spawned.emit("spawn");

      if (mode === "windows") {
        await registered;
        expect(readCodexAppServerProcessSnapshot).not.toHaveBeenCalled();
        expect(readCodexAppServerProcessCommand).not.toHaveBeenCalled();
        expect(store.entries()).toEqual([]);
        expect(kill).not.toHaveBeenCalled();
      } else if (mode === "live") {
        await registered;
        expect(store.entries().map((entry) => entry.value)).toEqual([
          {
            parent: { pid: observer.pid, pgid: observer.pgid, startedAt: observer.startedAt },
            child: { ...child, commandFingerprint },
          },
        ]);
        // Durable rows must never expose the raw argv (appServer.args can carry secrets).
        expect(JSON.stringify(store.entries())).not.toContain(command);
        expect(kill).not.toHaveBeenCalled();
        spawned.emit("exit", 0, null);
        expect(store.entries()).toEqual([]);
      } else {
        await expect(registered).rejects.toThrow(
          mode === "unreadable command"
            ? "Cannot inspect Codex processes"
            : "Cannot register the Codex child process command",
        );
        expect(store.entries()).toEqual([]);
      }
    },
  );

  it.for(["success", "failure", "win32"])(
    "starts a nonblocking best-effort boot sweep: %s",
    async (mode) => {
      store.register("orphan", { parent, child: { ...child, commandFingerprint } });
      const warn = vi.fn();
      const service = createCodexAppServerProcessReaperService();
      const sweep = createDeferred<boolean>();
      vi.mocked(terminateCodexAppServerOrphan).mockReturnValue(sweep.promise);
      if (mode === "win32") {
        vi.spyOn(process, "platform", "get").mockReturnValue("win32");
      }

      expect(
        service.start({
          config: {},
          stateDir: root,
          logger: { debug: vi.fn(), info: vi.fn(), warn, error: vi.fn() },
        }),
      ).toBeUndefined();

      if (mode === "win32") {
        expect(readCodexAppServerProcessSnapshot).not.toHaveBeenCalled();
        expect(terminateCodexAppServerOrphan).not.toHaveBeenCalled();
        expect(store.lookup("orphan")).toBeDefined();
        expect(warn).not.toHaveBeenCalled();
        return;
      }
      await expect.poll(() => vi.mocked(terminateCodexAppServerOrphan).mock.calls.length).toBe(1);
      if (mode === "failure") {
        sweep.reject(new Error("inspection unavailable"));
        await expect
          .poll(() => warn.mock.calls)
          .toEqual([["Codex app-server orphan cleanup failed: Error: inspection unavailable"]]);
        expect(store.lookup("orphan")).toBeDefined();
      } else {
        sweep.resolve(true);
        await expect.poll(() => store.lookup("orphan")).toBeUndefined();
        expect(warn).not.toHaveBeenCalled();
      }
    },
  );
});

import type { ChildProcessWithoutNullStreams } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import { once } from "node:events";
import type { OpenClawPluginService } from "openclaw/plugin-sdk/plugin-entry";
import { z } from "zod";
import { terminateCodexAppServerOrphan } from "./transport-process-containment.js";
import {
  ProcessInspectionError,
  readCodexAppServerProcessCommand,
  readCodexAppServerProcessSnapshot,
} from "./transport-process-snapshot.js";

const processIdentity = z.object({
  pid: z.number().int().positive().safe(),
  pgid: z.number().int().positive().safe(),
  startedAt: z.string().min(1).max(64),
});
const childIdentity = processIdentity.extend({
  // Durable rows hold only a digest: appServer.args is operator-configurable and
  // may carry secrets, matching the spawn-identity argsFingerprint precedent.
  // Unreleased dev/nightly rows stay reapable with identity-only authority instead
  // of blocking spawns. Require the fingerprint at the next natural schema touch.
  commandFingerprint: z
    .string()
    .regex(/^[a-f0-9]{64}$/)
    .optional(),
});
const registrationSchema = z.object({ parent: processIdentity, child: childIdentity }).strict();
type ProcessRegistration = z.infer<typeof registrationSchema>;

function fingerprintProcessCommand(command: string): string {
  return createHash("sha256").update(command).digest("hex");
}

async function openProcessRegistrationStore() {
  const { createPluginStateSyncKeyedStore } =
    await import("openclaw/plugin-sdk/plugin-state-store-runtime");
  return createPluginStateSyncKeyedStore<ProcessRegistration>("codex", {
    namespace: "app-server-processes",
    maxEntries: 512,
    // Expiration or eviction could forget a child that still owns a native turn.
    overflowPolicy: "reject-new",
  });
}

async function reapRegisteredCodexAppServerOrphans(requestedDeadline?: number): Promise<void> {
  const store = await openProcessRegistrationStore();
  const deadline = requestedDeadline ?? Date.now() + 10_000;
  for (const entry of store.entries()) {
    if (Date.now() >= deadline) {
      throw new Error("Codex orphan cleanup exceeded its startup budget. Retry to finish cleanup.");
    }
    const registration = registrationSchema.parse(entry.value);
    const snapshot = await readCodexAppServerProcessSnapshot(undefined, [
      registration.parent.pid,
      registration.child.pid,
    ]);
    const parent = snapshot.find((row) => row.pid === registration.parent.pid);
    if (parent?.startedAt === registration.parent.startedAt && !parent.state.startsWith("Z")) {
      continue;
    }
    const child = snapshot.find((row) => row.pid === registration.child.pid);
    if (
      registration.child.commandFingerprint !== undefined &&
      child?.startedAt === registration.child.startedAt &&
      !child.state.startsWith("Z")
    ) {
      let command: string | undefined;
      try {
        command = await readCodexAppServerProcessCommand(child, deadline);
      } catch (error) {
        // Only a successful inspection may revoke the fingerprint obligation.
        const current = (
          await readCodexAppServerProcessSnapshot(deadline, [registration.child.pid])
        ).find((row) => row.pid === registration.child.pid);
        if (current?.startedAt === registration.child.startedAt) {
          throw error;
        }
      }
      if (
        command !== undefined &&
        fingerprintProcessCommand(command) !== registration.child.commandFingerprint
      ) {
        // macOS lstart has second granularity: a replacement can inherit pid +
        // startedAt. A different command revokes kill authority; Linux already
        // uses tick-granular start identities.
        store.delete(entry.key);
        continue;
      }
    }
    if (!(await terminateCodexAppServerOrphan(registration.child))) {
      throw new Error(
        `Cannot reap registered Codex process ${registration.child.pid}. Stop it before retrying.`,
      );
    }
    store.delete(entry.key);
  }
}

export function createCodexAppServerProcessReaperService(): OpenClawPluginService {
  return {
    id: "codex-app-server-process-reaper",
    start(ctx) {
      if (process.platform === "win32") {
        return;
      }
      // Boot cleanup is best-effort promptness. The before-spawn check remains
      // authoritative and fails closed without delaying Gateway startup.
      void (async () => {
        try {
          await reapRegisteredCodexAppServerOrphans();
        } catch (error) {
          ctx.logger.warn(`Codex app-server orphan cleanup failed: ${String(error)}`);
        }
      })();
    },
  };
}

/** Reap previous owners before spawn; commit this child's identity before initialization. */
export async function prepareCodexAppServerProcessRegistration(): Promise<
  (child: ChildProcessWithoutNullStreams) => Promise<void>
> {
  if (process.platform === "win32") {
    return async (child) => {
      await once(child, "spawn");
    };
  }
  await reapRegisteredCodexAppServerOrphans();
  const store = await openProcessRegistrationStore();
  return async (child) => {
    await once(child, "spawn");
    if (!child.pid) {
      throw new ProcessInspectionError("unavailable");
    }
    const snapshot = await readCodexAppServerProcessSnapshot(undefined, [child.pid]);
    const parent = snapshot.find((row) => row.pid === process.pid);
    const spawned = snapshot.find((row) => row.pid === child.pid);
    if (!parent || !spawned || spawned.ppid !== process.pid) {
      throw new Error(
        "Cannot register the Codex child process: its direct-parent identity is unavailable. Retry.",
      );
    }
    const command = await readCodexAppServerProcessCommand(spawned, Date.now() + 2_000);
    if (child.exitCode !== null || child.signalCode !== null) {
      throw new Error(
        "Cannot register the Codex child process command: the child exited during inspection. Retry.",
      );
    }
    const key = randomUUID();
    // Codex rejects non-initialize requests; no native turn can start before
    // this synchronous commit. A failed commit closes the uninitialized child.
    store.register(key, {
      parent: processIdentity.parse(parent),
      child: childIdentity.parse({
        ...spawned,
        commandFingerprint: fingerprintProcessCommand(command),
      }),
    });
    child.once("exit", () => {
      try {
        store.delete(key);
      } catch {
        // Leave the durable fact for the next connection to verify and remove.
      }
    });
  };
}

import { execFileSync } from "node:child_process";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { isPidAlive } from "openclaw/plugin-sdk/process-runtime";
import { withEnvAsync } from "openclaw/plugin-sdk/test-env";
import { describe, expect, it, vi } from "vitest";
import {
  type PosixProcess,
  readCodexAppServerProcessCommand,
  readCodexAppServerProcessSnapshot,
} from "./transport-process-snapshot.js";

const procfs = vi.hoisted(() => ({
  readFile: vi.fn<(file: string) => Promise<string>>(),
  readdir: vi.fn<() => Promise<string[]>>(),
}));

const observedProcess: PosixProcess = {
  pid: process.pid,
  ppid: process.ppid,
  pgid: process.pid,
  state: "S",
  startedAt: "00000000-0000-0000-0000-000000000001:12345",
};

vi.mock("node:fs/promises", async (importOriginal) => {
  const original = await importOriginal<typeof import("node:fs/promises")>();
  return {
    ...original,
    readFile: (...args: Parameters<typeof original.readFile>) =>
      typeof args[0] === "string" &&
      args[0].startsWith("/proc/") &&
      procfs.readFile.getMockImplementation()
        ? procfs.readFile(args[0])
        : original.readFile(...args),
    readdir: (...args: Parameters<typeof original.readdir>) =>
      args[0] === "/proc" && procfs.readdir.getMockImplementation()
        ? procfs.readdir()
        : original.readdir(...args),
  };
});

describe("Codex procfs command inspector", () => {
  it.for([
    "ready",
    "empty",
    "gone",
    "replaced",
    "zombie",
    "reparented",
    "regrouped",
    "malformed",
    "permission",
    "read-error",
    "replaced after read",
  ])("binds empty-command startup readiness to the same live process: %s", async (mode, ctx) => {
    ctx.onTestFinished(() => {
      procfs.readFile.mockReset();
      vi.restoreAllMocks();
    });
    vi.spyOn(process, "platform", "get").mockReturnValue("linux");
    // Synthetic procfs outcomes must not race host scheduling between reads.
    let now = Date.now();
    const deadline = now + 250;
    vi.spyOn(Date, "now").mockImplementation(() => now);
    const bootId = "00000000-0000-0000-0000-000000000001";
    let commandReads = 0;
    procfs.readFile.mockImplementation(async (file) => {
      if (file === "/proc/sys/kernel/random/boot_id") {
        return bootId;
      }
      if (file === `/proc/${process.pid}/cmdline`) {
        commandReads += 1;
        if (commandReads > 1 && mode === "empty") {
          now = deadline;
        }
        if (commandReads > 1 && mode === "read-error") {
          throw Object.assign(new Error("command read failed"), { code: "EIO" });
        }
        return commandReads === 1 || mode === "empty" ? "" : "/opt/codex\0app-server\0";
      }
      expect(file).toBe(`/proc/${process.pid}/stat`);
      if (commandReads && (mode === "gone" || mode === "permission")) {
        throw Object.assign(new Error("identity unavailable"), {
          code: mode === "gone" ? "ENOENT" : "EACCES",
        });
      }
      if (commandReads && mode === "malformed") {
        return "";
      }
      const changed = commandReads > 0;
      const state = changed && mode === "zombie" ? "Z" : "R";
      const ppid = process.ppid + Number(changed && mode === "reparented");
      const pgid = process.pid + Number(changed && mode === "regrouped");
      const replaced =
        (changed && mode === "replaced") || (commandReads > 1 && mode === "replaced after read");
      return `${process.pid} (codex) ${state} ${ppid} ${pgid}${" 0".repeat(16)} ${replaced ? 54321 : 12345}\n`;
    });
    const observed = (await readCodexAppServerProcessSnapshot(undefined, [process.pid]))[0]!;
    const inspected = readCodexAppServerProcessCommand(observed, deadline);
    if (mode === "ready") {
      await expect(inspected).resolves.toBe("/opt/codex app-server");
    } else {
      await expect(inspected).rejects.toMatchObject({
        reason:
          mode === "empty" ? "deadline" : mode === "permission" ? "permission" : "unavailable",
      });
    }
    if (["ready", "empty", "read-error", "replaced after read"].includes(mode)) {
      expect(commandReads).toBe(2);
    }
  });

  it.for([
    {
      input: "/opt/codex\0app-server\0--listen\0stdio://\0",
      expected: "/opt/codex app-server --listen stdio://",
    },
    { input: "\0", reason: "unavailable" },
    { input: " \0 ", reason: "unavailable" },
    { code: "ENOENT", reason: "unavailable" },
    { code: "ESRCH", reason: "unavailable" },
    { code: "EACCES", reason: "permission" },
    { code: "ABORT_ERR", reason: "deadline" },
  ])(
    "reads command identity without authorizing absent or unreadable processes: %j",
    async (fixture, ctx) => {
      ctx.onTestFinished(() => {
        procfs.readFile.mockReset();
        vi.restoreAllMocks();
      });
      vi.spyOn(process, "platform", "get").mockReturnValue("linux");
      procfs.readFile.mockImplementation(async (file) => {
        expect(file).toBe(`/proc/${process.pid}/cmdline`);
        if (fixture.code) {
          throw Object.assign(new Error("command unavailable"), { code: fixture.code });
        }
        return fixture.input!;
      });

      const inspected = readCodexAppServerProcessCommand(observedProcess, Date.now() + 1_000);
      if (fixture.reason) {
        await expect(inspected).rejects.toMatchObject({ reason: fixture.reason });
        if (fixture.reason !== "permission") {
          await expect(inspected).rejects.not.toThrow("permissions");
        }
        if (fixture.reason === "deadline") {
          await expect(inspected).rejects.toThrow("deadline");
        }
      } else {
        await expect(inspected).resolves.toBe(fixture.expected);
      }
      procfs.readFile.mockClear();
      await expect(
        readCodexAppServerProcessCommand(observedProcess, Date.now() - 1),
      ).rejects.toMatchObject({ reason: "deadline" });
      expect(procfs.readFile).not.toHaveBeenCalled();
    },
  );
});

describe("Codex procfs process inspector", () => {
  it.for(["ENOENT", "ESRCH", "EACCES"] as const)(
    "distinguishes a vanished neighbor from unreadable state: %s",
    async (code, ctx) => {
      ctx.onTestFinished(() => {
        procfs.readFile.mockReset();
        procfs.readdir.mockReset();
        vi.restoreAllMocks();
      });
      vi.spyOn(process, "platform", "get").mockReturnValue("linux");
      const bootId = "00000000-0000-0000-0000-000000000001";
      const neighborPid = process.pid + 1;
      procfs.readdir.mockResolvedValue([String(process.pid), String(neighborPid)]);
      procfs.readFile.mockImplementation(async (file) => {
        if (file === "/proc/sys/kernel/random/boot_id") {
          return bootId;
        }
        if (file === `/proc/${process.pid}/stat`) {
          // Fields 3..22 follow the final ')', even when comm contains ')' and spaces.
          return `${process.pid} (codex ) worker) S ${process.ppid} ${process.pid}${" 0".repeat(16)} 12345${" 0".repeat(30)}\n`;
        }
        if (file === `/proc/${neighborPid}/stat`) {
          throw Object.assign(new Error("neighbor process read failed"), { code });
        }
        throw new Error(`Unexpected procfs read: ${file}`);
      });
      const snapshot = readCodexAppServerProcessSnapshot();
      if (code === "EACCES") {
        await expect(snapshot).rejects.toMatchObject({ reason: "permission" });
      } else {
        await expect(snapshot).resolves.toEqual([
          {
            pid: process.pid,
            ppid: process.ppid,
            pgid: process.pid,
            state: "S",
            startedAt: `${bootId}:12345`,
          },
        ]);
      }
    },
  );
});

describe.skipIf(process.platform === "win32" || process.platform === "linux")(
  "Codex POSIX process inspector",
  () => {
    it.for(["gone", "missing observer", "malformed"])(
      "requires complete selected ps evidence when the target is %s",
      async (mode, ctx) => {
        const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "codex-ps-selected-"));
        ctx.onTestFinished(() => fs.rm(tempDir, { recursive: true, force: true }));
        await fs.writeFile(
          path.join(tempDir, "ps"),
          `#!/usr/bin/env node
const selected = process.argv[process.argv.indexOf("-p") + 1]?.split(",");
if (selected?.includes("${process.pid}") && ${JSON.stringify(mode)} !== "missing observer") {
  console.log("${process.pid} ${process.ppid} ${process.pid} S Sat Aug 29 10:00:00 2026");
}
if (${JSON.stringify(mode)} === "malformed") console.log("unusable selected process");
`,
          { mode: 0o755 },
        );
        await withEnvAsync(
          { PATH: `${tempDir}${path.delimiter}${process.env.PATH ?? ""}` },
          async () => {
            const inspected = readCodexAppServerProcessSnapshot(undefined, [process.pid + 1]);
            if (mode === "gone") {
              await expect(inspected).resolves.toMatchObject([{ pid: process.pid }]);
            } else {
              await expect(inspected).rejects.toMatchObject({ reason: "unavailable" });
            }
          },
        );
      },
    );

    it.for([
      ["snapshot", "unavailable"],
      ["snapshot", "hung"],
      ["command", "unavailable"],
      ["command", "hung"],
    ] as const)(
      "settles a %s ps inspector without leaking its process",
      async ([kind, mode], ctx) => {
        const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "codex-ps-deadline-"));
        const inspectorPath = path.join(tempDir, "ps");
        const pidPath = path.join(tempDir, "inspector.pid");
        let inspectorPid: number | undefined;
        ctx.onTestFinished(async () => {
          const pid = inspectorPid ?? Number(await fs.readFile(pidPath, "utf8").catch(() => ""));
          if (pid && isPidAlive(pid)) {
            const command = execFileSync("/bin/ps", ["-o", "command=", "-p", String(pid)], {
              encoding: "utf8",
              stdio: ["ignore", "pipe", "ignore"],
            });
            if (command.includes(inspectorPath)) {
              process.kill(pid, "SIGKILL");
            }
          }
          await fs.rm(tempDir, { recursive: true, force: true });
        });
        await fs.writeFile(
          inspectorPath,
          `#!/usr/bin/env node
const fs = require("node:fs");
fs.writeFileSync(process.env.CODEX_TEST_PS_PID_FILE, String(process.pid));
${mode === "unavailable" ? "process.exit(1);" : "setInterval(() => {}, 1000);"}
`,
          { mode: 0o755 },
        );
        await withEnvAsync(
          {
            PATH: `${tempDir}${path.delimiter}${process.env.PATH ?? ""}`,
            CODEX_TEST_PS_PID_FILE: pidPath,
          },
          async () => {
            const startedAt = Date.now();
            const budgetMs = 1_000;
            const result =
              kind === "command"
                ? readCodexAppServerProcessCommand(observedProcess, startedAt + budgetMs)
                : readCodexAppServerProcessSnapshot(startedAt + budgetMs);
            await expect(result).rejects.toMatchObject({
              reason: mode === "hung" ? "deadline" : "unavailable",
            });
            const pid = Number(await fs.readFile(pidPath, "utf8"));
            inspectorPid = pid;
            expect(pid).toBeGreaterThan(0);
            // Allow scheduler jitter, but not the inspector's unbounded event loop.
            expect(Date.now() - startedAt).toBeLessThan(budgetMs + 500);
            await expect.poll(() => isPidAlive(pid)).toBe(false);
          },
        );
      },
    );
  },
);

import { execFile } from "node:child_process";
import { readdir, readFile } from "node:fs/promises";
import { setImmediate } from "node:timers/promises";

export type PosixProcess = {
  pid: number;
  ppid: number;
  pgid: number;
  state: string;
  startedAt: string;
};

const PROCESS_COLUMNS = "pid=,ppid=,pgid=,stat=,lstart=";
const MAX_PROCESS_CONTAINMENT_MS = 2_000;
const PROCESS_INSPECTION_MAX_BYTES = 8 * 1024 * 1024;

export class ProcessInspectionError extends Error {
  constructor(readonly reason: "deadline" | "permission" | "unavailable") {
    const detail = {
      deadline: "Process inspection exceeded its deadline. Retry when the host is responsive.",
      permission: "Check process inspection permissions (/proc on Linux, ps on macOS), then retry.",
      unavailable:
        "Process identity is unavailable or invalid. Check /proc on Linux or ps on macOS, then retry.",
    }[reason];
    super(`Cannot inspect Codex processes. ${detail}`);
    this.name = "ProcessInspectionError";
  }
}

function inspectionFailure(error: unknown): ProcessInspectionError {
  if (error instanceof ProcessInspectionError) {
    return error;
  }
  const code = error && typeof error === "object" && "code" in error ? error.code : undefined;
  // Every abort signal in this reader is owned by its inspection deadline.
  return new ProcessInspectionError(
    code === "ABORT_ERR"
      ? "deadline"
      : code === "EACCES" || code === "EPERM" || code === "ERR_ACCESS_DENIED"
        ? "permission"
        : "unavailable",
  );
}

export async function readCodexAppServerProcessSnapshot(
  deadline = Date.now() + MAX_PROCESS_CONTAINMENT_MS,
  pids?: readonly number[],
): Promise<PosixProcess[]> {
  // Registration proves only known owners. Containment still needs the full tree.
  // Include the observer so an empty selected ps result cannot prove disappearance.
  const selected = pids === undefined ? undefined : [...new Set([process.pid, ...pids])];
  const rows =
    process.platform === "linux"
      ? await readLinuxProcesses(selected, deadline)
      : await readProcesses(
          selected ? ["-o", PROCESS_COLUMNS, "-p", selected.join(",")] : ["-axo", PROCESS_COLUMNS],
          deadline,
          selected !== undefined,
        );
  if (selected && !rows.some((row) => row.pid === process.pid)) {
    throw new ProcessInspectionError("unavailable");
  }
  return rows;
}

export async function readCodexAppServerProcess(
  pid: number,
  deadline: number,
): Promise<PosixProcess | undefined> {
  const rows =
    process.platform === "linux"
      ? await readLinuxProcesses([pid], deadline)
      : await readProcesses(["-o", PROCESS_COLUMNS, "-p", String(pid)], deadline);
  return rows.find((row) => row.pid === pid);
}

export async function readCodexAppServerProcessCommand(
  observed: PosixProcess,
  deadline: number,
): Promise<string> {
  let output: string;
  if (process.platform === "linux") {
    let pending = false;
    do {
      const remainingMs = deadline - Date.now();
      if (remainingMs <= 0) {
        throw new ProcessInspectionError("deadline");
      }
      let command: string;
      try {
        command = await readFile(`/proc/${observed.pid}/cmdline`, {
          encoding: "utf8",
          signal: AbortSignal.timeout(remainingMs),
        });
      } catch (error) {
        throw inspectionFailure(error);
      }
      // Linux can expose zero command bytes during exec startup. Wait only for
      // that state, with the original identity and deadline, including the final read.
      if (!command || pending) {
        const current = await readCodexAppServerProcess(observed.pid, deadline);
        if (
          !current ||
          current.startedAt !== observed.startedAt ||
          current.ppid !== observed.ppid ||
          current.pgid !== observed.pgid ||
          current.state.startsWith("Z")
        ) {
          throw new ProcessInspectionError("unavailable");
        }
      }
      output = command.split("\0").join(" ").trim();
      pending = command.length === 0;
      if (pending) {
        await setImmediate();
      }
    } while (pending);
  } else {
    output =
      (await readProcessOutput(["-o", "command=", "-p", String(observed.pid)], deadline))
        .split("\n")[0]
        ?.trim() ?? "";
  }
  if (Date.now() >= deadline) {
    throw new ProcessInspectionError("deadline");
  }
  if (!output) {
    throw new ProcessInspectionError("unavailable");
  }
  return output;
}

async function readProcesses(
  args: string[],
  deadline: number,
  selected = false,
): Promise<PosixProcess[]> {
  const output = await readProcessOutput(args, deadline);
  return parseProcesses(output, selected);
}

async function readProcessOutput(args: string[], deadline: number): Promise<string> {
  const remainingMs = deadline - Date.now();
  if (remainingMs <= 0) {
    throw new ProcessInspectionError("deadline");
  }
  return await new Promise<string>((resolve, reject) => {
    let settled = false;
    const settle = (output: string | ProcessInspectionError) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timer);
      if (output instanceof ProcessInspectionError) {
        reject(output);
      } else {
        resolve(output);
      }
    };
    const inspector = execFile(
      "ps",
      args,
      {
        encoding: "utf8",
        maxBuffer: PROCESS_INSPECTION_MAX_BYTES,
        env: { ...process.env, LC_ALL: "C", TZ: "UTC" },
      },
      (error, stdout) => {
        settle(
          Date.now() >= deadline
            ? new ProcessInspectionError("deadline")
            : error
              ? inspectionFailure(error)
              : stdout,
        );
      },
    );
    const timer = setTimeout(
      () => {
        settle(new ProcessInspectionError("deadline"));
        inspector.stdout?.destroy();
        inspector.stderr?.destroy();
        inspector.kill("SIGKILL");
        inspector.unref();
      },
      Math.max(1, remainingMs),
    );
    timer.unref?.();
  });
}

function parseProcesses(output: string, selected: boolean): PosixProcess[] {
  const rows: PosixProcess[] = [];
  for (const line of output.split("\n")) {
    const match = /^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\S+)\s+(.+?)\s*$/.exec(line);
    if (!match) {
      if (selected && line.trim()) {
        throw new ProcessInspectionError("unavailable");
      }
      continue;
    }
    const pid = Number(match[1] ?? "");
    const ppid = Number(match[2] ?? "");
    const pgid = Number(match[3] ?? "");
    const startedAt = (match[5] ?? "").trim().replace(/\s+/g, " ");
    if (
      ![pid, ppid, pgid].every(Number.isSafeInteger) ||
      pid <= 0 ||
      ppid < 0 ||
      pgid <= 0 ||
      !startedAt
    ) {
      if (selected) {
        throw new ProcessInspectionError("unavailable");
      }
      continue;
    }
    rows.push({ pid, ppid, pgid, state: match[4] ?? "", startedAt });
  }
  return rows;
}

// Linux exposes stronger start identities in procfs; BusyBox ps on supported
// Alpine installs has no lstart. Boot identity prevents reuse across reboots.
async function readLinuxProcesses(
  selected: readonly number[] | undefined,
  deadline: number,
): Promise<PosixProcess[]> {
  const remainingMs = deadline - Date.now();
  if (remainingMs <= 0) {
    throw new ProcessInspectionError("deadline");
  }
  const options = { encoding: "utf8" as const, signal: AbortSignal.timeout(remainingMs) };
  try {
    const bootId = (await readFile("/proc/sys/kernel/random/boot_id", options)).trim();
    if (!/^[a-f0-9-]{36}$/.test(bootId)) {
      throw new ProcessInspectionError("unavailable");
    }
    const pids = selected === undefined ? await readdir("/proc") : selected.map(String);
    const rows: PosixProcess[] = [];
    let bytes = 0;
    for (const entry of pids) {
      if (!/^\d+$/.test(entry)) {
        continue;
      }
      if (Date.now() >= deadline) {
        throw new ProcessInspectionError("deadline");
      }
      const stat = await readFile(`/proc/${entry}/stat`, options).catch((error: unknown) => {
        // A process may exit between enumeration and read. Other failures must
        // not turn an unreadable process into proof that an orphan is gone.
        if (
          error &&
          typeof error === "object" &&
          "code" in error &&
          (error.code === "ENOENT" || error.code === "ESRCH")
        ) {
          return undefined;
        }
        throw error;
      });
      if (stat === undefined) {
        continue;
      }
      bytes += stat.length;
      if (bytes > PROCESS_INSPECTION_MAX_BYTES) {
        throw new ProcessInspectionError("unavailable");
      }
      // comm can contain spaces, newlines and ')'; fields 3..N follow its last ')'.
      const commEnd = stat.lastIndexOf(")");
      const fields = stat
        .slice(commEnd + 1)
        .trim()
        .split(/\s+/);
      const ppid = Number(fields[1]);
      const pgid = Number(fields[2]);
      const startTicks = fields[19];
      if (
        commEnd < 0 ||
        ![ppid, pgid].every(Number.isSafeInteger) ||
        (selected !== undefined && (pgid <= 0 || ppid < 0)) ||
        !/^\d+$/.test(startTicks ?? "")
      ) {
        throw new ProcessInspectionError("unavailable");
      }
      if (pgid > 0) {
        rows.push({
          pid: Number(entry),
          ppid,
          pgid,
          state: fields[0]!,
          startedAt: `${bootId}:${startTicks}`,
        });
      }
    }
    if (Date.now() >= deadline) {
      throw new ProcessInspectionError("deadline");
    }
    return rows;
  } catch (error) {
    throw inspectionFailure(error);
  }
}

