      command: "codex",
      args: [],
      url: `ws://127.0.0.1:${address.port}`,
      headers: {},
    });
    transports.push(transport);
    const exited = new Promise<unknown>((resolve) => {
      transport.once("exit", (code) => resolve(code));
    });
