    const localRegistration = vi
      .spyOn(processRegistration, "prepareCodexAppServerProcessRegistration")
      .mockRejectedValue(new Error("local inspection unavailable"));
    // macOS socket paths must fit sockaddr_un even when the runner nests TMPDIR.
    const tempRoot = process.platform === "darwin" ? "/tmp" : os.tmpdir();
    const tempDir = await mkdtemp(path.join(tempRoot, "openclaw-codex-unix-"));
    tempDirs.push(tempDir);
    const socketPath = path.join(tempDir, "app-server.sock");
    const httpServer = http.createServer();
    httpServers.push(httpServer);
    // Bind before ws forwards HTTP errors, so a listen failure rejects this test.
    await new Promise<void>((resolve, reject) => {
      httpServer.once("error", reject);
      httpServer.listen(socketPath, resolve);
    });
    const server = new WebSocketServer({ server: httpServer });
    servers.push(server);
    const upgradeExtensions: Array<string | undefined> = [];
    server.on("connection", (socket, request) => {
      upgradeExtensions.push(request.headers["sec-websocket-extensions"]);
      socket.on("message", (data) => {
        const message = JSON.parse(rawDataToText(data)) as { id?: number; method?: string };
        if (message.method === "initialize") {
          socket.send(
            JSON.stringify({
              id: message.id,
              result: { userAgent: `openclaw/${CODEX_APP_SERVER_VERSION}` },
            }),
          );
          return;
        }
        if (message.method === "thread/list") {
          socket.send(JSON.stringify({ id: message.id, result: { data: [] } }));
        }
      });
    });

    const client = await CodexAppServerClient.start({
      transport: "unix",
      homeScope: "user",
      url: `unix://${socketPath}`,
    });
    clients.push(client);

    await expect(client.initialize()).resolves.toBeUndefined();
    await expect(client.request("thread/list", {})).resolves.toEqual({ data: [] });
    expect(upgradeExtensions).toEqual([undefined]);
    expect(localRegistration).not.toHaveBeenCalled();
  });
});

function rawDataToText(data: RawData): string {
  if (Array.isArray(data)) {
    return Buffer.concat(data).toString("utf8");
  }
  if (data instanceof ArrayBuffer) {
    return Buffer.from(new Uint8Array(data)).toString("utf8");
  }
  return Buffer.from(data).toString("utf8");
}

/**
 * Adapts a remote Codex app-server WebSocket endpoint to the shared stdio-like
 * transport interface.
 */
import { EventEmitter } from "node:events";
import net from "node:net";
import path from "node:path";
import { PassThrough, Writable } from "node:stream";
import { StringDecoder } from "node:string_decoder";
import WebSocket, { type RawData } from "ws";
import { resolveCodexAppServerUserHomeDir, type CodexAppServerStartOptions } from "./config.js";
import type { CodexAppServerTransport } from "./transport.js";

const WEBSOCKET_HANDSHAKE_TIMEOUT_MS = 10_000;
const WEBSOCKET_PING_INTERVAL_MS = 20_000;
const WEBSOCKET_PONG_TIMEOUT_MS = 20_000;
const MAX_CONSECUTIVE_MISSED_WEBSOCKET_PONGS = 5;

/** Opens a WebSocket app-server transport and maps newline-delimited frames to stdout/stdin. */
export function createWebSocketTransport(
  options: CodexAppServerStartOptions,
): CodexAppServerTransport {
  if (!options.url) {
    throw new Error(
      "codex app-server websocket transport requires plugins.entries.codex.config.appServer.url",
    );
  }
  const events = new EventEmitter();
  const stdout = new PassThrough();
  const stderr = new PassThrough();
  const headers = {
    ...options.headers,
    ...(options.authToken ? { Authorization: `Bearer ${options.authToken}` } : {}),
  };
  const websocketOptions: WebSocket.ClientOptions = {
    headers,
    // Codex app-server closes Unix upgrade handshakes that offer compression.
    perMessageDeflate: false,
    ...(options.transport === "websocket"
      ? { handshakeTimeout: WEBSOCKET_HANDSHAKE_TIMEOUT_MS }
      : {}),
  };
  const unixSocketPath = resolveCodexAppServerUnixSocketPath(options);
  const socket = unixSocketPath
    ? new WebSocket("ws://localhost/", {
        ...websocketOptions,
        createConnection: () => connectCodexAppServerUnixSocket(unixSocketPath),
      })
    : new WebSocket(options.url, websocketOptions);
  const pendingFrames: string[] = [];
  const stdinDecoder = new StringDecoder("utf8");
  let pendingLine = "";
  let killed = false;
  let pingTimeout: NodeJS.Timeout | undefined;
  let pongTimeout: NodeJS.Timeout | undefined;
  let expectedPong: Buffer | undefined;
  let consecutiveMissedPongs = 0;
  let heartbeatSequence = 0;

  const clearConnectionHealthTimers = () => {
    if (pingTimeout) {
      clearTimeout(pingTimeout);
      pingTimeout = undefined;
    }
    if (pongTimeout) {
      clearTimeout(pongTimeout);
      pongTimeout = undefined;
    }
    expectedPong = undefined;
  };

  const sendHeartbeatPing = () => {
    if (socket.readyState !== WebSocket.OPEN || pongTimeout) {
      return;
    }

    const payload = Buffer.from(`openclaw-codex-${++heartbeatSequence}`);
    expectedPong = payload;
    pongTimeout = setTimeout(() => {
      pongTimeout = undefined;
      expectedPong = undefined;
      consecutiveMissedPongs += 1;
      if (consecutiveMissedPongs >= MAX_CONSECUTIVE_MISSED_WEBSOCKET_PONGS) {
        socket.terminate();
        return;
      }
      sendHeartbeatPing();
    }, WEBSOCKET_PONG_TIMEOUT_MS);
    pongTimeout.unref();
    socket.ping(payload, undefined, (error) => {
      if (error) {
        socket.terminate();
      }
    });
  };

  const scheduleHeartbeatPing = () => {
    if (
      options.transport !== "websocket" ||
      socket.readyState !== WebSocket.OPEN ||
      pingTimeout ||
      pongTimeout
    ) {
      return;
    }
    pingTimeout = setTimeout(() => {
      pingTimeout = undefined;
      sendHeartbeatPing();
    }, WEBSOCKET_PING_INTERVAL_MS);
    pingTimeout.unref();
  };

  const recordConnectionActivity = () => {
    consecutiveMissedPongs = 0;
    if (pongTimeout) {
      clearTimeout(pongTimeout);
      pongTimeout = undefined;
    }
    expectedPong = undefined;
    scheduleHeartbeatPing();
  };

  const sendFrame = (frame: string) => {
    const trimmed = frame.trim();
    if (!trimmed) {
      return;
    }
    if (socket.readyState === WebSocket.OPEN) {
      socket.send(trimmed);
      return;
    }
    pendingFrames.push(trimmed);
  };

  // `initialize` can be written before the WebSocket open event fires. Buffer
  // whole JSON-RPC frames so stdio and websocket transports share call timing.
  socket.once("open", () => {
    for (const frame of pendingFrames.splice(0)) {
      socket.send(frame);
    }
    scheduleHeartbeatPing();
  });
  socket.on("pong", (payload) => {
    if (expectedPong?.equals(payload)) {
      recordConnectionActivity();
    }
  });
  socket.once("error", (error) => {
    clearConnectionHealthTimers();
    events.emit("error", error);
  });
  socket.once("close", (code, reason) => {
    clearConnectionHealthTimers();
    killed = true;
    events.emit("exit", code, reason.toString("utf8"));
  });
  socket.on("message", (data) => {
    if (options.transport === "websocket") {
      recordConnectionActivity();
    }
    const text = websocketFrameToText(data);
    stdout.write(text.endsWith("\n") ? text : `${text}\n`);
  });

  const stdin = new Writable({
    write(chunk, _encoding, callback) {
      pendingLine += stdinDecoder.write(chunk);
      const lines = pendingLine.split("\n");
      pendingLine = lines.pop() ?? "";
      for (const frame of lines) {
        sendFrame(frame);
      }
      callback();
    },
    final(callback) {
      pendingLine += stdinDecoder.end();
      if (pendingLine) {
        sendFrame(pendingLine);
      }
      pendingLine = "";
      callback();
    },
  });
  const closeSocket = () => {
    if (socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) {
      return;
    }
    socket.close();
  };
  stdin.once("finish", closeSocket);
  stdin.once("close", closeSocket);

  return {
    stdin,
    stdout,
    stderr,
    get killed() {
      return killed;
    },
    kill: () => {
      killed = true;
      clearConnectionHealthTimers();
      socket.close();
    },
    once: (event, listener) => events.once(event, listener),
  };
}

/** Opens the owner-scoped Codex control socket used by the WebSocket upgrade. */
function connectCodexAppServerUnixSocket(socketPath: string): net.Socket {
  return net.createConnection(socketPath);
}

/** Resolves the canonical or explicitly configured Codex control socket. */
function resolveCodexAppServerUnixSocketPath(
  options: Pick<CodexAppServerStartOptions, "env" | "transport" | "url">,
): string | undefined {
  if (options.transport !== "unix") {
    if (options.url?.startsWith("unix://")) {
      throw new Error("codex app-server unix URL requires unix transport");
    }
    return undefined;
  }
  const url = options.url ?? "unix://";
  if (!url.startsWith("unix://")) {
    throw new Error("codex app-server unix transport requires a unix:// URL");
  }
  const configuredPath = url.slice("unix://".length);
  return (
    configuredPath ||
    path.join(
      resolveCodexAppServerUserHomeDir(options.env ?? process.env),
      "app-server-control",
      "app-server-control.sock",
    )
  );
}

function websocketFrameToText(data: RawData): string {
  if (typeof data === "string") {
    return data;
  }
  if (Buffer.isBuffer(data)) {
    return data.toString("utf8");
  }
  if (Array.isArray(data)) {
    return Buffer.concat(data).toString("utf8");
  }
  return Buffer.from(data).toString("utf8");
}

import { execFileSync, spawn } from "node:child_process";
import { once } from "node:events";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { describe, expect, it, vi } from "vitest";
import { terminateCodexAppServerOrphan } from "./transport-process-containment.js";
import * as processSnapshot from "./transport-process-snapshot.js";
import type { PosixProcess } from "./transport-process-snapshot.js";
import { closeCodexAppServerTransportAndWait } from "./transport.js";

type FixtureEvent = {
  role: "root" | "separate-leader" | "separate-descendant" | "shared-leader" | "shared-descendant";
  pid: number;
  pgid: number;
};

type ProcessRow = {
  pid: number;
  command: string;
};

const delay = (ms: number) =>
  new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });

function listProcesses(): ProcessRow[] {
  return execFileSync("ps", ["-axo", "pid=,command="], {
    encoding: "utf8",
  })
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const match = /^(\d+)\s+(.*)$/.exec(line);
      if (!match) {
        throw new Error(`unexpected ps row: ${line}`);
      }
      return {
        pid: Number(match[1]),
        command: match[2] ?? "",
      };
    });
}

async function waitForFixtureEvents(logPath: string, count: number): Promise<FixtureEvent[]> {
  const deadline = Date.now() + 5_000;
  while (Date.now() < deadline) {
    const events = await readFixtureEvents(logPath);
    if (events.length >= count) {
      return events;
    }
    await delay(20);
  }
  throw new Error(`timed out waiting for ${count} process fixture events`);
}

async function readFixtureEvents(logPath: string): Promise<FixtureEvent[]> {
  const contents = await fs.readFile(logPath, "utf8").catch(() => "");
  return contents
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line) as FixtureEvent);
}

async function removeTaskOwnedFixtureProcesses(tempDir: string): Promise<void> {
  const deadline = Date.now() + 2_000;
  while (Date.now() < deadline) {
    const allRows = listProcesses();
    const ownedRows = allRows.filter((row) => row.command.includes(tempDir));
    if (ownedRows.length === 0) {
      return;
    }
    for (const row of ownedRows) {
      try {
        process.kill(row.pid, "SIGKILL");
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== "ESRCH") {
          throw error;
        }
      }
    }
    await delay(20);
  }
  const survivors = listProcesses().filter((row) => row.command.includes(tempDir));
  if (survivors.length > 0) {
    throw new Error(`task-owned process fixture survived cleanup: ${JSON.stringify(survivors)}`);
  }
}

describe.skipIf(process.platform === "win32")("Codex app-server process containment", () => {
  it.each(["startedAt", "pgid"] as const)(
    "does not signal a registered PID with a changed %s",
    async (field) => {
      const child = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"], {
        detached: true,
        stdio: "ignore",
      });
      await once(child, "spawn");
      try {
        const identity = (await processSnapshot.readCodexAppServerProcessSnapshot())?.find(
          (row) => row.pid === child.pid,
        );
        if (!identity) {
          throw new Error("Missing test process identity");
        }
        const stale =
          field === "startedAt"
            ? { ...identity, startedAt: "Mon Jan 1 00:00:00 2001" }
            : { ...identity, pgid: identity.pgid + 1 };
        // PID reuse retires a stale row; group drift remains ambiguous and blocks startup.
        expect(await terminateCodexAppServerOrphan(stale)).toBe(field === "startedAt");
        expect(child.exitCode).toBeNull();
        expect(child.signalCode).toBeNull();
        expect(process.kill(child.pid!, 0)).toBe(true);
      } finally {
        const exited = once(child, "exit");
        child.kill("SIGKILL");
        await exited;
      }
    },
  );

  it("reaps descendants in independent and root process groups before close returns", async () => {
    const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-codex-transport-process-"));
    const logPath = path.join(tempDir, "processes.jsonl");
    const rootPath = path.join(tempDir, "root.mjs");
    const leaderPath = path.join(tempDir, "leader.mjs");
    const descendantPath = path.join(tempDir, "descendant.mjs");
    await fs.writeFile(logPath, "");
    await fs.writeFile(
      descendantPath,
      `
import { appendFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
const [logPath, role] = process.argv.slice(2);
const pgid = Number(execFileSync("ps", ["-o", "pgid=", "-p", String(process.pid)], { encoding: "utf8" }).trim());
appendFileSync(logPath, JSON.stringify({ role, pid: process.pid, pgid }) + "\\n");
for (const signal of ["SIGTERM", "SIGHUP", "SIGINT"]) process.on(signal, () => {});
setInterval(() => {}, 1_000);
`,
    );
    await fs.writeFile(
      leaderPath,
      `
import { appendFileSync } from "node:fs";
import { execFileSync, spawn } from "node:child_process";
const [logPath, role, descendantPath] = process.argv.slice(2);
const pgid = Number(execFileSync("ps", ["-o", "pgid=", "-p", String(process.pid)], { encoding: "utf8" }).trim());
appendFileSync(logPath, JSON.stringify({ role, pid: process.pid, pgid }) + "\\n");
const descendant = spawn(process.execPath, [descendantPath, logPath, role.replace("leader", "descendant")], { stdio: "ignore" });
descendant.unref();
for (const signal of ["SIGTERM", "SIGHUP", "SIGINT"]) process.on(signal, () => {});
setInterval(() => {}, 1_000);
`,
    );
    await fs.writeFile(
      rootPath,
      `
import { appendFileSync } from "node:fs";
import { execFileSync, spawn } from "node:child_process";
const [logPath, leaderPath, descendantPath] = process.argv.slice(2);
const pgid = Number(execFileSync("ps", ["-o", "pgid=", "-p", String(process.pid)], { encoding: "utf8" }).trim());
appendFileSync(logPath, JSON.stringify({ role: "root", pid: process.pid, pgid }) + "\\n");
for (const [role, detached] of [["separate-leader", true], ["shared-leader", false]]) {
  const child = spawn(process.execPath, [leaderPath, logPath, role, descendantPath], { detached, stdio: "ignore" });
  child.unref();
}
process.stdin.resume();
process.stdin.on("end", () => process.exit(0));
`,
    );

    const root = spawn(process.execPath, [rootPath, logPath, leaderPath, descendantPath], {
      detached: true,
      stdio: ["pipe", "pipe", "pipe"],
    });

    try {
      const events = await waitForFixtureEvents(logPath, 5);
      const eventByRole = new Map(events.map((event) => [event.role, event]));
      const rootEvent = eventByRole.get("root");
      const separateLeader = eventByRole.get("separate-leader");
      const separateDescendant = eventByRole.get("separate-descendant");
      const sharedLeader = eventByRole.get("shared-leader");
      const sharedDescendant = eventByRole.get("shared-descendant");
      expect(rootEvent).toBeDefined();
      expect(separateLeader?.pgid).toBe(separateLeader?.pid);
      expect(separateDescendant?.pgid).toBe(separateLeader?.pgid);
      expect(sharedLeader?.pgid).toBe(rootEvent?.pgid);
      expect(sharedDescendant?.pgid).toBe(rootEvent?.pgid);
      await expect(
        closeCodexAppServerTransportAndWait(root, {
