import { writeFileSync } from "node:fs";
const [sentinelPath, sentinelPidPath] = process.argv.slice(2);
const sentinel = spawn(process.execPath, [sentinelPath], { detached: true, stdio: "ignore" });
sentinel.unref();
writeFileSync(sentinelPidPath, String(sentinel.pid));
process.stdin.resume();
process.stdin.on("end", () => process.exit(0));
`,
    );
    const root = spawn(process.execPath, [rootPath, sentinelPath, sentinelPidPath], {
      detached: true,
      stdio: ["pipe", "pipe", "pipe"],
    });
    let restoreInspection: (() => void) | undefined;
    try {
      let sentinelPid: number | undefined;
      const deadline = Date.now() + 5_000;
      while (Date.now() < deadline) {
        const contents = await fs.readFile(sentinelPidPath, "utf8").catch(() => "");
        if (contents) {
          sentinelPid = Number(contents);
          break;
        }
        await delay(20);
      }
      const initial = await processSnapshot.readCodexAppServerProcessSnapshot();
      const rootIdentity = initial?.find((row) => row.pid === root.pid);
      const sentinelIdentity = initial?.find((row) => row.pid === sentinelPid);
      if (!rootIdentity || !sentinelIdentity) {
        throw new Error("Missing root or sentinel process identity");
      }
      const stoppedRoot = { ...rootIdentity, state: "T" };
      const oldSentinel = {
        ...sentinelIdentity,
        ppid: rootIdentity.pid,
        state: "S",
        startedAt: "Mon Jan 1 00:00:00 2001",
      };
      const stoppedOldSentinel = { ...oldSentinel, state: "T" };
      const stoppedSentinel = { ...sentinelIdentity, state: "T" };
      const runningTree = [rootIdentity, sentinelIdentity];
      const rootStoppedTree = [stoppedRoot, sentinelIdentity];
      const stoppedTree = [stoppedRoot, stoppedSentinel];
      const scenarios: Record<typeof mode, Array<PosixProcess[] | undefined | "deadline">> = {
        reuse: [
          [rootIdentity, oldSentinel],
          [rootIdentity, oldSentinel],
          [stoppedRoot, oldSentinel],
          [stoppedRoot, oldSentinel],
          [stoppedRoot, stoppedOldSentinel],
          stoppedTree,
        ],
        late: [[rootIdentity], [rootIdentity], rootStoppedTree, rootStoppedTree, stoppedTree],
        reparented: [
          runningTree,
          runningTree,
          rootStoppedTree,
          rootStoppedTree,
          [stoppedRoot, { ...stoppedSentinel, ppid: 1, pgid: stoppedSentinel.pgid + 1 }],
        ],
        "root-resumed": [
          runningTree,
          runningTree,
          runningTree,
          runningTree,
          rootStoppedTree,
          rootStoppedTree,
          stoppedTree,
        ],
        traced: [
          runningTree,
          runningTree,
          rootStoppedTree,
          rootStoppedTree,
          [stoppedRoot, { ...stoppedSentinel, state: "t" }],
        ],
        uninterruptible: [
          runningTree,
          runningTree,
          [stoppedRoot, { ...sentinelIdentity, state: "U" }],
          [stoppedRoot, { ...sentinelIdentity, state: "U" }],
        ],
        "snapshot-failure": [runningTree, runningTree, rootStoppedTree, rootStoppedTree, undefined],
        "inspection-timeout": [runningTree, runningTree, "deadline"],
        extended: [
          runningTree,
          runningTree,
          ...Array.from({ length: 16 }, () => rootStoppedTree),
          stoppedTree,
        ],
      };
      const snapshots = scenarios[mode];
      let inspection = 0;
      const readSnapshot = async (inspectionDeadline: number): Promise<PosixProcess[]> => {
        const rows = snapshots[Math.min(inspection++, snapshots.length - 1)];
        if (rows === "deadline") {
          await delay(Math.max(1, inspectionDeadline - Date.now()));
          throw new processSnapshot.ProcessInspectionError("deadline");
        }
        if (!rows) {
          throw new processSnapshot.ProcessInspectionError("unavailable");
        }
        return rows;
      };
      const snapshotSpy = vi
        .spyOn(processSnapshot, "readCodexAppServerProcessSnapshot")
        .mockImplementation((inspectionDeadline = Date.now() + 2_000) =>
          readSnapshot(inspectionDeadline),
        );
      const processSpy = vi
        .spyOn(processSnapshot, "readCodexAppServerProcess")
        .mockImplementation(async (pid, inspectionDeadline) =>
          (await readSnapshot(inspectionDeadline))?.find((row) => row.pid === pid),
        );
      restoreInspection = () => {
        snapshotSpy.mockRestore();
        processSpy.mockRestore();
      };
      const closed = await closeCodexAppServerTransportAndWait(root, {
        forceKillDelayMs: 500,
        exitTimeoutMs: 2_000,
      });
      restoreInspection();
      expect(closed).toBe(true);
      expect(root.exitCode).toBe(0);
      const survived = listProcesses().some(
        (row) => row.pid === sentinelPid && row.command.includes(tempDir),
      );
      expect(survived).toBe(sentinelSurvived);
      if (mode === "snapshot-failure" || mode === "inspection-timeout") {
        const sentinel = await processSnapshot.readCodexAppServerProcess(
          sentinelIdentity.pid,
          Date.now() + 2_000,
        );
        expect(sentinel).toBeDefined();
        expect(sentinel?.state).not.toMatch(/^[Tt]/);
      }
    } finally {
      restoreInspection?.();
      await removeTaskOwnedFixtureProcesses(tempDir);
      await fs.rm(tempDir, { recursive: true, force: true });
    }
  });
});

/**
 * Shared transport lifecycle helpers for stdio and WebSocket Codex app-server
 * connections.
 */
import { finished } from "node:stream/promises";
import { terminateCodexAppServerDescendants } from "./transport-process-containment.js";

type TransportClose = { closing: Promise<boolean>; naturalExit: boolean };
const CODEX_APP_SERVER_TRANSPORT_CLOSES = new WeakMap<object, TransportClose>();

type TransportCloseOptions = { forceKillDelayMs?: number; drainStdio?: boolean };

/** True only after bounded settlement proves an exit that cleanup did not cause. */
export function hasCodexAppServerNaturalExit(child: CodexAppServerTransport): boolean {
  return CODEX_APP_SERVER_TRANSPORT_CLOSES.get(child)?.naturalExit === true;
}

/** Child-process-like transport shape consumed by the Codex app-server client. */
export type CodexAppServerTransport = {
  stdin: {
    write: (data: string | Uint8Array, callback?: (error?: Error | null) => void) => unknown;
    end?: () => unknown;
    destroy?: () => unknown;
    unref?: () => unknown;
    on?: (event: "error", listener: (error: Error) => void) => unknown;
  };
  stdout: NodeJS.ReadableStream & {
    destroy?: () => unknown;
    unref?: () => unknown;
  };
  stderr: NodeJS.ReadableStream & {
    destroy?: () => unknown;
    unref?: () => unknown;
  };
  pid?: number;
  exitCode?: number | null;
  signalCode?: string | null;
  killed?: boolean;
  kill?: (signal?: NodeJS.Signals) => unknown;
  unref?: () => unknown;
  once: (event: string, listener: (...args: unknown[]) => void) => unknown;
  off?: (event: string, listener: (...args: unknown[]) => void) => unknown;
};

/** Starts graceful transport shutdown and schedules a force kill fallback. */
export function closeCodexAppServerTransport(
  child: CodexAppServerTransport,
  options: TransportCloseOptions = {},
): void {
  void beginCodexAppServerTransportClose(child, options).closing;
}

function beginCodexAppServerTransportClose(
  child: CodexAppServerTransport,
  options: TransportCloseOptions,
): TransportClose {
  const current = CODEX_APP_SERVER_TRANSPORT_CLOSES.get(child);
  if (current) {
    return current;
  }
  const closing = (async () => {
    if (hasCodexAppServerTransportExited(child)) {
      return true;
    }
    if (process.platform === "win32" || !child.pid || !child.kill) {
      finishCodexAppServerTransportClose(child, options);
      return false;
    }
    let resumeRoot: (() => void) | undefined;
    try {
      const contained = await terminateCodexAppServerDescendants(child);
      if (contained === "exited") {
        return true;
      }
      resumeRoot = contained;
    } catch {
      resumeRoot = undefined;
    }
    try {
      finishCodexAppServerTransportClose(child, options, resumeRoot);
    } catch {
      signalCodexAppServerTransport(child, "SIGKILL");
    }
    // Descendant termination or stdin EOF can make a launcher exit cleanly.
    // Record cleanup ownership here instead of inferring it from its exit code.
    return false;
  })();
  const closure = { closing, naturalExit: false };
  CODEX_APP_SERVER_TRANSPORT_CLOSES.set(child, closure);
  return closure;
}

function finishCodexAppServerTransportClose(
  child: CodexAppServerTransport,
  options: TransportCloseOptions,
  resumeRoot?: () => void,
): void {
  const forceKillDelayMs = options.forceKillDelayMs ?? 1_000;
  const forceKill = setTimeout(
    () => {
      if (hasCodexAppServerTransportExited(child)) {
        return;
      }
      signalCodexAppServerTransport(child, "SIGKILL");
    },
    Math.max(1, forceKillDelayMs),
  );
  forceKill.unref?.();
  child.once("exit", () => {
    clearTimeout(forceKill);
    if (!options.drainStdio) {
      child.stdout.destroy?.();
      child.stderr.destroy?.();
    }
  });
  try {
    child.stdin.end?.();
    child.stdin.destroy?.();
  } finally {
    resumeRoot?.();
  }
  child.unref?.();
  child.stdout.unref?.();
  child.stderr.unref?.();
  child.stdin.unref?.();
}

/** Closes a transport and waits briefly for an exit event. */
export async function closeCodexAppServerTransportAndWait(
  child: CodexAppServerTransport,
  options: TransportCloseOptions & { exitTimeoutMs?: number } = {},
): Promise<boolean> {
  const drained = options.drainStdio
    ? Promise.all(
        [child.stdout, child.stderr].map((stream) => finished(stream, { cleanup: true })),
      ).then(
        () => true,
        () => false,
      )
    : undefined;
  const closure = beginCodexAppServerTransportClose(child, options);
  const naturalExit = await closure.closing;
  const settled = await waitForCodexAppServerTransportExit(
    child,
    options.exitTimeoutMs ?? 2_000,
    drained,
  );
  closure.naturalExit = naturalExit && settled;
  if (options.drainStdio) {
    // Share the existing exit budget with pipe draining. A timed-out drain is
    // not a complete natural-exit diagnostic and must not authorize a retry.
    child.stdout.destroy?.();
    child.stderr.destroy?.();
  }
  return settled;
}

function hasCodexAppServerTransportExited(child: CodexAppServerTransport): boolean {
  return child.exitCode !== null && child.exitCode !== undefined
    ? true
    : child.signalCode !== null && child.signalCode !== undefined;
}

async function waitForCodexAppServerTransportExit(
  child: CodexAppServerTransport,
  timeoutMs: number,
  drained?: Promise<boolean>,
): Promise<boolean> {
  return await new Promise<boolean>((resolve) => {
    let settled = false;
    const finish = (exited: boolean) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timeout);
      child.off?.("exit", onExit);
      resolve(exited);
    };
    const onExit = () => {
      if (drained) {
        void drained.then(finish);
      } else {
        finish(true);
      }
    };
    const timeout = setTimeout(() => finish(false), Math.max(1, timeoutMs));
    child.once("exit", onExit);
    if (hasCodexAppServerTransportExited(child)) {
      onExit();
    }
  });
}

function signalCodexAppServerTransport(
  child: CodexAppServerTransport,
  signal: NodeJS.Signals,
): void {
  if (child.pid && process.platform !== "win32") {
    try {
      process.kill(-child.pid, signal);
      return;
    } catch {
      // Fall back to the child handle. The process may already be gone or not
      // be a process-group leader on older call sites.
    }
  }
  child.kill?.(signal);
}

import type { EmbeddedRunAttemptParamsV2 as EmbeddedRunAttemptParams } from "openclaw/plugin-sdk/agent-harness-runtime";
import {
  asOptionalRecord,
  normalizeOptionalString,
} from "openclaw/plugin-sdk/string-coerce-runtime";
import { truncateUtf16Safe } from "openclaw/plugin-sdk/text-utility-runtime";
import { codexSandboxPolicyForTurn, type CodexAppServerRuntimeOptions } from "./config.js";
import type {
  CodexSandboxPolicy,
  CodexTurnEnvironmentParams,
  CodexTurnStartParams,
  CodexUserInput,
} from "./protocol.js";
import { readCodexSupportedReasoningEfforts } from "./reasoning-effort.js";
import {
  CODEX_NATIVE_PERSONALITY_NONE,
  resolveCodexAppServerRequestModelSelection,
  resolveReasoningEffort,
} from "./thread-model-selection.js";
import { buildCodexUserInput } from "./user-input.js";

const CODEX_CURRENT_SENDER_FIELD_MAX_CHARS = 256;

function buildCodexCurrentSenderContextValue(params: EmbeddedRunAttemptParams): string | undefined {
  const metadata = asOptionalRecord(
    asOptionalRecord(params.userTurnTranscriptRecorder?.message as unknown)?.["__openclaw"],
  );
  const recorded = [
    normalizeOptionalString(metadata?.["senderId"]),
    normalizeOptionalString(metadata?.["senderName"]),
    normalizeOptionalString(metadata?.["senderUsername"]),
  ] as const;
  const [id, name, username] = recorded.some(Boolean)
    ? recorded
    : [
        normalizeOptionalString(params.senderId),
        normalizeOptionalString(params.senderName),
        normalizeOptionalString(params.senderUsername),
      ];
  if (!id && !name && !username) {
    return undefined;
  }
  const bound = (value: string) => truncateUtf16Safe(value, CODEX_CURRENT_SENDER_FIELD_MAX_CHARS);
  return JSON.stringify({
    sender: {
      ...(id ? { id: bound(id) } : {}),
      ...(name ? { name: bound(name) } : {}),
      ...(username ? { username: bound(username) } : {}),
    },
  });
}

export function buildTurnStartParams(
  params: EmbeddedRunAttemptParams,
  options: {
    threadId: string;
    cwd: string;
    appServer: CodexAppServerRuntimeOptions;
    promptText?: string;
    explicitSkillInputs?: Array<Extract<CodexUserInput, { type: "skill" }>>;
    sandboxPolicy?: CodexSandboxPolicy;
    environmentSelection?: CodexTurnEnvironmentParams[];
    model?: string | null;
    modelProvider?: string | null;
    turnScopedDeveloperInstructions?: string;
    skillsCollaborationInstructions?: string;
    memoryCollaborationInstructions?: string;
    preserveNativeTurnSettings?: boolean;
    clearInheritedServiceTier?: boolean;
  },
): CodexTurnStartParams {
  const modelSelection = options.preserveNativeTurnSettings
    ? undefined
    : resolveCodexAppServerRequestModelSelection({
        model: options.model ?? params.modelId,
        modelProvider: options.modelProvider,
        authProfileId: params.authProfileId,
        authProfileStore: params.authProfileStore,
        agentDir: params.agentDir,
        config: params.config,
      });
  const useThreadPermissionProfile = options.appServer.networkProxy && !options.sandboxPolicy;
  const currentSenderContext =
    params.trigger === "user" ? buildCodexCurrentSenderContextValue(params) : undefined;
  // Untrusted context exposes authenticated attribution without promoting human-controlled labels.
  let additionalContext: CodexTurnStartParams["additionalContext"] = currentSenderContext
    ? { openclaw_current_sender: { kind: "untrusted", value: currentSenderContext } }
    : undefined;
  if (params.permissionChange?.notice) {
    // Application context is a developer message in Codex 0.151.0 and also
    // reaches native-preserved threads without overriding their turn settings.
    additionalContext = {
      ...additionalContext,
      openclaw_permission_change: { kind: "application", value: params.permissionChange.notice },
    };
  }
  return {
    threadId: options.threadId,
    // codex-rs/app-server-protocol/src/protocol/v2/turn.rs:292-324 at 91d6f48992ad defines
    // UserInput::Skill; skills/src/selection.rs:60-92 blocks those names from duplicate text
    // selection while leaving unmatched Codex-native-only names scannable.
    input: [
      ...buildCodexUserInput(options.promptText ?? params.prompt, params.images),
      ...(options.explicitSkillInputs ?? []),
    ],
    ...(additionalContext ? { additionalContext } : {}),
    cwd: options.cwd,
    ...(options.appServer.sessionRoot
      ? { runtimeWorkspaceRoots: [options.appServer.sessionRoot] }
      : {}),
    approvalPolicy: options.appServer.approvalPolicy,
    approvalsReviewer: options.appServer.approvalsReviewer,
    ...(useThreadPermissionProfile
      ? {}
      : {
          sandboxPolicy:
            options.sandboxPolicy ??
            codexSandboxPolicyForTurn(
              options.appServer.sandbox,
              options.appServer.sessionRoot ?? options.cwd,
              options.appServer.start?.args,
            ),
        }),
    ...(modelSelection
      ? { model: modelSelection.model, personality: CODEX_NATIVE_PERSONALITY_NONE }
      : {}),
    // Codex distinguishes an omitted native default from explicitly clearing
    // an OpenClaw-owned priority override left on this exact warm session.
    ...(options.appServer.serviceTier !== undefined
      ? { serviceTier: options.appServer.serviceTier }
      : options.clearInheritedServiceTier
        ? { serviceTier: null }
        : {}),
    ...(modelSelection
      ? {
          effort: resolveReasoningEffort(
            params.thinkLevel,
            modelSelection.model,
            readCodexSupportedReasoningEfforts(params.model?.compat),
          ),
        }
      : {}),
    ...(options.environmentSelection ? { environments: options.environmentSelection } : {}),
    ...(modelSelection
      ? {
          collaborationMode: buildTurnCollaborationMode(params, {
            model: modelSelection.model,
            turnScopedDeveloperInstructions: options.turnScopedDeveloperInstructions,
            skillsCollaborationInstructions: options.skillsCollaborationInstructions,
            memoryCollaborationInstructions: options.memoryCollaborationInstructions,
          }),
        }
      : {}),
  };
}

type CodexTurnCollaborationMode = NonNullable<CodexTurnStartParams["collaborationMode"]>;

export function buildTurnCollaborationMode(
  params: EmbeddedRunAttemptParams,
  options: {
    model?: string;
    turnScopedDeveloperInstructions?: string;
    skillsCollaborationInstructions?: string;
    memoryCollaborationInstructions?: string;
  } = {},
): CodexTurnCollaborationMode {
  const model = options.model ?? params.modelId;
  return {
    mode: "default",
    settings: {
      model,
      reasoning_effort: resolveReasoningEffort(
        params.thinkLevel,
        model,
        readCodexSupportedReasoningEfforts(params.model?.compat),
      ),
      developer_instructions: buildTurnScopedCollaborationInstructions(params, options),
    },
  };
}

function buildTurnScopedCollaborationInstructions(
  params: EmbeddedRunAttemptParams,
  options: {
    turnScopedDeveloperInstructions?: string;
    skillsCollaborationInstructions?: string;
    memoryCollaborationInstructions?: string;
  } = {},
): string | null {
  const contextInstructions = joinPresentSections(
    options.turnScopedDeveloperInstructions,
    options.memoryCollaborationInstructions,
    options.skillsCollaborationInstructions,
  );
  if (params.trigger === "cron") {
    return joinPresentSections(buildCronCollaborationInstructions(), contextInstructions);
  }
  if (contextInstructions?.trim()) {
    return joinPresentSections(buildDefaultCollaborationInstructions(), contextInstructions);
  }
  return null;
}

function buildDefaultCollaborationInstructions(): string {
  // Codex only applies the built-in Default-mode preset when `developer_instructions`
  // is null. OpenClaw adds per-turn workspace instructions here, so preserve that
  // pinned Codex default behavior before appending the workspace overlay.
  return [
    "# Collaboration Mode: Default",
    "",
    "You are now in Default mode. Any previous instructions for other modes (e.g. Plan mode) are no longer active.",
    "",
    "Your active mode changes only when new developer instructions with a different `<collaboration_mode>...</collaboration_mode>` change it; user requests or tool descriptions do not change mode by themselves. Known mode names are Default and Plan.",
    "",
    "## request_user_input availability",
    "",
    "Use the `request_user_input` tool only when it is listed in the available tools for this turn.",
    "",
    "In Default mode, strongly prefer making reasonable assumptions and executing the user's request rather than stopping to ask questions. If you absolutely must ask a question because the answer cannot be discovered from local context and a reasonable assumption would be risky, ask the user directly with a concise plain-text question. Never write a multiple choice question as a textual assistant message.",
  ].join("\n");
}

function buildCronCollaborationInstructions(): string {
  return [
    "This is an OpenClaw cron automation turn. Apply these instructions only to this scheduled job; ordinary chat turns should stay in Codex Default mode.",
    "Execute the cron payload directly. If it asks you to run an exact command, run that command before doing any investigation, planning, memory review, or workspace bootstrap.",
    "Use context already provided by the runtime, but do not spend time loading or re-reading workspace bootstrap, memory, or project-doc files before executing the cron payload. Inspect those files only if the payload asks for them or the command fails and they are needed to diagnose it.",
    "Keep output concise and automation-oriented. Prefer the final command result or a short failure summary over status narration.",
  ].join("\n\n");
}

function joinPresentSections(...sections: Array<string | undefined>): string {
  return sections.filter((section): section is string => Boolean(section?.trim())).join("\n\n");
}

import { expect, vi } from "vitest";
import type { createClientHarness } from "./test-support.js";

export type WireResponse = {
  id: number | string;
  result?: unknown;
  error?: unknown;
};

export async function waitForResponse(
  harness: ReturnType<typeof createClientHarness>,
  id: number | string,
): Promise<WireResponse> {
  let response: WireResponse | undefined;
  await vi.waitFor(() => {
    response = harness.writes
      .map((write) => JSON.parse(write) as WireResponse)
      .find((candidate) => candidate.id === id);
    expect(response).toBeDefined();
  });
  if (!response) {
    throw new Error(`missing app-server response for ${id}`);
  }
  return response;
}

export async function settleInput(): Promise<void> {
  await new Promise<void>((resolve) => {
    setImmediate(resolve);
  });
}

