      }),
    );
    expect(() =>
      router.reserveThread({ threadId: "thread-late", onRequest: requestHandler }),
    ).toThrow("turn router is closed");
  });

  it("releases dormant waiters and aborts the reservation", async () => {
    const harness = createHarness();
    const router = getCodexAppServerTurnRouter(harness.client);
    const route = router.reserveThread({ threadId: "thread-dormant-release" });
    harness.send({
      id: "request-dormant-release",
      method: "item/tool/call",
      params: { threadId: "thread-dormant-release", turnId: "turn-1" },
    });
    await settleInput();

    route.release();

    expect(route.signal.aborted).toBe(true);
    expect(route.signal.reason).toEqual(new Error("codex app-server thread route is released"));
    await expect(route.activate({ onRequest: vi.fn() })).rejects.toThrow(
      "thread route is released",
    );
    await expect(route.bindTurn("turn-1")).rejects.toThrow("thread route is released");
    expect(await waitForResponse(harness, "request-dormant-release")).toEqual({
      id: "request-dormant-release",
      result: {
        contentItems: [
          {
            type: "inputText",
            text: "OpenClaw did not register a handler for this app-server tool call.",
          },
        ],
        success: false,
      },
    });
  });

  it("fails and removes a route when its pre-bind buffer is full", async () => {
    vi.spyOn(embeddedAgentLog, "warn").mockImplementation(() => undefined);
    const harness = createHarness();
    const router = getCodexAppServerTurnRouter(harness.client);
    const route = router.reserveThread({
      threadId: "thread-overflow",
      onNotification: vi.fn(),
    });
    route.armTurn();
    for (let index = 0; index <= 256; index += 1) {
      harness.send({
        method: "item/started",
        params: { threadId: "thread-overflow", turnId: "turn-overflow" },
      });
    }
    await settleInput();

    await expect(route.bindTurn("turn-overflow")).rejects.toThrow(
      "pre-bind notification buffer exceeded 256 entries",
    );
    expect(() =>
      router.reserveThread({
        threadId: "thread-overflow",
        onNotification: vi.fn(),
      }),
    ).not.toThrow();
  });
});

/** Keyed routing for all turn traffic on one shared Codex app-server client. */
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import { createDeferred } from "openclaw/plugin-sdk/extension-shared";
import type { CodexAppServerClient } from "./client.js";
import { redactCodexEventKind } from "./event-projector-diagnostics.js";
import {
  readCodexNotificationThreadId,
  readCodexNotificationTurnId,
} from "./notification-correlation.js";
import {
  isJsonObject,
  type CodexServerNotification,
  type JsonValue,
  type RpcRequest,
} from "./protocol.js";

const DEFAULT_PREBIND_NOTIFICATION_LIMIT = 256;
const DEFAULT_GLOBAL_WARNING_LIMIT = 32;
export const CODEX_APP_SERVER_NATIVE_TURN_WAIT_TIMEOUT_MS = 30_000;

export type CodexAppServerServerRequest = Required<Pick<RpcRequest, "id" | "method">> & {
  params?: JsonValue;
};
export type CodexThreadRouteScope = {
  threadId: string;
  turnId?: string;
};
type CodexThreadRequestHandler = (
  request: CodexAppServerServerRequest,
  scope: CodexThreadRouteScope,
  signal: AbortSignal,
) => Promise<JsonValue | undefined> | JsonValue | undefined;
type CodexThreadNotificationHandler = (
  notification: CodexServerNotification,
  scope: CodexThreadRouteScope,
) => Promise<void> | void;
type CodexThreadNotificationReceivedHandler = (
  notification: CodexServerNotification,
  scope: CodexThreadRouteScope,
  receivedAtMs: number,
) => void;
type CodexThreadRouteHandlers = {
  onNotificationReceived?: CodexThreadNotificationReceivedHandler;
  onNotification?: CodexThreadNotificationHandler;
  onRequest?: CodexThreadRequestHandler;
};

export type CodexThreadRouteReservation = {
  readonly threadId: string;
  readonly signal: AbortSignal;
  readonly observedNativeTurnId?: string;
  activate: (handlers: CodexThreadRouteHandlers) => Promise<void>;
  armTurn: () => void;
  bindTurn: (turnId: string) => Promise<void>;
  cancelTurn: () => Promise<void>;
  drain: () => Promise<void>;
  release: () => void;
};

type RouteOptions = Partial<CodexThreadRouteHandlers> & {
  threadId: string;
  releaseOn?: AbortSignal;
};

export type CodexAppServerTurnRouter = {
  reserveThread: (options: RouteOptions) => CodexThreadRouteReservation;
  watchNativeTurnCompletion: (options: {
    threadId: string;
    turnId: string;
    timeoutMs: number;
    signal?: AbortSignal;
  }) => CodexNativeTurnCompletionWatch;
};

type CodexNativeTurnCompletionWatch = {
  completion: Promise<boolean>;
  cancel: () => void;
};

type Deferred = ReturnType<typeof createDeferred<void>>;
type PendingNotification = {
  notification: CodexServerNotification;
  receivedAtMs: number;
  scope: CodexThreadRouteScope;
};
type Route = {
  threadId: string;
  controller: AbortController;
  handlers?: CodexThreadRouteHandlers;
  released?: Error;
  ended: Deferred;
  activated: Deferred;
  gate: "open" | "armed" | "bound";
  binding?: Deferred;
  turnId?: string;
  pending: PendingNotification[];
  notificationTail: Promise<void>;
  observedNativeTurn?: { id: string; completed: boolean };
  completedNativeTurnIds: Set<string>;
  ignoredTurnNotificationKeys: Set<string>;
  detachReleaseOn?: () => void;
};
type NativeTurnCompletionWatcher = {
  turnId: string;
  finish: (completed: boolean) => void;
};

const routers = new WeakMap<CodexAppServerClient, ClientTurnRouter>();

/** Returns the sole router installed on a physical app-server client. */
export function getCodexAppServerTurnRouter(
  client: CodexAppServerClient,
): CodexAppServerTurnRouter {
  const existing = routers.get(client);
  if (existing) {
    return existing;
  }
  const router = new ClientTurnRouter(client);
  routers.set(client, router);
  return router;
}

class ClientTurnRouter implements CodexAppServerTurnRouter {
  private readonly routes = new Map<string, Route>();
  private readonly globalWarnings: CodexServerNotification[] = [];
  private readonly nativeTurnCompletionWatchers = new Map<
    string,
    Set<NativeTurnCompletionWatcher>
  >();
  private disposed = false;

  constructor(client: CodexAppServerClient) {
    client.addNotificationHandler((notification) => this.routeNotification(notification));
    client.addRequestHandler((request, signal) => this.routeRequest(request, signal));
    client.addCloseHandler((closedClient) => {
      this.dispose(closedClient.getCloseError());
    });
  }

  reserveThread(options: RouteOptions): CodexThreadRouteReservation {
    this.assertActive();
    const threadId = requireId(options.threadId, "thread id");
    if (this.routes.has(threadId)) {
      throw new Error(`codex app-server thread route already reserved: ${threadId}`);
    }
    const route: Route = {
      threadId,
      controller: new AbortController(),
      ended: createDeferred<void>(),
      activated: createDeferred<void>(),
      gate: "open",
      pending: this.globalWarnings.map((notification) => ({
        notification,
        receivedAtMs: Date.now(),
        scope: { threadId },
      })),
      notificationTail: Promise.resolve(),
      completedNativeTurnIds: new Set(),
      ignoredTurnNotificationKeys: new Set(),
    };
    this.routes.set(threadId, route);
    if (options.onNotification || options.onRequest) {
      this.activateNow(route, options);
    }
    const releaseOn = options.releaseOn;
    if (releaseOn) {
      const release = () => this.release(route, abortReason(releaseOn));
      releaseOn.addEventListener("abort", release, { once: true });
      route.detachReleaseOn = () => releaseOn.removeEventListener("abort", release);
      if (releaseOn.aborted) {
        release();
      }
    }
    return {
      threadId,
      signal: route.controller.signal,
      get observedNativeTurnId() {
        return route.observedNativeTurn?.id;
      },
      activate: (handlers) => this.activate(route, handlers),
      armTurn: () => this.armTurn(route),
      bindTurn: (turnId) => this.bindTurn(route, turnId),
      cancelTurn: () => this.cancelTurn(route),
      drain: () => this.drainNotifications(route),
      release: () => this.release(route),
    };
  }

  watchNativeTurnCompletion(options: {
    threadId: string;
    turnId: string;
    timeoutMs: number;
    signal?: AbortSignal;
  }): CodexNativeTurnCompletionWatch {
    this.assertActive();
    const threadId = requireId(options.threadId, "thread id");
    const turnId = requireId(options.turnId, "turn id");
    if (options.signal?.aborted) {
      return { completion: Promise.resolve(false), cancel: () => {} };
    }
    // Resume discovers the active turn only after its route starts buffering;
    // preserve an exact completion that arrived before the watcher could exist.
    if (this.routes.get(threadId)?.completedNativeTurnIds.delete(turnId)) {
      return { completion: Promise.resolve(true), cancel: () => {} };
    }
    const { promise: completion, resolve: settle } = createDeferred<boolean>();
    const watchers =
      this.nativeTurnCompletionWatchers.get(threadId) ?? new Set<NativeTurnCompletionWatcher>();
    this.nativeTurnCompletionWatchers.set(threadId, watchers);
    let settled = false;
    const finish = (completed: boolean) => {
      if (settled) {
        return;
      }
      settled = true;
      watchers.delete(watcher);
      if (watchers.size === 0) {
        this.nativeTurnCompletionWatchers.delete(threadId);
      }
      clearTimeout(timeout);
      options.signal?.removeEventListener("abort", abort);
      settle(completed);
    };
    const watcher = { turnId, finish };
    watchers.add(watcher);
    const timeout = setTimeout(() => finish(false), Math.max(1, options.timeoutMs));
    timeout.unref?.();
    const abort = () => finish(false);
    options.signal?.addEventListener("abort", abort, { once: true });
    return { completion, cancel: () => finish(false) };
  }

  private dispose(cause?: Error): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    const closeError = cause
      ? new Error("codex app-server turn router closed", { cause })
      : new Error("codex app-server turn router closed");
    for (const route of this.routes.values()) {
      this.release(route, closeError);
    }
    for (const watchers of this.nativeTurnCompletionWatchers.values()) {
      for (const watcher of watchers) {
        watcher.finish(false);
      }
    }
  }

  private async activate(route: Route, handlers: CodexThreadRouteHandlers): Promise<void> {
    this.assertRoute(route);
    this.activateNow(route, handlers);
    await this.waitForNotifications(route);
    this.assertRoute(route);
  }

  private activateNow(route: Route, handlers: CodexThreadRouteHandlers): void {
    if (route.handlers) {
      throw new Error(`codex app-server thread route already activated: ${route.threadId}`);
    }
    this.assertRoute(route);
    if (!handlers.onNotification && !handlers.onRequest) {
      throw new Error("codex app-server thread route requires a notification or request handler");
    }
    route.handlers = handlers;
    if (!handlers.onNotification) {
      route.pending.length = 0;
    } else if (route.gate !== "armed") {
      this.flushNotifications(route);
    }
    route.activated.resolve();
  }

  private armTurn(route: Route): void {
    this.assertRoute(route);
    if (route.gate !== "open") {
      throw new Error(`codex app-server thread route cannot arm from ${route.gate}`);
    }
    route.gate = "armed";
    route.ignoredTurnNotificationKeys.clear();
    route.completedNativeTurnIds.clear();
    // A native turn started before our rejected turn/start remains authoritative;
    // completed turns from an earlier attempt must not unlock the next retry.
    if (route.observedNativeTurn?.completed) {
      route.observedNativeTurn = undefined;
    }
    route.binding = createDeferred<void>();
  }

  private async cancelTurn(route: Route): Promise<void> {
    if (route.released || route.gate !== "armed") {
      return;
    }
    route.gate = "open";
    route.binding?.resolve();
    route.binding = undefined;
    this.flushNotifications(route);
    await this.waitForNotifications(route);
    this.assertRoute(route);
  }

  private async bindTurn(route: Route, turnIdInput: string): Promise<void> {
    this.assertRoute(route);
    if (!route.handlers) {
      throw new Error("codex app-server thread route must be activated before binding a turn");
    }
    if (route.gate !== "armed") {
      throw new Error(`codex app-server thread route cannot bind from ${route.gate}`);
    }
    const turnId = requireId(turnIdInput, "turn id");
    route.gate = "bound";
    route.turnId = turnId;
    this.flushNotifications(route);
    route.binding?.resolve();
    await this.waitForNotifications(route);
    this.assertRoute(route);
  }

  // Returns the route's serialized tail so awaiting the client's notification
  // fan-out observes queued processing, not just enqueueing.
  private routeNotification(notification: CodexServerNotification): Promise<void> | undefined {
    if (this.disposed) {
      return undefined;
    }
    const scope = readScope(notification.params);
    if (
      !scope.threadId &&
      (notification.method === "configWarning" || notification.method === "warning")
    ) {
      if (this.globalWarnings.length === DEFAULT_GLOBAL_WARNING_LIMIT) {
        this.globalWarnings.shift();
      }
      this.globalWarnings.push(notification);
      for (const route of this.routes.values()) {
        this.bufferNotification(route, notification, { threadId: route.threadId }, Date.now());
        if (route.gate === "bound") {
          this.flushNotifications(route);
        }
      }
      return Promise.all([...this.routes.values()].map((route) => route.notificationTail)).then(
        () => undefined,
      );
    }
    const watchers = scope.threadId
      ? this.nativeTurnCompletionWatchers.get(scope.threadId)
      : undefined;
    const route = scope.threadId ? this.routes.get(scope.threadId) : undefined;
    if (!watchers && !route) {
      return undefined;
    }
    if (scope.turnId && watchers) {
      for (const watcher of watchers) {
        if (watcher.turnId === scope.turnId && notification.method === "turn/completed") {
          watcher.finish(true);
        }
      }
    }
    if (!route) {
      return undefined;
    }
    const routeScope: CodexThreadRouteScope = {
      threadId: route.threadId,
      ...(scope.turnId ? { turnId: scope.turnId } : {}),
    };
    const receivedAtMs = Date.now();
    if (route.gate !== "bound" && scope.turnId) {
      if (notification.method === "turn/started") {
        route.observedNativeTurn = { id: scope.turnId, completed: false };
      } else if (notification.method === "turn/completed") {
        route.completedNativeTurnIds.add(scope.turnId);
        if (
          !route.observedNativeTurn ||
          route.observedNativeTurn.completed ||
          route.observedNativeTurn.id === scope.turnId
        ) {
          route.observedNativeTurn = { id: scope.turnId, completed: true };
        }
      }
    }
    if (!route.handlers) {
      this.bufferNotification(route, notification, routeScope, receivedAtMs);
      return undefined;
    }
    const handler = route.handlers.onNotification;
    if (!handler) {
      return undefined;
    }
    if (route.gate === "bound" && scope.turnId && scope.turnId !== route.turnId) {
      this.warnDroppedStaleTurnNotification(route, notification, routeScope);
      return undefined;
    }
    if (route.gate === "armed") {
      this.bufferNotification(route, notification, routeScope, receivedAtMs);
      return undefined;
    }
    route.handlers.onNotificationReceived?.(notification, routeScope, receivedAtMs);
    this.enqueueNotification(route, handler, notification, routeScope);
    return route.notificationTail;
  }

  private async routeRequest(
    request: CodexAppServerServerRequest,
    signal: AbortSignal = new AbortController().signal,
  ): Promise<JsonValue | undefined> {
    if (this.disposed || signal.aborted) {
      return undefined;
    }
    const scope = readScope(request.params);
    if (!scope.threadId) {
      return undefined;
    }
    const route = this.routes.get(scope.threadId);
    if (!route) {
      return undefined;
    }
    // A retired route owns its in-flight tools and approvals; upstream can
    // cancel their callbacks before sending the terminal turn notification.
    const requestSignal = AbortSignal.any([signal, route.controller.signal]);
    if (!route.handlers && !(await waitForPromiseOrAbort(route.activated.promise, requestSignal))) {
      return undefined;
    }
    if (requestSignal.aborted || !route.handlers) {
      return undefined;
    }
    const handler = route.handlers.onRequest;
    if (!handler) {
      return undefined;
    }
    // Open routes service a resumed native turn. Arming starts the handoff to a
    // new OpenClaw turn, whose requests must wait for its accepted turn id.
    while (route.gate === "armed") {
      const binding = route.binding?.promise;
      if (!binding || !(await waitForPromiseOrAbort(binding, requestSignal))) {
        return undefined;
      }
      if (requestSignal.aborted) {
        return undefined;
      }
    }
    if (route.gate === "bound" && scope.turnId && scope.turnId !== route.turnId) {
      return undefined;
    }
    if (!(await waitForPromiseOrAbort(this.waitForNotifications(route), requestSignal))) {
      return undefined;
    }
    if (requestSignal.aborted) {
      return undefined;
    }
    try {
      const result = await handler(
        request,
        {
          threadId: scope.threadId,
          ...(scope.turnId ? { turnId: scope.turnId } : {}),
        },
        requestSignal,
      );
      return requestSignal.aborted ? undefined : result;
    } catch (error) {
      if (requestSignal.aborted) {
        return undefined;
      }
      throw error;
    }
  }

  private flushNotifications(route: Route): void {
    const handler = route.handlers?.onNotification;
    if (!handler) {
      return;
    }
    for (const pending of route.pending.splice(0)) {
      if (
        route.gate !== "bound" &&
        (pending.notification.method === "configWarning" ||
          (pending.notification.method === "warning" &&
            !readScope(pending.notification.params).threadId))
      ) {
        // The attempt projector does not exist until turn binding; releasing a
        // process-wide warning during route activation would silently lose it.
        route.pending.push(pending);
        continue;
      }
      if (route.gate === "bound" && pending.scope.turnId && pending.scope.turnId !== route.turnId) {
        this.warnDroppedStaleTurnNotification(route, pending.notification, pending.scope);
        continue;
      }
      route.handlers?.onNotificationReceived?.(
        pending.notification,
        pending.scope,
        pending.receivedAtMs,
      );
      this.enqueueNotification(route, handler, pending.notification, pending.scope);
    }
  }

  private warnDroppedStaleTurnNotification(
    route: Route,
    notification: CodexServerNotification,
    scope: CodexThreadRouteScope,
  ): void {
    if (notification.method === "turn/completed" || !scope.turnId || !route.turnId) {
      return;
    }
    const eventKind = redactCodexEventKind(notification.method);
    const key = JSON.stringify([notification.method, scope.turnId]);
    if (route.ignoredTurnNotificationKeys.has(key)) {
      return;
    }
    route.ignoredTurnNotificationKeys.add(key);
    embeddedAgentLog.warn("codex app-server notification ignored for inactive turn", {
      eventKind,
      activeThreadId: route.threadId,
      activeTurnId: route.turnId,
      threadId: scope.threadId,
      turnId: scope.turnId,
      matchesActiveThread: true,
      matchesActiveTurn: false,
    });
  }

  private bufferNotification(
    route: Route,
    notification: CodexServerNotification,
    scope: CodexThreadRouteScope,
    receivedAtMs: number,
  ): void {
    if (route.pending.length < DEFAULT_PREBIND_NOTIFICATION_LIMIT) {
      route.pending.push({ notification, receivedAtMs, scope });
      return;
    }
    const error = new Error(
      `codex app-server pre-bind notification buffer exceeded ${DEFAULT_PREBIND_NOTIFICATION_LIMIT} entries for thread ${route.threadId}`,
    );
    embeddedAgentLog.warn(error.message);
    this.release(route, error);
  }

  private enqueueNotification(
    route: Route,
    handler: CodexThreadNotificationHandler,
    notification: CodexServerNotification,
    scope: CodexThreadRouteScope,
  ): void {
    if (route.released) {
      return;
    }
    route.notificationTail = route.notificationTail
      .then(() => handler(notification, scope))
      .catch((error: unknown) => {
        if (!route.released) {
          embeddedAgentLog.warn("codex app-server keyed notification handler failed", {
            method: notification.method,
            threadId: route.threadId,
            turnId: route.turnId,
            error,
          });
        }
      });
  }

  private async waitForNotifications(route: Route): Promise<void> {
    await Promise.race([route.notificationTail, route.ended.promise]);
  }

  private async drainNotifications(route: Route): Promise<void> {
    // A released route cannot promise that accepted handlers finish processing.
    await Promise.race([route.notificationTail, route.ended.promise]);
  }

  private release(route: Route, error = new Error("codex app-server thread route is released")) {
    if (route.released) {
      return;
    }
    route.released = error;
    route.pending.length = 0;
    route.ended.resolve();
    route.activated.resolve();
    route.binding?.resolve();
    route.detachReleaseOn?.();
    route.controller.abort(error);
    if (this.routes.get(route.threadId) === route) {
      this.routes.delete(route.threadId);
    }
  }

  private assertActive(): void {
    if (this.disposed) {
      throw new Error("codex app-server turn router is closed");
    }
  }

  private assertRoute(route: Route): void {
    if (route.released) {
      throw route.released;
    }
  }
}

async function waitForPromiseOrAbort(
  promise: Promise<unknown>,
  signal: AbortSignal,
): Promise<boolean> {
  if (signal.aborted) {
    return false;
  }
  let removeAbort: (() => void) | undefined;
  try {
    return await Promise.race([
      promise.then(() => true),
      new Promise<boolean>((resolve) => {
        const onAbort = () => resolve(false);
        signal.addEventListener("abort", onAbort, { once: true });
        removeAbort = () => signal.removeEventListener("abort", onAbort);
        if (signal.aborted) {
          onAbort();
        }
      }),
    ]);
  } finally {
    removeAbort?.();
  }
}

function abortReason(signal: AbortSignal): Error {
  return signal.reason instanceof Error
    ? signal.reason
    : new Error(String(signal.reason ?? "codex app-server thread route aborted"));
}

function readScope(value: JsonValue | undefined) {
  if (!isJsonObject(value)) {
    return {};
  }
  const threadId = readCodexNotificationThreadId(value);
  const turnId = readCodexNotificationTurnId(value);
  return { ...(threadId ? { threadId } : {}), ...(turnId ? { turnId } : {}) };
}

function requireId(value: string, label: string): string {
  const normalized = value.trim();
  if (!normalized) {
    throw new Error(`codex app-server ${label} must not be empty`);
  }
  return normalized;
}

import type { SessionTranscriptMessageEntry } from "openclaw/plugin-sdk/session-transcript-runtime";
import { describe, expect, it, vi } from "vitest";
import type { CodexThreadItem, CodexTurn } from "./protocol.js";
import {
  attachCodexMirrorAttestation,
  fingerprintCodexMirrorSourceMessage,
} from "./transcript-mirror-attestation.js";
import { resolveCodexUpstreamForkBoundary } from "./upstream-fork-boundary.js";
import { attachCodexMirrorIdentity, attachUpstreamUserText } from "./upstream-prompt-provenance.js";

const transcriptMocks = vi.hoisted(() => ({
  readVisibleEntries: vi.fn(),
}));

vi.mock("openclaw/plugin-sdk/session-transcript-runtime", () => ({
  readVisibleSessionTranscriptMessageEntries: transcriptMocks.readVisibleEntries,
}));

function item(type: string, overrides: Record<string, unknown> = {}): CodexThreadItem {
  return { id: `${type}-item`, type, ...overrides } as CodexThreadItem;
}

function user(text: string): CodexThreadItem {
  return item("userMessage", {
    id: `${text}-user`,
    content: [{ type: "text", text, text_elements: [] }],
  });
}

function turn(id: string, items: CodexThreadItem[], overrides: Partial<CodexTurn> = {}): CodexTurn {
  return { id, status: "completed", items, ...overrides };
}

function attestedHarnessPrompt(upstreamText: string) {
  const prompt = attachUpstreamUserText(
    attachCodexMirrorIdentity(
      { role: "user", content: "visible question", timestamp: 0 },
      "turn-1:prompt",
    ),
    upstreamText,
  );
  return attachCodexMirrorAttestation(prompt, fingerprintCodexMirrorSourceMessage(prompt));
}

async function resolveFromTurns(params: {
  turns: readonly CodexTurn[];
  userMessageOrdinal: number;
  localPrefixTexts: readonly (string | undefined)[];
  localIdentities?: readonly (string | undefined)[];
  historyMode?: "legacy" | "paginated";
}) {
  const identities =
    params.localIdentities ??
    params.turns
      .flatMap((nativeTurn) =>
        nativeTurn.items
          .filter((nativeItem) => nativeItem.type === "userMessage")
          .map((nativeItem) => `${nativeTurn.id}:${nativeItem.id}`),
      )
      .slice(-params.localPrefixTexts.length);
  const entries: SessionTranscriptMessageEntry[] = params.localPrefixTexts.map((text, index) => ({
    entryId: `entry-${index}`,
    parentId: index > 0 ? `entry-${index - 1}` : null,
    seq: index,
    role: "user",
    message: identities[index]
      ? attachCodexMirrorIdentity(
          {
            role: "user",
            content: text ?? [{ type: "image", data: "", mimeType: "image/png" }],
            timestamp: index,
          },
          identities[index],
        )
      : { role: "user", content: text ?? "", timestamp: index },
  }));
  return await resolveEntries(
    params.turns,
    entries,
    `entry-${params.userMessageOrdinal}`,
    params.historyMode,
  );
}

async function resolveEntries(
  turns: readonly CodexTurn[],
  entries: SessionTranscriptMessageEntry[],
  entryId: string,
  historyMode: "legacy" | "paginated" = "legacy",
) {
  transcriptMocks.readVisibleEntries.mockResolvedValue(entries);
  const result = await resolveCodexUpstreamForkBoundary({
    agentId: "main",
    sessionId: "session-1",
    sessionKey: "agent:main:upstream",
    storePath: "/tmp/does-not-matter",
    entryId,
    threadId: "thread-1",
    control: {
      readThread: vi.fn(async () => ({ id: "thread-1", historyMode })),
      listTurnPage: vi.fn(async () => ({ data: [...turns] })),
    } as unknown as Parameters<typeof resolveCodexUpstreamForkBoundary>[0]["control"],
  });
  return result.ok ? { ok: true as const, boundary: result.boundary } : result;
}

