        message: `Managed Codex app-server version mismatch: expected ${CODEX_APP_SERVER_VERSION}, detected 0.146.0.`,
      }),
    ]);
    expect(deps.runVersionCommand).toHaveBeenCalledWith("/candidate/plugin/codex-native");
  });
});

