const CODEX_PLUGIN_AUTH_REQUIRED_REASON = "auth_required";
const CODEX_PLUGIN_NOT_SELECTED_REASON = "not selected for migration";
const CODEX_CONFIG_PATCH_MODE_RETURN = "return";
const CODEX_PLUGIN_LOAD_WARNING =
  "Some Codex plugins could not be migrated. Run `openclaw migrate codex` after onboarding.";
const TARGET_CODEX_MARKETPLACE_DISCOVERY_POLL_MS = 250;
const TARGET_CODEX_MARKETPLACE_DISCOVERY_TIMEOUT_MS = 30_000;
const TARGET_CODEX_MARKETPLACE_DISCOVERY_TIMEOUT_ENV =
  "OPENCLAW_CODEX_MIGRATION_PLUGIN_LIST_TIMEOUT_MS";

type CodexMigrationTargetAppServerPreparation = {
  dispose: () => Promise<void>;
};

class CodexPluginConfigConflictError extends Error {
  constructor(readonly reason: string) {
    super(reason);
    this.name = "CodexPluginConfigConflictError";
  }
}

function shouldReturnCodexPluginConfigPatch(ctx: MigrationProviderContext): boolean {
  return ctx.providerOptions?.configPatchMode === CODEX_CONFIG_PATCH_MODE_RETURN;
}

export function prepareTargetCodexAppServer(
  ctx: MigrationProviderContext,
): CodexMigrationTargetAppServerPreparation {
  const appServer = resolveTargetCodexAppServer(ctx);
  const targets = resolveCodexMigrationTargets(ctx);
  let warmedClient: Awaited<ReturnType<typeof getLeasedSharedCodexAppServerClient>> | undefined;
  const ready = getLeasedSharedCodexAppServerClient({
    startOptions: appServer.start,
    timeoutMs: 60_000,
    agentDir: targets.agentDir,
    config: ctx.config,
  }).then(
    (client) => {
      warmedClient = client;
    },
    () => undefined,
  );
  return {
    async dispose() {
      await ready;
      if (warmedClient) {
        releaseLeasedSharedCodexAppServerClient(warmedClient);
      }
      await clearSharedCodexAppServerClientIfCurrentAndWait(warmedClient, {
        exitTimeoutMs: 2_000,
        forceKillDelayMs: 250,
      });
    },
  };
}

export async function applyCodexMigrationPlan(params: {
  ctx: MigrationProviderContext;
  plan?: MigrationPlan;
  runtime?: MigrationProviderContext["runtime"];
}): Promise<MigrationApplyResult> {
  const plan = params.plan ?? (await buildCodexMigrationPlan(params.ctx));
  const reportDir = params.ctx.reportDir ?? path.join(params.ctx.stateDir, "migration", "codex");
  const items: MigrationItem[] = [];
  const targets = resolveCodexMigrationTargets(params.ctx);
  const codexHome =
    typeof plan.metadata?.codexHome === "string" && plan.metadata.codexHome.trim()
      ? plan.metadata.codexHome
      : plan.source;
  const authSource: CodexAuthSource = {
    codexHome,
    authPath: path.join(codexHome, "auth.json"),
    modelsCachePath: path.join(codexHome, "models_cache.json"),
  };
  const runtime = withCachedMigrationConfigRuntime(
    params.ctx.runtime ?? params.runtime,
    params.ctx.config,
  );
  const applyCtx = { ...params.ctx, runtime };
  for (const item of plan.items) {
    if (item.status !== "planned") {
      items.push(item);
      continue;
    }
    if (item.id === CODEX_PLUGIN_CONFIG_ITEM_ID) {
      items.push(await applyCodexPluginConfigItem(applyCtx, item, items));
    } else if (item.kind === "auth") {
      items.push(
        ...(await applyCodexAuthItems({
          ctx: applyCtx,
          item,
          source: authSource,
          targets,
        })),
      );
    } else if (item.kind === "plugin" && item.action === "install") {
      items.push(await applyCodexPluginInstallItem(applyCtx, item));
    } else if (item.kind === "manual") {
      items.push(applyMigrationManualItem(item));
    } else if (item.action === "archive") {
      items.push(await archiveMigrationItem(item, reportDir));
    } else if (item.kind === "memory") {
      items.push(
        await copyMemoryMigrationFileItem(item, reportDir, {
          workspaceDir: targets.workspaceDir,
          overwrite: params.ctx.overwrite,
        }),
      );
    } else {
      items.push(await copyMigrationFileItem(item, reportDir, { overwrite: params.ctx.overwrite }));
    }
  }
  const result: MigrationApplyResult = {
    ...plan,
    items,
    summary: summarizeMigrationItems(items),
    backupPath: params.ctx.backupPath,
    reportDir,
  };
  if (items.some(isCodexPluginLoadWarningItem)) {
    result.warnings = uniqueStrings([...(result.warnings ?? []), CODEX_PLUGIN_LOAD_WARNING]);
    result.nextSteps = uniqueStrings([CODEX_PLUGIN_LOAD_WARNING, ...(result.nextSteps ?? [])]);
  }
  await writeMigrationReport(result, { title: "Codex Migration Report" });
  return result;
}

async function applyCodexPluginInstallItem(
  ctx: MigrationProviderContext,
  item: MigrationItem,
): Promise<MigrationItem> {
  const policy = readCodexPluginPolicy(item);
  if (!policy) {
    return {
      ...markMigrationItemError(item, "invalid Codex plugin migration item"),
      details: { ...item.details, code: "invalid_plugin_item" },
    };
  }
  try {
    const appCacheKey = await buildTargetCodexPluginAppCacheKey(ctx);
    const appServer = resolveTargetCodexAppServer(ctx);
    const result = await ensureCodexPluginActivation({
      identity: policy,
      installEvenIfActive: true,
      request: async (method, requestParams) =>
        await requestTargetCodexAppServerJson({
          method,
          requestParams,
          timeoutMs: 60_000,
          startOptions: appServer.start,
          agentDir: resolveCodexMigrationTargets(ctx).agentDir,
          config: ctx.config,
          isolated: false,
        }),
      appCache: defaultCodexAppInventoryCache,
      appCacheKey,
    });
    const baseDetails = {
      ...item.details,
      code: result.reason,
      activationReason: result.reason,
      ...codexPluginActivationReportState(result),
      installAttempted: result.installAttempted,
      diagnostics: result.diagnostics.map((diagnostic) => diagnostic.message),
    };
    if (result.ok) {
      return {
        ...item,
        status: "migrated",
        ...(result.reason === "already_active" ? { reason: "already active" } : {}),
        details: baseDetails,
      };
    }
    if (result.reason === CODEX_PLUGIN_AUTH_REQUIRED_REASON) {
      return {
        ...item,
        status: "skipped",
        reason: CODEX_PLUGIN_AUTH_REQUIRED_REASON,
        details: {
          ...baseDetails,
          appsNeedingAuth: sanitizeAppsNeedingAuth(result.installResponse?.appsNeedingAuth ?? []),
        },
      };
    }
    if (result.reason === "plugin_missing" || result.reason === "marketplace_missing") {
      return {
        ...item,
        status: "warning",
        reason: result.reason,
        message: `Codex plugin "${policy.pluginName}" could not be migrated automatically`,
        details: {
          ...baseDetails,
          warningReason: CODEX_PLUGIN_LOAD_WARNING,
        },
      };
    }
    return {
      ...item,
      status: "error",
      reason: result.reason,
      details: baseDetails,
    };
  } catch (error) {
    if (isCodexPluginInventoryLoadError(error)) {
      return {
        ...item,
        status: "warning",
        reason: "plugin_inventory_unavailable",
        message: `Codex plugin "${policy.pluginName}" could not be migrated automatically`,
        details: {
          ...item.details,
          code: "plugin_inventory_unavailable",
          warningReason: CODEX_PLUGIN_LOAD_WARNING,
          diagnostic: coerceErrorMessage(error),
        },
      };
    }
    return {
      ...item,
      status: "error",
      reason: coerceErrorMessage(error),
      details: {
        ...item.details,
        code: "plugin_install_failed",
      },
    };
  }
}

function isCodexPluginInventoryLoadError(error: unknown): boolean {
  const message = coerceErrorMessage(error);
  return message.includes("codex app-server plugin/list timed out");
}

function resolveTargetCodexAppServer(ctx: MigrationProviderContext) {
  return resolveCodexAppServerRuntimeOptions({
    pluginConfig: readCodexPluginConfig(ctx.config),
  });
}

async function requestTargetCodexAppServerJson(params: {
  method: string;
  requestParams?: unknown;
  timeoutMs: number;
  startOptions: ReturnType<typeof resolveTargetCodexAppServer>["start"];
  agentDir: string;
  config: MigrationProviderContext["config"];
  isolated?: boolean;
}): Promise<unknown> {
  if (params.method !== "plugin/list") {
    return await requestCodexAppServerJson(params);
  }

  const deadline = Date.now() + params.timeoutMs;
  const discoveryTimeoutMs = targetCodexMarketplaceDiscoveryTimeoutMs();
  const discoveryDeadline = Math.min(deadline, Date.now() + discoveryTimeoutMs);
  let lastResponse: unknown;
  let attempt = 0;
  do {
    attempt += 1;
    const remainingMs = Math.max(1, discoveryDeadline - Date.now());
    lastResponse = await requestCodexAppServerJson({
      ...params,
      timeoutMs: remainingMs,
    });
    if (hasOpenAiCuratedMarketplace(lastResponse)) {
      return lastResponse;
    }
    if (Date.now() >= discoveryDeadline) {
      return lastResponse;
    }
    const waitMs = Math.min(
      TARGET_CODEX_MARKETPLACE_DISCOVERY_POLL_MS,
      discoveryDeadline - Date.now(),
    );
    await sleep(waitMs);
  } while (Date.now() < discoveryDeadline);

  return lastResponse;
}

function hasOpenAiCuratedMarketplace(response: unknown): boolean {
  if (!response || typeof response !== "object" || !("marketplaces" in response)) {
    return false;
  }
  const marketplaces = (response as { marketplaces?: unknown }).marketplaces;
  return (
    Array.isArray(marketplaces) &&
    marketplaces.some(
      (marketplace) =>
        marketplace &&
        typeof marketplace === "object" &&
        (marketplace as { name?: unknown }).name === CODEX_PLUGINS_MARKETPLACE_NAME,
    )
  );
}

function targetCodexMarketplaceDiscoveryTimeoutMs(env: NodeJS.ProcessEnv = process.env): number {
  const configured = parseStrictNonNegativeInteger(
    env[TARGET_CODEX_MARKETPLACE_DISCOVERY_TIMEOUT_ENV],
  );
  if (configured !== undefined) {
    return configured;
  }
  return TARGET_CODEX_MARKETPLACE_DISCOVERY_TIMEOUT_MS;
}

function isCodexPluginLoadWarningItem(item: MigrationItem): boolean {
  return (
    item.kind === "plugin" &&
    item.action === "install" &&
    item.status === "warning" &&
    item.details?.warningReason === CODEX_PLUGIN_LOAD_WARNING
  );
}

async function buildTargetCodexPluginAppCacheKey(ctx: MigrationProviderContext): Promise<string> {
  const targets = resolveCodexMigrationTargets(ctx);
  const appServer = resolveTargetCodexAppServer(ctx);
  const authProfileId = resolveCodexAppServerAuthProfileIdForAgent({
    agentDir: targets.agentDir,
    config: ctx.config,
  });
  const accountId = await resolveCodexAppServerAuthAccountCacheKey({
    authProfileId,
    agentDir: targets.agentDir,
    config: ctx.config,
  });
  const envApiKeyFingerprint = authProfileId
    ? undefined
    : resolveCodexAppServerFallbackApiKeyCacheKey({
        startOptions: appServer.start,
      });
  return buildCodexPluginAppCacheKey({
    appServer,
    agentDir: targets.agentDir,
    authProfileId,
    accountId,
    envApiKeyFingerprint,
  });
}

async function applyCodexPluginConfigItem(
  ctx: MigrationProviderContext,
  item: MigrationItem,
  appliedItems: readonly MigrationItem[],
): Promise<MigrationItem> {
  const incompletePluginItems = appliedItems.filter(
    (candidate) =>
      candidate.kind === "plugin" &&
      candidate.action === "install" &&
      readCodexPluginPolicy(candidate) !== undefined &&
      !isCodexPluginConfigTerminal(candidate),
  );
  if (incompletePluginItems.length > 0) {
    return {
      ...item,
      status: "warning",
      reason: "selected Codex plugin activation is incomplete",
    };
  }
  const entries = appliedItems
    .map(readAppliedPluginConfigEntry)
    .filter((entry): entry is CodexPluginMigrationConfigEntry => entry !== undefined);
  if (entries.length === 0) {
    return {
      ...markMigrationItemSkipped(item, "no selected Codex plugins"),
      deferredCompletion: true,
    };
  }
  const returnPatch = shouldReturnCodexPluginConfigPatch(ctx);
  const configApi = resolveMigrationConfigRuntime(ctx);
  const currentConfig = returnPatch
    ? ctx.config
    : (configApi?.current?.() as MigrationProviderContext["config"] | undefined);
  if (!currentConfig) {
    return markMigrationItemError(item, "config runtime unavailable");
  }
  const value = buildCodexPluginsConfigValue(entries, currentConfig);
  if (!ctx.overwrite && hasCodexPluginConfigConflict(currentConfig, value)) {
    return markMigrationItemConflict(item, MIGRATION_REASON_TARGET_EXISTS);
  }
  const migratedItem: MigrationItem = {
    ...item,
    status: "migrated",
    details: {
      ...item.details,
      path: [...CODEX_PLUGIN_CONFIG_PATH],
      value,
    },
  };
  if (returnPatch) {
    return migratedItem;
  }
  if (!configApi?.mutateConfigFile) {
    return markMigrationItemError(item, "config runtime unavailable");
  }
  try {
    await configApi.mutateConfigFile({
      base: "runtime",
      afterWrite: { mode: "auto" },
      mutate(draft) {
        if (!ctx.overwrite && hasCodexPluginConfigConflict(draft, value)) {
          throw new CodexPluginConfigConflictError(MIGRATION_REASON_TARGET_EXISTS);
        }
        writeMigrationConfigPath(draft as Record<string, unknown>, CODEX_PLUGIN_CONFIG_PATH, value);
      },
    });
    return migratedItem;
  } catch (error) {
    if (error instanceof CodexPluginConfigConflictError) {
      return markMigrationItemConflict(item, error.reason);
    }
    return markMigrationItemError(item, coerceErrorMessage(error));
  }
}

function isCodexPluginConfigTerminal(item: MigrationItem): boolean {
  return (
    item.status === "migrated" ||
    (item.status === "skipped" &&
      (item.deferredCompletion === true ||
        item.reason === CODEX_PLUGIN_NOT_SELECTED_REASON ||
        item.reason === CODEX_PLUGIN_AUTH_REQUIRED_REASON))
  );
}

function readAppliedPluginConfigEntry(
  item: MigrationItem,
): CodexPluginMigrationConfigEntry | undefined {
  if (item.status === "migrated" || item.deferredCompletion === true) {
    return readCodexPluginMigrationConfigEntry(item, true);
  }
  if (item.status === "skipped" && item.reason === CODEX_PLUGIN_AUTH_REQUIRED_REASON) {
    return readCodexPluginMigrationConfigEntry(item, false);
  }
  return undefined;
}

function readCodexPluginPolicy(item: MigrationItem): ResolvedCodexPluginPolicy | undefined {
  const entry = readCodexPluginMigrationConfigEntry(item, true);
  if (!entry) {
    return undefined;
  }
  return {
    configKey: entry.configKey,
    marketplaceName: CODEX_PLUGINS_MARKETPLACE_NAME,
    pluginName: entry.pluginName,
    enabled: true,
    allowDestructiveActions: true,
    destructiveApprovalMode: "allow",
  };
}

// Codex plugin module implements auth behavior.
import { loadAuthProfileStoreWithoutExternalProfiles } from "openclaw/plugin-sdk/agent-runtime";
import {
  createMigrationItem,
  markMigrationItemConflict,
  markMigrationItemError,
  markMigrationItemSkipped,
  mergeMigrationConfigValue,
  resolveMigrationConfigRuntime,
} from "openclaw/plugin-sdk/migration";
import type { MigrationItem, MigrationProviderContext } from "openclaw/plugin-sdk/plugin-entry";
import {
  applyAuthProfileConfig,
  buildApiKeyCredential,
  buildOpenAICodexCredentialExtra,
  buildOauthProviderAuthResult,
  readCodexCliCredentialsCached,
  resolveOpenAICodexAuthIdentity,
  resolveOpenAICodexImportProfileName,
  updateAuthProfileStoreWithLock,
  type AuthProfileStore,
  type OAuthCredential,
  type OpenClawConfig,
  type ProviderAuthResult,
} from "openclaw/plugin-sdk/provider-auth";
import {
  isRecord,
  normalizeOptionalString as readString,
} from "openclaw/plugin-sdk/string-coerce-runtime";
import { readJsonObject } from "./helpers.js";
import type { CodexSource } from "./source.js";
import type { resolveCodexMigrationTargets } from "./targets.js";

const OPENAI_PROVIDER_ID = "openai";
const OPENAI_CODEX_DEFAULT_MODEL = "openai/gpt-5.6-sol";
const CODEX_IMPORT_DISPLAY_NAME = "Codex import";
const CODEX_REASON_AUTH_NOT_SELECTED = "auth credential migration not selected";
const CODEX_REASON_AUTH_PROFILE_EXISTS = "auth profile exists";
const CODEX_REASON_AUTH_PROFILE_WRITE_FAILED = "failed to write auth profile";
const CODEX_REASON_AUTH_NO_LONGER_PRESENT = "auth credential no longer present";
const CODEX_REASON_MISSING_AUTH_METADATA = "missing auth metadata";
const CODEX_CONFIG_PATCH_MODE_RETURN = "return";

type CodexMigrationTargets = ReturnType<typeof resolveCodexMigrationTargets>;
export type CodexAuthSource = Pick<CodexSource, "codexHome" | "authPath" | "modelsCachePath">;

type CodexAuthCredential =
  | {
      kind: "oauth";
      provider: typeof OPENAI_PROVIDER_ID;
      profileId: string;
      result: ProviderAuthResult;
    }
  | {
      kind: "api_key";
      provider: typeof OPENAI_PROVIDER_ID;
      profileId: string;
      key: string;
    };

type CodexAuthProfileConfig = {
  profileId: string;
  provider: string;
  mode: "api_key" | "oauth";
  email?: string;
  displayName?: string;
};

type CodexAuthConfigApplyResult = "configured" | "conflict" | "unavailable";

class CodexAuthConfigConflict extends Error {}

async function readModelRefs(source: CodexAuthSource): Promise<string[]> {
  const cache = await readJsonObject(source.modelsCachePath);
  const models = Array.isArray(cache.models) ? cache.models : [];
  const refs = new Set<string>();
  for (const model of models) {
    const slug =
      typeof model === "string"
        ? model.trim()
        : isRecord(model)
          ? (readString(model.slug) ?? readString(model.id) ?? readString(model.name))
          : undefined;
    if (!slug) {
      continue;
    }
    refs.add(`${OPENAI_PROVIDER_ID}/${slug}`);
  }
  refs.add(OPENAI_CODEX_DEFAULT_MODEL);
  return [...refs].toSorted();
}

async function buildCodexOAuthCredential(
  source: CodexAuthSource,
): Promise<CodexAuthCredential | null> {
  const credential = readCodexCliCredentialsCached({
    codexHome: source.codexHome,
    allowKeychainPrompt: false,
    ttlMs: 0,
  });
  if (!credential) {
    return null;
  }
  const identity = resolveOpenAICodexAuthIdentity({
    access: credential.access,
    accountId: credential.accountId,
  });
  const modelRefs = await readModelRefs(source);
  const configPatch = {
    agents: {
      defaults: {
        models: Object.fromEntries(modelRefs.map((modelRef) => [modelRef, {}])),
      },
    },
  } satisfies Partial<OpenClawConfig>;
  const result = buildOauthProviderAuthResult({
    providerId: OPENAI_PROVIDER_ID,
    defaultModel: OPENAI_CODEX_DEFAULT_MODEL,
    access: credential.access,
    refresh: credential.refresh,
    expires: credential.expires,
    email: identity.email,
    profileName: resolveOpenAICodexImportProfileName(identity, "codex-import"),
    displayName: CODEX_IMPORT_DISPLAY_NAME,
    credentialExtra: buildOpenAICodexCredentialExtra({
      accountId: identity.accountId,
      chatgptPlanType: identity.chatgptPlanType,
      idToken: credential.idToken,
    }),
    configPatch,
  });
  const profile = result.profiles[0];
  return profile
    ? {
        kind: "oauth",
        provider: OPENAI_PROVIDER_ID,
        profileId: profile.profileId,
        result,
      }
    : null;
}

async function buildCodexApiKeyCredential(
  source: CodexAuthSource,
): Promise<CodexAuthCredential | null> {
  const raw = await readJsonObject(source.authPath);
  const key = readString(raw.OPENAI_API_KEY);
  if (!key) {
    return null;
  }
  return {
    kind: "api_key",
    provider: OPENAI_PROVIDER_ID,
    profileId: "openai:codex-import",
    key,
  };
}

async function readCodexAuthCredentials(source: CodexAuthSource): Promise<CodexAuthCredential[]> {
  const oauth = await buildCodexOAuthCredential(source);
  const apiKey = await buildCodexApiKeyCredential(source);
  return [oauth, apiKey].filter((entry): entry is CodexAuthCredential => entry !== null);
}

function findMatchingOAuthProfile(
  store: AuthProfileStore,
  credential: OAuthCredential,
): string | undefined {
  for (const [profileId, existing] of Object.entries(store.profiles)) {
    if (existing.type !== "oauth" || existing.provider !== credential.provider) {
      continue;
    }
    if (credential.accountId && existing.accountId === credential.accountId) {
      return profileId;
    }
    const canMatchByEmail = !credential.accountId || !existing.accountId;
    if (canMatchByEmail && credential.email && existing.email === credential.email) {
      return profileId;
    }
  }
  return undefined;
}

function findMatchingApiKeyProfile(
  store: AuthProfileStore,
  provider: string,
  key: string,
): string | undefined {
  for (const [profileId, existing] of Object.entries(store.profiles)) {
    if (existing.type === "api_key" && existing.provider === provider && existing.key === key) {
      return profileId;
    }
  }
  return undefined;
}

function itemProfileTarget(
  credential: CodexAuthCredential,
  store: AuthProfileStore,
): { profileId: string; matchedExisting: boolean } {
  if (credential.kind === "oauth") {
    const profile = credential.result.profiles[0];
    const matched =
      profile?.credential.type === "oauth"
        ? findMatchingOAuthProfile(store, profile.credential)
        : undefined;
    return { profileId: matched ?? credential.profileId, matchedExisting: Boolean(matched) };
  }
  const matched = findMatchingApiKeyProfile(store, credential.provider, credential.key);
  return { profileId: matched ?? credential.profileId, matchedExisting: Boolean(matched) };
}

function replaceConfigDraft(draft: OpenClawConfig, next: OpenClawConfig): void {
  for (const key of Object.keys(draft) as Array<keyof OpenClawConfig>) {
    delete draft[key];
  }
  Object.assign(draft, next);
}

function existingAuthProfileConfigIsCompatible(
  existing: NonNullable<NonNullable<OpenClawConfig["auth"]>["profiles"]>[string],
  profile: CodexAuthProfileConfig,
): boolean {
  if (existing.provider !== profile.provider || existing.mode !== profile.mode) {
    return false;
  }
  if (existing.email && profile.email && existing.email !== profile.email) {
    return false;
  }
  return true;
}

function hasAuthProfileConfigConflict(
  config: OpenClawConfig,
  profile: CodexAuthProfileConfig,
  overwrite: boolean,
): boolean {
  if (overwrite) {
    return false;
  }
  const existing = config.auth?.profiles?.[profile.profileId];
  return Boolean(existing && !existingAuthProfileConfigIsCompatible(existing, profile));
}

function hasCurrentAuthProfileConfigConflict(
  ctx: MigrationProviderContext,
  profile: CodexAuthProfileConfig,
): boolean {
  let config = ctx.config;
  try {
    config =
      (resolveMigrationConfigRuntime(ctx)?.current?.() as OpenClawConfig | undefined) ?? config;
  } catch {
    // Fall back to the planning snapshot; direct config writes recheck inside mutate.
  }
  return hasAuthProfileConfigConflict(config, profile, Boolean(ctx.overwrite));
}

function applyDefaultModelIfMissing(cfg: OpenClawConfig): OpenClawConfig {
  const currentModel = cfg.agents?.defaults?.model;
  const primary =
    typeof currentModel === "string"
      ? currentModel
      : isRecord(currentModel)
        ? readString(currentModel.primary)
        : undefined;
  if (primary) {
    return cfg;
  }
  return {
    ...cfg,
    agents: {
      ...cfg.agents,
      defaults: {
        ...cfg.agents?.defaults,
        model: {
          ...(isRecord(currentModel) ? currentModel : {}),
          primary: OPENAI_CODEX_DEFAULT_MODEL,
        },
      },
    },
  };
}

function applyOAuthConfigToConfig(
  cfg: OpenClawConfig,
  credential: Extract<CodexAuthCredential, { kind: "oauth" }>,
  profileId: string,
): OpenClawConfig {
  let next = mergeMigrationConfigValue(cfg, credential.result.configPatch) as OpenClawConfig;
  const profile = credential.result.profiles[0];
  if (profile) {
    next = applyAuthProfileConfig(next, {
      profileId,
      provider: profile.credential.provider,
      mode: "oauth",
      ...("email" in profile.credential && profile.credential.email
        ? { email: profile.credential.email }
        : {}),
      ...("displayName" in profile.credential && profile.credential.displayName
        ? { displayName: profile.credential.displayName }
        : {}),
      preferProfileFirst: false,
    });
  }
  return applyDefaultModelIfMissing(next);
}

function applyApiKeyConfigToConfig(
  cfg: OpenClawConfig,
  credential: Extract<CodexAuthCredential, { kind: "api_key" }>,
  profileId: string,
): OpenClawConfig {
  return applyAuthProfileConfig(cfg, {
    profileId,
    provider: credential.provider,
    mode: "api_key",
    displayName: CODEX_IMPORT_DISPLAY_NAME,
    preferProfileFirst: false,
  });
}

function shouldReturnAuthConfigPatch(ctx: MigrationProviderContext): boolean {
  return ctx.providerOptions?.configPatchMode === CODEX_CONFIG_PATCH_MODE_RETURN;
}

function authProfileConfigForCredential(
  credential: CodexAuthCredential,
  profileId: string,
): CodexAuthProfileConfig | null {
  if (credential.kind === "api_key") {
    return {
      profileId,
      provider: credential.provider,
      mode: "api_key",
      displayName: CODEX_IMPORT_DISPLAY_NAME,
    };
  }
  const profile = credential.result.profiles[0];
  if (!profile || profile.credential.type !== "oauth") {
    return null;
  }
  return {
    profileId,
    provider: profile.credential.provider,
    mode: "oauth",
    ...(profile.credential.email ? { email: profile.credential.email } : {}),
    ...(profile.credential.displayName ? { displayName: profile.credential.displayName } : {}),
  };
}

async function applyCodexAuthProfileConfig(
  ctx: MigrationProviderContext,
  profile: CodexAuthProfileConfig,
  applyConfig: (config: OpenClawConfig) => OpenClawConfig,
): Promise<CodexAuthConfigApplyResult> {
  const configApi = resolveMigrationConfigRuntime(ctx);
  if (!configApi?.current || !configApi.mutateConfigFile) {
    return "unavailable";
  }
  try {
    await configApi.mutateConfigFile({
      base: "runtime",
      afterWrite: { mode: "auto" },
      mutate(draft) {
        const current = draft;
        if (hasAuthProfileConfigConflict(current, profile, Boolean(ctx.overwrite))) {
          throw new CodexAuthConfigConflict();
        }
        const next = applyConfig(current);
        replaceConfigDraft(draft, next);
      },
    });
    return "configured";
  } catch (error) {
    return error instanceof CodexAuthConfigConflict ? "conflict" : "unavailable";
  }
}

async function applyCodexAuthConfig(
  ctx: MigrationProviderContext,
  credential: CodexAuthCredential,
  profileId: string,
): Promise<CodexAuthConfigApplyResult> {
  const profile = authProfileConfigForCredential(credential, profileId);
  if (!profile) {
    return "unavailable";
  }
  return applyCodexAuthProfileConfig(ctx, profile, (config) =>
    applyCredentialConfig(config, credential, profileId),
  );
}

function applyCredentialConfig(
  config: OpenClawConfig,
  credential: CodexAuthCredential,
  profileId: string,
): OpenClawConfig {
  return credential.kind === "oauth"
    ? applyOAuthConfigToConfig(config, credential, profileId)
    : applyApiKeyConfigToConfig(config, credential, profileId);
}

export async function buildCodexAuthItems(params: {
  ctx: MigrationProviderContext;
  source: CodexAuthSource;
  targets: CodexMigrationTargets;
}): Promise<MigrationItem[]> {
  const credentials = await readCodexAuthCredentials(params.source);
  if (credentials.length === 0) {
    return [];
  }
  const store = loadAuthProfileStoreWithoutExternalProfiles(params.targets.agentDir);
  const skipped = !params.ctx.includeSecrets;
  return credentials.map((credential) => {
    const { profileId, matchedExisting } = itemProfileTarget(credential, store);
    const targetExists = Boolean(store.profiles[profileId]);
    const configProfile = authProfileConfigForCredential(credential, profileId);
    const configConflict = configProfile
      ? hasAuthProfileConfigConflict(
          params.ctx.config,
          configProfile,
          Boolean(params.ctx.overwrite),
        )
      : false;
    const conflict =
      ((targetExists && !matchedExisting && !params.ctx.overwrite) || configConflict) && !skipped;
    return createMigrationItem({
      id: `auth:${credential.provider}`,
      kind: "auth",
      action: skipped ? "skip" : "create",
      source: params.source.authPath,
      // Credentials land in the agent's SQLite auth profile store; naming the
      // retired JSON file here promised operators a file that is never created.
      target: `${params.targets.agentDir}/openclaw-agent.sqlite#auth_profile_store:${profileId}`,
      status: skipped ? "skipped" : conflict ? "conflict" : "planned",
      sensitive: true,
      reason: skipped
        ? CODEX_REASON_AUTH_NOT_SELECTED
        : conflict
          ? CODEX_REASON_AUTH_PROFILE_EXISTS
          : undefined,
      message:
        credential.kind === "oauth"
          ? "Import Codex OAuth credentials and configure OpenAI Codex models."
          : "Import Codex OpenAI API key.",
      details: {
        provider: credential.provider,
        profileId,
        sourceProfileId: credential.profileId,
        sourceKind: "codex-auth-json",
        credentialKind: credential.kind,
      },
    });
  });
}

export async function applyCodexAuthItems(params: {
  ctx: MigrationProviderContext;
  item: MigrationItem;
  source: CodexAuthSource;
  targets: CodexMigrationTargets;
}): Promise<MigrationItem[]> {
  const { ctx, item, source, targets } = params;
  if (item.status !== "planned") {
    return [item];
  }
  const profileId = typeof item.details?.profileId === "string" ? item.details.profileId : "";
  const provider = typeof item.details?.provider === "string" ? item.details.provider : "";
  const sourceProfileId =
    typeof item.details?.sourceProfileId === "string" ? item.details.sourceProfileId : undefined;
  if (!profileId || !provider) {
    return [markMigrationItemError(item, CODEX_REASON_MISSING_AUTH_METADATA)];
  }
  const credential = (await readCodexAuthCredentials(source)).find(
    (candidate) => candidate.provider === provider,
  );
  if (!credential) {
    return [markMigrationItemSkipped(item, CODEX_REASON_AUTH_NO_LONGER_PRESENT)];
  }
  if (credential.kind === "oauth" && sourceProfileId && credential.profileId !== sourceProfileId) {
    return [markMigrationItemSkipped(item, CODEX_REASON_AUTH_NO_LONGER_PRESENT)];
  }
  const oauthProfile = credential.kind === "oauth" ? credential.result.profiles[0] : undefined;
  const oauthCredential =
    oauthProfile?.credential.type === "oauth" ? oauthProfile.credential : undefined;
  if (credential.kind === "oauth" && !oauthCredential) {
    return [markMigrationItemError(item, CODEX_REASON_MISSING_AUTH_METADATA)];
  }
  const configProfile = authProfileConfigForCredential(credential, profileId);
  if (!configProfile) {
    return [markMigrationItemError(item, CODEX_REASON_MISSING_AUTH_METADATA)];
  }
  if (hasCurrentAuthProfileConfigConflict(ctx, configProfile)) {
    return [markMigrationItemConflict(item, CODEX_REASON_AUTH_PROFILE_EXISTS)];
  }
  let conflicted = false;
  let wrote = false;
  const store = await updateAuthProfileStoreWithLock({
    agentDir: targets.agentDir,
    stateDir: ctx.stateDir,
    updater: (freshStore) => {
      const existing = freshStore.profiles[profileId];
      if (!ctx.overwrite && existing) {
        const matchedProfileId =
          credential.kind === "oauth"
            ? findMatchingOAuthProfile(freshStore, oauthCredential!)
            : findMatchingApiKeyProfile(freshStore, credential.provider, credential.key);
        if (matchedProfileId === profileId) {
          return false;
        }
        conflicted = true;
        return false;
      }
      freshStore.profiles[profileId] =
        credential.kind === "oauth"
          ? {
              ...oauthCredential!,
              displayName: CODEX_IMPORT_DISPLAY_NAME,
            }
          : {
              ...buildApiKeyCredential(credential.provider, credential.key),
              displayName: CODEX_IMPORT_DISPLAY_NAME,
            };
      wrote = true;
      return true;
    },
  });
  if (conflicted) {
    return [markMigrationItemConflict(item, CODEX_REASON_AUTH_PROFILE_EXISTS)];
  }
  if (!store?.profiles[profileId]) {
    return [markMigrationItemError(item, CODEX_REASON_AUTH_PROFILE_WRITE_FAILED)];
  }
  const configResult = shouldReturnAuthConfigPatch(ctx)
    ? "unavailable"
    : await applyCodexAuthConfig(ctx, credential, profileId);
  if (configResult === "conflict") {
    return [markMigrationItemConflict(item, CODEX_REASON_AUTH_PROFILE_EXISTS)];
  }
  const migratedItem: MigrationItem = {
    ...item,
    status: "migrated",
    details: {
      ...item.details,
      wroteAuthProfile: wrote,
      configUpdated: configResult === "configured",
      ...(shouldReturnAuthConfigPatch(ctx) ? { configPatchReturned: true } : {}),
    },
  };
  return [
    migratedItem,
    ...(shouldReturnAuthConfigPatch(ctx)
      ? buildCodexAuthConfigPatchItems(ctx, migratedItem, credential, profileId)
      : []),
  ];
}

function buildCodexAuthConfigPatchItems(
  ctx: MigrationProviderContext,
  item: MigrationItem,
  credential: CodexAuthCredential,
  profileId: string,
): MigrationItem[] {
  const next = applyCredentialConfig(ctx.config, credential, profileId);
  const items: MigrationItem[] = [];
  if (next.auth) {
    items.push(
      createMigrationItem({
        id: `${item.id}:config:auth`,
        kind: "config",
        action: "merge",
        status: "migrated",
        target: "auth",
        message: "Configure imported Codex auth profile.",
        details: {
          path: ["auth"],
          value: next.auth,
        },
      }),
    );
  }
  if (next.agents?.defaults) {
    items.push(
      createMigrationItem({
        id: `${item.id}:config:agents-defaults`,
        kind: "config",
        action: "merge",
        status: "migrated",
        target: "agents.defaults",
        message: "Configure imported Codex models.",
        details: {
          path: ["agents", "defaults"],
          value: next.agents.defaults,
        },
      }),
    );
  }
  return items;
}

// Codex helper module supports helpers behavior.
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { readJsonFileWithFallback } from "openclaw/plugin-sdk/json-store";
import { pathExists } from "openclaw/plugin-sdk/security-runtime";

export async function exists(filePath: string): Promise<boolean> {
  return await pathExists(filePath);
}

export async function isDirectory(filePath: string | undefined): Promise<boolean> {
  if (!filePath) {
    return false;
  }
  try {
    return (await fs.stat(filePath)).isDirectory();
  } catch {
    return false;
  }
}

export function resolveUserHomeDir(): string {
  return process.env.HOME?.trim() || os.homedir();
}

export function resolveHomePath(value: string): string {
  if (value === "~") {
    return resolveUserHomeDir();
  }
  if (value.startsWith("~/")) {
    return path.join(resolveUserHomeDir(), value.slice(2));
  }
  return path.resolve(value);
}

export function sanitizeName(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replaceAll(/[^a-z0-9._-]+/gu, "-")
    .replaceAll(/^-+|-+$/gu, "")
    .slice(0, 64);
}

export async function readJsonObject(
  filePath: string | undefined,
): Promise<Record<string, unknown>> {
  if (!filePath) {
    return {};
  }
  const { value: parsed } = await readJsonFileWithFallback<unknown>(filePath, {});
  return parsed && typeof parsed === "object" && !Array.isArray(parsed)
    ? (parsed as Record<string, unknown>)
    : {};
}

