function toolFixture(params?: {
  owner?: boolean;
  workspaceDir?: string;
  bindingCwd?: string;
  configWorkspaceDir?: string;
}) {
  const read = vi.fn(async () => (params?.bindingCwd ? { cwd: params.bindingCwd } : undefined));
