type CodexCatalogRequestOptions = {
  agentDir: string;
  config: OpenClawConfig | undefined;
  startOptions: CodexAppServerStartOptions;
};

type CodexCatalogPageCacheEntry = {
  expiresAt: number;
  page: Promise<CodexSessionCatalogPage>;
  value?: CodexSessionCatalogPage;
};

function codexCatalogPageCacheKey(
  params: CodexSessionCatalogPageParams,
  agentId: string,
  source?: CodexCatalogHome,
): string {
  // Mirror listPage's search/cwd normalization; these trimmed values are what reach app-server.
  return JSON.stringify([
    agentId,
    source?.sourceHomeId ?? null,
    params.cursor ?? null,
    params.limit ?? null,
    params.searchTerm?.trim().toLocaleLowerCase() || null,
    params.cwd?.trim() || null,
  ]);
}

type CodexSessionCatalogRequestSnapshot = {
  requestTimeoutMs: number;
  listThreads(params: CodexThreadListParams, timeoutMs: number): Promise<CodexThreadListResponse>;
  listThreadTurns(params: CodexThreadTurnsListParams): Promise<CodexThreadTurnsListResponse>;
  forkThread(params: CodexThreadForkParams): Promise<CodexThreadForkResponse>;
  readThread(threadId: string, includeTurns: boolean, timeoutMs?: number): Promise<CodexThread>;
  archiveThread(threadId: string): Promise<void>;
};

type CodexCatalogRequestMethod =
  | typeof CODEX_CONTROL_METHODS.archiveThread
  | typeof CODEX_CONTROL_METHODS.forkThread
  | typeof CODEX_CONTROL_METHODS.listThreads
  | typeof CODEX_CONTROL_METHODS.listThreadTurns
  | typeof CODEX_CONTROL_METHODS.readThread;

type CodexCatalogRequest = <M extends CodexCatalogRequestMethod>(
  method: M,
  requestParams: CodexAppServerRequestParams<M>,
  timeoutMs?: number,
) => Promise<CodexAppServerRequestResult<M>>;

function createCodexCatalogRequestSnapshot(
  requestTimeoutMs: number,
  request: CodexCatalogRequest,
): CodexSessionCatalogRequestSnapshot {
  return {
    requestTimeoutMs,
    listThreads: (params, timeoutMs) =>
      request(CODEX_CONTROL_METHODS.listThreads, params, timeoutMs),
    listThreadTurns: (params) => request(CODEX_CONTROL_METHODS.listThreadTurns, params),
    forkThread: (params) =>
      request(CODEX_CONTROL_METHODS.forkThread, assertCodexThreadForkParams(params)),
    readThread: async (threadId, includeTurns, timeoutMs) =>
      (await request(CODEX_CONTROL_METHODS.readThread, { threadId, includeTurns }, timeoutMs))
        .thread,
    archiveThread: async (threadId) => {
      await request(CODEX_CONTROL_METHODS.archiveThread, { threadId });
    },
  };
}

function createCodexSessionCatalogControlFromRequests(params: {
  clientId?: string;
  connectionFingerprint?: string;
  createRequestSnapshot: () => CodexSessionCatalogRequestSnapshot;
  localSessionsRoot?: string;
  sourceHomeId?: string;
  managedThreads?: CodexManagedThreadStore;
  now: () => number;
  withPinnedConnection: CodexSessionCatalogControl["withPinnedConnection"];
}): CodexSessionCatalogControl {
  return {
    ...(params.clientId ? { clientId: params.clientId } : {}),
    ...(params.connectionFingerprint
      ? { connectionFingerprint: params.connectionFingerprint }
      : {}),
    withPinnedConnection: params.withPinnedConnection,
    async requireEligibleThread(threadId) {
      const requests = params.createRequestSnapshot();
      const deadline = params.now() + requests.requestTimeoutMs;
      const unverified = () =>
        new CatalogParamsError(
          "Codex session eligibility could not be verified. Refresh the catalog and verify the session in its native Codex home before retrying.",
        );
      const remaining = () => {
        const timeoutMs = Math.ceil(deadline - params.now());
        if (timeoutMs <= 0) {
          throw unverified();
        }
        return timeoutMs;
      };
      const verify = async () => {
        if (
          params.sourceHomeId &&
          (await params.managedThreads?.has(params.sourceHomeId, threadId))
        ) {
          throw unverified();
        }
        // Local exact reads seed missing native index rows before DB-only membership checks.
        // Remote/pathless stores retain native scan-and-repair membership: no local rollout authority.
        const root = params.localSessionsRoot;
        const thread = root ? await requests.readThread(threadId, false, remaining()) : undefined;
        if (
          root &&
          (!thread || thread.id !== threadId || !isInteractiveThreadSource(thread.source))
        ) {
          throw unverified();
        }
        let cursor: string | undefined;
        const seenCursors = new Set<string>();
        for (let pageIndex = 0; pageIndex < MAX_ACTION_CATALOG_PAGES; pageIndex += 1) {
          const page = await requests.listThreads(
            {
              archived: false,
              limit: CODEX_SESSION_CATALOG_MAX_PAGE_LIMIT,
              modelProviders: [],
              sortKey: root ? "recency_at" : "updated_at",
              sortDirection: "desc",
              ...(root
                ? { useStateDbOnly: true, ...(thread?.cwd ? { cwd: thread.cwd } : {}) }
                : {}),
              ...(cursor ? { cursor } : {}),
            },
            remaining(),
          );
          remaining();
          const candidate = page.data.find((value) => value.id === threadId);
          if (candidate) {
            if (!isInteractiveThreadSource(candidate.source)) {
              throw unverified();
            }
            if (root && thread) {
              const rolloutPath = thread.path;
              // Codex may retain the plain path after compressing the selected immutable rollout.
              if (
                !rolloutPath ||
                !candidate.path ||
                rolloutPath.replace(/\.zst$/u, "") !== candidate.path.replace(/\.zst$/u, "")
              ) {
                throw unverified();
              }
              const metadata = await readCodexSessionMeta(root, rolloutPath, threadId);
              remaining();
              if (
                !metadata ||
                !isInteractiveThreadSource(metadata.source) ||
                metadata.originator === "openclaw"
              ) {
                throw unverified();
              }
              return thread;
            }
            return candidate;
          }
          const nextCursor = readControlCursor(page.nextCursor, "next response");
          if (!nextCursor || seenCursors.has(nextCursor)) {
            throw unverified();
          }
          seenCursors.add(nextCursor);
          cursor = nextCursor;
        }
        throw unverified();
      };
      return await withTimeout(
        verify(),
        requests.requestTimeoutMs,
        "Codex session eligibility could not be verified",
        unverified,
      );
    },
    async listPage(pageParams) {
      const limit = normalizeLimit(pageParams.limit, "limit");
      // App Server search also matches transcript previews. Scan native pages
      // without that filter so this catalog remains a title-only surface.
      const search = pageParams.searchTerm?.trim().toLocaleLowerCase() || undefined;
      const cwd = pageParams.cwd?.trim() || undefined;
      const maxPages = search ? MAX_TITLE_SEARCH_CATALOG_PAGES : 1;
      const sessions: CodexSessionCatalogSession[] = [];
      const managedThreads: Array<{ threadId: string; rolloutPath?: string }> = [];
      let cursor = readControlCursor(pageParams.cursor, "request");
      let nextCursor: string | undefined;
      let backwardsCursor: string | undefined;
      const seenCursors = new Set(cursor ? [cursor] : []);
      const requests = params.createRequestSnapshot();
      const deadline = params.now() + requests.requestTimeoutMs;

      for (let pageIndex = 0; pageIndex < maxPages; pageIndex += 1) {
        const remainingTimeoutMs = Math.ceil(deadline - params.now());
        if (remainingTimeoutMs <= 0) {
          throw new Error("Codex session catalog listing timed out");
        }
        const response = await requests.listThreads(
          {
            archived: false,
            limit: limit - sessions.length,
            modelProviders: [],
            // Match Codex's resume picker/latest-session ordering so a session
            // created outside OpenClaw enters the first catalog page immediately.
            sortKey: "updated_at",
            sortDirection: "desc",
            ...(cwd ? { cwd } : {}),
            ...(cursor ? { cursor } : {}),
          },
          remainingTimeoutMs,
        );
        if (pageIndex === 0) {
          backwardsCursor = readControlCursor(response.backwardsCursor, "backwards response");
        }
        for (const thread of response.data) {
          if (await isOpenClawManagedCodexThread(thread, params.localSessionsRoot)) {
            const rolloutPath = typeof thread.path === "string" ? thread.path.trim() : "";
            managedThreads.push({
              threadId: thread.id,
              ...(rolloutPath ? { rolloutPath } : {}),
            });
            continue;
          }
          const session = toCatalogSession(thread, false);
          if (
            session &&
            (!search ||
              (session.name ?? session.fallbackName)?.toLocaleLowerCase().includes(search))
          ) {
            sessions.push(session);
          }
        }
        nextCursor = readControlCursor(response.nextCursor, "next response");
        if (!nextCursor || sessions.length >= limit) {
          break;
        }
        if (seenCursors.has(nextCursor)) {
          throw new Error("Codex session catalog returned a repeated search cursor");
        }
        seenCursors.add(nextCursor);
        cursor = nextCursor;
      }
      return {
        sessions,
        ...(managedThreads.length > 0 ? { managedThreads } : {}),
        ...(nextCursor ? { nextCursor } : {}),
        ...(backwardsCursor ? { backwardsCursor } : {}),
      };
    },
    async listDescendantPage(listParams) {
      const requests = params.createRequestSnapshot();
      const response = await requests.listThreads(listParams, requests.requestTimeoutMs);
      return response;
    },
    async readThread(threadId, includeTurns = false) {
      const thread = await params.createRequestSnapshot().readThread(threadId, includeTurns);
      return thread;
    },
    async listTurnPage(listParams) {
      const response = await params.createRequestSnapshot().listThreadTurns(listParams);
      return response;
    },
    async forkThread(forkParams) {
      return await params.createRequestSnapshot().forkThread(forkParams);
    },
    async archiveThread(threadId) {
      await params.createRequestSnapshot().archiveThread(threadId);
    },
  };
}

/** Builds the passive catalog over the Codex plugin's canonical shared client. */
export function createCodexSessionCatalogControl(params: {
  config?: OpenClawConfig;
  env?: NodeJS.ProcessEnv;
  getPluginConfig: () => unknown;
  getRuntimeConfig: () => OpenClawConfig | undefined;
  now?: () => number;
  managedThreads?: CodexManagedThreadStore;
}): CodexSessionCatalogControlFactory {
  const now = params.now ?? Date.now;
  const getPluginConfig = () => params.getPluginConfig();
  const homeResolver = createCodexCatalogHomeResolver({
    config: params.getRuntimeConfig() ?? params.config ?? {},
    getRuntimeConfig: params.getRuntimeConfig,
    getPluginConfig: params.getPluginConfig,
    ...(params.env ? { env: params.env } : {}),
  });
  const requestOptionsByConfig = new WeakMap<
    OpenClawConfig,
    Map<string, CodexCatalogRequestOptions>
  >();
  const catalogPagesByConfig = new WeakMap<
    OpenClawConfig,
    Map<string, CodexCatalogPageCacheEntry>
  >();
  const resolveRequestOptions = (
    startOptions: CodexAppServerStartOptions,
    agentId: string,
    source?: CodexCatalogHome,
  ): CodexCatalogRequestOptions => {
    const runtimeConfig = params.getRuntimeConfig();
    const agentDir = source?.agentDir ?? resolveAgentDir(runtimeConfig ?? {}, agentId);
    const resolvedStartOptions = source?.appServer.start ?? startOptions;
    if (!runtimeConfig) {
      return {
        agentDir,
        config: undefined,
        startOptions: structuredClone(resolvedStartOptions),
      };
    }
    let byAgent = requestOptionsByConfig.get(runtimeConfig);
    const cacheKey = `${agentId ?? ""}\0${source?.sourceHomeId ?? ""}`;
    const cached = byAgent?.get(cacheKey);
    if (cached) {
      // Plugin start options derive from this same immutable config snapshot. Config reload changes
      // object identity; re-cloning on every poll only adds CPU and allocation to the catalog path.
      return cached;
    }
    const resolved = {
      agentDir,
      config: structuredClone(runtimeConfig),
      startOptions: structuredClone(resolvedStartOptions),
    };
    if (!byAgent) {
      byAgent = new Map();
      requestOptionsByConfig.set(runtimeConfig, byAgent);
    }
    byAgent.set(cacheKey, resolved);
    return resolved;
  };
  const createRequestSnapshot = (
    agentId: string,
    source?: CodexCatalogHome,
  ): CodexSessionCatalogRequestSnapshot => {
    const pluginConfig = getPluginConfig();
    const runtime =
      source?.appServer ?? resolveCodexSupervisionAppServerRuntimeOptions({ pluginConfig });
    const requestOptions = resolveRequestOptions(runtime.start, agentId, source);
    return createCodexCatalogRequestSnapshot(
      runtime.requestTimeoutMs,
      async (method, requestParams, timeoutMs) =>
        await codexControlRequest(pluginConfig, method, requestParams, {
          ...requestOptions,
          ...(timeoutMs === undefined ? {} : { timeoutMs }),
        }),
    );
  };

  const forRequest = (agentId: string, source?: CodexCatalogHome): CodexSessionCatalogControl => {
    const withPinnedConnection: CodexSessionCatalogControl["withPinnedConnection"] = async (
      run,
    ) => {
      const pluginConfig = getPluginConfig();
      const runtime =
        source?.appServer ?? resolveCodexSupervisionAppServerRuntimeOptions({ pluginConfig });
      const {
        agentDir,
        config: runtimeConfig,
        startOptions,
      } = resolveRequestOptions(runtime.start, agentId, source);
      const client = await getLeasedSharedCodexAppServerClient({
        agentDir,
        config: runtimeConfig,
        startOptions,
        timeoutMs: runtime.requestTimeoutMs,
      });
      try {
        const requests = createCodexCatalogRequestSnapshot(
          runtime.requestTimeoutMs,
          async <M extends CodexCatalogRequestMethod>(
            method: M,
            requestParams: CodexAppServerRequestParams<M>,
            timeoutMs?: number,
          ): Promise<CodexAppServerRequestResult<M>> =>
            await requestCodexAppServerClientJson<CodexAppServerRequestResult<M>>({
              client,
              method,
              requestParams,
              config: runtimeConfig,
              timeoutMs: timeoutMs ?? runtime.requestTimeoutMs,
            }),
        );
        const pinnedControl: CodexSessionCatalogControl =
          createCodexSessionCatalogControlFromRequests({
            clientId: resolveCodexAppServerClientInstanceId(client),
            connectionFingerprint: buildCodexAppServerConnectionFingerprint(runtime, agentDir),
            createRequestSnapshot: () => requests,
            ...(source?.localSessionsRoot ? { localSessionsRoot: source.localSessionsRoot } : {}),
            sourceHomeId: source?.sourceHomeId,
            managedThreads: params.managedThreads,
            now,
            withPinnedConnection: async (nestedRun) => await nestedRun(pinnedControl),
          });
        return await run(pinnedControl);
      } finally {
        releaseLeasedSharedCodexAppServerClient(client);
      }
    };
    const control = createCodexSessionCatalogControlFromRequests({
      createRequestSnapshot: () => createRequestSnapshot(agentId, source),
      ...(source?.localSessionsRoot ? { localSessionsRoot: source.localSessionsRoot } : {}),
      now,
      withPinnedConnection,
    });
    return {
      ...control,
      requireEligibleThread: (threadId) =>
        withPinnedConnection((pinned) => pinned.requireEligibleThread(threadId)),
      async listPage(pageParams: CodexSessionCatalogPageParams) {
        const runtimeConfig = params.getRuntimeConfig();
        if (!runtimeConfig) {
          return await control.listPage(pageParams);
        }
        let cache = catalogPagesByConfig.get(runtimeConfig);
        if (!cache) {
          cache = new Map();
          catalogPagesByConfig.set(runtimeConfig, cache);
        }
        const key = codexCatalogPageCacheKey(pageParams, agentId, source);
        const cached = cache.get(key);
        if (cached) {
          cache.delete(key);
          cache.set(key, cached);
          if (cached.expiresAt > now()) {
            return cached.value ?? (await cached.page);
          }
        }
        if (cached) {
          cache.delete(key);
        }
        const page = control.listPage(pageParams);
        const staleValue = cached?.value;
        const entry: CodexCatalogPageCacheEntry = {
          expiresAt: Number.POSITIVE_INFINITY,
          page,
          ...(staleValue ? { value: staleValue } : {}),
        };
        cache.set(key, entry);
        pruneMapToMaxSize(cache, CODEX_SESSION_CATALOG_LIST_CACHE_MAX_ENTRIES);
        const settle = (value: CodexSessionCatalogPage) => {
          if (cache.get(key) === entry) {
            entry.value = value;
            entry.expiresAt = now() + CODEX_SESSION_CATALOG_LIST_TTL_MS;
          }
          return value;
        };
        const restore = () => {
          if (cache.get(key) !== entry) {
            return;
          }
          if (staleValue) {
            cache.set(key, {
              expiresAt: now(),
              page: Promise.resolve(staleValue),
              value: staleValue,
            });
          } else {
            cache.delete(key);
          }
        };
        // Expiry starts one background refresh. Passive callers keep the last settled page while
        // the next poll publishes success or retries failure.
        if (staleValue) {
          void page.then(settle, restore);
          return staleValue;
        }
        try {
          return settle(await page);
        } catch (error) {
          restore();
          throw error;
        }
      },
    };
  };
  const homesForAgent = (agentId: string) => homeResolver.forAgent(agentId);
  const forUpstream = (agentId: string, connectionFingerprint: string) => {
    // A fingerprint is correlation only. A miss must stay fail-closed instead of selecting a
    // different home whose thread namespace could contain the same copied identifier.
    const source = homesForAgent(agentId).find(
      (home) =>
        buildCodexAppServerConnectionFingerprint(home.appServer, home.agentDir) ===
        connectionFingerprint,
    );
    return source ? forRequest(agentId, source) : undefined;
  };
  return { forRequest, forUpstream, homesForAgent };
}

import type { OpenClawConfig } from "openclaw/plugin-sdk/config-contracts";
import { describe, expect, it } from "vitest";
import { resolveCodexCatalogCreateSession } from "./session-catalog-create.js";

function configWithAllowedModels(models: string[], runtime?: string): OpenClawConfig {
  return {
    agents: {
      defaults: {
        model: { primary: models[0] },
        models: Object.fromEntries(
          models.map((model) => [model, runtime ? { agentRuntime: { id: runtime } } : {}]),
        ),
      },
    },
  };
}

describe("resolveCodexCatalogCreateSession", () => {
  it("advertises the canonical implicit Codex default", () => {
    expect(resolveCodexCatalogCreateSession({}, "main")).toEqual({
      model: "openai/gpt-5.6-sol",
      agentRuntime: "codex",
    });
  });

  it("pins the Codex model even when ordinary chats use the direct runtime", () => {
    expect(
      resolveCodexCatalogCreateSession(
        configWithAllowedModels(["openai/gpt-5.6-sol"], "openclaw"),
        "main",
      ),
    ).toEqual({
      model: "openai/gpt-5.6-sol",
      agentRuntime: "codex",
    });
  });

  it("does not advertise creation when the Codex model is outside the allowlist", () => {
    expect(
      resolveCodexCatalogCreateSession(configWithAllowedModels(["openai/gpt-5.6-terra"]), "main"),
    ).toBeUndefined();
  });

  it("uses the requested agent's model allowlist", () => {
    const config = {
      agents: {
        defaults: {
          model: { primary: "openai/gpt-5.6-sol" },
          models: { "openai/gpt-5.6-sol": {} },
        },
        list: [
          { id: "main", default: true },
          {
            id: "research",
            model: { primary: "openai/gpt-5.6-terra" },
            models: { "openai/gpt-5.6-terra": {} },
            modelPolicy: { allow: ["openai/gpt-5.6-terra"] },
          },
        ],
      },
    } satisfies OpenClawConfig;

    expect(resolveCodexCatalogCreateSession(config, "main")).toEqual({
      model: "openai/gpt-5.6-sol",
      agentRuntime: "codex",
    });
    expect(resolveCodexCatalogCreateSession(config, "research")).toBeUndefined();
  });

  it("does not advertise creation before runtime config is available", () => {
    expect(resolveCodexCatalogCreateSession(undefined, "main")).toBeUndefined();
  });
});

import {
  resolveAllowedModelRef,
  resolveDefaultAgentId,
  resolveDefaultModelForAgent,
} from "openclaw/plugin-sdk/agent-runtime";
import type { OpenClawConfig } from "openclaw/plugin-sdk/config-contracts";

const CODEX_AGENT_RUNTIME_ID = "codex";
const CODEX_CATALOG_DEFAULT_MODEL_REF = "openai/gpt-5.6-sol";

export function resolveCodexCatalogCreateSession(
  config: OpenClawConfig | undefined,
  requestedAgentId?: string,
): { model: string; agentRuntime: string } | undefined {
  if (!config) {
    return undefined;
  }
  const agentId = requestedAgentId ?? resolveDefaultAgentId(config);
  const defaultModel = resolveDefaultModelForAgent({ cfg: config, agentId });
  const allowed = resolveAllowedModelRef({
    cfg: config,
    catalog: [],
    raw: CODEX_CATALOG_DEFAULT_MODEL_REF,
    defaultProvider: defaultModel.provider,
    defaultModel: defaultModel.model,
    agentId,
  });
  return "error" in allowed
    ? undefined
    : { model: CODEX_CATALOG_DEFAULT_MODEL_REF, agentRuntime: CODEX_AGENT_RUNTIME_ID };
}

import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

export function canonicalCodexCatalogHome(value: string): string {
  const resolved = path.resolve(value);
  try {
    return fs.realpathSync.native(resolved);
  } catch {
    return resolved;
  }
}

/** One canonical identity for catalog discovery and durable ownership rows. */
export function codexCatalogHomeId(codexHome: string): string {
  return createHash("sha256")
    .update("openclaw:codex-session-catalog-home:v1\0")
    .update(canonicalCodexCatalogHome(codexHome))
    .digest("hex");
}

import fs from "node:fs";
import path from "node:path";
import { listAgentIds, resolveAgentDir } from "openclaw/plugin-sdk/agent-runtime";
import type { OpenClawConfig } from "openclaw/plugin-sdk/config-contracts";
import {
  resolveCodexAppServerHomeDir,
  resolveCodexAppServerLocalHomeDir,
} from "./app-server/auth-start-options.js";
import {
  readCodexPluginConfig,
  resolveCodexAppServerUserHomeDir,
  resolveCodexSupervisionAppServerRuntimeOptions,
} from "./app-server/config.js";
import {
  buildCodexAppServerConnectionFingerprint,
  replaceCodexCatalogConnectionHomes,
} from "./app-server/plugin-app-cache-key.js";
import { canonicalCodexCatalogHome, codexCatalogHomeId } from "./session-catalog-home-id.js";
import { CODEX_LOCAL_SESSION_HOST_ID, MAX_HOST_COUNT } from "./session-catalog-parsing.js";
import type { CodexCatalogHome } from "./session-catalog-types.js";

export type { CodexCatalogHome } from "./session-catalog-types.js";

type CatalogHomeCandidate = {
  codexHome: string;
  label: string;
  usesProcessHomeFallback?: boolean;
};

function existingCatalogHomeCandidates(value: string, label?: string): CatalogHomeCandidate[] {
  const codexHome = canonicalCodexCatalogHome(value);
  try {
    if (!fs.statSync(codexHome).isDirectory()) {
      return [];
    }
  } catch {
    return [];
  }
  return [{ codexHome, label: `Local Codex · ${label ?? path.basename(codexHome)}` }];
}

/** Resolves every local Codex store the operator already owns, without path disclosure. */
function resolveCodexCatalogHomes(params: {
  config: OpenClawConfig;
  pluginConfig: unknown;
  ownerAgentId: string;
  env: NodeJS.ProcessEnv;
}): CodexCatalogHome[] {
  const { config, env, ownerAgentId, pluginConfig } = params;
  const ownerAgentDir = resolveAgentDir(config, ownerAgentId, env);
  const configuredHomes = readCodexPluginConfig(pluginConfig).sessionCatalog?.homes ?? [];
  const base = resolveCodexSupervisionAppServerRuntimeOptions({
    pluginConfig,
    env,
    agentDir: ownerAgentDir,
    config,
  });
  const primaryCodexHome = canonicalCodexCatalogHome(
    resolveCodexAppServerLocalHomeDir(base.start, ownerAgentDir, env),
  );
  const processUserHome = canonicalCodexCatalogHome(resolveCodexAppServerUserHomeDir(env));
  const processHomeConfigured = Boolean(env.CODEX_HOME?.trim());
  const primaryUsesProcessHomeFallback =
    base.start.transport === "stdio" && base.start.homeScope === "user" && !processHomeConfigured;
  const candidates: CatalogHomeCandidate[] = [
    {
      codexHome: primaryCodexHome,
      label: "Local Codex",
      usesProcessHomeFallback: primaryUsesProcessHomeFallback,
    },
  ];

  if (base.start.transport === "stdio") {
    candidates.push({
      codexHome: processUserHome,
      label: "Local Codex · user",
      usesProcessHomeFallback: !processHomeConfigured,
    });
    const agentIds = listAgentIds(config).toSorted((left, right) =>
      left === ownerAgentId ? -1 : right === ownerAgentId ? 1 : left.localeCompare(right),
    );
    candidates.push(
      ...agentIds.flatMap((agentId) =>
        existingCatalogHomeCandidates(
          resolveCodexAppServerHomeDir(resolveAgentDir(config, agentId, env)),
          agentId,
        ),
      ),
      ...configuredHomes.flatMap((entry) => {
        const { path: home, label } = typeof entry === "string" ? { path: entry } : entry;
        return existingCatalogHomeCandidates(home, label);
      }),
    );
  }

  const seen = new Set<string>();
  const homes: CodexCatalogHome[] = [];
  for (const candidate of candidates) {
    if (seen.has(candidate.codexHome)) {
      continue;
    }
    seen.add(candidate.codexHome);
    const sourceHomeId = codexCatalogHomeId(candidate.codexHome);
    const primary = homes.length === 0;
    homes.push({
      sourceHomeId,
      hostId: primary
        ? CODEX_LOCAL_SESSION_HOST_ID
        : `${CODEX_LOCAL_SESSION_HOST_ID}:${sourceHomeId}`,
      label: candidate.label,
      agentDir: ownerAgentDir,
      appServer: primary
        ? base
        : {
            ...base,
            start: {
              ...base.start,
              homeScope: "user",
              env: { ...base.start.env, CODEX_HOME: candidate.codexHome },
            },
          },
      ...(base.connectionClass === "remote"
        ? {}
        : { localSessionsRoot: path.join(candidate.codexHome, "sessions") }),
      usesProcessHomeFallback: candidate.usesProcessHomeFallback ?? false,
    });
    if (homes.length >= MAX_HOST_COUNT) {
      break;
    }
  }
  return homes;
}

type CodexCatalogHomeResolver = {
  forAgent(agentId: string): readonly CodexCatalogHome[];
};

/** Discovers Codex homes once per immutable Gateway config generation. */
export function createCodexCatalogHomeResolver(params: {
  config: OpenClawConfig;
  getRuntimeConfig: () => OpenClawConfig | undefined;
  getPluginConfig: () => unknown;
  env?: NodeJS.ProcessEnv;
}): CodexCatalogHomeResolver {
  const env = params.env ?? process.env;
  const homesByConfig = new WeakMap<OpenClawConfig, Map<string, readonly CodexCatalogHome[]>>();
  const buildSnapshot = (config: OpenClawConfig) => {
    const pluginConfig = params.getPluginConfig();
    const homesByAgent = new Map(
      listAgentIds(config).map((agentId) => [
        agentId,
        resolveCodexCatalogHomes({
          config,
          pluginConfig,
          ownerAgentId: agentId,
          env,
        }),
      ]),
    );
    replaceCodexCatalogConnectionHomes(
      [...homesByAgent.values()].flatMap((homes) =>
        homes
          .filter((home) => home.appServer.start.transport === "stdio")
          .map((home) => ({
            agentDir: home.agentDir,
            fingerprint: buildCodexAppServerConnectionFingerprint(home.appServer, home.agentDir),
            codexHome: resolveCodexAppServerLocalHomeDir(home.appServer.start, home.agentDir, env),
          })),
      ),
    );
    homesByConfig.set(config, homesByAgent);
    return homesByAgent;
  };
  let lastSnapshot = buildSnapshot(params.config);
  return {
    forAgent(agentId) {
      // agents.entries hot-reloads without plugin re-registration. Config identity therefore owns
      // both filesystem discovery and the supervised-binding connection-home snapshot.
      const config = params.getRuntimeConfig();
      if (!config) {
        return lastSnapshot.get(agentId) ?? [];
      }
      const cached = homesByConfig.get(config);
      if (cached) {
        return cached.get(agentId) ?? [];
      }
      lastSnapshot = buildSnapshot(config);
      return lastSnapshot.get(agentId) ?? [];
    },
  };
}

// Codex supervision tests cover passive listing and safe local session takeover.
import { describe, expect, it, vi } from "vitest";
import {
  commandRpcMocks,
  createCodexSessionCatalogControl,
  config,
  idleThread,
  resolveDefaultAgentDir,
  type OpenClawConfig,
} from "./session-catalog.test-helpers.js";

describe("Codex supervision catalog", () => {
  it("memoizes cloned request options until runtime config identity changes", async () => {
    let runtimeConfig = { agents: { defaults: { workspace: "/workspace/a" } } } as OpenClawConfig;
    commandRpcMocks.codexControlRequest.mockResolvedValue({ thread: idleThread() });
    const control = createCodexSessionCatalogControl({
      getPluginConfig: () => ({ supervision: { enabled: true } }),
      getRuntimeConfig: () => runtimeConfig,
    });
    const cloneSpy = vi.spyOn(globalThis, "structuredClone");

    await control.readThread("thread-1");
    await control.readThread("thread-1");
    expect(cloneSpy).toHaveBeenCalledTimes(2);

    runtimeConfig = { agents: { defaults: { workspace: "/workspace/b" } } } as OpenClawConfig;
    await control.readThread("thread-1");
    expect(cloneSpy).toHaveBeenCalledTimes(4);
  });

  it("serves an expired page while one background refresh updates the next poll", async () => {
    let now = 1_000;
    let runtimeConfig = {} as OpenClawConfig;
    commandRpcMocks.codexControlRequest.mockResolvedValue({
      data: [idleThread({ id: "thread-stale", source: "cli" })],
    });
    const control = createCodexSessionCatalogControl({
      getPluginConfig: () => ({ supervision: { enabled: true } }),
      getRuntimeConfig: () => runtimeConfig,
      now: () => now,
    });

    await control.listPage({ limit: 25 });
    await control.listPage({ limit: 25 });
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledOnce();

    now += 31_999;
    await control.listPage({ limit: 25 });
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledOnce();

    now += 2;
    let resolveRefresh!: (value: unknown) => void;
    let refreshSettled = false;
    const refresh = new Promise<unknown>((resolve) => {
      resolveRefresh = resolve;
    }).then((value) => {
      refreshSettled = true;
      return value;
    });
    commandRpcMocks.codexControlRequest.mockReturnValueOnce(refresh);
    const firstExpiredPoll = control.listPage({ limit: 25 });
    const overlappingExpiredPoll = control.listPage({ limit: 25 });

    await expect(Promise.all([firstExpiredPoll, overlappingExpiredPoll])).resolves.toEqual([
      expect.objectContaining({
        sessions: [expect.objectContaining({ threadId: "thread-stale" })],
      }),
      expect.objectContaining({
        sessions: [expect.objectContaining({ threadId: "thread-stale" })],
      }),
    ]);
    expect(refreshSettled).toBe(false);
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledTimes(2);

    resolveRefresh({ data: [idleThread({ id: "thread-refreshed", source: "cli" })] });
    await vi.waitFor(async () => {
      await expect(control.listPage({ limit: 25 })).resolves.toMatchObject({
        sessions: [expect.objectContaining({ threadId: "thread-refreshed" })],
      });
    });
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledTimes(2);

    runtimeConfig = { agents: {} } as OpenClawConfig;
    await control.listPage({ limit: 25 });
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledTimes(3);
  });

  it("serves the last real page after a refresh failure and retries the next poll", async () => {
    let now = 1_000;
    commandRpcMocks.codexControlRequest.mockResolvedValue({
      data: [idleThread({ id: "thread-stale", source: "cli" })],
    });
    const control = createCodexSessionCatalogControl({
      getPluginConfig: () => ({ supervision: { enabled: true } }),
      getRuntimeConfig: () => config,
      now: () => now,
    });
    const first = await control.listPage({ limit: 25 });

    now += 32_001;
    commandRpcMocks.codexControlRequest.mockRejectedValueOnce(new Error("app-server unavailable"));
    await expect(control.listPage({ limit: 25 })).resolves.toEqual(first);
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledTimes(2);

    commandRpcMocks.codexControlRequest.mockResolvedValue({
      data: [idleThread({ id: "thread-recovered", source: "cli" })],
    });
    await expect(control.listPage({ limit: 25 })).resolves.toEqual(first);
    await vi.waitFor(async () => {
      await expect(control.listPage({ limit: 25 })).resolves.toMatchObject({
        sessions: [expect.objectContaining({ threadId: "thread-recovered" })],
      });
    });
    expect(commandRpcMocks.codexControlRequest).toHaveBeenCalledTimes(3);
  });

  it("evicts a cold failed page so the next caller retries immediately", async () => {
    commandRpcMocks.codexControlRequest.mockRejectedValueOnce(new Error("cold failure"));
    const control = createCodexSessionCatalogControl({
      getPluginConfig: () => ({ supervision: { enabled: true } }),
      getRuntimeConfig: () => config,
    });

    await expect(control.listPage({ limit: 25 })).rejects.toThrow("cold failure");
    commandRpcMocks.codexControlRequest.mockResolvedValue({
      data: [idleThread({ id: "thread-recovered", source: "cli" })],
    });
    await expect(control.listPage({ limit: 25 })).resolves.toMatchObject({
