    const { runtime } = createRuntime();
    const { api, getProvider } = createGatewayApi(runtime, runtimeConfig);
    const listPage = vi.fn(async (source?: { agentDir: string; sourceHomeId: string }) => ({
      sessions: [
        {
          threadId: `thread-${source?.sourceHomeId ?? "missing"}`,
          status: "idle",
          source: "cli",
